import { hex, scale, type RGB } from '../../world/biomes';
import type { InstitutionKind } from '../../world/tiles';
import { Vis, type Sched } from '../nightLights';
import { COOL_GLOW, DARK, GLASS, METAL, RED_LIGHT, SHOP_GLOW, TAU, WARM_GLOW, WHITE, WOOD, pennant, type Draw, type Kit, type P3 } from './kit';

/**
 * Institutions that make work for a haulage fleet: a film studio lot, an army base, an old star fort
 * on the border, a cable-car valley station, a research dome and a festival field that wakes in summer.
 */

const EVENING: Sched = [18, 23.5, 1.4];
const LATE: Sched = [17, 26, 2.2];
const ALL_NIGHT: Sched = [0, 36, 3];
const BRIGHTS = [0xe2412f, 0x2f7fb5, 0xf2a93b, 0x3f9b4a, 0x8e5cc7, 0x2bb3a3, 0xf26fa0].map((c) => hex(c));
const ASPHALT = hex(0x5d6066), CONCRETE = hex(0xbfc0bb);

/** A red obstruction light that burns all night. */
function beacon(k: Kit, x: number, y: number, z: number): void {
  k.glowBox(x, y, z, 0.05, 0.05, 0.05, hex(0xc23a30), ALL_NIGHT, RED_LIGHT);
}

/** An arched roof over a w×d base, its ridge along z, with both ends closed. */
function barrel(k: Kit, x: number, y: number, z: number, w: number, rise: number, d: number, col: RGB, end: RGB, n = 6): void {
  const z0 = z - d / 2, z1 = z + d / 2, I: P3 = [x, y - 0.05, z];
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
    const p0: [number, number] = [x - (Math.cos(a0) * w) / 2, y + Math.sin(a0) * rise];
    const p1: [number, number] = [x - (Math.cos(a1) * w) / 2, y + Math.sin(a1) * rise];
    k.quad([p0[0], p0[1], z0], [p1[0], p1[1], z0], [p1[0], p1[1], z1], [p0[0], p0[1], z1], i % 2 ? col : scale(col, 0.95), I);
    k.tri([x, y, z0], [p0[0], p0[1], z0], [p1[0], p1[1], z0], end, I);
    k.tri([x, y, z1], [p0[0], p0[1], z1], [p1[0], p1[1], z1], end, I);
  }
}

/** A straight run of fence between two points on an axis: posts, and either mesh or two rails. */
function fence(k: Kit, x0: number, z0: number, x1: number, z1: number, h: number, post: RGB, fill: RGB, rails: boolean): void {
  const len = Math.hypot(x1 - x0, z1 - z0), n = Math.max(1, Math.round(len / 0.55));
  const alongX = Math.abs(x1 - x0) > Math.abs(z1 - z0);
  const mx = (x0 + x1) / 2, mz = (z0 + z1) / 2;
  for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, 0.02, z0 + ((z1 - z0) * i) / n, 0.04, h + 0.03, 0.04, post);
  if (rails) {
    for (const f of [0.4, 0.8]) k.box(mx, 0.02 + h * f, mz, alongX ? len : 0.02, 0.03, alongX ? 0.02 : len, fill);
  } else {
    k.box(mx, 0.04, mz, alongX ? len : 0.012, h - 0.04, alongX ? 0.012 : len, fill);
  }
}

// ---- film studio (6 × 5) ------------------------------------------------------------------------------

const CREAM = hex(0xefe6cf), STAGE_ROOF = hex(0x9a9d9f), PLY = hex(0xb08a5a);

/**
 * A studio lot: three windowless sound stages under arched roofs, the arched gate on the road, a water
 * tower with the studio's band round it, and a backlot street of false fronts propped up from behind.
 */
const filmStudio: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, ASPHALT);
  // the sound stages along the back, each with its elephant door, its number panel and a lamp over the door
  for (let i = 0; i < 3; i++) {
    const sx = -hw + 0.95 + i * 1.65, sz = -hd + 1.1, sw = 1.5, sd = 1.8, sh = i === 1 ? 0.95 : 0.85;
    k.box(sx, 0.02, sz, sw, sh, sd, CREAM);
    k.box(sx, 0.02, sz, sw + 0.04, 0.1, sd + 0.04, scale(CREAM, 0.78));
    barrel(k, sx, sh + 0.02, sz, sw + 0.06, 0.22, sd + 0.06, STAGE_ROOF, CREAM);
    const fz = sz + sd / 2;
    k.box(sx - 0.32, 0.02, fz + 0.012, 0.5, 0.52, 0.024, scale(CREAM, 0.6));
    k.box(sx + 0.38, 0.4, fz + 0.012, 0.42, 0.4, 0.024, BRIGHTS[i]);
    for (let j = 0; j <= i; j++) k.box(sx + 0.38 + (j - i / 2) * 0.1, 0.47, fz + 0.03, 0.05, 0.26, 0.012, WHITE);
    k.glowBox(sx - 0.32, 0.6, fz + 0.03, 0.12, 0.04, 0.04, hex(0xf2e6b0), LATE, WARM_GLOW);
  }
  // the water tower in the back corner
  const tx = hw - 0.5, tz = -hd + 0.8;
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) {
    k.bar([tx + sx * 0.26, 0.02, tz + sz * 0.26], [tx + sx * 0.18, 1.2, tz + sz * 0.18], 0.022, METAL);
  }
  k.hoop(tx, 0.6, tz, 0.3, 0.012, METAL, 4, 'xz');
  k.cyl(tx, 1.2, tz, 0.3, 0.42, WHITE, 10);
  k.cyl(tx, 1.32, tz, 0.312, 0.16, BRIGHTS[0], 10);
  k.cone(tx, 1.62, tz, 0.34, 0.16, STAGE_ROOF, 10);
  // the front wall and the arched gate in the middle of it
  const gz = hd - 0.3;
  for (const sx of [-1, 1]) {
    k.box(sx * (hw / 2 + 0.33), 0.02, gz, hw - 0.86, 0.3, 0.1, CREAM, scale(CREAM, 0.8));
    k.box(sx * 0.62, 0.02, gz, 0.26, 0.62, 0.26, CREAM);
    k.box(sx * 0.62, 0.64, gz, 0.32, 0.05, 0.32, scale(CREAM, 0.8));
  }
  const ring = (a: number, rr: number, z: number): P3 => [Math.cos(a) * rr, 0.66 + Math.sin(a) * rr * 0.9, z];
  for (let i = 0; i < 8; i++) {
    const a0 = (i / 8) * Math.PI, a1 = ((i + 1) / 8) * Math.PI, am = (a0 + a1) / 2, I = ring(am, 0.62, gz);
    const z0 = gz - 0.11, z1 = gz + 0.11, col = i % 2 ? CREAM : scale(CREAM, 0.92);
    k.quad(ring(a0, 0.75, z0), ring(a1, 0.75, z0), ring(a1, 0.75, z1), ring(a0, 0.75, z1), col, I);
    k.quad(ring(a0, 0.49, z0), ring(a1, 0.49, z0), ring(a1, 0.49, z1), ring(a0, 0.49, z1), scale(CREAM, 0.75), I);
    for (const z of [z0, z1]) k.quad(ring(a0, 0.49, z), ring(a1, 0.49, z), ring(a1, 0.75, z), ring(a0, 0.75, z), col, I);
  }
  k.box(0, 1.3, gz, 0.8, 0.22, 0.1, DARK);
  k.glowBox(0, 1.34, gz + 0.055, 0.7, 0.14, 0.012, hex(0xf2c14e), LATE, SHOP_GLOW);
  // the gatekeeper's booth
  k.box(1.05, 0.02, gz - 0.3, 0.3, 0.32, 0.3, WHITE, BRIGHTS[0]);
  k.pane(1.05 - 0.15, 0.14, gz - 0.3, 0.2, 0.12, 2, GLASS, EVENING, WARM_GLOW);
  // the backlot: a street of false fronts facing the road, bare ply and struts behind
  const fronts = [hex(0xc96a4a), hex(0xe8d3b0), hex(0x7fa6b8), hex(0xd9b44a)];
  for (let i = 0; i < 4; i++) {
    const fx = 1.08 + i * 0.47, fz = 0.55, fw = 0.44, fh = 0.58 + r() * 0.3;
    k.box(fx, 0.02, fz, fw, fh, 0.04, fronts[i]);
    k.box(fx, 0.02, fz - 0.03, fw, fh, 0.02, PLY);
    k.box(fx, fh + 0.02, fz + 0.01, fw + 0.03, 0.05, 0.06, WHITE);
    k.box(fx - 0.1, 0.02, fz + 0.025, 0.11, 0.22, 0.012, DARK);
    k.box(fx + 0.1, 0.12, fz + 0.025, 0.12, 0.12, 0.012, GLASS);
    for (const wx of [-0.1, 0.1]) k.box(fx + wx, 0.36, fz + 0.025, 0.1, 0.13, 0.012, GLASS);
    for (const sx of [-0.14, 0.14]) k.bar([fx + sx, fh * 0.85, fz - 0.04], [fx + sx, 0.03, fz - 0.42], 0.015, WOOD);
  }
  k.box(1.78, 0.02, 0.76, 1.9, 0.025, 0.3, WOOD);
  // trailers parked in a row
  for (let i = 0; i < 3; i++) {
    const x = -hw + 0.55 + i * 0.62, z = 1.0;
    k.box(x, 0.02, z, 0.34, 0.05, 0.2, DARK);
    k.box(x, 0.07, z, 0.5, 0.2, 0.24, WHITE, METAL);
    k.box(x, 0.13, z + 0.122, 0.5, 0.04, 0.004, BRIGHTS[(i + 1) % 3]);
    k.pane(x - 0.12, 0.15, z + 0.12, 0.1, 0.07, 1, GLASS, EVENING, WARM_GLOW);
  }
  // a camera crane working the backlot street
  const cx = 0.72, cz = 1.45;
  k.box(cx, 0.02, cz, 0.24, 0.1, 0.32, DARK);
  k.box(cx, 0.12, cz, 0.08, 0.2, 0.08, METAL);
  k.bar([cx - 0.18, 0.2, cz + 0.16], [cx + 0.42, 0.78, cz - 0.38], 0.022, hex(0xf2c14e));
  k.box(cx - 0.18, 0.12, cz + 0.16, 0.1, 0.1, 0.1, DARK);
  k.box(cx + 0.42, 0.7, cz - 0.38, 0.12, 0.1, 0.12, DARK);
  // the searchlight by the gate, lit for a premiere every night
  const lx = -1.2, lz = gz - 0.45;
  k.cyl(lx, 0.02, lz, 0.11, 0.1, DARK, 8);
  k.bar([lx, 0.14, lz], [lx + 0.08, 0.34, lz - 0.06], 0.085, METAL);
  k.glowBox(lx + 0.09, 0.36, lz - 0.07, 0.15, 0.06, 0.15, hex(0xe8f0f4), [18, 30, 3.4], COOL_GLOW);
};

// ---- army base (8 × 6) --------------------------------------------------------------------------------

const OLIVE = hex(0x5d6b3f), OLIVE_DARK = hex(0x46532f), TAN = hex(0xc4b088), CANVAS = hex(0x7a7f56), MESH = hex(0x9aa39e);
const SHELTER = hex(0x7d8672), SANDBAG = hex(0xb8a27a);

/** An army truck facing the road: cab and a canvas-covered bed. */
function truck(k: Kit, x: number, z: number): void {
  k.box(x, 0.02, z, 0.17, 0.05, 0.46, DARK);
  k.box(x, 0.07, z + 0.16, 0.2, 0.15, 0.14, OLIVE, OLIVE_DARK);
  k.box(x, 0.07, z - 0.08, 0.2, 0.19, 0.3, OLIVE_DARK, CANVAS);
}

/** A tank: tracks, hull, turret and a barrel. */
function tank(k: Kit, x: number, z: number): void {
  for (const sx of [-1, 1]) k.box(x + sx * 0.13, 0.02, z, 0.08, 0.09, 0.52, DARK);
  k.box(x, 0.06, z, 0.2, 0.11, 0.48, OLIVE);
  k.cyl(x, 0.17, z - 0.04, 0.1, 0.08, OLIVE_DARK, 8, OLIVE);
  k.bar([x, 0.22, z + 0.04], [x, 0.24, z + 0.4], 0.018, OLIVE_DARK);
}

/** A watchtower on four legs with a red light on its roof. */
function watchtower(k: Kit, x: number, z: number): void {
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) {
    k.bar([x + sx * 0.17, 0.02, z + sz * 0.17], [x + sx * 0.13, 0.66, z + sz * 0.13], 0.02, OLIVE_DARK);
  }
  k.box(x, 0.66, z, 0.42, 0.04, 0.42, WOOD);
  k.box(x, 0.7, z, 0.32, 0.26, 0.32, OLIVE);
  k.box(x, 0.8, z, 0.34, 0.09, 0.34, DARK);
  k.hip(x, 0.96, z, 0.46, 0.14, 0.46, OLIVE_DARK);
  beacon(k, x, 1.08, z);
}

/**
 * An army base behind chain-link: watchtowers at the corners, a boom gate and sandbag post, rows of
 * barrack huts, a parade square, the motor pool, a hardened shelter, a turning radar and a helipad.
 */
const militaryBase: Draw = (k, W, D) => {
  const hw = W / 2, hd = D / 2, fx = hw - 0.15, fz = hd - 0.15;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, TAN);
  // the wire, open at the gate
  fence(k, -fx, -fz, fx, -fz, 0.3, METAL, MESH, false);
  for (const sx of [-1, 1]) {
    fence(k, sx * fx, -fz, sx * fx, fz, 0.3, METAL, MESH, false);
    fence(k, sx * 0.6, fz, sx * fx, fz, 0.3, METAL, MESH, false);
    for (const sz of [-1, 1]) watchtower(k, sx * (hw - 0.45), sz * (hd - 0.45));
  }
  // the road in from the gate, the boom, the guard hut and the sandbag post
  k.box(0, 0.02, 1.15, 0.9, 0.012, 3.4, ASPHALT);
  k.box(0.6, 0.02, fz, 0.08, 0.24, 0.08, WHITE);
  for (let i = 0; i < 5; i++) k.box(0.42 - i * 0.2, 0.19, fz, 0.2, 0.04, 0.04, i % 2 ? WHITE : hex(0xd23a2e));
  k.box(0.95, 0.02, fz - 0.4, 0.32, 0.34, 0.32, OLIVE);
  k.hip(0.95, 0.36, fz - 0.4, 0.4, 0.12, 0.4, OLIVE_DARK);
  k.pane(0.95 - 0.16, 0.16, fz - 0.4, 0.2, 0.12, 2, GLASS, ALL_NIGHT, WARM_GLOW);
  k.pane(0.95, 0.16, fz - 0.24, 0.2, 0.12, 1, GLASS, ALL_NIGHT, WARM_GLOW);
  const bx = -0.95, bz = fz - 0.4;
  k.box(bx, 0.02, bz + 0.2, 0.5, 0.16, 0.1, SANDBAG);
  for (const sx of [-1, 1]) k.box(bx + sx * 0.2, 0.02, bz, 0.1, 0.16, 0.34, SANDBAG);
  k.box(bx, 0.18, bz + 0.2, 0.4, 0.07, 0.09, scale(SANDBAG, 0.9));
  k.box(bx, 0.02, bz - 0.02, 0.24, 0.04, 0.24, OLIVE_DARK);
  // barrack huts in two ranks of three
  for (let i = 0; i < 6; i++) {
    const x = -2.65 + (i % 2) * 1.4, z = -2.15 + Math.floor(i / 2) * 0.75;
    k.box(x, 0.02, z, 1.2, 0.26, 0.46, OLIVE);
    k.gable(x, 0.28, z, 1.26, 0.16, 0.52, OLIVE_DARK, OLIVE);
    k.box(x + 0.61, 0.02, z, 0.02, 0.2, 0.12, OLIVE_DARK);
    for (let j = 0; j < 4; j++) k.pane(x - 0.42 + j * 0.28, 0.12, z + 0.23, 0.12, 0.09, 1, GLASS, EVENING, WARM_GLOW);
  }
  // the parade square and its flag
  const px = 1.3, pz = 0.25;
  k.box(px, 0.02, pz, 1.7, 0.012, 1.5, CONCRETE);
  for (const sz of [-1, 1]) k.box(px, 0.032, pz + sz * 0.68, 1.56, 0.006, 0.04, WHITE);
  for (const sx of [-1, 1]) k.box(px + sx * 0.76, 0.032, pz, 0.04, 0.006, 1.32, WHITE);
  k.box(px, 0.02, pz - 0.9, 0.16, 0.05, 0.16, CONCRETE);
  k.box(px, 0.07, pz - 0.9, 0.025, 1.3, 0.025, WHITE);
  k.box(px + 0.15, 1.17, pz - 0.9, 0.28, 0.18, 0.012, hex(0xd23a2e));
  k.box(px + 0.15, 1.23, pz - 0.9, 0.285, 0.06, 0.016, hex(0xf2c14e));
  // the motor pool: trucks in a rank, two tanks and an armoured car
  k.box(-2.25, 0.02, 1.4, 2.7, 0.012, 1.9, ASPHALT);
  for (let i = 0; i < 4; i++) truck(k, -3.3 + i * 0.36, 0.95);
  for (let i = 0; i < 2; i++) truck(k, -3.3 + i * 0.36, 1.85);
  tank(k, -1.7, 0.95);
  tank(k, -1.22, 0.95);
  k.box(-1.5, 0.02, 1.85, 0.18, 0.05, 0.36, DARK);
  k.box(-1.5, 0.06, 1.85, 0.22, 0.12, 0.4, OLIVE);
  k.box(-1.5, 0.18, 1.8, 0.14, 0.07, 0.16, OLIVE_DARK);
  k.bar([-1.5, 0.22, 1.85], [-1.5, 0.23, 2.08], 0.012, OLIVE_DARK);
  // the hardened shelter: a concrete arch with blast doors
  const sx0 = 2.55, sz0 = -1.75;
  barrel(k, sx0, 0.02, sz0, 1.8, 0.78, 1.7, SHELTER, scale(SHELTER, 0.85), 8);
  k.box(sx0, 0.02, sz0 + 0.86, 1.0, 0.46, 0.02, DARK);
  k.box(sx0, 0.02, sz0 + 0.875, 0.03, 0.46, 0.01, hex(0xf2c14e));
  k.box(sx0, 0.02, sz0 + 1.2, 1.1, 0.012, 0.7, CONCRETE);
  beacon(k, sx0, 0.8, sz0);
  // the radar on its hut, turning
  const rx = 0.4, rz = -2.05;
  k.box(rx, 0.02, rz, 0.5, 0.3, 0.5, OLIVE, OLIVE_DARK);
  k.pane(rx, 0.12, rz + 0.25, 0.22, 0.1, 1, GLASS, ALL_NIGHT, COOL_GLOW);
  k.cyl(rx, 0.32, rz, 0.05, 0.5, METAL, 6);
  k.spin(rx, 0.82, rz, 'y', 1.1, (s) => {
    s.box(0, 0, 0, 0.62, 0.26, 0.03, METAL, OLIVE_DARK);
    s.box(0, 0.02, 0.02, 0.5, 0.2, 0.02, OLIVE_DARK);
    s.bar([0, 0.02, 0], [0, 0.12, 0.2], 0.012, DARK);
  });
  beacon(k, rx + 0.2, 0.32, rz - 0.2);
  // a command hut behind the square
  k.box(1.1, 0.02, -1.6, 0.9, 0.34, 0.5, TAN, OLIVE_DARK);
  for (let j = 0; j < 3; j++) k.pane(0.84 + j * 0.26, 0.14, -1.35, 0.14, 0.12, 1, GLASS, LATE, WARM_GLOW);
  // the helipad
  const hx = 2.6, hz = 1.8;
  k.disc(hx, 0.02, hz, 0.75, hex(0x6d7074), 16);
  k.hoop(hx, 0.03, hz, 0.62, 0.018, WHITE, 16, 'xz');
  for (const s of [-1, 1]) k.box(hx + s * 0.16, 0.026, hz, 0.08, 0.012, 0.5, WHITE);
  k.box(hx, 0.026, hz, 0.24, 0.012, 0.08, WHITE);
  for (const [ax, az] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) beacon(k, hx + ax * 0.56, 0.03, hz + az * 0.56);
};

// ---- border fort (4 × 4) ------------------------------------------------------------------------------

const RAMPART = hex(0xb4ab97), RAMPART_TOP = hex(0x8fa860), PARAPET = hex(0xcdc5b2), YARD = hex(0xd3c5a0);
const IRON = hex(0x26282b), FORT_ROOF = hex(0x8a4a3a);

/**
 * An old star fort: a thick battered rampart with an arrowhead bastion at each corner, a gate tunnel and
 * drawbridge on the road side, barracks, a powder magazine and a tall flagstaff in the yard, cannon on top.
 */
const borderFort: Draw = (k) => {
  type P2 = [number, number];
  const c = 1.25, ci = 0.8, s = 0.5, H = 0.7, BAT = 0.88;
  // one wall section between two outer base points and the inner points behind them: battered face, walk, inner face
  const seg = (o0: P2, o1: P2, i0: P2, i1: P2, yb = 0) => {
    const f = yb / H, up = (o: P2): P2 => [o[0] * (1 - (1 - BAT) * f), o[1] * (1 - (1 - BAT) * f)];
    const t0: P2 = [o0[0] * BAT, o0[1] * BAT], t1: P2 = [o1[0] * BAT, o1[1] * BAT], b0 = up(o0), b1 = up(o1);
    const I: P3 = [(o0[0] + o1[0] + i0[0] + i1[0]) / 4, (yb + H) / 2 - 0.05, (o0[1] + o1[1] + i0[1] + i1[1]) / 4];
    k.quad([b0[0], yb, b0[1]], [b1[0], yb, b1[1]], [t1[0], H, t1[1]], [t0[0], H, t0[1]], RAMPART, I);
    k.quad([t0[0], H, t0[1]], [t1[0], H, t1[1]], [i1[0], H, i1[1]], [i0[0], H, i0[1]], RAMPART_TOP, I);
    k.quad([i0[0], yb, i0[1]], [i1[0], yb, i1[1]], [i1[0], H, i1[1]], [i0[0], H, i0[1]], scale(RAMPART, 0.9), I);
    // the parapet along the outer edge
    k.bar([t0[0], H + 0.04, t0[1]], [t1[0], H + 0.04, t1[1]], 0.045, PARAPET);
  };
  // the trace: five points a corner (curtain end, shoulder, tip, shoulder, curtain end), turned round four times
  const outer: P2[] = [], inner: P2[] = [];
  const corner: [P2, P2][] = [
    [[c, c - s], [ci, c - s]], [[c + 0.3, c - s], [ci, ci]], [[c + 0.6, c + 0.6], [ci, ci]],
    [[c - s, c + 0.3], [ci, ci]], [[c - s, c], [c - s, ci]],
  ];
  for (let q = 0; q < 4; q++) {
    for (const [o, i] of corner) {
      let po = o, pi = i;
      for (let t = 0; t < q; t++) { po = [-po[1], po[0]]; pi = [-pi[1], pi[0]]; }
      outer.push(po); inner.push(pi);
    }
  }
  const N = outer.length;
  for (let j = 0; j < N; j++) {
    if (j === 4) continue; // the front curtain, drawn below round the gate
    seg(outer[j], outer[(j + 1) % N], inner[j], inner[(j + 1) % N]);
  }
  // the front curtain with the gate tunnel through it
  const g = 0.22, gh = 0.44, e = c - s;
  seg([e, c], [g, c], [e, ci], [g, ci]);
  seg([-g, c], [-e, c], [-g, ci], [-e, ci]);
  seg([g, c], [-g, c], [g, ci], [-g, ci], gh);
  for (const sx of [-1, 1]) {
    k.quad([sx * g, 0, c], [sx * g, gh, c - 0.09], [sx * g, gh, ci], [sx * g, 0, ci], scale(RAMPART, 0.6), [sx * (g + 0.3), 0.2, 1]);
    k.box(sx * (g + 0.09), 0, c + 0.02, 0.12, 0.62, 0.12, PARAPET);
  }
  k.quad([-g, gh, c - 0.09], [g, gh, c - 0.09], [g, gh, ci], [-g, gh, ci], scale(RAMPART, 0.5), [0, gh + 0.2, 1]);
  k.box(0, 0.6, c - 0.04, 0.74, 0.1, 0.14, PARAPET);
  k.box(0, 0, (c + ci) / 2, g * 2, 0.025, c - ci, scale(YARD, 0.7));
  k.glowBox(0, 0.5, c - 0.02, 0.06, 0.07, 0.06, hex(0xf2c14e), LATE, WARM_GLOW);
  // the ditch and the drawbridge over it, on its chains
  k.box(0, 0, c + 0.33, 1.5, 0.014, 0.4, hex(0x5f95b3));
  k.box(0, 0.025, c + 0.3, 0.4, 0.03, 0.62, WOOD);
  for (const sx of [-1, 1]) k.bar([sx * 0.18, 0.06, c + 0.56], [sx * 0.2, 0.66, c - 0.04], 0.01, IRON);
  // the yard: barracks along the back, the magazine, the flagstaff and a sentry box by the gate
  k.box(0, 0, 0, ci * 2, 0.02, ci * 2, YARD);
  k.box(0, 0.02, -0.42, 1.1, 0.3, 0.36, WHITE);
  k.gable(0, 0.32, -0.42, 1.16, 0.18, 0.42, FORT_ROOF, WHITE);
  k.box(0, 0.02, -0.235, 0.12, 0.2, 0.012, WOOD);
  for (const wx of [-0.38, -0.2, 0.2, 0.38]) k.pane(wx, 0.13, -0.24, 0.09, 0.1, 1, GLASS, EVENING, WARM_GLOW);
  k.box(-0.48, 0.02, 0.3, 0.3, 0.2, 0.3, RAMPART);
  k.hip(-0.48, 0.22, 0.3, 0.36, 0.16, 0.36, scale(RAMPART, 0.7));
  k.box(-0.48, 0.02, 0.455, 0.09, 0.13, 0.012, IRON);
  k.box(0.3, 0.02, 0.2, 0.12, 0.05, 0.12, RAMPART);
  k.box(0.3, 0.07, 0.2, 0.028, 1.75, 0.028, WHITE);
  k.box(0.47, 1.6, 0.2, 0.32, 0.2, 0.012, hex(0x2f5fa5));
  k.box(0.47, 1.67, 0.2, 0.325, 0.06, 0.016, WHITE);
  k.box(0.52, 0.02, 0.62, 0.13, 0.26, 0.13, hex(0xd23a2e), WHITE);
  k.hip(0.52, 0.28, 0.62, 0.17, 0.1, 0.17, IRON);
  k.box(0.52, 0.02, 0.555, 0.07, 0.18, 0.006, IRON);
  // a cannon on each bastion, pointing out over its tip
  for (let q = 0; q < 4; q++) {
    k.turned((q * Math.PI) / 2, () => {
      const x = 1.22, z = 1.22, d = Math.SQRT1_2;
      k.box(x, H, z, 0.13, 0.07, 0.13, WOOD);
      k.bar([x - d * 0.08, H + 0.1, z - d * 0.08], [x + d * 0.26, H + 0.14, z + d * 0.26], 0.03, IRON);
      for (let i = 0; i < 3; i++) k.box(x - 0.16 + (i % 2) * 0.05, H, z - 0.02 + i * 0.05 - (i === 2 ? 0.08 : 0), 0.04, 0.04, 0.04, IRON);
    });
  }
};

// ---- cable-car valley station (2 × 2) -----------------------------------------------------------------

const STATION = hex(0xe9ecee), STATION_ROOF = hex(0x4a5560), GONDOLA = hex(0xd8352b), STEEL = hex(0x8f979e);

/**
 * The valley station of a cable car: a station with its mouth open to the mountain, a steel pylon with
 * sheaves at its head, two cables climbing off the back of the lot and a red cabin just leaving.
 */
const cableCarStation: Draw = (k, W, D) => {
  const sx = -0.15, z0 = 0.15, z1 = 0.82, mz = (z0 + z1) / 2, sd = z1 - z0, sh = 0.62;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, CONCRETE);
  // the station: side walls, a glazed front, a dark hall open at the back, and a roof lifting toward the mountain
  for (const s of [-1, 1]) k.box(sx + s * 0.5, 0.02, mz, 0.1, sh, sd, STATION);
  k.box(sx, 0.02, z1 - 0.04, 0.9, sh, 0.08, STATION);
  k.box(sx, 0.02, mz + 0.04, 0.9, sh - 0.06, sd - 0.2, hex(0x23272c));
  k.box(sx, 0.02, z0 + 0.03, 0.9, 0.1, 0.06, hex(0xf2c14e));
  k.turned(Math.PI, () => k.wedge(-sx, sh + 0.02, -mz, 1.3, 0.26, sd + 0.16, STATION_ROOF));
  k.box(sx, sh + 0.02, mz, 1.3, 0.012, sd + 0.16, STATION_ROOF);
  k.glowBox(sx, sh - 0.07, z0 + 0.02, 0.86, 0.05, 0.03, hex(0xe8f0f4), LATE, COOL_GLOW);
  k.glowBox(sx, sh + 0.08, z0 - 0.09, 0.7, 0.1, 0.012, GONDOLA, LATE, RED_LIGHT);
  k.pane(sx - 0.2, 0.06, z1, 0.18, 0.32, 1, GLASS, LATE, WARM_GLOW);
  k.pane(sx + 0.2, 0.2, z1, 0.3, 0.2, 1, GLASS, LATE, WARM_GLOW);
  k.glowBox(sx, 0.46, z1 + 0.012, 0.7, 0.08, 0.012, GONDOLA, LATE, RED_LIGHT);
  // the cables: one straight climb from the hall, over the pylon's sheaves, to the back edge of the lot
  const cy = (z: number) => 0.56 + 1.5 * (z0 + 0.1 - z), pz = -0.5, ez = -D / 2 + 0.04;
  for (const s of [-1, 1]) {
    k.bar([sx + s * 0.18, cy(z0 + 0.1), z0 + 0.1], [sx + s * 0.18, cy(ez), ez], 0.014, DARK);
    k.hoop(sx + s * 0.18, cy(pz) - 0.085, pz, 0.07, 0.014, DARK, 8, 'zy');
  }
  // the pylon
  const ph = cy(pz) - 0.17;
  for (const [ax, az] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) {
    k.bar([sx + ax * 0.15, 0.02, pz + az * 0.15], [sx + ax * 0.045, ph, pz + az * 0.045], 0.02, STEEL);
  }
  for (const f of [0.3, 0.62]) k.hoop(sx, 0.02 + ph * f, pz, (0.15 - 0.105 * f) * Math.SQRT2, 0.012, STEEL, 4, 'xz');
  k.box(sx, ph, pz, 0.56, 0.06, 0.12, STEEL);
  k.box(sx, 0.02, pz, 0.44, 0.04, 0.44, scale(CONCRETE, 0.85));
  beacon(k, sx, ph + 0.06, pz);
  // the cabin, just out of the hall on the right-hand cable
  const gx = sx + 0.18, gz = -0.12, gy = cy(gz);
  k.bar([gx, gy, gz], [gx, gy - 0.2, gz], 0.012, DARK);
  k.box(gx, gy - 0.5, gz, 0.2, 0.3, 0.26, GONDOLA, WHITE);
  k.box(gx, gy - 0.36, gz, 0.21, 0.1, 0.27, GLASS);
  k.glowBox(gx, gy - 0.22, gz, 0.1, 0.03, 0.1, hex(0xf2e6b0), LATE, WARM_GLOW);
  // the ticket kiosk and the ski racks
  const kx = W / 2 - 0.3, kz = 0.62;
  k.box(kx, 0.02, kz, 0.3, 0.32, 0.3, WHITE, GONDOLA);
  k.box(kx, 0.34, kz, 0.38, 0.04, 0.38, GONDOLA);
  k.pane(kx, 0.14, kz + 0.15, 0.2, 0.13, 1, GLASS, LATE, SHOP_GLOW);
  const rx = W / 2 - 0.32, rz = 0.05;
  for (const s of [-1, 1]) k.box(rx, 0.02, rz + s * 0.2, 0.03, 0.22, 0.03, WOOD);
  k.box(rx, 0.22, rz, 0.03, 0.025, 0.46, WOOD);
  for (let i = 0; i < 5; i++) k.bar([rx + 0.09, 0.02, rz - 0.16 + i * 0.08], [rx + 0.01, 0.34, rz - 0.16 + i * 0.08], 0.012, BRIGHTS[i]);
  // a bench and a piste-map board on the other side
  k.box(-W / 2 + 0.22, 0.02, 0.0, 0.04, 0.4, 0.4, WOOD);
  k.box(-W / 2 + 0.245, 0.16, 0.0, 0.012, 0.22, 0.34, WHITE);
};

// ---- research dome (3 × 3) ----------------------------------------------------------------------------

const LAB = hex(0xf1f3f4), FRAME = hex(0x8a98a6), PANEL = hex(0x2c4f8a), LAB_TRIM = hex(0xe07b2a);

/** A round porthole on a wall facing +z, lit cool after dark. */
function porthole(k: Kit, x: number, y: number, z: number): void {
  k.box(x, y - 0.065, z + 0.003, 0.13, 0.13, 0.006, FRAME);
  k.pane(x, y - 0.05, z + 0.006, 0.05, 0.1, 1, GLASS, LATE, COOL_GLOW);
  for (const s of [-1, 1]) k.pane(x + s * 0.0375, y - 0.03, z + 0.006, 0.025, 0.06, 1, GLASS, LATE, COOL_GLOW);
}

/**
 * A research station: a white geodesic dome on a ring wall, two radomes, a row of lab modules on stilts
 * with portholes, a weather mast with turning cups, a dish and a bank of solar panels.
 */
const researchDome: Draw = (k, W, D) => {
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, hex(0xd5dadd));
  // the dome: faceted white panels in a darker frame
  const dx = -0.4, dz = -0.4, R = 0.9, by = 0.2, SEG = 8, RINGS = 3;
  k.cyl(dx, 0.02, dz, R + 0.03, by - 0.02, scale(LAB, 0.82), SEG * 2);
  k.dome(dx, by, dz, R, LAB, SEG, RINGS);
  const v = (j: number, i: number): P3 => {
    const p = (j / RINGS) * (Math.PI / 2), a = (i / SEG) * TAU, rr = Math.cos(p) * (R + 0.004);
    return [dx + Math.cos(a) * rr, by + Math.sin(p) * (R + 0.004), dz + Math.sin(a) * rr];
  };
  for (let i = 0; i < SEG; i++) {
    for (let j = 0; j < RINGS; j++) {
      k.bar(v(j, i), v(j + 1, i), 0.012, FRAME);
      if (j > 0) k.bar(v(j, i), v(j, i + 1), 0.012, FRAME);
      if (j < RINGS - 1) k.bar(i % 2 ? v(j, i) : v(j, i + 1), i % 2 ? v(j + 1, i + 1) : v(j + 1, i), 0.009, FRAME);
    }
    const a = ((i + 0.5) / SEG) * TAU;
    k.glowBox(dx + Math.cos(a) * (R + 0.0), 0.07, dz + Math.sin(a) * (R + 0.0), 0.09, 0.07, 0.09, hex(0xcfe0ea), LATE, COOL_GLOW);
  }
  // the airlock on the front of the dome, joined to the lab
  k.box(dx, 0.02, dz + R + 0.08, 0.32, 0.36, 0.36, LAB, LAB_TRIM);
  // the lab: three modules on stilts, joined end to end, portholes along the front
  const lz = 0.98, ly = 0.17;
  for (let i = 0; i < 3; i++) {
    const x = -0.12 + i * 0.58;
    for (const [ax, az] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) k.box(x + ax * 0.18, 0.02, lz + az * 0.15, 0.03, ly, 0.03, FRAME);
    k.box(x, ly, lz, 0.48, 0.3, 0.42, LAB);
    k.box(x, ly + 0.3, lz, 0.5, 0.03, 0.44, LAB_TRIM);
    if (i < 2) k.box(x + 0.29, ly + 0.04, lz, 0.12, 0.2, 0.24, FRAME);
    for (const s of [-1, 1]) porthole(k, x + s * 0.12, ly + 0.17, lz + 0.21);
  }
  k.box(0.46, 0.02, lz + 0.29, 0.16, 0.08, 0.14, FRAME);
  k.box(0.46, 0.1, lz + 0.25, 0.16, 0.08, 0.07, FRAME);
  // a radome on its tower in the back corner, and a small instrument dome with its slit
  const tx = 1.02, tz = -1.0;
  k.cyl(tx, 0.02, tz, 0.15, 0.36, scale(LAB, 0.85), 8);
  k.band(tx, tz, 0.38, 0.15, 0.5, 0.25, 8, scale(LAB, 0.9));
  k.dome(tx, 0.5, tz, 0.25, LAB, 8, 3);
  const ix = 1.05, iz = -0.3;
  k.cyl(ix, 0.02, iz, 0.2, 0.14, scale(LAB, 0.85), 8);
  k.dome(ix, 0.16, iz, 0.2, LAB, 8, 3);
  k.box(ix, 0.16, iz + 0.1, 0.06, 0.2, 0.22, DARK);
  // the satellite dish
  const sx = 0.98, sz = 0.3;
  k.cyl(sx, 0.02, sz, 0.035, 0.3, METAL, 6);
  k.band(sx, sz, 0.32, 0.03, 0.43, 0.2, 10, WHITE, scale(WHITE, 0.82));
  k.bar([sx, 0.33, sz], [sx, 0.56, sz], 0.01, DARK);
  k.box(sx, 0.54, sz, 0.04, 0.04, 0.04, DARK);
  // the weather mast, its cups turning, and a screen box beside it
  const mx = -1.2, mz = 0.75, mh = 1.3;
  k.box(mx, 0.02, mz, 0.03, mh, 0.03, METAL);
  for (const [ax, az] of [[1, 0.3], [-0.6, 1], [-0.5, -1]] as const) k.bar([mx, mh * 0.75, mz], [mx + ax * 0.22, 0.02, mz + az * 0.22], 0.005, DARK);
  k.box(mx, mh * 0.6, mz, 0.24, 0.02, 0.02, METAL);
  k.box(mx - 0.12, mh * 0.6, mz, 0.05, 0.08, 0.05, WHITE);
  k.spin(mx, mh + 0.03, mz, 'y', 3.2, (s) => {
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU, c = Math.cos(a), n = Math.sin(a);
      s.bar([0, 0.02, 0], [c * 0.13, 0.02, n * 0.13], 0.008, DARK);
      s.box(c * 0.14, -0.01, n * 0.14, 0.055, 0.055, 0.055, LAB_TRIM);
    }
  });
  beacon(k, mx, mh - 0.06, mz + 0.03);
  k.box(mx + 0.2, 0.02, mz + 0.05, 0.03, 0.18, 0.03, FRAME);
  k.box(mx + 0.2, 0.2, mz + 0.05, 0.13, 0.12, 0.13, WHITE);
  // solar panels, two tables tilted to the sun
  for (let i = 0; i < 2; i++) {
    const z = 0.98 + i * 0.3;
    k.turned(Math.PI, () => k.wedge(0.92, 0.04, -z, 0.72, 0.17, 0.2, FRAME));
    k.quad([-1.26, 0.215, z - 0.095], [-0.58, 0.215, z - 0.095], [-0.58, 0.052, z + 0.095], [-1.26, 0.052, z + 0.095], PANEL, [-0.92, 0, z - 0.05]);
  }
};

// ---- festival grounds (6 × 6) -------------------------------------------------------------------------

const FIELD = hex(0x86b85a), FIELD_MOWN = hex(0x93c466), TIMBER = hex(0x8a6a44), LOO = hex(0x3f7fb5), TRUSS = hex(0x4a4f56);
const STAGE_BLACK = hex(0x25272b), TENT_RED = hex(0xd8352b);

/** A string of bunting between two points, its flags seen from both sides. */
function bunting(k: Kit, a: P3, b: P3, n: number): void {
  const at = (t: number): P3 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
  k.bar(a, b, 0.005, DARK);
  for (let i = 0; i < n; i++) {
    const p = at((i + 0.15) / n), q = at((i + 0.85) / n);
    const m: P3 = [(p[0] + q[0]) / 2, (p[1] + q[1]) / 2 - 0.1, (p[2] + q[2]) / 2];
    const col = BRIGHTS[i % BRIGHTS.length];
    // a side-on normal, so one triangle is wound each way
    const nx = q[2] - p[2], nz = -(q[0] - p[0]);
    k.tri(p, q, m, col, [m[0] + nx, m[1], m[2] + nz]);
    k.tri(p, q, m, col, [m[0] - nx, m[1], m[2] - nz]);
  }
}

/**
 * A festival field. Out of season: mown grass inside a timber fence, a gate arch, a bare stage deck and
 * a row of loos. In summer the main stage goes up with its lights, and with it a striped marquee, a
 * camp of dome tents, food stalls, bunting and a ferris wheel.
 */
const festivalGrounds: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2, fx = hw - 0.15, fz = hd - 0.15;
  // the permanent part
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, FIELD);
  for (let i = 0; i < 5; i++) k.box(-hw + 0.95 + i * 1.02, 0.02, 0, 0.5, 0.006, D - 0.5, FIELD_MOWN);
  fence(k, -fx, -fz, fx, -fz, 0.2, TIMBER, TIMBER, true);
  for (const sx of [-1, 1]) {
    fence(k, sx * fx, -fz, sx * fx, fz, 0.2, TIMBER, TIMBER, true);
    fence(k, sx * 0.55, fz, sx * fx, fz, 0.2, TIMBER, TIMBER, true);
    k.box(sx * 0.55, 0.02, fz, 0.08, 0.8, 0.08, TIMBER);
  }
  k.box(0, 0.72, fz, 1.3, 0.1, 0.07, TIMBER);
  k.box(0, 0.84, fz, 0.8, 0.16, 0.04, WHITE, TIMBER);
  const stz = -hd + 0.8;
  k.box(0, 0.02, stz, 1.9, 0.16, 1.0, TIMBER, scale(TIMBER, 1.25));
  k.box(0, 0.02, stz + 0.56, 0.4, 0.08, 0.12, TIMBER, scale(TIMBER, 1.25));
  for (let i = 0; i < 5; i++) {
    const z = -0.9 + i * 0.27, x = -hw + 0.42;
    k.box(x, 0.02, z, 0.2, 0.34, 0.2, LOO, WHITE);
    k.box(x + 0.102, 0.04, z, 0.006, 0.26, 0.13, scale(LOO, 1.3));
  }

  k.tagged(Vis.Summer, () => {
    // the main stage: truss towers, a black roof and backdrop, a lit screen, speaker stacks, a rank of coloured lights
    const top = 1.15;
    for (const sx of [-1, 1]) {
      for (const sz of [-1, 1]) k.box(sx * 0.98, 0.02, stz + sz * 0.46, 0.07, top, 0.07, TRUSS);
      k.box(sx * 1.28, 0.02, stz + 0.42, 0.28, 0.72, 0.28, STAGE_BLACK, TRUSS);
      k.box(sx * 1.28, 0.2, stz + 0.565, 0.18, 0.18, 0.006, TRUSS);
      k.box(sx * 1.28, 0.48, stz + 0.565, 0.18, 0.18, 0.006, TRUSS);
      pennant(k, sx * 0.98, top + 0.14, stz - 0.46, 0.3, BRIGHTS[sx > 0 ? 0 : 2]);
    }
    k.box(0, top, stz, 2.15, 0.06, 1.1, TRUSS);
    k.turned(Math.PI, () => k.wedge(0, top + 0.06, -stz, 2.15, 0.16, 1.1, STAGE_BLACK));
    k.box(0, 0.18, stz - 0.47, 1.9, top - 0.18, 0.04, STAGE_BLACK);
    k.glowBox(0, 0.4, stz - 0.44, 1.1, 0.55, 0.02, hex(0x7a4fc0), [19, 26, 2.4], hex(0xc08aff));
    for (let i = 0; i < 7; i++) {
      const col = BRIGHTS[i % BRIGHTS.length];
      k.glowBox(-0.78 + i * 0.26, top - 0.08, stz + 0.5, 0.09, 0.08, 0.09, col, [19, 26, 3.2], col);
    }
    // the marquee: a round big top in red and white
    const mx = 1.85, mz = 0.35, MR = 0.85, wallH = 0.32, peak = 1.0, SEG = 12;
    for (let s = 0; s < SEG; s++) {
      const a0 = ((s - 0.5) / SEG) * TAU, a1 = ((s + 0.5) / SEG) * TAU, col = s % 2 ? WHITE : TENT_RED;
      const p0: P3 = [mx + Math.cos(a0) * MR, 0.02, mz + Math.sin(a0) * MR], p1: P3 = [mx + Math.cos(a1) * MR, 0.02, mz + Math.sin(a1) * MR];
      const q0: P3 = [p0[0], wallH, p0[2]], q1: P3 = [p1[0], wallH, p1[2]];
      k.quad(p0, p1, q1, q0, col, [mx, 0.2, mz]);
      k.tri(q0, q1, [mx, peak, mz], s % 2 ? TENT_RED : WHITE, [mx, 0.2, mz]);
    }
    k.box(mx - MR * Math.cos(Math.PI / SEG) - 0.005, 0.02, mz, 0.02, 0.26, 0.24, STAGE_BLACK);
    pennant(k, mx, peak - 0.02, mz, 0.3, hex(0xf2c14e));
    // the campsite: a dozen little dome tents
    for (let i = 0; i < 12; i++) {
      const x = -hw + 0.55 + (i % 4) * 0.46 + (r() - 0.5) * 0.14, z = 1.05 + Math.floor(i / 4) * 0.5 + (r() - 0.5) * 0.14;
      const col = BRIGHTS[Math.floor(r() * BRIGHTS.length)];
      k.dome(x, 0.02, z, 0.14, col, 6, 2);
      k.box(x, 0.02, z + 0.125, 0.07, 0.08, 0.02, scale(col, 0.6));
    }
    // food stalls under striped awnings, counters to the field
    for (let i = 0; i < 4; i++) {
      const x = 1.0 + i * 0.5, z = hd - 0.5, col = BRIGHTS[(i * 2 + 1) % BRIGHTS.length];
      k.box(x, 0.02, z + 0.06, 0.38, 0.4, 0.2, WHITE, col);
      k.box(x, 0.02, z - 0.1, 0.38, 0.17, 0.1, col, WOOD);
      for (let j = 0; j < 4; j++) {
        const x0 = x - 0.21 + j * 0.105, x1 = x0 + 0.105;
        k.quad([x0, 0.44, z + 0.04], [x1, 0.44, z + 0.04], [x1, 0.32, z - 0.26], [x0, 0.32, z - 0.26], j % 2 ? WHITE : col, [x, 0.1, z - 0.1]);
      }
      for (const sx of [-1, 1]) k.box(x + sx * 0.2, 0.02, z - 0.24, 0.02, 0.3, 0.02, WHITE);
      k.glowBox(x, 0.27, z - 0.04, 0.24, 0.04, 0.02, hex(0xf2e6b0), [18, 26, 2], WARM_GLOW);
    }
    // bunting from the gate up the field to the stage, on poles
    const poles: [number, number][] = [[-0.95, 1.4], [0.95, 1.4], [-0.95, -0.3], [0.95, -0.3]];
    for (const [px, pz] of poles) k.box(px, 0.02, pz, 0.035, 0.62, 0.035, WHITE);
    for (const sx of [-1, 1]) {
      bunting(k, [sx * 0.55, 0.8, fz], [sx * 0.95, 0.62, 1.4], 6);
      bunting(k, [sx * 0.95, 0.62, 1.4], [sx * 0.95, 0.62, -0.3], 7);
      bunting(k, [sx * 0.95, 0.62, -0.3], [sx * 0.98, top, stz + 0.46], 6);
    }
    bunting(k, [-0.95, 0.62, 1.4], [0.95, 0.62, 1.4], 8);
    bunting(k, [-0.95, 0.62, -0.3], [0.95, 0.62, -0.3], 8);
    // the gate dressed for the season
    k.glowBox(0, 0.86, fz + 0.022, 0.72, 0.12, 0.01, hex(0xf2a93b), [18, 26, 2], SHOP_GLOW);
    for (const sx of [-1, 1]) pennant(k, sx * 0.55, 0.82, fz, 0.32, BRIGHTS[sx > 0 ? 1 : 4]);
    // the ferris wheel, turning
    const wx = -hw + 1.0, wz = -hd + 1.25, WR = 0.75, ay = WR + 0.22;
    for (const sz of [-1, 1]) {
      for (const sx of [-1, 1]) k.bar([wx + sx * 0.42, 0.02, wz + sz * 0.14], [wx, ay, wz + sz * 0.14], 0.025, WHITE);
    }
    k.box(wx, 0.02, wz, 1.0, 0.05, 0.4, TRUSS);
    k.spin(wx, ay, wz, 'z', 0.3, (s) => {
      s.hoop(0, 0, 0, WR, 0.018, WHITE, 12, 'xy');
      s.hoop(0, 0, 0, WR * 0.55, 0.01, WHITE, 12, 'xy');
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * Math.PI;
        s.bar([Math.cos(a) * WR, Math.sin(a) * WR, 0], [-Math.cos(a) * WR, -Math.sin(a) * WR, 0], 0.01, WHITE);
      }
      for (let i = 0; i < 12; i++) {
        const a = (i / 12) * TAU, col = BRIGHTS[i % BRIGHTS.length];
        s.box(Math.cos(a) * WR, Math.sin(a) * WR - 0.06, 0, 0.12, 0.12, 0.14, col);
        s.glowBox(Math.cos(a) * WR * 0.55, Math.sin(a) * WR * 0.55 - 0.02, 0, 0.04, 0.04, 0.05, col, [18, 26, 3], col);
      }
      s.box(0, -0.05, 0, 0.1, 0.1, 0.3, TENT_RED);
    });
  });
};

