import { DIRS, N, idx, inB, waterDepth, type Building, type Town, type TownKind, type World } from '../world/tiles';
import { reachable } from '../world/graph';
import { carAcross } from '../world/spawn';
import { TOMATO } from './cars';
import { reachAmong } from './race/route';
import { ALL_VEHICLES, type LandDef } from './vehicles';
import { gradeOf } from './hqGrade';
import { nearestRoad } from './nearRoad';

/**
 * Where a new game begins (the first-drive tutorial, game/tutorial.ts). Since 14 Oct 2026: in the driveway
 * of a house in a small town, the house the fleet already owns as its first HQ (homeStart), the car on the
 * street in front of it facing the way to the town's Auto Shop. Before that, and still where no town has
 * a house that will do: on a road at the far edge of a small town, facing into it. The town is a rural one (else a suburb) in the first cell, one with
 * somewhere to fix a car (a garage, or a rural town's filling station) by preference, and a bigger town
 * only when no small one has a long enough road out; the spot is some way out along one of the roads
 * that leave it, far enough for a first run in, with the first job's goods ten tiles up the road.
 * Pure, so it can be run headless over many seeds.
 */

export interface FirstStart {
  /** Where the car stands, in the world's own tiles, and which way it faces (toward the town). */
  x: number; z: number; heading: number;
  /** The town it is on the edge of. */
  town: Town;
  /** The road tile the first job's goods wait on: ten tiles ahead, toward the town. */
  pickup: { x: number; z: number };
  /** The house the fleet starts in and owns, its level 1 HQ (14 Oct 2026); null on the old roadside start. */
  home: Building | null;
}

/** Road tiles from the town's edge the car starts, at best, and at the least. */
const OUT = 18, MIN_OUT = 12;
/** Tiles the start keeps clear of any other town, so the car begins out in the country. */
const CLEAR = 6;
/** Road tiles ahead of the car the goods are put down. */
const AHEAD = 10;

const RANK: Record<TownKind, number> = { rural: 0, suburb: 1, city: 2, metro: 3, mega: 4 };
/** The kinds that count as an auto shop, best first. */
export const SHOP_KINDS = ['garage', 'gas', 'carDealership'];

const drivable = (w: World, i: number): boolean => w.road[i] > 0 && !w.blocked[i] && !w.deckAxis[i] && waterDepth(w, i) === 0;
const inside = (t: Town, x: number, z: number, pad = 0): boolean =>
  x >= t.x0 - pad && x < t.x0 + t.size + pad && z >= t.z0 - pad && z < t.z0 + t.size + pad;

/**
 * The start: the driveway of a house in the best small town (homeStart), else the best spot out along a
 * road from it, or null when the cell has neither. `free` turns down a house that is already somebody's
 * (online, another player's deed).
 */
export function firstStart(w: World, free: (b: Building) => boolean = () => true): FirstStart | null {
  const towns = [...w.towns].sort((a, b) => {
    // the county's own Auto Shop (world/storefronts.ts) first, then any garage-ish building
    const shop = (t: Town) => (t.buildings.some((q) => q.storefront === 'shop') ? 0 : t.buildings.some((q) => SHOP_KINDS.includes(q.kind as string)) ? 1 : 2);
    const small = (t: Town) => (RANK[t.kind] <= RANK.suburb ? 0 : 1);
    return small(a) - small(b) || shop(a) - shop(b) || RANK[a.kind] - RANK[b.kind] || a.size - b.size;
  });
  for (const t of towns) {
    const h = homeStart(w, t, free);
    if (h) return h;
  }
  for (const t of towns) {
    const p = outward(w, t);
    if (!p || p.length - 1 < MIN_OUT) continue;
    const k = Math.min(p.length - 1, OUT);
    const at = p[k], next = p[k - 1];
    const x = at % N, z = Math.floor(at / N), nx = next % N, nz = Math.floor(next / N);
    // ten tiles up the road; on a road that winds back on itself, on until they are four clear of the car
    let g = Math.max(0, k - AHEAD);
    while (g > 0 && Math.hypot((p[g] % N) - x, Math.floor(p[g] / N) - z) < 4) g--;
    const goods = p[g];
    return {
      x: x + 0.5, z: z + 0.5, heading: Math.atan2(nx - x, nz - z), town: t,
      pickup: { x: (goods % N) + 0.5, z: Math.floor(goods / N) + 0.5 }, home: null,
    };
  }
  return null;
}

/** The kinds of home a fleet can start in: a house or a cottage, never a block of flats. */
const HOME_KINDS = ['house', 'cottage', 'bungalow', 'farmhouse', 'townhouse', 'duplex'];
/** Road tiles from the driveway to the Auto Shop, at best: far enough for a first run, near enough to learn the town. */
const HOME_RUN = 30, HOME_RUN_MIN = 12, HOME_RUN_MAX = 80;

/**
 * The driveway start in town t: a house of grade 1 (one fleet slot, so the first upgrade means something)
 * with a street at its front joined to the town's Auto Shop. The car stands on that street facing along
 * the way to the shop, and the goods wait ten tiles up it. Of the houses that will do, the one whose run
 * to the shop is nearest HOME_RUN road tiles.
 */
function homeStart(w: World, t: Town, free: (b: Building) => boolean): FirstStart | null {
  const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
  const shop = townShop(t, { x: cx, z: cz });
  if (!shop) return null;
  const sm = mid(shop);
  const heart = nearestRoad(w, sm.x, sm.z, 4);
  if (heart < 0) return null;
  const joined = connected(w, heart);
  const homes = t.buildings.filter((b) => HOME_KINDS.includes(b.kind as string) && !b.gone && !b.storefront && !b.derelict && gradeOf(b).grade === 1 && free(b))
    // a first look by the crow, nearest a good run first, so only a few routes are walked
    .map((b) => ({ b, crow: Math.hypot(mid(b).x - sm.x, mid(b).z - sm.z) }))
    .filter((q) => q.crow >= 6)
    .sort((p, q) => Math.abs(p.crow - HOME_RUN * 0.7) - Math.abs(q.crow - HOME_RUN * 0.7))
    .slice(0, 12);
  let best: { f: FirstStart; score: number } | null = null;
  for (const { b } of homes) {
    const kerb = kerbOf(w, b, joined);
    if (kerb < 0) continue;
    const kx = (kerb % N) + 0.5, kz = Math.floor(kerb / N) + 0.5;
    const route = roadRoute(w, kx, kz, sm.x, sm.z);
    if (!route || route.length - 1 < HOME_RUN_MIN || route.length - 1 > HOME_RUN_MAX || route[0] !== kerb) continue;
    const next = route[1];
    const heading = Math.atan2((next % N) - (kerb % N), Math.floor(next / N) - Math.floor(kerb / N));
    // the goods ten tiles up the road to the shop, and never on top of the car
    let g = Math.min(AHEAD, route.length - 2);
    while (g > 1 && Math.hypot((route[g] % N) + 0.5 - kx, Math.floor(route[g] / N) + 0.5 - kz) < 4) g++;
    const goods = route[Math.min(g, route.length - 2)];
    const score = Math.abs(route.length - 1 - HOME_RUN);
    if (!best || score < best.score) {
      best = { score, f: { x: kx, z: kz, heading, town: t, pickup: { x: (goods % N) + 0.5, z: Math.floor(goods / N) + 0.5 }, home: b } };
    }
  }
  return best?.f ?? null;
}

/** The street in front of a building, joined to the town's roads: its front first, else any side. -1 when none. */
function kerbOf(w: World, b: Building, joined: Uint8Array): number {
  const x0 = Math.floor(b.x), z0 = Math.floor(b.z), x1 = x0 + Math.ceil(b.w), z1 = z0 + Math.ceil(b.d);
  // the tiles along each side, outside the lot, in DIRS order: +x, +z, −x, −z
  const side = (d: number): number[] => {
    const out: number[] = [];
    if (d === 0 || d === 2) { const x = d === 0 ? x1 : x0 - 1; for (let z = z0; z < z1; z++) out.push(x, z); }
    else { const z = d === 1 ? z1 : z0 - 1; for (let x = x0; x < x1; x++) out.push(x, z); }
    return out;
  };
  const order = [b.facing, (b.facing + 1) & 3, (b.facing + 3) & 3, (b.facing + 2) & 3];
  for (const d of order) {
    const xs = side(d);
    // the middle of the side first: the driveway is in front of the door
    const mids = Array.from({ length: xs.length / 2 }, (_, k) => k).sort((p, q) => Math.abs(p - (xs.length / 4 - 0.5)) - Math.abs(q - (xs.length / 4 - 0.5)));
    for (const k of mids) {
      const x = xs[k * 2], z = xs[k * 2 + 1];
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (joined[i] && drivable(w, i)) return i;
    }
  }
  return -1;
}

/**
 * The road out of a town: from every road tile inside it at once, outward along roads that never come
 * back in, as far as OUT. The path runs from the last tile in town to the tile furthest out; where
 * several roads go as far, the one ending furthest from the town wins.
 */
function outward(w: World, t: Town): number[] | null {
  // only the streets joined to the town's heart (its auto shop, else its middle): a stub cut off by a
  // building would start the car on a road that never gets there
  const shop = t.buildings.find((b) => b.storefront === 'shop') ?? t.buildings.find((b) => SHOP_KINDS.includes(b.kind as string));
  const heart = shop ? nearestRoad(w, shop.x + shop.w / 2, shop.z + shop.d / 2, 4) : nearestRoad(w, t.x0 + t.size / 2, t.z0 + t.size / 2, t.size >> 1);
  if (heart < 0) return null;
  const joined = connected(w, heart);
  const others = w.towns.filter((o) => o !== t);
  const prev = new Map<number, number>();
  const dist = new Map<number, number>();
  const queue: number[] = [];
  for (let z = t.z0; z < t.z0 + t.size; z++) {
    for (let x = t.x0; x < t.x0 + t.size; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (!drivable(w, i) || !joined[i]) continue;
      prev.set(i, -1);
      dist.set(i, 0);
      queue.push(i);
    }
  }
  if (!queue.length) return null;
  const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
  const away = (i: number) => Math.hypot((i % N) - cx, Math.floor(i / N) - cz);
  let far = -1;
  for (let h = 0; h < queue.length; h++) {
    const i = queue[h];
    const d = dist.get(i)!;
    if (d > 0 && (far < 0 || d > dist.get(far)! || (d === dist.get(far)! && away(i) > away(far)))) far = i;
    if (d >= OUT) continue;
    const x = i % N, z = Math.floor(i / N);
    for (const [dx, dz] of DIRS) {
      const qx = x + dx, qz = z + dz;
      // out into the country: never back into this town, and never up to another one's edge
      if (!inB(qx, qz) || inside(t, qx, qz) || others.some((o) => inside(o, qx, qz, CLEAR))) continue;
      const q = idx(qx, qz);
      if (prev.has(q) || !drivable(w, q)) continue;
      prev.set(q, i);
      dist.set(q, d + 1);
      queue.push(q);
    }
  }
  if (far < 0) return null;
  const path: number[] = [];
  for (let i = far; i !== -1; i = prev.get(i)!) path.push(i);
  return path.reverse();
}

/**
 * The way by road from (x, z) to the road tile nearest (tx, tz), in one world's tiles: the tile
 * indices from the start's tile to the end's, or null when no road joins them. Off-road at the start
 * it sets out from the nearest road tile.
 */
export function roadRoute(w: World, x: number, z: number, tx: number, tz: number): number[] | null {
  const start = nearestRoad(w, x, z, 3), goal = nearestRoad(w, tx, tz, 4);
  if (start < 0 || goal < 0) return null;
  const prev = new Int32Array(N * N).fill(-2);
  prev[start] = -1;
  const queue = [start];
  for (let h = 0; h < queue.length; h++) {
    const i = queue[h];
    if (i === goal) break;
    const ix = i % N, iz = Math.floor(i / N);
    for (const [dx, dz] of DIRS) {
      const qx = ix + dx, qz = iz + dz;
      if (!inB(qx, qz)) continue;
      const q = idx(qx, qz);
      if (prev[q] !== -2 || !(w.road[q] > 0) || w.blocked[q]) continue;
      prev[q] = i;
      queue.push(q);
    }
  }
  if (prev[goal] === -2) return null;
  const path: number[] = [];
  for (let i = goal; i !== -1; i = prev[i]) path.push(i);
  return path.reverse();
}

/** How far ahead of the nose (x, z, heading) a tile's centre lies, in tiles: negative behind. */
const aheadOf = (i: number, x: number, z: number, heading: number): number =>
  ((i % N) + 0.5 - x) * Math.sin(heading) + (Math.floor(i / N) + 0.5 - z) * Math.cos(heading);

/** The fewest road tiles ahead of the car the first job's goods are put down. */
const AHEAD_MIN = 5;

/**
 * Where the first job's goods should wait for a car at (x, z) facing `heading`, local tiles on w: on the
 * road in front of it, so it never has to turn round to fetch them. Best on the way to (tx, tz) (the
 * auto shop), AHEAD tiles along it; else AHEAD tiles along whichever road runs on ahead, the one ending
 * nearest the shop. Null when no road runs on ahead far enough.
 */
export function pickupAhead(w: World, x: number, z: number, heading: number, tx: number, tz: number): { x: number; z: number } | null {
  const at = (i: number) => ({ x: (i % N) + 0.5, z: Math.floor(i / N) + 0.5 });
  // a winding road may bend away, but never so far round that the goods sit behind the car
  const ok = (i: number) => drivable(w, i) && aheadOf(i, x, z, heading) > 0.5;
  // on the way: the road to the shop leaves forward
  const route = roadRoute(w, x, z, tx, tz);
  if (route && route.length > AHEAD_MIN + 1 && aheadOf(route[1], x, z, heading) > 0) {
    for (let k = Math.min(AHEAD, route.length - 2); k >= AHEAD_MIN; k--) if (ok(route[k])) return at(route[k]);
  }
  // else along whatever road runs on ahead, never back past the car
  const tree = roadTree(w, x, z, AHEAD, heading);
  if (!tree) return null;
  let best = -1, bs = Infinity;
  for (const i of tree.order) {
    const d = tree.dist[i];
    if (d < AHEAD_MIN || !ok(i)) continue;
    const s = (AHEAD - d) * 4 + Math.hypot((i % N) + 0.5 - tx, Math.floor(i / N) + 0.5 - tz) * 0.1;
    if (s < bs) { bs = s; best = i; }
  }
  return best >= 0 ? at(best) : null;
}

/** Every road tile joined by road to this one. */
function connected(w: World, from: number): Uint8Array {
  const seen = new Uint8Array(N * N);
  seen[from] = 1;
  const queue = [from];
  for (let h = 0; h < queue.length; h++) {
    const i = queue[h], x = i % N, z = Math.floor(i / N);
    for (const [dx, dz] of DIRS) {
      const qx = x + dx, qz = z + dz;
      if (!inB(qx, qz)) continue;
      const q = idx(qx, qz);
      if (seen[q] || !(w.road[q] > 0) || w.blocked[q]) continue;
      seen[q] = 1;
      queue.push(q);
    }
  }
  return seen;
}


// ---- the rest of the first drive's roads: a straight for the nitrous, corners for the drifts ----

/** The way a direction turns: left of (dx, dz) is (dz, -dx), as a positive steer swings the heading. */
const turnOf = (d: [number, number], dir: 'left' | 'right'): [number, number] => (dir === 'left' ? [d[1], -d[0]] : [-d[1], d[0]]);
const roadAt = (w: World, x: number, z: number) => inB(x, z) && w.road[idx(x, z)] > 0 && !w.blocked[idx(x, z)];

/**
 * Road tiles reached from the one nearest (x, z), with how far each is by road and the tile it was
 * reached from. Given the car's heading, the way out never starts backward: every road it holds is one
 * the car can take without turning round.
 */
function roadTree(w: World, x: number, z: number, depth: number, heading?: number): { order: number[]; prev: Int32Array; dist: Int32Array; start: number } | null {
  let start = -1, bd = Infinity;
  for (let dz = -3; dz <= 3; dz++) {
    for (let dx = -3; dx <= 3; dx++) {
      const qx = Math.floor(x) + dx, qz = Math.floor(z) + dz;
      if (!roadAt(w, qx, qz)) continue;
      const d = Math.hypot(qx + 0.5 - x, qz + 0.5 - z);
      if (d < bd) { bd = d; start = idx(qx, qz); }
    }
  }
  if (start < 0) return null;
  const prev = new Int32Array(N * N).fill(-2), dist = new Int32Array(N * N).fill(-1);
  prev[start] = -1;
  dist[start] = 0;
  const order = [start];
  for (let h = 0; h < order.length; h++) {
    const i = order[h];
    if (dist[i] >= depth) continue;
    const ix = i % N, iz = Math.floor(i / N);
    for (const [dx, dz] of DIRS) {
      const qx = ix + dx, qz = iz + dz;
      if (!roadAt(w, qx, qz)) continue;
      const q = idx(qx, qz);
      if (prev[q] !== -2) continue;
      if (h === 0 && heading !== undefined && aheadOf(q, x, z, heading) < -0.3) continue;
      prev[q] = i;
      dist[q] = dist[i] + 1;
      order.push(q);
    }
  }
  return { order, prev, dist, start };
}

/** The way back through a tree from a tile to its root, root first. */
function wayTo(tree: { prev: Int32Array }, i: number): number[] {
  const back: number[] = [];
  for (let q = i; q >= 0; q = tree.prev[q]) back.push(q);
  return back.reverse();
}

/** Tiles further by road a way that needs no turning round may be, and still win over one that does. */
const FORWARD_GRACE = 30;

/**
 * A straight run of road near (x, z) long enough to get up to speed and fire a bottle: its tiles in
 * order from the end the car should start at. The nearest one 14 tiles long or more, else the longest.
 */
export function findStraight(w: World, x: number, z: number, heading?: number): number[] | null {
  return findStraightCourse(w, x, z, heading)?.tiles ?? null;
}

/**
 * The straight and the way to it: `path` runs by road from the car to the far end of the straight,
 * `start` is where the straight begins in it and `tiles` is the straight alone. Given the car's heading,
 * a straight the car can reach without turning round wins unless one behind is much nearer.
 */
export function findStraightCourse(w: World, x: number, z: number, heading?: number): { path: number[]; start: number; tiles: number[] } | null {
  const all = straightIn(w, roadTree(w, x, z, 90));
  const fwd = heading === undefined ? null : straightIn(w, roadTree(w, x, z, 90, heading));
  const best = fwd && (!all || fwd.score <= all.score + FORWARD_GRACE) ? fwd : all;
  if (!best) return null;
  return { path: [...best.lead.slice(0, -1), ...best.tiles], start: best.lead.length - 1, tiles: best.tiles };
}

function straightIn(w: World, tree: ReturnType<typeof roadTree>): { tiles: number[]; lead: number[]; score: number } | null {
  if (!tree) return null;
  let best: { tiles: number[]; at: number; score: number } | null = null;
  for (const i of tree.order) {
    const ix = i % N, iz = Math.floor(i / N);
    for (const [dx, dz] of DIRS) {
      // a run starts anywhere the car comes to it without turning round: never back the way it came
      if (tree.prev[i] >= 0 && roadAt(w, ix + dx, iz + dz) && tree.prev[i] === idx(ix + dx, iz + dz)) continue;
      // nor, at the car itself, back along the road behind it (the tree never holds that way)
      if (i === tree.start && roadAt(w, ix + dx, iz + dz) && tree.prev[idx(ix + dx, iz + dz)] === -2) continue;
      const tiles = [i];
      for (let k = 1; k < 30 && roadAt(w, ix + dx * k, iz + dz * k); k++) tiles.push(idx(ix + dx * k, iz + dz * k));
      if (tiles.length < 9) continue;
      const score = tree.dist[i] + (tiles.length < 14 ? 40 - tiles.length : 0) - Math.min(tiles.length, 24) * 0.3;
      if (!best || score < best.score) best = { tiles, at: i, score };
    }
  }
  return best ? { tiles: best.tiles, lead: wayTo(tree, best.at), score: best.score } : null;
}

/**
 * A corner to drift round, turning `dir`: the way to it by road with at least three straight tiles
 * running into it, then three tiles of road out of it the other way. `corner` is its index in `path`.
 * Given the car's heading, a corner the car can reach without turning round wins unless one behind is
 * much nearer the best distance for a run-up.
 */
export function findCorner(w: World, x: number, z: number, dir: 'left' | 'right', heading?: number): { path: number[]; corner: number } | null {
  const all = cornerIn(w, roadTree(w, x, z, 60), dir);
  const fwd = heading === undefined ? null : cornerIn(w, roadTree(w, x, z, 60, heading), dir);
  const best = fwd && (!all || fwd.score <= all.score + FORWARD_GRACE / 2) ? fwd : all;
  return best ? { path: best.path, corner: best.corner } : null;
}

function cornerIn(w: World, tree: ReturnType<typeof roadTree>, dir: 'left' | 'right'): { path: number[]; corner: number; score: number } | null {
  if (!tree) return null;
  let best: { path: number[]; corner: number; score: number } | null = null;
  for (const i of tree.order) {
    const d0 = tree.dist[i];
    if (d0 < 5) continue;
    // the last three steps in: all the same way
    const a = tree.prev[i], b = a >= 0 ? tree.prev[a] : -1, c = b >= 0 ? tree.prev[b] : -1;
    if (c < 0) continue;
    const step = (p: number, q: number): [number, number] => [(q % N) - (p % N), Math.floor(q / N) - Math.floor(p / N)];
    const s1 = step(a, i), s2 = step(b, a), s3 = step(c, b);
    if (s1[0] !== s2[0] || s1[1] !== s2[1] || s2[0] !== s3[0] || s2[1] !== s3[1]) continue;
    const [tx, tz] = turnOf(s1, dir);
    const ix = i % N, iz = Math.floor(i / N);
    const out: number[] = [];
    for (let k = 1; k <= 3 && roadAt(w, ix + tx * k, iz + tz * k); k++) out.push(idx(ix + tx * k, iz + tz * k));
    if (out.length < 3) continue;
    // a true bend (the road stops ahead) is the better lesson than a crossroads
    const bend = !roadAt(w, ix + s1[0], iz + s1[1]);
    const score = Math.abs(d0 - 12) + (bend ? 0 : 4);
    if (best && score >= best.score) continue;
    const back = wayTo(tree, i);
    best = { path: [...back, ...out], corner: back.length - 1, score };
  }
  return best;
}

/**
 * Does the car, from this start, reach the cell's edge on every side the macro layer says a car can
 * cross (a land border or a causeway, world/spawn.ts `carAcross`)? world/spawn.ts chose the start cell
 * on that promise; this checks it on the generated ground, so a start whose island turns out cut off
 * is passed over for the next candidate. Off-road counts: a car can cross grass as well as road.
 */
export function startReaches(w: World, start: { x: number; z: number }, seedHash: number): boolean {
  const s = idx(Math.max(0, Math.min(N - 1, Math.floor(start.x))), Math.max(0, Math.min(N - 1, Math.floor(start.z))));
  const seen = reachable(w, s, TOMATO);
  let sides = 0;
  for (let d = 0; d < 4; d++) {
    if (!carAcross(seedHash, w.cx, w.cz, d)) continue;
    sides++;
    let hit = false;
    for (let k = 0; k < N && !hit; k++) {
      const x = d === 0 ? N - 1 : d === 2 ? 0 : k, z = d === 1 ? N - 1 : d === 3 ? 0 : k;
      if (seen[idx(x, z)]) hit = true;
    }
    if (!hit) return false;
  }
  return sides > 0;
}

// ---- how far the first drive sends a new player (the user, 7 Oct 2026) ---------------------------

/**
 * The farthest, in road tiles, the first drive's missions send a new player: from the start to the first
 * Auto Shop (the first job), and from there to the friend's Auto Shop in another town (the handbrake). A
 * start that would send them further is turned down (main.ts asks the server for another home).
 */
export const FIRST_DRIVE_MAX = 150;
/** The friend's shop is another town's, at least this far from the first as the crow flies. */
const FRIEND_MIN = 30;

const mid = (b: Building): { x: number; z: number } => ({ x: b.x + b.w / 2, z: b.z + b.d / 2 });

/**
 * A town's Auto Shop as the first job finds it (missions/templates.ts autoShopOf): the county's own, else a
 * garage, a filling station, a car dealer or a store, the nearest to `near`. In the world's own tiles.
 */
export function townShop(t: Town, near: { x: number; z: number }): Building | null {
  const own = t.buildings.find((b) => b.storefront === 'shop' && !b.gone);
  if (own) return own;
  const d = (b: Building) => Math.hypot(mid(b).x - near.x, mid(b).z - near.z);
  for (const kinds of [['garage'], ['gas'], ['carDealership'], ['store', 'generalStore', 'shop', 'grocery']]) {
    const b = t.buildings.filter((q) => !q.gone && kinds.includes(q.kind as string)).sort((p, q) => d(p) - d(q))[0];
    if (b) return b;
  }
  return null;
}

/** Road tiles from a to b in one world's tiles, or Infinity when no road joins them. */
export function roadTiles(w: World, a: { x: number; z: number }, b: { x: number; z: number }): number {
  const r = roadRoute(w, a.x, a.z, b.x, b.z);
  return r ? r.length - 1 : Infinity;
}

/**
 * The friend's shops a first drive could send the player on to: another town's garage, filling station or
 * car dealer in this county, FRIEND_MIN or more from the first shop and within FIRST_DRIVE_MAX road tiles
 * of it. Nearest by road first.
 */
export function friendShops(w: World, not: Town, from: { x: number; z: number }): { t: Town; b: Building; tiles: number }[] {
  const out: { t: Town; b: Building; tiles: number }[] = [];
  for (const t of w.towns) {
    if (t === not) continue;
    const b = t.buildings.filter((q) => !q.gone && SHOP_KINDS.includes(q.kind as string))
      .sort((p, q) => Math.hypot(mid(p).x - from.x, mid(p).z - from.z) - Math.hypot(mid(q).x - from.x, mid(q).z - from.z))[0];
    if (!b) continue;
    const crow = Math.hypot(mid(b).x - from.x, mid(b).z - from.z);
    if (crow < FRIEND_MIN || crow > FIRST_DRIVE_MAX) continue;
    const tiles = roadTiles(w, from, mid(b));
    if (tiles <= FIRST_DRIVE_MAX) out.push({ t, b, tiles });
  }
  return out.sort((p, q) => p.tiles - q.tiles);
}

/**
 * Why this start's first drive would send a new player too far, or null when it all fits: the first Auto
 * Shop more than FIRST_DRIVE_MAX road tiles from the start, or no other town's Auto Shop within
 * FIRST_DRIVE_MAX road tiles of the first.
 */
export function firstDriveTooFar(w: World, f: FirstStart): string | null {
  const shop = townShop(f.town, f.pickup);
  if (!shop) return 'no Auto Shop in the first town';
  const d1 = roadTiles(w, f, mid(shop));
  if (d1 > FIRST_DRIVE_MAX) return Number.isFinite(d1) ? `the first Auto Shop is ${d1} road tiles from the start` : 'no road from the start to the first Auto Shop';
  if (!friendShops(w, f.town, mid(shop)).length) return `no other town's Auto Shop within ${FIRST_DRIVE_MAX} road tiles of the first`;
  return null;
}
