import * as THREE from 'three';
import { N, STEP, idx, heightAt, type SkiLift, type Work, type World } from '../world/tiles';
import { hex } from '../world/biomes';
import { regionOf } from '../world/regions';
import { LIFT, liftAxis, ropeAt } from '../world/skiFields';
import { PERMANENT_SNOW, SEASON } from './season';
import type { Kit, P3 } from './buildings/kit';
import { rand } from '../util/math';

/**
 * Ski lifts: the towers and ropes drawn into the chunks with the rest of a ski field, and the moving part
 * of it, here, over every county in memory: the chairs and gondola cabins going round each rope loop, up
 * one side and down the other and round the bull wheels at the stations, and in season the skiers
 * (little spheres, as everyone in this game is) queueing at the bottom stations, riding up, getting off
 * at the top, skiing back down the runs and queueing again.
 *
 * All of it is four instanced meshes for the whole map. Carriers are placed from each lift's rope
 * phase, so nothing about them needs simulating; skiers are simulated every frame near the camera, a
 * frame in four (or eight) further off or out of view, and not at all far away or in a county not in
 * memory.
 */

// ---------------------------------------------------------------------------------------------
// the fixed part: towers and ropes, drawn into the chunk geometry (render/townMesh.ts)

const STEEL = hex(0xb9bdc2), STEEL_DARK = hex(0x6d7176), ROPE = hex(0x3d3a37), FOOTING = hex(0xa9a49a);
/** A resort run's sign at its top, in its grade's colour (a black run's twice over). */
const GRADE_SIGN = { green: hex(0x3f9b4a), blue: hex(0x2f7fb5), black: hex(0x22252a) } as const;

/**
 * A ski field's lifts in one chunk: each tower is drawn by the chunk its foot stands in, each rope span
 * by the chunk holding its middle, so nothing is drawn twice where chunks meet.
 */
export function drawSkiLifts(k: Kit, w: World, g: Work, x0: number, z0: number, size: number): void {
  const inside = (x: number, z: number) => x >= x0 && x < x0 + size && z >= z0 && z < z0 + size;
  k.place(0, 0, 0, 0);
  for (const l of g.lifts ?? []) {
    const spec = LIFT[l.kind];
    const { L, ux, uz } = liftAxis(l);
    const rx = -uz, rz = ux, half = spec.gauge / 2;
    const at = (s: number, side: number, y: number): P3 => [l.x0 + ux * s + rx * half * side, y, l.z0 + uz * s + rz * half * side];
    for (const t of l.towers) {
      const px = l.x0 + ux * t.s, pz = l.z0 + uz * t.s;
      if (!inside(px, pz)) continue;
      const foot = heightAt(w, px, pz) - 0.04;
      const head = t.y + 0.07;
      k.box(px, foot, pz, 0.2, 0.09, 0.2, FOOTING);
      if (l.kind === 'gondola') {
        // a splayed pair of legs along the line, braced, under a wide head frame
        const spread = Math.min(0.42, 0.14 + (head - foot) * 0.07);
        for (const e of [-1, 1]) k.bar([px + ux * spread * e, foot, pz + uz * spread * e], [px + ux * 0.07 * e, head, pz + uz * 0.07 * e], 0.035, STEEL);
        const mid = foot + (head - foot) * 0.45, ms = spread * 0.55 + 0.04;
        k.bar([px - ux * ms, mid, pz - uz * ms], [px + ux * ms, mid, pz + uz * ms], 0.022, STEEL);
      } else {
        k.bar([px, foot, pz], [px, head, pz], 0.042, STEEL);
      }
      // the cross arm, and a sheave train under each rope
      const arm = half + (l.kind === 'gondola' ? 0.16 : 0.09);
      k.bar([px - rx * arm, head, pz - rz * arm], [px + rx * arm, head, pz + rz * arm], 0.03, STEEL);
      for (const side of [-1, 1]) {
        const cx = px + rx * half * side, cz = pz + rz * half * side;
        k.bar([cx - ux * 0.13, t.y + 0.022, cz - uz * 0.13], [cx + ux * 0.13, t.y + 0.022, cz + uz * 0.13], 0.022, STEEL_DARK);
        k.bar([cx, t.y + 0.04, cz], [cx, head, cz], 0.012, STEEL_DARK);
      }
    }
    // a resort's runs signed at their tops: a post and a board in the run's grade colour
    l.runs.forEach((pts, n) => {
      const g = l.grades?.[n];
      if (!g || !inside(pts[0], pts[1])) return;
      const px = pts[0] + rx * 1.1, pz = pts[1] + rz * 1.1, foot = heightAt(w, px, pz) - 0.03;
      k.bar([px, foot, pz], [px, foot + 0.62, pz], 0.025, STEEL_DARK);
      k.box(px, foot + 0.42, pz, 0.2, 0.16, 0.04, GRADE_SIGN[g]);
      if (g === 'black') k.box(px, foot + 0.24, pz, 0.14, 0.12, 0.04, GRADE_SIGN[g]);
    });
    // the haul rope, up one side and back down the other, straight from support to support
    const sup = [{ s: 0, y: l.y0 }, ...l.towers, { s: L, y: l.y1 }];
    for (let i = 1; i < sup.length; i++) {
      const a = sup[i - 1], b = sup[i], ms = (a.s + b.s) / 2;
      if (!inside(l.x0 + ux * ms, l.z0 + uz * ms)) continue;
      for (const side of [-1, 1]) k.bar(at(a.s, side, a.y), at(b.s, side, b.y), 0.013, ROPE);
    }
  }
}

// ---------------------------------------------------------------------------------------------
// the moving part

const RADIUS = 0.056;          // as the beach and piste visitors (game/pedestrians.ts)
const COLOURS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5, 0xf4f2ec, 0x3a3f45, 0xc9463d, 0x6fb8e0];
const CHAIR_PAINT = [0xe2412f, 0x2f7fb5, 0xf2a93b, 0x3f9b4a, 0x3a3f45];
const CABIN_PAINT = [0xe2412f, 0xf2c14e, 0xf4f2ec, 0x2f7fb5];
const CAP_CHAIR = 1600, CAP_CABIN = 500, CAP_SKIER = 900;
/** Tiles from the camera's focus to a field's edge: every frame inside NEAR, a frame in a few out to FAR, then nothing. */
const NEAR = 70, FAR = 160;
/** Skiers a lift keeps busy, and most at one field. */
const PER_LIFT = 20, MAX_FIELD = 56;
/** Seat top below the rope (a chair), and the cabin's floor below it (a gondola). */
const SEAT_DROP = 0.44, CABIN_FLOOR = 0.41, CABIN_HANG = 0.08;
const WALK = 0.5, SKATE = 0.8;
/** The open hours: the lifts start turning a little before and run till the last riders are down. */
const OPEN = 8.5, CLOSE = 17;

type State = 'walk' | 'queue' | 'ride' | 'off' | 'ski' | 'lodge';
/** A run's line, and the lift (in its field) whose queue it ends in at a resort, else -1. */
interface Run { pts: Float32Array; cum: Float32Array; len: number; end: number }
interface Skier {
  st: State; x: number; z: number; y: number;
  lift: number; carrier: number; seat: number; t0: number;
  run: Run | null; s: number; speed: number; amp: number; lam: number; ph: number; bias: number;
  timer: number; tx: number; tz: number; colour: number; ready: boolean; home: boolean;
}
interface LiftRt {
  l: SkiLift; L: number; ux: number; uz: number; rx: number; rz: number; r: number;
  Lp: number; K: number; spacing: number; phase: number; v: number; n: number;
  queue: Skier[]; occ: Uint8Array; runs: Run[]; paint: number;
}
interface Field {
  w: World; g: Work; lifts: LiftRt[]; skiers: Skier[]; door: { x: number; z: number };
  cx: number; cy: number; cz: number; rad: number; acc: number; slot: number; spawn: number;
  allYear: boolean; fresh: boolean;
}

const tmp = { x: 0, y: 0, z: 0, dx: 0, dz: 0 };

function makeRun(p: number[], end = -1): Run | null {
  const n = p.length / 2;
  if (n < 3) return null;
  const pts = Float32Array.from(p), cum = new Float32Array(n);
  for (let k = 1; k < n; k++) cum[k] = cum[k - 1] + Math.hypot(pts[k * 2] - pts[k * 2 - 2], pts[k * 2 + 1] - pts[k * 2 - 1]);
  return { pts, cum, len: cum[n - 1], end };
}

/** The point s along a run, and its direction there, into tmp. */
function along(r: Run, s: number): void {
  const n = r.cum.length;
  let k = 1;
  while (k < n - 1 && r.cum[k] < s) k++;
  const seg = r.cum[k] - r.cum[k - 1] || 1, f = Math.min(1, Math.max(0, (s - r.cum[k - 1]) / seg));
  const ax = r.pts[k * 2 - 2], az = r.pts[k * 2 - 1], bx = r.pts[k * 2], bz = r.pts[k * 2 + 1];
  tmp.x = ax + (bx - ax) * f; tmp.z = az + (bz - az) * f;
  tmp.dx = (bx - ax) / seg; tmp.dz = (bz - az) / seg;
}

/** Where a carrier u along the loop is (island tiles, world-unit rope height) and which way it is going, into tmp. */
function carrierAt(t: LiftRt, u: number): void {
  const { l, L, ux, uz, rx, rz, r } = t;
  const half = Math.PI * r;
  if (u < L) {
    tmp.x = l.x0 + ux * u + rx * r; tmp.z = l.z0 + uz * u + rz * r; tmp.y = ropeAt(l, u, L);
    tmp.dx = ux; tmp.dz = uz;
  } else if (u < L + half) {
    const a = (u - L) / r, c = Math.cos(a), s = Math.sin(a);
    tmp.x = l.x1 + rx * r * c + ux * r * s; tmp.z = l.z1 + rz * r * c + uz * r * s; tmp.y = l.y1;
    tmp.dx = -rx * s + ux * c; tmp.dz = -rz * s + uz * c;
  } else if (u < 2 * L + half) {
    const s = L - (u - L - half);
    tmp.x = l.x0 + ux * s - rx * r; tmp.z = l.z0 + uz * s - rz * r; tmp.y = ropeAt(l, s, L);
    tmp.dx = -ux; tmp.dz = -uz;
  } else {
    const a = (u - 2 * L - half) / r, c = Math.cos(a), s = Math.sin(a);
    tmp.x = l.x0 - rx * r * c - ux * r * s; tmp.z = l.z0 - rz * r * c - uz * r * s; tmp.y = l.y0;
    tmp.dx = rx * s - ux * c; tmp.dz = rz * s - uz * c;
  }
}

/** The ground (or a station's platform) under a point, world units. */
function groundY(f: Field, x: number, z: number): number {
  let y = heightAt(f.w, x, z);
  for (const t of f.lifts) {
    if (Math.max(Math.abs(x - t.l.x0), Math.abs(z - t.l.z0)) < 1.3 || Math.max(Math.abs(x - t.l.x1), Math.abs(z - t.l.z1)) < 1.3) { y += 0.14; break; }
  }
  return y;
}

export class SkiLifts {
  readonly root = new THREE.Group();
  private hanger: THREE.InstancedMesh;
  private chair: THREE.InstancedMesh;
  private cabin: THREE.InstancedMesh;
  private skier: THREE.InstancedMesh;
  private fields = new Map<Work, Field>();
  private frame = 0;
  private m = new THREE.Matrix4();
  private c = new THREE.Color();
  private frustum = new THREE.Frustum();
  private proj = new THREE.Matrix4();
  private sphere = new THREE.Sphere();
  private nHanger = 0; private nChair = 0; private nCabin = 0; private nSkier = 0;
  /** Skiers who have got on a lift, and runs skied to the bottom, since the start (for the gate and the console). */
  boarded = 0;
  runsDone = 0;
  /** Resort runs skied to the bottom whose skier queued at the lift the run ends at. */
  endQueued = 0;

  constructor() {
    this.root.name = 'ski lifts';
    // one material as the pedestrians' (instanced, coloured per instance), so no new shader is compiled
    const mat = new THREE.MeshStandardMaterial({ roughness: 0.6, metalness: 0 });
    const make = (geo: THREE.BufferGeometry, cap: number) => {
      const im = new THREE.InstancedMesh(geo, mat, cap);
      im.count = 0;
      im.frustumCulled = false;
      for (let i = 0; i < cap; i++) im.setColorAt(i, this.c.setHex(0xffffff));
      this.root.add(im);
      return im;
    };
    this.hanger = make(new THREE.BoxGeometry(0.018, 1, 0.018).translate(0, -0.5, 0), CAP_CHAIR + CAP_CABIN);
    this.chair = make(merge([
      box(0.27, 0.035, 0.14, 0, -0.0175, 0), box(0.27, 0.13, 0.022, 0, 0.065, -0.07),
      box(0.016, 0.07, 0.13, -0.135, 0.03, 0), box(0.016, 0.07, 0.13, 0.135, 0.03, 0),
      box(0.27, 0.016, 0.016, 0, -0.14, 0.1), box(0.016, 0.14, 0.016, -0.12, -0.07, 0.09), box(0.016, 0.14, 0.016, 0.12, -0.07, 0.09),
    ]), CAP_CHAIR);
    this.cabin = make(merge([
      box(0.34, 0.035, 0.34, 0, -0.0175, 0),
      ...[[-1, -1], [-1, 1], [1, -1], [1, 1]].map(([a, b]) => box(0.022, 0.31, 0.022, a * 0.155, -0.19, b * 0.155)),
      box(0.33, 0.075, 0.33, 0, -CABIN_FLOOR + CABIN_HANG + 0.0375, 0),
    ]), CAP_CABIN);
    this.skier = make(new THREE.IcosahedronGeometry(RADIUS, 1), CAP_SKIER);
  }

  /** How many of each there are, for the console. */
  get counts(): { fields: number; lifts: number; carriers: number; skiers: number; riding: number; queueing: number; skiing: number } {
    let lifts = 0, carriers = 0, skiers = 0, riding = 0, queueing = 0, skiing = 0;
    for (const f of this.fields.values()) {
      lifts += f.lifts.length;
      for (const t of f.lifts) carriers += t.K;
      for (const s of f.skiers) { skiers++; if (s.st === 'ride') riding++; else if (s.st === 'queue') queueing++; else if (s.st === 'ski') skiing++; }
    }
    return { fields: this.fields.size, lifts, carriers, skiers, riding, queueing, skiing };
  }

  /**
   * Run every lift in the counties in memory and draw the ones in view. `focus` is the camera's focus in
   * world units; `camera`, when given, keeps the fields out of view from being drawn and slows them.
   */
  update(dt: number, worlds: World[], focus: { x: number; z: number }, hour: number, camera?: THREE.Camera): void {
    this.frame++;
    if (camera) {
      this.proj.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
      this.frustum.setFromProjectionMatrix(this.proj);
    }
    this.nHanger = this.nChair = this.nCabin = this.nSkier = 0;
    const seen = new Set<Work>();
    for (const w of worlds) {
      for (const g of w.works) {
        if (!g.lifts?.length) continue;
        seen.add(g);
        let f = this.fields.get(g);
        if (!f) { f = this.field(w, g); this.fields.set(g, f); }
        const d = Math.hypot(w.ox + f.cx - focus.x, w.oz + f.cz - focus.z) - f.rad;
        if (d > FAR) { f.acc = 0; continue; }
        this.sphere.center.set(w.ox + f.cx, f.cy, w.oz + f.cz);
        this.sphere.radius = f.rad;
        const shown = !camera || this.frustum.intersectsSphere(this.sphere);
        const every = d < NEAR ? (shown ? 1 : 4) : shown ? 3 : 8;
        f.acc += dt;
        if ((this.frame + f.slot) % every === 0) {
          // big gaps (a field that was off-screen) in short steps, so nobody skips a station
          let left = Math.min(f.acc, 2);
          while (left > 1e-4) { const h = Math.min(left, 0.25); this.step(f, h, hour); left -= h; }
          f.acc = 0;
        }
        if (shown) this.draw(f);
      }
    }
    for (const g of [...this.fields.keys()]) if (!seen.has(g)) this.fields.delete(g);
    for (const [im, n] of [[this.hanger, this.nHanger], [this.chair, this.nChair], [this.cabin, this.nCabin], [this.skier, this.nSkier]] as const) {
      im.count = n;
      im.visible = n > 0;
      if (n) { im.instanceMatrix.needsUpdate = true; if (im.instanceColor) im.instanceColor.needsUpdate = true; }
    }
  }

  private field(w: World, g: Work): Field {
    const lifts: LiftRt[] = g.lifts!.map((l, i) => {
      const spec = LIFT[l.kind];
      const { L, ux, uz } = liftAxis(l);
      const r = spec.gauge / 2;
      const Lp = 2 * L + 2 * Math.PI * r;
      const K = Math.max(4, Math.round(Lp / spec.spacing));
      const paint = (l.kind === 'gondola' ? CABIN_PAINT : CHAIR_PAINT)[(Math.floor(g.x * 7 + g.z * 13) + i) % (l.kind === 'gondola' ? CABIN_PAINT.length : CHAIR_PAINT.length)];
      return {
        l, L, ux, uz, rx: -uz, rz: ux, r, Lp, K, spacing: Lp / K, phase: Math.random() * Lp, v: 0, n: 0,
        queue: [], occ: new Uint8Array(K), runs: l.runs.map((p, k) => makeRun(p, l.ends?.[k] ?? -1)).filter((x): x is Run => !!x), paint,
      };
    });
    for (const t of lifts) t.n = Math.floor(t.phase / t.spacing);
    // the lodge's front door, where skiers come from and go back to
    const lodge = g.buildings.find((b) => b.kind === 'lodge');
    const door = lodge ? { x: lodge.x + lodge.w / 2, z: lodge.z + lodge.d + 0.2 } : { x: g.x + 0.5, z: g.z + 0.5 };
    let cx = 0, cz = 0, lo = Infinity, hi = -Infinity;
    for (const t of lifts) { cx += t.l.x0 + t.l.x1; cz += t.l.z0 + t.l.z1; lo = Math.min(lo, t.l.y0); hi = Math.max(hi, t.l.y1); }
    cx /= lifts.length * 2; cz /= lifts.length * 2;
    let rad = 0;
    for (const t of lifts) rad = Math.max(rad, Math.hypot(t.l.x0 - cx, t.l.z0 - cz), Math.hypot(t.l.x1 - cx, t.l.z1 - cz));
    for (const t of lifts) for (const r of t.runs) for (let k = 0; k < r.pts.length; k += 2) rad = Math.max(rad, Math.hypot(r.pts[k] - cx, r.pts[k + 1] - cz));
    // snow lies at the bottom all year where the county's own snow line is under it (the Icefield, high country)
    const ti = idx(Math.min(N - 1, Math.max(0, g.x)), Math.min(N - 1, Math.max(0, g.z)));
    const spec = w.regionK[ti] ? regionOf(w.regionK[ti]) : null;
    let line = PERMANENT_SNOW;
    if (spec && typeof spec.snowLine === 'number' && w.regionW[ti] > 128) line = spec.snowLine;
    if (w.snowLine[ti] > 0) line = Math.max(line, w.snowLine[ti] * STEP);
    return {
      w, g, lifts, skiers: [], door, cx, cy: (lo + hi) / 2, cz, rad: rad + 3 + (hi - lo) / 2, acc: 0,
      slot: Math.floor(Math.random() * 8), spawn: 0, allYear: g.level * STEP >= line, fresh: true,
    };
  }

  /** Skiing today: snow lying (winter, a storm, or a field above the snow line) and the lifts' hours. A canyon's cable car has no skiers. */
  private open(f: Field, hour: number): boolean {
    return f.g.kind === 'ski' && hour >= OPEN && hour < CLOSE && (SEASON.uSnow.value >= 0.3 || f.allYear);
  }

  private step(f: Field, dt: number, hour: number): void {
    const open = this.open(f, hour);
    const want = open ? Math.min(MAX_FIELD, PER_LIFT * f.lifts.length) : 0;
    // a field come into memory while open is already busy; one that has just opened fills from the lodge
    if (f.fresh) { f.fresh = false; if (open) this.populate(f, want); }
    f.spawn -= dt;
    if (f.skiers.length < want && f.spawn <= 0) {
      f.spawn = rand(0.3, 0.9);
      const s = this.newSkier(f.door.x + rand(-0.5, 0.5), f.door.z + rand(-0.2, 0.2));
      this.toQueue(f, s, WALK);
      f.skiers.push(s);
    }

    for (let i = 0; i < f.lifts.length; i++) {
      const t = f.lifts[i];
      const spec = LIFT[t.l.kind];
      let riders = 0;
      for (let c = 0; c < t.K; c++) riders += t.occ[c];
      // chairs run in the open hours of a skiing day; a gondola carries sightseers all summer's day too
      const run = open || riders > 0 || t.queue.length > 0 || (t.l.kind === 'gondola' && hour >= 8 && hour < 20);
      const target = run ? spec.speed : 0;
      t.v += Math.max(-dt * 0.4, Math.min(dt * 0.4, target - t.v));
      t.phase += t.v * dt;
      if (t.phase > 1e6) { t.phase -= t.Lp * Math.floor(1e6 / t.Lp); t.n = Math.floor(t.phase / t.spacing); for (const s of f.skiers) if (s.st === 'ride' && s.lift === i) s.t0 -= t.Lp * Math.floor(1e6 / t.Lp); }
      const n = Math.floor(t.phase / t.spacing);
      for (let k = Math.max(t.n + 1, n - 4); k <= n; k++) this.board(f, i, k);
      t.n = n;
    }

    for (let i = f.skiers.length - 1; i >= 0; i--) {
      const s = f.skiers[i];
      if (this.move(f, s, dt, open)) f.skiers.splice(i, 1);
    }
  }

  private newSkier(x: number, z: number): Skier {
    return {
      st: 'walk', x, z, y: 0, lift: 0, carrier: 0, seat: 0, t0: 0, run: null, s: 0,
      speed: rand(1.4, 2.6), amp: rand(0.5, 1.4), lam: rand(2.6, 5), ph: rand(0, 6.3), bias: rand(-0.6, 0.6),
      timer: 0, tx: x, tz: z, colour: COLOURS[Math.floor(Math.random() * COLOURS.length)], ready: false, home: false,
    };
  }

  /** A field already in full swing: some on the runs, some riding up, a few in the queues. */
  private populate(f: Field, want: number): void {
    for (let k = 0; k < want; k++) {
      const i = Math.floor(Math.random() * f.lifts.length), t = f.lifts[i];
      const s = this.newSkier(f.door.x, f.door.z);
      s.lift = i;
      const roll = Math.random();
      if (roll < 0.4 && t.runs.length) {
        s.st = 'ski'; s.run = t.runs[Math.floor(Math.random() * t.runs.length)]; s.s = Math.random() * s.run.len * 0.9;
        along(s.run, s.s); s.x = tmp.x; s.z = tmp.z;
      } else if (roll < 0.8) {
        // a seat on a carrier on its way up
        const c = Math.floor(Math.random() * t.K);
        const u = (c * t.spacing + t.phase) % t.Lp;
        if (u < t.L - 1 && t.occ[c] < LIFT[t.l.kind].seats) {
          s.st = 'ride'; s.carrier = c; s.seat = t.occ[c]++; s.t0 = t.phase - u;
        } else this.toQueue(f, s, WALK);
      } else this.toQueue(f, s, WALK);
      f.skiers.push(s);
    }
  }

  /**
   * Send a skier to the back of a lift's queue: the shorter queue, more often than not; at the foot of a resort's
   * run, mostly the lift it comes down to (`at`).
   */
  private toQueue(f: Field, s: Skier, speed: number, at = -1): void {
    let i = Math.floor(Math.random() * f.lifts.length);
    if (Math.random() < 0.6) for (let k = 0; k < f.lifts.length; k++) if (f.lifts[k].queue.length < f.lifts[i].queue.length) i = k;
    if (at >= 0 && at < f.lifts.length && Math.random() < 0.85) { i = at; this.endQueued++; }
    s.lift = i;
    s.st = 'walk';
    s.speed = speed;
    const t = f.lifts[i];
    this.slot(t, t.queue.length + 1);
    s.tx = tmp.x; s.tz = tmp.z;
    s.timer = 0;
  }

  /** Place k in a lift's queue, into tmp: rows snaking back from where the chairs are boarded. */
  private slot(t: LiftRt, k: number): void {
    const bx = t.l.x0 + t.rx * t.r, bz = t.l.z0 + t.rz * t.r;
    const row = Math.floor(k / 6), col = k % 6;
    // beside the bull wheel rather than under the chairs coming round it
    const back = 0.25 + (row % 2 === 0 ? col : 5 - col) * 0.16, side = 0.15 + row * 0.17;
    tmp.x = bx - t.ux * back + t.rx * side;
    tmp.z = bz - t.uz * back + t.rz * side;
  }

  /** A carrier has come round to the boarding point: whoever is at the front and ready gets on. */
  private board(f: Field, i: number, n: number): void {
    const t = f.lifts[i];
    const c = ((-n % t.K) + t.K) % t.K;
    const seats = LIFT[t.l.kind].seats;
    const head = t.queue[0];
    if (!head || head.st !== 'queue') return;
    this.slot(t, 0);
    if (Math.hypot(head.x - tmp.x, head.z - tmp.z) > 0.12) return;
    // the one at the front lets a chair go by while they shuffle up to the line; on the next one they go
    if (!head.ready) { head.ready = true; return; }
    if (t.occ[c]) return;
    const party = t.l.kind === 'gondola' ? seats : Math.random() < 0.6 ? 2 : 1;
    let k = 0;
    while (k < party && t.queue.length) {
      const s = t.queue[0];
      this.slot(t, k);
      if (s.st !== 'queue' || (k > 0 && Math.hypot(s.x - tmp.x, s.z - tmp.z) > 0.5)) break;
      t.queue.shift();
      s.st = 'ride'; s.carrier = c; s.seat = k; s.t0 = n * t.spacing; s.ready = false;
      k++;
      this.boarded++;
    }
    t.occ[c] = k;
  }

  /** One skier's step; true once they have gone home. */
  private move(f: Field, s: Skier, dt: number, open: boolean): boolean {
    const t = f.lifts[s.lift];
    switch (s.st) {
      case 'walk': {
        if (this.walkTo(s, s.tx, s.tz, s.speed * dt)) {
          if (s.home) { s.st = 'lodge'; s.timer = rand(12, 40); break; }
          if (!open) { this.goHome(f, s); break; }
          s.st = 'queue';
          s.ready = false;
          t.queue.push(s);
        }
        break;
      }
      case 'queue': {
        if (!open && t.queue[0] !== s) {
          // the lifts are closing: the queue breaks up and heads for the lodge
          const q = t.queue.indexOf(s);
          if (q >= 0) t.queue.splice(q, 1);
          this.goHome(f, s);
          break;
        }
        const q = t.queue.indexOf(s);
        this.slot(t, Math.max(0, q));
        this.walkTo(s, tmp.x, tmp.z, WALK * dt);
        break;
      }
      case 'ride': {
        const u = t.phase - s.t0;
        if (u >= t.L) {
          // off at the top, and out to where the run starts
          t.occ[s.carrier] = Math.max(0, t.occ[s.carrier] - 1);
          s.x = t.l.x1 + t.rx * (t.r + 0.35) + t.ux * 0.3; s.z = t.l.z1 + t.rz * (t.r + 0.35) + t.uz * 0.3;
          s.st = 'off';
          s.run = t.runs.length ? t.runs[Math.floor(Math.random() * t.runs.length)] : null;
          if (s.run) { s.tx = s.run.pts[0] + rand(-0.5, 0.5); s.tz = s.run.pts[1] + rand(-0.5, 0.5); } else { s.tx = s.x; s.tz = s.z; }
          s.timer = rand(0.5, 3);
        }
        break;
      }
      case 'off': {
        // a moment at the top to get the skis on, then across to the start of the run
        s.timer -= dt;
        if (s.timer > 0) break;
        if (this.walkTo(s, s.tx, s.tz, SKATE * dt)) {
          if (!s.run) { this.goHome(f, s); break; }
          s.st = 'ski'; s.s = 0;
          s.speed = rand(1.4, 2.6); s.amp = rand(0.5, 1.4); s.lam = rand(2.6, 5); s.ph = rand(0, 6.3); s.bias = rand(-0.6, 0.6);
        }
        break;
      }
      case 'ski': {
        const r = s.run!;
        // easing in off the top, carving down, and slowing into the bottom
        const ease = Math.min(1, 0.35 + s.s / 3) * Math.max(0.35, Math.min(1, (r.len - s.s) / 4));
        s.s += s.speed * ease * dt;
        if (s.s >= r.len) {
          s.s = r.len;
          this.runsDone++;
          if (!open) { this.goHome(f, s); break; }
          if (Math.random() < 0.12) { this.goHome(f, s); break; }
          this.toQueue(f, s, SKATE, r.end);
          break;
        }
        along(r, s.s);
        const taper = Math.min(1, s.s / 2.5, (r.len - s.s) / 2.5);
        const off = (s.bias + s.amp * Math.sin((s.s / s.lam) * Math.PI * 2 + s.ph)) * taper;
        s.x = tmp.x - tmp.dz * off;
        s.z = tmp.z + tmp.dx * off;
        break;
      }
      case 'lodge': {
        // inside for a hot chocolate, then out again (or home for the day)
        s.timer -= dt;
        if (s.timer <= 0) {
          if (!open) return true;
          s.home = false;
          s.x = f.door.x; s.z = f.door.z;
          this.toQueue(f, s, WALK);
        }
        break;
      }
    }
    if (s.st !== 'ride' && s.st !== 'lodge') s.y = groundY(f, s.x, s.z) + RADIUS;
    return false;
  }

  private goHome(f: Field, s: Skier): void {
    s.home = true;
    s.st = 'walk';
    s.speed = WALK;
    s.tx = f.door.x + rand(-0.4, 0.4); s.tz = f.door.z;
  }

  private walkTo(s: Skier, x: number, z: number, step: number): boolean {
    const dx = x - s.x, dz = z - s.z, d = Math.hypot(dx, dz);
    if (d <= step) { s.x = x; s.z = z; return true; }
    s.x += (dx / d) * step; s.z += (dz / d) * step;
    return false;
  }

  /** Write a field's carriers and skiers into the instance buffers. */
  private draw(f: Field): void {
    const m = this.m, ox = f.w.ox, oz = f.w.oz, e = m.elements;
    for (const t of f.lifts) {
      const gondola = t.l.kind === 'gondola';
      const body = gondola ? this.cabin : this.chair;
      const cap = gondola ? CAP_CABIN : CAP_CHAIR;
      const hang = gondola ? CABIN_HANG : SEAT_DROP;
      for (let c = 0; c < t.K; c++) {
        const n = gondola ? this.nCabin : this.nChair;
        if (n >= cap || this.nHanger >= CAP_CHAIR + CAP_CABIN) break;
        const u = (c * t.spacing + t.phase) % t.Lp;
        carrierAt(t, u);
        const x = ox + tmp.x, z = oz + tmp.z;
        m.makeScale(1, hang, 1);
        e[12] = x; e[13] = tmp.y; e[14] = z;
        this.hanger.setMatrixAt(this.nHanger, m);
        this.hanger.setColorAt(this.nHanger++, this.c.setHex(0x6d7176));
        m.makeRotationY(Math.atan2(tmp.dx, tmp.dz));
        e[12] = x; e[13] = tmp.y - hang; e[14] = z;
        body.setMatrixAt(n, m);
        body.setColorAt(n, this.c.setHex(t.paint));
        if (gondola) this.nCabin++; else this.nChair++;
      }
    }
    for (const s of f.skiers) {
      if (s.st === 'lodge' || this.nSkier >= CAP_SKIER) continue;
      let x = s.x, y = s.y, z = s.z;
      if (s.st === 'ride') {
        const t = f.lifts[s.lift];
        const gondola = t.l.kind === 'gondola';
        carrierAt(t, Math.max(0, Math.min(t.L, t.phase - s.t0)));
        const fx = tmp.dx, fz = tmp.dz, rx = fz, rz = -fx;
        let lat: number, fwd = 0;
        if (gondola) { lat = (s.seat % 2 ? 0.075 : -0.075); fwd = s.seat < 2 ? 0.075 : -0.075; y = tmp.y - CABIN_HANG - CABIN_FLOOR + 0.012 + RADIUS; }
        else { lat = s.seat ? 0.068 : -0.068; y = tmp.y - SEAT_DROP + RADIUS * 0.9; }
        x = tmp.x + rx * lat + fx * fwd; z = tmp.z + rz * lat + fz * fwd;
      }
      m.makeTranslation(ox + x, y, oz + z);
      this.skier.setMatrixAt(this.nSkier, m);
      this.skier.setColorAt(this.nSkier++, this.c.setHex(s.colour));
    }
  }
}

function box(w: number, h: number, d: number, x: number, y: number, z: number): THREE.BufferGeometry {
  return new THREE.BoxGeometry(w, h, d).translate(x, y, z);
}

/** Geometries merged into one (positions and normals; no colours, the instance colour paints the lot). */
function merge(parts: THREE.BufferGeometry[]): THREE.BufferGeometry {
  const pos: number[] = [], nor: number[] = [];
  for (const g of parts) {
    const ng = g.index ? g.toNonIndexed() : g;
    pos.push(...(ng.getAttribute('position').array as Float32Array));
    nor.push(...(ng.getAttribute('normal').array as Float32Array));
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  out.setAttribute('normal', new THREE.Float32BufferAttribute(nor, 3));
  return out;
}

