import { hex, scale, type RGB } from '../../world/biomes';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, TAU, type Kit, type P3 } from './kit';
import { eastRoof } from './regions/terraces';

/**
 * The pieces an onsen town's models share (render/buildings/onsen.ts, onsenB.ts, render/onsenDress.ts): steam that
 * rises, swells and thins away, the hip-and-gable kawara roof, gas lamps, noren, a name board, yukata-clad figures,
 * bathers up to their shoulders, and the weeping willow of Kinosaki's canal.
 */

export const TIMBER = hex(0x4a3428), TIMBER_OLD = hex(0x5e4330), TIMBER_DARK = hex(0x33241c), PLASTER = hex(0xf2eee4);
export const KAWARA = hex(0x4a4e54), KAWARA_DARK = hex(0x3a3e44), STONE = hex(0xb8b4a8), STONE_DARK = hex(0x8e8a80);
export const PAPER = hex(0xf4ecd8), PAPER_GLOW = hex(0xffdca6), VERMILION = hex(0xd2452e), HOT = hex(0x7fd2c4);
export const HOT_DEEP = hex(0x4fb8b0), SULPHUR = hex(0xe8d870), STEAM = hex(0xf6f7f7), STEAM2 = hex(0xe4e8ea);
export const INDIGO = hex(0x2f3f6a), GLASS = hex(0x9fb8c0), ROCK = hex(0x7a746a), MOSS = hex(0x5f8a4a), GRAVEL = hex(0xd8d2c0);
export const LAMP_GLOW = hex(0xffd88a);
/** Paper screens and rooms: lit through the evening, a few late. */
export const ROOMS: Sched = [17.4, 23.4, 1.4];
export const LATE: Sched = [18.2, 25.5, 1.3];
/** Lanterns and lamps: dusk to the small hours. */
export const LAMPS: Sched = [17.2, 29.5, 1.5];

/**
 * Steam rising off hot water at (x, y, z): `n` puffs, each its own part, rising `rise` while it swells and then
 * thins away to nothing, one after another so the plume never stops; `s` scales them. Drifts a little with the wind.
 */
export function steam(k: Kit, x: number, y: number, z: number, s = 1, n = 3, rise = 0.7, seed = 0): void {
  const parts: ((sk: Kit) => void)[] = [];
  for (let i = 0; i < n; i++) {
    parts.push((sk) => {
      sk.dome(0, -0.05 * s, 0, 0.17 * s, i % 2 ? STEAM2 : STEAM, 9, 4);
      sk.dome(0.08 * s, 0.0, 0.05 * s, 0.12 * s, STEAM, 8, 3);
      sk.dome(-0.07 * s, 0.02 * s, -0.04 * s, 0.11 * s, STEAM2, 8, 3);
      sk.dome(0.01 * s, 0.07 * s, -0.02 * s, 0.1 * s, STEAM, 8, 3);
    });
  }
  let t = (seed % 97) * 0.37;
  const speed = 0.16 + (seed % 7) * 0.012;
  k.rig(x, y, z, parts, (ps, dt) => {
    t += dt;
    for (let i = 0; i < ps.length; i++) {
      const ph = (t * speed + i / ps.length) % 1, o = ps[i];
      o.position.set(ph * 0.12 * s + Math.sin(t * 0.7 + i) * 0.02 * s, ph * rise * s, ph * 0.05 * s);
      const g = Math.sin(Math.PI * Math.min(1, ph * 1.15)) * (0.55 + ph * 0.9);
      o.scale.setScalar(Math.max(0.001, g));
      o.visible = g > 0.02;
    }
  });
}

/**
 * A hip-and-gable (irimoya) roof of grey kawara over a w × d outline whose eaves are at y: the hipped skirt turning up
 * at the corners, a gable standing out of its top at each end of the ridge. Returns the ridge's height.
 */
export function irimoya(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, col: RGB = KAWARA, lift = 0.06): number {
  const top = eastRoof(k, x, y, z, w, d, h * 0.62, col, lift);
  const along = w >= d, gw = along ? w * 0.56 : d * 0.56, gd = along ? d * 0.42 : w * 0.42;
  k.gable(x, top - h * 0.18, z, along ? gw : gd, h * 0.5, along ? gd : gw, col, scale(TIMBER, 0.9), !along);
  return top + h * 0.32;
}

/** A gas lamp on an iron post (Ginzan's): a square glass lantern under a little cap, lit after dark. */
export function gasLamp(k: Kit, x: number, y: number, z: number, h = 0.34): void {
  const iron = hex(0x2a2a2c);
  k.box(x, y, z, 0.04, 0.03, 0.04, iron);
  k.cyl(x, y, z, 0.011, h, iron, 5);
  k.glowBox(x, y + h, z, 0.055, 0.07, 0.055, hex(0xe8e0c8), LAMPS, LAMP_GLOW);
  k.hip(x, y + h + 0.07, z, 0.075, 0.03, 0.075, iron);
  k.box(x, y + h + 0.1, z, 0.012, 0.025, 0.012, iron);
}

/** A noren: a cloth curtain in strips across a doorway of width w at (x, y) on the face at z, hanging h down. */
export function noren(k: Kit, x: number, y: number, z: number, w: number, h: number, col: RGB, mark?: string): void {
  const n = w > 0.3 ? 3 : 2, sw = w / n;
  k.box(x, y - 0.012, z, w + 0.04, 0.012, 0.012, TIMBER_DARK);
  for (let i = 0; i < n; i++) k.box(x - w / 2 + sw * (i + 0.5), y - h, z + 0.008, sw - 0.012, h - 0.012, 0.006, col);
  if (mark) {
    const g = Math.min(w * 0.5, h * 0.7);
    k.glyph(mark, [x - g / 2, y - h / 2 - g / 2, z + 0.013], [x + g / 2, y - h / 2 - g / 2, z + 0.013], [x + g / 2, y - h / 2 + g / 2, z + 0.013], [x - g / 2, y - h / 2 + g / 2, z + 0.013]);
  }
}

/** A tall wooden name board standing out of a front at (x, y0) on the face at z, its name read downward in white. */
export function kanban(k: Kit, x: number, y0: number, z: number, word: string, cell = 0.09, board: RGB = TIMBER_DARK): void {
  const chars = [...word], h = chars.length * cell + cell * 0.4, w = cell * 1.25;
  k.box(x, y0, z, w, h, 0.03, board);
  k.box(x, y0 + h, z, w + 0.02, 0.015, 0.04, scale(board, 0.7));
  chars.forEach((ch, i) => {
    const top = y0 + h - cell * 0.2 - i * cell, g = cell * 0.82;
    k.glyph(ch, [x - g / 2, top - g, z + 0.017], [x + g / 2, top - g, z + 0.017], [x + g / 2, top, z + 0.017], [x - g / 2, top, z + 0.017]);
  });
}

/** A board lying across a front (its name read across), on the face at z. */
export function signboard(k: Kit, x: number, y: number, z: number, word: string, cell = 0.08, board: RGB = TIMBER_DARK): void {
  const chars = [...word], w = chars.length * cell + cell * 0.5, h = cell * 1.3;
  k.box(x, y, z, w, h, 0.025, board);
  chars.forEach((ch, i) => {
    const cx = x - w / 2 + cell * 0.25 + cell * (i + 0.5), g = cell * 0.84, cy = y + h / 2;
    k.glyph(ch, [cx - g / 2, cy - g / 2, z + 0.014], [cx + g / 2, cy - g / 2, z + 0.014], [cx + g / 2, cy + g / 2, z + 0.014], [cx - g / 2, cy + g / 2, z + 0.014]);
  });
}

/** Yukata patterns: indigo, white, a blue check, a rose, a grey. */
const YUKATA = [0x2f3f6a, 0xe8e4dc, 0x5a7ab0, 0xc86a7a, 0x8a8a90, 0x3a5a7a];

/** A guest strolling in a yukata, standing at (x, y, z), a towel over the shoulder now and then. */
export function yukata(k: Kit, r: Rng, x: number, y: number, z: number): void {
  const robe = hex(YUKATA[Math.floor(r() * YUKATA.length)]);
  k.box(x, y, z, 0.034, 0.012, 0.024, hex(0x6a4a30));
  k.box(x, y + 0.012, z, 0.04, 0.085, 0.03, robe);
  k.box(x, y + 0.06, z, 0.042, 0.012, 0.032, hex(0x2a2a3a));
  k.box(x, y + 0.097, z, 0.026, 0.026, 0.026, hex(0xe0b890));
  k.box(x, y + 0.12, z, 0.028, 0.01, 0.028, hex(0x2a2220));
  if (r() < 0.35) k.box(x + 0.022, y + 0.06, z, 0.008, 0.04, 0.02, hex(0xf4f2ec));
}

/** A guest sitting on the edge with feet in the water (a foot bath): the robe folded to the knee. */
export function sitter(k: Kit, r: Rng, x: number, y: number, z: number, facing: 1 | -1): void {
  const robe = hex(YUKATA[Math.floor(r() * YUKATA.length)]);
  k.box(x, y, z, 0.04, 0.035, 0.035, robe);
  k.box(x, y - 0.045, z + facing * 0.028, 0.03, 0.05, 0.018, hex(0xe0b890));
  k.box(x, y + 0.035, z - facing * 0.004, 0.038, 0.05, 0.026, robe);
  k.box(x, y + 0.085, z, 0.024, 0.024, 0.024, hex(0xe0b890));
  k.box(x, y + 0.108, z, 0.026, 0.01, 0.026, hex(0x2a2220));
}

/** A bather up to the shoulders in the water at y: a head and a pair of shoulders, now and then a folded towel on top. */
export function bather(k: Kit, r: Rng, x: number, y: number, z: number): void {
  k.box(x, y - 0.01, z, 0.04, 0.025, 0.026, hex(0xe0b890));
  k.box(x, y + 0.015, z, 0.024, 0.026, 0.024, hex(0xe0b890));
  k.box(x, y + 0.04, z, 0.026, 0.01, 0.026, r() < 0.4 ? hex(0xf4f2ec) : hex(0x2a2220));
}

/** A ring of rocks round a pool, the pool's water at y (a rotenburo's edge). */
export function rockRim(k: Kit, r: Rng, x: number, y: number, z: number, rx: number, rz: number, n = 12): void {
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU + r() * 0.2, s = 0.06 + r() * 0.05;
    k.box(x + Math.cos(a) * rx, y - 0.04, z + Math.sin(a) * rz, s * 1.4, 0.05 + r() * 0.05, s, i % 3 ? ROCK : STONE_DARK);
  }
}

/** A weeping willow at (x, y, z): a short leaning trunk and long green fronds hanging down all round. */
export function willow(k: Kit, x: number, y: number, z: number, s = 1, lean = 0): void {
  const leaf = hex(0x8ab85a), leaf2 = hex(0x9cc868), bark = hex(0x6a5a44);
  const top: P3 = [x + lean * 0.06 * s, y + 0.4 * s, z];
  k.bar([x, y, z], top, 0.022 * s, bark);
  k.dome(top[0], top[1] - 0.03 * s, top[2], 0.2 * s, leaf, 8, 2);
  // the fronds: thin strands from the crown's rim, falling outward almost to the ground
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU + (i % 2) * 0.2, ca = Math.cos(a), sa = Math.sin(a);
    k.bar([top[0] + ca * 0.16 * s, top[1] - 0.02 * s, top[2] + sa * 0.16 * s], [top[0] + ca * 0.24 * s, y + 0.07 * s, top[2] + sa * 0.24 * s], 0.026 * s, i % 2 ? leaf : leaf2);
  }
}

/** A row of hanging red-and-white festival lanterns along a line at height y (a ryokan's eaves, a lane). */
function lanternRow(k: Kit, a: P3, b: P3, n: number, r: Rng): void {
  for (let i = 0; i < n; i++) {
    const t = (i + 0.5) / n, x = a[0] + (b[0] - a[0]) * t, y = a[1] + (b[1] - a[1]) * t - 0.01, z = a[2] + (b[2] - a[2]) * t;
    const col = r() < 0.7 ? hex(0xd8402e) : hex(0xf2ead8);
    k.glowBox(x, y - 0.05, z, 0.04, 0.05, 0.04, col, LAMPS, scale(col, 1.3));
  }
  k.bar(a, b, 0.004, DARK);
}
