/**
 * The words on a mission card, and the rules they are held to (docs/missions.html, Rules).
 *
 * A card is read in five seconds or not at all: a title of four words or fewer, one line of why, at most
 * four objectives of 28 characters each, and the whole thing under thirty words not counting numbers.
 * Everything here builds text out of slots — an icon, a cargo's name, a place's short name — and never
 * glues a sentence out of notes, which is what made the old cards read "bread to the grocery · Bread ·
 * Bakery · Millbrook → Grocery · Millbrook". `lint` is what `npm run missions` holds every card to.
 */
import { SITE_LABEL } from '../cargoTypes';
import { cargoById } from '../cargoTypes';
import type { Mission, Obj, Reward } from './model';
import { money } from '../cargoHud';
import { speedText } from '../units';


export const LIMITS = { titleChars: 22, titleWords: 4, whyChars: 130, objChars: 28, objs: 4, words: 52, details: 500 };
/**
 * The one card allowed to run long (the user, 1 Nov 2026): the first drive's A Helping Hand, which has to carry
 * the fleet idea in its giver's own words. Its why, details and word count are held to these instead.
 */
export const LONG_LIMITS = { ...LIMITS, whyChars: 320, words: 120, details: 900 };
export const LONG_TPLS = new Set(['first:hand']);
export const limitsOf = (tpl: string): typeof LIMITS => (LONG_TPLS.has(tpl) ? LONG_LIMITS : LIMITS);

/** The verbs an objective may start with. The arrow form ("🍞 Bread → Grocery") needs none. */
export const VERBS = ['Deliver', 'Bring', 'Upgrade', 'Reach', 'Visit', 'Cross', 'Ferry', 'Race', 'Tow', 'Fit', 'Own', 'Meet', 'Arrive', 'Take', 'Buy', 'Keep', 'Haul', 'Hitch', 'Win', 'Stamp', 'Run', 'Drift', 'Find', 'Light', 'Follow', 'Film', 'Guide', 'Spot', 'Tag', 'Cover', 'Search', 'Land', 'Fly', 'Hire', 'Tail', 'Shadow', 'Trail', 'Lead', 'Dive', 'Build', 'Unlock', 'Ask', 'Collect', 'Sell', 'Knock', 'Dust', 'Level'];

/** A site's short name: its kind in a word or two, never its town (the header names the town once). */
export function shortSite(kind: string, port = false, major = false): string {
  if (port) return major ? 'Harbour' : 'Dock';
  const l = SITE_LABEL[kind as keyof typeof SITE_LABEL];
  if (l) return l;
  const s = String(kind).replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return s[0].toUpperCase() + s.slice(1);
}

/**
 * The vehicle a mission can only be done in, for the tag on its offer card ("Required: Ambulance"), or null
 * when anything will do. Read off its objectives: a step that must be driven in certain models, a night op
 * (a helicopter), a race, lap or grid slot (a road car), a tow (road vehicles with crews), and loads only a
 * helicopter, a jet or a boat takes. The cargo cuts' `veh` aren't requirements: they only steer what turns up.
 */
export function requiredOf(m: Mission): string | null {
  // "an ambulance" → "Ambulance"
  for (const o of m.objs) if ((o.t === 'reach' || o.t === 'ram' || o.t === 'deliver') && o.ride) { const l = o.ride.label.replace(/^(an?|the) /i, ''); return l.charAt(0).toUpperCase() + l.slice(1); }
  if (m.kind === 'op' || m.objs.some((o) => o.t === 'op')) return 'Helicopter';
  if (m.objs.some((o) => o.t === 'tail')) return 'Road car';
  const tow = m.objs.find((o) => o.t === 'tow');
  if (tow && tow.t === 'tow') return tow.min > 2 ? `Road vehicle + ${tow.min - 1} crewed road vehicles` : tow.min === 2 ? 'Road vehicle + 1 crewed road vehicle' : 'Road vehicle';
  if (m.objs.some((o) => o.t === 'race' || o.t === 'lap' || o.t === 'grid')) return 'Road car';
  for (const o of m.objs) {
    if (o.t !== 'deliver') continue;
    const type = cargoById(o.cargo);
    if (type?.heli) return 'Helicopter';
    if (type?.jet) return 'Jet';
    if (type?.sea) return 'Boat';
  }
  return null;
}

/** The bar across the top of an offer card: what kind of thing is being offered. */
export function offerLabel(m: Mission): string {
  if (m.tpl.startsWith('first:') || m.arc) return 'New Mission';
  switch (m.kind) {
    case 'race': return 'New Challenge';
    case 'tow': return 'Tow Job';
    case 'trip': return 'New Trip';
    case 'op': return 'Night Op';
    case 'tail': return 'Tail Job';
    default: return 'Job Offer';
  }
}

const SLOT_WORD: Record<string, string> = { nitrous: 'nitrous', handbrake: 'handbrake', engine: 'engine', gearbox: 'gearbox', tyres: 'tyres' };
const HAUL_WORD: Record<string, string> = { bell: 'church bell', boiler: 'boiler', propeller: 'propeller', statue: 'statue', yacht: 'yacht', wreck: 'wreck', loco: 'locomotive', dish: 'radio dish', sphere: 'pressure sphere' };
/** "on land", "on water", "in the air": the way a range step reads. */
export const KIND_IN: Record<'land' | 'water' | 'air', string> = { land: 'on land', water: 'on water', air: 'in the air' };
/** "21:00". */
const clock = (h: number): string => `${String(((h % 24) + 24) % 24).padStart(2, '0')}:00`;

/** How to do one objective, in a plain sentence: the long form of its 28-character label. */
function howTo(o: Obj): string {
  switch (o.t) {
    case 'deliver': {
      const type = cargoById(o.cargo);
      const what = type ? type.name.toLowerCase() : 'the goods';
      const how = `Pick up the ${what} at ${o.from.name.startsWith('the ') ? o.from.name : `the ${o.from.name.toLowerCase()}`} (stop in its ring, tap Space) and drop ${o.n > 1 ? `each load` : 'it'} at the ${o.to.name.replace(/^the /, '')}${o.n > 1 ? `, ${o.n} loads in all` : ''}.`;
      // the helping hand's second load: both lie at the roadside, and her hold takes the one yours can't
      if (o.also) {
        const other = cargoById(o.also.cargo)?.name.toLowerCase() ?? 'the other load';
        return `Stop by the goods at ${o.from.name} and tap Space: the ${what} fill your car. Once she has pulled in behind you her hold counts as yours, so tap Space again for the ${other}. At the ${o.to.name.replace(/^the /, '')}, stop in the ring and tap Space with her behind you: both come off together.`;
      }
      // a dash: the clock, and the siren
      if (o.with) return `${how} Bring ${o.with} of your vehicles in Follow mode (F): it is only set down with them all behind you.`;
      return o.clock ? `${how} The clock starts once they are aboard: ${o.clock} seconds. K sounds the siren, which clears the road and pays a fifth more.` : how;
    }
    case 'ram': return `Line up ${o.ride.label} on the ${o.b.name.toLowerCase()}, give it a run-up and hit a wall head on at ${speedText(o.kmh)} or faster: it comes down. A glancing blow won't do.`;
    case 'loads': return `Deliver any ${o.n} loads that start or end in ${plainTown(o.town.name)}.`;
    case 'reach': return o.door ? `Drive to ${o.at.name}, stop in the ring at its door and press Space.`
      : o.hidden ? `Nobody will show you where. Work it out from the clue; within ${o.hidden} tiles a ring shows on the ground, and you stop in it.`
      : o.with || o.hold || o.after !== undefined
        ? `${o.with ? `Put ${o.with} of your vehicles in Follow mode (F) and lead them to` : 'Drive to'} ${o.at.name}${o.after !== undefined && o.before !== undefined ? ` between ${clock(o.after)} and ${clock(o.before)}` : ''}${o.hold ? `, stop in the ring and wait ${o.hold} seconds` : ', and stop in the ring'}.`
      : `${o.ride ? `Come in ${o.ride.label}: ` : ''}drive to ${o.at.name} and ${o.stop ? 'stop in the ring' : 'pull up close'}.`;
    case 'visit': return o.at ? `Get to ${o.at.name}; the Passport stamps it as you arrive.` : 'Go somewhere you have never been.';
    case 'ferry': return 'Stop on a harbour slip and press Tab to board the car ferry.';
    case 'race': return `Stop on the start line, press Enter, and beat your rival to ${o.to.name}. Off-road shortcuts are allowed.`;
    case 'crew': return `Bring ${o.n} vehicles with drivers to the load; hired drivers answer the call.`;
    case 'tow': return `Stop by the ${HAUL_WORD[o.load] ?? 'load'}, press Enter to hitch it, and drag it to the ${o.to.name.replace(/^the /, '')} with at least ${o.min} vehicles on the ropes.`;
    case 'own': return `Own ${o.n} vehicles: buy them at a Vehicle Dealer's door (stop in its ring, Space).`;
    case 'make': return o.what === 'road' ? `Lay ${o.n} tiles of road with the builder: B opens it, a click starts a road and a second click builds it.`
      : o.what === 'unlock' ? `Unlock ${o.n > 1 ? `${o.n} vehicles` : 'a vehicle'} on a tech tree with diamonds: H, then the Tech tab, pick a lit vehicle and press Unlock.`
      : o.what === 'bridge' ? 'Bridge the water with a road: B opens the builder; start on one bank and end on the other, and the bridge goes in by itself. V lets it reach twice as far.'
      : o.what === 'level' ? 'Level the ground in the ring with the terrain tool: T picks it up, Shift-drag levels everything under the brush, 1–7 sizes it, Z undoes.'
      : o.what === 'rail' ? `Lay ${o.n} tiles of track: B opens the builder, pick the Rails side, click to start a track and click again where it ends.`
      : o.what === 'railParallel' ? 'Lay a track beside a line: on the builder’s Rails side, start a few tiles off an existing line and hold Shift while you pick the end.'
      : `Ask a town you hold for a building: B, then pick the Buildings side, choose one and set its ghost down on a free lot in town.`;
    case 'hq': return 'Buy a building as your HQ: press H and pick one under "Where to buy one", or click any house or shop for its card. Drive within 40 tiles of it, then press "Buy as your HQ".';
    case 'driving': return `Hire a road driver (H → Fleet → Hire…) and drag them onto a parked vehicle’s seat: they set off to work at once.`;
    case 'fit': return `Fit ${o.slot ? `any ${SLOT_WORD[o.slot] ?? o.slot} upgrade` : 'any upgrade'} at a Vehicle Shop: stop in its ring and press Space.`;
    case 'speed': return `Reach ${speedText(o.kmh)}. Hold W on a long straight road, then press Shift to fire the nitrous.`;
    case 'op': return OP_HOW[o.op](o.what ?? '');
    case 'drift': return `Take a ${o.dir}-hand corner at speed holding ${o.dir === 'left' ? 'A' : 'D'}, and hold Space for the handbrake to swing the tail round.`;
    case 'lap': return `Drive in at ${o.at.name}'s gate onto the track and cross the chequered line to start the clock. A lap counts driven the right way, all the way round, on the track.`;
    case 'grid': return `Drive to ${o.at.name}, stop on the yellow ring on the grid and wait for the five red lights to go out. Three laps; cutting across the infield doesn't count.`;
    case 'range': return `Get ${o.tiles.toLocaleString('en-US')} tiles from home${o.mname ? ` in your ${o.mname}` : o.kind ? ` ${KIND_IN[o.kind]}` : ''} in one drive out. Home is the pin on the map (M).`;
    case 'discover': return `Set foot in ${o.n} cells your fleet has never been in. Each pays its New ground as well.`;
    case 'tail': return o.train
      ? `Wait at ${o.at.name} for the freight, then follow it from the roads beside the line until it stops at a yard. Keep out of the guard's sight at the back and don't ride level with it for long; it won't wait for you.`
      : `Find ${o.car.name} at ${o.at.name} and follow it, unseen. Its mirror fills the meter, faster the closer you are; the horn makes you stand out, and after dark N switches your lights off. Fall too far back and it's gone.`;
  }
}

/** How each night op is done, for "More details". The searchlight is N; the mouse aims it. */
const OP_HOW: Record<string, (what: string) => string> = {
  search: (w) => `Fly over the search area after dark and sweep it with the searchlight (N, aimed with the mouse). Hold the beam on the ${w || 'lost walker'} to find them${w === 'dog' ? '.' : ', land beside them, then fly them to a hospital pad.'}`,
  overboard: () => 'Sweep the water with the searchlight until the beam finds the swimmer, then keep it on them: the lifeboat steers for your light.',
  pursuit: () => 'Meet the patrol after dark, then keep the fleeing car in your searchlight while the police chase it. Lose it for eight seconds and it gets away.',
  sweep: () => 'Search the streets with the searchlight for a stolen car parked with its lights off. Once the beam finds it, it bolts: keep it lit for the chase.',
  live: () => 'Hold the searchlight on the story for a minute of live news. Keep the beam steady and on the scene to keep the ratings up.',
  shoot: () => 'Press Enter over the start to call Action, then light the stunt car: follow it, have the beam on the mark as it passes, and switch the light off and back on for the reveal.',
  blackout: () => 'The town has lost its power. The ambulance only drives at speed where your searchlight lights the road just ahead of it.',
  livestock: () => 'Light each stray with the searchlight: the rancher drives to the one in your beam, and drivers slow for a lit animal.',
  drops: () => 'Sweep the area with the searchlight for smugglers’ lanterns. Hold the beam on each contact to tag it for the police.',
};

/**
 * "More details" on the card: the mission's own story, then how to do each step, what it pays and how
 * long there is, held to LIMITS.details characters.
 */
export function detailsOf(m: Mission): string {
  const parts: string[] = [];
  if (m.details) parts.push(m.details);
  const steps = m.objs.map((o, k) => `${m.objs.length > 1 ? `${k + 1}. ` : ''}${howTo(o)}`);
  parts.push(...steps);
  const pay = m.reward.filter((r) => r.r !== 'crew').map((r) => rewardChip(r).text).join(', ');
  if (pay) parts.push(`Reward: ${pay}.`);
  if (m.notes?.by !== undefined) parts.push(`It must be there by ${dayClock(m.notes.by)}.`);
  else if (m.due !== null) parts.push(`You have ${Math.round(m.due - m.posted)} game hours once you accept.`);
  let s = parts.join(' ');
  const max = limitsOf(m.tpl).details;
  if (s.length > max) s = `${s.slice(0, max - 1).replace(/\s+\S*$/, '')}…`;
  return s;
}

/** A game hour as a day and a clock: "day 3, 20:00" (an act's show or a kick-off, missions/actTemplates.ts). */
export function dayClock(h: number): string {
  const t = ((h % 24) + 24) % 24, hh = Math.floor(t), mm = Math.floor((t - hh) * 60);
  return `day ${Math.floor(h / 24) + 1}, ${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
}

/** A town's plain name, without "City". */
export const plainTown = (name: string): string => name.replace(/ City$/, '');

/** Tiles as the card reads them: "12 t". */
export const tiles = (n: number): string => `${Math.max(1, Math.round(n))} t`;

/** A reward as a chip: its text, and whether it is the big one. */
export function rewardChip(r: Reward): { text: string; big: boolean; icon: string } {
  switch (r.r) {
    case 'cash': return { text: money(r.n), big: false, icon: '💵' };
    case 'gems': return { text: `${r.n} diamonds`, big: true, icon: '◆' };
    case 'part': return { text: `${r.slot === 'nitrous' ? 'Nitrous' : r.slot[0].toUpperCase() + r.slot.slice(1)} T${r.tier}${r.all ? ' on all' : ''}`, big: true, icon: '🔧' };
    case 'vehicle': return { text: r.name ?? r.model, big: true, icon: '🚗' };
    case 'building': return { text: `${r.at.name} deed`, big: true, icon: '🏠' };
    case 'standing': return { text: `${plainTown(r.town.name)} talks you up`, big: false, icon: '🤝' };
    case 'effect': return { text: r.line, big: false, icon: '🏘️' };
    case 'driver': return { text: 'A driver', big: true, icon: '🧑‍✈️' };
    case 'crew': return { text: `${r.name.split(' ')[0]} stays on`, big: true, icon: '🧑‍✈️' };
    case 'livery': return { text: `${r.name} paint`, big: false, icon: '🎨' };
    case 'clue': return { text: 'A tip', big: true, icon: '🗝️' };
    case 'reveal': return { text: REVEAL_WORD[r.what], big: true, icon: r.what === 'depot' ? '🚩' : r.what === 'stash' ? '🗝️' : r.what === 'contact' ? '🌙' : '📍' };
  }
}

/** What a tail turns up, as its chip. */
const REVEAL_WORD: Record<'depot' | 'stash' | 'contact' | 'hideout', string> = { depot: 'Their depot', stash: 'A hidden ride', contact: 'A night contact', hideout: 'The hideout' };

const words = (s: string): number => s.replace(/[\d$,.%→+#]+/g, ' ').split(/\s+/).filter((w) => /[a-z]/i.test(w)).length;

/** Everything wrong with a card's words, or an empty list. */
export function lint(m: Mission): string[] {
  const out: string[] = [];
  const L = limitsOf(m.tpl);
  if (m.title.length > L.titleChars) out.push(`title "${m.title}" is ${m.title.length} chars (max ${L.titleChars})`);
  if (m.title.split(/\s+/).length > L.titleWords) out.push(`title "${m.title}" is more than ${L.titleWords} words`);
  if (m.why.length > L.whyChars) out.push(`why "${m.why}" is ${m.why.length} chars (max ${L.whyChars})`);
  if (m.objs.length > L.objs) out.push(`${m.objs.length} objectives (max ${L.objs})`);
  for (const o of m.objs) {
    if (o.label.length > L.objChars) out.push(`objective "${o.label}" is ${o.label.length} chars (max ${L.objChars})`);
    const first = o.label.split(/\s+/)[0];
    if (!o.label.includes('→') && !VERBS.includes(first)) out.push(`objective "${o.label}" starts with "${first}", not a verb`);
  }
  for (const s of [m.title, m.why, ...m.objs.map((o) => o.label)]) {
    if (/[()·]/.test(s)) out.push(`"${s}" has brackets or a middle dot`);
  }
  const town = m.giver.town ? plainTown(m.giver.town.name) : '';
  if (town) {
    const all = [m.title, m.why, ...m.objs.map((o) => o.label)].join(' ');
    const n = all.split(town).length - 1;
    if (n > 1) out.push(`"${town}" appears ${n} times (the header names it)`);
  }
  const total = words(m.title) + words(m.why) + m.objs.reduce((s, o) => s + words(o.label), 0) + m.reward.reduce((s, r) => s + words(rewardChip(r).text), 0);
  if (total > L.words) out.push(`${total} words (max ${L.words})`);
  const more = [m.details ?? '', ...m.objs.map(howTo)].join(' ');
  if (more.length > L.details) out.push(`details run to ${more.length} chars (max ${L.details})`);
  return out;
}
