import { hex, scale, type RGB } from '../../../world/biomes';
import type { Rng } from '../../../world/rng';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, WARM_GLOW, flared, type Draw, type Kit, type P3 } from '../kit';

/**
 * Dragon Bay: a floating fishing village on its barrels, a junk at its mooring under ribbed red sails, a
 * slim pagoda, and the temple that clings to a karst pinnacle. Jade water, grey-green limestone, dark
 * timber, red and gold.
 */

const JADE = hex(0x3f9a84), JADE_DEEP = hex(0x2f7f6e);
const KARST = hex(0x7c8a76), KARST_LIGHT = hex(0x94a08a), KARST_DARK = hex(0x5c6a5a), MOSS = hex(0x4f8a3c), MOSS_DARK = hex(0x3c6e32);
const TIMBER = hex(0x5a3a24), TIMBER_DARK = hex(0x3e2a1c), DECK = hex(0x8e6e48), BARREL = hex(0x2f6fb5);
const SAIL = hex(0x9a3420), SAIL_DARK = hex(0x5e2016), TILE = hex(0x2c3034), RED = hex(0xb02a22), GOLD = hex(0xe0b040);
const STONE = hex(0xcfc8b8), TIN = hex(0x9aa0a0), CREAM = hex(0xeadfc6);
const LANTERN = hex(0xd8412f), LANTERN_GLOW = hex(0xff8a4a);
const EVENING: Sched = [18, 23.5, 1.4], LAMPS: Sched = [17.5, 30.5, 1.4];

/** A paper lantern: a small red box that glows all night. */
function lantern(k: Kit, x: number, y: number, z: number, s = 0.05): void {
  k.glowBox(x, y, z, s, s * 1.2, s, LANTERN, LAMPS, LANTERN_GLOW);
}

/** A little open boat lying along x. */
function sampan(k: Kit, x: number, z: number, col: RGB): void {
  k.box(x, 0.03, z, 0.32, 0.05, 0.11, col, scale(col, 0.6));
  k.box(x + 0.19, 0.04, z, 0.08, 0.055, 0.07, col);
  k.box(x - 0.19, 0.04, z, 0.08, 0.055, 0.07, col);
}

// ---- the floating village (3 × 3) ---------------------------------------------------------------------

/** A floating fishing village: timber rafts on blue barrels, tiny tin-roofed houses, fish pens, boats, washing. */
const floatingVillage: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.16, 0.03, D - 0.16, JADE);
  // a raft: a deck on a fringe of barrels
  const raft = (x: number, z: number, w: number, d: number) => {
    k.box(x, 0.085, z, w, 0.035, d, DECK);
    const nx = Math.max(2, Math.round(w / 0.22)), nz = Math.max(2, Math.round(d / 0.22));
    for (let i = 0; i < nx; i++) for (const s of [-1, 1]) k.box(x - w / 2 + ((i + 0.5) * w) / nx, 0.03, z + s * (d / 2 - 0.03), 0.12, 0.055, 0.09, BARREL);
    for (let j = 1; j < nz - 1; j++) for (const s of [-1, 1]) k.box(x + s * (w / 2 - 0.03), 0.03, z - d / 2 + ((j + 0.5) * d) / nz, 0.09, 0.055, 0.12, BARREL);
  };
  const PAINT = [0x6fa8c8, 0x7fb89a, 0xe2c662, 0x5f93b8, 0x9ac4a0, 0xd9a860];
  const house = (x: number, z: number, w: number, d: number, alongZ: boolean) => {
    const col = hex(PAINT[Math.floor(r() * PAINT.length)]), h = 0.2 + r() * 0.05;
    k.box(x, 0.12, z, w, h, d, col);
    k.gable(x, 0.12 + h, z, w + 0.07, 0.1, d + 0.07, r() < 0.3 ? hex(0x9a5636) : TIN, col, alongZ);
    k.box(x - w * 0.2, 0.12, z + d / 2 + 0.006, 0.07, 0.14, 0.012, TIMBER_DARK);
    k.pane(x + w * 0.2, 0.2, z + d / 2, 0.08, 0.07, 1, DARK, EVENING, WARM_GLOW);
    lantern(k, x - w * 0.2, 0.27, z + d / 2 + 0.04, 0.04);
  };
  // the main raft along the back with three houses, a second one forward on the left with two, walkways between
  raft(-0.1, -hd + 0.75, 2.3, 0.95);
  house(-0.9, -hd + 0.62, 0.5, 0.42, false);
  house(-0.2, -hd + 0.66, 0.44, 0.46, true);
  house(0.55, -hd + 0.6, 0.55, 0.4, false);
  raft(-0.75, 0.35, 1.0, 0.8);
  house(-0.95, 0.28, 0.42, 0.4, true);
  house(-0.45, 0.32, 0.36, 0.36, false);
  k.box(-0.75, 0.085, -0.19, 0.2, 0.03, 0.34, TIMBER);
  k.box(-0.1, 0.085, -hd + 0.19, 0.24, 0.03, 0.22, TIMBER);
  // a washing line on the back raft
  const lx0 = 0.9, lx1 = 0.98, lz0 = -hd + 0.42, lz1 = -hd + 1.1;
  k.box(lx0, 0.12, lz0, 0.02, 0.28, 0.02, TIMBER_DARK);
  k.box(lx1, 0.12, lz1, 0.02, 0.28, 0.02, TIMBER_DARK);
  k.bar([lx0, 0.39, lz0], [lx1, 0.39, lz1], 0.005, DARK);
  const WASH = [0xf4f2ec, 0xd8412f, 0x2f7fb5, 0xf2c14e, 0xf4f2ec];
  for (let i = 0; i < 5; i++) {
    const f = (i + 0.7) / 6;
    k.box(lx0 + (lx1 - lx0) * f, 0.31, lz0 + (lz1 - lz0) * f, 0.012, 0.075, 0.07, hex(WASH[i]));
  }
  // fish pens: square timber frames on floats, the water darker inside them
  const pen = (x: number, z: number, s: number) => {
    k.box(x, 0.03, z, s, 0.006, s, JADE_DEEP);
    for (const a of [-1, 1]) {
      k.box(x, 0.035, z + a * s / 2, s + 0.05, 0.035, 0.05, TIMBER);
      k.box(x + a * s / 2, 0.035, z, 0.05, 0.035, s - 0.05, TIMBER);
      for (const c of [-1, 1]) k.box(x + a * s / 2, 0.03, z + c * s / 2, 0.09, 0.05, 0.09, BARREL);
    }
  };
  pen(0.35, 0.3, 0.5);
  pen(0.95, 0.3, 0.5);
  pen(0.65, 0.9, 0.5);
  // boats tied up alongside
  sampan(k, -0.6, hd - 0.35, TIMBER);
  sampan(k, hw - 0.4, -hd + 1.45, hex(0x3f7a8a));
  k.turned(Math.PI / 2, () => sampan(k, -0.95, -hw + 0.3, hex(0x8a5a3a)));
};

// ---- a moored junk (2 × 2) ----------------------------------------------------------------------------

/** A batten sail in the plane z, its head cut on the slant, ribbed with dark battens that fan a little. */
function battenSail(k: Kit, x: number, y: number, z: number, w: number, h: number): void {
  const x0 = x - w * 0.62, x1 = x + w * 0.38, lo = h * 0.72;
  const a: P3 = [x0, y + h * 0.06, z], b: P3 = [x1, y, z], c: P3 = [x1, y + lo, z], d: P3 = [x0, y + h, z];
  k.quad(a, b, c, d, SAIL, [x, y + h / 2, z - 1]);
  k.quad(a, b, c, d, scale(SAIL, 0.85), [x, y + h / 2, z + 1]);
  const n = Math.max(3, Math.round(h / 0.13));
  for (let i = 0; i <= n; i++) {
    const f = i / n;
    k.bar([x0 - 0.01, y + h * 0.06 + (h * 0.94) * f, z], [x1 + 0.01, y + lo * f, z], 0.009, SAIL_DARK);
  }
}

/** A wooden junk at a timber jetty: a high stern with a cabin, a raised bow, three ribbed red-brown sails. */
const junkMooring: Draw = (k, W, D) => {
  const hd = D / 2;
  k.box(0, 0, 0, W - 0.16, 0.03, D - 0.16, JADE);
  const bz = 0.3;
  // the hull: waist, a bow that lifts, a stern that stands high and square
  k.box(0, 0.03, bz, 1.0, 0.15, 0.38, TIMBER, DECK);
  k.box(0, 0.12, bz, 1.02, 0.025, 0.4, TIMBER_DARK, DECK);
  k.box(0.56, 0.03, bz, 0.2, 0.2, 0.34, TIMBER, DECK);
  k.box(0.7, 0.08, bz, 0.14, 0.19, 0.24, TIMBER, TIMBER_DARK);
  k.box(-0.6, 0.03, bz, 0.28, 0.3, 0.4, TIMBER, DECK);
  k.box(-0.74, 0.12, bz, 0.06, 0.3, 0.36, TIMBER_DARK);
  // the cabin under a curved roof, a lantern at its door
  k.box(-0.36, 0.18, bz, 0.26, 0.14, 0.3, hex(0x8a5a3a));
  k.box(-0.36, 0.32, bz, 0.32, 0.025, 0.36, TILE);
  k.pane(-0.23, 0.22, bz, 0.12, 0.07, 0, DARK, EVENING, WARM_GLOW);
  lantern(k, -0.2, 0.26, bz + 0.17, 0.045);
  lantern(k, 0.66, 0.29, bz, 0.045);
  // three masts and their sails
  for (const [mx, mh, sw] of [[0.36, 0.78, 0.4], [-0.02, 1.0, 0.5], [-0.6, 0.62, 0.3]] as const) {
    const y0 = mx < -0.5 ? 0.33 : 0.18;
    k.box(mx, y0 - 0.02, bz, 0.03, mh, 0.03, TIMBER_DARK);
    battenSail(k, mx, y0 + 0.08, bz + 0.025, sw, mh - 0.14);
  }
  // the jetty in from the back edge, on piles, and the mooring lines
  const jz0 = -hd + 0.08, jz1 = bz - 0.24;
  k.box(-0.15, 0.1, (jz0 + jz1) / 2, 0.26, 0.03, jz1 - jz0, DECK);
  for (let i = 0; i < 4; i++) for (const s of [-1, 1]) k.box(-0.15 + s * 0.12, 0.03, jz0 + 0.06 + (i * (jz1 - jz0 - 0.12)) / 3, 0.035, 0.13, 0.035, TIMBER_DARK);
  k.box(0.3, 0.1, jz1 - 0.1, 0.7, 0.03, 0.2, DECK);
  for (const px of [0.1, 0.6]) k.box(px, 0.03, jz1 - 0.02, 0.035, 0.16, 0.035, TIMBER_DARK);
  k.bar([0.6, 0.18, jz1 - 0.02], [0.56, 0.22, bz - 0.17], 0.006, CREAM);
  k.bar([0.1, 0.18, jz1 - 0.02], [-0.5, 0.3, bz - 0.2], 0.006, CREAM);
  for (let i = 0; i < 3; i++) k.cyl(-0.15 + (i - 1) * 0.07, 0.13, jz0 + 0.3 + (i % 2) * 0.1, 0.035, 0.06, i === 1 ? BARREL : hex(0x8d6d48), 6);
};

// ---- the pagoda (1 × 1) -------------------------------------------------------------------------------

/** One tier's roof: a six-sided skirt of dark tile with the corners turned up. */
function hexEave(k: Kit, x: number, y: number, z: number, rOut: number, rIn: number, h: number): void {
  k.band(x, z, y, rOut, y + h, rIn, 6, TILE);
  k.cyl(x, y - 0.012, z, rOut, 0.012, scale(TILE, 0.8), 6);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2, c = Math.cos(a), s = Math.sin(a);
    k.bar([x + c * rOut * 0.86, y + h * 0.12, z + s * rOut * 0.86], [x + c * rOut * 1.07, y + h * 0.6, z + s * rOut * 1.07], 0.018, TILE);
  }
}

/** A slim six-sided pagoda of three tiers: red posts, cream walls, dark upturned eaves, a gold finial. */
const karstPagoda: Draw = (k) => {
  k.cyl(0, 0, 0, 0.36, 0.05, STONE, 6);
  k.cyl(0, 0.05, 0, 0.3, 0.05, STONE, 6);
  let y = 0.1;
  for (let t = 0; t < 3; t++) {
    const rad = 0.2 - t * 0.03, h = 0.34 - t * 0.02;
    k.cyl(0, y, 0, rad, h, CREAM, 6);
    // red posts at the six corners and a red rail round the foot
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2;
      k.box(Math.cos(a) * rad, y, Math.sin(a) * rad, 0.035, h, 0.035, RED);
    }
    k.cyl(0, y, 0, rad + 0.015, 0.05, RED, 6);
    k.pane(0, y + 0.1, rad * 0.866, rad * 0.5, h * 0.45, 1, DARK, EVENING, WARM_GLOW);
    k.pane(0, y + 0.1, -rad * 0.866, rad * 0.5, h * 0.45, 3, DARK, EVENING, WARM_GLOW);
    y += h;
    hexEave(k, 0, y, 0, rad + 0.17, rad * 0.75, 0.11);
    y += 0.11;
  }
  // the finial: a gold spike with rings
  k.cone(0, y - 0.02, 0, 0.09, 0.1, TILE, 6);
  k.cyl(0, y + 0.05, 0, 0.018, 0.22, GOLD, 5);
  k.cyl(0, y + 0.1, 0, 0.04, 0.02, GOLD, 6);
  k.cyl(0, y + 0.16, 0, 0.03, 0.02, GOLD, 6);
  lantern(k, 0, 0.36, 0.3, 0.04);
};

// ---- the cloud temple (the wonder, 12 × 12) -----------------------------------------------------------

interface Course { r: number; rz: number; x: number; z: number; y: number; h: number }

/**
 * A karst pinnacle: a stack of many-sided limestone courses, each a little off the one below, with tufts of
 * green on the ledges. Returns the courses, so that stairs and buildings can stand on them.
 */
function pinnacle(k: Kit, r: Rng, x: number, z: number, y0: number, radii: readonly number[], h: number, squash: number): Course[] {
  const out: Course[] = [];
  let y = y0;
  radii.forEach((rad, i) => {
    const cx = x + (r() - 0.5) * rad * 0.14, cz = z - Math.abs(r() - 0.5) * rad * 0.1;
    const col = i % 3 === 0 ? KARST : i % 3 === 1 ? KARST_LIGHT : scale(KARST, 0.92);
    // a dark undercut at the foot of each course makes the ledges read
    k.cyl(cx, y, cz, rad * 0.96, h * 0.12, KARST_DARK, 8, KARST_DARK, rad * squash * 0.96);
    k.cyl(cx, y + h * 0.12, cz, rad, h * 0.88, col, 7 + ((i * 2) % 3), i % 2 ? MOSS_DARK : KARST_LIGHT, rad * squash);
    out.push({ r: rad, rz: rad * squash, x: cx, z: cz, y, h });
    y += h;
    // tufts on the top of the course, out by its edge (not over the front, where the stair climbs)
    const n = 2 + Math.floor(r() * 2);
    for (let j = 0; j < n; j++) {
      const a = Math.PI * (0.75 + r() * 1.5), s = rad * (0.13 + r() * 0.08);
      k.dome(cx + Math.cos(a) * rad * 0.86, y - 0.02, cz + Math.sin(a) * rad * squash * 0.86, s, j % 2 ? MOSS : MOSS_DARK, 6, 2);
    }
  });
  return out;
}

/** A red hall under a swept dark roof, its ridge along x, standing on y: a plinth, walls, gold door, lanterns. */
function hall(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number): void {
  k.box(x, y, z, w + 0.2, 0.08, d + 0.2, STONE);
  k.box(x, y + 0.08, z, w, h, d, RED);
  k.box(x, y + 0.08 + h, z, w + 0.04, 0.05, d + 0.04, GOLD);
  flared(k, x, y + 0.13 + h, z, w + 0.5, h * 0.95, d + 0.5, TILE, RED);
  k.box(x, y + 0.08, z + d / 2 + 0.006, w * 0.2, h * 0.8, 0.012, GOLD);
  for (const s of [-1, 1]) {
    k.pane(x + s * w * 0.3, y + 0.08 + h * 0.3, z + d / 2, w * 0.16, h * 0.45, 1, DARK, EVENING, WARM_GLOW);
    k.pane(x + s * w * 0.3, y + 0.08 + h * 0.3, z - d / 2, w * 0.16, h * 0.45, 3, DARK, EVENING, WARM_GLOW);
    lantern(k, x + s * (w / 2 + 0.12), y + h * 0.75, z + d / 2 + 0.12, 0.07);
  }
  k.cyl(x, y + 0.14 + h * 1.95, z, 0.04, 0.16, GOLD, 5);
}

/** A temple on a karst pinnacle: a zigzag stair with red rails, a hall on the summit, a pavilion and a bridge halfway. */
const cloudTemple: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.3, 0.02, D - 0.3, hex(0x7f9a68));
  const cx = -1.3, cz = -1.6;
  // the rocky base the towers stand on
  k.band(cx + 0.9, cz + 0.2, 0.02, 4.0, 0.55, 3.3, 11, KARST_DARK);
  k.cyl(cx + 0.9, 0.53, cz + 0.2, 3.32, 0.04, MOSS_DARK, 11);
  for (let i = 0; i < 9; i++) {
    const a = r() * Math.PI * 2, d = 3.6 + r() * 0.7, s = 0.3 + r() * 0.35;
    k.cyl(cx + 0.9 + Math.cos(a) * d, 0.02, cz + 0.2 + Math.sin(a) * d, s, s * (0.8 + r()), i % 2 ? KARST : KARST_LIGHT, 6);
  }
  // the great pinnacle, the shoulder that carries the pavilion, and the lower pinnacle across the gap
  const y0 = 0.55, ch = 0.9;
  const main = pinnacle(k, r, cx, cz, y0, [2.5, 2.35, 2.3, 2.0, 1.9, 1.65, 1.55, 1.4], ch, 0.84);
  const top = y0 + ch * 8;
  const sx = cx + 2.35, sz = cz + 0.5;
  pinnacle(k, r, sx, sz, y0, [1.25, 1.15, 1.05, 0.95], ch, 0.9);
  const px = cx + 5.0, pz = cz + 1.0;
  pinnacle(k, r, px, pz, y0, [1.35, 1.2, 1.0, 0.85], ch, 0.9);
  const ledge = y0 + ch * 4;

  // the summit hall
  hall(k, cx, top, cz - 0.1, 1.5, 0.8, 0.5);
  // the pavilion on the shoulder: four red posts under a tiled hip, open on every side
  k.box(sx - 0.1, ledge, sz, 0.8, 0.06, 0.8, STONE);
  for (const ax of [-1, 1]) for (const az of [-1, 1]) k.box(sx - 0.1 + ax * 0.28, ledge + 0.06, sz + az * 0.28, 0.06, 0.42, 0.06, RED);
  k.box(sx - 0.1, ledge + 0.48, sz, 0.72, 0.05, 0.72, GOLD);
  k.hip(sx - 0.1, ledge + 0.53, sz, 1.05, 0.38, 1.05, TILE);
  k.cyl(sx - 0.1, ledge + 0.88, sz, 0.03, 0.14, GOLD, 5);
  lantern(k, sx - 0.1, ledge + 0.36, sz, 0.08);
  // the arched bridge across to the lower pinnacle, and a shrine lantern and a pine on that one
  const bx0 = sx + 0.55, bx1 = px - 0.45, bz = (sz + pz) / 2 + 0.1, n = 5;
  for (let i = 0; i < n; i++) {
    const f0 = i / n, f1 = (i + 1) / n;
    const at = (f: number, up: number, off: number): P3 => [bx0 + (bx1 - bx0) * f, ledge - 0.04 + Math.sin(f * Math.PI) * 0.3 + up, sz + (pz - sz) * f + 0.1 + off];
    k.bar(at(f0, 0, 0), at(f1, 0, 0), 0.13, STONE);
    for (const s of [-1, 1]) k.bar(at(f0, 0.2, s * 0.13), at(f1, 0.2, s * 0.13), 0.02, RED);
  }
  for (const s of [-1, 1]) {
    lantern(k, bx0, ledge + 0.2, bz - 0.1 + s * 0.16, 0.06);
    lantern(k, bx1, ledge + 0.2, bz + 0.1 + s * 0.16, 0.06);
  }
  k.box(px + 0.1, ledge, pz - 0.1, 0.3, 0.3, 0.3, STONE);
  k.hip(px + 0.1, ledge + 0.3, pz - 0.1, 0.5, 0.2, 0.5, TILE);
  lantern(k, px + 0.1, ledge + 0.08, pz + 0.06, 0.08);
  k.box(px + 0.45, ledge, pz + 0.2, 0.06, 0.3, 0.06, TIMBER);
  k.cone(px + 0.45, ledge + 0.2, pz + 0.2, 0.26, 0.45, MOSS_DARK, 6);

  // the stair: flights zigzagging up the front face between landings on each ledge, red rails on the outside
  const land: P3[] = [];
  for (let i = 0; i <= 8; i++) {
    const below = main[Math.max(0, i - 1)], here = main[Math.min(7, i)];
    const reach = Math.max(below.z + below.rz, here.z + here.rz) + 0.16;
    const side = i % 2 ? -1 : 1, off = Math.min(0.95, here.r * 0.42);
    land.push([cx + side * off, y0 + ch * i, reach]);
  }
  land.forEach(([x, y, z], i) => {
    // a landing, run back into the rock so it never floats
    k.box(x, y - 0.1, z - 0.3, 0.46, 0.1, 0.95, STONE);
    if (i < 8) {
      const [nx, ny, nz] = land[i + 1];
      k.bar([x, y - 0.06, z], [nx, ny - 0.06, nz], 0.1, STONE);
      k.bar([x, y + 0.2, z + 0.1], [nx, ny + 0.2, nz + 0.1], 0.022, RED);
      k.box(x, y, z + 0.1, 0.035, 0.22, 0.035, RED);
    }
    if (i % 2 === 0 && i > 0 && i < 8) lantern(k, x + 0.2, y + 0.02, z + 0.1, 0.06);
  });
  // from the last landing in to the hall's door
  const [tx, , tz] = land[8];
  k.box(tx, top - 0.1, (tz + cz) / 2, 0.4, 0.1, tz - cz, STONE);
  // from the gate up the base to the first landing
  const [fx, fy, fz] = land[0];
  const gx = fx + 0.3, gz = hd - 1.5;
  const bz0 = cz + 0.2 + 3.3 * 0.97, bz1 = cz + 0.2 + 4.0;
  k.bar([gx, 0.0, bz1 + 0.12], [gx, fy + 0.02, bz0 + 0.08], 0.13, STONE);
  for (const s of [-1, 1]) k.bar([gx + s * 0.15, 0.24, bz1 + 0.12], [gx + s * 0.15, fy + 0.26, bz0 + 0.08], 0.022, RED);
  k.box((gx + fx) / 2, fy + 0.025, (bz0 + fz) / 2, 0.5 + Math.abs(gx - fx), 0.03, bz0 - fz + 0.2, STONE);
  k.box(gx, 0.02, (bz1 + hd - 0.2) / 2, 0.5, 0.012, hd - 0.2 - bz1, STONE);
  // the paifang at the foot: red posts, a tiled beam, a gold board
  for (const s of [-1, 1]) {
    k.box(gx + s * 0.55, 0.02, gz, 0.12, 1.0, 0.12, RED);
    k.box(gx + s * 0.55, 0.02, gz, 0.2, 0.12, 0.2, STONE);
    lantern(k, gx + s * 0.55, 0.62, gz + 0.12, 0.09);
  }
  k.box(gx, 0.8, gz, 1.5, 0.1, 0.1, RED);
  k.box(gx, 0.9, gz, 0.4, 0.14, 0.06, GOLD);
  flared(k, gx, 1.04, gz, 1.9, 0.26, 0.5, TILE, RED);
  // pines about the foot
  for (let i = 0; i < 7; i++) {
    const x = (r() - 0.5) * (W - 1.2), z = hd - 0.6 - r() * 1.6;
    if (Math.abs(x - gx) < 1.2) continue;
    k.box(x, 0.02, z, 0.07, 0.25, 0.07, TIMBER);
    k.cone(x, 0.2, z, 0.3, 0.6, MOSS_DARK, 6);
  }
  k.cyl(-hw + 1.2, 0.02, hd - 1.4, 0.7, 0.012, JADE, 10);
};

