/**
 * Water that stands above the dry ground beside it (the user, 9 Nov 2026: "water abruptly ends with a vertical face"):
 * a lake whose bank some later levelling brought down under it, a sea whose cliff foot was left dry below sea level.
 * Each is drawn as a sheer wall of water ending in the air. GEN 54 (world/nextWorld.ts NEXT_080) settles them, once,
 * at the end of generation:
 *
 *  - the sea floods the dry ground below sea level beside it (a cliff's foot is under the sea, not a dry pit);
 *  - a lake a step over its banks comes down that step, where that keeps it a lake and it reaches no border;
 *  - a bank one or two steps under the water is built back up to it: a lip of shore round the lake;
 *  - where the water stands well over what lies beyond (a spill over a drop), a plunge pool is cut into the ground at
 *    the foot, its water as high as the ground round it, so the lake pours down into it: render/mesher.ts draws a
 *    falling sheet wherever two waters stand apart, so the drop draws itself as a waterfall.
 *
 * Nothing on a road, railway, building or deck moves, and nothing within a few tiles of the county's edge (the
 * neighbour's ground there must meet it), so a few edges stay as they were; `npm run shores` counts them.
 */
import { N, SEA, Biome, Feature, Flag, World, DIRS, EDGE_MINE, EDGE_THEIRS, idx, inB, maxCorner, minCorner } from './tiles';

/** Tiles from the county's edge nothing here touches. */
const EDGE_KEEP = 4;
/** A bank this many steps or fewer under the water is built up to it; deeper, the water pours into a pool. */
const LIP_MAX = 2;
/** The most dry ground the sea floods from one place, in tiles. */
const FLOOD_MAX = 600;

/** What settleShores did, for the gate and the stats. */
export interface ShoreStats { flooded: number; lowered: number; lipped: number; pools: number; left: number }

/** May this dry tile's ground be moved: plain ground, nothing built on or over it, clear of the county's edge. */
function shapeable(w: World, t: number): boolean {
  const x = t % N, z = (t - x) / N;
  if (x < EDGE_KEEP || z < EDGE_KEEP || x >= N - EDGE_KEEP || z >= N - EDGE_KEEP) return false;
  return !w.road[t] && !w.rail[t] && !w.blocked[t] && !w.deckAxis[t] && !(w.flags[t] & Flag.Poi) && w.feature[t] !== Feature.Airfield && w.townId[t] < 0 && w.portId[t] < 0;
}

/** Every edge where water at level L stands over dry ground: the water tile, its side, the dry tile and the drop in steps. */
function perchedEdges(w: World, body: number[], L: number): { i: number; d: number; j: number; drop: number }[] {
  const out: { i: number; d: number; j: number; drop: number }[] = [];
  for (const i of body) {
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (w.water[j] >= 0 || w.biome[j] === Biome.Ocean) continue;
      const g = Math.max(w.corners[j * 4 + EDGE_THEIRS[d][0]], w.corners[j * 4 + EDGE_THEIRS[d][1]]);
      if (L - g >= 1) out.push({ i, d, j, drop: L - g });
    }
  }
  return out;
}

/** Raise every dry, movable tile's corner at vertex (vx, vz) to at least h. */
function raiseVertex(w: World, vx: number, vz: number, h: number): void {
  for (const [tx, tz, q] of [[vx, vz, 0], [vx - 1, vz, 1], [vx - 1, vz - 1, 2], [vx, vz - 1, 3]] as const) {
    if (!inB(tx, tz)) continue;
    const t = idx(tx, tz);
    if (w.water[t] >= 0 || !shapeable(w, t)) continue;
    w.corners[t * 4 + q] = Math.max(w.corners[t * 4 + q], h);
  }
}

/** The two vertices of tile t's side d, as (x, z) pairs. */
function sideVertices(t: number, d: number): [number, number][] {
  const x = t % N, z = (t - x) / N;
  const at = (q: number): [number, number] => [x + (q === 1 || q === 2 ? 1 : 0), z + (q >= 2 ? 1 : 0)];
  return EDGE_MINE[d].map(at);
}

export function settleShores(w: World): ShoreStats {
  const st: ShoreStats = { flooded: 0, lowered: 0, lipped: 0, pools: 0, left: 0 };
  // the sea first: dry ground under sea level beside it goes under
  for (let i = 0; i < N * N; i++) {
    if (w.water[i] !== SEA) continue;
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const s = idx(nx, nz);
      if (w.water[s] >= 0 || maxCorner(w, s) >= SEA || !shapeable(w, s)) continue;
      // the whole hollow below sea level this opens onto
      const fill = [s], seen = new Set([s]);
      for (let h = 0; h < fill.length && fill.length <= FLOOD_MAX; h++) {
        const t = fill[h], tx = t % N, tz = (t - tx) / N;
        for (let e = 0; e < 4; e++) {
          const ux = tx + DIRS[e][0], uz = tz + DIRS[e][1];
          if (!inB(ux, uz)) continue;
          const u = idx(ux, uz);
          if (seen.has(u) || w.water[u] >= 0 || maxCorner(w, u) >= SEA || !shapeable(w, u)) continue;
          seen.add(u); fill.push(u);
        }
      }
      if (fill.length > FLOOD_MAX) continue;
      for (const t of fill) { w.water[t] = SEA; st.flooded++; }
    }
  }
  // and where the sea's shallows meet a beach or a bank a step or two under them, the shore built up to them
  for (let i = 0; i < N * N; i++) {
    if (w.water[i] !== SEA || w.biome[i] === Biome.Ocean) continue;
    for (const e of perchedEdges(w, [i], SEA)) {
      if (e.drop > LIP_MAX || !shapeable(w, e.j)) continue;
      for (const [vx, vz] of sideVertices(e.i, e.d)) raiseVertex(w, vx, vz, SEA);
      st.lipped++;
    }
  }
  // then each lake: a body of still water at one level, neither the sea nor a running river or stream
  const done = new Uint8Array(N * N);
  for (let s = 0; s < N * N; s++) {
    const L = w.water[s];
    if (done[s] || L < 0 || L <= SEA || (w.flags[s] & (Flag.River | Flag.Stream)) || w.biome[s] === Biome.Ocean) continue;
    const body = [s];
    done[s] = 1;
    let edge = false;
    for (let h = 0; h < body.length; h++) {
      const i = body[h], x = i % N, z = (i - x) / N;
      if (x < EDGE_KEEP || z < EDGE_KEEP || x >= N - EDGE_KEEP || z >= N - EDGE_KEEP) edge = true;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (done[j] || w.water[j] !== L || (w.flags[j] & (Flag.River | Flag.Stream))) continue;
        done[j] = 1; body.push(j);
      }
    }
    const edges = perchedEdges(w, body, L);
    if (!edges.length) continue;
    // down to its banks, where it stays a lake and touches no border: a step where it stands a step over them all
    // round, or as far as a railway or road beside it (whose bank can't be built up) needs
    if (!edge) {
      const fixed = edges.filter((e) => !shapeable(w, e.j));
      const by = edges.every((e) => e.drop <= 1) ? 1 : fixed.length ? Math.max(...fixed.map((e) => e.drop)) : 0;
      const wet = body.filter((i) => minCorner(w, i) < L - by).length;
      if (by > 0 && by <= 3 && wet >= body.length * 0.8) {
        for (const i of body) w.water[i] = minCorner(w, i) < L - by ? L - by : -1;
        st.lowered++;
        const left = perchedEdges(w, body.filter((i) => w.water[i] >= 0), L - by);
        if (!left.length) continue;
      }
    }
    const Lnow = w.water[body.find((i) => w.water[i] >= 0) ?? s];
    if (Lnow < 0) continue;
    if (Lnow !== L) { lipAndPool(w, body.filter((i) => w.water[i] >= 0), Lnow, st); continue; }
    lipAndPool(w, body, L, st);
  }
  // the rivers and streams: their banks built up to them where a step or two under
  for (let i = 0; i < N * N; i++) {
    const L = w.water[i];
    if (L < 0 || !(w.flags[i] & (Flag.River | Flag.Stream))) continue;
    for (const e of perchedEdges(w, [i], L)) {
      if (e.drop > LIP_MAX + 1 || !shapeable(w, e.j)) continue;
      for (const [vx, vz] of sideVertices(e.i, e.d)) raiseVertex(w, vx, vz, L);
      st.lipped++;
    }
  }
  return st;
}

/** A lake's banks a step or two under it built up to it, and a pool cut at the foot of each deeper spill. */
function lipAndPool(w: World, body: number[], L: number, st: ShoreStats): void {
  let edges = perchedEdges(w, body, L);
  for (const e of edges) {
    if (e.drop <= LIP_MAX && shapeable(w, e.j)) {
      // a lip of shore: the bank's edge up to the water
      for (const [vx, vz] of sideVertices(e.i, e.d)) raiseVertex(w, vx, vz, L);
      st.lipped++;
    }
  }
  // what is left stands well over the ground beyond: a pool cut at the foot for the water to pour into
  edges = perchedEdges(w, body, L);
  for (const e of edges) {
    if (w.water[e.j] >= 0 || !shapeable(w, e.j)) { st.left++; continue; }
    // the pool: the tile at the foot and the one beyond it, as long as both may be dug
    const jx = e.j % N, jz = (e.j - jx) / N;
    const pool = [e.j];
    const bx = jx + DIRS[e.d][0], bz = jz + DIRS[e.d][1];
    if (inB(bx, bz) && w.water[idx(bx, bz)] < 0 && shapeable(w, idx(bx, bz))) pool.push(idx(bx, bz));
    const inPool = new Set(pool);
    // its water as high as the lowest ground round it, so it stands over nothing itself
    let P = L - 1;
    for (const t of pool) {
      const tx = t % N, tz = (t - tx) / N;
      for (let d = 0; d < 4; d++) {
        const ux = tx + DIRS[d][0], uz = tz + DIRS[d][1];
        if (!inB(ux, uz)) continue;
        const u = idx(ux, uz);
        if (inPool.has(u)) continue;
        if (w.water[u] >= 0) continue;
        P = Math.min(P, w.corners[u * 4 + EDGE_THEIRS[d][0]], w.corners[u * 4 + EDGE_THEIRS[d][1]]);
      }
    }
    if (P >= L || P < -20) { st.left++; continue; }
    for (const t of pool) {
      for (let q = 0; q < 4; q++) w.corners[t * 4 + q] = Math.min(w.corners[t * 4 + q], P - 1);
      w.water[t] = P;
      w.flags[t] |= Flag.Corridor;
      w.surface[t] = 0;
    }
    st.pools++;
  }
}
