import { JOBS } from './factions/paintjobs';
import type { AirDef, LandDef, Looks, VehicleDef, WaterDef } from './vehicles';
import { priceOf } from './economy';
import { speedIn, speedText, speedUnit } from './units';
import { NEXT_WORLD } from '../world/nextWorld';

/**
 * The workshop (docs/upgrades.html): parts a unit can own, in named slots, each with three tiers. A
 * part is a change to the vehicle's definition, so a tuned Mule is a Mule whose def says 2.5 where the
 * model says 2; physics, meshes, tyre tracks and hired drivers all read the unit's own def and learn
 * nothing new. `applyParts` builds that def; Fleet.defFor caches it per distinct set of parts.
 */

export type SlotId =
  | 'paint' | 'engine' | 'gearbox' | 'tyres' | 'handbrake' | 'hull' | 'wings'
  | 'nitrous' | 'brakes' | 'suspension' | 'rack' | 'bullbar' | 'horn' | 'banner';

type Kind = VehicleDef['kind'];

export interface Slot {
  id: SlotId;
  icon: string;
  /** What the slot is called on each kind of vehicle that takes it. */
  names: Partial<Record<Kind, string>>;
  /** The three tiers' names, per kind where they differ. */
  tiers: Partial<Record<Kind | 'all', [string, string, string]>>;
  /** Only these models take it (the banner: the Barnstormer's alone). */
  only?: string[];
}

/** The panel's order. */
export const SLOTS: Slot[] = [
  { id: 'paint', icon: '🎨', names: { land: 'Paint', water: 'Paint', air: 'Paint' }, tiers: { all: ['Respray', 'Metallic', 'Two-tone'] } },
  { id: 'engine', icon: '⚙️', names: { land: 'Engine', water: 'Outboard', air: 'Engine', rail: 'Engine' }, tiers: { all: ['Stage 1', 'Stage 2', 'Stage 3'] } },
  { id: 'gearbox', icon: '🔧', names: { land: 'Gearbox', water: 'Prop', air: 'Throttle', rail: 'Traction' }, tiers: { all: ['Close ratio', 'Sport', 'Race'], water: ['Three-blade', 'Four-blade', 'Cleaver'], air: ['Quick', 'Sharp', 'Twitchy'], rail: ['Sanders', 'Twin motors', 'All-axle'] } },
  { id: 'tyres', icon: '🛞', names: { land: 'Tyres' }, tiers: { all: ['Wide', 'Chunky', 'Monster'] } },
  { id: 'handbrake', icon: '🅿️', names: { land: 'Handbrake' }, tiers: { all: ['Handbrake', 'Hydraulic', 'Rally'] } },
  { id: 'hull', icon: '🚤', names: { water: 'Hull' }, tiers: { all: ['Stepped', 'Spray rails', 'Keel'] } },
  { id: 'wings', icon: '🪽', names: { air: 'Rotor / wings' }, tiers: { all: ['Long tips', 'Swept', 'Aerobatic'] } },
  { id: 'nitrous', icon: '🧪', names: { land: 'Nitrous', water: 'Turbo' }, tiers: { all: ['Bottle', 'Big bottle', 'Twin bottles'] } },
  { id: 'brakes', icon: '🛑', names: { land: 'Brakes', water: 'Reverse gear', air: 'Airbrake', rail: 'Brakes' }, tiers: { all: ['Discs', 'Big discs', 'Race brakes'], water: ['Quick', 'Strong', 'Crash stop'], air: ['Flaps', 'Big flaps', 'Spoilers'] } },
  { id: 'suspension', icon: '🪜', names: { land: 'Suspension' }, tiers: { all: ['Sport', 'Rally', 'Lifted'] } },
  { id: 'rack', icon: '📦', names: { land: 'Rack', water: 'Deck cargo', air: 'Pods' }, tiers: { all: ['Roof box', 'Rack', 'Full rack'], water: ['Deck crates', 'Second row', 'Deck stack'], air: ['Pod', 'Two pods', 'Big pods'] } },
  { id: 'bullbar', icon: '🛡️', names: { land: 'Bull bar', water: 'Fenders' }, tiers: { all: ['Nudge bar', 'Bull bar', 'Plough'], water: ['Fenders', 'Rubbing strake', 'Ice bow'] } },
  { id: 'horn', icon: '📯', names: { land: 'Horn', water: 'Foghorn', air: 'Klaxon', rail: 'Whistle' }, tiers: { all: ['Beep', 'Air horn', 'Tune'], water: ['Foghorn', 'Deep blast', 'Ship’s horn'], air: ['Klaxon', 'Long klaxon', 'Tune'], rail: ['Two-chime', 'Steam whistle', 'Three-chime'] } },
  // the Barnstormer's towed advertising banner (0.7.0, render/banners.ts): which tier is fitted is what it says
  ...(NEXT_WORLD ? [{ id: 'banner', icon: '🎏', names: { air: 'Banner' }, tiers: { all: ['Fleet banner', 'Visit banner', 'Lit banner'] }, only: ['barnstormer'] } as Slot] : []),
];

export const slotOf = (id: SlotId): Slot => SLOTS.find((s) => s.id === id)!;

/** The slots a model takes, in the panel's order. */
export function slotsFor(def: VehicleDef): Slot[] {
  return SLOTS.filter((s) => s.names[def.kind] && (!s.only || s.only.includes(def.id)));
}
export const slotName = (s: Slot, def: VehicleDef): string => s.names[def.kind] ?? s.id;
export const tierName = (s: Slot, def: VehicleDef, tier: number): string => tier <= 0 ? 'Stock' : (s.tiers[def.kind] ?? s.tiers.all!)[tier - 1];

/** The 24 colours a respray comes in: every model's own, and a few more. */
export const PALETTE: { c: number; name: string }[] = [
  { c: 0xe2412f, name: 'Tomato' }, { c: 0xf28c38, name: 'Tangerine' }, { c: 0xf2a93b, name: 'Marigold' }, { c: 0xf5cf3a, name: 'Canary' },
  { c: 0xf6d04d, name: 'Duckling' }, { c: 0x6f9e6b, name: 'Bramble' }, { c: 0x3f9b4a, name: 'Tractor' }, { c: 0xa7dcc8, name: 'Mint' },
  { c: 0x2bb3a3, name: 'Teal' }, { c: 0x3f78c0, name: 'Cornflower' }, { c: 0x4a6fa5, name: 'Denim' }, { c: 0x2f4d7a, name: 'Navy' },
  { c: 0x2e4b7a, name: 'Ocean' }, { c: 0x8e5cc7, name: 'Grape' }, { c: 0xf7c5d4, name: 'Candy' }, { c: 0xef6a4c, name: 'Coral' },
  { c: 0xf4f2ec, name: 'Chalk' }, { c: 0xc9ced4, name: 'Silver' }, { c: 0x8a8f96, name: 'Gunmetal' }, { c: 0x2a2a2e, name: 'Black' },
  { c: 0xb07a4a, name: 'Walnut' }, { c: 0x9e2b3a, name: 'Claret' }, { c: 0xd9b34a, name: 'Gold' }, { c: 0x86c36c, name: 'Lime' },
];
export const colourName = (c: number): string => PALETTE.find((p) => p.c === c)?.name ?? `#${c.toString(16).padStart(6, '0')}`;

/** A colour's hue in degrees, and how far round the wheel two hues are (0–180). */
function hueOf(c: number): number {
  const r = ((c >> 16) & 255) / 255, g = ((c >> 8) & 255) / 255, b = (c & 255) / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
  if (d < 1e-6) return -1;
  const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return ((h * 60) + 360) % 360;
}
const hueGap = (a: number, b: number): number => { const d = Math.abs(a - b) % 360; return d > 180 ? 360 - d : d; };

/**
 * The respray colour that stands furthest from these (a hand's own car beside the fleet's livery, missions/
 * templates.ts first:hand): the strongest colour on the wheel furthest in hue from every one of `from`; greys
 * and the Tomato's own red are never picked.
 */
export function farColour(from: number[]): number {
  const hues = from.map(hueOf).filter((h) => h >= 0);
  const avoid = new Set([0xe2412f, 0xf4f2ec, 0xc9ced4, 0x8a8f96, 0x2a2a2e]);
  let best = 0x3f78c0, bestD = -1;
  for (const p of PALETTE) {
    if (avoid.has(p.c)) continue;
    const h = hueOf(p.c);
    if (h < 0) continue;
    const d = hues.length ? Math.min(...hues.map((q) => hueGap(h, q))) : 180;
    if (d > bestD) { bestD = d; best = p.c; }
  }
  return best;
}

/** What a unit has: per slot, the tier owned (bought up to) and the tier fitted (0 is stock). */
export interface Parts {
  t: Partial<Record<SlotId, [number, number]>>;
  /** The respray's colour and the two-tone accent; missing is the model's own. */
  c?: number;
  a?: number;
  /** Dollars spent on parts, for the resale and the workshop's totals. */
  spent: number;
  /** Seconds until each nitrous bottle is full again; 0 is full. */
  nos?: number[];
  /** A faction paintjob the player has earned (docs/factions.html, game/factions/paintjobs.ts): over the paint while it is on. */
  j?: string;
  // the Passport's treats (game/passportRewards.ts), free once earned, each shown to other players with the parts
  /** The Wonder Ball on the roof (every wonder stamped): kept beside `tp` so an older game still draws it. */
  w?: 1;
  /** The topper on the roof (docs/toppers.html, game/toppers.ts): a topper id, the Wonder Ball's `wonder` among them. */
  tp?: string;
  /** Under a crown (game/crownIds.ts): the topper it wore before, worn again when the crown is lost. */
  tb?: string;
  /** The Explorer's lantern: coloured headlamps and a roof searchlight (every landform stamped). */
  l?: 1;
  /** A treat horn: the fanfare (every signature building) or the confetti horn (every event). */
  h?: HornTune;
  /** The Gilded Fleet (every stamp in the book): 1 gold trim, 2 gold all over. Set fleet-wide from the HQ window. */
  g?: 1 | 2;
}

/** The treat horns (game/passportRewards.ts). */
export type HornTune = 'fanfare' | 'confetti';
export const HORN_TUNES: HornTune[] = ['fanfare', 'confetti'];

/** A topper id as one may be written (game/toppers.ts has the catalogue; one this game doesn't know is drawn as nothing). */
const isTopper = (v: unknown): v is string => typeof v === 'string' && /^[A-Za-z0-9:]{1,32}$/.test(v);
/** The topper a unit wears: its own, or the Wonder Ball from a save made before toppers (`w`). */
export const topperOf = (p: Parts | undefined): string | undefined => (p ? (isTopper(p.tp) ? p.tp : p.w === 1 ? 'wonder' : undefined) : undefined);

export const emptyParts = (): Parts => ({ t: {}, spent: 0 });
export const owned = (p: Parts | undefined, s: SlotId): number => p?.t[s]?.[0] ?? 0;
export const fitted = (p: Parts | undefined, s: SlotId): number => p?.t[s]?.[1] ?? 0;

/** Seconds a bottle takes to fill. */
export const NOS_REFILL = 60;

// ---- prices ----------------------------------------------------------------------------------------

/** What the parts are priced off: the model's price, with a floor so the free Tomato isn't free to tune. */
const bookValue = (model: string): number => Math.max(priceOf(model), 600);
const r10 = (v: number) => Math.round(v / 10) * 10;
/** The paint costs more to spread over a bigger thing. */
const paintMul = (def: VehicleDef): number => (def.kind === 'land' ? 1 : def.kind === 'rail' ? 4 : 2);
/** One coat in a new colour once a respray is owned. */
export const coatPrice = (def: VehicleDef): number => 60 * paintMul(def);

/** The full price of a tier, as if bought from stock. */
export function tierPrice(def: VehicleDef, slot: SlotId, tier: number): number {
  if (tier <= 0) return 0;
  if (slot === 'horn') return [40, 120, 300][tier - 1];
  if (slot === 'banner') return [350, 500, 900][tier - 1];
  if (slot === 'paint') return [60, 180, 400][tier - 1] * paintMul(def);
  const b = bookValue(def.id);
  return r10([0.08 * b + 120, 0.15 * b + 250, 0.25 * b + 500][tier - 1]);
}

/** What fitting this tier costs now: the difference from what is owned, nothing for a tier already owned. */
export function owedFor(def: VehicleDef, p: Parts | undefined, slot: SlotId, tier: number): number {
  const have = owned(p, slot);
  return tier <= have ? 0 : tierPrice(def, slot, tier) - tierPrice(def, slot, have);
}

/** Every slot the model takes, at the top tier: what a unit is when nothing more can be bought. */
export function fullWorks(def: VehicleDef, p: Parts | undefined): boolean {
  return slotsFor(def).every((s) => owned(p, s.id) >= 3);
}

// ---- the effective definition ------------------------------------------------------------------------

export function partsKey(p: Parts | undefined): string {
  if (!p) return '';
  const t = SLOTS.map((s) => fitted(p, s.id)).join('');
  return `${t}|${p.c ?? ''}|${p.a ?? ''}|${p.j ?? ''}|${p.w ?? ''}${p.l ?? ''}${p.h ?? ''}${p.g ?? ''}${p.tp ? `|${p.tp}` : ''}`;
}

/** The model's definition with the unit's fitted parts laid over it. Pure: it copies, never writes the model. */
export function applyParts(base: VehicleDef, p: Parts | undefined): VehicleDef {
  const key = partsKey(p);
  if (!p || /^0+\|\|\|\|$/.test(key)) return base;
  const tier = (s: SlotId) => (slotOf(s).names[base.kind] ? fitted(p, s) : 0);
  const d = { ...base } as VehicleDef & Record<string, unknown>;
  const paint = tier('paint');
  const looks: Looks = {
    key, paint,
    colour: paint >= 1 && p.c !== undefined ? p.c : base.color,
    accent: paint >= 3 && p.a !== undefined ? p.a : 0x1f2b33,
    engine: tier('engine'), tyres: tier('tyres'), brakes: tier('brakes'), suspension: tier('suspension'),
    rack: tier('rack'), bullbar: tier('bullbar'), nitrous: tier('nitrous'), hull: tier('hull'), wings: tier('wings'),
  };
  // a faction paintjob (docs/factions.html) is the body's colour and its own rules: the workshop's paint stands aside
  const job = p.j ? JOBS[p.j] : undefined;
  if (job) { looks.colour = job.body; looks.paint = Math.min(looks.paint, 1); d.job = job.id; }
  d.color = looks.colour;
  d.looks = looks;
  // the Passport's treats: the mesh builder and the horn read them off the def (game/passportRewards.ts)
  const tp = topperOf(p);
  if (tp) d.topper = tp;
  if (p.l) d.lantern = 1;
  if (p.h && HORN_TUNES.includes(p.h)) d.tune = p.h;
  if (p.g === 1 || p.g === 2) d.gild = p.g;

  const engine = tier('engine');
  if (engine) {
    const k = [1.08, 1.16, 1.25][engine - 1];
    if (d.kind === 'water' && d.sail) d.motor = [0.8, 1.2, 1.6][engine - 1];
    else {
      d.topSpeed *= k;
      d.reverseCap *= k;
      // a plane's stall speed rises with it, so it stays flyable
      if (d.kind === 'air' && d.minSpeed > 0) d.minSpeed *= k;
    }
  }
  const gear = tier('gearbox');
  if (gear) {
    d.accel *= [1.2, 1.4, 1.65][gear - 1];
    if (d.kind === 'land' && gear === 3) d.burnout = true;
  }
  const brakes = tier('brakes');
  if (brakes) {
    d.brake *= [1.2, 1.4, 1.6][brakes - 1];
    if (d.kind === 'land' && brakes === 3) d.chirp = true;
  }
  const rack = tier('rack');
  if (rack && d.kind !== 'rail') d.capacity += Math.max([1, 2, 3][rack - 1], Math.round(base.capacity * [0.2, 0.4, 0.6][rack - 1]));
  const horn = tier('horn');
  if (horn) d.horn = horn;
  // the banner it tows: 1 the fleet's name, 2 "Visit" the town below, 3 the fleet's name lit after dark
  if (NEXT_WORLD && d.kind === 'air' && base.id === 'barnstormer') { const b = tier('banner'); if (b) d.banner = b; }
  const nos = tier('nitrous');
  if (nos && (d.kind === 'land' || d.kind === 'water')) {
    d.nitrous = { bottles: nos === 3 ? 2 : 1, secs: [2, 3, 3.5][nos - 1], mul: [1.25, 1.4, 1.45][nos - 1], acc: [2, 2, 2.5][nos - 1] };
  }
  const bar = tier('bullbar');
  if (bar && (d.kind === 'land' || d.kind === 'water')) {
    // never softer than the model is stock (a tipper or a tank already shrugs knocks off)
    d.knock = Math.min(base.knock ?? 1, [0.6, 0.4, 0.2][bar - 1]);
    if (d.kind === 'land') {
      d.heft = Math.max(base.kind === 'land' ? base.heft ?? 1 : 1, [1.3, 1.6, 2][bar - 1]);
      d.glance = Math.max(base.kind === 'land' ? base.glance ?? 0.7 : 0.7, [0.7, 0.8, 0.9][bar - 1]);
      if (bar === 3) d.bounce = Math.max(base.kind === 'land' ? base.bounce ?? 0.1 : 0.1, 0.3);
    }
  }

  if (d.kind === 'land') applyLand(d, base as LandDef, tier);
  else if (d.kind === 'water') applyWater(d, tier);
  else if (d.kind === 'air') applyAir(d, tier);
  return d as VehicleDef;
}

function applyLand(d: LandDef, base: LandDef, tier: (s: SlotId) => number): void {
  const tyres = tier('tyres');
  if (tyres) {
    d.tyres = { ...(base.tyres ?? {}), width: (base.tyres?.width ?? 0.38) * [1.4, 1.5, 1.6][tyres - 1] };
    d.grip = Math.max(base.grip ?? 0, [1.1, 1.2, 1.3][tyres - 1]);
    // rough ground costs less: each tier wins back more of what grass, sand, snow, marsh, mud and ballast
    // take off its pace, the best keeping it near dirt-lane speed anywhere (game/car.ts roughLift). No tier
    // lets it hop a higher ledge or climb a steeper tile: tyres don't drive up cliffs (the user, Oct 2026).
    d.rough = [0.35, 0.65, 0.9][tyres - 1];
    if (tyres >= 2) d.roadMul = tyres === 2 ? 0.97 : 0.94;
    if (tyres === 3) d.bumpMul = (base.bumpMul ?? 1) * 1.4;
  }
  const susp = tier('suspension');
  if (susp) {
    d.bumpMul = (d.bumpMul ?? 1) * [0.7, 0.5, 0.5][susp - 1];
    d.lean = (base.lean ?? 0) * 0.6;
    if (susp === 2) d.springK = (base.springK ?? 120) * 1.3;
    // the duck already floats; everything else fords one step deeper
    if (susp === 3 && base.wade < 2) d.wade = base.wade + 1;
  }
  const hb = tier('handbrake');
  if (hb) d.drift = [{ yaw: 1.15, follow: 2.6, drag: 1.5 }, { yaw: 1.35, follow: 3.1, drag: 1.1 }, { yaw: 1.55, follow: 3.6, drag: 0.8 }][hb - 1];
}

function applyWater(d: WaterDef, tier: (s: SlotId) => number): void {
  const hull = tier('hull');
  if (!hull) return;
  d.grip *= [1.3, 1.6, 1.8][hull - 1];
  d.wave *= [0.8, 0.6, 0.6][hull - 1];
  if (hull >= 2) d.steerRate *= 1.1;
  if (hull === 3) d.minDepth = Math.max(1, d.minDepth - 1);
}

function applyAir(d: AirDef, tier: (s: SlotId) => number): void {
  // a jet's engine part shortens its take-off roll as well
  const engine = tier('engine');
  if (engine && d.jet) d.jet = { ...d.jet, groundAccel: d.jet.groundAccel * [1.1, 1.2, 1.3][engine - 1] };
  const wings = tier('wings');
  if (!wings) return;
  d.climbRate *= [1.2, 1.4, 1.6][wings - 1];
  d.maxClear += [2, 4, 6][wings - 1];
  if (wings >= 2) d.steerRate *= 1.1;
  if (wings === 3) d.bank *= 1.2;
}

// ---- words ---------------------------------------------------------------------------------------------

const kmh = (v: number) => Math.round(v * 12);
/** Seconds from a standstill to top speed on the flat. */
const toTop = (d: VehicleDef) => (d.topSpeed / Math.max(0.01, d.accel));
const secs = (v: number) => `${v < 10 ? v.toFixed(1) : Math.round(v)} s`;

/** The numbers the head of the pane shows, for a def. */
export function headline(d: VehicleDef): string {
  const bits = [speedText(kmh(d.topSpeed)), `0–top ${secs(toTop(d))}`];
  if (d.kind !== 'rail') bits.push(`holds ${d.capacity}`);
  if (d.kind === 'land') bits.push(`curb ${d.curb}`, d.wade > 10 ? 'floats' : `wades ${d.wade}`);
  if (d.kind === 'water') bits.push(`draws ${d.minDepth}`);
  if (d.kind === 'air') bits.push(`ceiling ${d.maxClear}`);
  return bits.join(' · ');
}

/**
 * What a tier does to this vehicle, in the player's units, worked out from the two definitions rather
 * than written by hand: "top speed 24 → 28 km/h · curb 1 → 2".
 */
export function effectLine(slot: SlotId, stock: VehicleDef, withIt: VehicleDef, tier: number): string {
  if (tier <= 0) return 'As it left the factory.';
  const out: string[] = [];
  const num = (label: string, a: number, b: number, unit = '') => { if (a !== b) out.push(`${label} ${a}${unit} → ${b}${unit}`); };
  num('top speed', speedIn(kmh(stock.topSpeed)), speedIn(kmh(withIt.topSpeed)), ` ${speedUnit()}`);
  if (Math.abs(toTop(stock) - toTop(withIt)) > 0.05) out.push(`0 to top ${secs(toTop(stock))} → ${secs(toTop(withIt))}`);
  if (Math.abs(stock.brake - withIt.brake) > 1e-6) out.push(`braking ×${(withIt.brake / stock.brake).toFixed(1)}`);
  if (stock.kind !== 'rail' && withIt.kind !== 'rail') num('holds', stock.capacity, withIt.capacity);
  if (stock.kind === 'land' && withIt.kind === 'land') {
    num('curb', stock.curb, withIt.curb);
    num('climbs', stock.maxGrade, withIt.maxGrade);
    if (stock.wade < 10) num('wades', stock.wade, withIt.wade);
    if (withIt.grip && withIt.grip !== stock.grip) out.push(`off-road grip ×${withIt.grip.toFixed(1)}`);
    if (withIt.rough && withIt.rough !== stock.rough) out.push(`wins back ${Math.round(withIt.rough * 100)}% of the pace rough ground costs (up to dirt-lane speed)`);
    if (withIt.roadMul && withIt.roadMul !== stock.roadMul) out.push(`${Math.round((1 - withIt.roadMul) * 100)}% slower on tarmac`);
    if ((withIt.bumpMul ?? 1) < (stock.bumpMul ?? 1)) out.push('softer over bumps');
    if (withIt.heft && withIt.heft !== stock.heft) out.push(`flattens fences ×${withIt.heft}`, `knocks felt ×${withIt.knock}`);
    if (withIt.drift && JSON.stringify(withIt.drift) !== JSON.stringify(stock.drift)) out.push(`Holding Space slides the tail round: turns ×${withIt.drift.yaw} while held, scrubs ${withIt.drift.drag <= 0.8 ? 'little' : withIt.drift.drag <= 1.1 ? 'some' : 'plenty of'} speed`);
    if (withIt.burnout && !stock.burnout) out.push('lays rubber pulling away');
    if (withIt.chirp && !stock.chirp) out.push('marks the road in a hard stop');
  }
  if (stock.kind === 'water' && withIt.kind === 'water') {
    if (withIt.motor && withIt.motor !== stock.motor) out.push(`motors at ${speedText(kmh(withIt.motor))} whatever the wind`);
    if (withIt.grip !== stock.grip) out.push(`drift dies ×${(withIt.grip / stock.grip).toFixed(1)} faster`);
    num('draws', stock.minDepth, withIt.minDepth, ' steps');
    if (withIt.knock && withIt.knock !== stock.knock) out.push(`knocks felt ×${withIt.knock}`);
  }
  if (stock.kind === 'air' && withIt.kind === 'air') {
    if (withIt.climbRate !== stock.climbRate) out.push(`climbs ×${(withIt.climbRate / stock.climbRate).toFixed(1)}`);
    num('ceiling', stock.maxClear, withIt.maxClear);
  }
  if (withIt.nitrous && JSON.stringify(withIt.nitrous) !== JSON.stringify(stock.nitrous)) {
    const n = withIt.nitrous;
    out.push(`Shift: ${n.secs} s at +${Math.round((n.mul - 1) * 100)}% (${speedText(kmh(withIt.topSpeed * n.mul))})${n.bottles > 1 ? ', two bottles' : ''}, ${NOS_REFILL} s to refill · drivers never use it`);
  }
  // the parts that don't move a number say what they are, not what the rest of the car does
  if (slot === 'horn') return `K sounds it: ${tierName(slotOf('horn'), withIt, tier).toLowerCase()}`;
  if (slot === 'banner') return tier === 1 ? 'Tows your fleet’s name across the sky, in its colours, wherever it flies (hired pilots too).'
    : tier === 2 ? 'Tows “Visit” and the name of the town it is over, changing as it flies on.' : 'Your fleet’s name, lit up after dark.';
  if (slot === 'paint') return tier === 1 ? 'Any of 24 colours.' : tier === 2 ? 'A metallic finish that catches the sun.' : 'A second colour on the roof and trim.';
  return out.length ? out.join(' · ') : 'Looks the part.';
}

/** The garage list's second line: a few words for what has been done to it. */
export function partsLine(def: VehicleDef, p: Parts | undefined): string {
  if (!p || !p.spent) return 'stock';
  const bits: string[] = [];
  for (const s of slotsFor(def)) {
    const t = fitted(p, s.id);
    if (!t) continue;
    if (s.id === 'paint') bits.push(`${colourName(p.c ?? def.color).toLowerCase()}${t >= 2 ? ' ' + tierName(s, def, t).toLowerCase() : ''}`);
    else if (s.id === 'engine' || s.id === 'nitrous' || s.id === 'handbrake' || s.id === 'horn' || s.id === 'banner') bits.push(tierName(s, def, t).toLowerCase());
    else bits.push(`${tierName(s, def, t).toLowerCase()}`);
  }
  return bits.length ? bits.join(' · ') : 'stock';
}

/** Kept only when it holds anything, and rounded, for the save. */
export function packParts(p: Parts | undefined): Parts | undefined {
  if (!p || (!p.spent && !Object.keys(p.t).length && !p.j && !p.w && !p.tp && !p.l && !p.h && !p.g)) return undefined;
  const out: Parts = { t: {}, spent: Math.round(p.spent) };
  for (const [k, v] of Object.entries(p.t)) if (v && (v[0] || v[1])) out.t[k as SlotId] = [v[0], v[1]];
  if (p.c !== undefined) out.c = p.c;
  if (p.a !== undefined) out.a = p.a;
  if (p.nos?.some((s) => s > 0)) out.nos = p.nos.map((s) => Math.round(s));
  if (p.j) out.j = p.j;
  const tp = topperOf(p);
  if (tp) out.tp = tp;
  if (tp === 'wonder') out.w = 1;
  if (isTopper(p.tb)) out.tb = p.tb;
  if (p.l) out.l = 1;
  if (p.h) out.h = p.h;
  if (p.g) out.g = p.g;
  return out;
}

export function unpackParts(p: Parts | undefined): Parts | undefined {
  if (!p || typeof p !== 'object') return undefined;
  return {
    t: { ...(p.t ?? {}) }, spent: p.spent ?? 0, c: p.c, a: p.a, nos: p.nos ? [...p.nos] : undefined, ...(typeof p.j === 'string' ? { j: p.j } : {}),
    ...(isTopper(p.tp) ? { tp: p.tp } : p.w === 1 ? { tp: 'wonder' } : {}), ...(isTopper(p.tb) ? { tb: p.tb } : {}), ...(p.l === 1 ? { l: 1 as const } : {}),
    ...(HORN_TUNES.includes(p.h as HornTune) ? { h: p.h } : {}), ...(p.g === 1 || p.g === 2 ? { g: p.g } : {}),
  };
}

