import { hashString } from '../../world/rng';
import { compose, moneyText, ordinal, toned, whoClass, type Told } from './copy';
import { paperFor, publisher } from './masthead';
import {
  DAY_H, PRESS_HOUR, YEAR_H,
  type Article, type Boxes, type Fields, type Issue, type Kind, type Layout, type LedgerNumbers, type Pic, type PressEvent, type PressSave,
  type Snapshot, type SportNow, type TownInfo,
} from './types';

/**
 * The news desk (docs/newspaper.html): the Press's local branch writes down what happens near the player as it
 * happens, and once a game year, at 07:00 on the first morning of spring, prints a paper about the year.
 *
 * Game code calls `press.write({ k, who, town, f })` beside an announcement it already makes; the desk stamps
 * it with the hour and how far it was from the player, and asks for a still of the moment when a big thing
 * happens where the player is. At press time every local event of the year is scored (weight × nearness ×
 * novelty × involvement): the best becomes the headline, the next three to five the minors, the rest the
 * briefs; the tavern talk and the vans after midnight go to Heard at the Inn; the league, the weather and the
 * company's own year fill the standing boxes. A thin year prints a quiet two-column sheet; an empty one is
 * skipped and its events wait for the next. Nothing is invented: every line is one event's own fields.
 *
 * One of these for the game, like the story chains: main.ts gives it its host, ticks it, saves it.
 */

export interface PressHost {
  hours(): number;
  /** The player's position in world tiles, or null. */
  player(): { x: number; z: number } | null;
  /** A town's middle in world tiles, by key, when anything knows where it is. */
  townPos(key: string): { x: number; z: number } | null;
  /** A town as it stands now, when its cell is in memory: the dealt-with list keeps this. */
  townInfo(key: string): Omit<TownInfo, 'n'> | null;
  /** The company and the met rival firms as they stand now. */
  snapshot(): Snapshot;
  /** The player's fleet's name. */
  fleet(): string;
  /** Towns with a news station near the player: the publisher when no dealt-with town has one. */
  newsTowns(): TownInfo[];
  /** The county the player is in. */
  county(): string;
  /** The game hour the company was founded. */
  founded(): number;
  /** An issue has come out (not called for a dry run). */
  printed(issue: Issue): void;
  /** The league round the nearest stadium, its last finished season (the Sport box, the champions' story). */
  sport?(): SportNow | null;
  /** The Press's standing with the player (factions.ts RUNG index, 3 Neutral), for the paper's tone. */
  rung?(): number;
}

/** What a hook gives the desk. `at`: where it happened, in world tiles, when that isn't the town's middle or the player's spot. */
export interface LogIn {
  k: Kind;
  v?: string;
  who?: string;
  town?: string;
  at?: { x: number; z: number };
  w?: number;
  f: Fields;
  pic?: Pic;
  /** The game hour it happened, when not now (the founding, written down on a save's first load). */
  t?: number;
}

/** Each kind's starting weight: 1 a brief, 5 a front page. */
export const WEIGHT: Record<Kind, number> = {
  founded: 5, vehicleBought: 2, fleetSize: 3, driverHired: 1, driverAce: 3, driverQuit: 2,
  hq: 4, deedBought: 3, deedSold: 2, deedMended: 2, deedVoid: 2, plantRun: 2,
  territoryWon: 4, territoryLost: 4, territoryStrong: 3, territoryContested: 3,
  lobbied: 3, annexed: 3, roadsBuilt: 2, worth: 4, deed: 2, missionDone: 2, storyBeat: 4,
  raceResult: 3, nightRun: 1, bust: 3, towed: 1, firmMet: 2, firmCeased: 5,
  graduated: 5, requestDone: 2, culture: 3, bigGame: 1, concert: 2, weather: 2, rumour: 1, find: 3, firstVisit: 2,
  season: 2, built: 3, mood: 2, protest: 2, event: 2,
  record: 3, guest: 1, sign: 2, hearts: 2, gg: 2, named: 3, postcard: 2, pick: 3, crossings: 1, listed: 3, tracks: 2,
  friendHq: 2, crewJoin: 3, board: 1, sealed: 3, wire: 2, award: 4,
};

/**
 * The news wire's stories, by whose news they are to this player (docs: server/news.ts): their own fleet's count as
 * theirs, their circle's as near news, their county's by distance; the rest of the world's only from this weight up,
 * at most one of them a minor, the others in the From further afield box.
 */
const WIRE_NEAR: Record<string, number> = { you: 1, circle: 0.7, county: 0.7 };
const WORLD_WEIGHT = 4, WORLD_MINORS = 1, WORLD_NEAR = 0.4;
/** Fleet of the Year: the least stories on the wire a fleet needs, for the world and for the county. */
const AWARD_N = 3, AWARD_COUNTY_N = 2;
/** Standing boxes a paper prints at most, beside the Ledger and the briefs; the rest wait for another issue. */
const BOXES = 3;

/** Within this many tiles of the player an event is local news; within NEAR it is close to home. */
export const LOCAL = 160;
export const NEAR = 60;
/** Within this many tiles, a big thing gets a still of the moment; from this weight up. */
const SHOT_NEAR = 40, SHOT_WEIGHT = 3;
/** Stills of the moment kept in a year's log, and issues back that keep theirs (older ones show the plinth). */
export const SHOTS = 4, PHOTO_ISSUES = 2;
/** The year in pictures: at most this many stills on the second page. */
export const GALLERY = 4;
/** Most events the log keeps before it folds; what it folds down to, by weight. */
const LOG_MAX = 300, LOG_FOLD = 120;
/** Issues kept in the save; template ids remembered for variety, issues back. */
const ISSUES_KEPT = 8;
const USED_BACK = 3;
/** Fleet sizes worth a story when crossed, and net worths. */
const UNIT_MARKS = [2, 5, 10, 20, 40];
const WORTH_MARKS = [10e3, 25e3, 50e3, 100e3, 250e3, 500e3, 1e6, 2.5e6, 5e6, 10e6];
/** Road tiles built in a year before it is news. */
const ROADS_NEWS = 20;
/** Minors and briefs at most, and at least for a full paper. */
const MINORS_MIN = 3, MINORS_D = 2, BRIEFS = 6, YOU_MINORS = 2;
/** Minors each full layout holds: A one a column, B and C two by two. */
const MINORS_OF: Record<Layout, number> = { A: 3, B: 4, C: 4, D: MINORS_D };
/** The headline's own year: at most this many of the same firm's or town's other news, told after it. */
const RELATED = 3;
/** Heard at the Inn: rumours, and one van after midnight. These kinds print only there. */
const INN_KINDS = new Set<Kind>(['rumour', 'nightRun']);
const INN_RUMOURS = 3;
/** The layouts a full paper turns through, by issue number; B (the tabloid) only with a still of the moment. */
const ROTATION: Layout[] = ['A', 'B', 'C'];
/** The Weather box's words for each weather. */
const WX_LABEL: Record<string, string> = {
  storm: 'Thunderstorms', blizzard: 'Blizzard', dust: 'Dust storms', mist: 'Fog', aurora: 'Aurora', rainbow: 'Rainbows', fireflies: 'Fireflies', rain: 'Rain', snow: 'Snow',
};

/** What a print chose, for the gate and the console: each article's event, in order, and the headline templates used. */
export interface Printed { issue: Issue; picked: PressEvent[]; briefs: PressEvent[]; related: PressEvent[]; inn: PressEvent[]; hids: string[]; gallery: PressEvent[] }

/**
 * The world this week's lines for the paper's box (server/worldWeek.ts, as the online server last sent them): set by
 * main.ts; none offline.
 */
export const pressWorld = { lines: (): string[] => [], honours: (): string[] => [] };

export class Desk {
  host: PressHost | null = null;
  log: PressEvent[] = [];
  readonly towns = new Map<string, TownInfo>();
  snap: Snapshot | null = null;
  issues: Issue[] = [];
  /** The game hour of the next press time; 0 until scheduled. */
  next = 0;
  readonly seen = new Set<string>();
  used: string[][] = [];
  papers: Record<string, number> = {};
  /** Game hours of each weather this year. */
  wx: Record<string, number> = {};
  /** News already written down that is told again and again (the week's picks), by key. */
  private onceKeys = new Set<string>();
  /** A big thing has just happened where the player is: main.ts takes a still of the next frame for it. */
  wantShot: PressEvent | null = null;
  /** The last print's choices (pr.press.log, the gate). */
  last: Printed | null = null;

  /** Write an event down. */
  write(i: LogIn): PressEvent | null {
    const h = this.host;
    if (!h) return null;
    const t = i.t ?? h.hours();
    const p = h.player();
    const at = i.at ?? (i.town ? h.townPos(i.town) : null);
    // nowhere given and no town: it happened where the player is
    const d = !p ? -1 : at ? Math.round(Math.hypot(at.x - p.x, at.z - p.z)) : i.town ? -1 : 0;
    const e: PressEvent = { k: i.k, t: Math.round(t * 10) / 10, who: i.who ?? '', d, w: i.w ?? WEIGHT[i.k], f: clean(i.f) };
    if (i.v) e.v = i.v;
    if (i.town) e.town = i.town;
    if (i.pic) e.pic = i.pic;
    this.log.push(e);
    if (this.log.length > LOG_MAX) this.fold();
    // a still of the moment, when the player is there to see it (not a backdated one, not the tavern's talk)
    if (i.t === undefined && e.w >= SHOT_WEIGHT && d >= 0 && d <= SHOT_NEAR && !INN_KINDS.has(e.k) && (!this.wantShot || this.wantShot.w < e.w)) this.wantShot = e;
    return e;
  }

  /** Write it down only the first time this key is seen (and remember the key in the save). */
  once(key: string, i: LogIn): PressEvent | null {
    if (this.onceKeys.has(key)) return null;
    this.onceKeys.add(key);
    if (this.onceKeys.size > 800) this.onceKeys.delete(this.onceKeys.values().next().value!);
    return this.write(i);
  }

  /** The still main.ts took for `wantShot`: kept on the event, the year keeping its SHOTS weightiest. */
  shot(e: PressEvent, jpg: string): void {
    if (this.wantShot === e) this.wantShot = null;
    if (!this.log.includes(e)) return;
    e.jpg = jpg;
    const with_ = this.log.filter((q) => q.jpg).sort((a, b) => b.w - a.w || b.t - a.t);
    for (const q of with_.slice(SHOTS)) delete q.jpg;
  }

  /** Weather seen where the player is, for the Weather box: game hours of it. */
  weather(kind: string, hours: number): void {
    if (hours > 0) this.wx[kind] = (this.wx[kind] ?? 0) + hours;
  }

  /** The player dealt with a town (a delivery, a stop, a purchase): it may publish this year's paper. */
  dealt(key: string, n = 1): void {
    const info = this.host?.townInfo(key);
    const had = this.towns.get(key);
    if (info) this.towns.set(key, { ...info, n: (had?.n ?? 0) + n });
    else if (had) had.n += n;
  }

  /** The hour of the next press: 07:00 on the first day of the next year. */
  static after(hours: number): number {
    const y = Math.floor(hours / YEAR_H);
    const thisYear = y * YEAR_H + PRESS_HOUR;
    return hours < thisYear ? thisYear : (y + 1) * YEAR_H + PRESS_HOUR;
  }

  /** Once a frame in play: print when the hour has come. */
  update(hours: number): void {
    const h = this.host;
    if (!h) return;
    this.snap ??= h.snapshot();
    if (!this.next) this.next = Desk.after(hours);
    if (hours < this.next) return;
    const done = this.press(hours);
    this.next = Desk.after(hours);
    if (done) h.printed(done.issue);
  }

  /** Score one event: 0 when it isn't local news. */
  score(e: PressEvent): number {
    const wire = e.k === 'wire' ? (e.v === 'world' ? (e.w >= WORLD_WEIGHT ? WORLD_NEAR : 0) : WIRE_NEAR[e.v ?? ''] ?? 0) : null;
    // the Fleet of the Year is the paper's own: news wherever the fleet is
    const near = e.k === 'award' ? 1 : wire !== null ? (e.v === 'county' && e.d >= 0 && e.d <= NEAR ? 1 : wire) : e.who === 'you' ? 1
      : e.d >= 0 && e.d <= NEAR ? 1
        : e.d >= 0 && e.d <= LOCAL ? 0.7
          : e.town && this.towns.has(e.town) ? 0.5 : 0;
    if (!near) return 0;
    const usedK = this.used.flat().filter((id) => id.includes('.h') && id.split('.')[0] === e.k).length;
    const novelty = !this.seen.has(e.k) ? 2 : usedK >= 3 ? 0.5 : 1;
    const inv = e.who === 'you' ? 1.5 : e.who ? 1.2 : 1;
    return e.w * near * novelty * inv;
  }

  /**
   * Print the year's paper. `dry`: build it from the log as it stands without consuming anything (the console,
   * the gate's previews). Null when the year is too thin to print; its events wait for the next.
   */
  press(hours: number, dry = false): Printed | null {
    const h = this.host;
    if (!h) return null;
    const fleet = h.fleet() || 'The fleet';
    const now = h.snapshot();
    const since = this.issues[this.issues.length - 1]?.t ?? -Infinity;
    const sport = h.sport?.() ?? null;
    const synth = [...(this.snap ? this.deltas(this.snap, now, hours) : []), ...this.champions(sport, since, hours), ...this.awards(this.log, fleet, h.county(), hours)];
    // a building bought to be the HQ is one story, the HQ's, not two
    const hqs = this.log.filter((e) => e.k === 'hq');
    const all = merge([...this.log, ...synth].filter((e) => e.k !== 'deedBought' || !hqs.some((q) => q.who === e.who && q.f.building === e.f.building && Math.abs(q.t - e.t) < 1)));
    const first = this.issues.length === 0;
    // the first paper waits for two game days of the company (docs/newspaper.html, The year)
    if (first && !dry && hours - h.founded() < 2 * DAY_H) { this.rollOver(now); return null; }

    // the headlines and bodies of the last few issues, oldest lowest: a choice goes to the longest unused
    const avoid = new Map<string, number>();
    this.used.forEach((ids, i) => { for (const id of ids) avoid.set(id, i + 1); });
    const scored = all.filter((e) => !INN_KINDS.has(e.k)).map((e) => ({ e, s: this.score(e) })).filter((x) => x.s > 0)
      .sort((a, b) => b.s - a.s || b.e.t - a.e.t);
    const told = new Map<PressEvent, Told>();
    const tell = (e: PressEvent): Told | null => {
      if (told.has(e)) return told.get(e)!;
      const c = compose(e, fleet, avoid);
      if (c) told.set(e, c);
      return c;
    };
    // a headline and a body are spent only when they print: the headline story's and the minors'
    const spend = (e: PressEvent) => { const c = told.get(e); if (c) { avoid.set(c.hid, 1e9); avoid.set(c.bid, 1e9); } };
    const strong = scored.filter((x) => x.e.w >= 2 && tplOk(x.e));
    if (!strong.length) { if (!dry) this.rollOver(now); return null; }

    // the headline: the founding, the first time; else the best that fills
    const founding = first ? scored.find((x) => x.e.k === 'founded') : undefined;
    const order = founding ? [founding, ...scored.filter((x) => x !== founding)] : scored;
    let lead: PressEvent | null = null;
    for (const x of order) if (tell(x.e)) { lead = x.e; break; }
    if (!lead) { if (!dry) this.rollOver(now); return null; }
    spend(lead);

    // the minors: no two of a kind (nor the headline's), at most two about the player, a town or the world when it rates
    const minors: PressEvent[] = [];
    const kinds = new Set<string>([kindOf(lead)]);
    const wantFull = strong.length >= 3;
    // the layout turns with the issue number; the tabloid only when the headline has a still of the moment
    const n = (this.issues[this.issues.length - 1]?.n ?? 0) + 1;
    const turn = ROTATION[(n - 1) % ROTATION.length];
    const fullAs: Layout = turn === 'B' && !lead.jpg ? 'A' : turn;
    const cap = wantFull ? MINORS_OF[fullAs] : MINORS_D;
    // two passes: the player's own news at most twice while there is other news to tell; then, if the
    // year was all the player's, as much of theirs as a full page wants
    for (const limit of [YOU_MINORS, Infinity]) {
      for (const x of scored) {
        if (minors.length >= cap) break;
        const e = x.e;
        // no two of a kind: the wire's stories are each of their desk's kind (a crown and a lap record are two), and only
        // one of them from further afield
        if (e === lead || kinds.has(kindOf(e))) continue;
        if (e.k === 'wire' && e.v === 'world' && minors.filter((m) => m.k === 'wire' && m.v === 'world').length >= WORLD_MINORS) continue;
        if (e.who === 'you' && minors.filter((m) => m.who === 'you').length >= limit) continue;
        if (!tell(e)) continue;
        minors.push(e);
        kinds.add(kindOf(e));
        spend(e);
      }
      if (minors.length >= MINORS_MIN) break;
    }
    if (minors.length && !minors.some((m) => m.who !== 'you')) {
      const other = scored.find((x) => x.e !== lead && x.e.who !== 'you' && x.s > 2 && !kinds.has(kindOf(x.e)) && tell(x.e));
      if (other) { minors[minors.length - 1] = other.e; spend(other.e); }
    }
    const full = wantFull && minors.length >= MINORS_MIN;
    if (!full) minors.length = Math.min(minors.length, MINORS_D);
    const layout: Layout = full ? fullAs : 'D';

    // the headline's story goes on with the rest of its year: the same firm's or the same town's other news
    const related: PressEvent[] = [];
    for (const x of scored) {
      if (related.length >= RELATED) break;
      const e = x.e;
      if (e === lead || minors.includes(e)) continue;
      const same = (lead.who && e.who === lead.who) || (lead.town && e.town === lead.town);
      if (same && tell(e)) related.push(e);
    }

    // the briefs: what is left, a line each, no line twice
    const briefs: PressEvent[] = [];
    const lines = new Set<string>();
    for (const x of scored) {
      if (briefs.length >= BRIEFS) break;
      if (x.e === lead || minors.includes(x.e) || related.includes(x.e)) continue;
      const c = tell(x.e);
      if (!c || lines.has(c.brief)) continue;
      lines.add(c.brief);
      briefs.push(x.e);
    }

    // Heard at the Inn: the tavern talk of the towns near, one line a town, and a van after midnight
    const inn: PressEvent[] = [];
    const innTowns = new Set<string>();
    for (const e of all.filter((q) => q.k === 'rumour' && this.score(q) > 0).sort((a, b) => b.t - a.t)) {
      if (inn.length >= INN_RUMOURS) break;
      const key = String(e.f.town ?? '');
      if (innTowns.has(key) || !tell(e)) continue;
      innTowns.add(key);
      inn.push(e);
    }
    const van = all.filter((q) => q.k === 'nightRun').sort((a, b) => b.t - a.t)[0];
    if (van && tell(van)) inn.push(van);

    // the paper: whose it is, and its people
    const pub = publisher([...this.towns.values()], h.newsTowns());
    const paper = paperFor(pub, pub?.county || h.county() || 'the county');
    const year = Math.max(1, Math.floor(hours / YEAR_H));
    const est = this.papers[paper.key || `county:${paper.county}`] ?? year;
    const article = (e: PressEvent, i: number): Article => {
      const c = told.get(e)!;
      const a: Article = {
        k: e.k, ...(e.k === 'wire' && e.f.desk ? { desk: String(e.f.desk) } : {}), head: c.head, body: c.body, by: paper.staff[i % paper.staff.length], hid: c.hid,
        page: 2 + (hashString(`${c.hid}|${e.t}`) % 11),
        mark: e.who === 'you' ? fleet : e.who || String(e.f.town ?? e.f.county ?? paper.city),
      };
      if (e.pic) a.pic = e.pic;
      if (e.jpg) a.photo = e.jpg;
      if (e.pic || e.jpg) a.cap = c.brief;
      return a;
    };
    const wxEvents = all.filter((e) => e.k === 'weather' && this.score(e) > 0).sort((a, b) => b.w - a.w || a.t - b.t);
    const worst = wxEvents[0];
    const lead0 = article(lead, 0);
    if (related.length) lead0.body.push(`Also this year: ${related.map((e) => told.get(e)!.brief).join(' ')}`);
    const rung = h.rung?.() ?? 3;
    lead0.body = toned(lead0.body, fleet, rung, paper.key ? paper.city : '');
    const issue: Issue = {
      n, t: Math.round(hours * 10) / 10, year,
      from: Math.max(1, Math.min(year, ...[lead, ...minors].map((e) => Math.floor(e.t / YEAR_H) + 1))),
      layout, paper, est, price: 1 + year,
      ear: worst ? tell(worst)?.brief ?? `${paper.county} edition` : `${paper.county} edition`,
      lead: lead0, minors: minors.map((e, i) => article(e, i + 1)), briefs: briefs.map((e) => told.get(e)!.brief),
      ...(rung !== 3 ? { tone: rung } : {}),
    };
    // the wire's stories that made no article: the year's biggest from further afield, and the neighbours'
    const printed = new Set<PressEvent>([lead, ...minors, ...related, ...briefs]);
    const wireLines = (v: string, most: number) => all.filter((e) => e.k === 'wire' && e.v === v && !printed.has(e)).sort((a, b) => b.w - a.w || b.t - a.t).slice(0, most)
      .map((e) => tell(e)?.brief).filter((x): x is string => !!x);
    const ago = this.issues[this.issues.length - 1];
    const boxes = this.boxes(sport, now, fleet, inn.map((e) => told.get(e)!.brief), worst ? told.get(worst)?.brief : undefined,
      { afield: wireLines('world', 4), circle: wireLines('circle', 4), ...(ago ? { ago: { head: ago.lead.head, year: ago.year } } : {}), n });
    if (boxes) issue.boxes = boxes;
    // the year in pictures: the stills the front page didn't use, weightiest first, each with its own line
    const shots = all.filter((e) => e.jpg && e !== lead && this.score(e) > 0 && tell(e)).sort((a, b) => b.w - a.w || a.t - b.t).slice(0, GALLERY)
      .sort((a, b) => a.t - b.t);
    const gallery = shots.map((e) => ({ photo: e.jpg!, cap: told.get(e)!.brief, when: `Day ${Math.floor(e.t / DAY_H) + 1}, ${['spring', 'summer', 'autumn', 'winter'][Math.floor(e.t / DAY_H) % 4]}` }));
    if (gallery.length) issue.gallery = gallery;
    const out: Printed = { issue, picked: [lead, ...minors], briefs, related, inn, hids: [lead, ...minors].map((e) => told.get(e)!.hid), gallery: shots };
    this.last = out;
    if (dry) return out;

    // consumed: the year's log, the towns dealt with, the weather, the template ids for variety
    this.issues.push(issue);
    if (this.issues.length > ISSUES_KEPT) this.issues.splice(0, this.issues.length - ISSUES_KEPT);
    // only the newest issues keep their stills; older ones fall back to the plinth
    for (const old of this.issues.slice(0, -PHOTO_ISSUES)) { for (const a of [old.lead, ...old.minors]) delete a.photo; delete old.gallery; }
    for (const e of [lead, ...minors]) this.seen.add(e.k);
    this.used.push([lead, ...minors].flatMap((e) => [told.get(e)!.hid, told.get(e)!.bid]));
    if (this.used.length > USED_BACK) this.used.splice(0, this.used.length - USED_BACK);
    this.papers[paper.key || `county:${paper.county}`] ??= year;
    this.log = [];
    this.towns.clear();
    this.wx = {};
    this.wantShot = null;
    this.snap = now;
    return out;
  }

  /**
   * The standing boxes, each only when the year filled it; undefined when none did. The Ledger is always the
   * company's, and the Inn always prints its talk (rumours print nowhere else); of the others (Sport, Weather, the
   * World This Week, From further afield, the neighbours' year, Honours, A year ago) a paper prints BOXES, turning
   * with the issue number so each year's foot differs.
   */
  boxes(sport: SportNow | null, now: Snapshot, fleet: string, inn: string[], worst?: string, more: { afield?: string[]; circle?: string[]; ago?: { head: string; year: number }; n?: number } = {}): Boxes | undefined {
    const b: Boxes = {};
    if (sport && sport.rows.length) {
      b.sport = { league: sport.league, season: sport.season, rows: sport.rows.slice(0, 3) };
      if (sport.home) b.sport.home = `${sport.home.name}: ${ordinal(sport.home.pos)} of ${sport.home.of}`;
    }
    const wxRows = Object.entries(this.wx).filter(([, hrs]) => hrs >= 0.5).sort((a, b2) => b2[1] - a[1]).slice(0, 5)
      .map(([k, hrs]) => [WX_LABEL[k] ?? k, Math.round(hrs)] as [string, number]);
    if (wxRows.length) b.weather = { rows: wxRows, ...(worst ? { worst } : {}) };
    const was: LedgerNumbers = this.snap?.book ?? { deliveries: 0, takings: 0, units: 1, doors: 0, held: 0, worth: 0 };
    const is = now.book;
    if (is) {
      const n = (v: number) => Math.round(v).toLocaleString('en-US');
      b.ledger = {
        fleet,
        rows: [
          ['Deliveries', n(was.deliveries), n(is.deliveries)],
          ['Takings', moneyText(was.takings), moneyText(is.takings)],
          ['Vehicles', n(was.units), n(is.units)],
          ['Doors', n(was.doors), n(is.doors)],
          ['Towns carried', n(was.held), n(is.held)],
          ['Net worth', moneyText(was.worth), moneyText(is.worth)],
        ],
      };
      if (now.rival) b.ledger.rival = `Best-placed rival: ${now.rival.name}, ${now.rival.units} vehicle${now.rival.units === 1 ? '' : 's'}, worth ${moneyText(now.rival.worth)}.`;
    }
    if (inn.length) b.inn = inn;
    const world = pressWorld.lines().slice(0, 5);
    if (world.length) b.world = world;
    if (more.afield?.length) b.afield = more.afield;
    if (more.circle?.length) b.circle = more.circle;
    const honours = pressWorld.honours().slice(0, 5);
    if (honours.length) b.honours = honours;
    if (more.ago) b.ago = more.ago;
    // the turn: the rotating boxes the year filled, BOXES of them from where this issue's number starts
    const ROT = ['sport', 'weather', 'world', 'afield', 'circle', 'honours', 'ago'] as const;
    const have = ROT.filter((k) => b[k] !== undefined);
    if (have.length > BOXES) {
      const from = (more.n ?? 1) % have.length;
      const keep = new Set(Array.from({ length: BOXES }, (_, i) => have[(from + i) % have.length]));
      for (const k of have) if (!keep.has(k)) delete b[k];
    }
    return Object.keys(b).length ? b : undefined;
  }

  /**
   * Fleet of the Year: the fleet the year's wire told of most (weighted by each story's size), in the world and in
   * the county, when it made the wire often enough; the player's own fleet when it was them. League scores are the
   * clubs', not a fleet's, and don't count.
   */
  awards(log: PressEvent[], fleet: string, county: string, hours: number): PressEvent[] {
    const wire = log.filter((e) => e.k === 'wire' && typeof e.f.by === 'string' && e.f.by && e.f.desk !== 'Sport');
    const top = (list: PressEvent[], least: number) => {
      const by = new Map<string, { n: number; w: number; best: PressEvent }>();
      for (const e of list) {
        const k = String(e.f.by), had = by.get(k) ?? { n: 0, w: 0, best: e };
        had.n++; had.w += e.w;
        if (e.w > had.best.w) had.best = e;
        by.set(k, had);
      }
      const win = [...by.entries()].filter(([, v]) => v.n >= least).sort((a, b) => b[1].w - a[1].w || b[1].n - a[1].n || (a[0] < b[0] ? -1 : 1))[0];
      return win ? { by: win[0], ...win[1] } : null;
    };
    const t = Math.round((hours - 1) * 10) / 10, out: PressEvent[] = [];
    const world = top(wire, AWARD_N);
    if (world) out.push({ k: 'award', v: 'world', t, who: world.by === fleet ? 'you' : world.by, d: -1, w: WEIGHT.award, f: clean({ by: world.by, n: world.n, best: String(world.best.f.title ?? '') }) });
    const local = top(wire.filter((e) => e.v === 'county' || e.v === 'you'), AWARD_COUNTY_N);
    if (local && local.by !== world?.by && county) out.push({ k: 'award', v: 'county', t, who: local.by === fleet ? 'you' : local.by, d: 0, w: WEIGHT.award - 1, f: clean({ by: local.by, n: local.n, best: String(local.best.f.title ?? ''), county }) });
    return out;
  }

  /** The champions' story, when the league round the nearest stadium finished a season since the last paper. */
  champions(s: SportNow | null, since: number, hours: number): PressEvent[] {
    if (!s || !s.rows.length || s.ended <= since || s.ended > hours) return [];
    const f: Fields = { league: s.league, champion: s.rows[0].name, record: s.rows[0].rec, season: s.season };
    if (s.rows[1]) { f.runnerUp = s.rows[1].name; if (s.margin > 0) f.margin = s.margin; }
    return [{ k: 'season', ...(s.homeWon ? { v: 'home' } : {}), t: Math.round(s.ended * 10) / 10, who: '', d: 0, w: s.homeWon ? 4 : WEIGHT.season, f }];
  }

  /** A year too thin to print: its events wait for the next, the snapshot stays where it was. */
  private rollOver(now: Snapshot): void { this.snap ??= now; }

  /** Growth since the last paper, read from two snapshots: the fleets' sizes, the company's worth, its roads. */
  deltas(a: Snapshot, b: Snapshot, hours: number): PressEvent[] {
    const t = Math.round((hours - 1) * 10) / 10, out: PressEvent[] = [];
    const h = this.host;
    const p = h?.player() ?? null;
    if (b.units > a.units && (b.units - a.units >= 2 || UNIT_MARKS.some((m) => a.units < m && b.units >= m))) {
      out.push({ k: 'fleetSize', t, who: 'you', d: 0, w: WEIGHT.fleetSize, f: { from: a.units, to: b.units, grown: b.units - a.units } });
    }
    for (const [name, now] of Object.entries(b.firms)) {
      const was = a.firms[name];
      if (!was || now.units - was.units < 2) continue;
      const at = now.key ? h?.townPos(now.key) ?? null : null;
      const d = p && at ? Math.round(Math.hypot(at.x - p.x, at.z - p.z)) : -1;
      out.push({ k: 'fleetSize', t, who: name, d, w: WEIGHT.fleetSize, f: clean({ from: was.units, to: now.units, grown: now.units - was.units, firm: name, town: now.town }), ...(now.key ? { town: now.key } : {}) });
    }
    const crossed = WORTH_MARKS.filter((m) => a.worth < m && b.worth >= m).pop();
    if (crossed) out.push({ k: 'worth', t, who: 'you', d: 0, w: WEIGHT.worth, f: { mark: crossed, worth: Math.round(b.worth) } });
    const tiles = b.roads[0] - a.roads[0];
    if (tiles >= ROADS_NEWS) {
      const f: Fields = { tiles };
      if (b.roads[1] > a.roads[1]) f.bridges = b.roads[1] - a.roads[1];
      if (b.roads[2] > a.roads[2]) f.tunnels = b.roads[2] - a.roads[2];
      out.push({ k: 'roadsBuilt', t, who: 'you', d: 0, w: tiles >= 200 ? 3 : WEIGHT.roadsBuilt, f });
    }
    return out;
  }

  /** Too many events: keep the weightiest (and the founding) and the newest of the rest. */
  private fold(): void {
    const keep = new Set([...this.log].sort((a, b) => b.w - a.w || b.t - a.t).slice(0, LOG_FOLD));
    this.log = this.log.filter((e) => keep.has(e) || e.k === 'founded');
  }

  // ---- saving ---------------------------------------------------------------------------------------

  toSave(): PressSave {
    return {
      log: this.log, snap: this.snap, towns: [...this.towns.values()], issues: this.issues, next: this.next,
      seen: [...this.seen], used: this.used, papers: this.papers, wx: this.wx, once: [...this.onceKeys],
    };
  }

  /** A save's desk, or an empty one (a new game, a save from before the paper). True when the save had one. */
  load(s: PressSave | null | undefined): boolean {
    this.reset();
    if (!s) return false;
    this.log = Array.isArray(s.log) ? s.log.filter((e) => e && typeof e.k === 'string' && typeof e.t === 'number') : [];
    this.snap = s.snap ?? null;
    for (const t of s.towns ?? []) if (t?.key) this.towns.set(t.key, t);
    this.issues = Array.isArray(s.issues) ? s.issues.slice(-ISSUES_KEPT) : [];
    this.next = typeof s.next === 'number' ? s.next : 0;
    for (const k of s.seen ?? []) this.seen.add(k);
    this.used = Array.isArray(s.used) ? s.used.slice(-USED_BACK) : [];
    this.papers = { ...(s.papers ?? {}) };
    this.wx = { ...(s.wx ?? {}) };
    for (const k of s.once ?? []) this.onceKeys.add(k);
    return true;
  }

  reset(): void {
    this.log = [];
    this.towns.clear();
    this.snap = null;
    this.issues = [];
    this.next = 0;
    this.seen.clear();
    this.used = [];
    this.papers = {};
    this.wx = {};
    this.onceKeys.clear();
    this.wantShot = null;
    this.last = null;
  }

  /** An issue by number. */
  issue(n: number): Issue | null { return this.issues.find((i) => i.n === n) ?? null; }
}

/** "A", "A and B", "A, B and C", "A, B, C and 2 more". */
export function names(list: string[], most = 3): string {
  const u = [...new Set(list.filter(Boolean))];
  if (u.length <= 1) return u[0] ?? '';
  if (u.length <= most) return `${u.slice(0, -1).join(', ')} and ${u[u.length - 1]}`;
  return `${u.slice(0, most).join(', ')} and ${u.length - most} more`;
}

/**
 * Many small things as one story: every guestbook signature of the year as one visit, every heart as one tally;
 * and the same news told twice (a town won in play, then again by the server's away news) as once.
 */
export function merge(list: PressEvent[]): PressEvent[] {
  const out: PressEvent[] = [];
  const seen = new Set<string>();
  const pile = new Map<string, PressEvent[]>();
  for (const e of list) {
    if (e.k === 'guest' || e.k === 'hearts') { const g = pile.get(e.k) ?? []; g.push(e); pile.set(e.k, g); continue; }
    if (e.k === 'territoryWon' || e.k === 'territoryLost') {
      const key = `${e.k}|${e.who}|${e.f.town}|${Math.floor(e.t / DAY_H)}`;
      if (seen.has(key)) continue;
      seen.add(key);
    }
    out.push(e);
  }
  for (const [k, g] of pile) {
    const n = g.reduce((s, e) => s + (typeof e.f.n === 'number' ? e.f.n : 1), 0);
    const last = g[g.length - 1];
    const f: Fields = { n, by: names(g.flatMap((e) => String(e.f.by ?? '').split(/, | and /)).filter((x) => x && !/^\d+ more$/.test(x))) };
    const work = g.map((e) => e.f.work).find(Boolean);
    if (work) f.work = work;
    const big = k === 'hearts' ? n >= 10 : n >= 3;
    const e: PressEvent = { k: k as Kind, t: last.t, who: 'you', d: 0, w: big ? WEIGHT[k as Kind] + 1 : WEIGHT[k as Kind], f: clean(f) };
    if (n === 1) e.v = 'one';
    const jpg = g.find((q) => q.jpg)?.jpg;
    if (jpg) e.jpg = jpg;
    out.push(e);
  }
  return out;
}

/** Drop empty and non-finite fields: a field that isn't there is a template passed over, never "undefined". */
function clean(f: Fields): Fields {
  const out: Fields = {};
  for (const [k, v] of Object.entries(f)) {
    if (v === undefined || v === null || v === '') continue;
    if (typeof v === 'number' && !Number.isFinite(v)) continue;
    out[k] = typeof v === 'string' ? v.trim() : v;
  }
  return out;
}

/** An event's kind for "no two of a kind": the wire's stories go by their desk (Crowns, Records desk, Territory…). */
export const kindOf = (e: { k: Kind; f: Fields }): string => (e.k === 'wire' ? `wire:${e.f.desk ?? ''}` : e.k);

/** Whether an event's kind has any copy at all (a kind with none never counts toward a full paper). */
const tplOk = (e: PressEvent): boolean => !!compose(e, 'x');

export { whoClass };

/** The one desk the game keeps. */
export const press = new Desk();
