import * as THREE from 'three';
import type { Build, Kit } from '../vehicleMeshes';

/** The factions' vehicles, group B (docs/factions.html): a model not drawn yet borrows a similar body (vehicleMeshes STAND_IN). */

// (a box's y is its middle; front is +z; every main panel is in d.color so resprays and paintjobs find it)
const WHITE = 0xf4f2ec, STEEL = 0x5b6168, CHASSIS = 0x3a3f45, HUB = 0xc9c9cd, RED = 0xe2412f, GOLD = 0xf2c12e;
const CARD = 0xc49a6c, CARD2 = 0xd9b07a, MINT = 0x8ef0c8;

/** An open half-cylinder lying along z, its arch up: a canvas tilt's roof. `flat` squashes the arch. */
function arch(r: number, len: number, flat: number, open: boolean): THREE.BufferGeometry {
  const g = new THREE.CylinderGeometry(r, r, len, 8, 1, open, Math.PI / 2, Math.PI);
  g.rotateX(Math.PI / 2);
  g.scale(1, flat, 1);
  return g;
}

/** A lattice-free crane hook: a little block on its cable and the open hook under it. */
function hook(k: Kit, parent: THREE.Object3D, x: number, yTop: number, z: number, drop: number): void {
  k.box(parent, 0.012, drop, 0.012, k.dark(), x, yTop - drop / 2, z);
  k.box(parent, 0.07, 0.08, 0.05, 0xf2c14e, x, yTop - drop - 0.04, z);
  k.box(parent, 0.02, 0.04, 0.02, k.chrome(), x, yTop - drop - 0.1, z);
  const h = k.add(parent, new THREE.TorusGeometry(0.032, 0.011, 4, 8, Math.PI * 1.4), k.chrome(), x, yTop - drop - 0.15, z);
  h.rotation.y = Math.PI / 2;
  h.rotation.x = Math.PI * 0.8;
}

