/** The cement mixer: a cab forward, a big drum tilted up to the tail with two spiral stripes, turning slowly; hopper, chute and ladder behind. */
const mixer: Build = (k, b, d) => {
  const p = d.color;
  k.box(b, 0.62, 0.14, 1.4, CHASSIS, 0, 0.3, 0);
  // the cab, its lower part tucked between the front wheels, fenders over them
  k.box(b, 0.66, 0.4, 0.32, p, 0, 0.66, 0.54);
  k.box(b, 0.5, 0.1, 0.32, p, 0, 0.41, 0.54);
  k.cabinGlass(b, 0.66, 0.26, 0.32, 0.75, 0.54);
  for (const sx of [-1, 1]) {
    k.box(b, 0.2, 0.03, 0.46, p, sx * 0.36, 0.46, 0.5);
    k.box(b, 0.04, 0.04, 0.06, k.dark(), sx * 0.35, 0.74, 0.7);
    k.box(b, 0.16, 0.025, 0.6, k.dark(), sx * 0.34, 0.465, -0.41);
  }
  k.box(b, 0.46, 0.14, 0.03, k.chrome(), 0, 0.53, 0.705);
  k.box(b, 0.7, 0.08, 0.06, k.dark(), 0, 0.28, 0.71);
  // the water tank behind the cab and the drum's front pedestal
  k.cyl(b, 0.07, 0.07, 0.5, 8, WHITE, 0, 0.47, 0.33, 'x');
  k.box(b, 0.3, 0.12, 0.08, STEEL, 0, 0.43, 0.2);
  // the drum: a tilted cradle, and inside it the drum itself turning on its own axis
  const cradle = k.group(b, 0, 0.74, -0.2);
  cradle.rotation.x = 0.16;
  const drum = k.group(cradle);
  drum.name = 'drum';
  k.cyl(drum, 0.3, 0.3, 0.44, 12, p, 0, 0, 0, 'z');
  k.cyl(drum, 0.14, 0.3, 0.18, 12, p, 0, 0, 0.31, 'z');
  k.cyl(drum, 0.3, 0.12, 0.26, 12, p, 0, 0, -0.35, 'z');
  k.cyl(drum, 0.13, 0.13, 0.03, 10, k.dark(), 0, 0, -0.485, 'z');
  // two spiral stripes wound round the drum, so its turning shows
  for (const s of [0, Math.PI]) {
    for (let i = 0; i < 13; i++) {
      const t = i / 12;
      const g = k.group(drum, 0, 0, -0.2 + 0.4 * t);
      g.rotation.z = s + t * Math.PI * 0.9;
      k.box(g, 0.1, 0.02, 0.06, WHITE, 0, 0.3, 0).rotation.y = 0.44;
    }
  }
  k.spin(drum, 'z', 2.2);
  // the rear frame the drum rides on, the charge hopper above its mouth and the chute below
  for (const sx of [-1, 1]) k.box(b, 0.05, 0.3, 0.05, STEEL, sx * 0.22, 0.52, -0.5);
  k.box(b, 0.5, 0.05, 0.05, STEEL, 0, 0.66, -0.5);
  k.cyl(b, 0.11, 0.05, 0.14, 8, STEEL, 0, 0.98, -0.62);
  k.cyl(b, 0.07, 0.05, 0.08, 8, STEEL, 0, 0.7, -0.66);
  const chute = k.group(b, 0, 0.66, -0.68);
  chute.rotation.x = -1.05;
  k.box(chute, 0.14, 0.015, 0.22, STEEL, 0, 0, -0.11);
  for (const sx of [-1, 1]) k.box(chute, 0.015, 0.05, 0.22, STEEL, sx * 0.07, 0.025, -0.11);
  // the ladder up the tail to the hopper
  for (const sx of [-1, 1]) k.box(b, 0.015, 0.56, 0.015, k.dark(), 0.2 + sx * 0.05, 0.62, -0.69);
  for (let i = 0; i < 5; i++) k.box(b, 0.1, 0.012, 0.012, k.dark(), 0.2, 0.4 + i * 0.11, -0.69);
  k.box(b, 0.66, 0.08, 0.06, k.dark(), 0, 0.28, -0.7);
  k.lights(b, 0.22, 0.42, 0.705, -0.715);
  for (const sx of [-1, 1]) {
    k.wheel(b, 0.22, 0.18, sx * 0.36, 0.22, 0.5, true);
    k.wheel(b, 0.22, 0.24, sx * 0.34, 0.22, -0.28);
    k.wheel(b, 0.22, 0.24, sx * 0.34, 0.22, -0.54);
  }
};

