  // the turret: slewing ring, housing, the operator's little cab and the counterweight
  k.cyl(b, 0.24, 0.24, 0.06, 12, STEEL, 0, 0.45, -0.52);
  k.box(b, 0.46, 0.2, 0.42, p, 0, 0.58, -0.55);
  k.box(b, 0.52, 0.18, 0.14, CHASSIS, 0, 0.6, -0.78);
  k.box(b, 0.16, 0.22, 0.22, p, 0.23, 0.79, -0.42);
  k.box(b, 0.14, 0.12, 0.01, k.glass(), 0.23, 0.82, -0.305);
  k.box(b, 0.01, 0.12, 0.16, k.glass(), 0.312, 0.82, -0.42);
  for (const sx of [-1, 1]) k.box(b, 0.025, 0.2, 0.16, p, sx * 0.1, 0.76, -0.62);
  k.cyl(b, 0.03, 0.03, 0.24, 6, k.dark(), 0, 0.82, -0.62, 'x');
  // the boom rest behind the cab
  for (const sx of [-1, 1]) k.box(b, 0.035, 0.45, 0.035, STEEL, sx * 0.11, 0.64, 0.46);
  k.box(b, 0.26, 0.04, 0.06, STEEL, 0, 0.87, 0.46);
  // the boom, three sections telescoped in, pivoting at the turret and lying forward over the cab
  const boom = k.group(b, 0, 0.84, -0.62);
  boom.name = 'boom';
  boom.rotation.x = -0.075;
  k.box(boom, 0.16, 0.14, 0.86, p, 0, 0, 0.43);
  k.box(boom, 0.12, 0.11, 0.42, p, 0, 0.005, 1.06);
  k.box(boom, 0.09, 0.08, 0.26, p, 0, 0.01, 1.38);
  k.box(boom, 0.17, 0.02, 0.6, k.dark(), 0, -0.075, 0.4);
  k.cyl(boom, 0.05, 0.05, 0.1, 8, STEEL, 0, 0, 1.5, 'x');
  k.cyl(b, 0.03, 0.03, 0.4, 6, k.chrome(), 0, 0.68, -0.15).rotation.x = 0.86;
  k.cyl(b, 0.045, 0.045, 0.2, 6, STEEL, 0, 0.62, -0.23).rotation.x = 0.86;
  hook(k, b, 0, 0.93, 0.89, 0.06);
  k.lights(b, 0.22, 0.42, 0.845, -0.86);
