/** The scout saucer: a silver disc a hand off the ground, a clear dome with its pilot, a ring of mint lights round the rim turning slowly. No wheels. */
const saucerScout: Build = (k, b, d) => {
  const p = d.color, glow = k.mat(MINT, 0.4, 0, MINT, 1.6), y = 0.24;
  const profile = [[0.001, -0.07], [0.2, -0.075], [0.4, -0.035], [0.48, 0], [0.45, 0.035], [0.3, 0.075], [0.18, 0.09], [0.001, 0.09]]
    .map(([r, h]) => new THREE.Vector2(r, h));
  k.add(b, new THREE.LatheGeometry(profile, 16), k.mat(p, 0.35, 0.45), 0, y, 0);
  // a dark seam round the rim, the glowing ring underneath and the drive's pod at its heart
  k.add(b, new THREE.TorusGeometry(0.47, 0.012, 3, 24), k.dark(), 0, y + 0.005, 0).rotation.x = Math.PI / 2;
  k.add(b, new THREE.TorusGeometry(0.24, 0.02, 3, 16), glow, 0, y - 0.075, 0).rotation.x = Math.PI / 2;
  k.cyl(b, 0.1, 0.13, 0.04, 10, CHASSIS, 0, y - 0.09, 0);
  // the dome, clear so the pilot shows, on a collar
  k.cyl(b, 0.2, 0.21, 0.03, 14, p, 0, y + 0.1, 0.03);
  k.ball(b, 0.06, 0x9fb8a8, 0, y + 0.18, 0.04, 1, 1.15, 1, 1);
  for (const sx of [-1, 1]) k.ball(b, 0.018, 0x101014, sx * 0.025, y + 0.19, 0.093, 1, 1.4, 0.6, 0);
  k.box(b, 0.1, 0.06, 0.07, 0x9fb8a8, 0, y + 0.13, 0.03);
  const domeMat = new THREE.MeshStandardMaterial({ color: 0xc8f2ea, roughness: 0.1, metalness: 0.2, transparent: true, opacity: 0.4, flatShading: true, depthWrite: false });
  k.add(b, new THREE.SphereGeometry(0.19, 12, 5, 0, Math.PI * 2, 0, Math.PI / 2), domeMat, 0, y + 0.115, 0.03).scale.y = 0.9;
  // the rim lights, turning round the disc
  const ring = k.group(b, 0, y, 0);
  ring.name = 'rimLights';
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    k.ball(ring, 0.032, glow, Math.sin(a) * 0.43, 0.035, Math.cos(a) * 0.43, 1, 0.7, 1, 0);
  }
  k.spin(ring, 'y', 1.5);
  // a lamp pair at the nose and a red one at the tail, so its heading reads
  for (const sx of [-1, 1]) k.box(b, 0.07, 0.03, 0.03, k.lamp(), sx * 0.09, y - 0.025, 0.43);
  k.box(b, 0.12, 0.025, 0.03, k.tail(), 0, y - 0.025, -0.43);
};

