import { N, Feature, World, idx, type BuildingKind } from './tiles';
import type { RegionSpec } from './regions';
import { cell01, hashCell, mulberry32 } from './rng';
import type { TownPlan } from './towns';
import type { WorkSite } from './industry';
import { cutAirbase } from './industry';
import { planWonder } from './wonders';
import { landformName } from './landforms';
import { INFO_080, type Kind080 } from './kinds080';

/**
 * The 0.8.0 world's big complexes (NEXT_080, docs/phonelist.html items 11, 17-20), each one lot of its own planned and
 * levelled the way a wonder is (world/wonders.ts planWonder), then stood up as a work of its own (kind 'resort', so a
 * paved road comes to its gate and nothing treats it as a wonder):
 *
 *   campus          a university's quads, library, halls, chapel and clock tower near a city (item 17)
 *   zooPark         a zoological park's habitats round a looping path near a city (item 11)
 *   schoolCastle    a great rambling castle-school of towers and spires on high ground over a lake (item 18)
 *   baronialCastle  a Highland country house of round turrets and crow-stepped gables, a terraced garden (item 18)
 *   ksarVillage     a desert village of domed houses, pit-court homes and stacked granaries (item 20)
 *
 * and the air force base (item 19): a real airfield (world/industry.ts cutAirbase), its runway, hangars and tower, with a
 * base headquarters, jets on the line and helipads in place of an airport's terminal and airliners.
 *
 * Each is rolled from the seed and the county alone and planned on a stream of its own, after the county's own works,
 * so a county that gets none is exactly what it was.
 */

const SALT = 0xc0c0;
type Roll = { kind: Kind080; chance: number; where: 'flat' | 'high'; fits: (c: Ctx) => boolean; name: (word: string) => string };
interface Ctx { w: World; plans: TownPlan[]; spec: RegionSpec | null; temp: number }

const CITY = (c: Ctx) => c.plans.some((p) => p.kind === 'city' || p.kind === 'metro' || p.kind === 'mega');
const DESERT_REGIONS = new Set(['sands', 'saltpan', 'redrock']);

const ROLLS: Roll[] = [
  { kind: 'campus', chance: 0.32, where: 'flat', fits: CITY, name: (a) => `${a} University` },
  { kind: 'zooPark', chance: 0.18, where: 'flat', fits: CITY, name: (a) => `${a} Zoo` },
  // the castles: cool, green, hilly country, a find
  { kind: 'schoolCastle', chance: 0.035, where: 'high', fits: (c) => c.temp < 0.86 && (!c.spec || c.spec.kind === 'moors' || c.spec.kind === 'heights'), name: (a) => `${a} Castle School` },
  { kind: 'baronialCastle', chance: 0.04, where: 'high', fits: (c) => c.temp < 0.88 && (!c.spec || c.spec.kind === 'moors' || c.spec.kind === 'heights' || c.spec.kind === 'fjords' || c.spec.kind === 'green'), name: (a) => `${a} Castle` },
  { kind: 'ksarVillage', chance: 0.16, where: 'flat', fits: (c) => !!c.spec && DESERT_REGIONS.has(c.spec.kind), name: (a) => `Ksar ${a}` },
];
/** The share of continent counties with an air force base. */
const AIRBASE_CHANCE = 0.04;

/**
 * Plan the county's complexes, carving and levelling their lots, and push their sites onto `works`. Returns the kinds
 * planned (for the county's stats).
 */
export function planComplexes(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, lakeLvl: Int8Array, plans: TownPlan[], works: WorkSite[],
  seedHash: number, spec: RegionSpec | null, band: number,
): string[] {
  const out: string[] = [];
  let temp = 0, n = 0;
  for (let i = 0; i < N * N; i += 11) if (land[i]) { temp += w.temp[i]; n++; }
  const c: Ctx = { w, plans, spec, temp: n ? temp / n : 1 };
  // an airfield's ground is taken while the complexes look for theirs: a zoo park stood between an international's
  // stands and its second runway (scripts/airports2.ts). Marked as airfield for the search, then given back.
  const lent: number[] = [];
  for (const s of works) {
    if (s.kind !== 'airfield') continue;
    const r = Math.ceil(s.len / 2) + 8;
    for (let z = Math.max(0, s.z - r); z < Math.min(N, s.z + r); z++) {
      for (let x = Math.max(0, s.x - r); x < Math.min(N, s.x + r); x++) {
        const i = idx(x, z);
        if (!w.feature[i]) { w.feature[i] = Feature.Airfield; lent.push(i); }
      }
    }
  }
  ROLLS.forEach((roll, k) => {
    if (cell01(seedHash, w.cx, w.cz, SALT + k) >= roll.chance || !roll.fits(c)) return;
    const [W, D] = INFO_080[roll.kind].size;
    const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 100 + k));
    const got = planWonder(w, land, E, river, lakeLvl, rng, { wonder: { kind: roll.kind as BuildingKind, name: [''], w: W, d: D, where: roll.where } } as Pick<RegionSpec, 'wonder'>, band);
    if (!got) return;
    const s = got.site;
    s.kind = 'resort';
    s.name = roll.name(landformName('wood', seedHash ^ (SALT + k), w.ox + s.x, w.oz + s.z));
    works.push(s);
    out.push(roll.kind);
  });
  for (const i of lent) w.feature[i] = 0;
  if (w.kind === 'continent' && cell01(seedHash, w.cx, w.cz, SALT + 50) < AIRBASE_CHANCE) {
    const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 150));
    const s = cutAirbase(w, land, E, river, rng, works);
    if (s) {
      s.name = `${landformName('wood', seedHash ^ (SALT + 50), w.ox + s.x, w.oz + s.z)} Air Force Base`;
      out.push('airbase');
    }
  }
  return out;
}

