/**
 * The most frames a second the game draws (0 for as many as the browser asks), kept on this device.
 *
 * 60 by default: drawing faster than that let finished frames pile up between the browser and the
 * graphics card, and every so often the card made everything wait half a second to catch up (on a
 * laptop whose screen hangs off a second, smaller GPU, 4 to 8 such pauses in four minutes of driving;
 * capped at 60, none — the lag audit, Oct 2026). Faster screens can lift it in Settings.
 */
const KEY = 'tinyfleet-fps-cap';
export const FPS_CHOICES = [30, 60, 0] as const;

function load(): number {
  try {
    const v = Number(localStorage.getItem(KEY));
    if ((FPS_CHOICES as readonly number[]).includes(v) && localStorage.getItem(KEY) !== null) return v;
  } catch { /* storage blocked: the default */ }
  return 60;
}

export const frameCap = {
  value: load(),
  set(v: number): void {
    this.value = v;
    try { localStorage.setItem(KEY, String(v)); } catch { /* kept for the session */ }
  },
};
