import * as THREE from 'three';
import { halfSize, isHelicopter, type AirDef, type VehicleDef } from '../game/vehicles';

/**
 * The shadows of the blimps, helicopters and planes flying about the island — the traffic's and the
 * player's own — as dark shapes laid on the ground, not cast in the sun's shadow map (the user, Oct 2026:
 * "shadows for blimps and other aircraft look like they're jumping every couple of seconds").
 *
 * The shadow map's light turns in steps (render/daynight.ts SUN_STEP, half a degree about every 0.8 s) so
 * that the edges of everything standing still don't shimmer. A thing on the ground hardly moves with a
 * step, but a blimp thirty units up throws its shadow half a unit at each one, and at sunrise several
 * times that. These follow the sun's smooth path instead (DayNight.smoothDir), down its ray to the first
 * ground or roof it meets, as the jets' shadows overhead already did (render/skyLayer.ts PlaneShadow), and
 * so they glide. Each is the craft's own outline: a blimp's envelope, a helicopter's body and rotor disc,
 * a plane's fuselage and wings.
 */

/** Below this height above the ground a shadow is the craft's own business (landed): drawn under it all the same. */
const TOO_HIGH = 120;

export interface AirBody {
  /** Stable while the craft is about (its agent, or the player's mesh). */
  key: object;
  def: AirDef;
  /** World tiles, and the craft's heading. */
  x: number; y: number; z: number; heading: number;
  /** Its mesh, which stops casting into the shadow map while this draws its shadow. */
  root: THREE.Object3D;
}

/** The outline a craft throws, laid flat with its nose along +z, in world units. */
function outline(def: AirDef): THREE.BufferGeometry {
  const [hl, hw] = halfSize(def as VehicleDef);
  const L = hl * 2, S = hw * 2;
  const shape = new THREE.Shape();
  if (isHelicopter(def)) {
    // the rotor's disc, and the body and tail boom under it
    const r = Math.max(L, S) * 0.55;
    shape.absellipse(0, L * 0.05, r, r, 0, Math.PI * 2, false, 0);
    const body = new THREE.Path();
    body.absellipse(0, 0, S * 0.22, L * 0.3, 0, Math.PI * 2, false, 0);
    const g = new THREE.ShapeGeometry([shape, new THREE.Shape(body.getPoints(16)), tailBoom(L, S)]);
    g.rotateX(Math.PI / 2);
    return g;
  }
  if (!(def.minSpeed > 0)) {
    // a blimp: the envelope, long and round-ended, and its fins
    shape.absellipse(0, 0, S * 0.5, L * 0.5, 0, Math.PI * 2, false, 0);
    const fins = new THREE.Shape();
    fins.moveTo(-S * 0.55, -L * 0.42); fins.lineTo(S * 0.55, -L * 0.42); fins.lineTo(S * 0.2, -L * 0.3); fins.lineTo(-S * 0.2, -L * 0.3); fins.closePath();
    const g = new THREE.ShapeGeometry([shape, fins]);
    g.rotateX(Math.PI / 2);
    return g;
  }
  // a plane: as the jets overhead (render/skyLayer.ts PlaneShadow)
  const f = L * 0.08, wz = L * 0.05, wd = L * 0.14;
  shape.moveTo(-f, L / 2); shape.lineTo(f, L / 2); shape.lineTo(f, wz + wd); shape.lineTo(S / 2, wz - wd * 0.6); shape.lineTo(S / 2, wz - wd * 1.3);
  shape.lineTo(f, wz - wd * 0.5); shape.lineTo(f * 0.7, -L / 2 + L * 0.1); shape.lineTo(S * 0.18, -L / 2); shape.lineTo(-S * 0.18, -L / 2);
  shape.lineTo(-f * 0.7, -L / 2 + L * 0.1); shape.lineTo(-f, wz - wd * 0.5); shape.lineTo(-S / 2, wz - wd * 1.3); shape.lineTo(-S / 2, wz - wd * 0.6);
  shape.lineTo(-f, wz + wd); shape.closePath();
  const g = new THREE.ShapeGeometry(shape);
  g.rotateX(Math.PI / 2);
  return g;
}

function tailBoom(L: number, S: number): THREE.Shape {
  const t = new THREE.Shape();
  t.moveTo(-S * 0.05, -L * 0.25); t.lineTo(S * 0.05, -L * 0.25); t.lineTo(S * 0.05, -L * 0.62); t.lineTo(-S * 0.05, -L * 0.62); t.closePath();
  return t;
}

interface Shadow { mesh: THREE.Mesh; def: AirDef; root: THREE.Object3D; seen: number; gy: number }

export class AirShadows {
  private by = new Map<object, Shadow>();
  private frame = 0;

  constructor(private parent: THREE.Object3D) {}

  /**
   * Once a frame: every craft in the air near the camera, the ground's height in world tiles, the sun's
   * smooth direction (pointing at it), and how strong shadows are (none by night).
   */
  update(bodies: AirBody[], ground: (x: number, z: number) => number, sun: THREE.Vector3, strength: number): void {
    this.frame++;
    for (const b of bodies) {
      let s = this.by.get(b.key);
      if (s && (s.def !== b.def || s.root !== b.root)) { this.drop(b.key, s); s = undefined; }
      if (!s) {
        const mat = new THREE.MeshBasicMaterial({ color: 0x0a1418, transparent: true, opacity: 0.2, depthWrite: false, side: THREE.DoubleSide });
        const mesh = new THREE.Mesh(outline(b.def), mat);
        mesh.renderOrder = 1;
        this.parent.add(mesh);
        s = { mesh, def: b.def, root: b.root, seen: 0, gy: NaN };
        this.by.set(b.key, s);
        // the craft no longer casts into the shadow map: this is its shadow now
        castsInto(b.root, false);
      }
      s.seen = this.frame;
      this.place(s, b, ground, sun, strength);
    }
    for (const [k, s] of this.by) if (s.seen !== this.frame) this.drop(k, s);
  }

  /** Down the sun's ray from the craft to the first ground or roof it meets, and the outline laid there. */
  private place(s: Shadow, b: AirBody, ground: (x: number, z: number) => number, sun: THREE.Vector3, strength: number): void {
    const sy = Math.max(0.12, sun.y);
    let gy = ground(b.x, b.z);
    for (let h = b.y - 0.4; h > gy - 2; h -= 0.4) {
      const k = (b.y - h) / sy;
      const g = ground(b.x - sun.x * k, b.z - sun.z * k);
      if (g >= h) { gy = g; break; }
    }
    // eased onto the new height rather than snapped: the ray's first hit leaps between a roof and the street
    // as the craft passes over a building's edge, and down a slanting sun every step up or down is a leap
    // sideways too, so the shadow of a blimp over a town jerked about with whatever stood under it (19 Oct 2026)
    s.gy = Number.isNaN(s.gy) || Math.abs(gy - s.gy) > 12 ? gy : s.gy + (gy - s.gy) * 0.08;
    gy = s.gy;
    const h = Math.max(0, b.y - gy);
    const ok = strength > 0.01 && sun.y > 0.12 && h < TOO_HIGH;
    s.mesh.visible = ok;
    if (!ok) return;
    const k = h / sy;
    s.mesh.position.set(b.x - sun.x * k, gy + 0.06, b.z - sun.z * k);
    s.mesh.rotation.set(0, b.heading, 0);
    // higher up, fainter and softer, and a touch bigger; on the ground, as dark as anything's
    const fade = Math.max(0.25, 1 - h / 110);
    (s.mesh.material as THREE.MeshBasicMaterial).opacity = 0.3 * strength * fade;
    s.mesh.scale.setScalar(1 + h / 160);
  }

  private drop(k: object, s: Shadow): void {
    castsInto(s.root, true);
    s.mesh.removeFromParent();
    s.mesh.geometry.dispose();
    (s.mesh.material as THREE.Material).dispose();
    this.by.delete(k);
  }
}

/**
 * Whether a craft's meshes cast into the shadow map. Each mesh's own choice (some never cast — glass, lamps)
 * is kept on it and put back when the decal lets go.
 */
function castsInto(root: THREE.Object3D, on: boolean): void {
  root.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    const ud = m.userData as { castWas?: boolean };
    if (!on) { if (ud.castWas === undefined) ud.castWas = m.castShadow; m.castShadow = false; }
    else if (ud.castWas !== undefined) { m.castShadow = ud.castWas; delete ud.castWas; }
  });
}
