import * as THREE from 'three';
import { N, STEP, DIRS, Flag, RailBit, World, idx, inB, waterDepth } from '../world/tiles';
import { railDeckAt } from '../world/railSurface';

/**
 * Barges on the great rivers (docs/geology.html, 0.7.0): on each county's longest navigable reach, a barge works
 * up and down, a pause at each end. A reach is a great river's channel (Flag.River and Flag.Corridor), two steps
 * deep or more, broken wherever a bridge or a railway's deck crosses lower than a barge stands: there the barge
 * turns back (navigable, deckClearance). Nothing collides with it; it is scenery that moves.
 */

/** A barge's wheelhouse over the water, world units, with a little to spare: a deck lower than this turns it back. */
export const BARGE_CLEAR = 0.75;
/** Tiles a second, and seconds tied up at each end. */
const SPEED = 0.9, DWELL = 10;
/** The shortest reach worth a barge, in tiles. */
const MIN_REACH = 40;

/** Headroom under whatever deck crosses tile i, above its water (world units); Infinity with none. */
export function deckClearance(w: World, i: number): number {
  const wl = w.water[i];
  if (wl < 0) return Infinity;
  const tx = i % N, tz = (i - tx) / N;
  let top = Infinity;
  if (w.deckAxis[i]) top = Math.min(w.deckLo[i], w.deckHi[i]);
  if (w.rail[i] & RailBit.Deck) {
    const y = railDeckAt(w, tx, tz, tx + 0.5, tz + 0.5);
    if (y !== null) top = Math.min(top, y);
  }
  return top - wl * STEP;
}

/** Can a barge pass this tile: a great river's channel, deep enough, with headroom under any deck? */
export function navigable(w: World, i: number): boolean {
  return (w.flags[i] & (Flag.River | Flag.Corridor)) === (Flag.River | Flag.Corridor) && w.water[i] >= 0 && waterDepth(w, i) >= 2 && deckClearance(w, i) >= BARGE_CLEAR;
}

/** The longest navigable reach in a county, as tiles end to end (a farthest-pair path through its biggest stretch), or null. */
export function reachOf(w: World): number[] | null {
  const ok = new Uint8Array(N * N);
  for (let i = 0; i < N * N; i++) if (navigable(w, i)) ok[i] = 1;
  const seen = new Int32Array(N * N).fill(-1);
  let bestStart = -1, bestN = 0, comp = 0;
  for (let s = 0; s < N * N; s++) {
    if (!ok[s] || seen[s] >= 0) continue;
    const q = [s];
    seen[s] = comp;
    for (let k = 0; k < q.length; k++) {
      const i = q[k], x = i % N, z = (i - x) / N;
      for (const [dx, dz] of DIRS) {
        if (!inB(x + dx, z + dz)) continue;
        const j = idx(x + dx, z + dz);
        if (ok[j] && seen[j] < 0) { seen[j] = comp; q.push(j); }
      }
    }
    if (q.length > bestN) { bestN = q.length; bestStart = s; }
    comp++;
  }
  if (bestStart < 0 || bestN < MIN_REACH) return null;
  // the farthest pair of the stretch: out from anywhere to its far end, then from there to the other
  const far = (from: number): { end: number; prev: Int32Array } => {
    const prev = new Int32Array(N * N).fill(-2);
    prev[from] = -1;
    const q = [from];
    let end = from;
    for (let k = 0; k < q.length; k++) {
      const i = q[k], x = i % N, z = (i - x) / N;
      end = i;
      for (const [dx, dz] of DIRS) {
        if (!inB(x + dx, z + dz)) continue;
        const j = idx(x + dx, z + dz);
        if (ok[j] && prev[j] === -2) { prev[j] = i; q.push(j); }
      }
    }
    return { end, prev };
  };
  const a = far(bestStart).end, { end: b, prev } = far(a);
  const path: number[] = [];
  for (let i = b; i >= 0; i = prev[i]) path.push(i);
  return path.length >= MIN_REACH ? path : null;
}

interface Barge { w: World; rev: number; pts: number[]; len: number; s: number; dir: 1 | -1; wait: number; mesh: THREE.Group }

export class Barges {
  readonly root = new THREE.Group();
  private barges = new Map<World, Barge | null>();
  private hull = new THREE.MeshStandardMaterial({ color: 0x3d4a3f, roughness: 0.8 });
  private deck = new THREE.MeshStandardMaterial({ color: 0x6b5a45, roughness: 0.9 });
  private cabin = new THREE.MeshStandardMaterial({ color: 0xe9e2d0, roughness: 0.7 });
  private glass = new THREE.MeshStandardMaterial({ color: 0x2a4866, roughness: 0.2 });
  private loads = [0xc0392b, 0x2e6da4, 0xd9a43a, 0x5b8c4a].map((c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.7 }));
  // the towboat's tow and the motor barge's hatches (docs/models070-audit.md)
  private hopper = new THREE.MeshStandardMaterial({ color: 0x5a3a2a, roughness: 0.9 });
  private knee = new THREE.MeshStandardMaterial({ color: 0x1e1e20, roughness: 0.8 });
  private stack = new THREE.MeshStandardMaterial({ color: 0x2a2a2c, roughness: 0.6 });
  private hatch = new THREE.MeshStandardMaterial({ color: 0x2f4a6a, roughness: 0.7 });
  private hatch2 = new THREE.MeshStandardMaterial({ color: 0x3a5a7a, roughness: 0.7 });
  private coal = new THREE.MeshStandardMaterial({ color: 0x2c2a28, roughness: 0.95 });
  private gravel = new THREE.MeshStandardMaterial({ color: 0x9a948a, roughness: 0.95 });
  private tmp = new THREE.Vector3();

  constructor() { this.root.name = 'barges'; }

  private build(seed: number): THREE.Group {
    const g = new THREE.Group();
    const add = (geo: THREE.BufferGeometry, m: THREE.Material, x: number, y: number, z: number) => {
      const mesh = new THREE.Mesh(geo, m);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      g.add(mesh);
    };
    if (seed % 2) {
      // an American towboat pushing its tow (docs/models070-audit.md): two or three open hopper barges lashed ahead of
      // it, heaped with coal or gravel, and the towboat itself: a square bow with push knees, two tiers of white
      // superstructure, the pilothouse on top with its glass all round, twin stacks
      const n = 2 + (seed % 3 === 0 ? 1 : 0), L = 0.6;
      for (let k = 0; k < n; k++) {
        const z = 0.1 + (k + 0.5) * L - (n * L) / 2 + 0.35;
        add(new THREE.BoxGeometry(0.52, 0.12, L - 0.02), this.hopper, 0, 0.03, z);
        add(new THREE.BoxGeometry(0.44, 0.04, L - 0.1), this.deck, 0, 0.1, z);
        add(new THREE.BoxGeometry(0.4, 0.07, L - 0.16), (seed >> 1) % 2 ? this.coal : this.gravel, 0, 0.15, z);
      }
      const tz = 0.1 - (n * L) / 2 + 0.35 - 0.32;
      add(new THREE.BoxGeometry(0.46, 0.13, 0.56), this.hull, 0, 0.03, tz);
      for (const x of [-0.16, 0.16]) add(new THREE.BoxGeometry(0.05, 0.12, 0.04), this.knee, x, 0.16, tz + 0.28);
      add(new THREE.BoxGeometry(0.38, 0.12, 0.4), this.cabin, 0, 0.16, tz - 0.04);
      add(new THREE.BoxGeometry(0.3, 0.1, 0.28), this.cabin, 0, 0.28, tz - 0.06);
      add(new THREE.BoxGeometry(0.24, 0.1, 0.18), this.glass, 0, 0.38, tz - 0.04);
      add(new THREE.BoxGeometry(0.28, 0.02, 0.22), this.cabin, 0, 0.48, tz - 0.04);
      for (const x of [-0.08, 0.08]) add(new THREE.CylinderGeometry(0.025, 0.025, 0.2, 8), this.stack, x, 0.46, tz - 0.2);
      return g;
    }
    // a Rhine motor barge: a long low hull, hatch covers down the hold, a car on its stern deck under the wheelhouse
    add(new THREE.BoxGeometry(0.5, 0.14, 1.9), this.hull, 0, 0.03, 0);
    add(new THREE.BoxGeometry(0.46, 0.02, 1.86), this.deck, 0, 0.11, 0);
    for (let k = 0; k < 5; k++) add(new THREE.BoxGeometry(0.42, 0.05, 0.22), k % 2 ? this.hatch : this.hatch2, 0, 0.15, 0.62 - k * 0.24);
    add(new THREE.BoxGeometry(0.34, 0.22, 0.28), this.cabin, 0, 0.23, -0.76);
    add(new THREE.BoxGeometry(0.28, 0.12, 0.2), this.cabin, 0, 0.45, -0.7);
    add(new THREE.BoxGeometry(0.3, 0.07, 0.18), this.glass, 0, 0.5, -0.7);
    add(new THREE.BoxGeometry(0.14, 0.06, 0.24), this.loads[seed % this.loads.length], 0.1, 0.15, -0.42);
    add(new THREE.CylinderGeometry(0.006, 0.006, 0.3, 4), this.stack, 0, 0.62, -0.86);
    return g;
  }

  /** A barge on each county's longest reach in memory, worked out again when the county changes. */
  update(dt: number, worlds: World[]): void {
    const live = new Set(worlds);
    for (const w of worlds) {
      let b = this.barges.get(w);
      if (b === undefined || (b && b.rev !== w.revision)) {
        if (b) this.root.remove(b.mesh);
        const path = reachOf(w);
        b = path ? this.make(w, path) : null;
        this.barges.set(w, b);
        if (b) this.root.add(b.mesh);
      }
      if (b) this.drive(b, dt);
    }
    for (const [w, b] of this.barges) if (!live.has(w)) { if (b) this.root.remove(b.mesh); this.barges.delete(w); }
  }

  private make(w: World, path: number[]): Barge {
    // the tile path eased into a line through the channel, in world tiles
    const raw = path.map((i) => [w.ox + (i % N) + 0.5, w.oz + Math.floor(i / N) + 0.5]);
    const pts: number[] = [];
    for (let k = 0; k < raw.length; k++) {
      let sx = 0, sz = 0, n = 0;
      for (let j = Math.max(0, k - 3); j <= Math.min(raw.length - 1, k + 3); j++) { sx += raw[j][0]; sz += raw[j][1]; n++; }
      pts.push(sx / n, sz / n);
    }
    let len = 0;
    for (let k = 2; k < pts.length; k += 2) len += Math.hypot(pts[k] - pts[k - 2], pts[k + 1] - pts[k - 1]);
    return { w, rev: w.revision, pts, len, s: len * 0.3, dir: 1, wait: 0, mesh: this.build(path.length) };
  }

  private drive(b: Barge, dt: number): void {
    if (b.wait > 0) b.wait -= dt;
    else {
      b.s += b.dir * SPEED * dt;
      if (b.s >= b.len - 1) { b.s = b.len - 1; b.dir = -1; b.wait = DWELL; }
      else if (b.s <= 1) { b.s = 1; b.dir = 1; b.wait = DWELL; }
    }
    const a = this.at(b, b.s - 0.5 * b.dir), c = this.at(b, b.s + 0.5 * b.dir);
    b.mesh.position.set((a.x + c.x) / 2, (a.y + c.y) / 2, (a.z + c.z) / 2);
    b.mesh.rotation.set(0, 0, 0);
    b.mesh.lookAt(this.tmp.set(c.x, (a.y + c.y) / 2, c.z));
  }

  private at(b: Barge, s: number): { x: number; y: number; z: number } {
    let left = Math.max(0, Math.min(b.len, s));
    const p = b.pts;
    for (let k = 2; k < p.length; k += 2) {
      const seg = Math.hypot(p[k] - p[k - 2], p[k + 1] - p[k - 1]);
      if (left <= seg || k === p.length - 2) {
        const f = seg ? Math.min(1, left / seg) : 0;
        const x = p[k - 2] + (p[k] - p[k - 2]) * f, z = p[k - 1] + (p[k + 1] - p[k - 1]) * f;
        const tx = Math.floor(x - b.w.ox), tz = Math.floor(z - b.w.oz);
        const wl = inB(tx, tz) ? b.w.water[idx(tx, tz)] : -1;
        return { x, y: (wl >= 0 ? wl * STEP : 0) - 0.02, z };
      }
      left -= seg;
    }
    return { x: p[0], y: 0, z: p[1] };
  }
}
