import { ECONOMY } from '../ledger';
import { GRADUATION, builtCount } from '../../world/growth';
import { TOWN_INFO } from '../../world/towns';
import { seatLabel, seatOf } from '../../world/townShape';
import type { TownDigest } from '../../world/townDigest';
import { asOf, dl, esc, farNote, hoursText, ordinal, perHour, plural, tick, tradeChart, type TabCtx } from './common';

/** The measures a town is ranked by on its Overview, best place first. */
interface Measure { id: string; label: string; of: (d: TownDigest) => number }

/**
 * Tab 1 (docs/townregister.html): how the town is doing, where it ranks, and what it needs to grow. `rate` gives a
 * town's trade rate by key, for ranking on trade.
 */
export function overviewTab(c: TabCtx, rate: (key: string) => number): string {
  const { w, t, ledger: r } = c;
  const norm = ECONOMY.norm[c.kind];
  let out = '';
  const rows: [string, string][] = [];

  if (c.mood) {
    const cls = c.mood.mood === 'Struggling' ? 'bad' : c.mood.mood === 'Steady' ? 'mid' : 'good';
    out += `<div class="perf ${cls}"><div class="row"><b>${c.mood.mood}</b><span>${c.mood.p.toFixed(2)}×</span></div>`
      + `<div class="bar"><i style="width:${Math.min(100, (c.mood.p / 2) * 100)}%"></i><s></s></div></div>`;
  } else out += farNote();

  out += ranksHtml(c, rate);

  if (r) {
    rows.push(['Trade', `${perHour(r.rate)} of ${perHour(norm)} a town this size expects${c.mood ? '' : ` · ${(r.rate / norm).toFixed(2)}×`}`]);
    const chart = tradeChart(r, norm);
    if (chart) rows.push([`${r.hist!.length} days`, `${chart}<small class="tc-chart-key">— its trade · - - expected · ● grew a building</small>`]);
  }
  if (c.mood && r) {
    // the meter's drift by the ledger's own rule, to say when it next grows or wears
    const p = c.mood.p;
    const drift = p > ECONOMY.thrive ? ECONOMY.up * Math.min(ECONOMY.upCap, p - 1) : p < ECONOMY.struggle ? ECONOMY.down * Math.max(ECONOMY.downCap, p - 1) : 0;
    const growth = drift > 0 ? `next building in about ${hoursText((1 - r.meter) / drift)}`
      : drift < 0 ? `<em class="bad">a building boards up in about ${hoursText((r.meter + 1) / -drift)}</em>` : 'holding steady: trade here to grow it';
    rows.push(['Growth', `${growth}${r.grown ? ` · ${r.grown} grown so far` : ''}`]);
  } else if (r) {
    rows.push(['Grown', `${plural(r.grown, 'building')}${r.blight ? ` · <em class="bad">${r.blight} boarded up</em>` : ''}`]);
  }

  const d = c.digest;
  if (t) {
    const g = GRADUATION[t.kind];
    if (g && !(t.parent !== undefined && g.to === 'metro')) {
      const built = builtCount(t);
      const has = t.buildings.some((b) => !b.gone && g.needs.includes(b.kind));
      rows.push([`To ${TOWN_INFO[g.to].label.toLowerCase()}`, [
        tick(built >= g.built, `${built}/${g.built} buildings`),
        tick(t.size >= g.size, `${t.size}/${g.size} across`),
        tick(has, `a ${g.needs.map((k) => c.label(k).toLowerCase()).join(' or ')}`),
      ].join(' ')]);
    } else {
      rows.push(['Next', t.parent !== undefined ? 'A satellite grows no bigger than a small city' : 'As big as a town gets']);
    }
  }
  if (d) rows.push(['Size', `${plural(d.built, 'building')} · ${plural(c.shape?.area ?? d.area, 'tile')}${c.w ? '' : ` <small>${asOf(d.day).toLowerCase()}</small>`}`]);
  if (t && w) {
    const seat = seatOf(t);
    if (seat) rows.push(['Seat', `${esc(seatLabel(seat))} <button type="button" class="link" data-act="seat">show</button>`]);
  }
  if (d?.notable.length) {
    const top = d.notable.slice(0, 4).map(([k, n]) => `${esc(c.label(k))}${n > 1 ? ` ×${n}` : ''}`).join(', ');
    rows.push(['Known for', `${top}${d.notable.length > 4 ? ` <button type="button" class="link" data-tab="buildings">+${d.notable.length - 4} more</button>` : ''}`]);
  }
  if (!r && !d) return out + '<p class="note">Nothing is on its books yet.</p>';
  return out + dl(rows);
}

/** Its three best places among the towns known, and its place in its own county. */
function ranksHtml(c: TabCtx, rate: (key: string) => number): string {
  const idx = c.index;
  if (!c.digest || idx.size < 3) return '';
  const measures: Measure[] = [
    { id: 'built', label: 'by buildings', of: (d) => d.built },
    { id: 'area', label: 'by size', of: (d) => d.area },
    { id: 'trade', label: 'by trade', of: (d) => rate(d.key) },
    { id: 'sights', label: 'for sights', of: (d) => d.notable.reduce((s, [, n]) => s + n, 0) },
    { id: 'links', label: 'for connections', of: (d) => d.roadsTo + d.stations + d.ports * 2 + d.airports * 3 },
  ];
  const all = measures.map((m) => ({ m, r: idx.rank(c.key, m.of) })).filter((x) => x.r && x.r.value > 0)
    .sort((a, b) => a.r!.place / a.r!.of - b.r!.place / b.r!.of || a.r!.place - b.r!.place).slice(0, 3);
  if (!all.length) return '';
  const [cx, cz] = c.digest.at;
  const county = idx.rank(c.key, (d) => d.built, (d) => d.at[0] === cx && d.at[1] === cz);
  const chips = all.map(({ m, r }) => `<span class="rk${r!.place === 1 ? ' top' : ''}" title="${esc(`${ordinal(r!.place)} of ${r!.of} towns known, ${m.label}`)}"><b>#${r!.place}</b> ${m.label}</span>`).join('');
  const home = county && county.of > 1 ? `<span class="rk"><b>#${county.place}</b> of ${county.of} in ${esc(c.digest.county)}</span>` : '';
  return `<div class="tc-ranks"><small>Among ${idx.size} towns known <button type="button" class="link" data-act="register">see all</button></small>${chips}${home}</div>`;
}
