import * as THREE from 'three';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { ALL_VEHICLES, type VehicleDef, type VehicleState } from './vehicles';
import type { World } from '../world/tiles';

/**
 * The airlift home (the user, 7 Oct 2026): from the HQ window's Home tab, a twin-rotor Bumblebee fetches the
 * player's vehicle and sets it down at the HQ, for $100 a county crossed, once the HQ is two counties or
 * more away. The vehicle stands frozen and the camera is held while a chopper swoops in, hooks the vehicle
 * on four cables, lifts it and carries it off screen; the world then moves to the HQ (main.ts does that
 * under the screen's band), the chopper swoops in there with the vehicle dangling, lowers it onto the road
 * beside the HQ and lets go: the vehicle is the player's again, and the chopper flies off.
 *
 * Nothing here is physics: the vehicle on the cables is a copy of its model, posed by hand, and the
 * player's own (hidden meanwhile) only moves once, when main.ts puts it down at the HQ.
 */

export const AIRLIFT_PER_COUNTY = 100;
/** Counties away from the HQ before an airlift is offered: two, so the least it costs is $200. */
export const AIRLIFT_MIN_COUNTIES = 2;

/** Counties between two cells, as the chopper flies: diagonal steps count one, like a king on a chessboard. */
export function airliftCounties(a: { cx: number; cz: number }, b: { cx: number; cz: number }): number {
  return Math.max(Math.abs(a.cx - b.cx), Math.abs(a.cz - b.cz));
}

/** A place in the world (absolute coordinates) and the way a vehicle there faces. */
export interface LiftSpot { x: number; y: number; z: number; heading: number }

interface AirliftHooks {
  /**
   * The chopper is off screen: move the player to the HQ and call `done` with where the vehicle is to be
   * set down (null: it can't be, and the vehicle is put back where it was picked up).
   */
  relocate(done: (drop: LiftSpot | null) => void): void;
  /** The vehicle is on the ground: show the player's own and hand it back. */
  landed(at: LiftSpot, moved: boolean): void;
}

type Phase = 'in' | 'hook' | 'lift' | 'out' | 'cut' | 'arrive' | 'lower' | 'release' | 'leave';
const DUR: Record<Phase, number> = { in: 1.9, hook: 0.6, lift: 0.85, out: 1.7, cut: 99, arrive: 2.1, lower: 1.0, release: 0.5, leave: 2.2 };
/** How far below the chopper's belly the vehicle's roof hangs. */
const HANG = 1.5;

const CHINOOK = ALL_VEHICLES.find((v) => v.id === 'chinook') as VehicleDef;

const still = (heading: number): VehicleState => ({
  x: 0, y: 0, z: 0, heading, v: 0, pitch: 0, roll: 0, bob: 0, lean: 0, wheelSpin: 0, steerVis: 0, power: 1, blocked: 0,
  trailerHeading: heading, sailAngle: 0, surfaceY: NaN, step() { /* posed by hand */ }, status: () => '',
});

const smooth = (t: number) => t * t * (3 - 2 * t);
const easeOut = (t: number) => 1 - (1 - t) ** 3;
const easeIn = (t: number) => t * t * t;
/** The shortest turn from heading a to b, a share t of the way. */
function turnTo(a: number, b: number, t: number): number {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}
/** A point on the quadratic curve p0 → c → p1. */
function bez(p0: THREE.Vector3, c: THREE.Vector3, p1: THREE.Vector3, t: number, out: THREE.Vector3): THREE.Vector3 {
  const u = 1 - t;
  return out.set(u * u * p0.x + 2 * u * t * c.x + t * t * p1.x, u * u * p0.y + 2 * u * t * c.y + t * t * p1.y, u * u * p0.z + 2 * u * t * c.z + t * t * p1.z);
}

export class Airlift {
  readonly group = new THREE.Group();
  /** Where the camera should look while the vehicle isn't the player's to drive (null: at the vehicle, as ever). */
  readonly aim = new THREE.Vector3();
  private phase: Phase | null = null;
  private t = 0;
  private heli: VehicleMesh | null = null;
  private load: VehicleMesh | null = null;
  private loadDef: VehicleDef | null = null;
  private cables: THREE.Mesh[] = [];
  private cableGeo = new THREE.CylinderGeometry(0.014, 0.014, 1, 5).translate(0, 0.5, 0);
  private cableMat = new THREE.MeshLambertMaterial({ color: 0x2a2a2a });
  private hooks: AirliftHooks | null = null;
  private pick: LiftSpot = { x: 0, y: 0, z: 0, heading: 0 };
  private drop: LiftSpot | null = null;
  /** The way to the HQ across the ground, and the camera's right hand at the start (where the chopper comes in from). */
  private dir = new THREE.Vector3(0, 0, 1);
  private side = new THREE.Vector3(1, 0, 0);
  /** The vehicle's roof above its origin, its half length and width; the chopper's belly below its origin. */
  private roof = 0.5;
  private half = { l: 0.5, w: 0.3 };
  private belly = 0.2;
  // where things are this frame
  private H = new THREE.Vector3();
  private heading = 0;
  private pitch = 0;
  private roll = 0;
  private L = new THREE.Vector3();
  private loadHeading = 0;
  private swing = 0;
  private grow = 0;
  /** Where each leg starts, set as it begins. */
  private from = new THREE.Vector3();
  private fromHeading = 0;
  private ctrl = new THREE.Vector3();
  private to = new THREE.Vector3();
  private tmp = new THREE.Vector3();
  private prevH = new THREE.Vector3();

  constructor() { this.group.name = 'airlift'; }

  /** Anything of the airlift on screen. */
  get active(): boolean { return this.phase !== null; }
  /** The vehicle is the chopper's, not the player's: it is frozen, and the camera is held on `aim`. */
  get busy(): boolean { return this.phase !== null && this.phase !== 'release' && this.phase !== 'leave'; }

  /**
   * Begin: `pick` is the vehicle where it stands, `dir` the way to the HQ on the ground, `camRight` the
   * camera's right hand (the chopper comes in from that side, so it swoops across the view).
   */
  start(def: VehicleDef, w: World, pick: LiftSpot, dir: { x: number; z: number }, camRight: { x: number; z: number }, hooks: AirliftHooks): void {
    this.dispose();
    this.hooks = hooks;
    this.pick = { ...pick };
    this.drop = null;
    this.dir.set(dir.x, 0, dir.z).normalize();
    if (!Number.isFinite(this.dir.x) || this.dir.lengthSq() < 0.5) this.dir.set(0, 0, 1);
    this.side.set(camRight.x, 0, camRight.z).normalize();
    if (!Number.isFinite(this.side.x) || this.side.lengthSq() < 0.5) this.side.set(1, 0, 0);
    // the chopper, and a copy of the vehicle to hang under it
    this.heli = buildVehicleMesh(CHINOOK);
    poseVehicleMesh(this.heli, still(0), CHINOOK, w);
    const hb = new THREE.Box3().setFromObject(this.heli.root);
    this.belly = Number.isFinite(hb.min.y) ? hb.min.y + 0.12 : 0.2;
    this.load = buildVehicleMesh(def);
    this.loadDef = def;
    poseVehicleMesh(this.load, still(0), def, w);
    const lb = new THREE.Box3().setFromObject(this.load.root);
    this.roof = Number.isFinite(lb.max.y) ? Math.max(0.2, lb.max.y) : 0.5;
    this.half = { l: Number.isFinite(lb.max.z) ? Math.max(0.2, (lb.max.z - lb.min.z) / 2) : 0.5, w: Number.isFinite(lb.max.x) ? Math.max(0.15, (lb.max.x - lb.min.x) / 2) : 0.3 };
    this.group.add(this.heli.holder, this.load.holder);
    for (let k = 0; k < 4; k++) {
      const c = new THREE.Mesh(this.cableGeo, this.cableMat);
      c.visible = false;
      c.frustumCulled = false;
      this.cables.push(c);
      this.group.add(c);
    }
    this.L.set(pick.x, pick.y, pick.z);
    this.loadHeading = pick.heading;
    this.aim.set(pick.x, pick.y, pick.z);
    this.begin('in');
  }

  private hover(at: LiftSpot, extra: number, out: THREE.Vector3): THREE.Vector3 {
    return out.set(at.x, at.y + this.roof + HANG - this.belly + extra, at.z);
  }

  private begin(p: Phase): void {
    this.phase = p;
    this.t = 0;
    this.from.copy(this.H);
    this.fromHeading = this.heading;
    const pick = this.pick;
    if (p === 'in') {
      // from high off to the camera's right, swooping round to a hover over the vehicle
      this.hover(pick, 1.2, this.to);
      this.from.set(pick.x, pick.y, pick.z).addScaledVector(this.side, 46).addScaledVector(this.dir, -14);
      this.from.y = pick.y + 24;
      this.ctrl.set(pick.x, pick.y + 9, pick.z).addScaledVector(this.side, 15).addScaledVector(this.dir, -8);
      this.H.copy(this.from);
      this.heading = Math.atan2(this.to.x - this.from.x, this.to.z - this.from.z);
      this.fromHeading = this.heading;
    } else if (p === 'hook') this.hover(pick, 0, this.to);
    else if (p === 'lift') this.to.copy(this.H).setY(this.H.y + 3.4);
    else if (p === 'out') {
      // away toward the HQ, climbing, gone off the edge of the view
      this.to.copy(this.H).addScaledVector(this.dir, 80);
      this.to.y += 20;
    } else if (p === 'arrive' && this.drop) {
      const d = this.drop;
      this.hover(d, 1.4, this.to);
      this.from.set(d.x, d.y + 22, d.z).addScaledVector(this.dir, -80);
      this.ctrl.set(d.x, d.y + 8, d.z).addScaledVector(this.dir, -14);
      this.H.copy(this.from);
      this.heading = Math.atan2(this.dir.x, this.dir.z);
      this.fromHeading = this.heading;
    } else if (p === 'lower' && this.drop) this.hover(this.drop, 0, this.to);
    else if (p === 'leave') {
      this.to.copy(this.H).addScaledVector(this.dir, 70);
      this.to.y += 22;
    }
    this.prevH.copy(this.H);
  }

  /** Every frame, in real time (the game may pause its world for a hitstop; the chopper doesn't). */
  update(dt: number): void {
    const p = this.phase;
    if (!p || !this.heli || !this.load) return;
    dt = Math.min(dt, 0.1);
    this.t += dt / DUR[p];
    const k = Math.min(1, this.t);
    this.prevH.copy(this.H);
    let hanging = false;
    if (p === 'in') {
      bez(this.from, this.ctrl, this.to, easeOut(k), this.H);
    } else if (p === 'hook') {
      this.H.lerpVectors(this.from, this.to, smooth(k));
      this.grow = smooth(k);
    } else if (p === 'lift') {
      this.H.lerpVectors(this.from, this.to, smooth(k));
      hanging = true;
    } else if (p === 'out') {
      this.H.lerpVectors(this.from, this.to, easeIn(k));
      this.heading = turnTo(this.fromHeading, Math.atan2(this.dir.x, this.dir.z), smooth(Math.min(1, k * 2.5)));
      hanging = true;
    } else if (p === 'cut') {
      hanging = true;
    } else if (p === 'arrive') {
      bez(this.from, this.ctrl, this.to, easeOut(k), this.H);
      hanging = true;
    } else if (p === 'lower') {
      this.H.lerpVectors(this.from, this.to, smooth(k));
      hanging = true;
    } else if (p === 'release') {
      this.grow = 1 - smooth(k);
      this.H.y += dt * 0.6;
    } else if (p === 'leave') {
      this.H.lerpVectors(this.from, this.to, easeIn(k));
      this.heading = turnTo(this.fromHeading, Math.atan2(this.dir.x, this.dir.z), smooth(Math.min(1, k * 2)));
    }
    // the chopper leans into its speed: nose down going, nose up as it flares to a hover
    const vx = (this.H.x - this.prevH.x) / Math.max(dt, 1e-3), vz = (this.H.z - this.prevH.z) / Math.max(dt, 1e-3);
    const speed = Math.hypot(vx, vz);
    if ((p === 'in' || p === 'arrive') && speed > 0.5) this.heading = turnTo(this.heading, Math.atan2(vx, vz), Math.min(1, dt * 4));
    const fwd = vx * Math.sin(this.heading) + vz * Math.cos(this.heading);
    const wantPitch = Math.max(-0.32, Math.min(0.22, fwd * 0.02)) * (p === 'in' || p === 'arrive' ? (k > 0.75 ? -0.6 : 1) : 1);
    this.pitch += (wantPitch - this.pitch) * Math.min(1, dt * 3);
    this.roll += ((p === 'in' || p === 'arrive' ? Math.sin(k * Math.PI) * 0.18 : 0) - this.roll) * Math.min(1, dt * 3);
    this.heli.root.position.copy(this.H);
    this.heli.root.rotation.set(this.pitch, this.heading, this.roll, 'YXZ');
    for (const sp of this.heli.spinners) sp.obj.rotation[sp.axis] += sp.speed * dt * 1.5;

    // the vehicle: on the ground until it's lifted, then hanging and swinging under the chopper
    if (hanging) {
      this.swing += dt;
      const sway = Math.sin(this.swing * 2.3) * 0.05 + (p === 'out' || p === 'arrive' ? -this.pitch * 0.6 : 0);
      const want = this.tmp.set(this.H.x, this.H.y + this.belly - HANG - this.roof, this.H.z);
      // a little lag behind the chopper, as a load on a rope has
      this.L.lerp(want, Math.min(1, dt * (p === 'lift' || p === 'lower' ? 12 : 6)));
      if (p === 'lower' && this.drop) {
        this.loadHeading = turnTo(this.loadHeading, this.drop.heading, Math.min(1, dt * 3));
        if (k >= 1) this.L.set(this.drop.x, this.drop.y, this.drop.z);
      } else this.loadHeading = turnTo(this.loadHeading, this.heading, Math.min(1, dt * 0.8));
      this.load.root.position.copy(this.L);
      this.load.root.rotation.set(sway, this.loadHeading, Math.sin(this.swing * 1.7) * 0.04, 'YXZ');
    } else if (p === 'in' || p === 'hook') {
      this.load.root.position.set(this.pick.x, this.pick.y, this.pick.z);
      this.load.root.rotation.set(0, this.pick.heading, 0, 'YXZ');
    }
    this.load.holder.visible = p !== 'release' && p !== 'leave';
    this.cablesNow(p === 'in' || p === 'leave' ? 0 : p === 'hook' || p === 'release' ? this.grow : 1);

    // the camera: on the vehicle where it was picked up, then where it is set down
    if (this.drop && (p === 'arrive' || p === 'lower')) this.aim.set(this.drop.x, this.drop.y, this.drop.z);

    if (k < 1 || p === 'cut') return;
    if (p === 'in') this.begin('hook');
    else if (p === 'hook') this.begin('lift');
    else if (p === 'lift') this.begin('out');
    else if (p === 'out') {
      this.begin('cut');
      this.hooks?.relocate((drop) => {
        if (!drop) {
          // nowhere to set it down: it goes back where it came from
          this.drop = { ...this.pick };
          this.dir.multiplyScalar(-1);
        } else this.drop = drop;
        this.L.set(this.drop.x, this.drop.y + 30, this.drop.z);
        this.begin('arrive');
        this.L.set(this.H.x, this.H.y + this.belly - HANG - this.roof, this.H.z);
        this.aim.set(this.drop.x, this.drop.y, this.drop.z);
        this.moved = !!drop;
      });
    } else if (p === 'arrive') this.begin('lower');
    else if (p === 'lower') {
      this.begin('release');
      // the vehicle is down: it is the player's again, and the copy goes
      if (this.drop) this.hooks?.landed(this.drop, this.moved);
    } else if (p === 'release') this.begin('leave');
    else if (p === 'leave') this.dispose();
  }
  private moved = false;

  /** The four cables from the chopper's belly to the vehicle's roof, `g` of the way down. */
  private cablesNow(g: number): void {
    const show = g > 0.01 && !!this.heli;
    const sh = Math.sin(this.heading), ch = Math.cos(this.heading);
    const lh = Math.sin(this.loadHeading), lc = Math.cos(this.loadHeading);
    const corners: [number, number][] = [[-1, -1], [1, -1], [-1, 1], [1, 1]];
    corners.forEach(([sx, sz], i) => {
      const c = this.cables[i];
      if (!c) return;
      c.visible = show;
      if (!show) return;
      // from a hook under the chopper's middle to a corner of the roof
      const ax = this.H.x + (sx * 0.06) * ch + (sz * 0.08) * sh, az = this.H.z - (sx * 0.06) * sh + (sz * 0.08) * ch, ay = this.H.y + this.belly;
      const ox = sx * this.half.w * 0.7, oz = sz * this.half.l * 0.65;
      const bx = this.L.x + ox * lc + oz * lh, bz = this.L.z - ox * lh + oz * lc, by = this.L.y + this.roof;
      const v = this.tmp.set((bx - ax) * g, (by - ay) * g, (bz - az) * g);
      const len = v.length();
      c.position.set(ax, ay, az);
      c.scale.set(1, Math.max(0.001, len), 1);
      c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), v.normalize());
    });
  }

  /** Everything off the screen and let go. */
  dispose(): void {
    if (this.heli) { this.group.remove(this.heli.holder); disposeVehicleMesh(this.heli); this.heli = null; }
    if (this.load) { this.group.remove(this.load.holder); disposeVehicleMesh(this.load); this.load = null; }
    for (const c of this.cables) this.group.remove(c);
    this.cables = [];
    this.phase = null;
    this.hooks = null;
    this.loadDef = null;
  }
}
