import { CARGO } from './cargoTypes';
import { ALL_VEHICLES } from './vehicles';
import type { GoodsBoardKind } from '../../shared/social';

/**
 * The crowns' rules and names (docs/toppers.html, phase 2), shared by the game and the server (server/crowns.ts):
 * every cargo kind and every culture has a gold, a silver and a bronze crown, worn by the fleets first, second and
 * third on its board (server/goodsBoards.ts: loads of a cargo kind delivered, units of a culture's goods brought home).
 *
 * A board is keyed as the goods boards key it, a cargo kind by its NAME and a culture by its style; a crown's topper
 * id is short and safe to save: `cg:<cargo id>:g` (or `:s`, `:b`) and `cc:<style>:g`.
 */

/** Places on the podium: 0 gold, 1 silver, 2 bronze. */
export type Place = 0 | 1 | 2;
export const PLACES: Place[] = [0, 1, 2];
export const METAL_KEY = ['g', 's', 'b'] as const;
export const METAL_NAME = ['Gold', 'Silver', 'Bronze'] as const;
export const METAL_ICON = ['🥇', '🥈', '🥉'] as const;

/** The least a fleet must have to hold each place: loads of a cargo kind, units of a culture's goods, loads in a model, dollars in a model. */
export const CROWN_FLOOR: Record<GoodsBoardKind, [number, number, number]> = { g: [25, 15, 10], c: [50, 30, 20], v: [25, 15, 10], e: [5000, 3000, 2000] };
/** How long a fleet that has been passed keeps its crown, to win it back. */
export const CROWN_GRACE_MS = 48 * 3600 * 1000;
/** Held this long in all (any metal), a crown goes on the fleet's Crown Roll for good. */
export const CROWN_ROLL_MS = 30 * 24 * 3600 * 1000;

/** A cargo kind's id by its name (the first, where two kinds share a name: they share a board too). */
const ID_BY_NAME = new Map<string, string>();
const NAME_BY_ID = new Map<string, string>();
for (const t of CARGO) if (!ID_BY_NAME.has(t.name)) { ID_BY_NAME.set(t.name, t.id); NAME_BY_ID.set(t.id, t.name); }
/** Every cargo board's kind name, in the cargo list's order. */
export const CARGO_CROWN_KINDS: string[] = [...ID_BY_NAME.keys()];
export const cargoIdOf = (name: string): string | undefined => ID_BY_NAME.get(name);

const STYLE = /^[a-z]{2,16}$/;
/** Every vehicle model's id (the vehicle boards: loads and earnings by model). */
const MODEL_IDS = new Set(ALL_VEHICLES.map((d) => d.id).filter((id) => /^[A-Za-z0-9]{1,24}$/.test(id)));
/** Whether a board's kind can have crowns: a cargo kind the game knows, a culture's style, or a vehicle model. */
export const crownable = (k: GoodsBoardKind, kind: string): boolean => (k === 'g' ? ID_BY_NAME.has(kind) : k === 'c' ? STYLE.test(kind) : MODEL_IDS.has(kind));

/** A crown's topper id, or null for a kind with none. */
export function crownId(k: GoodsBoardKind, kind: string, place: Place): string | null {
  if (k === 'g') { const id = ID_BY_NAME.get(kind); return id ? `cg:${id}:${METAL_KEY[place]}` : null; }
  if (k === 'v' || k === 'e') return MODEL_IDS.has(kind) ? `c${k}:${kind}:${METAL_KEY[place]}` : null;
  return STYLE.test(kind) ? `cc:${kind}:${METAL_KEY[place]}` : null;
}

/** A topper id read back as a crown: its board and place, or null when it isn't one. */
export function parseCrown(id: string): { k: GoodsBoardKind; kind: string; place: Place; key: string } | null {
  const m = /^c([gcve]):([A-Za-z0-9]{1,24}):([gsb])$/.exec(id);
  if (!m) return null;
  const k = m[1] as GoodsBoardKind;
  const kind = k === 'g' ? NAME_BY_ID.get(m[2]) : k === 'c' ? (STYLE.test(m[2]) ? m[2] : undefined) : MODEL_IDS.has(m[2]) ? m[2] : undefined;
  if (!kind) return null;
  return { k, kind, place: METAL_KEY.indexOf(m[3] as 'g') as Place, key: `${k}|${kind}` };
}
/**
 * Whether a topper is held rather than kept: a crown, or (phase 4) a rush pennant, a challenge flag or a range record,
 * each worn only while the server says this fleet holds it (server/crowns.ts allowed).
 */
export const isCrownId = (id: string | undefined): boolean => !!id && /^(c[gcve]|rp|cf|rk|tt):/.test(id);
/** The phase-4 held toppers (not crowns): what a board's holder wears. */
export const isHolderId = (id: string | undefined): boolean => !!id && /^(rp|cf|rk|tt):/.test(id);
/** A rush kind's pennant id (its own id has dashes: `fleet-long`). */
export const rushPennantId = (kind: string): string => `rp:${kind.replace(/[^A-Za-z0-9]/g, '')}`;
/** A challenge line's flag: its class (L/A/S) and kind (far/dash). */
export const chalFlagId = (cls: string, kind: string): string => `cf:${cls}${kind}`;
/** A range record's trophy: farthest from home in a vehicle of this kind. */
export const rangeRecordId = (kind: string): string => `rk:${kind}`;
/** A Track Trophy: the most lap records at circuits of a design (or of all, `laps`), or the most drift records. */
export const trackTrophyId = (t: string): string => `tt:${t}`;
