import { hex, scale, type RGB } from '../../world/biomes';
import type { PlantKind } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import { type Sched } from '../nightLights';
import { BRICK, DARK, GLASS, METAL, ROOF_GREY, SHOP_GLOW, STONE, TAU, WARM_GLOW, WHITE, WOOD, pick, row, type Draw, type Kit } from './kit';

/**
 * The supply chains' plants (docs/supplychains.html, world/plants.ts; held for 0.8.0): seventeen small works at the
 * edge of a town, each a shed or a shopfront on a yard with the thing it makes stacked out front, so a player looking
 * for the bindery or the ice house can tell it from across the street. The front (+z) faces the road.
 */

const CONCRETE = hex(0xc4c0b8), YARD = hex(0xb8b2a6), CREAM = hex(0xf2ead8), RED = hex(0xc8102e), GOLD = hex(0xd9b34a);
const ICE = hex(0xd6eef6), SLATE = hex(0x5a6066), COPPER = hex(0xb87333), BARREL = hex(0x8a5a2e), BLACK = hex(0x232427);
const LAMP_DAY = hex(0xe8e4d0);
/** Shop signs and yard lamps: on at dusk. */
const SIGN: Sched = [16.5, 30, 1.8];
const LAMP: Sched = [17, 30, 2.2];

/** The yard: a pad over the whole lot. */
function pad(k: Kit, W: number, D: number, col: RGB = YARD): void {
  k.box(0, 0, 0, W - 0.06, 0.01, D - 0.06, col);
}

/** A gabled shed at (cx, cz), its sign band in `band`, a door and a row of windows on the front. Returns its front z. */
function shed(k: Kit, b: Parameters<Draw>[3], r: Rng, cx: number, cz: number, w: number, d: number, h: number, wall: RGB, roof: RGB, band: RGB, n = 3): number {
  k.box(cx, 0, cz, w, h, d, wall);
  k.box(cx, h - 0.09, cz, w + 0.014, 0.07, d + 0.014, band);
  k.gable(cx, h, cz, w + 0.06, Math.min(0.28, w * 0.18), d + 0.06, roof, wall);
  const fz = cz + d / 2;
  k.box(cx, 0, fz + 0.006, 0.16, 0.26, 0.012, scale(wall, 0.55));
  k.glowBox(cx, 0.3, fz + 0.03, 0.06, 0.03, 0.04, LAMP_DAY, LAMP, WARM_GLOW);
  if (w > 0.7) row(k, b, r, cx, h * 0.45, fz, w - 0.35, Math.min(0.18, h * 0.3), n, 1);
  return fz;
}

/** A shop sign board on posts or over the door: a lit panel in the plant's colour. */
function sign(k: Kit, x: number, y: number, z: number, w: number, col: RGB): void {
  k.box(x, y, z, w, 0.1, 0.03, col);
  k.glowBox(x, y + 0.02, z + 0.02, w * 0.8, 0.05, 0.01, CREAM, SIGN, SHOP_GLOW);
}

/** Crates stacked out front: a few boxes in `col`. */
function crates(k: Kit, r: Rng, x: number, z: number, n: number, col: RGB): void {
  for (let i = 0; i < n; i++) {
    const s = 0.1 + r() * 0.04;
    k.box(x + (i % 3) * 0.14 - 0.14, Math.floor(i / 3) * s, z + (r() - 0.5) * 0.06, s, s, s, col, scale(col, 1.12));
  }
}

/** Barrels on their sides in a rack. */
function barrels(k: Kit, x: number, z: number, n: number, col: RGB = BARREL): void {
  for (let i = 0; i < n; i++) {
    const bx = x + (i - (n - 1) / 2) * 0.13;
    k.cyl(bx, 0, z, 0.055, 0.14, col, 8, scale(col, 0.85));
    k.cyl(bx, 0.04, z, 0.058, 0.012, BLACK, 8);
    k.cyl(bx, 0.1, z, 0.058, 0.012, BLACK, 8);
  }
}

/** A small van parked on the yard, in the plant's colour. */
function van(k: Kit, x: number, z: number, col: RGB): void {
  k.box(x, 0.04, z, 0.32, 0.18, 0.18, col);
  k.box(x + 0.16, 0.04, z, 0.1, 0.13, 0.18, col);
  k.box(x + 0.2, 0.1, z, 0.012, 0.05, 0.14, GLASS);
  for (const sx of [-1, 1]) for (const s of [-1, 1]) k.box(x + sx * 0.11, 0, z + s * 0.085, 0.07, 0.06, 0.025, DARK);
}

// ---- 2 Sweet tooth -------------------------------------------------------------------------------

/** An ice house: a thick-walled stone store half under a turfed bank, ice blocks on a sledge at the door. */
const iceHouse: Draw = (k, W, D, b, r) => {
  pad(k, W, D);
  const wall = pick(r, STONE);
  k.box(0, 0, -0.15, W - 0.4, 0.5, D - 0.6, wall);
  k.box(0, 0.5, -0.15, W - 0.3, 0.12, D - 0.5, hex(0x6f9e5b));
  k.cyl(0, 0.62, -0.15, 0.08, 0.16, METAL, 6);
  const fz = -0.15 + (D - 0.6) / 2;
  k.box(0, 0, fz + 0.006, 0.26, 0.34, 0.02, hex(0x3d6f8f));
  k.box(0, 0.36, fz + 0.01, 0.34, 0.06, 0.04, scale(wall, 0.8));
  for (let i = 0; i < 6; i++) k.box(-0.4 + (i % 3) * 0.15, Math.floor(i / 3) * 0.09, fz + 0.32, 0.13, 0.09, 0.13, ICE, hex(0xeef8fc));
  sign(k, 0.45, 0.42, fz + 0.03, 0.4, hex(0x3d6f8f));
};

/** A creamery: a white dairy shed with a steel churn tower and a milk tanker at the bay. */
const creamery: Draw = (k, W, D, b, r) => {
  pad(k, W, D, CONCRETE);
  const fz = shed(k, b, r, -0.3, -0.1, W - 0.9, D - 0.6, 0.6, WHITE, ROOF_GREY, hex(0x7fb7e6), 4);
  k.cyl(W / 2 - 0.4, 0, -0.2, 0.22, 0.95, METAL, 10, scale(METAL, 1.1));
  k.cone(W / 2 - 0.4, 0.95, -0.2, 0.22, 0.12, METAL, 10);
  k.box(W / 2 - 0.4, 0.4, 0.05, 0.05, 0.05, 0.3, METAL);
  sign(k, -0.3, 0.68, fz + 0.03, 0.9, hex(0xf7c5d4));
  k.cyl(0.6, 0.06, fz + 0.32, 0.1, 0.5, hex(0xe8ecee), 10);
  k.box(0.95, 0.04, fz + 0.32, 0.18, 0.18, 0.2, hex(0x7fb7e6));
};

// ---- 1 Books and boards ------------------------------------------------------------------------

/** A bindery: a brick workshop with tall windows and crated books on the step. */
const bindery: Draw = (k, W, D, b, r) => {
  pad(k, W, D, CONCRETE);
  const wall = pick(r, BRICK);
  const fz = shed(k, b, r, 0, -0.1, W - 0.4, D - 0.5, 0.75, wall, SLATE, hex(0x8a3b2e), 3);
  sign(k, 0, 0.82, fz + 0.03, W * 0.55, hex(0x8a3b2e));
  crates(k, r, -0.45, fz + 0.18, 4, hex(0xb08a5a));
  k.box(0.55, 0, fz + 0.14, 0.24, 0.14, 0.16, hex(0x6a4a8a), hex(0x8a3b2e));
};

/** A joinery: a timber shed with an open bay, planks stacked and a chair out front. */
const joinery: Draw = (k, W, D, b, r) => {
  pad(k, W, D);
  const fz = shed(k, b, r, -0.25, -0.1, W - 0.8, D - 0.5, 0.65, WOOD, hex(0x6f5a40), hex(0x9a6a3a), 3);
  for (let i = 0; i < 4; i++) k.box(W / 2 - 0.4, i * 0.05, -0.4 + i * 0.01, 0.6, 0.045, 0.22, hex(0xc9a06a), hex(0xd8b07a));
  k.box(0.3, 0, fz + 0.2, 0.14, 0.12, 0.14, hex(0x9a6a3a));
  k.box(0.3, 0.12, fz + 0.14, 0.14, 0.14, 0.02, hex(0x9a6a3a));
  sign(k, -0.25, 0.72, fz + 0.03, 0.8, hex(0x9a6a3a));
};

// ---- 4 The round ------------------------------------------------------------------------------

/** A print shop: a shopfront with a big window on the presses and paper reels on a pallet. */
const printShop: Draw = (k, W, D, b, r) => {
  pad(k, W, D, CONCRETE);
  const wall = pick(r, STONE);
  k.box(0, 0, -0.1, W - 0.3, 0.8, D - 0.5, wall);
  k.box(0, 0.8, -0.1, W - 0.26, 0.06, D - 0.46, SLATE);
  const fz = -0.1 + (D - 0.5) / 2;
  k.box(0, 0.12, fz + 0.006, W - 0.7, 0.42, 0.012, GLASS);
  k.glowBox(0, 0.3, fz - 0.02, W - 0.8, 0.2, 0.01, GLASS, SIGN, SHOP_GLOW);
  sign(k, 0, 0.6, fz + 0.03, W - 0.6, BLACK);
  for (let i = 0; i < 3; i++) k.cyl(-0.4 + i * 0.2, 0.02, fz + 0.25, 0.08, 0.18, CREAM, 10, hex(0xd8d0c0));
};

/** A parcel hub: a long shed of loading doors, a canopy and vans in a row. */
const parcelHub: Draw = (k, W, D, b, r) => {
  pad(k, W, D, hex(0x7a7f85));
  const sw = W - 0.4, sd = D - 1.2, cz = -0.3;
  k.box(0, 0, cz, sw, 0.7, sd, hex(0xe8e4dc));
  k.box(0, 0.6, cz, sw + 0.02, 0.1, sd + 0.02, RED);
  k.box(0, 0.7, cz, sw + 0.04, 0.05, sd + 0.04, ROOF_GREY);
  const fz = cz + sd / 2;
  for (let i = 0; i < 5; i++) k.box(-sw / 2 + 0.3 + i * ((sw - 0.6) / 4), 0, fz + 0.006, 0.36, 0.38, 0.012, hex(0x8a9096));
  k.box(0, 0.5, fz + 0.2, sw, 0.03, 0.42, RED, ROOF_GREY);
  for (let i = 0; i < 3; i++) van(k, -0.9 + i * 0.9, fz + 0.75, i === 1 ? hex(0xf2c12e) : RED);
  void r;
};

// ---- 5 Concrete and steel ---------------------------------------------------------------------

/** A concrete plant: a batching tower over a hopper, aggregate bays and a mixer in the yard. */
const readyMix: Draw = (k, W, D, b, r) => {
  pad(k, W, D, hex(0x9a958c));
  k.box(-0.5, 0, -0.5, 0.6, 1.4, 0.6, hex(0xa8acb0));
  k.box(-0.5, 1.4, -0.5, 0.7, 0.2, 0.7, hex(0xf2a93b));
  k.cyl(-0.5, 0, -0.5, 0.16, 0.3, METAL, 8);
  k.box(0.2, 0.6, -0.5, 1.0, 0.06, 0.12, METAL);
  for (let i = 0; i < 3; i++) {
    const x = 0.2 + i * 0.4;
    k.box(x, 0, 0.3, 0.36, 0.2, 0.36, CONCRETE);
    k.cone(x, 0.2, 0.3, 0.15, 0.12, i === 1 ? hex(0x8f8a82) : hex(0xb0a898), 6);
  }
  k.box(-0.6, 0.04, 0.8, 0.5, 0.16, 0.22, hex(0xf2a93b));
  k.cyl(-0.45, 0.2, 0.8, 0.1, 0.22, hex(0xd8d4cc), 8);
  sign(k, 0.6, 0.35, D / 2 - 0.2, 0.7, hex(0xf2a93b));
  void b; void r;
};

// ---- 7 Catch of the day ------------------------------------------------------------------------

/** A smokehouse: a black timber shed with a smoking chimney, fish hung on racks out front. */
const smokehouse: Draw = (k, W, D, b, r) => {
  pad(k, W, D);
  const fz = shed(k, b, r, 0, -0.15, W - 0.5, D - 0.7, 0.55, hex(0x2f2a26), hex(0x3a3330), hex(0xc9873a), 2);
  k.box(0.35, 0.55, -0.3, 0.14, 0.4, 0.14, pick(r, BRICK));
  k.detail(() => { for (let i = 0; i < 3; i++) k.cyl(0.35, 1.0 + i * 0.1, -0.3, 0.05 + i * 0.02, 0.06, hex(0xcfcfcf), 6); });
  for (const x of [-0.4, 0.4]) k.box(x, 0, fz + 0.25, 0.03, 0.4, 0.03, WOOD);
  k.box(0, 0.38, fz + 0.25, 0.86, 0.03, 0.03, WOOD);
  for (let i = 0; i < 6; i++) k.box(-0.3 + i * 0.12, 0.22, fz + 0.25, 0.04, 0.14, 0.02, hex(0xc9873a));
  sign(k, 0, 0.6, fz + 0.03, 0.6, hex(0xc9873a));
};

// ---- 8 Vintage, 16 Cask and peat ---------------------------------------------------------------

/** A winery: a long stone cellar with an arched door, barrels outside and a press under a lean-to. */
const winery: Draw = (k, W, D, b, r) => {
  pad(k, W, D, hex(0xd8c9a3));
  const wall = pick(r, STONE);
  const fz = shed(k, b, r, -0.2, -0.1, W - 0.7, D - 0.5, 0.6, wall, hex(0xb5543f), hex(0x7a2f4a), 3);
  barrels(k, -0.2, fz + 0.2, 5);
  k.box(W / 2 - 0.3, 0, 0, 0.4, 0.45, 0.6, WOOD);
  k.cyl(W / 2 - 0.3, 0.05, 0.1, 0.12, 0.2, hex(0x7a2f4a), 10);
  sign(k, -0.2, 0.66, fz + 0.03, 0.8, hex(0x7a2f4a));
};

/** A cooperage: an open-fronted timber shop with staves stacked and new casks rolled out. */
const cooperage: Draw = (k, W, D, b, r) => {
  pad(k, W, D);
  const fz = shed(k, b, r, 0, -0.15, W - 0.4, D - 0.7, 0.55, WOOD, hex(0x5a4a3c), BARREL, 2);
  barrels(k, 0, fz + 0.2, 6, hex(0xb08a5a));
  for (let i = 0; i < 4; i++) k.box(-W / 2 + 0.25, i * 0.03, -0.2 + i * 0.12, 0.08, 0.3, 0.06, hex(0xc9a06a));
  sign(k, 0, 0.6, fz + 0.03, 0.6, BARREL);
  void r;
};

// ---- 10 Deep metal, 18 Silicon -----------------------------------------------------------------

/** An alloy works: a furnace hall with a tall stack, an ore bunker and ingots on pallets. */
const alloyWorks: Draw = (k, W, D, b, r) => {
  pad(k, W, D, hex(0x7a7f85));
  const fz = shed(k, b, r, -0.2, -0.2, W - 0.8, D - 1.0, 0.9, hex(0x6d7a8a), SLATE, COPPER, 3);
  k.cyl(W / 2 - 0.35, 0, -0.6, 0.12, 1.9, pick(r, BRICK), 8);
  k.cyl(W / 2 - 0.35, 1.8, -0.6, 0.14, 0.08, BLACK, 8);
  k.box(W / 2 - 0.35, 0, 0.3, 0.5, 0.3, 0.5, hex(0x4a3f3a));
  for (let i = 0; i < 4; i++) k.box(-0.6 + i * 0.25, 0, fz + 0.3, 0.2, 0.06 + (i % 2) * 0.05, 0.12, hex(0xa0a8b0), hex(0xc8d0d8));
  k.glowBox(-0.2, 0.2, fz + 0.02, 0.3, 0.2, 0.02, hex(0xf28c38), [0, 24, 2], hex(0xffa060));
  sign(k, -0.2, 0.96, fz + 0.03, 0.9, COPPER);
};

/** A glassworks: a furnace hall with a conical kiln, sheets of glass leaning on A-frames. */
const glassworks: Draw = (k, W, D, b, r) => {
  pad(k, W, D, CONCRETE);
  const fz = shed(k, b, r, -0.3, -0.15, W - 1.0, D - 0.7, 0.7, pick(r, BRICK), SLATE, hex(0x2f7fb5), 3);
  k.cone(W / 2 - 0.45, 0, -0.2, 0.42, 1.3, pick(r, BRICK), 10);
  k.cyl(W / 2 - 0.45, 1.2, -0.2, 0.08, 0.2, BLACK, 6);
  for (let i = 0; i < 3; i++) {
    const x = -0.6 + i * 0.4;
    k.box(x, 0, fz + 0.25, 0.3, 0.32, 0.02, hex(0x9fd0e0), hex(0xc8e8f2));
    k.box(x, 0, fz + 0.32, 0.02, 0.3, 0.12, WOOD);
  }
  sign(k, -0.3, 0.76, fz + 0.03, 0.8, hex(0x2f7fb5));
};

// ---- 14 Fleece and couture, 21 Going, going, 22 Encore, 24 Snowline ----------------------------

/** A shopfront workshop for the fine trades: a tall window, an awning, a sign in its colour, a mannequin or a lamp. */
function boutique(k: Kit, W: number, D: number, b: Parameters<Draw>[3], r: Rng, wallTone: RGB, colour: RGB, awning: RGB, h = 0.9): number {
  pad(k, W, D, CONCRETE);
  k.box(0, 0, -0.1, W - 0.3, h, D - 0.5, wallTone);
  k.box(0, h, -0.1, W - 0.26, 0.06, D - 0.46, SLATE);
  const fz = -0.1 + (D - 0.5) / 2;
  k.box(0, 0.08, fz + 0.006, W - 0.7, 0.42, 0.012, GLASS);
  k.glowBox(0, 0.25, fz - 0.02, W - 0.8, 0.25, 0.01, GLASS, SIGN, SHOP_GLOW);
  k.box(0, 0.54, fz + 0.12, W - 0.5, 0.025, 0.24, awning);
  sign(k, 0, 0.62, fz + 0.03, W - 0.7, colour);
  row(k, b, r, 0, h * 0.72, fz, W - 0.6, 0.14, 3, 1);
  return fz;
}

const atelier: Draw = (k, W, D, b, r) => {
  const fz = boutique(k, W, D, b, r, CREAM, hex(0xa84a8a), hex(0x2a2a2e));
  k.cyl(-0.3, 0.08, fz - 0.15, 0.05, 0.3, hex(0xa84a8a), 8);
  k.cyl(-0.3, 0.38, fz - 0.15, 0.04, 0.06, CREAM, 6);
};

const auctionHouse: Draw = (k, W, D, b, r) => {
  const fz = boutique(k, W, D, b, r, pick(r, STONE), GOLD, hex(0x6a4a8a), 1.0);
  for (const x of [-0.6, 0.6]) k.cyl(x, 0, fz + 0.02, 0.05, 0.9, CREAM, 8);
  k.gable(0, 1.0, fz - 0.05, W - 0.4, 0.14, 0.2, SLATE, CREAM);
};

const luthier: Draw = (k, W, D, b, r) => {
  const fz = boutique(k, W, D, b, r, pick(r, BRICK), hex(0x9a5a2e), hex(0x2f5a3e), 0.8);
  // a fiddle in the window
  k.cyl(0, 0.16, fz - 0.05, 0.05, 0.04, hex(0x9a5a2e), 8);
  k.cyl(0, 0.24, fz - 0.05, 0.04, 0.04, hex(0x9a5a2e), 8);
  k.box(0, 0.28, fz - 0.05, 0.015, 0.1, 0.015, BLACK);
};

const outfitter: Draw = (k, W, D, b, r) => {
  const fz = boutique(k, W, D, b, r, WOOD, hex(0x2f6f9c), hex(0xe2412f), 0.85);
  // skis and a sledge by the door
  for (let i = 0; i < 3; i++) k.box(W / 2 - 0.3 + i * 0.05, 0, fz + 0.06, 0.02, 0.5, 0.03, i === 1 ? hex(0xe2412f) : hex(0xf2c14e));
  k.box(-W / 2 + 0.35, 0, fz + 0.25, 0.3, 0.05, 0.14, WOOD);
};

/** A roastery: a café-fronted roasting shed, a copper drum roaster in the window, sacks on the step. */
const roastery: Draw = (k, W, D, b, r) => {
  const fz = boutique(k, W, D, b, r, pick(r, BRICK), hex(0x5a3a2a), hex(0xf2c14e), 0.8);
  k.cyl(0.3, 0.08, fz - 0.15, 0.1, 0.18, COPPER, 10);
  k.cyl(0.3, 0.26, fz - 0.15, 0.03, 0.3, BLACK, 6);
  for (let i = 0; i < 3; i++) k.box(-0.5 + i * 0.16, 0, fz + 0.2, 0.14, 0.12, 0.1, hex(0xc9a87a), hex(0xb8986a));
};

export const PLANT_DRAW: Record<PlantKind, Draw> = {
  iceHouse, creamery, bindery, joinery, printShop, parcelHub, readyMix, smokehouse, winery, alloyWorks,
  atelier, roastery, cooperage, glassworks, auctionHouse, luthier, outfitter,
};

void TAU; void METAL;
