import { hex, scale, type RGB } from '../../world/biomes';
import type { PlayKind } from '../../world/playKinds';
import { DARK, GLASS, METAL, WARM_GLOW, WATER, type Draw, type Kit } from './kit';

/**
 * A mine's buildings (world/mines.ts, 0.7.0): the ore processing plant with its mill house, thickener tanks and
 * conveyor gantry; the tailings pond in its embankment; a crawler crane with its lattice boom; a derrick over a
 * cut face; the gravel screening plant; the walking dragline with its long boom and bucket; and the coal tipple
 * over its loading track. Machines in safety yellow, steel grey and rust.
 */

const YELLOW = hex(0xf2b21e), RUST = hex(0x9a5a34), STEEL = hex(0x8a8f95), STEEL_D = hex(0x5d6166), CONCRETE = hex(0xc9c4b8);
const SHED = hex(0xb8bcc0), SHED_ROOF = hex(0x7a7f85), SLUDGE = hex(0xb7a98c), SLURRY = hex(0x8fa3a0), SAND = hex(0xd9c79a);

/** A lattice mast or boom between two points: four chords and zig-zag bracing, in boxes and bars. */
function lattice(k: Kit, a: [number, number, number], b: [number, number, number], w: number, col: RGB): void {
  const off: [number, number][] = [[-w, -w], [w, -w], [w, w], [-w, w]];
  const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2];
  // two directions across the boom: horizontal across it, and one square to that and the boom
  const len = Math.hypot(dx, dy, dz) || 1, ux = dx / len, uy = dy / len, uz = dz / len;
  let px = -uz, py = 0, pz = ux;
  const pl = Math.hypot(px, pz) || 1; px /= pl; pz /= pl;
  const qx = uy * pz - uz * py, qy = uz * px - ux * pz, qz = ux * py - uy * px;
  const at = (p: [number, number, number], s: number, t: number): [number, number, number] => [p[0] + px * s + qx * t, p[1] + py * s + qy * t, p[2] + pz * s + qz * t];
  for (const [s, t] of off) k.bar(at(a, s, t), at(b, s, t), 0.012, col);
  const n = Math.max(2, Math.round(len / 0.22));
  for (let i = 0; i < n; i++) {
    const f0 = i / n, f1 = (i + 1) / n;
    const p0: [number, number, number] = [a[0] + dx * f0, a[1] + dy * f0, a[2] + dz * f0], p1: [number, number, number] = [a[0] + dx * f1, a[1] + dy * f1, a[2] + dz * f1];
    k.bar(at(p0, -w, -w), at(p1, w, -w), 0.007, col);
    k.bar(at(p0, w, w), at(p1, -w, w), 0.007, col);
  }
}

/** The ore processing plant: a tall mill house, a conveyor gantry up into it, two thickener tanks and a bin. */
const oreMill: Draw = (k, W, D) => {
  k.box(0, 0, 0, W - 0.2, 0.08, D - 0.2, CONCRETE);
  k.box(-W * 0.18, 0.08, -0.1, W * 0.5, 1.1, D * 0.6, SHED, SHED_ROOF);
  k.gable(-W * 0.18, 1.18, -0.1, W * 0.52, 0.25, D * 0.62, SHED_ROOF, SHED);
  for (let i = 0; i < 4; i++) k.glowBox(-W * 0.18 - W * 0.2 + i * W * 0.13, 0.55, -0.1 + D * 0.3 + 0.004, 0.12, 0.08, 0.02, GLASS, [18, 30, 0.8], WARM_GLOW);
  // the gantry: a covered belt rising from the apron's front into the top of the mill house
  k.bar([W / 2 - 0.3, 0.12, D / 2 - 0.3], [-W * 0.05, 1.0, 0.1], 0.06, STEEL_D);
  k.box(W / 2 - 0.5, 0.08, D / 2 - 0.5, 0.06, 0.25, 0.06, STEEL);
  k.box(W * 0.12, 0.08, 0.3, 0.06, 0.6, 0.06, STEEL);
  // thickeners: wide round tanks of grey slurry
  for (const [x, z] of [[W * 0.28, -D * 0.22], [W * 0.28, D * 0.2]]) {
    k.cyl(x, 0.08, z, 0.55, 0.22, CONCRETE, 14, SLURRY);
    k.bar([x - 0.55, 0.32, z], [x + 0.55, 0.32, z], 0.02, STEEL);
  }
  // the ore bin on its legs over the truck bay
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(-W * 0.42 + sx * 0.25, 0.08, D * 0.3 + sz * 0.2, 0.05, 0.55, 0.05, STEEL_D);
  k.box(-W * 0.42, 0.63, D * 0.3, 0.6, 0.35, 0.5, RUST);
};

/** The tailings pond: grey-brown sludge drying behind a terraced embankment, a pipe running in over its wall. */
const tailings: Draw = (k, W, D) => {
  for (const [w, d, y, c] of [[W - 0.1, D - 0.1, 0, SAND], [W - 0.5, D - 0.5, 0.12, scale(SAND, 0.92)]] as const) k.box(0, y, 0, w, 0.12, d, c);
  k.box(0, 0.2, 0, W - 0.9, 0.05, D - 0.9, SLUDGE);
  k.box(0.6, 0.21, 0.4, W * 0.4, 0.05, D * 0.35, SLURRY);
  k.bar([-W / 2, 0.3, D / 2 - 0.4], [-W / 2 + 1.4, 0.3, D / 2 - 0.4], 0.035, STEEL_D);
};

/** A crawler crane: tracks, a turning house and a long lattice boom raised high with its hook hanging. */
const crawlerCrane: Draw = (k, W, D) => {
  for (const sx of [-1, 1]) k.box(sx * 0.32, 0, 0, 0.22, 0.16, D - 0.6, DARK);
  k.box(0, 0.16, -0.15, 0.62, 0.32, 0.8, YELLOW, scale(YELLOW, 0.9));
  k.box(0.2, 0.48, 0.12, 0.2, 0.2, 0.22, GLASS);
  k.box(0, 0.16, -0.6, 0.62, 0.22, 0.25, STEEL_D);
  lattice(k, [0, 0.4, 0.2], [0, 2.1, 1.1], 0.06, YELLOW);
  k.bar([0, 2.1, 1.1], [0, 0.9, 1.15], 0.006, DARK);
  k.box(0, 0.8, 1.15, 0.08, 0.1, 0.08, STEEL_D);
};

/** A derrick: a tall guyed mast over the face with a boom swung out from its foot and a hook block on its rope. */
const derrick: Draw = (k, W, D) => {
  k.box(0, 0, 0, W - 0.4, 0.1, D - 0.4, CONCRETE);
  lattice(k, [0, 0.1, 0], [0, 2.5, 0], 0.07, RUST);
  lattice(k, [0, 0.2, 0], [0, 1.6, 1.6], 0.05, RUST);
  k.bar([0, 2.5, 0], [0, 1.6, 1.6], 0.008, DARK);
  k.bar([0, 1.6, 1.6], [0, 0.7, 1.6], 0.006, DARK);
  k.box(0, 0.6, 1.6, 0.1, 0.12, 0.1, YELLOW);
  for (const [gx, gz] of [[-1.4, -1.4], [1.4, -1.4], [-1.6, 0.6]]) k.bar([0, 2.45, 0], [gx, 0.05, gz], 0.005, STEEL_D);
  k.box(-0.55, 0.1, -0.4, 0.4, 0.3, 0.35, YELLOW);
};

/** The gravel screening plant: shaking screens on a steel frame over bays of sorted gravel, a belt off each side. */
const gravelPlant: Draw = (k, W, D) => {
  k.box(0, 0, 0, W - 0.2, 0.06, D - 0.2, CONCRETE);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 0.6, 0.06, sz * 0.4, 0.06, 0.6, 0.06, STEEL_D);
  k.box(0, 0.66, 0, 1.5, 0.12, 1.0, YELLOW);
  k.box(0, 0.78, 0, 1.3, 0.08, 0.8, STEEL);
  // three bays of sorted stone under it, and belts off to the heaps
  for (let i = -1; i <= 1; i++) k.cyl(i * 0.5, 0.06, D / 2 - 0.55, 0.3, 0.22, SAND, 8, scale(SAND, 1 - 0.08 * (i + 1)));
  for (const s of [-1, 1]) k.bar([s * 0.7, 0.7, 0], [s * (W / 2 - 0.2), 0.3, -0.3], 0.05, DARK);
  k.box(-W / 2 + 0.4, 0.06, -D / 2 + 0.35, 0.5, 0.35, 0.4, YELLOW);
};

/** A walking dragline: a great house on its round tub, a long lattice boom out over the cut and the bucket hung from it. */
const dragline: Draw = (k, W, D) => {
  k.cyl(0, 0, 0, Math.min(W, D) / 2 - 0.2, 0.15, STEEL_D, 14);
  for (const sx of [-1, 1]) k.box(sx * (W / 2 - 0.25), 0, 0, 0.3, 0.12, 1.6, STEEL_D);
  k.box(0, 0.15, -0.2, 1.7, 0.75, 1.9, SHED, SHED_ROOF);
  k.box(0.45, 0.9, 0.55, 0.5, 0.3, 0.4, GLASS);
  lattice(k, [0, 0.9, -0.4], [0, 2.4, -0.4], 0.08, STEEL);
  lattice(k, [0, 0.4, 0.75], [0, 1.9, 5.5], 0.1, YELLOW);
  for (const s of [-1, 1]) k.bar([0, 2.4, -0.4], [s * 0.08, 1.9, 5.5], 0.008, DARK);
  k.bar([0, 1.9, 5.5], [0, 0.55, 5.2], 0.008, DARK);
  k.box(0, 0.25, 5.1, 0.55, 0.3, 0.45, RUST);
};

/** The coal tipple: a tall timber-and-iron loading house over the track, a belt up into it, chutes over the bay. */
const coalTipple: Draw = (k, W, D) => {
  k.box(0, 0, 0, W - 0.2, 0.06, D - 0.2, scale(DARK, 1.3));
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 0.6, 0.06, sz * 0.6, 0.08, 0.8, 0.08, RUST);
  k.box(0, 0.86, 0, 1.6, 0.55, 1.5, RUST, scale(RUST, 0.85));
  k.gable(0, 1.41, 0, 1.7, 0.25, 1.6, SHED_ROOF, RUST);
  k.bar([0, 1.1, 0.6], [0, 0.1, D / 2 + 1.4], 0.07, STEEL_D);
  for (const sx of [-0.35, 0.35]) k.bar([sx, 0.86, -0.2], [sx, 0.45, -0.55], 0.04, METAL);
  k.box(0, 0.06, -0.9, W - 0.4, 0.04, 0.3, hex(0x6b5a45));
  k.box(0, 0.06, -0.9, 0.7, 0.3, 0.32, scale(DARK, 1.6));
  k.glowBox(0.5, 0.95, 0.756, 0.18, 0.12, 0.02, GLASS, [18, 30, 0.8], WARM_GLOW);
  void WATER;
};

/** A mine's models, by kind (render/buildings/play.ts gathers them with the places to play). */
export const MINE_DRAW: Partial<Record<PlayKind, Draw>> = { oreMill, tailings, crawlerCrane, derrick, gravelPlant, dragline, coalTipple };
