import * as THREE from 'three';
import { N, SEA, STEP, DIRS, EDGE_MINE, heightAt, idx, inB, tileMean, type World } from '../world/tiles';
import { buildOutline, disposeObject } from '../render/roadMesh';
import { pickGround } from '../render/pick';
import {
  LAND, acrossEdge, commitPlan, emptyUndo, landProblem, planLand, planPinned, planWater, revert, type Plan, type Selection, type Style, type TownGate, type Undo,
} from '../world/land';
import { encodeLand, type LandBlock } from '../world/landCodec';
import { money, type CargoHud } from './cargoHud';
import type { Wallet } from './economy';
import type { Input } from './input';
import type { FollowCamera } from './camera';
import { deeds } from './deeds';
import { clamp } from '../util/math';

/** Pixels of mouse travel for one step of ground, as in RollerCoaster Tycoon 2. */
const STEP_PX = 22;
/** Saved land past which the panel's meter turns amber, in KB. */
const SAVE_WARN_KB = 250;

type Mode = 'land' | 'water';

interface Stroke {
  undo: Undo;
  tiles: Set<number>;
  cost: number;
  lifts: number;
  sel: Selection;
  /** The Shift drag: every tile the brush crosses goes to this height. */
  level?: number;
  reclaimed: number; opened: number; lakes: number; summit: number;
  /** The counties over a line the stroke was carried into (carry): each one's undo and the tiles it moved there. */
  more: Map<World, { undo: Undo; tiles: Set<number> }>;
}

/**
 * The U tool (docs/terrain.html): earthworks. Hover a tile — or at brush 1, one of its corners — press,
 * and drag the mouse up or down; the ground comes with it a step at a time and every step is paid for
 * as it happens. V switches to water, F between cliff and smooth, 1–7 the brush, Shift-drag levels,
 * Z takes back the last stroke with a full refund.
 */
export class LandTool {
  active = false;
  readonly focus = new THREE.Vector3();
  mode: Mode = 'land';
  style: Style = 'cliff';
  brush = 1;
  strokes = 0;
  lifts = 0;
  spent = 0;
  /** Sculpt without paying (pr.land.free, for testing). */
  free = false;
  /** Tiles with a vehicle on them, which sit every step out. */
  occupied: ((w: World) => Set<number>) | null = null;
  /** The ground moved under the drag: redraw these tiles now, cheaply. */
  onGround: ((w: World, tiles: number[]) => void) | null = null;
  /** A stroke is finished (or taken back): everything that reads the world should look again. */
  onStroke: ((w: World, tiles: number[]) => void) | null = null;
  /** The island's overlay has changed: this is what goes in its save delta now. */
  onLand: ((w: World, land: LandBlock | undefined) => void) | null = null;
  /** Whether the player's fleet holds a town as its territory: its open ground is theirs to grade. */
  ownsTown: ((w: World, town: number) => boolean) | null = null;
  /**
   * The county in memory at a cell, or null (main.ts: the islands). The tool works on whichever loaded county the
   * cursor is over (the user, 5 Nov 2026: a land bridge to the next county couldn't be finished without driving
   * there): a stroke stays in the county it began in; between strokes, the brush goes over the border.
   */
  worldAt: ((cx: number, cz: number) => World | null) | null = null;

  private w: World | null = null;
  private ox = 0;
  private oz = 0;
  private sel: Selection | null = null;
  private hoverKey = '';
  private stroke: Stroke | null = null;
  private history: { w: World; undo: Undo; tiles: number[]; cost: number; lifts: number; more: { w: World; undo: Undo; tiles: number[] }[] }[] = [];
  private acc = 0;
  private pending = new Set<number>();
  private blocked: Set<number> = new Set();
  /** Towns asked about this frame, so a ripple of hundreds of tiles asks each town once. */
  private held = new Map<number, boolean>();
  private towns: TownGate = (t) => {
    let h = this.held.get(t);
    if (h === undefined) this.held.set(t, (h = !!this.w && !!this.ownsTown?.(this.w, t)));
    return h;
  };
  private savedKB = 0;
  private layer = new THREE.Group();
  private marks: THREE.Object3D[] = [];
  private leakMarks: THREE.Object3D[] = [];
  private panel = document.getElementById('earth')!;
  private tip = document.getElementById('earth-tip')!;
  private help = document.getElementById('br')!;
  private tipTitle = document.createElement('b');
  private tipBody = document.createElement('span');
  private modeEl = document.createElement('div');
  private countEl = document.createElement('div');
  private fwd = new THREE.Vector2();

  constructor(scene: THREE.Scene, private cam: FollowCamera, private wallet: Wallet, private hud: CargoHud) {
    scene.add(this.layer);
    this.tip.append(this.tipTitle, this.tipBody);
    this.countEl.className = 'count';
    this.modeEl.className = 'modes';
    const head = document.createElement('header');
    head.innerHTML = '<b>Earthworks<span>.</span></b><span><kbd>T</kbd> done</span>';
    const help = document.createElement('div');
    help.className = 'help';
    help.innerHTML = 'Press on the ground and drag <b>up</b> to raise, <b>down</b> to lower<br>'
      + '<kbd>Shift</kbd>+drag across the ground to level it<br>'
      + '<kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> pan · wheel zoom · <kbd>Z</kbd> undo<br>'
      + `$${LAND.lift} a corner a step · rock ×${LAND.rock} · under water ×${LAND.wet}`;
    this.panel.append(head, this.modeEl, help, this.countEl);
    // Land/Water, Cliff/Smooth and the brush size are buttons: click them, same as the keyboard shortcuts.
    this.modeEl.addEventListener('click', (e) => {
      if (this.stroke) return;
      const b = (e.target as HTMLElement).closest('button');
      if (!b || b.disabled) return;
      if (b.dataset.mode) this.mode = b.dataset.mode as Mode;
      else if (b.dataset.style) this.style = b.dataset.style as Style;
      else if (b.dataset.brush) this.brush = Number(b.dataset.brush);
      this.hoverKey = '';
      this.paint();
    });
    this.paint();
  }

  setWorld(w: World): void {
    this.close();
    this.w = w;
    this.ox = w.ox;
    this.oz = w.oz;
    this.layer.position.set(w.ox, 0, w.oz);
    this.strokes = this.lifts = this.spent = 0;
    this.savedKB = sizeKB(encodeLand(w));
    this.paint();
  }

  /** Work on another loaded county (the brush has gone over the border), the tool staying open. */
  private retarget(w: World): void {
    if (w === this.w || this.stroke) return;
    this.clearMarks();
    this.clearLeaks();
    this.w = w;
    this.ox = w.ox;
    this.oz = w.oz;
    this.layer.position.set(w.ox, 0, w.oz);
    this.blocked = this.occupied?.(w) ?? new Set();
    this.held.clear();
    this.savedKB = sizeKB(encodeLand(w));
    this.hoverKey = '';
    this.paint();
  }

  /** The loaded county under a world point (this one first), or null. */
  private countyAt(gx: number, gz: number): World | null {
    const w = this.w;
    if (w && gx >= w.ox && gz >= w.oz && gx < w.ox + N && gz < w.oz + N) return w;
    return this.worldAt?.(Math.floor(gx / N), Math.floor(gz / N)) ?? null;
  }

  /**
   * The county the cursor is over and what the brush covers there: this one first, else any loaded neighbour
   * (a ray meets only one county's ground). Null over nothing loaded.
   */
  private pickAny(camera: THREE.Camera, cx: number, cy: number): { w: World; sel: Selection } | null {
    const w = this.w;
    if (!w) return null;
    const here = this.pickSel(w, camera, cx, cy);
    if (here) return { w, sel: here };
    if (!this.worldAt) return null;
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dz) continue;
      const n = this.worldAt(w.cx + dx, w.cz + dz);
      if (!n) continue;
      const sel = this.pickSel(n, camera, cx, cy, n.ox, n.oz);
      if (sel) return { w: n, sel };
    }
    return null;
  }

  toggle(from: THREE.Vector3): void {
    if (this.active) this.close();
    else this.open(from);
  }

  open(from: THREE.Vector3): void {
    if (!this.w) return;
    this.active = true;
    this.focus.copy(from);
    this.cam.minDist = 26;
    this.cam.maxDist = 420;
    this.panel.hidden = false;
    this.help.hidden = true;
    this.hoverKey = '';
    this.blocked = this.occupied?.(this.w) ?? new Set();
    this.paint();
  }

  close(): void {
    this.finish();
    this.active = false;
    this.cam.minDist = 20;
    this.cam.maxDist = 140;
    this.panel.hidden = true;
    this.help.hidden = false;
    this.tip.hidden = true;
    this.clearMarks();
    this.clearLeaks();
    this.sel = null;
    this.hoverKey = '';
    // undo is for this visit only: once the world runs again, a town may have built on the ground
    this.history = [];
  }

  update(dt: number, input: Input, camera: THREE.Camera): void {
    const w = this.w;
    if (!this.active || !w) return;
    this.held.clear();
    if (input.justPressed('Escape') || input.justPressed('KeyT')) { this.close(); return; }
    if (!this.stroke) {
      let changed = false;
      if (input.justPressed('KeyV')) { this.mode = this.mode === 'land' ? 'water' : 'land'; changed = true; }
      if (input.justPressed('KeyF')) { this.style = this.style === 'cliff' ? 'smooth' : 'cliff'; changed = true; }
      for (let k = 1; k <= 7; k++) if (input.justPressed(`Digit${k}`)) { this.brush = k; changed = true; }
      if (input.justPressed('KeyZ')) this.undo();
      if (changed) { this.hoverKey = ''; this.paint(); }
    }

    // pan relative to the camera, like the road builder
    const f = this.cam.forwardXZ(this.fwd);
    const pan = this.cam.dist * 0.45 * dt;
    const th = input.throttle, st = input.steer;
    // over the border into a county in memory, as far as one is loaded (the user, 5 Nov 2026)
    const nx = this.focus.x + (f.x * th + f.y * st) * pan, nz = this.focus.z + (f.y * th - f.x * st) * pan;
    if (this.countyAt(nx, this.focus.z)) this.focus.x = nx;
    if (this.countyAt(this.focus.x, nz)) this.focus.z = nz;
    const fw = this.countyAt(this.focus.x, this.focus.z) ?? w;
    const gy = heightAt(fw, clamp(this.focus.x - fw.ox, 0, N - 0.001), clamp(this.focus.z - fw.oz, 0, N - 0.001));
    this.focus.y += (gy - this.focus.y) * Math.min(1, dt * 6);

    const shift = input.down('ShiftLeft') || input.down('ShiftRight');
    if (input.leftHeld) {
      if (!this.stroke) {
        const from = input.leftFrom!;
        const at = this.pickAny(camera, from.x, from.y);
        // the press is over the next county: the stroke is that county's, begun on the next frame (the button
        // is still down) with everything this frame read of the county read again
        if (at && at.w !== this.w) { this.retarget(at.w); return; }
        const sel = at?.sel ?? null;
        input.takeLeftDY();
        this.acc = 0;
        if (sel) {
          const level = shift && this.mode === 'land' ? Math.round(tileMean(w, sel.tiles[Math.floor(sel.tiles.length / 2)])) : undefined;
          this.stroke = { undo: emptyUndo(), tiles: new Set(), cost: 0, lifts: 0, sel, level, reclaimed: 0, opened: 0, lakes: 0, summit: -Infinity, more: new Map() };
          this.clearLeaks();
        }
      }
      const s = this.stroke;
      if (s && s.level !== undefined) {
        // the Shift drag: the brush follows the cursor, and everything under it comes to one height
        const sel = input.hasMouse ? this.pickSel(w, camera, input.mouseX, input.mouseY) : null;
        if (sel) {
          s.sel = sel;
          this.markSel(w, sel);
          const p = planLand(w, sel, 0, { style: this.style, occupied: this.blocked, towns: this.towns, edges: this.edgesOf(w) }, s.level);
          if (p.ok && p.corners.size) this.apply(p);
          else if (!p.ok && p.leaks.length) this.showLeaks(w, p);
        }
        input.takeLeftDY();
      } else if (s) {
        this.acc += input.takeLeftDY();
        // mouse up raises, mouse down lowers
        while (this.acc <= -STEP_PX) { this.acc += STEP_PX; if (!this.step(1)) { this.acc = 0; break; } }
        while (this.acc >= STEP_PX) { this.acc -= STEP_PX; if (!this.step(-1)) { this.acc = 0; break; } }
      }
    } else {
      if (this.stroke) this.finish();
      if (input.hasMouse) {
        const at = this.pickAny(camera, input.mouseX, input.mouseY);
        if (at && at.w !== this.w) this.retarget(at.w);
        const sel = at?.sel ?? null;
        this.hover(this.w!, sel);
        if (!this.tip.hidden) this.placeTip(input.mouseX, input.mouseY);
      }
    }
    if (this.stroke && input.hasMouse && !this.tip.hidden) this.placeTip(input.mouseX, input.mouseY);
    this.flush();
  }

  // ---------------------------------------------------------------------------------------------

  /** What the brush covers with the cursor at (clientX, clientY). */
  private pickSel(w: World, camera: THREE.Camera, cx: number, cy: number, ox = this.ox, oz = this.oz): Selection | null {
    const hit = pickGround(w, camera, cx, cy, ox, oz);
    if (!hit) return null;
    const hx = hit.x, hz = hit.z;
    const n = this.brush;
    if (n === 1) {
      const x = Math.floor(hx), z = Math.floor(hz);
      if (!inB(x, z)) return null;
      const fx = hx - x, fz = hz - z;
      const q = fx < 0.5 ? (fz < 0.5 ? 0 : 3) : (fz < 0.5 ? 1 : 2);
      const qx = q === 1 || q === 2 ? 1 : 0, qz = q === 2 || q === 3 ? 1 : 0;
      const grip = this.mode === 'land' && Math.hypot(fx - qx, fz - qz) < 0.28;
      return grip ? { tiles: [idx(x, z)], corner: q } : { tiles: [idx(x, z)] };
    }
    const x0 = clamp(Math.floor(hx - (n - 1) / 2), 0, N - n), z0 = clamp(Math.floor(hz - (n - 1) / 2), 0, N - n);
    const tiles: number[] = [];
    for (let z = z0; z < z0 + n; z++) for (let x = x0; x < x0 + n; x++) tiles.push(idx(x, z));
    return { tiles };
  }

  /**
   * Which tiles of a county's outer ring may move (the user, 5 Nov 2026: a smooth mountain by a county line was cut off
   * at it): those whose county over the line is in memory, every one of them for a corner tile, so a step there can be
   * carried over (carry). Null without the islands to ask.
   */
  private edgesOf(w: World): ((i: number) => boolean) | undefined {
    const at = this.worldAt;
    if (!at) return undefined;
    return (i: number) => {
      const x = i % N, z = (i - x) / N;
      const dx = x === 0 ? -1 : x === N - 1 ? 1 : 0, dz = z === 0 ? -1 : z === N - 1 ? 1 : 0;
      if (dx && !at(w.cx + dx, w.cz)) return false;
      if (dz && !at(w.cx, w.cz + dz)) return false;
      if (dx && dz && !at(w.cx + dx, w.cz + dz)) return false;
      return true;
    };
  }

  /**
   * A step that moved corners on the county's edge, carried over the line: each county over it takes those corners to
   * the same heights and lets the ground follow on from them (world/land.ts planPinned), paid for with the step. A
   * carry that can't be taken (the ground there won't go, or the money's gone) leaves the line a cliff, as it was.
   */
  private carry(w: World, p: Plan): void {
    const s = this.stroke;
    if (!s || !this.worldAt) return;
    const over = new Map<string, { n: World; dx: number; dz: number; pins: Map<number, number> }>();
    for (const [k, v] of p.corners) {
      for (const [dx, dz, kb] of acrossEdge(k)) {
        const key = `${dx},${dz}`;
        let e = over.get(key);
        if (!e) {
          const n = this.worldAt(w.cx + dx, w.cz + dz);
          if (!n) continue;
          over.set(key, (e = { n, dx, dz, pins: new Map() }));
        }
        e.pins.set(kb, v);
      }
    }
    for (const e of over.values()) {
      const held = new Map<number, boolean>();
      const towns: TownGate = (t) => { let h = held.get(t); if (h === undefined) held.set(t, (h = !!this.ownsTown?.(e.n, t))); return h; };
      const q = planPinned(e.n, e.pins, -e.dx, -e.dz, { style: this.style, occupied: this.occupied?.(e.n) ?? new Set(), towns, edges: this.edgesOf(e.n) });
      if (!q.ok || !q.corners.size) continue;
      if (!this.free && !this.wallet.spend(q.cost, 'earthworks')) continue;
      const m = s.more.get(e.n) ?? { undo: emptyUndo(), tiles: new Set<number>() };
      s.more.set(e.n, m);
      commitPlan(e.n, q, m.undo);
      for (const tl of q.tiles) m.tiles.add(tl);
      s.cost += q.cost;
      s.lifts += q.lifts;
      s.reclaimed += q.reclaimed;
      this.onGround?.(e.n, ring(q.tiles));
    }
  }

  private plan(w: World, sel: Selection, dir: 1 | -1): Plan {
    return this.mode === 'land'
      ? planLand(w, sel, dir, { style: this.style, occupied: this.blocked, towns: this.towns, edges: this.edgesOf(w) })
      : planWater(w, sel, dir, { occupied: this.blocked, towns: this.towns });
  }

  /** The cursor has moved: outline what the brush covers and price a step either way. */
  private hover(w: World, sel: Selection | null): void {
    const key = sel ? `${this.mode}|${this.style}|${sel.tiles[0]}|${sel.tiles.length}|${sel.corner ?? -1}|${w.revision}` : '';
    if (key === this.hoverKey) return;
    this.hoverKey = key;
    this.sel = sel;
    if (!sel) { this.clearMarks(); this.tip.hidden = true; return; }
    this.markSel(w, sel);
    const up = this.plan(w, sel, 1), down = this.plan(w, sel, -1);
    const verb = this.mode === 'land' ? ['Raise', 'Lower'] : ['Fill', 'Drain'];
    const price = (p: Plan) => (p.ok && (p.corners.size || p.water.size) ? money(p.cost) : '—');
    const title = `${verb[0]} ${price(up)} · ${verb[1].toLowerCase()} ${price(down)}`;
    const what = sel.corner !== undefined ? 'one corner' : `${this.brush} × ${this.brush}`;
    const lines = [`${what} · ${this.mode === 'land' ? this.style : 'water'} · drag up or down`];
    const refused = up.refused.length || down.refused.length ? Math.max(up.refused.length, down.refused.length) : 0;
    const why = up.reason ?? down.reason;
    const firstRefused = up.refused[0] ?? down.refused[0];
    if (refused && refused < sel.tiles.length && firstRefused !== undefined) lines.push(`${refused} sit out: ${landProblem(w, firstRefused, this.style, this.towns) ?? 'a vehicle is there'}`);
    const good = (up.ok && (up.corners.size || up.water.size)) || (down.ok && (down.corners.size || down.water.size));
    if (!good && why) lines.push(why);
    else if (!this.free && !this.wallet.canAfford(Math.min(up.ok ? up.cost : Infinity, down.ok ? down.cost : Infinity))) lines.push(`Not enough cash — you have ${money(this.wallet.cash)}`);
    if (up.flooded || down.flooded) lines.push(this.mode === 'land' ? 'Water will come in' : '');
    // under water (the user, 5 Nov 2026: working the seabed was guesswork): how deep the ground lies
    const mid = sel.tiles[Math.floor(sel.tiles.length / 2)];
    if (w.water[mid] >= 0) {
      const deep = Math.max(0, Math.round(w.water[mid] - tileMean(w, mid)));
      lines.push(deep ? `Under water · ${deep} step${deep === 1 ? '' : 's'} below the surface` : 'Under water · just under the surface');
    }
    this.setTip(good ? 'ok' : 'bad', title, lines.filter(Boolean).join('\n'));
  }

  /**
   * Where the brush is, world tiles, and how wide, for the water to thin round it (main.ts: render/mesher.ts
   * setWaterWindow): the seabed under the brush shows through. Null when the cursor is over nothing.
   */
  get aim(): { x: number; z: number; r: number } | null {
    const w = this.w, sel = this.stroke?.sel ?? this.sel;
    if (!w || !sel || !this.active) return null;
    const mid = sel.tiles[Math.floor(sel.tiles.length / 2)];
    const x = mid % N, z = (mid - x) / N;
    return { x: w.ox + x + (this.brush % 2 ? 0.5 : 0), z: w.oz + z + (this.brush % 2 ? 0.5 : 0), r: 10 + this.brush * 1.5 };
  }

  /** One step of a drag. False when it could not be taken. */
  private step(dir: 1 | -1): boolean {
    const w = this.w!, s = this.stroke!;
    const p = this.plan(w, s.sel, dir);
    if (!p.ok || (!p.corners.size && !p.water.size)) {
      if (p.leaks.length) this.showLeaks(w, p);
      this.setTip('bad', p.reason ?? 'Nothing to move', p.leaks.length ? 'Red edges have nothing to hold the water' : '');
      return false;
    }
    return this.apply(p);
  }

  /** Pay for a plan and write it in. */
  private apply(p: Plan): boolean {
    const w = this.w!, s = this.stroke!;
    if (!this.free && !this.wallet.spend(p.cost, 'earthworks')) {
      this.setTip('bad', 'Not enough cash', `That step costs ${money(p.cost)} — you have ${money(this.wallet.cash)}`);
      return false;
    }
    // standing water made above the sea, on a tile that was dry
    for (const [i, v] of p.water) if (v > SEA && w.water[i] < 0) s.lakes++;
    for (const [k, v] of p.corners) if (v > w.corners[k]) s.summit = Math.max(s.summit, v);
    commitPlan(w, p, s.undo);
    this.carry(w, p);
    s.cost += p.cost;
    s.lifts += p.lifts;
    s.reclaimed += p.reclaimed;
    s.opened += p.opened;
    for (const t of p.tiles) { s.tiles.add(t); this.pending.add(t); }
    this.clearLeaks();
    // a float at the brush for every step, as the chip ticks down
    const mid = p.tiles[Math.floor(p.tiles.length / 2)];
    const mx = mid % N, mz = (mid - mx) / N;
    if (p.cost > 0) this.hud.float(`-${money(p.cost)}`, new THREE.Vector3(mx + 0.5 + this.ox, heightAt(w, mx + 0.5, mz + 0.5) + 0.6, mz + 0.5 + this.oz), 'bad');
    this.setTip('ok', `${this.mode === 'land' ? 'Moving' : 'Water'} · ${money(s.cost)}`, `${s.lifts} lifts this stroke · let go when it looks right`);
    this.markSel(w, s.sel);
    return true;
  }

  /** The button is up: the stroke is one thing now, for undo, the deeds, the save and the world. */
  private finish(): void {
    const s = this.stroke;
    this.stroke = null;
    this.acc = 0;
    const w = this.w;
    if (!s || !w || !s.tiles.size) return;
    this.flush();
    const tiles = [...s.tiles];
    const more = [...s.more].map(([n, m]) => ({ w: n, undo: m.undo, tiles: [...m.tiles] }));
    this.history.push({ w, undo: s.undo, tiles, cost: s.cost, lifts: s.lifts, more });
    for (const m of more) this.settle(m.w, m.tiles);
    if (this.history.length > LAND.undo) this.history.shift();
    this.strokes++;
    this.lifts += s.lifts;
    this.spent += s.cost;
    if (s.lifts) deeds.add('lifts', s.lifts);
    if (s.cost) deeds.add('landSpend', s.cost);
    if (s.reclaimed) deeds.add('reclaimed', s.reclaimed);
    if (s.opened) deeds.add('navvy', s.opened);
    if (s.lakes) deeds.add('lakes', s.lakes);
    if (s.summit > -Infinity) {
      // the highest ground the player raised: a corner that went up and stands where it stopped
      let top = -Infinity;
      for (const [k, was] of s.undo.corners) if (w.corners[k] > was) top = Math.max(top, w.corners[k]);
      if (top > -Infinity) deeds.best('summit', top);
    }
    this.settle(w, tiles);
    this.hoverKey = '';
  }

  private undo(): void {
    const last = this.history.pop();
    // a stroke is taken back in the county it was made in, wherever the brush is now
    if (last && last.w !== this.w) this.retarget(last.w);
    const w = this.w;
    if (!w || !last) { if (w) this.hud.float('Nothing to undo', this.focus, 'info'); return; }
    const tiles = revert(w, last.undo);
    // and what it was carried into over a county line
    for (const m of last.more) { const back = revert(m.w, m.undo); this.onGround?.(m.w, ring(back)); this.settle(m.w, back); }
    if (!this.free) this.wallet.earn(last.cost, 'refunds');
    this.strokes = Math.max(0, this.strokes - 1);
    this.lifts = Math.max(0, this.lifts - last.lifts);
    this.spent = Math.max(0, this.spent - last.cost);
    this.hud.float(`+${money(last.cost)} · undone`, this.focus, 'cash');
    for (const t of tiles) this.pending.add(t);
    this.flush();
    this.settle(w, tiles);
    this.hoverKey = '';
  }

  /** After a stroke or an undo: the world looks again, and the save learns the new ground. */
  private settle(w: World, tiles: number[]): void {
    w.revision++;
    this.onStroke?.(w, ring(tiles));
    const land = encodeLand(w);
    this.savedKB = sizeKB(land);
    this.onLand?.(w, land);
    this.paint();
  }

  /** Redraw what the drag moved this frame, with a ring round it: a lowered tile's neighbour draws the new cliff. */
  private flush(): void {
    if (!this.pending.size || !this.w) return;
    this.onGround?.(this.w, ring([...this.pending]));
    this.pending.clear();
  }

  // ---------------------------------------------------------------------------------------------
  // drawing

  private markSel(w: World, sel: Selection): void {
    this.clearMarks();
    const ok = this.mode === 'land' ? 0xffffff : 0x7fc8f0;
    if (sel.corner !== undefined) {
      const i = sel.tiles[0];
      const x = i % N, z = (i - x) / N, q = sel.corner;
      const vx = x + (q === 1 || q === 2 ? 1 : 0), vz = z + (q === 2 || q === 3 ? 1 : 0);
      const o = buildOutline(w, x, z, x + 1, z + 1, 0x8a93a6);
      if (o) this.addMark(o);
      const grip = new THREE.Mesh(new THREE.SphereGeometry(0.16, 12, 8), new THREE.MeshBasicMaterial({ color: ok, depthTest: false }));
      grip.renderOrder = 10;
      grip.position.set(vx, w.corners[i * 4 + q] * STEP + 0.08, vz);
      this.addMark(grip);
      return;
    }
    let x0 = N, z0 = N, x1 = 0, z1 = 0;
    for (const t of sel.tiles) {
      const tx = t % N, tz = (t - tx) / N;
      x0 = Math.min(x0, tx); z0 = Math.min(z0, tz); x1 = Math.max(x1, tx + 1); z1 = Math.max(z1, tz + 1);
    }
    const o = buildOutline(w, x0, z0, x1, z1, ok);
    if (o) this.addMark(o);
    // tiles that sit the step out, in red
    for (const t of sel.tiles) {
      if (!this.blocked.has(t) && landProblem(w, t, this.mode === 'land' ? this.style : 'cliff', this.towns) === null) continue;
      const tx = t % N, tz = (t - tx) / N;
      const r = buildOutline(w, tx, tz, tx + 1, tz + 1, 0xd2564f);
      if (r) this.addMark(r);
    }
  }

  /** Red bars along the edges where water would stand against nothing. */
  private showLeaks(w: World, p: Plan): void {
    this.clearLeaks();
    const mat = new THREE.MeshBasicMaterial({ color: 0xff4a3d, depthTest: false, transparent: true, opacity: 0.9 });
    for (const e of p.leaks.slice(0, 64)) {
      const i = e >> 2, d = e & 3;
      const x = i % N, z = (i - x) / N;
      const L = p.water.get(i) ?? w.water[i];
      const m = EDGE_MINE[d];
      const cx = x + 0.5 + DIRS[d][0] * 0.5, cz = z + 0.5 + DIRS[d][1] * 0.5;
      const along = DIRS[d][0] !== 0;
      const bar = new THREE.Mesh(new THREE.BoxGeometry(along ? 0.1 : 1, 0.1, along ? 1 : 0.1), mat);
      bar.renderOrder = 11;
      const y = Math.max(L * STEP, Math.max(w.corners[i * 4 + m[0]], w.corners[i * 4 + m[1]]) * STEP) + 0.05;
      bar.position.set(cx, y, cz);
      this.layer.add(bar);
      this.leakMarks.push(bar);
    }
  }

  private addMark(o: THREE.Object3D): void { this.layer.add(o); this.marks.push(o); }

  private clearMarks(): void {
    for (const m of this.marks) { this.layer.remove(m); disposeObject(m); }
    this.marks = [];
  }

  private clearLeaks(): void {
    for (const m of this.leakMarks) { this.layer.remove(m); disposeObject(m); }
    this.leakMarks = [];
  }

  private paint(): void {
    const on = (b: boolean) => (b ? ' class="on"' : '');
    const styleDisabled = this.mode === 'water' ? ' disabled' : '';
    this.modeEl.innerHTML =
      `<div class="seg"><button type="button" data-mode="land"${on(this.mode === 'land')}>⛰️ Land</button><button type="button" data-mode="water"${on(this.mode === 'water')}>💧 Water</button><kbd>V</kbd></div>`
      + `<div class="seg"${this.mode === 'water' ? ' style="opacity:.45"' : ''}><button type="button" data-style="cliff"${on(this.style === 'cliff')}${styleDisabled}>🧱 Cliff</button><button type="button" data-style="smooth"${on(this.style === 'smooth')}${styleDisabled}>⛰ Smooth</button><kbd>F</kbd></div>`
      + `<div class="seg">Brush ${[1, 2, 3, 4, 5, 6, 7].map((k) => `<button type="button" data-brush="${k}"${on(this.brush === k)}>${k}</button>`).join('')}</div>`;
    const kb = this.savedKB;
    const meter = kb ? ` · <span${kb > SAVE_WARN_KB ? ' class="warn"' : ''}>${kb.toFixed(1)} KB saved here</span>` : '';
    this.countEl.innerHTML = (this.strokes
      ? `${this.strokes} stroke${this.strokes === 1 ? '' : 's'} · ${this.lifts.toLocaleString('en-US')} lifts · ${money(this.spent)} spent`
      : 'Nothing moved yet') + meter;
  }

  private setTip(kind: 'ok' | 'bad' | 'none', title: string, body: string): void {
    this.tip.className = `hud chip ${kind}`;
    this.tipTitle.textContent = title;
    this.tipBody.textContent = body;
    this.tip.hidden = false;
  }

  private placeTip(mx: number, my: number): void {
    const r = this.tip.getBoundingClientRect();
    let x = mx + 18, y = my + 18;
    if (x + r.width > window.innerWidth - 8) x = mx - 18 - r.width;
    if (y + r.height > window.innerHeight - 8) y = my - 18 - r.height;
    this.tip.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px)`;
  }
}

/** Tiles and the ring round them. */
export function ring(tiles: number[]): number[] {
  const out = new Set<number>();
  for (const t of tiles) {
    const x = t % N, z = (t - x) / N;
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (inB(x + dx, z + dz)) out.add(idx(x + dx, z + dz));
  }
  return [...out];
}

function sizeKB(land: LandBlock | undefined): number {
  if (!land) return 0;
  let n = 0;
  for (const k of Object.keys(land)) n += land[Number(k)].length + k.length + 4;
  return n / 1024;
}
