import { hex, mix, scale, type RGB } from '../../world/biomes';
import { resortPlan } from '../../world/beachResorts';
import { FLOOR } from '../../world/towns';
import type { PlayKind } from '../../world/playKinds';
import { Vis } from '../nightLights';
import { DARK, GLASS, GLASS_LIGHT, METAL, SHOP_GLOW, WARM_GLOW, WHITE, WOOD, type Draw, type Kit } from './kit';

/**
 * A private beach resort (world/beachResorts.ts resortPlan): guest wings on an arc round the pool deck, balconies
 * on every floor looking down to the sea; the lagoon pool with its swim-up bar, the infinity pool along the deck's
 * front, hot tubs and cabanas; restaurants and bars under deep roofs at the water's edge, a beach bar and a
 * water-sports hut on the sand, loungers and umbrellas down the beach, a jetty with a boat; behind it all the lobby
 * under its porte-cochère at the end of a palm-lined drive, the grounds walled. Guests on the loungers and in the
 * water in summer; the pools are lit and the bars glow after dark. Pools drained in winter, as the lido's are.
 */

const SAND = hex(0xefe2a9), DECK = hex(0xe9e1d0), LAWN = hex(0x7cc35e), DRIVE = hex(0x9c958a);
const COPING = hex(0xf2ede2), POOL = hex(0x4fc3e0), TUB = hex(0x8fe0ee), DRAINED = hex(0xb9c4c6);
const THATCH = hex(0xb08a52), TRUNK = hex(0x9a7a52), FROND = hex(0x4f9a3e), FROND_B = hex(0x5fae48);
const SKIN = [0xf1c9a5, 0xd9a982, 0xa8714a, 0x7a4e2e].map(hex);
/** Three looks a resort is built in: Mediterranean white and terracotta, Caribbean pastels, modern white and glass. */
const LOOKS: { wall: number[]; roof: number; trim: number; brolly: number[] }[] = [
  { wall: [0xf6f2ea, 0xf2ebdd], roof: 0xc4643f, trim: 0x2f6f9c, brolly: [0xf4f2ec, 0x2f6f9c] },
  { wall: [0xf6c9b4, 0xbfe3d6, 0xf7e2a6, 0xc9d8f2], roof: 0x5aa0a8, trim: 0xf4f2ec, brolly: [0xe2412f, 0xf2c14e, 0x2bb3a3] },
  { wall: [0xf4f2ec, 0xe6e8e8], roof: 0x8c8a84, trim: 0x3a3f45, brolly: [0xf4f2ec, 0x3a3f45] },
];
/** The pools lit from dusk; the bars and restaurants till late. */
const POOL_HOURS: [number, number, number] = [18.5, 29.5, 1], BAR_HOURS: [number, number, number] = [17.5, 25.5, 1];
const POOL_GLOW = hex(0x7fe8ff);

/** A flat rectangle facing up. */
function flat(k: Kit, x: number, z: number, w: number, d: number, y: number, col: RGB): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2;
  k.quad([x0, y, z0], [x1, y, z0], [x1, y, z1], [x0, y, z1], col, [x, y - 1, z]);
}

/** A palm: a leaning trunk in two bends and a crown of fronds drooping out all round. */
function palm(k: Kit, x: number, z: number, h: number, lean: number): void {
  const mx = x + lean * 0.06, mz = z + lean * 0.03, tx = x + lean * 0.14, tz = z + lean * 0.07;
  k.bar([x, 0, z], [mx, h * 0.55, mz], 0.035, TRUNK);
  k.bar([mx, h * 0.55, mz], [tx, h, tz], 0.03, TRUNK);
  for (let f = 0; f < 6; f++) {
    const a = (f / 6) * Math.PI * 2 + lean;
    k.bar([tx, h, tz], [tx + Math.cos(a) * 0.32, h - 0.12, tz + Math.sin(a) * 0.32], 0.028, f % 2 ? FROND : FROND_B);
  }
}

/** A lounger, with a guest on it in summer, and an umbrella over it if it has one. */
function lounger(k: Kit, x: number, z: number, brolly: RGB | null, guest: RGB | null): void {
  k.box(x, 0, z, 0.1, 0.035, 0.24, WHITE);
  k.box(x, 0.035, z - 0.09, 0.1, 0.05, 0.05, WHITE);
  if (guest) k.tagged(Vis.Summer, () => k.box(x, 0.036, z + 0.01, 0.055, 0.03, 0.17, guest));
  if (brolly) {
    k.bar([x + 0.08, 0, z - 0.02], [x + 0.08, 0.34, z - 0.02], 0.008, WHITE);
    k.cone(x + 0.08, 0.28, z - 0.02, 0.2, 0.08, brolly, 8);
  }
}

const draw: Draw = (k, W, D, b, r) => {
  const p = resortPlan(b.seed, W, D);
  const look = LOOKS[Math.floor(r() * LOOKS.length)];
  const roof = hex(look.roof), trim = hex(look.trim);
  const walls = look.wall.map(hex);
  // the grounds: lawn, the paved deck, the sand, the drive in; a wall round the sides and back
  flat(k, 0, (-D / 2 + p.beach.z0) / 2, W - 0.1, p.beach.z0 + D / 2 - 0.05, 0.006, LAWN);
  flat(k, (p.deck.x0 + p.deck.x1) / 2, (p.deck.z0 + p.deck.z1) / 2, p.deck.x1 - p.deck.x0, p.deck.z1 - p.deck.z0, 0.012, DECK);
  flat(k, 0, (p.beach.z0 + p.beach.z1) / 2, W - 0.05, p.beach.z1 - p.beach.z0, 0.008, SAND);
  flat(k, 0, (p.drive.z0 + p.drive.z1) / 2, p.drive.half * 2, p.drive.z1 - p.drive.z0, 0.012, DRIVE);
  for (const s of [-1, 1]) {
    k.box(s * (W / 2 - 0.04), 0, (-D / 2 + p.beach.z0) / 2, 0.07, 0.2, p.beach.z0 + D / 2, walls[0], roof);
    k.box(s * (W / 4 + p.drive.half / 2), 0, -D / 2 + 0.04, W / 2 - p.drive.half, 0.2, 0.07, walls[0], roof);
    // the gate piers either side of the drive
    k.box(s * (p.drive.half + 0.08), 0, -D / 2 + 0.06, 0.14, 0.32, 0.14, walls[0], roof);
  }
  // the buildings
  for (const blk of p.blocks) {
    const wall = blk.kind === 'wing' || blk.kind === 'lobby' ? walls[Math.floor(r() * walls.length)] : WOOD;
    k.turned(blk.yaw, () => {
      const c = Math.cos(blk.yaw), s = Math.sin(blk.yaw);
      // where the plan's centre lies in the turned frame
      const x = blk.x * c - blk.z * s, z = blk.x * s + blk.z * c;
      const { w, d, h } = blk;
      if (blk.kind === 'wing') {
        k.box(x, 0, z, w, h, d, wall, scale(wall, 0.9));
        k.box(x, h, z, w + 0.05, 0.05, d + 0.05, roof);
        // guest rooms on every floor, front and back: each room's window, and its balcony with a glass rail
        // (the front looks over the pools to the sea, the back over the gardens), lit in the evening
        const floors = Math.max(2, Math.floor(h / FLOOR)), fh = (h - 0.1) / floors;
        const rooms = Math.max(3, Math.round((w - 0.2) / 0.36)), rw = (w - 0.2) / rooms;
        for (let f = 0; f < floors; f++) {
          const y = 0.08 + f * fh;
          for (const side of [1, -1]) {
            const fz = z + side * (d / 2);
            k.box(x, y, fz + side * 0.06, w - 0.12, 0.025, 0.12, scale(wall, 0.95));
            k.box(x, y + 0.025, fz + side * 0.115, w - 0.12, 0.05, 0.01, GLASS_LIGHT);
            for (let m = 0; m < rooms; m++) {
              const rx = x - (w - 0.2) / 2 + (m + 0.5) * rw;
              k.glowBox(rx, y + 0.04, fz + side * 0.002, rw * 0.62, fh * 0.6, 0.02, GLASS, [18, 23.5, 0.7], WARM_GLOW);
              // the dividers between the balconies
              if (m) k.box(x - (w - 0.2) / 2 + m * rw, y, fz + side * 0.06, 0.015, fh * 0.75, 0.12, scale(wall, 0.92));
            }
          }
          // the stair windows at each end
          for (const ex of [-1, 1]) k.glowBox(x + ex * (w / 2 + 0.002), y + 0.04, z, 0.02, fh * 0.55, d * 0.3, GLASS, [18, 23.5, 0.7], WARM_GLOW);
        }
      } else if (blk.kind === 'lobby') {
        k.box(x, 0, z, w, h, d, wall, scale(wall, 0.9));
        k.hip(x, h, z, w + 0.2, 0.42, d + 0.2, roof);
        // a two-storey glass atrium onto the deck, and the porte-cochère out the back over the drive
        k.glowBox(x, 0.02, z + d / 2 + 0.002, w * 0.5, h * 0.7, 0.02, GLASS, [16.5, 30, 1], SHOP_GLOW);
        k.box(x, 0.44, z - d / 2 - 0.45, 1.4, 0.06, 0.9, roof, roof);
        for (const sx of [-0.6, 0.6]) k.box(x + sx, 0, z - d / 2 - 0.82, 0.07, 0.44, 0.07, WHITE);
        k.box(x, 0.32, z - d / 2 - 0.01, 0.5, 0.1, 0.02, trim);
        // a row of windows along the upper floor front and back, either side of the atrium
        for (const side of [1, -1]) for (const sx of [-1, 1]) {
          k.glowBox(x + sx * w * 0.36, h * 0.55, z + side * (d / 2 + 0.002), w * 0.2, h * 0.25, 0.02, GLASS, [17, 23.5, 0.8], WARM_GLOW);
        }
      } else {
        // a restaurant or bar at the water's edge: an open pavilion under a deep thatched hip, its deck out front
        k.box(x, 0, z, w + 0.2, 0.06, d + 0.2, WOOD);
        for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * (w / 2 - 0.06), 0.06, z + sz * (d / 2 - 0.06), 0.06, h - 0.06, 0.06, WOOD);
        k.hip(x, h, z, w + 0.3, blk.kind === 'hut' ? 0.22 : 0.36, d + 0.3, blk.kind === 'hut' ? roof : THATCH);
        k.box(x, 0.06, z - d / 2 + 0.2, w - 0.3, 0.2, 0.18, DARK);
        k.glowBox(x, 0.27, z - d / 2 + 0.2, w - 0.4, 0.04, 0.12, WOOD, BAR_HOURS, WARM_GLOW);
        if (blk.kind === 'hut') {
          // kayaks racked by the water-sports hut
          for (let i = 0; i < 3; i++) k.box(x + w / 2 + 0.12, 0.05 + i * 0.07, z, 0.06, 0.04, 0.5, [hex(0xf2c14e), hex(0xe2412f), hex(0x2bb3a3)][i]);
        } else {
          for (let t = 0; t < 4; t++) {
            const tx = x - w / 2 + 0.35 + t * (w - 0.7) / 3, tz = z + 0.15;
            k.cyl(tx, 0.06, tz, 0.08, 0.12, WHITE, 8);
          }
        }
      }
    });
  }
  // the pools: a lagoon of ovals round its swim-up bar, the infinity pool along the deck's front, hot tubs
  const y0 = 0.012;
  for (const [x, z, rx, rz] of p.lagoon) k.cyl(x, y0, z, rx + 0.1, 0.035, COPING, 18, COPING, rz + 0.1);
  k.tagged(Vis.NotWinter, () => { for (const [x, z, rx, rz] of p.lagoon) k.cyl(x, y0, z, rx, 0.05, POOL, 18, POOL, rz); });
  k.tagged(Vis.Winter, () => { for (const [x, z, rx, rz] of p.lagoon) k.cyl(x, y0, z, rx, 0.04, DRAINED, 18, DRAINED, rz); });
  for (const [x, z] of p.lagoon.slice(0, 2)) k.glowBox(x, y0 + 0.02, z, 0.08, 0.03, 0.08, POOL, POOL_HOURS, POOL_GLOW);
  k.cyl(p.swimBar.x, y0, p.swimBar.z, p.swimBar.r, 0.16, WOOD, 10, THATCH);
  k.cone(p.swimBar.x, 0.38, p.swimBar.z, p.swimBar.r + 0.14, 0.16, THATCH, 10);
  k.bar([p.swimBar.x, 0.16, p.swimBar.z], [p.swimBar.x, 0.4, p.swimBar.z], 0.02, WOOD);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2;
    k.cyl(p.swimBar.x + Math.cos(a) * (p.swimBar.r + 0.12), y0, p.swimBar.z + Math.sin(a) * (p.swimBar.r + 0.12), 0.035, 0.09, WHITE, 6);
  }
  const inf = p.infinity;
  k.box(inf.x, y0, inf.z, inf.w + 0.12, 0.03, inf.d + 0.12, COPING);
  k.tagged(Vis.NotWinter, () => k.glowBox(inf.x, y0 + 0.03, inf.z, inf.w, 0.025, inf.d, POOL, POOL_HOURS, POOL_GLOW));
  // its seaward edge: the overflow, a dark glass lip down to the catch channel
  k.box(inf.x, y0, inf.z + inf.d / 2 + 0.07, inf.w + 0.12, 0.05, 0.03, mix(POOL, DARK, 0.5));
  for (const t of p.tubs) {
    k.cyl(t.x, y0, t.z, t.r + 0.05, 0.06, COPING, 12);
    k.tagged(Vis.NotWinter, () => k.glowBox(t.x, y0 + 0.06, t.z, t.r * 1.3, 0.012, t.r * 1.3, TUB, POOL_HOURS, POOL_GLOW));
  }
  // cabanas: four posts, a white roof and a drape
  for (const [x, z] of p.cabanas) {
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * 0.17, y0, z + sz * 0.17, 0.025, 0.3, 0.025, WHITE);
    k.box(x, 0.3, z, 0.4, 0.04, 0.4, WHITE);
    k.box(x - 0.18, 0.06, z, 0.01, 0.24, 0.36, scale(trim, 1.1));
  }
  // loungers on the deck and down the beach, an umbrella over every other one; guests on half of them in summer
  const brollies = look.brolly.map(hex);
  p.loungers.forEach((l, i) => lounger(k, l.x, l.z, i % 2 ? brollies[i % brollies.length] : null, r() < 0.5 ? SKIN[Math.floor(r() * SKIN.length)] : null));
  // bathers' heads in the lagoon in summer
  k.tagged(Vis.Summer, () => {
    for (const [x, z, rx, rz] of p.lagoon) for (let i = 0; i < 2; i++) {
      const a = r() * Math.PI * 2, f = 0.3 + r() * 0.5;
      k.dome(x + Math.cos(a) * rx * f, y0 + 0.05, z + Math.sin(a) * rz * f, 0.035, SKIN[Math.floor(r() * SKIN.length)], 6, 2);
    }
  });
  for (const [x, z] of p.palms) palm(k, x, z, 0.75 + r() * 0.3, r() * 2 - 1);
  // the jetty out over the water, a boat tied up at its end
  const j = p.jetty;
  k.box(j.x, 0.02, D / 2 + j.len / 2, 0.32, 0.04, j.len, WOOD);
  for (let s = 0.4; s <= j.len; s += 0.6) for (const sx of [-0.14, 0.14]) k.box(j.x + sx, -0.3, D / 2 + s, 0.04, 0.32, 0.04, scale(WOOD, 0.7));
  k.box(j.x + 0.38, -0.02, D / 2 + j.len - 0.3, 0.26, 0.08, 0.7, WHITE);
  k.box(j.x + 0.38, 0.06, D / 2 + j.len - 0.4, 0.18, 0.08, 0.22, METAL);
};

/** The resort's model, by kind (render/buildings/play.ts gathers it with the places to play). */
export const RESORT_DRAW: Partial<Record<PlayKind, Draw>> = { beachResort: draw };
