import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { BRIGHT, DARK, WARM_GLOW, WHITE, flared, type Draw, type Kit, type P3 } from '../kit';

/**
 * The Mangroves: a village on stilts over the swamp, the shrimp ponds with their paddle wheels, and
 * the floating market, a crowd of loaded boats round its roofed pontoons. Murky green water, grey
 * piles, tin roofs, tarpaulin blue and every colour of fruit.
 */

const MURK = hex(0x5f7d5e), MURK_DEEP = hex(0x4f6c54), POND = hex(0x5a6a3a), MUD = hex(0x8a7556);
const PILE = hex(0x77736a), PLANK = hex(0xa98a62), PLANK_DARK = hex(0x86694a), TIN = hex(0xaab1b3), TIN_RUST = hex(0x9a6044);
const TARP = hex(0x2f7fc4), MANGROVE = hex(0x3f7a45), MANGROVE2 = hex(0x558f4a), ROOT = hex(0x6a5a48), STRAW = hex(0xe3cf95);
const LACQUER = hex(0xb8332a), GOLD = hex(0xe0b040);
const PRODUCE = [0x4fae3c, 0xf08a24, 0xd8342a, 0xf2cf3a, 0x8fce4a, 0xe85a8a, 0x7a3fa0, 0xf4f0e0].map(hex);
const HULLS = [0x8a5a3a, 0x2f7f9a, 0xc23b32, 0x3f8f5a, 0xd9a83a, 0x6a4a36, 0x2f5d8a].map(hex);
const TINS = [TIN, TIN_RUST, TARP, hex(0x7f8a8c), hex(0x4f8f7a)];
const EVENING: Sched = [18, 23.5, 1.4], LANTERN: Sched = [17.5, 29, 2];

/** Draw parts about the lot point (x, z), turned by `yaw`: `draw` is handed that point in the turned frame. */
function placed(k: Kit, x: number, z: number, yaw: number, draw: (x: number, z: number) => void): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  k.turned(yaw, () => draw(x * c - z * s, x * s + z * c));
}

/** A mangrove: a round crown held over the water on a splay of arched prop roots. */
function mangrove(k: Kit, x: number, z: number, s: number): void {
  const top = 0.3 * s;
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 + 0.3, c = Math.cos(a), sn = Math.sin(a);
    k.bar([x + c * 0.03 * s, top + 0.03 * s, z + sn * 0.03 * s], [x + c * 0.24 * s, 0.01, z + sn * 0.24 * s], 0.014 * s, ROOT);
  }
  k.dome(x, top, z, 0.25 * s, MANGROVE, 7, 2);
  k.dome(x + 0.14 * s, top - 0.01 * s, z + 0.1 * s, 0.15 * s, MANGROVE2, 6, 2);
}

/**
 * A long narrow boat along x, pointed and upswept at both ends. `load` piles it with produce; `hat`
 * seats a figure under a conical hat at the stern, or under a parasol of that colour.
 */
function boat(k: Kit, r: () => number, x: number, z: number, L: number, hull: RGB, load: boolean, shade: RGB | null): void {
  const w = L * 0.11, h = 0.07, y = 0.02, m = L * 0.27, e = L / 2, up = 0.05;
  const I: P3 = [x, y + 0.03, z], inner = scale(hull, 0.7);
  for (const s of [-1, 1]) {
    // the side, the tapering bow and stern, and the floor seen from above
    k.quad([x - m, y, z + s * w * 0.8], [x + m, y, z + s * w * 0.8], [x + m, y + h, z + s * w], [x - m, y + h, z + s * w], hull, I);
    for (const d of [-1, 1]) {
      k.quad([x + d * m, y, z + s * w * 0.8], [x + d * e, y + up, z], [x + d * e, y + h + up, z], [x + d * m, y + h, z + s * w], hull, I);
      k.tri([x + d * m, y + h * 0.5, z + s * w], [x + d * m, y + h * 0.5, z], [x + d * e, y + h + up - 0.01, z], inner, [x, y + 0.5, z]);
    }
  }
  k.quad([x - m, y + h * 0.5, z - w * 0.9], [x + m, y + h * 0.5, z - w * 0.9], [x + m, y + h * 0.5, z + w * 0.9], [x - m, y + h * 0.5, z + w * 0.9], inner, [x, y - 1, z]);
  if (load) {
    const n = 2 + Math.floor(r() * 2);
    for (let i = 0; i < n; i++) {
      const px = x - m * 0.35 + (i * m * 1.2) / n, col = PRODUCE[Math.floor(r() * PRODUCE.length)];
      if (r() < 0.75) k.hip(px, y + h * 0.5, z, m * 0.55, 0.08 + r() * 0.04, w * 1.7, col);
      else k.box(px, y + h * 0.5, z, m * 0.45, 0.06, w * 1.6, col, scale(col, 1.12));
    }
  }
  // the boatman at the stern
  const sx = x - m * 0.78;
  if (shade) {
    k.box(sx + 0.05, y + h * 0.5, z, 0.014, 0.24, 0.014, DARK);
    k.cone(sx + 0.05, y + 0.24, z, 0.16, 0.06, shade, 6);
  } else {
    k.hip(sx, y + h * 0.5, z, 0.055, 0.1, 0.055, hex(0x4a5a7a));
    k.cone(sx, y + h * 0.5 + 0.075, z, 0.07, 0.045, STRAW, 6);
  }
}

/** A little house on piles: a plank deck, a box of timber and a tin roof, with a lit window. */
function stiltHouse(k: Kit, r: () => number, x: number, z: number, w: number, d: number, deckY: number, wall: RGB, roof: RGB, alongZ: boolean): number {
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * (w / 2 + 0.02), 0, z + sz * (d / 2 + 0.02), 0.035, deckY, 0.035, PILE);
  k.box(x, deckY, z, w + 0.16, 0.03, d + 0.16, PLANK);
  const h = 0.24 + r() * 0.08, y = deckY + 0.03;
  k.box(x, y, z, w, h, d, wall);
  k.gable(x, y + h, z, w + 0.1, 0.13 + r() * 0.04, d + 0.1, roof, scale(wall, 0.9), alongZ);
  k.box(x + w * 0.2, y, z + d / 2 + 0.006, 0.08, 0.17, 0.01, PLANK_DARK);
  k.pane(x - w * 0.2, y + 0.09, z + d / 2, 0.1, 0.09, 1, DARK, EVENING, WARM_GLOW);
  k.pane(x + w / 2, y + 0.09, z, 0.1, 0.09, 0, DARK, EVENING, WARM_GLOW);
  return y + h;
}

// ---- the stilt village (3 × 3) ---------------------------------------------------------------------------

/**
 * A village on stilts: five small timber and tin houses on tall piles over the swamp, joined by plank
 * walkways, boats tied below, mangroves at the corners and lanterns along the walk.
 */
const stiltVillage: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2, deck = 0.34;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, MURK);
  k.box(0.3, 0.02, 0.5, W * 0.5, 0.004, D * 0.3, MURK_DEEP);
  const walls = [PLANK, PLANK_DARK, hex(0xb9a27c), hex(0x7f9a9a), hex(0xc2b08a)];
  const wall = () => walls[Math.floor(r() * walls.length)], roof = () => TINS[Math.floor(r() * TINS.length)];
  // the back row of three, and two nearer the front
  const spine = -0.32;
  for (const x of [-0.95, 0, 0.95]) stiltHouse(k, r, x, -hd + 0.5, 0.5, 0.42, deck + (x === 0 ? 0.06 : 0), wall(), roof(), r() < 0.5);
  for (const x of [-0.95, 0.95]) stiltHouse(k, r, x, 0.42, 0.46, 0.44, deck, wall(), roof(), r() < 0.5);
  // the walkways: a spine across, spurs to each door, and a jetty out to the front
  k.box(0, deck, spine, W - 0.7, 0.025, 0.15, PLANK_DARK, PLANK);
  for (let i = 0; i < 6; i++) for (const s of [-1, 1]) k.box(-hw + 0.45 + i * ((W - 0.9) / 5), 0, spine + s * 0.07, 0.025, deck, 0.025, PILE);
  for (const x of [-0.95, 0, 0.95]) k.box(x + 0.1, deck + 0.004, (spine + (-hd + 0.79)) / 2, 0.12, 0.025, spine - (-hd + 0.79) + 0.1, PLANK);
  for (const x of [-0.95, 0.95]) k.box(x - 0.25 * Math.sign(x), deck + 0.004, (spine + 0.2) / 2 + 0.05, 0.12, 0.025, 0.2 - spine, PLANK);
  k.box(0, deck + 0.004, (spine + hd - 0.2) / 2, 0.16, 0.025, hd - 0.2 - spine, PLANK);
  for (let i = 0; i < 4; i++) for (const s of [-1, 1]) k.box(s * 0.07, 0, spine + 0.3 + i * 0.4, 0.025, deck, 0.025, PILE);
  // lanterns on posts along the walk
  for (const [lx, lz] of [[-0.5, spine - 0.07], [0.5, spine - 0.07], [0.09, 0.5], [0.09, hd - 0.25]] as const) {
    k.box(lx, deck, lz, 0.015, 0.2, 0.015, DARK);
    k.glowBox(lx, deck + 0.2, lz, 0.04, 0.05, 0.04, hex(0xf2c14e), LANTERN, WARM_GLOW);
  }
  // washing on a line, boats tied below, mangroves
  k.bar([-0.7, deck + 0.22, 0.75], [-0.25, deck + 0.22, 0.75], 0.006, DARK);
  k.box(-0.7, deck, 0.75, 0.015, 0.24, 0.015, PILE);
  for (let i = 0; i < 3; i++) k.box(-0.6 + i * 0.12, deck + 0.13, 0.75, 0.07, 0.09, 0.008, [WHITE, TARP, hex(0xd8342a)][i]);
  placed(k, 0.45, 0.95, 0.35, (x, z) => boat(k, r, x, z, 0.6, HULLS[1], false, null));
  placed(k, -0.4, 0.1, -0.2, (x, z) => boat(k, r, x, z, 0.55, HULLS[2], true, null));
  placed(k, 0.5, -0.75, 1.4, (x, z) => boat(k, r, x, z, 0.5, HULLS[0], false, null));
  mangrove(k, -hw + 0.4, hd - 0.4, 1);
  mangrove(k, hw - 0.4, hd - 0.38, 0.85);
  mangrove(k, hw - 0.38, -0.3, 0.7);
};

// ---- the shrimp farm (3 × 3) ------------------------------------------------------------------------------

/**
 * Shrimp ponds: four murky ponds between earth bunds, a paddle-wheel aerator churning in each, a
 * sluice at the front, a tin sorting shed with its crates and a pickup.
 */
const shrimpFarm: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, MUD);
  const x0 = -hw + 0.2, x1 = hw - 1.0, z0 = -hd + 0.2, z1 = hd - 0.75;
  const pw = (x1 - x0) / 2, pd = (z1 - z0) / 2;
  for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) {
    const px = x0 + (i + 0.5) * pw, pz = z0 + (j + 0.5) * pd;
    k.box(px, 0.02, pz, pw - 0.1, 0.02, pd - 0.1, scale(POND, 0.92 + ((i + j * 2) % 3) * 0.07));
    // the aerator: two floats, an axle, and the paddles turning on it
    const ax = px + (i ? -0.12 : 0.12), az = pz + (j ? 0.1 : -0.1);
    for (const s of [-1, 1]) k.box(ax + s * 0.13, 0.04, az, 0.06, 0.035, 0.2, hex(0xe8e2cf));
    k.bar([ax - 0.13, 0.1, az], [ax + 0.13, 0.1, az], 0.01, DARK);
    k.spin(ax, 0.1, az, 'x', 5 + r() * 2, (s) => {
      for (const px2 of [-0.05, 0.05]) {
        s.box(px2, -0.07, 0, 0.07, 0.14, 0.015, TARP);
        s.box(px2, -0.0075, 0, 0.07, 0.015, 0.14, TARP);
      }
    });
    k.disc(ax, 0.041, az + 0.18, 0.1, hex(0xa9b89a), 7, 0.07);
  }
  for (let i = 0; i <= 2; i++) k.box(x0 + i * pw, 0.02, (z0 + z1) / 2, 0.12, 0.07, z1 - z0 + 0.12, MUD, scale(MUD, 1.12));
  for (let j = 0; j <= 2; j++) k.box((x0 + x1) / 2, 0.02, z0 + j * pd, x1 - x0, 0.065, 0.12, MUD, scale(MUD, 1.12));
  // the sluice gate in the front bund, and its drain
  const gx = x0 + pw * 0.5;
  for (const s of [-1, 1]) k.box(gx + s * 0.11, 0.02, z1, 0.035, 0.3, 0.05, hex(0xb9b3a8));
  k.box(gx, 0.29, z1, 0.29, 0.035, 0.06, hex(0xb9b3a8));
  k.box(gx, 0.09, z1, 0.18, 0.14, 0.02, hex(0x3f6a8a));
  k.hoop(gx, 0.37, z1 + 0.035, 0.045, 0.01, DARK, 8);
  k.box(gx, 0.02, z1 + 0.25, 0.16, 0.012, 0.4, MURK);
  // the sorting shed down the right side: tin walls, open front, crates at the door
  const sx = hw - 0.5, sz = -hd + 0.85;
  k.box(sx, 0.02, sz, 0.62, 0.34, 1.1, TIN);
  k.gable(sx, 0.36, sz, 0.7, 0.16, 1.18, TIN_RUST, TIN, true);
  k.box(sx, 0.02, sz + 0.556, 0.34, 0.25, 0.01, DARK);
  k.pane(sx - 0.31, 0.16, sz - 0.2, 0.2, 0.1, 2, DARK, EVENING, WARM_GLOW);
  k.glowBox(sx, 0.4, sz + 0.57, 0.05, 0.04, 0.03, hex(0xf2c14e), LANTERN, WARM_GLOW);
  for (let i = 0; i < 5; i++) {
    const cx = sx - 0.2 + (i % 3) * 0.17, cy = 0.02 + (i > 2 ? 0.08 : 0), cz = sz + 0.72 + (i > 2 ? 0.01 : 0);
    k.box(cx + (i > 2 ? 0.08 : 0), cy, cz, 0.14, 0.08, 0.12, i % 2 ? TARP : hex(0xd9d4c4), hex(0xe6a08a));
  }
  // the pickup, nose to the road
  const px = hw - 0.5, pz = hd - 0.55;
  const paint = hex(BRIGHT[Math.floor(r() * BRIGHT.length)]);
  k.box(px, 0.05, pz, 0.22, 0.09, 0.46, paint);
  k.box(px, 0.14, pz + 0.06, 0.2, 0.09, 0.15, hex(0x9cc6d9), paint);
  k.box(px, 0.14, pz - 0.13, 0.2, 0.04, 0.18, scale(paint, 0.8), DARK);
  for (const s of [-1, 1]) for (const dz of [-0.14, 0.15]) k.box(px + s * 0.11, 0.01, pz + dz, 0.04, 0.08, 0.1, DARK);
  // net poles along the back
  for (let i = 0; i < 3; i++) k.box(x0 + 0.3 + i * pw * 0.7, 0.085, z0, 0.02, 0.22, 0.02, PLANK_DARK);
};

// ---- the floating market (the wonder, 12 × 12) ------------------------------------------------------------

/** A shop-house on the quay: a painted front under a tin roof, an awning out over the water's edge. */
function shopHouse(k: Kit, r: () => number, x: number, z: number, w: number, y: number, face: 0 | 1 | 2): void {
  // drawn facing +z about its own point; the side quays turn it
  const yaw = face === 1 ? 0 : face === 0 ? Math.PI / 2 : -Math.PI / 2;
  placed(k, x, z, yaw, (ox, oz) => {
    const two = r() < 0.6, h = two ? 0.62 : 0.36, d = 0.85;
    const wall = [hex(0xe8d9b0), hex(0xd98a5a), hex(0x7fb3a8), hex(0xe6c04e), hex(0xc9d3e6), hex(0xd9a0a0)][Math.floor(r() * 6)];
    const roof = TINS[Math.floor(r() * TINS.length)], awn = PRODUCE[Math.floor(r() * 4)];
    k.box(ox, y, oz, w, h, d, wall);
    k.gable(ox, y + h, oz, w + 0.08, 0.22, d + 0.1, roof, scale(wall, 0.9), r() < 0.5);
    // the open shop front, glowing after dark, and the awning over it
    k.pane(ox, y + 0.04, oz + d / 2, w * 0.7, 0.2, 1, hex(0x4a3a30), [17.5, 24.5, 1.6], WARM_GLOW);
    if (two) k.pane(ox, y + 0.4, oz + d / 2, w * 0.5, 0.12, 1, DARK, EVENING, WARM_GLOW);
    const az = oz + d / 2, ay = y + 0.3;
    k.quad([ox - w / 2, ay, az], [ox + w / 2, ay, az], [ox + w / 2, ay - 0.1, az + 0.34], [ox - w / 2, ay - 0.1, az + 0.34], awn, [ox, ay - 0.3, az]);
    k.quad([ox - w / 2, ay - 0.004, az], [ox + w / 2, ay - 0.004, az], [ox + w / 2, ay - 0.104, az + 0.34], [ox - w / 2, ay - 0.104, az + 0.34], scale(awn, 0.7), [ox, ay + 0.3, az + 0.2]);
    // goods set out in front
    k.box(ox, y, az + 0.18, w * 0.6, 0.07, 0.14, PLANK_DARK, PRODUCE[Math.floor(r() * PRODUCE.length)]);
  });
}

/** A big roofed market pontoon: a raft on drums, stalls heaped with produce, a broad tiled roof on posts. */
function pontoon(k: Kit, r: () => number, x: number, z: number, w: number, d: number, roof: RGB): void {
  k.box(x, 0.02, z, w, 0.1, d, PLANK_DARK, PLANK);
  for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - 0.05), 0.02, z, 0.2, 0.07, d - 0.3, TARP);
  const ph = 0.62;
  for (const sx of [-1, 0, 1]) for (const sz of [-1, 1]) k.box(x + sx * (w / 2 - 0.12), 0.12, z + sz * (d / 2 - 0.12), 0.05, ph, 0.05, LACQUER);
  // a two-tier roof: a broad skirt and a raised ridge, with a gap between for the smoke
  k.box(x, 0.12 + ph, z, w + 0.1, 0.04, d + 0.1, scale(roof, 0.75));
  flared(k, x, 0.16 + ph, z, w + 0.5, 0.34, d + 0.5, roof, scale(roof, 0.8));
  flared(k, x, 0.56 + ph, z, w * 0.55, 0.26, d * 0.55, scale(roof, 1.12), scale(roof, 0.8));
  k.box(x, 0.4 + ph, z, w * 0.4, 0.2, d * 0.35, GOLD);
  // the stalls: tables of produce down both long sides
  const n = Math.floor(w / 0.42);
  for (let i = 0; i < n; i++) for (const sz of [-1, 1]) {
    const sx = x - w / 2 + 0.3 + (i * (w - 0.6)) / Math.max(1, n - 1), col = PRODUCE[Math.floor(r() * PRODUCE.length)];
    k.hip(sx, 0.22, z + sz * (d / 2 - 0.3), 0.3, 0.12, 0.24, col);
  }
  for (const sz of [-1, 1]) k.box(x, 0.12, z + sz * (d / 2 - 0.3), w - 0.3, 0.1, 0.28, PLANK);
  for (const sx of [-1, 1]) k.glowBox(x + sx * (w / 2 - 0.1), 0.6, z + d / 2 - 0.05, 0.07, 0.09, 0.07, hex(0xe8402f), LANTERN, hex(0xff8a4a));
}

/** A string of paper lanterns slung between two posts. */
function lanterns(k: Kit, a: P3, b: P3, n: number): void {
  for (const p of [a, b]) k.box(p[0], p[1] - 0.5, p[2], 0.025, 0.5, 0.025, PLANK_DARK);
  const cols = [hex(0xe8402f), hex(0xf2c14e), hex(0xf08a24)];
  let prev = a;
  for (let i = 1; i <= n + 1; i++) {
    const t = i / (n + 1), sag = Math.sin(t * Math.PI) * 0.12;
    const p: P3 = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t - sag, a[2] + (b[2] - a[2]) * t];
    k.bar(prev, p, 0.005, DARK);
    if (i <= n) k.glowBox(p[0], p[1] - 0.1, p[2], 0.09, 0.1, 0.09, cols[i % 3], LANTERN, i % 3 === 1 ? WARM_GLOW : hex(0xff8a4a));
    prev = p;
  }
}

/**
 * The floating market: a basin of murky water inside a timber quay, three roofed pontoons, and a
 * raft of long boats heaped with fruit and greens under straw hats and parasols. Stilted shop-houses
 * line the quay, lanterns hang over the water, and a pagoda-roofed gate stands at the landing.
 */
const floatingMarket: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2, qy = 0.16, q = 1.5;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, MURK);
  k.box(0.4, 0.02, 0.6, W * 0.55, 0.004, D * 0.5, MURK_DEEP);
  // the quay: a back strip and two arms, on piles
  const side = D - 0.2 - q - 2.2;
  k.box(0, 0.02, -hd + 0.1 + q / 2, W - 0.2, qy - 0.02, q, PLANK_DARK, PLANK);
  for (const s of [-1, 1]) k.box(s * (hw - 0.1 - q / 2), 0.02, -hd + 0.1 + q + side / 2, q, qy - 0.02, side, PLANK_DARK, PLANK);
  for (let i = 0; i < 7; i++) k.box(-hw + 0.6 + i * ((W - 1.2) / 6), 0, -hd + 0.1 + q + 0.03, 0.07, qy + 0.1, 0.07, PILE);
  for (const s of [-1, 1]) for (let i = 0; i < 4; i++) k.box(s * (hw - 0.1 - q - 0.03), 0, -hd + 2.6 + i * (side / 4), 0.07, qy + 0.1, 0.07, PILE);
  // shop-houses along the back and down the arms
  const nb = 7, bw = (W - 1.0) / nb;
  for (let i = 0; i < nb; i++) shopHouse(k, r, -hw + 0.5 + (i + 0.5) * bw, -hd + 0.62, bw - 0.18, qy, 1);
  for (const s of [-1, 1]) for (let i = 0; i < 4; i++) shopHouse(k, r, s * (hw - 0.62), -hd + 2.6 + i * 1.55, 1.2, qy, s < 0 ? 0 : 2);
  // the pontoons
  const pons: [number, number, number, number, RGB][] = [[-2.0, -1.7, 2.3, 1.5, hex(0xb8452f)], [2.1, -0.6, 2.1, 1.5, hex(0x2f8a7a)], [-0.4, 2.0, 2.5, 1.6, hex(0xd9a030)]];
  for (const [px, pz, pw, pd, roof] of pons) pontoon(k, r, px, pz, pw, pd, roof);
  // the boats: a ring nosed in round each pontoon, then the loose crowd between
  const boats: [number, number, number][] = [];
  const clear = (x: number, z: number): boolean => {
    if (Math.abs(x) > hw - q - 0.6 || z < -hd + q + 0.6 || z > hd - 0.6) return false;
    if (Math.abs(x) < 1.3 && z > hd - 2.2) return false;
    for (const [px, pz, pw, pd] of pons) if (Math.abs(x - px) < pw / 2 + 0.3 && Math.abs(z - pz) < pd / 2 + 0.3) return false;
    for (const [bx, bz] of boats) if (Math.hypot(x - bx, z - bz) < 0.52) return false;
    return true;
  };
  const launch = (x: number, z: number, yaw: number): void => {
    boats.push([x, z, yaw]);
    const shade = r() < 0.35 ? hex(BRIGHT[Math.floor(r() * BRIGHT.length)]) : null;
    placed(k, x, z, yaw, (ox, oz) => boat(k, r, ox, oz, 1.1 + r() * 0.3, HULLS[Math.floor(r() * HULLS.length)], r() < 0.92, shade));
  };
  for (const [px, pz, pw, pd] of pons) {
    for (let i = 0; i < 9; i++) {
      const a = (i / 9) * Math.PI * 2 + r() * 0.3, rx = pw / 2 + 0.75, rz = pd / 2 + 0.75;
      const x = px + Math.cos(a) * rx, z = pz + Math.sin(a) * rz;
      // (a boat along x turned by yaw points along (cos, -sin))
      if (clear(x, z)) launch(x, z, -a + (r() - 0.5) * 0.5);
    }
  }
  for (let tries = 0; tries < 400 && boats.length < 38; tries++) {
    const x = (r() - 0.5) * (W - 2 * q - 1.4), z = -hd + q + 0.7 + r() * (D - q - 1.6);
    if (clear(x, z)) launch(x, z, r() * Math.PI);
  }
  // lantern strings across the water between the quay arms, and along the back
  const ax = hw - 0.1 - q + 0.1;
  for (const z of [-hd + 3.6, -hd + 6.4]) lanterns(k, [-ax, qy + 0.9, z], [ax, qy + 0.9, z], 9);
  // the landing at the front, and the gate on it
  const lz = hd - 0.85;
  k.box(0, 0.02, lz, 3.0, qy - 0.02, 1.5, PLANK_DARK, PLANK);
  for (const s of [-1, 1]) for (const dz of [-0.7, 0, 0.7]) k.box(s * 1.47, 0, lz + dz, 0.07, qy + 0.1, 0.07, PILE);
  for (let i = 0; i < 3; i++) k.box(0, 0.02, lz - 0.8 - i * 0.12, 1.6, qy - 0.05 - i * 0.04, 0.12, PLANK);
  const gz = hd - 0.55, gx = 0.95, gh = 1.15;
  for (const s of [-1, 1]) {
    k.box(s * gx, qy, gz, 0.2, 0.08, 0.2, hex(0xb9b3a8));
    k.cyl(s * gx, qy + 0.08, gz, 0.065, gh, LACQUER, 8);
  }
  k.box(0, qy + gh - 0.18, gz, gx * 2 + 0.5, 0.09, 0.1, LACQUER);
  k.box(0, qy + gh - 0.02, gz, gx * 2 + 0.3, 0.12, 0.12, GOLD);
  flared(k, 0, qy + gh + 0.1, gz, gx * 2 + 1.0, 0.3, 0.8, hex(0x2f7a6a), LACQUER);
  k.box(0, qy + gh + 0.38, gz, gx * 1.1, 0.14, 0.2, LACQUER);
  flared(k, 0, qy + gh + 0.52, gz, gx * 1.7, 0.26, 0.6, hex(0x2f7a6a), LACQUER);
  k.box(0, qy + gh + 0.76, gz, 0.1, 0.1, 0.1, GOLD);
  for (const s of [-1, 1]) k.glowBox(s * (gx - 0.2), qy + gh - 0.36, gz, 0.1, 0.14, 0.1, hex(0xe8402f), LANTERN, hex(0xff8a4a));
  // mooring posts and a couple of mangroves in the corners
  for (const s of [-1, 1]) for (let i = 0; i < 3; i++) k.box(s * (hw - 0.5 - i * 0.9), 0, hd - 0.5, 0.06, 0.3, 0.06, PILE);
  for (const s of [-1, 1]) {
    k.cyl(s * (hw - 0.9), 0.02, hd - 1.3, 0.45, 0.04, MUD, 8);
    mangrove(k, s * (hw - 0.9), hd - 1.3, 1.6);
  }
};

export const MANGROVE_DRAW: Partial<Record<RegionBuildingKind, Draw>> = { stiltVillage, shrimpFarm, floatingMarket };
