import * as THREE from 'three';
import { NIGHT, VIS, Vis, poolMaterial } from './nightLights';
import { PERMANENT_SNOW, SEASON, seasonAt, snowfallAt, type SeasonName } from './season';
import { syncBoughs } from './regionProps';

/** Real seconds per game hour: twelve hours of day take five minutes, and so do twelve of night. */
export const SECONDS_PER_HOUR = 25;
/**
 * The lowest the key light is allowed to sit. A sun on the horizon throws shadows so long that the
 * shadow pass has to draw most of the neighbourhood: at 0.05 a sunset frame drew twice the meshes of noon.
 */
const SHADOW_MIN_EL = 0.3;
/**
 * The share of the shadow map, at each edge, over which shadows fade out. The box is fitted with this
 * much to spare round what the camera sees, so the fade lies just off screen; only where the box is
 * capped (a low camera looking to the horizon) does it show, as shadows thinning out rather than a line.
 */
const SHADOW_EDGE = 0.03;
/** How far above the ground something can stand and still throw its shadow into the box (along the light). */
const SHADOW_REACH_UP = 90;
/** The shadow box's own spread in depth, before fitting; the bias was tuned for it. */
const SHADOW_BIAS_DEPTH = 190;
/** Past this far from the camera there are no shadows (they are a pixel or two by then). */
const SHADOW_FAR = 140;
/** The widest the shadow box may grow (the overview and the building tools stand far back). */
const SHADOW_MAX = 320;
/** The shadow box grows and shrinks in steps this big (world units). */
const SHADOW_STEP = 4;
/** The shadow box turns with the camera in steps this big, so it lies along a low camera's long view. */
const SHADOW_YAW_STEP = Math.PI / 8;
/**
 * The sun and moon move the key light in steps this big (0.5°, a step about every 0.8 s), not every
 * frame. A light turning a hair each frame turns the shadow map's texel grid with it, so every shadow
 * edge re-rasterises a little differently 60 times a second and shimmers even with the camera still;
 * held between steps, the map is the same from one frame to the next.
 */
const SUN_STEP = Math.PI / 360;

// fade shadows out over the map's outer rim instead of stopping dead at its edge (the first getShadow is the
// directional and spot lights'; the point lights' own copy comes later)
if (!THREE.ShaderChunk.shadowmap_pars_fragment.includes('shadowEdge')) {
  THREE.ShaderChunk.shadowmap_pars_fragment = THREE.ShaderChunk.shadowmap_pars_fragment.replace(
    'return mix( 1.0, shadow, shadowIntensity );',
    `vec2 shadowEdge = min( shadowCoord.xy, 1.0 - shadowCoord.xy );
		return mix( 1.0, shadow, shadowIntensity * smoothstep( 0.0, ${SHADOW_EDGE.toFixed(3)}, min( shadowEdge.x, shadowEdge.y ) ) );`,
  );
}

/** Game days from one new moon to the next. */
const LUNAR_DAYS = 8;
/** The days of the week, for markets and weekend evenings. */
const WEEKDAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
/** Market day, twice a week: the stalls go up in the square. */
const MARKET_DAYS = new Set([1, 4]);

const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};
const c = (hex: number) => new THREE.Color(hex);

const SKY = { day: c(0xcfe6f5), glow: c(0xf1b08a), night: c(0x0c1530) };
const HEMI_SKY = { day: c(0xd8ecff), glow: c(0xffc4a2), night: c(0x42568e) };
const HEMI_GROUND = { day: c(0x8fb37a), glow: c(0x8a7560), night: c(0x1c2233) };
const SUN_LOW = c(0xff8a45), SUN_HIGH = c(0xfff1d6), MOONLIGHT = c(0xa9bcff);

const MOON_NAMES = ['new moon', 'waxing crescent', 'first quarter', 'waxing gibbous', 'full moon', 'waning gibbous', 'last quarter', 'waning crescent'];

/**
 * The sun and moon. One shadow-casting directional light follows whichever is brighter; the
 * hemisphere fill, sky and fog colours and exposure shift through sunrise, day, sunset and night.
 */
export class DayNight {
  /** Hour of the day, 0..24. */
  hour = 8;
  days = 0;
  /** 0 in full daylight, 1 in full darkness. */
  night = 0;
  /** An eclipse over the camera (docs/events.html), 0..1: the day dims toward dusk while it lasts. */
  eclipse = 0;
  /** 0 new, 0.25 first quarter, 0.5 full, 0.75 last quarter. */
  moonPhase = 0.3;
  /** Which season it is, and how deep into it. */
  season: SeasonName = 'summer';
  /** How hard it is snowing right now, 0..1. */
  snowing = 0;
  /** Seeds the weather, so two worlds get different winters. */
  weatherSeed = 1;
  private clockT = 0;
  /** How much of the moon's face is lit, 0..1. */
  moonLit = 0;
  readonly key: THREE.DirectionalLight;
  readonly hemi: THREE.HemisphereLight;
  private dir = new THREE.Vector3(-0.75, 0.9, -0.6).normalize();
  /**
   * The same direction as the key light's (toward the sun or the moon), but moving smoothly rather than in
   * SUN_STEPs: for the shadows laid on the ground as shapes (render/airShadows.ts, the jets' PlaneShadow),
   * which have no shadow-map texels to shimmer and would only jump with the steps.
   */
  readonly smoothDir = new THREE.Vector3(-0.75, 0.9, -0.6).normalize();
  private sky = new THREE.Color();
  private tmp = new THREE.Color();

  constructor(private scene: THREE.Scene, private renderer: THREE.WebGLRenderer) {
    scene.background = SKY.day.clone();
    this.hemi = new THREE.HemisphereLight(HEMI_SKY.day, HEMI_GROUND.day, 0.95);
    scene.add(this.hemi);
    const key = new THREE.DirectionalLight(SUN_HIGH, 2.6);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    // a first box; follow() fits it to the view every frame
    key.shadow.camera.near = 40;
    key.shadow.camera.far = 230;
    key.shadow.camera.left = -34;
    key.shadow.camera.right = 34;
    key.shadow.camera.top = 34;
    key.shadow.camera.bottom = -34;
    key.shadow.bias = -0.0004;
    key.shadow.normalBias = 0.04;
    // the shadow pass culls against the box; this adds the view's own outline inside it
    const frustum = key.shadow.getFrustum();
    const inBox = frustum.intersectsSphere.bind(frustum);
    frustum.intersectsSphere = (sphere) => inBox(sphere) && this.overView(sphere);
    scene.add(key);
    scene.add(key.target);
    this.key = key;
    this.update(0);
  }

  /** Move the clock by some hours (the moon keeps pace). */
  advance(hours: number): void {
    this.hour += hours;
    while (this.hour >= 24) { this.hour -= 24; this.days++; }
    while (this.hour < 0) { this.hour += 24; this.days--; }
  }

  update(dt: number): void {
    this.advance(dt / SECONDS_PER_HOUR);
    this.clockT += dt;
    this.turnYear();
    const a = ((this.hour - 6) / 12) * Math.PI; // 0 at 6:00 (east), π/2 at noon, π at 18:00 (west)
    const sunEl = Math.sin(a);
    this.moonPhase = (((this.days + this.hour / 24) / LUNAR_DAYS + 0.3) % 1 + 1) % 1;
    this.moonLit = (1 - Math.cos(this.moonPhase * Math.PI * 2)) / 2;

    // dusk lingers about forty game minutes past sunset (and dawn starts as long before sunrise)
    const day = smooth(-0.24, 0.14, sunEl) * (1 - 0.82 * this.eclipse);
    this.night = 1 - day;
    const twilight = Math.exp(-(((sunEl + 0.06) / 0.2) ** 2));
    // the high peaks keep the light a little after the valleys lose it, and go rose while they do
    SEASON.uAlpen.value = Math.exp(-(((sunEl + 0.02) / 0.09) ** 2));

    // sky, fog and fill light
    this.sky.copy(SKY.night).lerp(SKY.day, day).lerp(SKY.glow, twilight * 0.75);
    (this.scene.background as THREE.Color).copy(this.sky);
    if (this.scene.fog) (this.scene.fog as THREE.Fog).color.copy(this.sky);
    this.hemi.color.copy(HEMI_SKY.night).lerp(HEMI_SKY.day, day).lerp(HEMI_SKY.glow, twilight * 0.6);
    this.hemi.groundColor.copy(HEMI_GROUND.night).lerp(HEMI_GROUND.day, day).lerp(HEMI_GROUND.glow, twilight * 0.5);
    this.hemi.intensity = 0.34 + 0.61 * day;

    // key light: the sun while it's up, otherwise the moon (brighter the fuller it is)
    const sunI = 2.6 * smooth(-0.02, 0.3, sunEl) * (1 - 0.9 * this.eclipse);
    const moonI = (0.2 + 0.6 * this.moonLit) * smooth(0, 0.3, -sunEl);
    // the light's direction goes in steps (SUN_STEP); its colour and strength stay smooth
    const as = Math.round(a / SUN_STEP) * SUN_STEP, elS = Math.sin(as);
    const el = Math.sin(a);
    if (sunI >= moonI) this.smoothDir.set(Math.cos(a), Math.max(SHADOW_MIN_EL, el), 0.35).normalize();
    else this.smoothDir.set(-Math.cos(a), Math.max(SHADOW_MIN_EL, -el), -0.25).normalize();
    if (sunI >= moonI) {
      this.dir.set(Math.cos(as), Math.max(SHADOW_MIN_EL, elS), 0.35).normalize();
      this.tmp.copy(SUN_LOW).lerp(SUN_HIGH, smooth(0, 0.45, sunEl));
      this.key.intensity = sunI;
    } else {
      this.dir.set(-Math.cos(as), Math.max(SHADOW_MIN_EL, -elS), -0.25).normalize();
      this.tmp.copy(MOONLIGHT);
      this.key.intensity = moonI;
    }
    this.key.color.copy(this.tmp);
    this.renderer.toneMappingExposure = 1.05 + 0.2 * this.night;

    NIGHT.uHour.value = this.hour;
    NIGHT.uNight.value = this.night;
    // the lamps' pools are black until night passes 0.15 (SCHEDULE_GLSL): not drawn at all till then,
    // a draw a lit chunk all day (the lag audit, Oct 2026)
    poolMaterial.visible = this.night > 0.15;
  }

  /**
   * Work the year round. Nothing is rebuilt: the ground, the leaves and the water all read these
   * few uniforms, so the greens, the ambers, the lying snow and the ice on the shallows are just
   * numbers moving. Snow settles down the mountain as winter deepens, and a storm brings it lower.
   */
  private turnYear(): void {
    const s = seasonAt(this.days, this.hour);
    this.season = s.name;
    SEASON.uTime.value = this.clockT;
    SEASON.uYear.value = s.year;
    SEASON.uSpring.value = s.spring;
    SEASON.uAutumn.value = s.autumn;
    SEASON.uWinter.value = s.winter;
    syncBoughs(s.winter);

    const fall = snowfallAt(this.days, this.hour, this.weatherSeed);
    this.snowing = fall;
    // outside winter only the tops keep their snow; in a storm it comes right down to the shore
    SEASON.uSnow.value = Math.max(s.winter * 0.9, fall);
    SEASON.uSnowLine.value = PERMANENT_SNOW - (PERMANENT_SNOW - 0.4) * Math.min(1, fall * 1.25);
    // the shallows skin over once winter is properly in
    SEASON.uFreeze.value = Math.max(0, (s.winter - 0.35) / 0.65);

    // the parts of buildings that come and go: the fairground and the pools in summer, the rink in
    // winter, the market's stalls on market day, the bandstand's lights at the weekend
    const summer = s.summer >= 0.5, winter = s.winter >= 0.5, market = MARKET_DAYS.has(this.weekday);
    const v = VIS.uVis.value;
    v[Vis.Always] = 1;
    v[Vis.Summer] = summer ? 1 : 0; v[Vis.NotSummer] = summer ? 0 : 1;
    v[Vis.Market] = market ? 1 : 0; v[Vis.NotMarket] = market ? 0 : 1;
    v[Vis.Winter] = winter ? 1 : 0; v[Vis.NotWinter] = winter ? 0 : 1;
    v[Vis.Weekend] = this.weekend ? 1 : 0;
  }

  /**
   * Keep the shadow box over exactly what the camera sees. The view's four corner rays are run down to
   * the ground (a band a little under and over it, for roofs and slopes), cut off at SHADOW_FAR, and the
   * box is the tightest rectangle round them as the light sees them — plus a little ahead of the
   * vehicle, and the rim the edge fade lies in; the shadow pass then skips casters beside the view's own
   * outline inside that rectangle (see overView). Nothing off screen is drawn into the map, and nothing
   * on screen is left out of it, whatever the pitch or the height of the plane. The box turns with the
   * camera in steps, keeps its size until it is well wrong, and moves in whole texels, so the shadows
   * hold still rather than crawl. `ground` is the ground's height under the target, if known.
   *
   * (It used to be a square of a guessed size round the target: at a wide window or from a plane it
   * stopped short of the screen's edges, and there the shadows ended in a line.)
   */
  follow(target: THREE.Vector3, camera: THREE.Camera, ground?: number | null): void {
    const sc = this.key.shadow.camera;
    camera.updateMatrixWorld();
    const eye = camera.position;
    // the box's axes: z towards the light, y along the camera's view as the light sees it
    const e = camera.matrixWorld.elements;
    // the camera's up and its forward both point the way it looks, over the ground, at any pitch
    const fx = e[4] - e[8], fz = e[6] - e[10];
    const yaw = Math.atan2(fx, fz);
    const off = Math.atan2(Math.sin(yaw - this.boxYaw), Math.cos(yaw - this.boxYaw));
    if (Math.abs(off) > SHADOW_YAW_STEP * 0.6) this.boxYaw = Math.round(yaw / SHADOW_YAW_STEP) * SHADOW_YAW_STEP;
    sc.up.set(Math.sin(this.boxYaw), 0, Math.cos(this.boxYaw));
    const lz = this.lz.copy(this.dir);
    const lx = this.lx.crossVectors(sc.up, lz).normalize();
    const ly = this.ly.crossVectors(lz, lx);

    // the ground band the view can land on
    const g = ground ?? target.y;
    const lo = g - 2, hi = Math.min(g + 6, eye.y - 0.5);
    // never further than SHADOW_FAR, however far back the camera stands: zoomed out, a box stretched to
    // 1.4× the eye's distance drew every tree's shadow to the horizon (1.4M shadow triangles in the lag
    // audit, Oct 2026) for shadows a pixel or two across; the target itself is always in the box below
    const far = SHADOW_FAR;
    // the points, as the light sees them: x and y across its beam, z towards it
    const px = this.px, py = this.py;
    let n = 0, z0 = Infinity, z1 = -Infinity;
    const add = (q: THREE.Vector3) => {
      px[n] = q.dot(lx); py[n] = q.dot(ly);
      const z = q.dot(lz);
      if (z < z0) z0 = z;
      if (z > z1) z1 = z;
      n++;
    };
    add(target);
    const ray = this.ray, p = this.pt;
    for (let k = 0; k < 4; k++) {
      ray.set(k & 1 ? 1 : -1, k & 2 ? 1 : -1, 0.5).unproject(camera).sub(eye).normalize();
      for (let j = 0; j < 2; j++) {
        const h = j ? hi : lo;
        // where the corner ray meets this height, or the cut-off along it, brought down to the height
        const t = ray.y < -1e-4 && eye.y > h ? Math.min((h - eye.y) / ray.y, far) : far;
        p.copy(eye).addScaledVector(ray, t);
        p.y = h;
        add(p);
      }
    }
    // a little ahead of where the target is going, for the frames the map is not redrawn (Low redraws every other)
    const mx = target.x - this.lastAt.x, mz = target.z - this.lastAt.z;
    this.lastAt.copy(target);
    if (Math.hypot(mx, mz) < 4) {
      const ax = (mx * lx.x + mz * lx.z) * 8, ay = (mx * ly.x + mz * ly.z) * 8;
      for (let i = 0, m = n; i < m; i++) { px[n] = px[i] + ax; py[n] = py[i] + ay; n++; }
    }
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    for (let i = 0; i < n; i++) {
      x0 = Math.min(x0, px[i]); x1 = Math.max(x1, px[i]);
      y0 = Math.min(y0, py[i]); y1 = Math.max(y1, py[i]);
    }
    this.fitHull(n);
    // a view too big for the map keeps the part round the target
    const tx = target.dot(lx), ty = target.dot(ly);
    const inner = SHADOW_MAX * (1 - 2 * SHADOW_EDGE);
    x0 = Math.max(x0, tx - inner / 2); x1 = Math.min(x1, tx + inner / 2);
    y0 = Math.max(y0, ty - inner / 2); y1 = Math.min(y1, ty + inner / 2);

    // the size goes in steps, and holds until the view outgrows it or shrinks a step and more inside it,
    // so the texels keep their size while the camera eases about
    const pad = 1 / (1 - 2 * SHADOW_EDGE);
    const w = Math.max(16, (x1 - x0 + 1) * pad), hgt = Math.max(16, (y1 - y0 + 1) * pad);
    if (w > this.boxW || w < this.boxW - 2 * SHADOW_STEP) this.boxW = Math.min(SHADOW_MAX, Math.ceil(w / SHADOW_STEP) * SHADOW_STEP);
    if (hgt > this.boxH || hgt < this.boxH - 2 * SHADOW_STEP) this.boxH = Math.min(SHADOW_MAX, Math.ceil(hgt / SHADOW_STEP) * SHADOW_STEP);
    // the centre moves in whole texels
    const sx = this.boxW / this.key.shadow.mapSize.x, sy = this.boxH / this.key.shadow.mapSize.y;
    const cx = Math.round((x0 + x1) / 2 / sx) * sx, cy = Math.round((y0 + y1) / 2 / sy) * sy;
    // the light stands back far enough to catch whatever stands over the ground in the box
    const top = z1 + SHADOW_REACH_UP;
    const depth = Math.ceil((top - z0 + 4) / 8) * 8;
    this.key.position.set(0, 0, 0).addScaledVector(lx, cx).addScaledVector(ly, cy).addScaledVector(lz, top);
    this.key.target.position.copy(this.key.position).sub(lz);
    this.key.target.updateMatrixWorld();
    // the bias is a share of the depth range, so it is scaled to keep the same size in the world
    this.setBox(this.boxW / 2, this.boxH / 2, 0.5, depth, -0.0004 * SHADOW_BIAS_DEPTH / depth);
  }

  /**
   * The outline of the view as the light sees it (the convex hull of the points follow() gathered), as
   * edge lines with outward normals. The box is a rectangle round it; a low camera's view is a long
   * wedge, and a caster in the box's corners beside the wedge can throw no shadow anyone sees.
   */
  private fitHull(n: number): void {
    const px = this.px, py = this.py, ord = this.ord;
    ord.length = n;
    for (let i = 0; i < n; i++) ord[i] = i;
    ord.sort((a, b) => px[a] - px[b] || py[a] - py[b]);
    // Andrew's monotone chain: lower hull then upper, counter-clockwise
    const h = this.hull;
    let m = 0;
    const cross = (o: number, a: number, b: number) => (px[a] - px[o]) * (py[b] - py[o]) - (py[a] - py[o]) * (px[b] - px[o]);
    for (let i = 0; i < n; i++) {
      while (m >= 2 && cross(h[m - 2], h[m - 1], ord[i]) <= 0) m--;
      h[m++] = ord[i];
    }
    for (let i = n - 2, lower = m + 1; i >= 0; i--) {
      while (m >= lower && cross(h[m - 2], h[m - 1], ord[i]) <= 0) m--;
      h[m++] = ord[i];
    }
    m--; // the last point is the first again
    this.edges = 0;
    for (let i = 0; i < m; i++) {
      const a = h[i], b = h[(i + 1) % m];
      const dx = px[b] - px[a], dy = py[b] - py[a], len = Math.hypot(dx, dy);
      if (len < 1e-6) continue;
      const e = this.edges++;
      this.enx[e] = dy / len;
      this.eny[e] = -dx / len;
      this.ed[e] = this.enx[e] * px[a] + this.eny[e] * py[a];
    }
  }

  /** Whether a caster's bounding sphere reaches over the view's outline (the shadow pass's own test, added to its box test). */
  private overView(s: THREE.Sphere): boolean {
    const x = s.center.dot(this.lx), y = s.center.dot(this.ly);
    for (let e = 0; e < this.edges; e++) if (this.enx[e] * x + this.eny[e] * y - this.ed[e] > s.radius) return false;
    return true;
  }
  private px = new Float64Array(18);
  private py = new Float64Array(18);
  private ord: number[] = [];
  private hull = new Int32Array(40);
  private edges = 0;
  private enx = new Float64Array(40);
  private eny = new Float64Array(40);
  private ed = new Float64Array(40);

  private setBox(halfW: number, halfH: number, near: number, far: number, bias: number): void {
    const sc = this.key.shadow.camera;
    this.key.shadow.bias = bias;
    if (sc.right === halfW && sc.top === halfH && sc.near === near && sc.far === far) return;
    sc.left = -halfW; sc.right = halfW;
    sc.bottom = -halfH; sc.top = halfH;
    sc.near = near; sc.far = far;
    sc.updateProjectionMatrix();
  }
  private boxYaw = 0;
  private boxW = 0;
  private boxH = 0;
  private lastAt = new THREE.Vector3();
  private lx = new THREE.Vector3();
  private ly = new THREE.Vector3();
  private lz = new THREE.Vector3();
  private ray = new THREE.Vector3();
  private pt = new THREE.Vector3();

  /** 0 Monday .. 6 Sunday. */
  get weekday(): number { return ((this.days % 7) + 7) % 7; }
  get weekend(): boolean { return this.weekday >= 5; }

  clock(): string {
    const m = Math.floor(this.hour * 60);
    return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
  }

  moonName(): string {
    return MOON_NAMES[Math.round(this.moonPhase * 8) % 8];
  }
}
