/**
 * Work for the working vehicles' own knacks (the user, 27 Oct 2026): offered only about what the player is in,
 * whatever the director's gap (Missions.nearWork), each again after its cooldown.
 *
 * The Dozer: a town's mayor wants a boarded-up building nobody owns knocked down. Driving into one of its
 * walls head on at RAM_SHARE of the Dozer's top speed or more brings it down, the way the bulldoze tool (X)
 * clears one, in dust and rubble (main.ts knockDown).
 *
 * The ambulance: a patient at home needs a hospital, fast. Pick them up and a clock runs, set from the road
 * route's length at the ambulance's pace; get them in before it runs out. Sounding the siren (K) on the way
 * clears the road and pays a fifth more.
 */
import { Biome, DIRS, N, idx, inB, waterDepth, type Building, type Town, type World } from '../../world/tiles';
import { fenceAcross } from '../../world/fences';
import { buildingAt } from '../demolish';
import { BIG_SHIP, cargoById } from '../cargoTypes';
import { valueOf, type Site } from '../cargo';
import { demolishCost } from '../economy';
import { offerable } from '../fit';
import { defOf } from '../fleet';
import { roadRoute } from '../firstStart';
import { mayorOf } from '../mayor';
import type { MissionCtx } from './missions';
import type { Obj, PlaceRef, Reward } from './model';
import { shortSite } from './text';
import { offshore, roadNear, siteRef, squareOf, townRef, townsNear, type Template } from './templates';

/** The share of the Dozer's top speed a knock-down must be hit at: a run-up's worth, not a crawl. */
export const RAM_SHARE = 0.72;
/** The knock-down's speed, as the HUD reads it (km/h): about 13 for a Dozer's 1.5 tiles a second. */
export const RAM_KMH = Math.round(defOf('bulldozer').topSpeed * 12 * RAM_SHARE);
/** Boarded-up buildings this far from the player, at most, with a road this near them to come in by. */
const RAZE_NEAR = 160, RAZE_ROAD = 4;
/** Open tiles straight out from one of its faces a knock-down needs, for the Dozer to build up speed on. */
const RAZE_RUN = 3;
/**
 * A dash's clock: the road route at this share of the ambulance's top speed, plus a few seconds to pull
 * away. Set so the play bot's careful autopilot (about 1.6 tiles a second through town, half the Medic's top
 * speed) just makes it: a player who keeps their foot down has some seconds in hand, one who dawdles or takes
 * a wrong turn doesn't. Measured 27 Oct 2026 on a 43-tile route: 26.4 s for the bot, 30 s on the clock.
 */
const DASH_PACE = 0.55, DASH_GRACE = 6;
/** A patient's home this many road tiles from the hospital: a real drive, not round the corner. */
const DASH_MIN = 24, DASH_MAX = 110;

const r5 = (v: number) => Math.round(v / 5) * 5;
const r10 = (v: number) => Math.round(v / 10) * 10;
const pick = <T>(h: number, xs: T[]): T => xs[h % xs.length];
const RIDE_DOZER = { ids: ['bulldozer'], label: 'the Dozer' };
const RIDE_MEDIC = { ids: ['ambulance'], label: 'the Medic' };

/** In the Dozer, or with one in the fleet to go and get. */
const dozerAbout = (c: MissionCtx): boolean => c.def.id === 'bulldozer' || c.units.some((u) => u.model === 'bulldozer');

/**
 * Has some face of `b` a run-up: RAZE_RUN tiles straight out from it with nothing blocked, built or under water,
 * and no fence across it (a Dozer pulling away from a standstill can't push one over).
 */
function runUp(w: World, b: Building): boolean {
  const open = (x: number, z: number) => inB(x, z) && !w.blocked[idx(x, z)] && !(w.water[idx(x, z)] >= 0) && !buildingAt(w, x, z);
  for (let d = 0; d < 4; d++) {
    // from the face outward along DIRS[d]; the Dozer drives back the other way, (d + 2) & 3
    const [dx, dz] = DIRS[d], back = (d + 2) & 3;
    for (let k = 0; k < (dx ? b.d : b.w); k++) {
      const x0 = dx > 0 ? b.x + b.w : dx < 0 ? b.x - 1 : b.x + k, z0 = dz > 0 ? b.z + b.d : dz < 0 ? b.z - 1 : b.z + k;
      let s = 0;
      while (s < RAZE_RUN && open(x0 + dx * s, z0 + dz * s) && !(s > 0 && fenceAcross(w, idx(x0 + dx * s, z0 + dz * s), back))) s++;
      if (s >= RAZE_RUN) return true;
    }
  }
  return false;
}

/** Boarded-up buildings of a town nobody holds: not the player's, not a CPU fleet's, not another player's. */
function eyesores(c: MissionCtx, w: World, b: Building[]): Building[] {
  return b.filter((q) => q.derelict && q.solid && !q.gone && q.uid >= 0 && w.allBuildings[q.uid] === q && !c.owns(w, q.uid) && !c.held?.(w, q)
    // never the one-of-a-kind buildings a town is known by ("the capitol"), nor its station
    && !/^the /i.test(shortSite(q.kind)) && q.kind !== 'cityHall' && !w.stations.some((s) => s.building === q)
    && roadNear(w, q.x + q.w / 2, q.z + q.d / 2, Math.ceil(RAZE_ROAD + Math.max(q.w, q.d) / 2)) >= 0 && runUp(w, q));
}

/** The mayor's knock-down: a boarded-up building in a town near the player, rammed down in the Dozer. */
const raze: Template = {
  id: 'work:raze', thread: 'town', kind: 'job', cooldown: 6,
  gate(c) { return dozerAbout(c) ? null : 'needs a Dozer'; },
  bind(c, h) {
    if (!dozerAbout(c)) return null;
    for (const { w, t } of townsNear(c, RAZE_NEAR).slice(0, 4)) {
      const bs = eyesores(c, w, t.buildings);
      if (!bs.length) continue;
      const b = pick(h, bs);
      const name = shortSite(b.kind);
      const low = name.toLowerCase();
      const at: PlaceRef = { x: w.ox + b.x + b.w / 2, z: w.oz + b.z + b.d / 2, cell: [w.cx, w.cz], name: `the old ${low}` };
      // "Knock down the old bakery", or shorter for a long name
      const label = [`Knock down the old ${low}`, `Knock down the ${low}`].find((l) => l.length <= 28) ?? 'Knock down the old place';
      const m = mayorOf(t.name);
      const obj: Obj = { t: 'ram', label, icon: '🚜', at, b: { cell: [w.cx, w.cz], uid: b.uid, kind: b.kind, name }, kmh: RAM_KMH, ride: RIDE_DOZER };
      return {
        title: pick(h >>> 3, ['Knock It Down', 'The Eyesore', 'Bring It Down']),
        why: `The old ${low} has stood boarded up for years. Ram it down in your Dozer and the town will thank you for it.`,
        details: `${m.name} has had enough of the old ${low}: it is falling in, nobody will buy it, and the council can't run to a demolition crew.`,
        giver: { who: 'mayor', name: `Mayor ${m.short}`, at: squareOf(w, t, 'the town hall'), town: townRef(w, t) },
        hero: { kind: 'building', b: b.kind, arch: t.style, w: b.w, d: b.d, floors: b.floors, real: { cx: w.cx, cz: w.cz, uid: b.uid, seed: b.seed, facing: b.facing, ...(b.style ? { style: b.style } : {}), derelict: true } },
        caption: `The old ${low}`,
        objs: [obj],
        reward: [{ r: 'cash', n: r10(150 + demolishCost(b) * 0.6) }, { r: 'standing', town: townRef(w, t), n: 1 }],
      };
    }
    return null;
  },
};

/** The town a site stands in, if any. */
function townAt(s: Site) {
  const id = s.w.townId[Math.floor(s.lz) * N + Math.floor(s.lx)];
  return s.w.towns.find((t) => t.id === id) ?? null;
}

/** The ambulance's dash: a patient at home to a hospital, on the clock from the moment they are aboard. */
const dash: Template = {
  id: 'work:dash', thread: 'town', kind: 'job', cooldown: 3,
  gate(c) { return c.def.id === 'ambulance' ? null : 'in an ambulance'; },
  bind(c, h) {
    if (c.def.id !== 'ambulance') return null;
    const type = cargoById('patients');
    if (!type) return null;
    const near = (s: Site) => Math.hypot(s.x - c.at.x, s.z - c.at.z);
    let hosps = c.sites(['hospital']).filter((s) => near(s) < 160);
    if (!hosps.length) hosps = c.sites(['clinic']).filter((s) => near(s) < 120);
    hosps.sort((a, b) => near(a) - near(b));
    const homes = c.sites(type.from as string[]);
    for (const to of hosps.slice(0, 3)) {
      const span = (s: Site) => Math.hypot(s.x - to.x, s.z - to.z);
      const cands = homes.filter((s) => s.w === to.w && span(s) >= DASH_MIN * 0.6 && span(s) <= DASH_MAX * 0.8);
      for (let k = 0; k < Math.min(6, cands.length); k++) {
        const from = cands[(h + k * 7919) % cands.length];
        const route = roadRoute(to.w, from.lx, from.lz, to.lx, to.lz);
        if (!route || route.length < DASH_MIN || route.length > DASH_MAX) continue;
        const fit = offerable(c.def, c.at, from, to, type, true);
        if (!fit.ok && fit.why !== 'far') continue;
        const secs = r5(route.length / (c.def.topSpeed * DASH_PACE) + DASH_GRACE);
        const value = valueOf(type, fit.dist, 'urgent', fit.seconds);
        const town = townAt(to);
        const reward: Reward[] = [{ r: 'cash', n: r10(value * 0.6 + secs * 3) }];
        if (town) reward.push({ r: 'standing', town: townRef(to.w, town), n: 1 });
        const hosp = siteRef(to);
        return {
          title: pick(h >>> 3, ['Emergency Call', 'Blue Lights', 'Against the Clock']),
          why: `A patient needs the ${hosp.name.toLowerCase()}, fast. Pick them up and the clock starts: ${secs} seconds to get them in.`,
          details: 'Ambulance control has nobody nearer. Take the quick way, not the pretty one.',
          giver: { who: 'hospital', name: 'Ambulance control', at: { ...hosp, name: `the ${hosp.name.toLowerCase()}` }, town: town ? townRef(to.w, town) : null },
          hero: { kind: 'vehicle', model: 'ambulance' }, caption: 'The Medic',
          objs: [{ t: 'deliver', label: 'Bring the patient in', icon: type.icon, cargo: type.id, from: siteRef(from), to: hosp, n: 1, value, clock: secs, ride: RIDE_MEDIC }],
          reward,
        };
      }
    }
    return null;
  },
};


// ---- five more working vehicles' own jobs (the user, 27 Oct 2026) ----------------------------------------

const RIDE_HOOKY = { ids: ['wrecker'], label: 'Hooky' };
const RIDE_POST = { ids: ['postal', 'mailTruck'], label: 'a post van' };
const RIDE_SUNDAE = { ids: ['sundae'], label: 'Sundae' };
const RIDE_BALLOON = { ids: ['balloon'], label: 'the Sunrise' };
const RIDE_DUCK = { ids: ['duck'], label: 'the Puddle Duck' };
const inA = (ride: { ids: string[]; label: string }) => (c: MissionCtx): string | null => (ride.ids.includes(c.def.id) ? null : `in ${ride.label}`);
const placeOf = (w: World, lx: number, lz: number, name: string): PlaceRef => ({ x: w.ox + lx, z: w.oz + lz, cell: [w.cx, w.cz], name });
const near = (c: MissionCtx) => (s: { x: number; z: number }) => Math.hypot(s.x - c.at.x, s.z - c.at.z);

/** A broken-down car's resting place: a road tile out of town, `lo` to `hi` tiles from the player, not on a bridge. */
function hardShoulder(c: MissionCtx, h: number, lo: number, hi: number): { w: World; lx: number; lz: number } | null {
  for (const w of c.worlds.slice(0, 4)) {
    const cands: number[] = [];
    for (let z = 2; z < N - 2; z += 3) for (let x = 2; x < N - 2; x += 3) {
      const i = idx(x, z);
      if (!w.road[i] || w.townId[i] >= 0 || w.deckAxis[i] || w.blocked[i]) continue;
      const d = Math.hypot(w.ox + x + 0.5 - c.at.x, w.oz + z + 0.5 - c.at.z);
      if (d >= lo && d <= hi) cands.push(i);
    }
    if (cands.length) { const i = cands[h % cands.length]; return { w, lx: (i % N) + 0.5, lz: Math.floor(i / N) + 0.5 }; }
  }
  return null;
}

/** Hooky's recovery: a car broken down on a road out of town, brought in to the nearest garage. */
const recovery: Template = {
  id: 'work:recover', thread: 'town', kind: 'job', cooldown: 3,
  gate: inA(RIDE_HOOKY),
  bind(c, h) {
    if (!RIDE_HOOKY.ids.includes(c.def.id)) return null;
    const spot = hardShoulder(c, h, 40, 170);
    if (!spot) return null;
    const from = placeOf(spot.w, spot.lx, spot.lz, 'the hard shoulder');
    const garages = c.sites(['garage', 'gas']).filter((s) => Math.hypot(s.x - from.x, s.z - from.z) < 260)
      .sort((a, b) => Math.hypot(a.x - from.x, a.z - from.z) - Math.hypot(b.x - from.x, b.z - from.z));
    const to = garages[0];
    if (!to) return null;
    const car = pick(h >>> 2, ['tomato', 'bramble', 'mule', 'sunny', 'stomper']);
    const dist = Math.hypot(to.x - from.x, to.z - from.z) + Math.hypot(from.x - c.at.x, from.z - c.at.z);
    const town = townAt(to);
    const reward: Reward[] = [{ r: 'cash', n: r10(220 + dist * 2.2) }];
    if (town) reward.push({ r: 'standing', town: townRef(to.w, town), n: 1 });
    const g = siteRef(to);
    return {
      title: pick(h >>> 3, ['Broken Down', 'Roadside Rescue', 'Stuck on the Road']),
      why: `A ${defOf(car).name} has broken down on the road out of town. Load it up in Hooky and bring it in to the ${g.name.toLowerCase()}.`,
      details: 'The driver has the bonnet up and no idea what is wrong. The garage will take it from there.',
      giver: { who: 'garage', name: 'The breakdown line', at: { ...g, name: `the ${g.name.toLowerCase()}` }, town: town ? townRef(to.w, town) : null },
      hero: { kind: 'vehicle', model: 'wrecker' }, caption: 'Hooky to the rescue',
      objs: [{ t: 'deliver', label: 'Tow the car to the garage', icon: '🚗', cargo: 'brokenCar', from: { ...from, kind: 'roadside' }, to: g, n: 1, value: r5(60 + dist * 0.9), prop: car, ride: RIDE_HOOKY }],
      reward, hours: 4,
    };
  },
};

/** The town a site stands in, and whether a site is in it. */
const inTown = (s: Site, t: Town) => townAt(s) === t;

/** The Postie's collection: three of a town's postboxes emptied, and the sacks brought in to its post office. */
const mailRound: Template = {
  id: 'work:mail', thread: 'town', kind: 'job', cooldown: 3,
  gate: inA(RIDE_POST),
  bind(c, h) {
    if (!RIDE_POST.ids.includes(c.def.id)) return null;
    const offices = c.sites(['postOffice']).filter((s) => near(c)(s) < 200).sort((a, b) => near(c)(a) - near(c)(b));
    for (const po of offices.slice(0, 3)) {
      const t = townAt(po);
      if (!t) continue;
      const doors = c.sites(['house', 'townhouse', 'cottage', 'bungalow', 'apartment', 'duplex', 'terraceRow', 'shop', 'store', 'pub', 'diner'])
        .filter((s) => inTown(s, t) && Math.hypot(s.x - po.x, s.z - po.z) >= 8);
      const boxes: Site[] = [];
      for (let k = 0; k < doors.length && boxes.length < 3; k++) {
        const s = doors[(h + k * 7919) % doors.length];
        if (boxes.every((b) => Math.hypot(b.x - s.x, b.z - s.z) >= 8)) boxes.push(s);
      }
      if (boxes.length < 3) continue;
      // round the boxes nearest first from the post office, then back
      boxes.sort((a, b) => Math.hypot(a.x - po.x, a.z - po.z) - Math.hypot(b.x - po.x, b.z - po.z));
      const words = ['first', 'second', 'last'];
      const objs: Obj[] = boxes.map((s, k) => ({ t: 'reach', label: `Collect the ${words[k]} postbox`, icon: '📮', at: { x: s.x, z: s.z, cell: [s.w.cx, s.w.cz], name: `the ${words[k]} postbox` }, r: 2, stop: true, ride: RIDE_POST }));
      const p = siteRef(po);
      objs.push({ t: 'reach', label: 'Bring the sacks in', icon: '🏤', at: { x: po.x, z: po.z, cell: [po.w.cx, po.w.cz], name: `the ${p.name.toLowerCase()}` }, r: 2, stop: true, ride: RIDE_POST });
      return {
        title: pick(h >>> 3, ['The Last Post', 'Collection Round', 'Mail Run']),
        why: 'Three postboxes to empty before the last post goes. Stop at each in your post van, then bring the sacks in.',
        details: 'The regular postie is off sick and the boxes are overflowing. The sorting office closes at the end of the shift.',
        giver: { who: 'post', name: 'The postmaster', at: { ...p, name: `the ${p.name.toLowerCase()}` }, town: townRef(po.w, t) },
        hero: { kind: 'vehicle', model: c.def.id }, caption: 'The collection round',
        objs, reward: [{ r: 'cash', n: r10(260 + boxes.reduce((s, b) => s + Math.hypot(b.x - po.x, b.z - po.z), 0) * 1.6) }, { r: 'standing', town: townRef(po.w, t), n: 1 }], hours: 3,
      };
    }
    return null;
  },
};

/** Where an ice-cream van does trade: a town's parks, squares, lidos and fairgrounds. */
const TREATS = ['park', 'plaza', 'lido', 'fairground', 'waterPark', 'zoo', 'bandstandGreen', 'lakePark', 'greatPark', 'botanicalGarden'];

/** Sundae's round: two or three of a town's sunny spots, parked up a while at each with the chimes going, in the day. */
const iceCream: Template = {
  id: 'work:icecream', thread: 'car', kind: 'job', cooldown: 4,
  gate: inA(RIDE_SUNDAE),
  bind(c, h) {
    if (!RIDE_SUNDAE.ids.includes(c.def.id)) return null;
    for (const { w, t } of townsNear(c, 180).slice(0, 4)) {
      const spots = c.sites(TREATS).filter((s) => s.w === w && townAt(s) === t);
      const stops: Site[] = [];
      for (let k = 0; k < spots.length && stops.length < 3; k++) {
        const s = spots[(h + k * 7919) % spots.length];
        if (stops.every((q) => Math.hypot(q.x - s.x, q.z - s.z) >= 10)) stops.push(s);
      }
      if (stops.length < 2) continue;
      const objs: Obj[] = stops.map((s) => {
        const name = shortSite(String(s.kind)).toLowerCase();
        return { t: 'reach', label: `Sell at the ${name}`.slice(0, 28), icon: '🍦', at: { x: s.x, z: s.z, cell: [s.w.cx, s.w.cz], name: `the ${name}` }, r: 2.5, stop: true, hold: 15, after: 10, before: 19, ride: RIDE_SUNDAE };
      });
      return {
        title: pick(h >>> 3, ['Ice Cream Round', 'Ninety-Nines', 'Sunny Day Trade']),
        why: `Hot day, long queues. Park Sundae at ${stops.length} spots round town and sell for a while at each, in the daytime.`,
        details: 'Fifteen seconds parked at each with the chimes going, between ten in the morning and seven at night, while the crowds are out.',
        giver: { who: 'mayor', name: `Mayor ${mayorOf(t.name).short}`, at: squareOf(w, t, 'the town hall'), town: townRef(w, t) },
        hero: { kind: 'vehicle', model: 'sundae' }, caption: 'Chimes on',
        objs, reward: [{ r: 'cash', n: r10(180 + stops.length * 90) }, { r: 'standing', town: townRef(w, t), n: 1 }],
      };
    }
    return null;
  },
};

/** What a balloon's sightseers want to float over. */
const SIGHTS = ['landmark', 'lighthouse', 'capeLight', 'moatedCastle', 'dam', 'volcano'];
/** Where a balloon goes up from and comes down in: open country. */
const FIELDS = ['farmhouse', 'barn', 'croft', 'park', 'greatPark'];

/** The Sunrise's scenic flight: up from a field at dawn or dusk, over two sights, down in another field. */
const scenic: Template = {
  id: 'work:scenic', thread: 'car', kind: 'job', cooldown: 4,
  gate: inA(RIDE_BALLOON),
  bind(c, h) {
    if (!RIDE_BALLOON.ids.includes(c.def.id)) return null;
    const fields = c.sites(FIELDS).filter((s) => near(c)(s) < 120).sort((a, b) => near(c)(a) - near(c)(b));
    for (const up of fields.slice(0, 4)) {
      const d = (s: { x: number; z: number }) => Math.hypot(s.x - up.x, s.z - up.z);
      const sights = c.sites(SIGHTS).filter((s) => d(s) >= 30 && d(s) <= 170);
      const pair: Site[] = [];
      for (let k = 0; k < sights.length && pair.length < 2; k++) {
        const s = sights[(h + k * 7919) % sights.length];
        if (pair.every((q) => Math.hypot(q.x - s.x, q.z - s.z) >= 25 && q.kind !== s.kind || Math.hypot(q.x - s.x, q.z - s.z) >= 60)) pair.push(s);
      }
      if (pair.length < 2) continue;
      const last = pair[1];
      const down = c.sites(FIELDS).filter((s) => s !== up && Math.hypot(s.x - last.x, s.z - last.z) <= 90 && d(s) >= 30)
        .sort((a, b) => Math.hypot(a.x - last.x, a.z - last.z) - Math.hypot(b.x - last.x, b.z - last.z))[0];
      if (!down) continue;
      const dawn = h % 2 === 0;
      // a wonder by its own name ("the Colossus"), anything else by what it is ("the lighthouse")
      const sightName = (s: Site) => (s.kind === 'landmark' ? s.name.split(' · ')[0].replace(/^the /i, '') : shortSite(String(s.kind)).toLowerCase());
      const objs: Obj[] = [
        { t: 'reach', label: 'Take off from the field', icon: '🎈', at: { x: up.x, z: up.z, cell: [up.w.cx, up.w.cz], name: 'the take-off field' }, r: 3, stop: true, ride: RIDE_BALLOON, after: dawn ? 5 : 17, before: dawn ? 9 : 21 },
        ...pair.map((s): Obj => ({ t: 'reach', label: [`Fly over the ${sightName(s)}`, `Fly over ${sightName(s)}`, 'Fly over the wonder'].find((l) => l.length <= 28)!, icon: '🔭', at: { x: s.x, z: s.z, cell: [s.w.cx, s.w.cz], name: `the ${sightName(s)}` }, r: 8, ride: RIDE_BALLOON })),
        { t: 'reach', label: 'Land in the far field', icon: '🌾', at: { x: down.x, z: down.z, cell: [down.w.cx, down.w.cz], name: 'the landing field' }, r: 3, stop: true, ride: RIDE_BALLOON },
      ];
      const town = townAt(up);
      const span = d(pair[0]) + Math.hypot(pair[1].x - pair[0].x, pair[1].z - pair[0].z) + Math.hypot(down.x - last.x, down.z - last.z);
      return {
        title: dawn ? 'Sunrise Flight' : 'Sunset Flight',
        why: `Three sightseers want to see the ${sightName(pair[0])} and the ${sightName(pair[1])} from the air, then come down in a field.`,
        details: `They are booked for ${dawn ? 'dawn' : 'dusk'}: go up from the field ${dawn ? 'between five and nine in the morning' : 'between five and nine in the evening'}, float over both, then land gently in the field past the last.`,
        giver: { who: 'tours', name: 'The balloon club', at: { x: up.x, z: up.z, cell: [up.w.cx, up.w.cz], name: 'the take-off field' }, town: town ? townRef(up.w, town) : null },
        hero: { kind: 'vehicle', model: 'balloon' }, caption: dawn ? 'Up with the sun' : 'Down with the sun',
        objs, reward: [{ r: 'cash', n: r10(300 + span * 1.8) }],
      };
    }
    return null;
  },
};

/** The Puddle Duck's tour: tourists from the town square, down into the harbour, across it, and back ashore. */
const duckTour: Template = {
  id: 'work:ducktour', thread: 'town', kind: 'job', cooldown: 4,
  gate: inA(RIDE_DUCK),
  bind(c, h) {
    if (!RIDE_DUCK.ids.includes(c.def.id)) return null;
    for (const { w, t } of townsNear(c, 200).slice(0, 5)) {
      const port = w.ports.find((p) => p.town === t.id) ?? w.ports.slice().sort((a, b) => Math.hypot((a.root % N) - (t.x0 + t.size / 2), Math.floor(a.root / N) - (t.z0 + t.size / 2)) - Math.hypot((b.root % N) - (t.x0 + t.size / 2), Math.floor(b.root / N) - (t.z0 + t.size / 2)))[0];
      if (!port || Math.hypot((port.root % N) - (t.x0 + t.size / 2), Math.floor(port.root / N) - (t.z0 + t.size / 2)) > t.size + 30) continue;
      const a = offshore(w, port.root, port.dir, h, 10, 24), b = offshore(w, port.root, port.dir, h + 7, 18, 40);
      if (!a || !b || Math.hypot(a.lx - b.lx, a.lz - b.lz) < 8) continue;
      const sq = squareOf(w, t, 'the town square');
      const objs: Obj[] = [
        { t: 'reach', label: 'Meet the tourists', icon: '📸', at: sq, r: 3, stop: true, ride: RIDE_DUCK },
        { t: 'reach', label: 'Take them into the harbour', icon: '🦆', at: placeOf(w, a.lx, a.lz, 'the harbour'), r: 4, ride: RIDE_DUCK },
        { t: 'reach', label: 'Cross the harbour', icon: '⚓', at: placeOf(w, b.lx, b.lz, 'the far side of the harbour'), r: 4, ride: RIDE_DUCK },
        { t: 'reach', label: 'Bring them back ashore', icon: '🏛️', at: sq, r: 3, stop: true, ride: RIDE_DUCK },
      ];
      return {
        title: pick(h >>> 3, ['Duck Tour', 'Quack Attack', 'Land and Sea']),
        why: 'A coach party wants the duck tour: round the streets, straight down into the harbour, across it and back to the square.',
        details: 'Drive in off a beach or a slipway and the Puddle Duck floats. The tourists love the splash.',
        giver: { who: 'tours', name: 'The tourist office', at: sq, town: townRef(w, t) },
        hero: { kind: 'vehicle', model: 'duck' }, caption: 'Splashdown',
        objs, reward: [{ r: 'cash', n: r10(320) }, { r: 'standing', town: townRef(w, t), n: 1 }],
      };
    }
    return null;
  },
};

