import type { Look } from '../../shared/protocol';
import type { Arch } from '../world/tiles';
import { ARCHES } from './missions/passport';
import type { Fleet, Unit } from './fleet';
import { rewards } from './passportRewards';
import { sights } from './sights';

/**
 * The Passport's treats on the HQ, the buildings and the badge (game/passportRewards.ts says which are earned):
 * what this player is showing now, read by the town mesher's overrides (render/buildingStyle.ts), the HQ's
 * nameplate and statue (render/hqTreats.ts), the badges (render/fleetBadges.ts) and the online look
 * (net/online.ts → Look's g/hs/em/fp/np), so others see them too. Nothing here for a player without seals.
 */

/** A visa page's emblem: the glyph on its medallion and the colour of the frame round the badge. */
export interface Emblem { glyph: string; colour: string; deep: string }
export const EMBLEMS: Record<string, Emblem> = {
  Exploration: { glyph: '🧭', colour: '#2f8f6a', deep: '#1c5a42' },
  Haulage: { glyph: '📦', colour: '#b0703a', deep: '#6e4320' },
  Towns: { glyph: '🏘️', colour: '#c2562f', deep: '#7a321a' },
  Roads: { glyph: '🛣️', colour: '#5a6470', deep: '#353c44' },
  Vehicles: { glyph: '🚗', colour: '#d33a3a', deep: '#842020' },
  Company: { glyph: '🏢', colour: '#2c5aa0', deep: '#1a3664' },
  Factions: { glyph: '⚜️', colour: '#6b3fa0', deep: '#41255f' },
  Rail: { glyph: '🚂', colour: '#3b4a5a', deep: '#222b35' },
  'After Dark': { glyph: '🌙', colour: '#2b2f6b', deep: '#171940' },
  Estate: { glyph: '🔑', colour: '#8a6d1e', deep: '#56430f' },
  Earthworks: { glyph: '⛰️', colour: '#6d5a3a', deep: '#433722' },
  Community: { glyph: '🤝', colour: '#d0477a', deep: '#80284a' },
};
export const emblemOf = (g: string | null | undefined): Emblem | null => (g ? EMBLEMS[g] ?? null : null);

const isArch = (s: unknown): s is Arch => typeof s === 'string' && (ARCHES as string[]).includes(s);

/** What one fleet shows: its own (from the fleet and the seals), or another player's (from their look). */
export interface TreatLook {
  /** Architect's Eye: the HQ drawn in this style. */
  style: Arch | null;
  /** The Gilded Fleet: 1 gold roofs on the livery, 2 gold walls under deep gold roofs. */
  gild: 0 | 1 | 2;
  /** A visa emblem framing the badge. */
  emblem: string | null;
  /** The Front-row pass hanging off the badge. */
  pass: boolean;
  /** The gilded nameplate on the HQ. */
  plate: boolean;
}
export const NO_TREATS: TreatLook = { style: null, gild: 0, emblem: null, pass: false, plate: false };

/** This player's treats as they show: only what is both earned and switched on. */
export function myTreats(fleet: Fleet): TreatLook {
  const style = rewards.has('arch') && isArch(fleet.hqStyle) && sights.has('arch', fleet.hqStyle) ? fleet.hqStyle : null;
  return {
    style,
    gild: rewards.gilded ? fleet.gild : 0,
    emblem: fleet.emblem && rewards.emblems().includes(fleet.emblem) ? fleet.emblem : null,
    pass: rewards.has('event'),
    plate: rewards.has('sig'),
  };
}

/** Is the player's name in gold: the whole book, with the gold switched on. */
export const myNameGilded = (fleet: Fleet): boolean => rewards.gilded && fleet.gild > 0;

/** The treats as sent with this player's look (only the fields that are set, so a plain fleet's look is unchanged). */
export function lookTreats(fleet: Fleet): Pick<Look, 'g' | 'hs' | 'em' | 'fp' | 'np'> {
  const t = myTreats(fleet);
  return {
    ...(t.gild ? { g: t.gild } : {}),
    ...(t.style ? { hs: t.style } : {}),
    ...(t.emblem ? { em: t.emblem } : {}),
    ...(t.pass ? { fp: 1 as const } : {}),
    ...(t.plate ? { np: 1 as const } : {}),
  };
}

/** Another player's treats, read from their look (whatever an old or odd client sent is ignored). */
export function treatsOfLook(l: Look | null | undefined): TreatLook {
  if (!l) return NO_TREATS;
  return {
    style: isArch(l.hs) ? l.hs : null,
    gild: l.g === 1 || l.g === 2 ? l.g : 0,
    emblem: typeof l.em === 'string' && l.em in EMBLEMS ? l.em : null,
    pass: l.fp === 1,
    plate: l.np === 1,
  };
}

/** The favourite vehicle, for the gold statue: the one that has driven furthest (no trains: they have no body of their own). */
export function favouriteUnit(fleet: Fleet, isTrain: (model: string) => boolean): Unit | null {
  let best: Unit | null = null;
  for (const u of fleet.units) {
    if (isTrain(u.model)) continue;
    if (!best || u.log.tiles > best.log.tiles) best = u;
  }
  return best;
}
