import { money } from './cargoHud';
import type { Wallet } from './economy';

/** What the C menu hands out. */
const GRANTS = [1000, 100000];

/** What the cheats menu can do to the world as well as the wallet. */
interface CheatActions {
  /** Move the clock on an hour. */
  skipHour: () => void;
  /** Throw the save away and start a fresh world. */
  newWorld: () => void;
  /** The full dealer: every model, bought from anywhere at list price. */
  dealer: () => void;
  /** The full shop: every part and paint, at list price, from anywhere. */
  shop: () => void;
  /** The full roster: a driver with every licence at every rank, always there to hire. */
  roster: () => void;
  /** Online: the clock is the shared world's and the world is everyone's, so those two stay greyed. */
  online?: () => boolean;
}

/**
 * The hidden cheats menu (C with the settings window up, online or off): money, the full dealer, shop and roster; in
 * a world of your own also an hour on the clock or a new world. Not listed in the on-screen help — they are cheats, for trying out expensive vehicles,
 * seeing the night or a new seed without earning or waiting for it, so ordinary play never reaches
 * them.
 */
export class CashMenu {
  isOpen = false;
  private el = document.getElementById('cashmenu')!;
  private balance = document.createElement('div');

  constructor(private wallet: Wallet, private actions: CheatActions, private onChange: () => void = () => {}) {
    const panel = document.createElement('div');
    panel.className = 'panel';
    panel.innerHTML = `<header><h2>Cheats<span>.</span></h2><div class="keys"><kbd>C</kbd> or <kbd>Esc</kbd> close</div></header>`;
    this.balance.className = 'balance';
    panel.append(this.balance);
    const row = document.createElement('div');
    row.className = 'row';
    for (const amount of GRANTS) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'give';
      btn.textContent = `+${money(amount)}`;
      btn.addEventListener('click', () => {
        this.wallet.earn(amount, 'grants');
        this.sync();
        this.onChange();
      });
      row.append(btn);
    }
    panel.append(row);

    const world = document.createElement('h3');
    world.textContent = 'World';
    const acts = document.createElement('div');
    acts.className = 'row';
    const action = (title: string, sub: string, run: () => void, danger = false, local = false) => {
      const btn = document.createElement('button');
      if (local) this.localOnly.push({ btn, sub });
      btn.type = 'button';
      btn.className = `act${danger ? ' danger' : ''}`;
      const b = document.createElement('b');
      b.textContent = title;
      const s = document.createElement('span');
      s.textContent = sub;
      btn.append(b, s);
      btn.addEventListener('click', run);
      acts.append(btn);
    };
    action('Full dealer', 'Every model at list price, bought from anywhere', () => { this.close(); this.actions.dealer(); });
    action('Full shop', 'Every part and paint at list price, fitted from anywhere', () => { this.close(); this.actions.shop(); });
    action('Full roster', 'Every licence at every rank, always there to hire', () => { this.close(); this.actions.roster(); });
    action('Skip ahead an hour', 'The clock moves on; the sun follows', () => this.actions.skipHour(), false, true);
    action('New world', 'Throws this save away for a fresh seed', () => {
      if (!window.confirm('Start a new world? This one and its save are thrown away.')) return;
      this.close();
      this.actions.newWorld();
    }, true, true);
    panel.append(world, acts);
    this.el.append(panel);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    window.addEventListener('keydown', (e) => {
      if (!this.isOpen) return;
      if (e.code === 'Escape') { this.close(); e.preventDefault(); }
    });
  }

  toggle(): void {
    if (this.isOpen) this.close();
    else this.open();
  }

  open(): void {
    this.isOpen = true;
    this.el.hidden = false;
    this.sync();
  }

  close(): void {
    this.isOpen = false;
    this.el.hidden = true;
    (document.activeElement as HTMLElement | null)?.blur?.();
  }

  /** The buttons that only work in a world of your own, and what each says there. */
  private localOnly: { btn: HTMLButtonElement; sub: string }[] = [];

  private sync(): void {
    this.balance.textContent = `Wallet ${money(this.wallet.cash)}`;
    const online = this.actions.online?.() ?? false;
    for (const { btn, sub } of this.localOnly) {
      btn.disabled = online;
      const s = btn.querySelector('span');
      if (s) s.textContent = online ? 'Not online: the world and its clock are shared' : sub;
    }
  }
}
