import * as THREE from 'three';
import { fadingCone, softPoolTexture } from './softLight';
import { DIRS, STEP, World, heightAt, type Building } from '../world/tiles';
import { PHAROS_LAMP } from '../world/ancientKinds';

/**
 * Lighthouse beams: after dark every lighthouse in reach sweeps two long shafts of light round over the
 * sea, drawn as the helicopter's searchlight is (render/heliSpot.ts) — an open cone glowing faintly in the
 * night air, its tip at the lantern — with a soft pool where each shaft comes down on the water. No real
 * light is cast: a dozen spotlights would cost far more than they show from this high up.
 *
 * The lanterns are found once per county: the old lighthouses on the coast (world/poi.ts), the remote cape
 * lights (render/buildings/finds.ts `capeLight`), the Morro's light on its bastion (worldStylesB.ts) and the
 * Pharos, the ancient wonder on its headland (render/buildings/ancient.ts).
 */

/** How far a shaft reaches (tiles), how wide its cone opens (radians), how fast it turns (per second). */
const REACH = 18, HALF_ANGLE = 0.11, TURN = 0.55;
/** The most lighthouses drawn at once, and how far from the camera's focus one may be. */
const MOST = 10, NEAR = 140;

/** `aim`: the one height every shaft of this lamp comes down to, found once (see LighthouseBeams.update). */
interface Lamp { x: number; y: number; z: number; phase: number; aim?: number }
interface Shaft { beam: THREE.Mesh; pool: THREE.Mesh }

/** A lantern on a building, from where it stands in the model's own frame (origin mid-lot, +z its front). */
function onBuilding(w: World, b: Building, lx: number, lz: number, y: number): Lamp {
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const x = b.x + b.w / 2 + lx * c + lz * s, z = b.z + b.d / 2 - lx * s + lz * c;
  return { x: w.ox + x, y: b.level * STEP + y, z: w.oz + z, phase: (b.uid * 2.39996) % (Math.PI * 2) };
}

const lampCache = new WeakMap<World, { rev: number; lamps: Lamp[] }>();

/** Every lantern in a county, in world tiles. */
function lampsOf(w: World): Lamp[] {
  const have = lampCache.get(w);
  if (have && have.rev === w.revision) return have.lamps;
  const lamps: Lamp[] = [];
  for (const p of w.pois) {
    if (p.type !== 'lighthouse') continue;
    const cx = p.x + 0.5, cz = p.z + 0.5;
    lamps.push({ x: w.ox + cx, y: heightAt(w, cx, cz) + 1.62, z: w.oz + cz, phase: ((p.x * 7 + p.z * 13) % 31) / 5 });
  }
  for (const b of [...w.countryside, ...w.towns.flatMap((t) => t.buildings), ...w.works.flatMap((g) => (g.kind === 'wonder' ? g.buildings : []))]) {
    if (b.gone) continue;
    if (b.kind === 'capeLight') lamps.push(onBuilding(w, b, -0.38, -0.3, 2.35 + 0.22));
    else if (b.kind === 'pharos') lamps.push(onBuilding(w, b, PHAROS_LAMP.x, PHAROS_LAMP.z, PHAROS_LAMP.y));
    else if (b.kind === 'morroFort') lamps.push(onBuilding(w, b, -0.1 * (b.facing % 2 ? b.w : b.d) / 4, -1.15 * (b.facing % 2 ? b.d : b.w) / 4, 0.62 + 1.84));
  }
  lampCache.set(w, { rev: w.revision, lamps });
  return lamps;
}

export class LighthouseBeams {
  private shafts: Shaft[] = [];
  private beamMat = new THREE.MeshBasicMaterial({
    color: 0xfff1c8, vertexColors: true, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
  });
  private poolMat = new THREE.MeshBasicMaterial({ color: 0xfff1c8, map: softPoolTexture(), transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending });
  private cone: THREE.BufferGeometry;
  private disc = new THREE.CircleGeometry(1, 24).rotateX(-Math.PI / 2);
  private dir = new THREE.Vector3();
  private down = new THREE.Vector3(0, -1, 0);

  constructor(private scene: THREE.Scene) {
    // an open cone from its tip at the origin down -y: stretched and turned to each shaft each frame
    this.cone = fadingCone(20, 0.3);
    // every shaft made now, hidden: their shaders are built with the rest at the start of play, not on
    // the first evening a lighthouse comes into view
    for (let k = 0; k < MOST * 2; k++) { const s = this.shaft(k); s.beam.visible = s.pool.visible = false; }
  }

  private shaft(k: number): Shaft {
    while (this.shafts.length <= k) {
      const beam = new THREE.Mesh(this.cone, this.beamMat);
      const pool = new THREE.Mesh(this.disc, this.poolMat);
      beam.renderOrder = pool.renderOrder = 5;
      // culled like anything else: the frame's scale is in the matrix the frustum test uses (the shafts
      // were drawn even behind the camera, 40 draws at night)
      this.scene.add(beam, pool);
      this.shafts.push({ beam, pool });
    }
    return this.shafts[k];
  }

  /**
   * One frame. `night` 0..1 is how dark it is; `worlds` the counties in memory; `focus` where the camera
   * looks (world tiles); `ground(x, z)` the height of land or water there; `t` seconds, for the sweep.
   */
  update(t: number, night: number, worlds: Iterable<World>, focus: { x: number; z: number }, ground: (x: number, z: number) => number): void {
    const level = Math.max(0, Math.min(1, (night - 0.25) / 0.35));
    let used = 0;
    if (level > 0.01) {
      const near: Lamp[] = [];
      for (const w of worlds) for (const l of lampsOf(w)) if (Math.hypot(l.x - focus.x, l.z - focus.z) < NEAR) near.push(l);
      near.sort((a, b) => Math.hypot(a.x - focus.x, a.z - focus.z) - Math.hypot(b.x - focus.x, b.z - focus.z));
      for (const l of near.slice(0, MOST)) {
        for (const half of [0, Math.PI]) {
          const a = t * TURN + l.phase + half;
          const ex = l.x + Math.sin(a) * REACH, ez = l.z + Math.cos(a) * REACH;
          // the shaft only ever turns: it comes down to one height all the way round, the lowest ground on
          // its circle (the sea, for a light on the coast), found once. Aimed at whatever was under each end,
          // it pitched up and down with every hill it swept over
          l.aim ??= Math.min(l.y - 0.2, aimOf(l, ground) + 0.05);
          const ey = l.aim;
          const under = ground(ex, ez);
          const s = this.shaft(used++);
          this.dir.set(ex - l.x, ey - l.y, ez - l.z);
          const len = this.dir.length();
          const r = Math.tan(HALF_ANGLE) * len;
          s.beam.position.set(l.x, l.y, l.z);
          s.beam.scale.set(r, len, r);
          s.beam.quaternion.setFromUnitVectors(this.down, this.dir.normalize());
          s.pool.position.set(ex, ey + 0.04, ez);
          s.pool.scale.setScalar(r * 0.9);
          s.beam.visible = true;
          // the pool only where the shaft really meets the ground or the water, not hanging over a hollow or inside a hill
          s.pool.visible = Math.abs(under + 0.05 - ey) < 0.4;
        }
      }
    }
    for (let k = used; k < this.shafts.length; k++) this.shafts[k].beam.visible = this.shafts[k].pool.visible = false;
    this.beamMat.opacity = 0.045 * level;
    this.poolMat.opacity = 0.09 * level;
  }
}

/** The lowest land or water on the circle a lamp's shafts sweep: where they are all aimed. */
function aimOf(l: Lamp, ground: (x: number, z: number) => number): number {
  let lo = Infinity;
  for (let k = 0; k < 48; k++) {
    const a = (k / 48) * Math.PI * 2;
    lo = Math.min(lo, ground(l.x + Math.sin(a) * REACH, l.z + Math.cos(a) * REACH));
  }
  return Number.isFinite(lo) ? lo : l.y - 2;
}
