import { hex, scale } from '../../world/biomes';
import type { CountryKind } from '../../world/tiles';
import { Vis } from '../nightLights';
import {
  BRICK, BRIGHT, DARK, GLASS_LIGHT, METAL, PINE, ROOF_GREY, TAU, TRUNK, WARM_GLOW, WHITE, WOOD, pick, styleWall, win,
  type Draw, type Kit,
} from './kit';
import { lorry } from './business';

/** Country and roadside: mills, orchards, vines, stables and the farm shop at the gate. */

const CROPS = [0xd8a742, 0x5f9e45, 0xe2412f, 0xf28c38, 0x8e5cc7];

// ---- 94. windmill ------------------------------------------------------------------------------

/** A tower mill on the origin, sails turning slowly; also used outside towns. */
export function mill(k: Kit, seed: number): void {
  const tar = seed % 2 === 0, body = tar ? hex(0x3a3a3a) : hex(0xf4f1e8), cap = tar ? hex(0xf4f1e8) : hex(0x6b6f76);
  const seg = 8, H = 1.2;
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU, r0 = 0.3, r1 = 0.18;
    k.quad([Math.cos(a0) * r0, 0, Math.sin(a0) * r0], [Math.cos(a1) * r0, 0, Math.sin(a1) * r0], [Math.cos(a1) * r1, H, Math.sin(a1) * r1], [Math.cos(a0) * r1, H, Math.sin(a0) * r1], body, [0, H / 2, 0]);
  }
  k.dome(0, H, 0, 0.2, cap, 8, 3);
  k.box(0, 0, 0.26, 0.1, 0.18, 0.04, hex(0x5a3a28));
  k.box(0.12, 0.7, 0.22, 0.04, 0.04, 0.12, WOOD);
  k.spin(0, H - 0.02, 0.24, 'z', 0.5, (s) => {
    s.cyl(0, -0.03, 0, 0.04, 0.06, DARK, 6);
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + 0.3;
      const c = Math.cos(a), sn = Math.sin(a);
      s.bar([0, 0, 0.03], [c * 0.8, sn * 0.8, 0.03], 0.015, WOOD);
      // the lattice of the sail
      s.bar([c * 0.25 - sn * 0.08, sn * 0.25 + c * 0.08, 0.035], [c * 0.8 - sn * 0.08, sn * 0.8 + c * 0.08, 0.035], 0.012, WHITE);
      for (let j = 0; j < 4; j++) {
        const f = 0.3 + j * 0.16;
        s.bar([c * f, sn * f, 0.035], [c * f - sn * 0.08, sn * f + c * 0.08, 0.035], 0.006, WHITE);
      }
    }
  });
}

const windmill: Draw = (k, _W, _D, b) => mill(k, b.seed);

// ---- 95. sawmill -------------------------------------------------------------------------------

const sawmill: Draw = (k, W, D, b, r) => {
  // the open-sided shed with its saw carriage
  const sz = -D / 2 + 0.55;
  for (const sx of [-1, 1]) for (const zz of [-0.35, 0.35]) k.box(sx * 0.6, 0, sz + zz, 0.05, 0.5, 0.05, WOOD);
  k.gable(0, 0.5, sz, 1.4, 0.2, 0.9, ROOF_GREY, WOOD);
  k.box(0, 0, sz, 1.0, 0.1, 0.16, METAL);
  k.cyl(0.1, 0.1, sz, 0.1, 0.02, hex(0xdadada), 10);
  // log pile and plank stack
  for (let row = 0; row < 3; row++) {
    for (let i = 0; i < 4 - row; i++) {
      k.bar([-W / 2 + 0.3, 0.05 + row * 0.09, 0.1 + i * 0.1 + row * 0.05], [-W / 2 + 1.1, 0.05 + row * 0.09, 0.1 + i * 0.1 + row * 0.05], 0.045, i % 2 ? TRUNK : scale(TRUNK, 1.1));
    }
  }
  for (let i = 0; i < 5; i++) k.box(W / 2 - 0.45, i * 0.035, 0.3, 0.6, 0.03, 0.3, scale(hex(0xd8b27a), 1 - i * 0.03));
  // small office and a lorry
  k.box(W / 2 - 0.3, 0, -D / 2 + 0.3, 0.36, 0.26, 0.3, styleWall(r), ROOF_GREY);
  win(k, b, r, W / 2 - 0.3, 0.08, -D / 2 + 0.45, 0.14, 0.1, 1);
  lorry(k, 0, D / 2 - 0.25, true, hex(0x3f7d3a));
  for (let i = 0; i < 3; i++) k.cone(-W / 2 + 0.2 + i * 0.25, 0, D / 2 - 0.15, 0.1, 0.4, PINE, 6);
};

// ---- 96. greenhouse ----------------------------------------------------------------------------

const greenhouse: Draw = (k, W, D, _b, r) => {
  const glass = hex(0xcfe6ea), brick = pick(r, BRICK);
  const tw = (W - 0.6) / 2;
  for (const sx of [-1, 1]) {
    const x = sx * (tw / 2 + 0.15);
    k.box(x, 0, 0, tw, 0.06, D - 0.3, brick);
    // rows of green inside
    for (let i = 0; i < 3; i++) k.box(x - tw / 3 + (i * tw) / 3, 0.06, 0, 0.1, 0.08, D - 0.5, hex(0x4f9e45));
    // the glass tunnel as a half cylinder in six strips
    const seg = 6, R = tw / 2;
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * Math.PI, a1 = ((s + 1) / seg) * Math.PI;
      k.quad([x + Math.cos(a0) * R, 0.06 + Math.sin(a0) * R, -(D - 0.3) / 2], [x + Math.cos(a1) * R, 0.06 + Math.sin(a1) * R, -(D - 0.3) / 2],
        [x + Math.cos(a1) * R, 0.06 + Math.sin(a1) * R, (D - 0.3) / 2], [x + Math.cos(a0) * R, 0.06 + Math.sin(a0) * R, (D - 0.3) / 2], glass, [x, 0, 0]);
    }
    for (const sz of [-1, 1]) {
      for (let s = 0; s < seg; s++) {
        const a0 = (s / seg) * Math.PI, a1 = ((s + 1) / seg) * Math.PI;
        k.tri([x, 0.06, sz * (D - 0.3) / 2], [x + Math.cos(a0) * R, 0.06 + Math.sin(a0) * R, sz * (D - 0.3) / 2], [x + Math.cos(a1) * R, 0.06 + Math.sin(a1) * R, sz * (D - 0.3) / 2], glass, [x, 0.1, 0]);
      }
    }
    if (sx > 0) k.glowBox(x, 0.08, 0, tw * 0.8, R * 0.7, D - 0.5, glass, [17, 30, 1.2], hex(0xff4fd0));
  }
  // the water tank between them
  k.cyl(0, 0, -D / 2 + 0.3, 0.1, 0.3, hex(0x3f6b4a), 8);
};

// ---- 97. orchard -------------------------------------------------------------------------------

const orchard: Draw = (k, W, D, _b, r) => {
  const leaf = hex(0x5fa84a), blossom = hex(0xf2c4d8), fruit = pick(r, [0xe2412f, 0xf2a93b, 0xd8c83a]);
  for (let z = -D / 2 + 0.4; z < D / 2 - 0.2; z += 0.55) {
    for (let x = -W / 2 + 0.4; x < W / 2 - 0.2; x += 0.55) {
      const y = k.ground(x, z) - 0.02;
      k.box(x, y, z, 0.04, 0.16, 0.04, TRUNK);
      k.dome(x, y + 0.14, z, 0.2, leaf, 7, 2);
      // blossom out of summer, fruit in it
      k.tagged(Vis.NotSummer, () => k.dome(x, y + 0.16, z, 0.17, blossom, 7, 2));
      k.tagged(Vis.Summer, () => { for (let f = 0; f < 3; f++) k.box(x + Math.cos(f * 2.1) * 0.15, y + 0.2 + f * 0.03, z + Math.sin(f * 2.1) * 0.15, 0.04, 0.04, 0.04, fruit); });
    }
  }
  // a ladder, crates and beehives
  k.bar([W / 2 - 0.3, 0, D / 2 - 0.15], [W / 2 - 0.3, 0.32, D / 2 - 0.3], 0.01, WOOD);
  for (let i = 0; i < 3; i++) k.box(-W / 2 + 0.25 + i * 0.14, 0, D / 2 - 0.15, 0.12, 0.08, 0.1, WOOD);
  for (let i = 0; i < 2; i++) {
    k.box(W / 2 - 0.2, 0, -D / 2 + 0.2 + i * 0.2, 0.1, 0.12, 0.1, WHITE);
    k.box(W / 2 - 0.2, 0.12, -D / 2 + 0.2 + i * 0.2, 0.12, 0.02, 0.12, hex(0x9a8f86));
  }
};

// ---- 98. vineyard ------------------------------------------------------------------------------

const vineyard: Draw = (k, W, D, b, r) => {
  const vine = hex(0x4f8a3a);
  // rows of trellised vines, following the ground
  for (let x = -W / 2 + 0.3; x < W / 2 - 0.9; x += 0.3) {
    const z0 = -D / 2 + 0.25, z1 = D / 2 - 0.25;
    const y0 = k.ground(x, z0), y1 = k.ground(x, z1);
    k.bar([x, y0 + 0.14, z0], [x, y1 + 0.14, z1], 0.004, METAL);
    for (let z = z0; z <= z1; z += 0.4) k.box(x, k.ground(x, z), z, 0.015, 0.16, 0.015, WOOD);
    for (let z = z0 + 0.1; z < z1; z += 0.2) k.box(x, k.ground(x, z) + 0.08, z, 0.06, 0.08, 0.16, vine);
  }
  // the little winery with its terracotta roof and a barrel
  const wx = W / 2 - 0.45, wz = -D / 2 + 0.45, wall = hex(0xf1e4cc);
  k.box(wx, 0, wz, 0.6, 0.34, 0.6, wall);
  k.hip(wx, 0.34, wz, 0.7, 0.18, 0.7, hex(0xc06a42));
  k.box(wx, 0, wz + 0.305, 0.14, 0.22, 0.02, hex(0x5a3a28));
  win(k, b, r, wx - 0.3, 0.12, wz, 0.12, 0.1, 2);
  k.cyl(wx + 0.2, 0, wz + 0.4, 0.07, 0.14, WOOD, 8);
};

// ---- 99. farm shop -----------------------------------------------------------------------------

const farmShop: Draw = (k, _W, _D, _b, r) => {
  // an open-fronted stall under a pitched roof
  for (const sx of [-0.3, 0.3]) k.box(sx, 0, 0.05, 0.04, 0.32, 0.04, WOOD);
  k.box(0, 0, -0.2, 0.7, 0.32, 0.06, WOOD);
  for (const sx of [-1, 1]) k.box(sx * 0.33, 0, -0.08, 0.04, 0.32, 0.28, WOOD);
  k.gable(0, 0.32, -0.08, 0.8, 0.18, 0.44, pick(r, [0x8a3a34, 0x4a5560]), WOOD);
  // crates of produce
  for (let i = 0; i < 4; i++) {
    k.box(-0.24 + i * 0.16, 0.08, -0.05, 0.13, 0.06, 0.12, WOOD);
    k.box(-0.24 + i * 0.16, 0.14, -0.05, 0.11, 0.02, 0.1, hex(CROPS[i]));
  }
  // pumpkins out of summer
  k.tagged(Vis.NotSummer, () => { for (let i = 0; i < 3; i++) k.dome(-0.2 + i * 0.12, 0, 0.25, 0.045, hex(0xef8a1a), 6, 2); });
  // the hand-painted sign on an A-frame
  k.bar([0.3, 0, 0.36], [0.3, 0.16, 0.32], 0.02, WHITE);
  k.bar([0.3, 0, 0.28], [0.3, 0.16, 0.32], 0.02, WHITE);
  k.glowBox(0, 0.36, 0.1, 0.05, 0.03, 0.05, WHITE, [17, 20, 1.6], WARM_GLOW);
};

// ---- 100. stables ------------------------------------------------------------------------------

function horse(k: Kit, x: number, z: number, yaw: number, col: [number, number, number]): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const at = (u: number, v: number): [number, number] => [x + u * c + v * s, z - u * s + v * c];
  const body = at(0, 0), head = at(0, 0.14);
  k.box(body[0], 0.1, body[1], 0.07, 0.07, 0.07, col);
  const tail = at(0, -0.06);
  k.box(tail[0], 0.1, tail[1], 0.07, 0.07, 0.07, col);
  for (const [u, v] of [[-0.025, -0.06], [0.025, -0.06], [-0.025, 0.04], [0.025, 0.04]]) {
    const p = at(u, v);
    k.box(p[0], 0, p[1], 0.018, 0.1, 0.018, scale(col, 0.8));
  }
  k.bar([body[0], 0.16, body[1]], [head[0], 0.22, head[1]], 0.02, col);
}

const stables: Draw = (k, W, D, b, r) => {
  const wall = hex(0x9a6a44), roof = hex(0x5a5f6b);
  const bz = -D / 2 + 0.35;
  k.box(0, 0, bz, W - 0.3, 0.3, 0.5, wall);
  k.gable(0, 0.3, bz, W - 0.2, 0.18, 0.6, roof, wall);
  for (let i = 0; i < 4; i++) {
    const x = -W / 2 + 0.4 + i * ((W - 0.8) / 3);
    k.box(x, 0, bz + 0.255, 0.14, 0.12, 0.02, scale(wall, 0.7));
    k.box(x, 0.13, bz + 0.254, 0.14, 0.08, 0.004, DARK);
  }
  // the paddock
  const pz = 0.35, pd = D - 1.0;
  for (const sx of [-1, 1]) k.box(sx * (W / 2 - 0.15), 0, pz, 0.03, 0.14, pd, WHITE);
  k.box(0, 0.1, pz + pd / 2, W - 0.3, 0.03, 0.03, WHITE);
  k.box(0, 0.1, pz - pd / 2, W - 0.3, 0.03, 0.03, WHITE);
  horse(k, -0.3, pz, 0.6, hex(0x7a4a2a));
  horse(k, 0.35, pz + 0.1, -1.9, hex(0xb9b4aa));
  // hay and the horsebox
  k.cyl(W / 2 - 0.3, 0, bz + 0.4, 0.1, 0.12, hex(0xd8b85a), 8);
  k.box(-W / 2 + 0.35, 0.02, D / 2 - 0.15, 0.36, 0.2, 0.18, pick(r, [0xe8e2d4, 0x3f5a4a]));
  void [b, BRIGHT, GLASS_LIGHT, METAL];
};

export const COUNTRY_DRAW: Record<CountryKind, Draw> = {
  windmill, sawmill, greenhouse, orchard, vineyard, farmShop, stables,
};
