import type { KindSpec } from './townKinds';
import { Lot, type Building } from './tiles';
import { REGION_SHAPES_A, boxes } from './regionShapesA';
import { complexSolid } from './complexPlans';

type Solid = (lx: number, lz: number) => boolean;

/**
 * The 0.8.0 world's new buildings (NEXT_080, docs/phonelist.html): one table, spread into the game's per-kind tables
 * (townKinds, towns' heights, economy, estate, hqGrade, cargo labels, traffic tags, the gallery's sizes) the way the
 * places to play are (world/playKinds.ts), so each is added here once. The models are in render/buildings/k080*.ts.
 *
 * - the beachfront (world/beachfront.ts): a town's pier out over the sea in three sizes, lifeguard towers and
 *   volleyball courts on its sand
 * - the headland park (world/headland.ts): its row of old officers' houses, the gun battery on the cliff, the lookout
 * - rich enclaves (world/enclaves.ts): estate houses in ten styles on their grounds, and the gatehouse on the way in
 * - the big complexes (world/complexes.ts): a university campus, a zoological park, the castle-school, the baronial
 *   castle, the desert ksar, and an air force base's headquarters, jets on the line and helipads
 */

export const KINDS_080 = [
  'fishingPier', 'pleasurePier080', 'grandPier', 'lifeguardTower', 'volleyCourt',
  'officersRow', 'gunBattery', 'lookoutPoint',
  'estateHouse', 'gatehouse',
  'campus', 'zooPark', 'schoolCastle', 'baronialCastle', 'ksarVillage', 'baseHQ', 'parkedJets', 'heliPad080',
] as const;

export type Kind080 = (typeof KINDS_080)[number];

interface Info {
  label: string;
  icon: string;
  /** The lot in tiles: W across its front, D deep. */
  size: [number, number];
  /** How tall the model stands, in world units (towns.ts buildingHeight). */
  h: number;
  /** What it costs to knock down (economy.ts), which sets a lot's floor price. */
  price: number;
  /** As an HQ (hqGrade.ts). */
  grade: 0 | 1 | 2 | 3 | 4;
  zone: KindSpec['zone'];
  lot: Lot;
  /** What kind of place a trip there is (game/traffic.ts TAG_OF). */
  tag: 'work' | 'leisure' | 'shop';
  /** Nothing stops a car on it (a pier's deck, a court). */
  open?: boolean;
}

