const pick = <T>(f: (i: Info) => T): Record<Kind080, T> => Object.fromEntries(KINDS_080.map((k) => [k, f(INFO_080[k])])) as Record<Kind080, T>;

/** Spread into townKinds' KIND_SPEC (behind NEXT_080). */
export const SPEC_080 = pick((i): KindSpec => ({ w: i.size[0], d: i.size[1], zone: i.zone, lot: i.lot, gap: 0, apart: 6, ...(i.open ? { solid: false } : {}) }));
export const HEIGHT_080 = pick((i) => i.h);
export const PRICE_080 = pick((i) => i.price);
export const ICON_080 = pick((i) => i.icon);
export const LABEL_080 = pick((i) => i.label);
export const GRADE_080 = pick((i) => i.grade);
export const SIZE_080 = pick((i) => i.size);
export const TAG_080 = pick((i) => i.tag);
export const isKind080 = (k: string): k is Kind080 => k in INFO_080;

/**
 * What of each model stands up and stops a car (world/footprint.ts solidMask), in the model's frame: the pleasure
 * piers' wheel, helter-skelter, kiosks and pavilion as the wonder's are, the grand pier's coaster and carousel too.
 */
export const SHAPES_080: Partial<Record<Kind080, (W: number, D: number, b: Building) => Solid>> = {
  pleasurePier080: (W, D, b) => REGION_SHAPES_A.pleasurePier!(W, D, b),
  grandPier: (W, D, b) => {
    const pier = REGION_SHAPES_A.pleasurePier!(W, D, b);
    const extra = boxes({ x: W / 2 - 0.91, z: -D / 2 + 7.6, w: 1.3, d: 4.4 }, { x: -W / 2 + 0.81, z: -D / 2 + 9.2, w: 1.4, d: 1.4 });
    return (x, z) => pier(x, z) || extra(x, z);
  },
  // the big complexes (world/complexPlans.ts): their buildings and paddocks, the quads, courts and paths between open
  campus: () => complexSolid('campus'), zooPark: () => complexSolid('zooPark'), schoolCastle: () => complexSolid('schoolCastle'),
  baronialCastle: () => complexSolid('baronialCastle'), ksarVillage: () => complexSolid('ksarVillage'),
};
