/**
 * The big complexes' layouts (world/complexes.ts, 0.8.0): each a list of blocks in the model's frame (origin in the
 * lot's middle, x across W, +z the way it faces), read by both the model (render/buildings/k080complex.ts) and the
 * footprint (world/kinds080.ts SHAPES_080), so what stands up is exactly what stops a car. A block's `type` says how
 * the model draws it; `open` blocks are drawn but drivable or walkable (a quad's lawn, a paddock seen over a low wall
 * is not: its animals would be run down).
 */

export interface Block { type: string; x: number; z: number; w: number; d: number; h: number; open?: boolean }

