/** The desert ksar (12 x 10): its stacked granary round a court, domed houses, two pit courts, dew-catchers and the well. */
function ksar(): Block[] {
  const out: Block[] = [
    { type: 'granary', x: 0, z: -3.2, w: 7.0, d: 3.0, h: 1.1 },
    { type: 'pit', x: -4.2, z: 2.6, w: 2.4, d: 2.4, h: 0.15 },
    { type: 'pit', x: 4.4, z: -0.2, w: 2.4, d: 2.4, h: 0.15 },
    { type: 'dew', x: 4.6, z: 3.8, w: 2.6, d: 1.8, h: 1.1 },
    { type: 'well', x: 0, z: 1.2, w: 0.8, d: 0.8, h: 0.3 },
    { type: 'market', x: 0.2, z: 3.6, w: 3.6, d: 1.0, h: 0.5 },
    { type: 'square', x: 0, z: 1.2, w: 4.6, d: 3.6, h: 0, open: true },
  ];
  // the domed houses in a ring round the square
  const domes: [number, number][] = [[-4.8, -0.4], [-2.6, -0.6], [2.6, -0.6], [-5.0, 4.4], [-2.2, 4.4], [2.2, 4.6], [-4.8, -4.4], [5.0, -4.4], [5.2, 1.8]];
  for (const [x, z] of domes) out.push({ type: 'dome', x, z, w: 1.4, d: 1.4, h: 0.7 });
  return out;
}

const PLANS: Record<string, () => Block[]> = { campus, zooPark: zoo, schoolCastle, baronialCastle: baronial, ksarVillage: ksar };

/** A complex's blocks, or none for a kind that isn't one. */
export function complexBlocks(kind: string): Block[] {
  return PLANS[kind]?.() ?? [];
}

/** What of a complex stands up and stops a car, in the model's frame. */
export function complexSolid(kind: string): (x: number, z: number) => boolean {
  const solid = complexBlocks(kind).filter((b) => !b.open);
  return (x, z) => solid.some((b) => Math.abs(x - b.x) <= b.w / 2 && Math.abs(z - b.z) <= b.d / 2);
}
