import * as THREE from 'three';
import type { Town, World } from '../world/tiles';
import { GHOST_RED, buildTiles, disposeGhost } from '../render/ghost';
import type { Lobby } from './lobby';

/** The fleet's colours, for its ghosts. */
export interface Livery { primary: number; accent: number }

/**
 * Every call for ground standing in a town whose island is in memory, drawn where it stands (docs/lobbying.html):
 * the tiles the town would take in now, tinted in the fleet's colours, red when no ground is left. Rebuilt when a
 * preference changes or the island does. (The building ghosts that stood here too went with the building asks on
 * 3 Nov 2026: a fleet puts up its own buildings now, docs/blueprints.html.)
 */
export class GhostLayer {
  readonly group = new THREE.Group();
  private built = new Map<string, { obj: THREE.Object3D; sig: string }>();
  /** Territory previews are traced again at most this often, in seconds: they read the whole border. */
  private timer = 0;

  constructor(scene: THREE.Scene, private lobby: Lobby, private worlds: () => World[], private livery: () => Livery) {
    scene.add(this.group);
  }

  /** Something changed: look again next frame. */
  poke(): void { this.timer = 0; }

  update(dt: number): void {
    this.timer -= dt;
    if (this.timer > 0) return;
    this.timer = 1;
    const live = new Map<string, World>();
    for (const w of this.worlds()) live.set(`${w.cx},${w.cz}`, w);
    const want = new Set<string>();
    const colours = this.livery();
    for (const { key, p } of this.lobby.all()) {
      if (p.what !== 'territory') continue;
      const [cell, id] = key.split('#');
      const w = live.get(cell);
      const t = w?.towns[Number(id)];
      if (!w || !t) continue;
      const share = this.lobby.influence(key, p.who);
      const red = p.blocked || share <= 0;
      const tag = `${key}|${p.who}|t`;
      want.add(tag);
      const sig = `t|${red}|${w.revision}|${colours.primary}`;
      const have = this.built.get(tag);
      if (have?.sig === sig) continue;
      if (have) this.drop(tag);
      const obj = this.territoryGhost(w, t, red, colours);
      this.group.add(obj);
      this.built.set(tag, { obj, sig });
    }
    for (const tag of [...this.built.keys()]) if (!want.has(tag)) this.drop(tag);
  }

  private territoryGhost(w: World, t: Town, red: boolean, c: Livery): THREE.Object3D {
    const tiles = this.lobby.claimPreview(w, t);
    const mesh = buildTiles(w, tiles, red ? GHOST_RED : c.primary, 0.45);
    mesh.position.set(w.ox, 0, w.oz);
    return mesh;
  }

  private drop(tag: string): void {
    const b = this.built.get(tag);
    if (!b) return;
    this.group.remove(b.obj);
    disposeGhost(b.obj);
    this.built.delete(tag);
  }
}
