import { hex } from '../../world/biomes';
import { PLAY_INFO, PLAY_KINDS, type PlayKind } from '../../world/playKinds';
import type { Draw } from './kit';
import { PLAY_A_DRAW } from './playA';
import { PLAY_B_DRAW } from './playB';
import { MALL_DRAW } from './mall';
import { RESORT_DRAW } from './resort';
import { MINE_DRAW } from './mines';

/**
 * Places to play (world/playKinds.ts), gathered from the files that draw them: A the go-kart track and the
 * archery range, B the elementary school (and, in playKit.ts, the jungle gyms every playground is built from).
 * A kind not drawn yet stands as a plain block.
 */
const placeholder: Draw = (k, W, D, b) => {
  const h = Math.max(0.1, PLAY_INFO[b.kind as PlayKind]?.h ?? 0.5);
  k.box(0, 0, 0, Math.max(0.4, W - 0.3), h, Math.max(0.4, D - 0.3), hex(0xd8d0c0));
};

const parts: Partial<Record<PlayKind, Draw>> = { ...PLAY_A_DRAW, ...PLAY_B_DRAW, ...MALL_DRAW, ...RESORT_DRAW, ...MINE_DRAW };

export const PLAY_DRAW = Object.fromEntries(PLAY_KINDS.map((k) => [k, parts[k] ?? placeholder])) as Record<PlayKind, Draw>;

/** gallery.html?group=play. */
export const PLAY_GALLERY: Record<string, Record<string, Draw>> = { play: PLAY_DRAW };
