import { hashString } from '../../world/rng';
import { personName } from '../mayor';
import type { Paper, TownInfo } from './types';

/**
 * Who publishes the paper, and what it is called (docs/newspaper.html, The publisher). The biggest town the
 * player dealt with this year that has a news station is the Press's local branch; failing that, the biggest
 * with a news station in reach; failing that, the county prints a country weekly. A city's paper is named by
 * a hash of the city, in its own style's manner, so the same city always prints the same paper.
 */

/** Bigger towns publish first. */
const RANK: Record<string, number> = { mega: 5, metro: 4, city: 3, suburb: 2, rural: 1 };
export const rankOf = (kind: string): number => RANK[kind] ?? 0;

type Family = 'english' | 'french' | 'italian' | 'spanish' | 'dutch' | 'hungarian' | 'russian' | 'turkish' | 'japanese' | 'chinese' | 'sun';

/** Each town style's newspaper manner. */
const FAMILY: Record<string, Family> = {
  paris: 'french', leman: 'french',
  roman: 'italian', venice: 'italian', mediterranean: 'italian', adriatic: 'italian', como: 'italian',
  andean: 'spanish', havana: 'spanish', moorish: 'spanish', adobe: 'spanish', maya: 'spanish',
  dutch: 'dutch', budapest: 'hungarian', russian: 'russian', ottoman: 'turkish',
  japanese: 'japanese', tokyo: 'japanese', osaka: 'japanese', spirit: 'japanese', onsen: 'japanese',
  chinese: 'chinese', hongkong: 'chinese', eastern: 'chinese', seasia: 'chinese',
  vegas: 'sun', modernist: 'sun', dubai: 'sun', cyberpunk: 'sun', motherroad: 'sun',
};

/** The forms each manner names a paper in; {c} is the city. */
const FORMS: Record<Family, string[]> = {
  english: ['The {c} Herald', 'The {c} Gazette', 'The {c} Chronicle', 'The {c} Times', 'The {c} Courier', 'The {c} Post', 'The {c} Tribune',
    'The {c} Standard', 'The {c} Examiner', 'The {c} Bugle', 'The {c} Echo', 'The {c} Argus', 'The {c} Ledger', 'The {c} Sentinel'],
  french: ['Le Journal de {c}', 'La Dépêche de {c}', '{c}-Soir'],
  italian: ['Il Corriere di {c}', 'La Gazzetta di {c}', 'Il Messaggero di {c}'],
  spanish: ['El Diario de {c}', 'La Voz de {c}', 'El Heraldo de {c}'],
  dutch: ['Het {c} Dagblad', '{c} Courant'],
  hungarian: ['{c} Hírlap', '{c} Napló'],
  russian: ['{c} Pravda', '{c} Vestnik'],
  turkish: ['{c} Gazetesi', '{c} Postası'],
  japanese: ['{c} Shimbun', '{c} Nichinichi'],
  chinese: ['{c} Daily', '{c} Evening News'],
  sun: ['The {c} Sun', 'The {c} Review-Journal', 'The {c} Mirror'],
};

const FACE: Record<Family, Paper['face']> = {
  english: 'black', french: 'serif', italian: 'serif', spanish: 'serif', dutch: 'black', hungarian: 'serif', russian: 'serif', turkish: 'serif',
  japanese: 'sans', chinese: 'sans', sun: 'sans',
};

const SLOGANS = [
  'All the news that fits the page', 'Since before the bypass', 'Read by every driver worth the name', 'Printed while the kettle boils',
  'The town’s own paper', 'News by the cartload', 'First with the freight', 'Never late, rarely wrong', 'Every road, every week of the year',
  'Fair to all, afraid of none', 'Ink on the presses since the first road', 'What the town is talking about', 'The paper on every dashboard',
  'News that pays its levy', 'From the quay to the town hall', 'Folded in every glovebox', 'Here when the ferry is not',
  'Straight from the square', 'As told at the counter', 'The county’s own voice',
];

const COUNTY_FORMS = ['The {c} Advertiser', 'The {c} Weekly News', 'The {c} Courier & Advertiser'];

/** The paper a city prints, or a county when there is no city. */
export function paperFor(t: TownInfo | null, county: string): Paper {
  if (!t) {
    const h = hashString(`press|county|${county}`);
    return {
      name: COUNTY_FORMS[h % COUNTY_FORMS.length].replace('{c}', county), slogan: SLOGANS[(h >>> 7) % SLOGANS.length], face: 'black',
      city: county, key: '', county, staff: staff(county),
    };
  }
  const fam = FAMILY[t.style] ?? 'english';
  const forms = FORMS[fam];
  const h = hashString(`press|${t.key}|${t.name}`);
  return {
    name: forms[h % forms.length].replace('{c}', t.name), slogan: SLOGANS[(h >>> 7) % SLOGANS.length], face: FACE[fam],
    city: t.name, key: t.key, county: t.county, staff: staff(t.name),
  };
}

/** Three reporters a city names once and keeps (mayor.ts personName, salted with the city). */
function staff(city: string): string[] {
  const out: string[] = [];
  for (let i = 0; out.length < 3 && i < 12; i++) {
    const n = personName(`press|${city}|${i}`);
    if (!out.includes(n)) out.push(n);
  }
  return out;
}

/**
 * The publisher: the biggest dealt-with town that has a news station (ties to the one dealt with most), else
 * the biggest with a news station in reach (`near`), else none (the county prints).
 */
export function publisher(dealt: TownInfo[], near: TownInfo[]): TownInfo | null {
  const best = (list: TownInfo[]) => list.filter((t) => t.news).sort((a, b) => rankOf(b.kind) - rankOf(a.kind) || b.n - a.n || a.key.localeCompare(b.key))[0] ?? null;
  return best(dealt) ?? best(near);
}
