/**
 * Range (docs/exploration.html), the parts the game and the server share: the chain that decides how much of
 * a vehicle's distance from home was honestly travelled, a board line, and the world's frontier bounty.
 *
 * Both sides run the same chain. The game feeds it a frame at a time and calls a step of four tiles or more
 * a placement; the server feeds it the poses it is sent and calls a step a placement when it is faster than
 * the vehicle could have gone. Either way a placement keeps what was already credited and claims nothing new.
 */

/** Tiles to a cell's side (world/tiles.ts N, kept here so the server needs nothing of the game's). */
export const RANGE_N = 256;

/** The frontier bounty for reaching ring `r` from the origin first: $500 a ring, never more than BOUNTY_MAX (the user, 28 Oct 2026). */
export const BOUNTY_PER_RING = 500;
export const BOUNTY_MAX = 1000;
export const bountyFor = (ring: number): number => Math.min(BOUNTY_MAX, BOUNTY_PER_RING * ring);

/** A board keeps this many lines a model. */
export const BOARD_KEEP = 100;

/** The board metrics the server writes on a player's leaderboard line (BoardRow.v), by kind ('' for anything). */
export const RANGE_METRIC: Record<'' | 'land' | 'water' | 'air' | 'rail', string> = { '': 'range', land: 'rangeLand', water: 'rangeWater', air: 'rangeAir', rail: 'rangeRail' };
export const FRONTIER_METRIC = 'frontier';

/** The cell ring of a world point from the origin: Chebyshev distance in cells. */
export const ringOf = (gx: number, gz: number): number => Math.max(Math.abs(Math.floor(gx / RANGE_N)), Math.abs(Math.floor(gz / RANGE_N)));

/**
 * How far out a chain may honestly claim to be: never beyond its distance from home, nor beyond what it was
 * credited when it last began plus every tile travelled since.
 */
export class Chain {
  budget = 0;
  credit = 0;
  private last: [number, number] | null = null;
  /** `carried`: the credit a save or a sign-in starts from (Infinity trusts wherever the vehicle is). */
  constructor(public carried = 0) {}

  /** A new start: the next step carries on from what was credited (or, if it never stepped, from what it was to carry). */
  restart(carried = this.last ? this.credit : this.carried): void { this.last = null; this.carried = carried; }

  /** One step to (gx, gz); `jump` true when this step is a placement. Returns the credit. */
  step(gx: number, gz: number, hx: number, hz: number, jump: (moved: number) => boolean): number {
    const d = Math.hypot(gx - hx, gz - hz);
    if (!this.last) this.budget = Math.min(d, this.carried);
    else {
      const moved = Math.hypot(gx - this.last[0], gz - this.last[1]);
      if (jump(moved)) this.budget = Math.min(d, this.credit);
      else this.budget += moved;
    }
    this.last = [gx, gz];
    this.credit = Math.min(d, this.budget);
    return this.credit;
  }

  /** The vehicle is where it honestly travelled to: nothing of its distance from home was a placement. */
  honest(gx: number, gz: number, hx: number, hz: number): boolean {
    return this.credit >= Math.hypot(gx - hx, gz - hz) - 2;
  }
}

/** The furthest from the origin a chain can honestly be: no further than home's own distance plus the credit. */
export const frontierOf = (gx: number, gz: number, hx: number, hz: number, credit: number): number =>
  credit > 0 ? Math.min(Math.hypot(gx, gz), Math.hypot(hx, hz) + credit) : 0;

/** One line of a model's board, as sent. */
export interface ReachRow {
  by: string; name: string;
  /** Tiles from home, the record. */
  d: number;
  /** When it was set (ms). */
  at: number;
  /** The cell it was set in. */
  c: [number, number];
  brand?: { primary: number; accent: number; logo: string };
  /** Its place on the board, 1 first: sent on my own line. */
  place?: number;
}

/** The world's frontier as told: the furthest ring anyone has honestly reached, who got there, and the open bounty. */
export interface FrontierInfo {
  ring: number;
  by?: string; name?: string;
  /** The bounty waiting for the first fleet to reach `open` rings out. */
  open: number; prize: number;
}
