/**
 * The Standings tab of the social window (game/socialWindow.ts, docs/social.html): how the fleet stands
 * against the others, in a local game and online alike. On the left every metric with your number, your
 * place and the best of the rest; on the right every fleet ranked by the metric picked, its bar in its own
 * livery, and over the net-worth ranking a line chart of the leaders' last fortnight. Online there is a
 * scope switch: the fleets you have met (your own books, game/metrics.ts), your friends, or everyone on the
 * server's board, whose rows carry the same metrics once their game has saved.
 */
import { esc, money } from './cargoHud';
import { chip, css } from './firmSpec';
import { METRICS, type FleetMetrics, type MetricDef, type MetricKey } from './metrics';
import { legend, lines, type Series } from './charts';
import type { BoardRow } from '../../shared/protocol';
import type { SocialTabBody } from './socialWindow';

/**
 * Every other player's fleet on the server's board, signed in or not (the user, 21 Oct 2026): not this
 * player's, nor a shared fleet they are in. Online first, then the richest.
 */
export function otherPlayers(rows: BoardRow[], me: string | null, crew: string | null): BoardRow[] {
  return rows.filter((r) => !r.cpu && r.id !== me && !(crew && r.crew === crew))
    .sort((a, b) => Number(!!b.online) - Number(!!a.online) || b.worth - a.worth);
}

/** When a player was last about: online now, or how long since their game last saved. */
export function lastSeen(r: { online?: boolean; seen?: number }, now = Date.now()): string {
  if (r.online) return 'online';
  if (!r.seen) return 'away';
  const m = Math.max(0, (now - r.seen) / 60000);
  if (m < 2) return 'seen just now';
  if (m < 60) return `seen ${Math.round(m)} min ago`;
  if (m < 48 * 60) return `seen ${Math.round(m / 60)} h ago`;
  return `seen ${Math.round(m / 1440)} days ago`;
}

/** A player's line under their fleet's name: who runs it, whether they are about, and its size. */
function playerSub(r: BoardRow): string {
  return `${esc(r.by ?? 'player')}${r.online ? ' <i class="on"></i>' : ` · ${esc(lastSeen(r))}`} · ${r.units} vehicle${r.units === 1 ? '' : 's'}${r.towns ? ` · ${r.towns} town${r.towns === 1 ? '' : 's'}` : ''}`;
}

/** A board line as one of the tab's entries. */
function rowEntry(r: BoardRow): Entry {
  return {
    name: r.name, livery: [r.primary, r.accent], logo: r.logo || undefined, you: false, gone: null,
    v: { ...(r.v ?? {}), worth: r.worth, units: r.units, held: r.towns }, hist: r.hist ?? [],
    pid: r.cpu ? undefined : r.id, human: !r.cpu,
    // the Gilded Fleet (game/treats.ts): its game sends it with the metrics
    gilded: !r.cpu && !!r.v?.gilded,
    sub: r.cpu ? `CPU · ${r.units} vehicle${r.units === 1 ? '' : 's'}${r.towns ? ` · ${r.towns} town${r.towns === 1 ? '' : 's'}` : ''}` : playerSub(r),
  };
}

/** Fleets the ranking shows before "Show all". */
const RANK_TOP = 10;
/** Fleets the chart draws. */
const CHART_TOP = 5;
const BARS = '▁▂▃▄▅▆▇█';

type Scope = 'met' | 'friends' | 'neighbours' | 'world';

/** What the tab needs from the online game; null in a local one. */
export interface StandingsOnline {
  active(): boolean;
  /** The server's board as last heard. */
  rows(): BoardRow[];
  /** Ask the server for its board again. */
  ask(): void;
  /** This player's id on the board. */
  youId(): string | null;
  /** The shared fleet this player is in (docs/sharedfleets.html), whose other members' lines are this fleet's own. */
  crewId(): string | null;
  /** The players this player has added as friends. */
  friendIds(): string[];
  /** Every player of the fleets this player has most dealings with (the dealings ledger, net/neighbours.ts). */
  nearIds(): string[];
}

/** One fleet as the tab shows it, from your own books or the server's board. */
interface Entry {
  name: string;
  livery: [number, number];
  logo?: string;
  you: boolean;
  /** The game day it ceased trading, or null. */
  gone: number | null;
  v: Partial<Record<MetricKey, number>>;
  /** Net worth by day, newest first, for the sparkline and the chart. */
  hist: number[];
  /** CPU, a player's name, vehicles and towns: the line under the name (the server's board only). */
  sub: string;
  /** A player's id, so the name opens their card and a right-click adds them as a friend (net/friends.ts); none for a CPU firm. */
  pid?: string;
  /** Another player's fleet (from the server's board). */
  human?: boolean;
  /** The Gilded Fleet (every page of the Passport, gold on): a gold name and a Gilded title. */
  gilded?: boolean;
}

/** Net worth by day as a row of block characters, oldest first, scaled between its own low and high. */
function spark(hist: number[]): string {
  const xs = hist.slice(0, 14).reverse();
  if (xs.length < 2) return '';
  const lo = Math.min(...xs), hi = Math.max(...xs);
  return xs.map((v) => BARS[hi > lo ? Math.min(7, Math.floor(((v - lo) / (hi - lo)) * 7.99)) : 3]).join('');
}

/** A metric's value in its own units: dollars, or a plain count. */
const shown = (m: MetricDef, v: number | undefined): string => (v === undefined ? '—' : m.money ? money(v) : v.toLocaleString('en-US'));
/** Is `a` ahead of `b` on this metric. */
const ahead = (m: MetricDef, a: number, b: number): boolean => (m.low ? a < b : a > b);

/** Where an entry stands on a metric among those still trading that have a number for it. */
function placeIn(list: Entry[], e: Entry, m: MetricDef): number {
  const mine = e.v[m.key];
  if (mine === undefined) return 0;
  return 1 + list.filter((o) => o !== e && o.gone === null && o.v[m.key] !== undefined && ahead(m, o.v[m.key]!, mine)).length;
}

export class StandingsTab implements SocialTabBody {
  private scope: Scope = 'met';
  private metric: MetricKey = 'worth';
  private allRanks = false;
  online: StandingsOnline | null = null;
  /** Is this player's own name in gold (game/treats.ts myNameGilded), set by the game. */
  youGilded: () => boolean = () => false;

  constructor(private metrics: FleetMetrics) {}

  private get onlineNow(): boolean { return !!this.online?.active(); }

  opened(): void { if (this.onlineNow) this.online!.ask(); }
  tick(): void { if (this.onlineNow) this.online!.ask(); }

  press(target: HTMLElement): boolean {
    const b = target.closest('[data-scope],[data-metric],[data-allranks]') as HTMLElement | null;
    if (!b) return false;
    const d = b.dataset;
    if (d.scope) { this.scope = d.scope as Scope; this.allRanks = false; if (this.scope === 'world') this.online?.ask(); }
    if (d.metric) this.metric = d.metric as MetricKey;
    if (d.allranks) this.allRanks = !this.allRanks;
    return true;
  }

  /** Every other player's fleet on the server, signed in or not: in every scope online, none in a local game. */
  private playerEntries(): Entry[] {
    if (!this.onlineNow) return [];
    return otherPlayers(this.online!.rows(), this.online!.youId(), this.online!.crewId()).map(rowEntry);
  }

  private youEntry(): Entry {
    const you = this.metrics.you();
    return { name: you.name, livery: you.livery, logo: you.logo, you: true, gone: null, v: you.v, hist: you.hist, sub: '', gilded: this.youGilded() };
  }

  /** Your own books (you and every rival firm met) and, online, every other player's fleet. */
  private metEntries(): Entry[] {
    return [...this.metrics.list().map((b) => ({ name: b.name, livery: b.livery, logo: b.logo, you: b.you, gone: b.gone, v: b.v, hist: b.hist, sub: '', gilded: b.you && this.youGilded() })), ...this.playerEntries()];
  }

  /** Your friends' fleets, or your neighbours', and yours. */
  private friendEntries(near = false): Entry[] {
    const ids = new Set(near ? this.online!.nearIds() : this.online!.friendIds());
    return [...this.playerEntries().filter((e) => e.pid && ids.has(e.pid)), this.youEntry()];
  }

  /** The server's board: every player and every rival somebody is near. Your own line is live from your books. */
  private worldEntries(): Entry[] {
    const me = this.online!.youId(), crew = this.online!.crewId();
    const list: Entry[] = this.online!.rows().filter((r) => r.id !== me && !(crew && r.crew === crew)).map(rowEntry);
    list.push(this.youEntry());
    return list;
  }

  /** The leaders' net worth over the last fortnight, as one line each. */
  private chart(ranked: Entry[]): string {
    const top = ranked.filter((e) => e.gone === null && e.hist.length > 1).slice(0, CHART_TOP);
    const you = ranked.find((e) => e.you);
    if (you && !top.includes(you) && you.hist.length > 1) top.push(you);
    if (top.length < 1) return '';
    const days = Math.min(14, Math.max(...top.map((e) => e.hist.length)));
    if (days < 2) return '';
    const cats = Array.from({ length: days }, (_, i) => (i === days - 1 ? 'now' : `−${days - 1 - i}`));
    const series: Series[] = top.map((e, k) => {
      const h = e.hist.slice(0, days);
      while (h.length < days) h.push(h[h.length - 1]);
      return { label: e.you ? 'You' : e.name, colour: Math.min(8, k + 1), values: h.slice().reverse().map((v) => Math.max(0, v)) };
    });
    return `<div class="sw-chart">${lines(cats, series, 150)}${legend(series)}</div>`;
  }

  html(): { left: string; right: string } {
    const on = this.onlineNow;
    if (!on && this.scope !== 'met') this.scope = 'met';
    const world = this.scope === 'world', near = this.scope === 'neighbours', friends = this.scope === 'friends' || near;
    const list = world ? this.worldEntries() : friends ? this.friendEntries(near) : this.metEntries();
    const met = this.metrics.list().length + (on ? this.playerEntries().length : 0);
    const friendN = on ? this.online!.friendIds().length : 0;
    const nearN = on ? new Set(this.online!.nearIds()).size : 0;
    const chipB = (s: Scope, label: string) => `<button type="button" data-scope="${s}" class="${this.scope === s ? 'on' : ''}">${label}</button>`;
    const scope = on
      ? `<div class="scope">${chipB('met', `Players and firms met · ${met}`)}${chipB('friends', `Friends · ${friendN}`)}${chipB('neighbours', `Neighbours · ${nearN}`)}${chipB('world', `Everyone · ${this.online!.rows().length || '…'}`)}</div>`
      : '';
    const live = list.filter((e) => e.gone === null);
    const you = list.find((e) => e.you)!;
    const others = live.filter((e) => !e.you);
    const gone = list.length - live.length;
    const m = METRICS.find((x) => x.key === this.metric) ?? METRICS[0];
    const players = others.filter((e) => e.human).length, cpu = others.length - players;
    const lead = world
      ? `You are <b>#${placeIn(list, you, METRICS[0])} of ${live.length}</b> by net worth · ${players} other player${players === 1 ? '' : 's'} · ${cpu} CPU firm${cpu === 1 ? '' : 's'}`
      : friends
        ? (players ? `You are <b>#${placeIn(list, you, METRICS[0])} of ${live.length}</b> by net worth among your ${near ? 'neighbours' : 'friends'}` : near ? 'No neighbours yet: the fleets you deal with most join here' : 'No friends yet: right-click a player’s name, or open their card, to add one')
        : on
          ? `You are <b>#${placeIn(list, you, METRICS[0])} of ${live.length}</b> by net worth · ${players} other player${players === 1 ? '' : 's'} · ${cpu} rival firm${cpu === 1 ? '' : 's'} met${gone ? ` · ${gone} ceased trading` : ''}`
          : `You are <b>#${placeIn(list, you, METRICS[0])} of ${live.length}</b> by net worth · ${others.length} rival${others.length === 1 ? '' : 's'} met${gone ? ` · ${gone} ceased trading` : ''}`;

    const rows = METRICS.map((d) => {
      const have = others.filter((e) => e.v[d.key] !== undefined);
      const best = have.length ? have.reduce((a, b) => (ahead(d, b.v[d.key]!, a.v[d.key]!) ? b : a)) : null;
      const p = placeIn(list, you, d);
      // everyone level (all nought on the first day, say): no place to speak of
      const level = have.every((e) => e.v[d.key] === you.v[d.key]);
      const cls = `${d.key === m.key ? 'on' : ''}${p === 1 && have.length && !level ? ' top' : ''}`;
      return `<tr class="${cls}" data-metric="${d.key}" title="${esc(d.hint)}"><td>${esc(d.label)}</td><td class="n">${shown(d, you.v[d.key])}</td>
        <td class="p">${!have.length ? '—' : level ? '=' : `#${p}`}</td>
        <td class="n best">${best ? `${chip(best.livery, best.logo)}${shown(d, best.v[d.key])}` : '—'}</td></tr>`;
    }).join('');

    // the ranking: best first, then those with no number for it, ceased firms last; bars to scale with the largest shown
    const ranked = [...list].sort((a, b) => Number(a.gone !== null) - Number(b.gone !== null)
      || Number(a.v[m.key] === undefined) - Number(b.v[m.key] === undefined)
      || (m.low ? (a.v[m.key] ?? 0) - (b.v[m.key] ?? 0) : (b.v[m.key] ?? 0) - (a.v[m.key] ?? 0)));
    const shownRanks = this.allRanks ? ranked : ranked.filter((e, k) => k < RANK_TOP || e.you);
    const hidden = ranked.length - shownRanks.length;
    const top = Math.max(1, ...shownRanks.map((e) => Math.abs(e.v[m.key] ?? 0)));
    const bars = shownRanks.map((e) => {
      const v = e.v[m.key];
      const w = v === undefined ? 0 : Math.max(v !== 0 ? 1.5 : 0, (Math.abs(v) / top) * 100);
      const note = e.gone !== null ? `ceased day ${e.gone + 1}` : m.key === 'worth' ? spark(e.hist) : '';
      const place = e.gone === null && v !== undefined ? placeIn(list, e, m) : '–';
      return `<li class="${e.you ? 'you' : ''}${e.gone !== null ? ' gone' : ''}">
        <span class="nm"><i>${place}</i>${chip(e.livery, e.logo)}<b${e.pid ? ` data-pid="${esc(e.pid)}"` : ''}${e.gilded ? ' class="gilded"' : ''}>${esc(e.name)}</b>${e.gilded ? ' <small class="gilded-title" title="Every page of the Passport filled">👑 Gilded</small>' : ''}${e.you ? ' <small>you</small>' : ''}${e.sub ? `<span class="sub">${e.sub}</span>` : ''}</span>
        <em class="${(v ?? 0) < 0 ? 'neg' : ''}">${shown(m, v)}</em>
        <span class="bar"><i style="width:${w.toFixed(1)}%;background:${css(e.livery[0])}"></i></span>
        ${note ? `<small class="note">${esc(note)}</small>` : ''}</li>`;
    }).join('');

    const foot = world
      ? '<p class="foot">Rival firms are counted while somebody is near their home county. A fleet’s other numbers show once its game has saved.</p>'
      : on && players ? '<p class="foot">Every player’s fleet is here, signed in or not, as their game last saved it. Click a fleet’s name for its card.</p>'
        : others.length ? '' : '<p class="foot">No rival firms met yet. Their numbers join the table the first time you see their colours.</p>';
    const left = `${scope}<div class="lead">${lead}</div>
      <table class="metrics"><thead><tr><th>Metric</th><th class="n">You</th><th class="p">Rank</th><th class="n">${world ? 'Best other' : near ? 'Best neighbour' : friends ? 'Best friend' : 'Best rival'}</th></tr></thead><tbody>${rows}</tbody></table>
      <p class="foot">Click a metric to rank every fleet by it.</p>`;
    const right = `<div class="rankhead"><b>${esc(m.label)}</b><small>${esc(m.hint)}${m.key === 'worth' ? ' · under each bar, the last fourteen days' : ''}</small></div>
      ${m.key === 'worth' ? this.chart(ranked) : ''}
      <ul class="ranking">${bars}</ul>
      ${hidden || this.allRanks ? `<button type="button" class="link allranks" data-allranks="1">${this.allRanks ? 'Show the top ten' : `Show all ${ranked.length} fleets`}</button>` : ''}
      ${foot}`;
    return { left, right };
  }
}
