import { hex, type RGB } from '../../world/biomes';
import { DIRS, STEP, idx, inB, waterDepth, type Building, type ThemeKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, TAU, WARM_GLOW, WHITE, cur, pick, styleWall, win, type Draw, type Kit, type P3 } from './kit';
import { archPanel, archWin, around, hull, spandrel } from './worldStylesB';

/**
 * The Adriatic old town's own (Rovinj, with a nod each to Dubrovnik, Split, Hvar and Korčula), swapped in or put
 * up by the adriatic town style (world/towns.ts STYLE_SWAPS and its `adriatic` layout). Each stands on its lot
 * centred on the origin, its front to +z, in its own fixed palette of white Istrian stone and terracotta.
 *
 * - **St Euphemia** (church, cathedral): the baroque church on the top of the hill, its great Venetian campanile
 *   behind it, the copper saint turning with the wind on the spire's point.
 * - **The city gate** (memorial, triumphal arch): a stretch of Dubrovnik's walls, battered and crenellated, the
 *   gate tower over its stone bridge with the patron saint in his niche, and a round fortress tower at one end.
 * - **The loggia** (clock tower, observation tower): Hvar's and Korčula's open loggia, three arches under a
 *   tiled roof, and the slim clock tower beside it with its bell under a little bronze dome.
 * - **The riva** (marina): the stone waterfront, its quay edge and the steps down into the sea, bollards, lamps,
 *   benches and palms, and the painted wooden fishing boats (batane) tied up below it.
 * - **The peristyle** (civic square): the court of Diocletian's palace at Split, its two arcades on granite
 *   columns, the temple front of the vestibule and its open dome, the cathedral's bell tower and a sphinx.
 *
 * Not kinds of their own: the old town's tall narrow houses (`adriaticHouse`, townMesh's townhouse in this
 * style) and the washing hung out across their fronts (kit.ts styleDress, StyleSpec.laundry).
 */

const ISTRIA = hex(0xf0ebdc), ISTRIA_SHADE = hex(0xd8d0bc), ISTRIA_DARK = hex(0xbcb29c), LIMESTONE = hex(0xe2d6bc);
const TERRACOTTA = hex(0xb85a36), TERRA_DARK = hex(0x9a4a2c), SHADOW = hex(0x3a302c), GRANITE = hex(0x8a6a66);
const COPPER = hex(0x5e9e86), BRONZE = hex(0x8a6a2a), IRON = hex(0x2a2e30), SEA_STONE = hex(0xc8bea6), MOSS_STONE = hex(0xa8a48c);
const PAVING = hex(0xe6dfcf), PALM_TRUNK = hex(0x8a6a4a), PALM_LEAF = hex(0x4f8a3e), BENCH = hex(0x6a4a30), ROPE = hex(0xd8c8a0);
const FLOOD: Sched = [18, 25.5, 1.3], LAMP: Sched = [17.5, 30, 1.8], EVENING: Sched = [18, 23.5, 1.4];
/** The colours a batana is painted: its hull, then the band under its gunwale. */
const BATANA: readonly [number, number][] = [[0x2f5f9a, 0xf2ece0], [0xc8402e, 0xf2ece0], [0x2f7a4a, 0xe8c050], [0xf2ece0, 0x2f5f9a], [0xe8b040, 0x2f4a6a], [0x4a8ac0, 0xc8402e]];

// ---- the old town's houses ----------------------------------------------------------------------

/**
 * Two narrow houses to the lot, shoulder to shoulder, each its own colour and its own height: a low hipped
 * roof of terracotta, one green-shuttered window a floor, a stone-framed door, now and then a little iron
 * balcony or a pot of geraniums on the sill, and a chimney. What packs a hill of Rovinj tight.
 */
export const adriaticHouse: Draw = (k, _W, _D, b, r) => {
  const d = 0.8, z = -0.04, front = z + d / 2, floors = Math.max(2, b.floors);
  for (const side of [-1, 1]) {
    const w = 0.4, x = side * 0.21;
    const f = Math.max(2, Math.min(6, floors + (r() < 0.45 ? (r() < 0.5 ? 1 : -1) : 0)));
    const wall = styleWall(r), h = f * FLOOR + 0.04;
    k.box(x, 0, z, w, h, d, wall);
    // a plinth of bare stone, and quoins up the outer corner on the better houses
    k.box(x, 0, front + 0.004, w, 0.06, 0.012, ISTRIA_SHADE);
    if (r() < 0.4) k.detail(() => { for (let y = 0.06; y < h - 0.06; y += 0.12) k.box(x + side * (w / 2 - 0.02), y, front + 0.006, 0.05, 0.05, 0.01, ISTRIA); });
    // the roof: a low hip with a little eave, and a cornice under it in stone
    k.box(x, h - 0.02, z, w + 0.02, 0.02, d + 0.02, ISTRIA);
    k.hip(x, h, z, w + 0.06, 0.13, d + 0.06, pick(r, cur.roofs));
    if (r() < 0.6) k.box(x - side * 0.08, h + 0.02, z - 0.18, 0.06, 0.16, 0.06, hex(0xe0d4bc));
    // the door, in a stone frame, and a window on every floor over it
    const door = pick(r, cur.doors ?? [0x2f5a3a]);
    k.box(x, 0, front + 0.006, 0.12, 0.2, 0.01, ISTRIA);
    k.box(x, 0, front + 0.012, 0.09, 0.18, 0.01, door);
    for (let i = 1; i < f; i++) {
      const y = 0.07 + i * FLOOR;
      win(k, b, r, x, y, front, 0.11, 0.14, 1);
      if (i === 1 && r() < 0.3) {
        // a little iron balcony on a stone slab
        k.box(x, y - 0.015, front + 0.04, 0.2, 0.015, 0.08, ISTRIA);
        k.box(x, y, front + 0.078, 0.2, 0.05, 0.004, IRON);
      } else if (r() < 0.25) {
        // geraniums on the sill
        k.box(x, y - 0.01, front + 0.03, 0.12, 0.025, 0.04, TERRA_DARK);
        k.box(x, y + 0.015, front + 0.03, 0.11, 0.02, 0.035, hex(r() < 0.5 ? 0xd8323a : 0xe85a8a));
      }
    }
    // a small window to the side street on the end house, and one at the back for the evening
    win(k, b, r, x + side * (w / 2), 0.07 + FLOOR, z - 0.1, 0.1, 0.12, side > 0 ? 0 : 2);
    win(k, b, r, x, 0.07 + (f - 1) * FLOOR, z - d / 2, 0.1, 0.12, 3);
  }
};

// ---- St Euphemia --------------------------------------------------------------------------------

/** A copper saint on a ball at (x, y, z), her arm out like a vane. */
function saint(k: Kit, x: number, y: number, z: number, s: number): void {
  k.cyl(x, y, z, 0.03 * s, 0.03 * s, COPPER, 6);
  k.cone(x, y + 0.03 * s, z, 0.04 * s, 0.12 * s, COPPER, 6);
  k.box(x, y + 0.13 * s, z, 0.022 * s, 0.03 * s, 0.022 * s, COPPER);
  k.bar([x, y + 0.11 * s, z], [x + 0.08 * s, y + 0.15 * s, z + 0.02 * s], 0.008 * s, COPPER);
}

/**
 * The Venetian campanile of Rovinj: a square stone shaft with pilaster strips and slit windows, the belfry of
 * arches on every face with the bells lit behind them, an octagonal lantern, a tall stone spire and the saint.
 */
function campanile(k: Kit, x: number, z: number, sw: number, shaft: number): void {
  k.box(x, 0, z, sw + 0.06, 0.1, sw + 0.06, ISTRIA_SHADE);
  k.box(x, 0.1, z, sw, shaft - 0.1, sw, LIMESTONE);
  around(k, x, z, sw, sw, (x0, zf, _span, f) => {
    for (const o of [-1, 1]) k.box(x0 + o * sw * 0.42, 0.1, zf + 0.004, sw * 0.12, shaft - 0.1, 0.008, ISTRIA);
    for (let i = 0; i < 4; i++) k.box(x0, 0.45 + i * shaft * 0.2 + (f % 2) * 0.1, zf + 0.008, 0.025, 0.08, 0.006, SHADOW);
    k.box(x0, shaft * 0.5, zf + 0.004, sw * 0.86, 0.02, 0.01, ISTRIA);
  });
  // the belfry: two arches a face on stone piers, the bells behind
  const by = shaft, bh = 0.36;
  k.box(x, by, z, sw + 0.08, 0.05, sw + 0.08, ISTRIA);
  k.glowBox(x, by + 0.05, z, sw - 0.1, bh - 0.04, sw - 0.1, SHADOW, FLOOD, WARM_GLOW);
  k.box(x, by + 0.08, z, 0.1, 0.13, 0.1, BRONZE);
  around(k, x, z, sw, sw, (x0, zf, span) => {
    const n = 2, bay = (span - 0.06) / n, xs = x0 - span / 2 + 0.03;
    for (let i = 0; i <= n; i++) k.box(xs + i * bay, by + 0.05, zf - 0.03, i % n ? 0.035 : 0.06, bh * 0.55, i % n ? 0.035 : 0.06, ISTRIA);
    for (let i = 0; i < n; i++) spandrel(k, xs + i * bay, xs + (i + 1) * bay, by + 0.05 + bh * 0.55, by + 0.05 + bh, zf - 0.015, ISTRIA, false);
  });
  k.box(x, by + bh + 0.05, z, sw + 0.1, 0.05, sw + 0.1, ISTRIA);
  // a balustrade round the top, the octagonal lantern and the spire
  const ty = by + bh + 0.1;
  for (const [dx, dz] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) k.box(x + (dx * sw) / 2, ty, z + (dz * sw) / 2, dx ? 0.02 : sw, 0.06, dz ? 0.02 : sw, ISTRIA);
  k.cyl(x, ty, z, sw * 0.34, 0.2, LIMESTONE, 8);
  k.cyl(x, ty + 0.2, z, sw * 0.38, 0.03, ISTRIA, 8);
  k.cone(x, ty + 0.23, z, sw * 0.34, 0.62, ISTRIA_SHADE, 8);
  saint(k, x, ty + 0.85, z, 1);
}

const stEuphemia: Draw = (k, W, D, b, r) => {
  // the church across the front of the lot, the campanile behind it at one corner
  const nw = Math.min(W - 0.3, 1.2), nd = Math.min(D - 0.9, 1.7), fz = D / 2 - 0.35, cz = fz - nd / 2, H = 0.78;
  // the paved terrace in front and the steps up to it
  k.box(0, 0, D / 2 - 0.18, nw + 0.3, 0.05, 0.34, PAVING);
  for (let i = 0; i < 3; i++) k.box(0, 0, D / 2 - 0.03 - i * 0.04, nw * 0.6, 0.02 + i * 0.015, 0.04, ISTRIA_SHADE);
  // the nave and its lower aisles
  k.box(0, 0, cz, nw * 0.5, H, nd, ISTRIA);
  for (const s of [-1, 1]) {
    k.box(s * nw * 0.37, 0, cz, nw * 0.26, H * 0.62, nd, ISTRIA_SHADE);
    k.hip(s * nw * 0.37, H * 0.62, cz, nw * 0.28, 0.08, nd + 0.02, TERRACOTTA);
  }
  k.gable(0, H, cz, nw * 0.52, 0.22, nd + 0.02, TERRACOTTA, ISTRIA, true);
  // the arched windows down both sides of the aisles and of the clerestory
  around(k, 0, cz, nw, nd, (x0, zf, span) => {
    for (let i = 0; i < 4; i++) archWin(k, x0 - span / 2 + (span * (i + 0.5)) / 4, 0.14, zf, 0.07, 0.17, ISTRIA, false, EVENING);
  }, [1, 3]);
  // the baroque front: a tall middle under a pediment, scrolls down to the aisles, the rose window and the door
  const z1 = fz + 0.02;
  k.box(0, 0, z1, nw * 0.52, H + 0.06, 0.05, ISTRIA);
  k.gable(0, H + 0.06, z1, nw * 0.56, 0.2, 0.06, ISTRIA, ISTRIA, true);
  for (const s of [-1, 1]) {
    k.box(s * nw * 0.37, 0, z1, nw * 0.26, H * 0.62, 0.04, ISTRIA);
    // the scroll: a quarter-round wedge leaning in from the aisle's top to the middle
    const I: P3 = [s * nw * 0.3, H * 0.7, z1];
    for (let j = 0; j < 4; j++) {
      const a0 = (j / 4) * Math.PI / 2, a1 = ((j + 1) / 4) * Math.PI / 2, rr = nw * 0.24;
      const xa = s * (nw * 0.26 + Math.cos(a0) * rr), ya = H * 0.62 + Math.sin(a0) * rr * 0.6;
      const xb = s * (nw * 0.26 + Math.cos(a1) * rr), yb = H * 0.62 + Math.sin(a1) * rr * 0.6;
      k.quad([s * nw * 0.26, H * 0.62, z1 + 0.025], [xa, ya, z1 + 0.025], [xb, yb, z1 + 0.025], [s * nw * 0.26, yb, z1 + 0.025], ISTRIA, I);
    }
    for (const px of [0.26, 0.5]) k.box(s * nw * px, 0, z1 + 0.03, 0.04, H * 0.6, 0.02, ISTRIA_SHADE);
    k.box(s * nw * 0.37, H * 0.62 + 0.01, z1, 0.03, 0.08, 0.03, ISTRIA);
  }
  k.face(0, H * 0.72, z1 + 0.03, 0.09, ISTRIA_SHADE, 12);
  k.face(0, H * 0.72, z1 + 0.034, 0.07, hex(0x6a4a7a), 10);
  k.glowBox(0, H * 0.72 - 0.05, z1 + 0.02, 0.1, 0.1, 0.01, hex(0x6a4a7a), EVENING, WARM_GLOW);
  archPanel(k, 0, 0, z1 + 0.03, 0.16, 0.3, ISTRIA_SHADE);
  archPanel(k, 0, 0, z1 + 0.034, 0.12, 0.26, hex(0x4a3222));
  k.glowBox(0, 0.3, z1 + 0.05, 0.03, 0.03, 0.03, hex(0xf6e6b8), LAMP, WARM_GLOW);
  saint(k, 0, H + 0.26, z1, 0.6);
  // the campanile behind, at one corner of the church
  const side = (b.seed & 1) ? 1 : -1, sw = 0.36;
  campanile(k, side * Math.min(nw / 2 - 0.05, W / 2 - sw / 2 - 0.08), Math.max(-D / 2 + sw / 2 + 0.08, cz - nd / 2 - 0.05), sw, 2.1);
  // a cypress or two in the churchyard
  for (const s of [-1, 1]) if (r() < 0.7) k.cone(s * (W / 2 - 0.16), 0, D / 2 - 0.25, 0.06, 0.5, hex(0x2f5a36), 6);
};

// ---- the city gate ------------------------------------------------------------------------------

/** Merlons along a wall top from x0 to x1 at y, on the face at z. */
function merlons(k: Kit, x0: number, x1: number, y: number, z: number, col: RGB): void {
  for (let x = x0 + 0.05; x < x1 - 0.03; x += 0.11) k.box(x, y, z, 0.06, 0.07, 0.06, col);
}

const pileGate: Draw = (k, W, D, b) => {
  const wz = -D / 2 + 0.45, wd = 0.42, H = 0.82, x0 = -W / 2 + 0.05, x1 = W / 2 - 0.05;
  const round = (b.seed & 2) ? 1 : -1, tr = 0.5, tx = round * (W / 2 - tr - 0.02);
  // the wall: a battered foot, the curtain, a walk along the top behind its merlons
  k.box(0, 0, wz, x1 - x0, 0.18, wd + 0.08, ISTRIA_DARK);
  k.box(0, 0.18, wz, x1 - x0, H - 0.18, wd, LIMESTONE, ISTRIA_SHADE);
  merlons(k, x0, x1, H, wz + wd / 2 - 0.03, LIMESTONE);
  merlons(k, x0, x1, H, wz - wd / 2 + 0.03, LIMESTONE);
  k.detail(() => { for (let y = 0.3; y < H - 0.05; y += 0.16) k.box(0, y, wz + wd / 2 + 0.002, x1 - x0, 0.008, 0.006, ISTRIA_DARK); });
  // the round fortress tower at one end, a smaller turret on top of it (Minčeta)
  k.cyl(tx, 0, wz, tr, 0.2, ISTRIA_DARK, 14);
  k.cyl(tx, 0.2, wz, tr * 0.94, H + 0.3, LIMESTONE, 14, ISTRIA_SHADE);
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * TAU;
    k.box(tx + Math.cos(a) * tr * 0.9, H + 0.5, wz + Math.sin(a) * tr * 0.9, 0.07, 0.08, 0.07, LIMESTONE);
  }
  k.cyl(tx, H + 0.5, wz, tr * 0.5, 0.36, LIMESTONE, 12);
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    k.box(tx + Math.cos(a) * tr * 0.47, H + 0.86, wz + Math.sin(a) * tr * 0.47, 0.05, 0.06, 0.05, LIMESTONE);
  }
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU + 0.3;
    k.box(tx + Math.cos(a) * tr * 0.95, 0.5 + (i % 2) * 0.3, wz + Math.sin(a) * tr * 0.95, 0.03, 0.08, 0.03, SHADOW);
  }
  // the gate tower, standing out of the wall over the road side
  const gx = -round * W * 0.12, gw = 0.62, gd = wd + 0.3, gz = wz + 0.12, GH = H + 0.32;
  k.box(gx, 0, gz, gw, GH, gd, LIMESTONE, ISTRIA_SHADE);
  merlons(k, gx - gw / 2, gx + gw / 2, GH, gz + gd / 2 - 0.03, LIMESTONE);
  const gf = gz + gd / 2;
  archPanel(k, gx, 0, gf + 0.004, 0.3, 0.42, ISTRIA);
  archPanel(k, gx, 0, gf + 0.008, 0.24, 0.38, SHADOW);
  k.glowBox(gx, 0.36, gf + 0.02, 0.04, 0.04, 0.04, hex(0xf6e6b8), LAMP, WARM_GLOW);
  // St Blaise in his niche over the gate, holding the city
  archPanel(k, gx, 0.55, gf + 0.004, 0.12, 0.2, SHADOW);
  k.box(gx, 0.57, gf + 0.02, 0.05, 0.12, 0.03, ISTRIA);
  k.box(gx, 0.69, gf + 0.02, 0.035, 0.035, 0.03, ISTRIA);
  // the stone bridge over the dry moat, and the moat along the foot of the wall
  const mz = gf + 0.18;
  k.box(0, 0.002, mz, x1 - x0 - (tr + 0.1), 0.004, 0.2, hex(0x6a7a52));
  k.box(gx, 0, mz, 0.34, 0.06, 0.24, ISTRIA_SHADE);
  for (const s of [-1, 1]) k.box(gx + s * 0.16, 0.06, mz, 0.03, 0.05, 0.24, ISTRIA_SHADE);
  // the flag of the old republic over the gate
  k.bar([gx + gw / 2 - 0.06, GH, gz], [gx + gw / 2 - 0.06, GH + 0.4, gz], 0.008, IRON);
  k.box(gx + gw / 2 + 0.03, GH + 0.28, gz, 0.16, 0.1, 0.008, WHITE);
  k.box(gx + gw / 2 + 0.03, GH + 0.31, gz + 0.006, 0.05, 0.05, 0.004, hex(0xc8302a));
};

// ---- the loggia and clock tower -----------------------------------------------------------------

const clockLoggia: Draw = (k, W, D, b, r) => {
  const tSide = (b.seed & 1) ? 1 : -1;
  const lw = W - 0.62, ld = D - 0.75, lx = -tSide * 0.24, lz = 0.12, H = 0.42;
  // the stone platform and its step
  k.box(lx, 0, lz, lw + 0.1, 0.05, ld + 0.1, ISTRIA_SHADE);
  k.box(lx, 0, lz + ld / 2 + 0.08, lw, 0.025, 0.06, ISTRIA_SHADE);
  // the back wall, shadowed inside, and the arcade on the front and the open side
  k.box(lx, 0.05, lz - ld / 2 + 0.03, lw, H, 0.06, ISTRIA);
  k.box(lx, 0.05, lz, lw - 0.1, 0.01, ld - 0.1, SHADOW);
  around(k, lx, lz, lw, ld, (x0, zf, span, f) => {
    if (f === 2) return;
    const n = f === 0 ? 3 : 2, bay = span / n, xs = x0 - span / 2, sp = 0.05 + H * 0.6;
    for (let i = 0; i <= n; i++) k.cyl(xs + i * bay, 0.05, zf - 0.04, 0.024, sp - 0.05, ISTRIA, 6);
    for (let i = 0; i < n; i++) spandrel(k, xs + i * bay, xs + (i + 1) * bay, sp, 0.05 + H, zf - 0.03, ISTRIA, false);
    k.box(x0, 0.05 + H, zf - 0.04, span + 0.04, 0.035, 0.06, ISTRIA_SHADE);
  });
  k.hip(lx, 0.05 + H + 0.035, lz, lw + 0.12, 0.18, ld + 0.12, TERRACOTTA);
  // a lamp under the arcade, and a café table or two in front of it
  k.glowBox(lx, H - 0.04, lz, 0.05, 0.05, 0.05, hex(0xf6e6b8), LAMP, WARM_GLOW);
  for (const o of [-0.3, 0.3]) {
    const tx = lx + o, tz = D / 2 - 0.16;
    k.cyl(tx, 0, tz, 0.05, 0.08, WHITE, 6);
    k.box(tx, 0.12, tz, 0.012, 0.1, 0.012, IRON);
    k.cone(tx, 0.2, tz, 0.13, 0.06, r() < 0.5 ? hex(0xf2ece0) : hex(0xc8402e), 8);
  }
  // the clock tower beside it
  const tx = tSide * (W / 2 - 0.22), tz = -0.05, sw = 0.28, sh = 1.55;
  k.box(tx, 0, tz, sw + 0.04, 0.08, sw + 0.04, ISTRIA_SHADE);
  k.box(tx, 0.08, tz, sw, sh - 0.08, sw, LIMESTONE);
  around(k, tx, tz, sw, sw, (x0, zf, _span, f) => {
    // a slit or two up the stair, and the clock face near the top on every side
    if (f % 2) k.box(x0, 0.6, zf + 0.006, 0.02, 0.08, 0.006, SHADOW);
    k.box(x0, sh * 0.52, zf + 0.004, sw - 0.02, 0.016, 0.008, ISTRIA);
    k.face(x0, sh - 0.2, zf + 0.008, 0.09, ISTRIA_DARK, 12);
    k.face(x0, sh - 0.2, zf + 0.012, 0.075, WHITE, 12);
    k.glowBox(x0, sh - 0.26, zf + 0.004, 0.1, 0.12, 0.006, WHITE, LAMP, hex(0xfff2d0));
    k.bar([x0, sh - 0.2, zf + 0.018], [x0, sh - 0.15, zf + 0.018], 0.006, IRON);
    k.bar([x0, sh - 0.2, zf + 0.018], [x0 + 0.04, sh - 0.2, zf + 0.018], 0.006, IRON);
  });
  k.box(tx, sh, tz, sw + 0.06, 0.035, sw + 0.06, ISTRIA);
  // the bell in its open frame, under a little bronze dome
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(tx + sx * (sw / 2 - 0.03), sh + 0.035, tz + sz * (sw / 2 - 0.03), 0.04, 0.2, 0.04, ISTRIA);
  k.cone(tx, sh + 0.08, tz, 0.07, 0.1, BRONZE, 8);
  k.box(tx, sh + 0.235, tz, sw + 0.02, 0.03, sw + 0.02, ISTRIA);
  k.dome(tx, sh + 0.265, tz, sw * 0.42, COPPER, 10, 3);
  k.cyl(tx, sh + 0.265 + sw * 0.42, tz, 0.008, 0.1, IRON, 4);
};

// ---- the riva ------------------------------------------------------------------------------------

/**
 * Which side of the lot the sea lies on, as a face (0 front +z, 1 +x, 2 back, 3 -x, around()'s numbering),
 * and the sea's surface in the lot's frame. Off the water (the gallery) it is behind, a step down.
 */
function seaSide(k: Kit, b: Building, W: number, D: number): { face: number; y: number } {
  const w = k.world, yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]), c = Math.cos(yaw), s = Math.sin(yaw);
  const ox = b.x + b.w / 2, oz = b.z + b.d / 2;
  let best = 2, most = 0, level = 0;
  if (w?.water) {
    for (let f = 0; f < 4; f++) {
      // probe a row of points just past the side, out to two tiles
      const a = (f * Math.PI) / 2, nx = Math.round(Math.sin(a)), nz = Math.round(Math.cos(a));
      const along = f % 2 ? D : W, out = f % 2 ? W / 2 : D / 2;
      let n = 0, lv = 0;
      for (let u = -along / 2 + 0.5; u < along / 2; u += 1) {
        for (const o of [0.5, 1.5]) {
          const lx = nx * (out + o) + nz * u, lz = nz * (out + o) - nx * u;
          const tx = Math.floor(ox + lx * c + lz * s), tz = Math.floor(oz - lx * s + lz * c);
          if (!inB(tx, tz)) continue;
          const i = idx(tx, tz);
          if (waterDepth(w, i) > 0) { n++; lv = w.water[i]; }
        }
      }
      if (n > most) { most = n; best = f; level = lv; }
    }
  }
  const y = most ? Math.min(-0.15, (level - b.level) * STEP) : -STEP;
  return { face: best, y };
}

/** A batana: a little flat-bottomed wooden fishing boat lying along x at the water's surface y, a mast laid along it. */
function batana(k: Kit, x: number, y: number, z: number, r: Rng): void {
  const [h, band] = BATANA[Math.floor(r() * BATANA.length)];
  hull(k, x, y - 0.02, z, 0.42, 0.14, 0.05, 0.03, hex(h), hex(0x8a6a48), 6);
  k.box(x, y + 0.03, z, 0.34, 0.012, 0.142, hex(band));
  k.box(x - 0.05, y + 0.035, z, 0.04, 0.02, 0.1, hex(0x8a6a48));
  if (r() < 0.6) k.bar([x - 0.16, y + 0.06, z + 0.02], [x + 0.2, y + 0.07, z + 0.02], 0.006, hex(0x9a7a50));
  if (r() < 0.5) k.box(x + 0.08, y + 0.04, z - 0.02, 0.06, 0.03, 0.05, hex(0xc8a050));
}

/** A palm on the promenade at (x, z): a leaning trunk and a crown of drooping fronds. */
function palm(k: Kit, x: number, z: number, h: number, r: Rng): void {
  const lean = (r() - 0.5) * 0.08, top: P3 = [x + lean, h, z];
  k.bar([x, 0, z], top, 0.025, PALM_TRUNK);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU + r(), ex = x + lean + Math.cos(a) * 0.2, ez = z + Math.sin(a) * 0.2;
    k.bar(top, [ex, h - 0.06, ez], 0.02, PALM_LEAF);
  }
}

const riva: Draw = (k, W, D, b, r) => {
  const { face, y: sea } = seaSide(k, b, W, D);
  // draw in a frame turned so the sea lies past local +z
  const a = (face * Math.PI) / 2, L = face % 2 ? D : W, Dp = face % 2 ? W : D;
  k.turned(a, () => {
    const qz = Dp / 2;
    // the promenade's stone and its kerb of big white blocks along the edge
    k.box(0, 0, 0, L - 0.04, 0.025, Dp - 0.04, PAVING);
    k.box(0, 0.025, qz - 0.06, L - 0.04, 0.03, 0.12, ISTRIA);
    // the quay wall dropping to the sea past the edge, weed-dark at the waterline
    k.box(0, sea, qz + 0.02, L - 0.04, -sea + 0.02, 0.04, SEA_STONE);
    k.box(0, sea - 0.02, qz + 0.045, L - 0.04, 0.06, 0.01, MOSS_STONE);
    // the steps down into the sea, set into the quay at one end
    const sx = -L / 2 + 0.4 + r() * 0.3, n = Math.max(3, Math.round(-sea / 0.07));
    for (let i = 0; i < n; i++) {
      const t = i / n;
      k.box(sx, sea - 0.02, qz + 0.06 + t * 0.32, 0.36, 0.02 - sea * (1 - t), 0.32 / n + 0.005, i % 2 ? ISTRIA : ISTRIA_SHADE);
    }
    // bollards and the boats tied up to them, their lines slack in the water
    const boats = Math.max(2, Math.round(L / 0.6));
    for (let i = 0; i < boats; i++) {
      const bx = -L / 2 + 0.95 + ((L - 1.2) * i) / Math.max(1, boats - 1);
      if (Math.abs(bx - sx) < 0.3) continue;
      k.cyl(bx, 0.025, qz - 0.08, 0.025, 0.06, IRON, 6);
      k.box(bx, 0.085, qz - 0.08, 0.06, 0.012, 0.06, IRON);
      if (r() < 0.85) {
        const bz = qz + 0.22 + r() * 0.12;
        batana(k, bx + (r() - 0.5) * 0.1, sea, bz, r);
        k.bar([bx, 0.07, qz - 0.08], [bx - 0.18, sea + 0.05, bz], 0.004, ROPE);
      }
    }
    // lamps and benches along the walk, and two palms
    for (const o of [-0.3, 0.3]) {
      const lx = o * L;
      k.cyl(lx, 0.025, qz - 0.26, 0.012, 0.36, IRON, 5);
      k.glowBox(lx, 0.38, qz - 0.26, 0.05, 0.06, 0.05, hex(0xf6e6b8), LAMP, WARM_GLOW);
    }
    for (const o of [-0.12, 0.42]) {
      const bx = o * L;
      k.box(bx, 0.025, qz - 0.4, 0.26, 0.05, 0.06, BENCH);
      k.box(bx, 0.075, qz - 0.43, 0.26, 0.05, 0.012, BENCH);
    }
    palm(k, -L * 0.42, -Dp / 2 + 0.3, 0.55, r);
    palm(k, L * 0.15, -Dp / 2 + 0.28, 0.6, r);
    // a fish stall under a striped awning, and nets drying over a crate
    const fx = L / 2 - 0.35, fz = -Dp / 2 + 0.32;
    k.box(fx, 0.025, fz, 0.32, 0.14, 0.18, hex(0xd8d0c0));
    k.box(fx, 0.165, fz, 0.32, 0.01, 0.18, hex(0x9ab8c8));
    for (let i = 0; i < 4; i++) k.box(fx - 0.12 + i * 0.08, 0.3, fz + 0.02, 0.08, 0.012, 0.26, i % 2 ? WHITE : hex(0x2f5f9a));
    for (const s of [-1, 1]) k.box(fx + s * 0.15, 0.025, fz + 0.12, 0.012, 0.28, 0.012, IRON);
    k.box(-L * 0.18, 0.025, -Dp / 2 + 0.25, 0.14, 0.08, 0.1, hex(0x8a6a48));
    k.box(-L * 0.18, 0.105, -Dp / 2 + 0.25, 0.18, 0.02, 0.14, hex(0x6a7a5a));
  });
};

// ---- the peristyle at Split ---------------------------------------------------------------------

/** A granite column on a white base with a Corinthian capital. */
function column(k: Kit, x: number, y: number, z: number, h: number): void {
  k.box(x, y, z, 0.07, 0.03, 0.07, ISTRIA);
  k.cyl(x, y + 0.03, z, 0.026, h - 0.08, GRANITE, 6);
  k.cyl(x, y + h - 0.05, z, 0.034, 0.05, ISTRIA, 6, ISTRIA, 0.034);
}

/**
 * A run of round arches along z in the plane x, from z0 to z1 in n bays, springing at ys and closed by a beam at yt,
 * facing +x (dir 1) or -x (dir -1): the stone over each arch, with the opening left under it.
 */
function arcadeZ(k: Kit, x: number, z0: number, z1: number, n: number, ys: number, yt: number, dir: 1 | -1, col: RGB): void {
  const bay = (z1 - z0) / n, seg = 4;
  for (let i = 0; i < n; i++) {
    const za = z0 + i * bay, zm = za + bay / 2, rz = bay / 2, ry = (yt - ys) * 0.88, I: P3 = [x - dir * 0.2, ys, zm];
    for (let j = 0; j < seg; j++) {
      const a0 = (j / seg) * Math.PI, a1 = ((j + 1) / seg) * Math.PI;
      const p0z = zm - Math.cos(a0) * rz, p0y = ys + Math.sin(a0) * ry, p1z = zm - Math.cos(a1) * rz, p1y = ys + Math.sin(a1) * ry;
      k.quad([x, p0y, p0z], [x, p1y, p1z], [x, yt, p1z], [x, yt, p0z], col, I);
    }
  }
}

const peristyle: Draw = (k, W, D, b, r) => {
  const court = 0.06, cx = 0.6, z0 = -D / 2 + 0.55, z1 = D / 2 - 0.12, H = 0.6, side = (b.seed & 1) ? 1 : -1;
  // the court, a step down between the arcades, paved in worn white stone with the old drain down its middle
  k.box(0, 0, 0, W - 0.06, court, D - 0.06, ISTRIA_SHADE);
  k.box(0, court, (z0 + z1) / 2, cx * 2 - 0.1, 0.004, z1 - z0, PAVING);
  k.box(0, court + 0.004, (z0 + z1) / 2 + 0.2, 0.04, 0.003, z1 - z0 - 0.6, ISTRIA_DARK);
  for (const s of [-1, 1] as const) {
    // the arcade: granite columns, the arches over them, the beam, and the wall of the palace standing on it
    const ax = s * cx, n = 5, a0 = z0 + 0.15, a1 = z1 - 0.15, sp = court + H * 0.62;
    for (let i = 0; i <= n; i++) column(k, ax, court, a0 + ((a1 - a0) * i) / n, H * 0.62);
    arcadeZ(k, ax - s * 0.005, a0, a1, n, sp, court + H, s === 1 ? -1 : 1, ISTRIA);
    k.box(ax + s * 0.04, court + H, (a0 + a1) / 2, 0.14, 0.06, a1 - a0 + 0.08, ISTRIA);
    k.box(ax + s * 0.1, court, (a0 + a1) / 2, 0.08, H, a1 - a0, SHADOW);
    // the houses built into the palace over and behind the arcade, each its own height and colour
    const hx0 = cx + 0.04, hx1 = W / 2 - 0.05, hw = hx1 - hx0, cells = 4, cd = (z1 - z0 + 0.4) / cells;
    for (let c = 0; c < cells; c++) {
      const hz = z0 - 0.2 + cd * (c + 0.5), hh = court + H + 0.06 + 0.26 * (1 + Math.floor(r() * 3));
      const bell = s === side && c === 1;
      if (bell) continue;
      const wall = r() < 0.55 ? LIMESTONE : styleWall(r);
      k.box(s * (hx0 + hw / 2), court + H + 0.06, hz, hw, hh - court - H - 0.06, cd - 0.02, wall);
      k.box(s * (hx0 + hw / 2 + 0.06), court, hz, hw - 0.12, H + 0.06, cd - 0.02, LIMESTONE);
      k.hip(s * (hx0 + hw / 2), hh, hz, hw + 0.04, 0.12, cd + 0.02, pick(r, [0xb85a36, 0xc46a40, 0xa84e30]));
      // windows to the court over the arcade, and out to the street behind
      for (let y = court + H + 0.12; y < hh - 0.15; y += FLOOR) {
        win(k, b, r, s * hx0, y, hz, 0.1, 0.13, s === 1 ? 2 : 0);
        win(k, b, r, s * hx1, y, hz, 0.1, 0.13, s === 1 ? 0 : 2);
      }
    }
  }
  // the protiron across the back of the court: four columns, the arch in the middle of the architrave, the pediment
  const pz = z0 - 0.08, pw = cx * 2 - 0.08;
  for (let i = 0; i < 3; i++) k.box(0, court + i * 0.02, pz + 0.12 - i * 0.03, pw + 0.04 - i * 0.04, 0.02, 0.12, ISTRIA);
  for (const o of [-1.5, -0.5, 0.5, 1.5]) column(k, (o * pw) / 3.4, court + 0.06, pz + 0.06, H);
  k.box(0, court + 0.06 + H, pz + 0.04, pw, 0.08, 0.16, ISTRIA);
  k.gable(0, court + 0.14 + H, pz + 0.04, pw + 0.04, 0.18, 0.18, ISTRIA_SHADE, ISTRIA, true);
  archPanel(k, 0, court + 0.06 + H * 0.66, pz + 0.125, pw / 3.4, H * 0.4, SHADOW);
  // the vestibule behind it: a round hall, its dome long fallen, open to the sky
  const vz = -D / 2 + 0.26;
  k.cyl(0, court, vz, 0.24, H + 0.36, LIMESTONE, 12, SHADOW);
  k.cyl(0, court + H + 0.36, vz, 0.25, 0.04, ISTRIA, 12, ISTRIA_DARK);
  // the cathedral's bell tower over the houses on one side: tiers of arches narrowing up to a pyramid
  const bx = side * (cx + 0.55), bz = z0 - 0.2 + ((z1 - z0 + 0.4) / 4) * 1.5;
  let y = court, tw = 0.4;
  k.box(bx, y, bz, tw + 0.04, 0.34, tw + 0.04, LIMESTONE);
  around(k, bx, bz, tw + 0.04, tw + 0.04, (x0, zf) => archPanel(k, x0, y, zf + 0.004, 0.14, 0.28, SHADOW));
  y += 0.34;
  for (let i = 0; i < 4; i++) {
    const th = 0.36 - i * 0.03;
    k.box(bx, y, bz, tw, th, tw, LIMESTONE);
    const ty = y, m = i < 2 ? 1 : 2;
    around(k, bx, bz, tw, tw, (x0, zf) => {
      for (let j = 0; j < m; j++) archPanel(k, x0 + (m === 2 ? (j - 0.5) * tw * 0.42 : 0), ty + 0.05, zf + 0.004, tw * (m === 2 ? 0.3 : 0.45), th - 0.1, SHADOW);
    });
    k.box(bx, y + th, bz, tw + 0.04, 0.025, tw + 0.04, ISTRIA);
    y += th + 0.025;
    tw -= 0.03;
  }
  k.hip(bx, y, bz, tw + 0.02, 0.46, tw + 0.02, ISTRIA_SHADE);
  k.box(bx, y + 0.46, bz, 0.012, 0.08, 0.012, IRON);
  k.glowBox(bx, y - 0.3, bz, tw * 0.6, 0.22, tw * 0.6, SHADOW, FLOOD, WARM_GLOW);
  // the black granite sphinx, lying by the steps of the protiron
  const sx = -side * 0.4, sz = pz + 0.3;
  k.box(sx, court, sz, 0.16, 0.05, 0.08, ISTRIA_DARK);
  k.box(sx, court + 0.05, sz, 0.13, 0.04, 0.05, hex(0x2a2826));
  k.box(sx + 0.055, court + 0.09, sz, 0.035, 0.05, 0.035, hex(0x2a2826));
  // café chairs in the court, and a floodlight at each front corner for the summer evenings
  for (const o of [-0.25, 0.25]) k.box(o, court, z1 - 0.35, 0.06, 0.04, 0.06, hex(0xc8402e));
  for (const s of [-1, 1]) k.glowBox(s * (cx - 0.1), court, D / 2 - 0.1, 0.04, 0.04, 0.04, DARK, FLOOD, WARM_GLOW);
};

/** The Adriatic town's landmarks, by kind. */
export const ADRIATIC_DRAW = { stEuphemia, pileGate, clockLoggia, riva, peristyle } satisfies Partial<Record<ThemeKind, Draw>>;
