import * as THREE from 'three';
import { SEEN_THROUGH } from './drape';

/**
 * The ring at a shop's door (the first drive's Auto Shops): not a drop-off's green glow but an entrance,
 * a doormat in a ring of awning stripes on the ground and the shop's sign hanging over it. Stopping in
 * it and pressing Space goes in (game/cargo.ts, `pressDoor`). A tavern's (game/tavern) is plum and
 * lamplit, with a smoky board for a sign. A mission offer's (missions/wire.ts) is a diamond: a gold-and-teal
 * diamond on the ground, a gem spinning high over it and a beam of light up from it, to be seen from afar.
 */

const flat = (g: THREE.BufferGeometry) => g.rotateX(-Math.PI / 2);
const MAT = flat(new THREE.PlaneGeometry(2, 2));
const WAVE = flat(new THREE.RingGeometry(0.95, 1, 56));
const STRIPES = 20;
const RED = '#e2412f', CREAM = '#fff6e2', GOLD = '#f2a93b';
/** A tavern's door: lamplight on plum, a smoky board, a string of lanterns instead of an awning. */
const PLUM = '#4a2140', WINE = '#6e2a55', AMBER = '#ffb347', SMOKE = '#231a22';

/** How a door looks: a shop's striped awning, a tavern's lanterns, or a mission offer's diamond. */
export type DoorLook = 'shop' | 'tavern' | 'mission';
/** The pattern round a faction depot's ring (game/outlets.ts doorTheme), after what the faction is. */
export type DoorMotif = 'checker' | 'pinstripe' | 'seal' | 'crop' | 'hazard' | 'airmail' | 'camo' | 'film' | 'rope' | 'newsprint';
/** A faction depot's door: its colours (CSS), its glyph, and its motif, in place of the shop's red-and-cream awning. */
export interface DoorTheme { body: string; accent: string; glyph: string; motif: DoorMotif }

/** A mission offer's diamond: deep teal, mission-yellow edges (game/cargoLook.ts MISSION_YELLOW), a warm gem. */
const TEAL = '#0f4f5c', TEAL2 = '#1b7a87', GEM = 0xffd24a, EDGE = '#ffd24a';
const GEM_GEO = new THREE.OctahedronGeometry(0.5, 0);
/** The beam: an open cylinder from the ground up, its texture fading it out towards the top. */
const BEAM_GEO = new THREE.CylinderGeometry(0.22, 0.32, 1, 20, 1, true).translate(0, 0.5, 0);
let beamTex: THREE.Texture | null = null;
function beamTexture(): THREE.Texture {
  if (beamTex) return beamTex;
  const c = document.createElement('canvas');
  c.width = 4; c.height = 128;
  const g = c.getContext('2d')!;
  const gr = g.createLinearGradient(0, 128, 0, 0);
  gr.addColorStop(0, 'rgba(255,255,255,0.9)');
  gr.addColorStop(0.35, 'rgba(255,255,255,0.45)');
  gr.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = gr;
  g.fillRect(0, 0, 4, 128);
  beamTex = new THREE.CanvasTexture(c);
  beamTex.colorSpace = THREE.SRGBColorSpace;
  return beamTex;
}

export interface DoorMarker {
  group: THREE.Group;
  mat: THREE.Mesh; wave: THREE.Mesh; sign: THREE.Sprite;
  /** A mission offer's gem and beam. */
  gem?: THREE.Mesh; beam?: THREE.Mesh; gemMat?: THREE.MeshBasicMaterial; beamMat?: THREE.MeshBasicMaterial;
  /** A mission offer's space bar, drawn across the top of its sign while the player is close enough to press it. */
  key?: THREE.Sprite; keyMat?: THREE.SpriteMaterial; keyShown?: number;
  matMat: THREE.MeshBasicMaterial; waveMat: THREE.MeshBasicMaterial; signMat: THREE.SpriteMaterial;
  tex: THREE.Texture[];
  seed: number;
}

function overlay(color: number, map?: THREE.Texture): THREE.MeshBasicMaterial {
  return new THREE.MeshBasicMaterial({
    color, ...(map ? { map } : {}), transparent: true, depthWrite: false, toneMapped: false,
    polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2,
  });
}

/** The mark on the ground: a striped awning ring round a doormat with a dashed edge and the shop's icon. */
function matTexture(icon: string, look: DoorLook, theme?: DoorTheme): THREE.Texture {
  if (look === 'mission') return diamondTexture(icon);
  if (theme) return themedMat(icon, theme);
  const S = 256, c = document.createElement('canvas');
  c.width = c.height = S;
  const g = c.getContext('2d')!;
  const m = S / 2;
  const tavern = look === 'tavern';
  const step = (Math.PI * 2) / STRIPES;
  for (let i = 0; i < STRIPES; i++) {
    g.beginPath();
    g.moveTo(m, m);
    g.arc(m, m, m - 2, i * step, (i + 1) * step);
    g.closePath();
    g.fillStyle = tavern ? (i % 2 ? WINE : PLUM) : i % 2 ? CREAM : RED;
    g.fill();
  }
  if (tavern) {
    // a lamp at every other stripe's rim, like a string of lanterns round the mat
    for (let i = 0; i < STRIPES; i += 2) {
      const a = (i + 0.5) * step, r = m * 0.86;
      const x = m + Math.cos(a) * r, y = m + Math.sin(a) * r;
      const glow = g.createRadialGradient(x, y, 0, x, y, 13);
      glow.addColorStop(0, 'rgba(255,214,140,1)');
      glow.addColorStop(1, 'rgba(255,179,71,0)');
      g.fillStyle = glow;
      g.beginPath();
      g.arc(x, y, 13, 0, Math.PI * 2);
      g.fill();
    }
  }
  g.beginPath();
  g.arc(m, m, m * 0.74, 0, Math.PI * 2);
  if (tavern) {
    const pool = g.createRadialGradient(m, m, 0, m, m, m * 0.74);
    pool.addColorStop(0, 'rgba(120,70,40,0.95)');
    pool.addColorStop(1, 'rgba(35,26,34,0.95)');
    g.fillStyle = pool;
  } else g.fillStyle = 'rgba(255,246,226,0.92)';
  g.fill();
  g.setLineDash([10, 8]);
  g.lineWidth = 5;
  g.strokeStyle = tavern ? AMBER : GOLD;
  g.beginPath();
  g.arc(m, m, m * 0.64, 0, Math.PI * 2);
  g.stroke();
  g.setLineDash([]);
  g.font = `${Math.round(S * 0.3)}px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif`;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(icon, m, m + S * 0.02);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** A mission offer's mark on the ground: a teal diamond inside a gold one, the kind of work at its heart. */
function diamondTexture(icon: string): THREE.Texture {
  const S = 256, c = document.createElement('canvas');
  c.width = c.height = S;
  const g = c.getContext('2d')!;
  const m = S / 2;
  const dia = (r: number) => { g.beginPath(); g.moveTo(m, m - r); g.lineTo(m + r, m); g.lineTo(m, m + r); g.lineTo(m - r, m); g.closePath(); };
  dia(m - 4);
  g.fillStyle = EDGE;
  g.fill();
  dia(m - 16);
  const pool = g.createRadialGradient(m, m, 0, m, m, m - 16);
  pool.addColorStop(0, TEAL2);
  pool.addColorStop(1, TEAL);
  g.fillStyle = pool;
  g.fill();
  g.setLineDash([10, 8]);
  g.lineWidth = 5;
  g.strokeStyle = '#ffd86b';
  dia(m - 34);
  g.stroke();
  g.setLineDash([]);
  g.font = `${Math.round(S * 0.28)}px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif`;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(icon, m, m + S * 0.02);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** The space bar, as a key: a wide pale keycap with a bevel and a shadow under it, and the bar's mark on its face. */
let keyTex: THREE.Texture | null = null;
function spaceKey(): THREE.Texture {
  if (keyTex) return keyTex;
  const W = 256, H = 72, c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  const round = (x: number, y: number, w: number, h: number, r: number) => { g.beginPath(); g.roundRect(x, y, w, h, r); };
  // its side (the key's depth) under it, then the face
  round(6, 12, W - 12, H - 16, 14);
  g.fillStyle = '#9aa6ad';
  g.fill();
  round(6, 4, W - 12, H - 18, 14);
  const face = g.createLinearGradient(0, 4, 0, H - 14);
  face.addColorStop(0, '#ffffff');
  face.addColorStop(1, '#e6ebee');
  g.fillStyle = face;
  g.fill();
  g.strokeStyle = '#1f2b33';
  g.lineWidth = 3;
  round(6, 4, W - 12, H - 18, 14);
  g.stroke();
  // the bar's mark: a long open-topped bracket
  g.strokeStyle = '#1f2b33';
  g.lineWidth = 5;
  g.lineCap = 'round';
  g.lineJoin = 'round';
  g.beginPath();
  g.moveTo(W * 0.3, 22); g.lineTo(W * 0.3, 38); g.lineTo(W * 0.7, 38); g.lineTo(W * 0.7, 22);
  g.stroke();
  keyTex = new THREE.CanvasTexture(c);
  keyTex.colorSpace = THREE.SRGBColorSpace;
  keyTex.userData.aspect = W / H;
  return keyTex;
}

/** A mission offer's sign: a teal board with a gold rim, a gem, and the job's name. */
function missionSign(name: string): { tex: THREE.Texture; aspect: number } {
  const H = 128, W = 448, c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  const round = (x: number, y: number, w: number, h: number, r: number) => {
    g.beginPath();
    g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);
    g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();
  };
  round(8, 20, W - 16, H - 28, 18);
  g.fillStyle = EDGE;
  g.fill();
  round(14, 26, W - 28, H - 40, 13);
  g.fillStyle = TEAL;
  g.fill();
  g.fillStyle = '#ffd86b';
  g.font = '700 22px system-ui, sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText('◆ WORK HERE', W / 2, 46);
  g.fillStyle = '#ffffff';
  let size = 34;
  g.font = `800 ${size}px system-ui, sans-serif`;
  while (size > 18 && g.measureText(name).width > W - 60) { size -= 2; g.font = `800 ${size}px system-ui, sans-serif`; }
  g.fillText(name, W / 2, 84);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return { tex, aspect: W / H };
}

/** The hanging sign: a scalloped red-and-cream awning over a board with the shop's name. */
function signTexture(icon: string, name: string, look: DoorLook, theme?: DoorTheme): { tex: THREE.Texture; aspect: number } {
  if (theme) return themedSign(icon, name, theme);
  if (look === 'tavern') return tavernSign(icon, name);
  if (look === 'mission') return missionSign(name);
  const H = 128, W = 384, c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  const round = (x: number, y: number, w: number, h: number, r: number) => {
    g.beginPath();
    g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);
    g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();
  };
  // the board
  round(8, 34, W - 16, H - 42, 16);
  g.fillStyle = '#1f2b33';
  g.fill();
  round(14, 40, W - 28, H - 54, 12);
  g.fillStyle = CREAM;
  g.fill();
  // the awning across its top, in scallops
  const n = 8, sw = (W - 16) / n;
  for (let i = 0; i < n; i++) {
    g.fillStyle = i % 2 ? CREAM : RED;
    g.fillRect(8 + i * sw, 8, sw, 26);
    g.beginPath();
    g.arc(8 + i * sw + sw / 2, 34, sw / 2, 0, Math.PI);
    g.fill();
  }
  g.fillStyle = '#1f2b33';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  const label = name.replace(/^the /i, '');
  let size = 40;
  g.font = `800 ${size}px system-ui, sans-serif`;
  while (size > 20 && g.measureText(`${icon} ${label}`).width > W - 60) { size -= 2; g.font = `800 ${size}px system-ui, sans-serif`; }
  g.fillText(`${icon} ${label}`, W / 2, 84);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return { tex, aspect: W / H };
}

/** A tavern's sign: a dark board hung from a bar, lanterns at its ends, the name in lamplight. */
function tavernSign(icon: string, name: string): { tex: THREE.Texture; aspect: number } {
  const H = 128, W = 384, c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  const round = (x: number, y: number, w: number, h: number, r: number) => {
    g.beginPath();
    g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);
    g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();
  };
  // the bar and its two chains
  g.fillStyle = SMOKE;
  g.fillRect(20, 8, W - 40, 8);
  g.fillRect(70, 14, 5, 22); g.fillRect(W - 75, 14, 5, 22);
  // the board
  round(30, 34, W - 60, H - 42, 14);
  g.fillStyle = SMOKE;
  g.fill();
  round(36, 40, W - 72, H - 54, 10);
  g.fillStyle = PLUM;
  g.fill();
  // a lantern at each end
  for (const x of [16, W - 16]) {
    const glow = g.createRadialGradient(x, 58, 0, x, 58, 16);
    glow.addColorStop(0, 'rgba(255,224,160,1)');
    glow.addColorStop(1, 'rgba(255,179,71,0)');
    g.fillStyle = glow;
    g.beginPath(); g.arc(x, 58, 16, 0, Math.PI * 2); g.fill();
    g.fillStyle = SMOKE;
    g.fillRect(x - 5, 40, 10, 5);
  }
  g.fillStyle = AMBER;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  const label = name.replace(/^the /i, '');
  let size = 38;
  g.font = `italic 800 ${size}px Georgia, serif`;
  while (size > 18 && g.measureText(`${icon} ${label}`).width > W - 90) { size -= 2; g.font = `italic 800 ${size}px Georgia, serif`; }
  g.fillText(`${icon} ${label}`, W / 2, 81);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return { tex, aspect: W / H };
}

// ---- faction depots ---------------------------------------------------------------------------------

/** Which of two CSS colours is the lighter: the one a ripple or a line of lettering should be drawn in over the other. */
function lighter(a: string, b: string): string {
  const lum = (c: string) => { const v = new THREE.Color(c); return 0.3 * v.r + 0.59 * v.g + 0.11 * v.b; };
  return lum(a) >= lum(b) ? a : b;
}
const darker = (a: string, b: string): string => (lighter(a, b) === a ? b : a);

/** A small steady hash, so a camouflage ring is the same blotches every time it is drawn. */
const jit = (i: number, k: number): number => {
  let h = Math.imul(i + 1, 374761393) ^ Math.imul(k + 7, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
};

/**
 * Fill the rectangle (x, y, w, h) with a faction's motif: the band across a depot's sign, and (clipped to
 * the ring, or laid round it a piece at a time) the band round its mat.
 */
function paintMotif(g: CanvasRenderingContext2D, t: DoorTheme, x: number, y: number, w: number, h: number): void {
  const { body, accent } = t;
  g.save();
  g.beginPath(); g.rect(x, y, w, h); g.clip();
  g.fillStyle = body; g.fillRect(x, y, w, h);
  switch (t.motif) {
    case 'checker': {
      // the Sillitoe check: three rows of squares
      const q = h / 3;
      for (let r = 0; r < 3; r++) for (let c = 0; c * q < w; c++) if ((r + c) % 2) { g.fillStyle = accent; g.fillRect(x + c * q, y + r * q, q, q); }
      break;
    }
    case 'pinstripe': {
      g.strokeStyle = accent; g.lineWidth = 1.5;
      for (let i = 0; i * 9 < w; i++) { g.beginPath(); g.moveTo(x + i * 9, y); g.lineTo(x + i * 9, y + h); g.stroke(); }
      break;
    }
    case 'hazard': case 'airmail': {
      // diagonal bands: black and yellow on a works gate, red, white and blue round an airmail envelope
      const cols = t.motif === 'hazard' ? [body, accent] : [body, accent, '#1f3a7a', accent];
      const band = Math.min(h, 40) * 0.55;
      for (let i = -Math.ceil(h / band) - 1, k = 0; i * band < w; i++, k++) {
        g.fillStyle = cols[k % cols.length];
        g.beginPath();
        g.moveTo(x + i * band, y + h); g.lineTo(x + i * band + h, y); g.lineTo(x + (i + 1) * band + h, y); g.lineTo(x + (i + 1) * band, y + h);
        g.closePath(); g.fill();
      }
      break;
    }
    case 'camo': {
      const shades = [accent, '#2b2f17', '#6b6a3a'];
      for (let i = 0; i < Math.ceil((w * h) / 220); i++) {
        g.fillStyle = shades[i % 3];
        g.beginPath();
        g.ellipse(x + jit(i, 1) * w, y + jit(i, 2) * h, 5 + jit(i, 3) * 12, 4 + jit(i, 4) * 7, jit(i, 5) * Math.PI, 0, Math.PI * 2);
        g.fill();
      }
      break;
    }
    case 'film': {
      // a film strip: black, sprocket holes along both edges, the frames between in the studio's colour
      g.fillStyle = '#15161a'; g.fillRect(x, y, w, h);
      const hole = h * 0.16;
      g.fillStyle = '#f4f2ec';
      for (let i = 0; i * hole * 2 < w; i++) { g.fillRect(x + i * hole * 2 + hole * 0.5, y + hole * 0.35, hole, hole * 0.8); g.fillRect(x + i * hole * 2 + hole * 0.5, y + h - hole * 1.15, hole, hole * 0.8); }
      g.fillStyle = body;
      for (let i = 0; i * h * 1.1 < w; i++) g.fillRect(x + i * h * 1.1 + h * 0.08, y + hole * 1.5, h * 0.94, h - hole * 3);
      break;
    }
    case 'rope': {
      // a twisted rope along the middle, between two thin lines
      g.strokeStyle = accent; g.lineWidth = 2;
      for (const yy of [y + h * 0.14, y + h * 0.86]) { g.beginPath(); g.moveTo(x, yy); g.lineTo(x + w, yy); g.stroke(); }
      g.lineWidth = h * 0.13; g.lineCap = 'round';
      for (let i = 0; i * h * 0.3 < w + h; i++) { g.beginPath(); g.moveTo(x + i * h * 0.3, y + h * 0.3); g.lineTo(x + i * h * 0.3 - h * 0.2, y + h * 0.7); g.stroke(); }
      break;
    }
    case 'newsprint': {
      // columns of type on newsprint, a rule in the paper's red between them
      g.fillStyle = '#ecebe4'; g.fillRect(x, y, w, h);
      const col = Math.max(18, h * 0.55);
      for (let c = 0; c * col < w; c++) {
        g.fillStyle = '#4a4a4a';
        for (let r = 0; r < 5; r++) g.fillRect(x + c * col + 4, y + h * (0.12 + r * 0.16), col - 8 - jit(c, r) * col * 0.35, h * 0.07);
        g.fillStyle = body; g.fillRect(x + (c + 1) * col - 3, y, 3, h);
      }
      break;
    }
    case 'seal': case 'crop': {
      // a row of the faction's glyph: a ministry's stamp, the Visitors' marks
      g.fillStyle = accent;
      g.font = `700 ${Math.round(h * 0.62)}px "Segoe UI Symbol", system-ui, sans-serif`;
      g.textAlign = 'center'; g.textBaseline = 'middle';
      for (let i = 0; i * h < w; i++) g.fillText(t.glyph, x + i * h + h / 2, y + h / 2 + 1);
      break;
    }
  }
  g.restore();
}

/** A faction depot's mark on the ground: the faction's motif in a ring round a pool of its colours and its icon. */
function themedMat(icon: string, t: DoorTheme): THREE.Texture {
  const S = 256, c = document.createElement('canvas');
  c.width = c.height = S;
  const g = c.getContext('2d')!;
  const m = S / 2, R = m - 2, r0 = m * 0.74;
  g.save();
  g.beginPath(); g.arc(m, m, R, 0, Math.PI * 2); g.arc(m, m, r0, 0, Math.PI * 2, true); g.clip('evenodd');
  switch (t.motif) {
    case 'checker': {
      // two rows of the check, round the ring
      const n = 24, step = (Math.PI * 2) / n, rm = (R + r0) / 2;
      for (let i = 0; i < n; i++) for (const [a, b, k] of [[rm, R, 0], [r0, rm, 1]] as [number, number, number][]) {
        g.beginPath(); g.arc(m, m, b, i * step, (i + 1) * step); g.arc(m, m, a, (i + 1) * step, i * step, true); g.closePath();
        g.fillStyle = (i + k) % 2 ? t.accent : t.body; g.fill();
      }
      break;
    }
    case 'pinstripe': {
      g.fillStyle = t.body; g.fillRect(0, 0, S, S);
      g.strokeStyle = t.accent; g.lineWidth = 1.5;
      for (let i = 0; i < 72; i++) { const a = (i / 72) * Math.PI * 2; g.beginPath(); g.moveTo(m + Math.cos(a) * r0, m + Math.sin(a) * r0); g.lineTo(m + Math.cos(a) * R, m + Math.sin(a) * R); g.stroke(); }
      g.lineWidth = 3;
      for (const rr of [R - 5, r0 + 5]) { g.beginPath(); g.arc(m, m, rr, 0, Math.PI * 2); g.stroke(); }
      break;
    }
    case 'crop': {
      // a crop circle: thin rings in the field's dark green, little circles of flattened corn round it
      g.fillStyle = t.body; g.fillRect(0, 0, S, S);
      g.strokeStyle = t.accent; g.lineWidth = 2.5;
      for (const rr of [R - 4, (R + r0) / 2, r0 + 4]) { g.beginPath(); g.arc(m, m, rr, 0, Math.PI * 2); g.stroke(); }
      g.fillStyle = t.accent;
      for (let i = 0; i < 12; i++) {
        const a = (i / 12) * Math.PI * 2, rr = (R + r0) / 2;
        g.beginPath(); g.arc(m + Math.cos(a) * rr, m + Math.sin(a) * rr, i % 3 ? 4 : 8, 0, Math.PI * 2); g.fill();
      }
      break;
    }
    case 'camo':
      // reads as well straight as round: the motif over the whole mat, the ring cut from it
      paintMotif(g, t, 0, 0, S, S);
      break;
    default: {
      // laid round the ring a piece at a time, each square on to it: film, rope, chevrons, airmail, stamps, type
      g.fillStyle = t.motif === 'film' ? '#15161a' : t.motif === 'newsprint' ? '#ecebe4' : t.body; g.fillRect(0, 0, S, S);
      const band = R - r0, rm = (R + r0) / 2, n = Math.round((Math.PI * 2 * rm) / band);
      for (let i = 0; i < n; i++) {
        const a = ((i + 0.5) / n) * Math.PI * 2;
        g.save();
        g.translate(m + Math.cos(a) * rm, m + Math.sin(a) * rm); g.rotate(a + Math.PI / 2);
        paintMotif(g, t, -band * 0.56, -band / 2, band * 1.12, band);
        g.restore();
      }
    }
  }
  g.restore();
  // the pool inside in the faction's colour, an edge in its accent, and its icon
  g.beginPath(); g.arc(m, m, r0, 0, Math.PI * 2);
  const pool = g.createRadialGradient(m, m, 0, m, m, r0);
  pool.addColorStop(0, t.motif === 'crop' ? '#3f6e52' : t.body);
  pool.addColorStop(1, darker(t.body, t.accent));
  g.globalAlpha = 0.92; g.fillStyle = pool; g.fill(); g.globalAlpha = 1;
  g.setLineDash([10, 8]); g.lineWidth = 5; g.strokeStyle = lighter(t.accent, t.body);
  g.beginPath(); g.arc(m, m, m * 0.64, 0, Math.PI * 2); g.stroke(); g.setLineDash([]);
  if (t.motif === 'crop') {
    // and a glow at the heart, where whatever landed stood
    const glow = g.createRadialGradient(m, m, 0, m, m, m * 0.5);
    glow.addColorStop(0, 'rgba(142,240,200,0.55)'); glow.addColorStop(1, 'rgba(142,240,200,0)');
    g.fillStyle = glow; g.beginPath(); g.arc(m, m, m * 0.5, 0, Math.PI * 2); g.fill();
  }
  g.font = `${Math.round(S * 0.3)}px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif`;
  g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(icon, m, m + S * 0.02);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

/** Lettering for each motif's sign: a stencil for the Army, a marquee's italic for the Studios, a masthead for the Press. */
const SIGN_FONT: Record<DoorMotif, string> = {
  checker: '800 {s}px system-ui, sans-serif', pinstripe: 'italic 700 {s}px Georgia, serif', seal: '700 {s}px Georgia, serif',
  crop: '700 {s}px "Courier New", monospace', hazard: '900 {s}px Impact, "Arial Black", sans-serif', airmail: '800 {s}px system-ui, sans-serif',
  camo: '900 {s}px Impact, "Arial Black", sans-serif', film: 'italic 800 {s}px Georgia, serif', rope: '800 {s}px Georgia, serif',
  newsprint: '900 {s}px "Times New Roman", Georgia, serif',
};

/** A faction depot's sign: a board in its colours under a band of its motif, its name in the faction's own lettering. */
function themedSign(icon: string, name: string, t: DoorTheme): { tex: THREE.Texture; aspect: number } {
  const H = 128, W = 384, c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  const paper = t.motif === 'newsprint';
  // the board, rimmed in the accent
  g.beginPath(); g.roundRect(8, 30, W - 16, H - 38, 16);
  g.fillStyle = paper ? t.body : t.accent; g.fill();
  g.beginPath(); g.roundRect(14, 36, W - 28, H - 50, 12);
  g.fillStyle = paper ? '#ecebe4' : t.body; g.fill();
  // the band of the motif across its top
  g.save();
  g.beginPath(); g.roundRect(8, 6, W - 16, 30, [12, 12, 0, 0]); g.clip();
  paintMotif(g, t, 8, 6, W - 16, 30);
  g.restore();
  // the lettering in the accent, unless that is too near the board's own shade to read (gold on the Studios' pink)
  const lum = (c: string) => { const v = new THREE.Color(c); return 0.3 * v.r + 0.59 * v.g + 0.11 * v.b; };
  const ink = Math.abs(lum(t.accent) - lum(t.body)) > 0.3 ? t.accent : lum(t.body) > 0.45 ? '#15161a' : '#ffffff';
  g.fillStyle = paper ? '#15161a' : ink;
  g.textAlign = 'center'; g.textBaseline = 'middle';
  const label = `${icon} ${name.replace(/^the /i, '')}`;
  const font = (n: number) => SIGN_FONT[t.motif].replace('{s}', String(n));
  let size = 38;
  g.font = font(size);
  while (size > 18 && g.measureText(label).width > W - 56) { size -= 2; g.font = font(size); }
  if (t.motif === 'crop') { g.shadowColor = '#8ef0c8'; g.shadowBlur = 12; }
  g.fillText(label, W / 2, 81);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return { tex, aspect: W / H };
}

export function buildDoorMarker(icon: string, name: string, look: DoorLook = 'shop', theme?: DoorTheme): DoorMarker {
  const group = new THREE.Group();
  const matTex = matTexture(icon, look, theme);
  const ripple = theme ? new THREE.Color(theme.motif === 'crop' ? '#8ef0c8' : lighter(theme.body, theme.accent)).getHex() : look === 'tavern' ? 0xffb347 : look === 'mission' ? 0x4fd4e0 : 0xf2a93b;
  const matMat = overlay(0xffffff, matTex), waveMat = overlay(ripple);
  const mat = new THREE.Mesh(MAT, matMat), wave = new THREE.Mesh(WAVE, waveMat);
  // the diamond on the ground before the buildings, so a faded one lets it show (render/drape.ts SEEN_THROUGH)
  mat.renderOrder = SEEN_THROUGH + 2; wave.renderOrder = SEEN_THROUGH + 3;
  mat.position.y = 0.01; wave.position.y = 0.012;
  const s = signTexture(icon, name, look, theme);
  const signMat = new THREE.SpriteMaterial({ map: s.tex, transparent: true, depthWrite: false, toneMapped: false });
  const sign = new THREE.Sprite(signMat);
  sign.center.set(0.5, 0);
  sign.userData.aspect = s.aspect;
  sign.renderOrder = 4;
  group.add(mat, wave, sign);
  const out: DoorMarker = { group, mat, wave, sign, matMat, waveMat, signMat, tex: [matTex, s.tex], seed: Math.random() * 10 };
  if (look === 'mission') {
    // seen from afar: a gem turning high over the diamond, and a beam of light up from it
    out.gemMat = overlay(GEM);
    out.gemMat.opacity = 0.95;
    out.gem = new THREE.Mesh(GEM_GEO, out.gemMat);
    out.gem.renderOrder = 4;
    out.beamMat = overlay(0x7fe6ef, beamTexture());
    out.beamMat.blending = THREE.AdditiveBlending;
    out.beam = new THREE.Mesh(BEAM_GEO, out.beamMat);
    out.beam.renderOrder = 3;
    group.add(out.gem, out.beam);
    // the key to press, laid over the top edge of the sign: shown only near enough to press it (poseDoorMarker)
    out.keyMat = new THREE.SpriteMaterial({ map: spaceKey(), transparent: true, depthWrite: false, depthTest: false, toneMapped: false, opacity: 0 });
    out.key = new THREE.Sprite(out.keyMat);
    out.key.center.set(0.5, 0.5);
    out.key.renderOrder = 5;
    out.key.visible = false;
    out.keyShown = 0;
    group.add(out.key);
  }
  return out;
}

/**
 * Pulse it at `radius`: the mat breathes, a gold ripple runs out, the sign sways over it. `yaw` keeps
 * the icon on the mat the right way up on screen; `ready` (stopped inside) holds it bright and still;
 * `alpha` fades the whole thing (a shop's door far off).
 */
export function poseDoorMarker(m: DoorMarker, time: number, radius: number, yaw: number, ready: boolean, alpha = 1, near = false, dt = 1 / 60): void {
  const t = time + m.seed;
  const beat = 0.5 + 0.5 * Math.sin(t * 3.4);
  m.mat.scale.setScalar(radius * (ready ? 1.04 : 0.97 + 0.05 * beat));
  m.mat.rotation.y = yaw;
  m.matMat.opacity = (ready ? 1 : 0.82 + 0.18 * beat) * alpha;
  const w = (t * 0.6) % 1;
  m.wave.scale.setScalar(radius * (1 + 0.6 * w));
  m.waveMat.opacity = (1 - w) * 0.8 * alpha;
  m.signMat.opacity = alpha;
  const h = radius * 0.8;
  m.sign.scale.set(h * m.sign.userData.aspect, h, 1);
  m.sign.position.y = radius * 0.95 + (ready ? 0 : Math.sin(t * 2.2) * 0.05);
  if (m.key && m.keyMat) {
    // the space bar fades in on the sign's top edge within reach of pressing it, and out again past it
    m.keyShown = Math.max(0, Math.min(1, (m.keyShown ?? 0) + (near ? dt : -dt) * 5));
    m.key.visible = m.keyShown > 0.01;
    if (m.key.visible) {
      const kh = h * 0.25, pop = 0.85 + 0.15 * m.keyShown;
      m.key.scale.set(kh * (m.keyMat.map!.userData.aspect as number) * pop, kh * pop, 1);
      // the board's top edge is 20/128 down from the top of the sign's picture
      // straddling it, a little high, so it sits on the edge and clears the WORK HERE line under it
      m.key.position.y = m.sign.position.y + h * (1 - 20 / 128) + kh * 0.22 + (ready ? 0 : Math.sin(t * 4) * 0.03);
      m.keyMat.opacity = m.keyShown * alpha;
    }
  }
  if (m.gem && m.beam && m.gemMat && m.beamMat) {
    // a mission offer's: the gem bobs and turns above the sign, the beam rises behind it and breathes
    const s = Math.max(1.1, radius * 0.9);
    m.gem.scale.set(s, s * 1.5, s);
    m.gem.position.y = radius * 0.95 + h + s * 1.1 + Math.sin(t * 1.8) * 0.25;
    m.gem.rotation.y = t * 1.4;
    m.gemMat.opacity = 0.95 * alpha;
    m.beam.scale.set(radius * 1.1, 26, radius * 1.1);
    m.beamMat.opacity = (0.32 + 0.12 * beat) * alpha;
  }
}

export function disposeDoorMarker(m: DoorMarker): void {
  m.group.removeFromParent();
  m.matMat.dispose(); m.waveMat.dispose(); m.signMat.dispose(); m.gemMat?.dispose(); m.beamMat?.dispose(); m.keyMat?.dispose();
  for (const t of m.tex) t.dispose();
}
