import * as THREE from 'three';
import { N, DIRS, OPEN_SEA, inB, idx, owner, tileMean, waterDepth, type Port, type World } from '../world/tiles';
import { canCross } from '../world/graph';
import { MinHeap } from '../world/rivers';
import { RouteArrows } from '../render/routeArrows';
import { railHeights } from './railWay';
import type { CargoSystem } from './cargo';
import type { VehicleDef, VehicleState } from './vehicles';

/** Where the setting is remembered on this device. */
const KEY = 'tinyfleet-autopath';
/** The most tiles a route search looks at before giving up for this second. */
const EXPANSIONS = 90000;
/** What taking a car ferry is worth in tiles of driving, when weighing it against a way round by land. */
const FERRY_TILES = 40;

/** The car ferries from a county's harbours: where each one lands (main.ts ferryRun). */
export type Ferries = { from: Port; to: { w: World; port: Port } }[];

/**
 * Auto-Pathing (settings): yellow arrows from the vehicle to the tracked mission's next step, or with none
 * to point at, to the first drop of the load aboard, the #1 of the hold's suggested order. The way is the one that suits what is being driven: a road car keeps to
 * the roads where it can and climbs off them only where it must, an off-roader cuts across whatever its
 * wheels can take, a boat keeps to water deep enough to float in, and anything that flies is shown the
 * straight line. A drop on another county is aimed at across this one's border, toward it.
 */
export class AutoPath {
  on = false;
  /**
   * Route here, from a building's card: arrows to its door (world coordinates) whether or not the setting
   * is on, until the player comes within `near` tiles of it. `key` is what the card checks to show it is
   * the one being routed to.
   */
  pin: { x: number; z: number; key: string; near: number } | null = null;
  private arrows: RouteArrows;
  private def: VehicleDef | null = null;
  /** The car ferries sailing from a county's harbours (main.ts), for a way to another county over the water. */
  ferries: ((w: World) => Ferries) | null = null;
  /** The county the arrows were last laid on. */
  private w: World | null = null;

  /**
   * A train's way: along the rails it will take to world point (x, z), as local tiles of w (game/railWay.ts
   * railPath), set by main. A train has no other way to go, so without it there are no arrows.
   */
  rail: ((w: World, x: number, z: number) => number[] | null) | null = null;

  constructor(scene: THREE.Scene) {
    this.arrows = new RouteArrows(scene, (w, x, z, tx, tz) => (this.def?.kind === 'rail'
      ? this.rail?.(w, w.ox + tx, w.oz + tz) ?? null
      : routeFor(w, this.def, x, z, tx, tz, this.ferries?.(w))));
    // a train's way lies on its track, which can run well above the ground (an embankment, a viaduct)
    this.arrows.heightOf = (i) => (this.def?.kind === 'rail' ? railHeights.get(i) : undefined);
    try { this.on = localStorage.getItem(KEY) === '1'; } catch { /* storage blocked: off */ }
  }

  set(on: boolean): void {
    this.on = on;
    try { localStorage.setItem(KEY, on ? '1' : '0'); } catch { /* storage blocked: for this visit only */ }
    if (!on) this.arrows.clear();
  }

  /** The way the arrows are laid along now, in world tiles, or null (for the region map's Fleet view). */
  laid(): { x: number; z: number }[] | null {
    const p = this.arrows.laid, w = this.w;
    if (!p || !w || !this.arrows.shown) return null;
    return p.map((i) => ({ x: w.ox + (i % N) + 0.5, z: w.oz + Math.floor(i / N) + 0.5 }));
  }

  /** Pin a place to route to (Route here), or null to take the arrows down. */
  goTo(pin: { x: number; z: number; key: string; near: number } | null): void {
    this.pin = pin;
    if (!pin) this.arrows.clear();
  }

  /**
   * Lay the trail, or hide it. `quiet` is for when something else is already showing the way (the first
   * job's own guide), or the player is not driving.
   */
  update(dt: number, cargo: CargoSystem, p: { w: World; state: VehicleState; def: VehicleDef } | null, quiet: boolean,
    goal: { x: number; z: number; key: string } | null = null): void {
    // a train is shown its way along the rails (the user, 3 Nov 2026: Route here did nothing in one)
    if (quiet || !p || (p.def.kind === 'rail' && !this.rail)) { this.arrows.hide(); return; }
    // a pinned place comes first, and it is shown even with the setting off; reached, the pin is dropped
    this.w = p.w;
    if (this.pin) {
      this.def = p.def;
      const me = { x: p.w.ox + p.state.x, z: p.w.oz + p.state.z };
      if (Math.hypot(this.pin.x - me.x, this.pin.z - me.z) < this.pin.near) { this.goTo(null); return; }
      this.arrows.update(dt, p.w, me, { x: this.pin.x, z: this.pin.z }, true, `${p.def.id}|pin|${this.pin.key}`);
      return;
    }
    if (!this.on) { this.arrows.hide(); return; }
    if (goal) {
      this.def = p.def;
      const me = { x: p.w.ox + p.state.x, z: p.w.oz + p.state.z };
      if (Math.hypot(goal.x - me.x, goal.z - me.z) < 3) { this.arrows.hide(); return; }
      this.arrows.update(dt, p.w, me, { x: goal.x, z: goal.z }, true, `${p.def.id}|${goal.key}`);
      return;
    }
    const hold = cargo.hold;
    if (!hold.length) { this.arrows.hide(); return; }
    // the #1 drop: the suggested order's first, or the only place everything is going
    let first = hold[0];
    let best = Infinity;
    for (const it of hold) {
      const k = cargo.dropOrder.get(it.id) ?? Infinity;
      if (k < best) { best = k; first = it; }
    }
    this.def = p.def;
    const me = { x: p.w.ox + p.state.x, z: p.w.oz + p.state.z };
    const to = first.to;
    if (Math.hypot(to.x - me.x, to.z - me.z) < 3) { this.arrows.hide(); return; }
    this.arrows.update(dt, p.w, me, { x: to.x, z: to.z }, true, `${p.def.id}|${first.id}`);
  }
}

/**
 * The way from local tile (x, z) to (tx, tz) on w for this vehicle. A target on another county is reached by
 * the best way off this one (offCounty): across the county line where the vehicle can actually go on, or by a
 * car ferry; not by heading straight for the nearest point of the border, which can be open sea (the user,
 * 27 Oct 2026: arrows led out into deep water instead of over the causeway).
 */
export function routeFor(w: World, def: VehicleDef | null, x: number, z: number, tx: number, tz: number, ferries?: Ferries): number[] | null {
  const cl = (v: number) => Math.min(N - 1, Math.max(0, Math.floor(v)));
  const from = idx(cl(x), cl(z));
  const goal = idx(cl(tx), cl(tz));
  const off = tx < 0 || tz < 0 || tx >= N || tz >= N;
  if (!def || def.kind === 'air') return straight(from, goal);
  if (def.kind === 'water') {
    const wet = (_i: number, j: number) => (w.water[j] >= 0 && waterDepth(w, j) >= 1 ? 1 : Infinity);
    if (!off) return search(w, from, goal, wet);
    // over the line only where the water goes on, deep enough and a step of level at most (game/boat.ts)
    return offCounty(w, from, tx, tz, wet, (i, d) => {
      const o = owner(w, (i % N) + DIRS[d][0], Math.floor(i / N) + DIRS[d][1]);
      if (o.w === OPEN_SEA || o.w === w) return false;
      const j = idx(o.x, o.z);
      return o.w.water[j] >= 0 && waterDepth(o.w, j) >= 1 && Math.abs(o.w.water[j] - w.water[i]) <= 1;
    }, null) ?? search(w, from, goal, wet);
  }
  if (def.kind !== 'land') return null;
  const s = def;
  const step = (i: number, j: number, d: number): number => {
    // a bridge deck carries the road over whatever is under it, along the deck's own axis
    const along = d % 2 === 0 ? 1 : 2;
    // (a raised road's platform, deckAxis 3, carries it any way round)
    const carries = (t: number) => w.deckAxis[t] === along || w.deckAxis[t] === 3;
    if ((carries(j) || carries(i)) && (w.road[i] || w.deckAxis[i]) && (w.road[j] || w.deckAxis[j])) return 1;
    if (!canCross(w, i, d, s)) return Infinity;
    // a road is the way; off it the vehicle goes where it has to, dearer the less it likes rough ground
    const rough = w.road[j] ? 1 : 1 + 2.5 / Math.max(0.35, s.surface?.offroad ?? 0.6);
    return rough + 0.8 * Math.abs(tileMean(w, j) - tileMean(w, i));
  };
  if (!off) return search(w, from, goal, step);
  // over the line where the car can drive on into the next county (a road's crossing, a causeway, a bridge's
  // far end), or onto a ferry: canCross looks over the border into the neighbour itself
  return offCounty(w, from, tx, tz, step, (i, d) => {
    const nx = (i % N) + DIRS[d][0], nz = Math.floor(i / N) + DIRS[d][1];
    const o = owner(w, nx, nz);
    return o.w !== OPEN_SEA && o.w !== w && canCross(w, i, d, s);
  }, ferries ?? null) ?? search(w, from, goal, step);
}

/**
 * A target off the county, at local (tx, tz): A* toward it, where a tile on the border that can be crossed
 * (`out`) finishes the way at what was spent getting there plus the straight line on from it, and a
 * harbour's yard with a car ferry at FERRY_TILES plus the straight line on from where the ferry lands. The
 * best of those is the way shown; null when the county has no way off at all (then the nearest point will do).
 */
function offCounty(w: World, from: number, tx: number, tz: number, cost: (i: number, j: number, d: number) => number,
  out: (i: number, d: number) => boolean, ferries: Ferries | null): number[] | null {
  const NN = N * N;
  const g = new Float32Array(NN).fill(Infinity);
  const prev = new Int32Array(NN).fill(-1);
  const closed = new Uint8Array(NN);
  const left = (x: number, z: number) => Math.hypot(x + 0.5 - tx, z + 0.5 - tz);
  // the ferries by harbour: what is left from where each lands, in this county's tiles
  const sail = new Map<number, number>();
  for (const f of ferries ?? []) {
    const lx = f.to.w.ox - w.ox + f.to.port.x, lz = f.to.w.oz - w.oz + f.to.port.z;
    const on = FERRY_TILES + Math.hypot(lx - tx, lz - tz);
    if (on < (sail.get(f.from.id) ?? Infinity)) sail.set(f.from.id, on);
  }
  const heap = new MinHeap();
  g[from] = 0;
  heap.push(left(from % N, Math.floor(from / N)), from);
  let best = Infinity, end = -1, n = 0;
  while (heap.size) {
    const i = heap.pop();
    if (closed[i]) continue;
    const x = i % N, z = (i - x) / N;
    // nothing left to pop can beat the best way off found
    if (g[i] + left(x, z) >= best) break;
    closed[i] = 1;
    if (++n > EXPANSIONS) break;
    // a ferry's yard: the way could go on by sea from here
    const port = w.portId[i];
    if (port >= 0 && sail.has(port) && g[i] + sail.get(port)! < best) { best = g[i] + sail.get(port)!; end = i; }
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) {
        if (out(i, d)) { const t = g[i] + 1 + left(nx, nz); if (t < best) { best = t; end = i; } }
        continue;
      }
      const j = idx(nx, nz);
      if (closed[j]) continue;
      const c = cost(i, j, d);
      if (!Number.isFinite(c)) continue;
      const ng = g[i] + c;
      if (ng < g[j]) { g[j] = ng; prev[j] = i; heap.push(ng + left(nx, nz), j); }
    }
  }
  if (end < 0 || end === from) return end === from ? [from] : null;
  const path: number[] = [];
  for (let i = end; i >= 0; i = prev[i]) path.push(i);
  return path.reverse();
}

/** A* over the county's tiles, stepping by `cost` (Infinity for no way); when the goal cannot be reached, the nearest tile reached. */
function search(_w: World, from: number, goal: number, cost: (i: number, j: number, d: number) => number): number[] | null {
  const NN = N * N;
  const g = new Float32Array(NN).fill(Infinity);
  const prev = new Int32Array(NN).fill(-1);
  const closed = new Uint8Array(NN);
  const gx = goal % N, gz = Math.floor(goal / N);
  const heap = new MinHeap();
  g[from] = 0;
  heap.push(0, from);
  let n = 0, near = from, nearD = Infinity;
  while (heap.size) {
    const i = heap.pop();
    if (closed[i]) continue;
    closed[i] = 1;
    const x = i % N, z = (i - x) / N;
    const dd = Math.abs(x - gx) + Math.abs(z - gz);
    if (dd < nearD) { nearD = dd; near = i; }
    if (i === goal || ++n > EXPANSIONS) break;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (closed[j]) continue;
      const c = cost(i, j, d);
      if (!Number.isFinite(c)) continue;
      const ng = g[i] + c;
      if (ng < g[j]) { g[j] = ng; prev[j] = i; heap.push(ng + Math.abs(nx - gx) + Math.abs(nz - gz), j); }
    }
  }
  const end = closed[goal] ? goal : near;
  if (end === from) return null;
  const path: number[] = [];
  for (let i = end; i >= 0; i = prev[i]) path.push(i);
  return path.reverse();
}

/** Tiles along the straight line between two tiles: the way for anything that flies. */
function straight(from: number, goal: number): number[] {
  const ax = from % N, az = Math.floor(from / N), bx = goal % N, bz = Math.floor(goal / N);
  const n = Math.max(Math.abs(bx - ax), Math.abs(bz - az), 1);
  const out: number[] = [];
  for (let k = 0; k <= n; k += 2) out.push(idx(Math.round(ax + ((bx - ax) * k) / n), Math.round(az + ((bz - az) * k) / n)));
  return out;
}
