import { N } from '../world/tiles';
import { railAt, railLines, railStation, stationsAlong, type StationRef } from '../world/rail';
import { allowed, type Loc, type Track, type Trains } from './trains';
import { SETS } from './rollingStock';
import { hashString } from '../world/rng';
import type { FarCell, FarWire } from '../../shared/protocol';
export type { FarCell, FarWire };

/**
 * A crewed train's far run (docs/crewtrains.html, Long haul): out of memory a train is only a route and a clock. The
 * route is read from the world plan (world/rail.ts), so nothing need be generated to know it: the counties from the
 * one it left by to the far station, each with the side it is entered by and the side it leaves by. Where it is now is
 * the clock over the route, a county at a time.
 *
 * Wherever a county on the route is in memory (the owner watching, or another player online near it), a stand-in for
 * the train is put on that county's real track at the clock's place (Trains.phantom): it moves along the track at the
 * train's speed, CPU trains give way to it, and it is never driven. Only the owner's clock pays, once, at the end of a
 * leg, so watching it or letting it go can never pay twice.
 *
 * Pure but for the trains it reads: the gate can walk routes with no game.
 */


const DX = [1, 0, -1, 0], DZ = [0, 1, 0, -1];
/** Counties a route may run before it gives up looking for the far station. */
export const FAR_MAX = 16;
/** Seconds a far train stands at the far station handing in and loading before it sets off back. */
export const FAR_DWELL = 20;

/**
 * The route from county (cx, cz) left over side d, to the county `dest` (the far station in it), or null when the line
 * doesn't get there within FAR_MAX counties. With no dest: as far as the line goes, every county (for picking one).
 */
export function farRoute(sh: number, cx: number, cz: number, d: number, dest: { cx: number; cz: number } | null): FarCell[] | null {
  const out: FarCell[] = [];
  let x = cx + DX[d], z = cz + DZ[d], enter = (d + 2) % 4;
  for (let n = 0; n < FAR_MAX; n++) {
    const lines = railLines(sh, x, z);
    const line = lines.find((l) => l.sides.includes(enter) && l.kind !== 'stub') ?? lines.find((l) => l.sides.includes(enter));
    if (!line) break;
    if (dest && x === dest.cx && z === dest.cz) { out.push({ cx: x, cz: z, enter, exit: -1 }); return out; }
    const exit = line.kind === 'stub' ? line.joinDir! : line.sides.find((s) => s !== enter);
    if (exit === undefined) break;
    out.push({ cx: x, cz: z, enter, exit });
    x += DX[exit]; z += DZ[exit]; enter = (exit + 2) % 4;
  }
  return dest ? null : out;
}

/** The way back: the same counties the other way round, from the far station to the border it left by. */
export const reversedRoute = (cells: FarCell[]): FarCell[] => [...cells].reverse().map((c) => ({ cx: c.cx, cz: c.cz, enter: c.exit, exit: c.enter }));

/** How much of a county's time a cell takes: a half for one the far station ends or starts the leg in. */
const weight = (c: FarCell): number => (c.enter < 0 || c.exit < 0 ? 0.5 : 1);
/** Seconds a leg takes, the far station's dwell left out. */
export const legTime = (w: Pick<FarWire, 'cells' | 'spc'>): number => w.cells.reduce((n, c) => n + weight(c), 0) * w.spc;

/** Where on its route a far train is at `t` seconds into the leg: the county and the share of the way through it. */
export function farAt(w: Pick<FarWire, 'cells' | 'spc'>, t: number): { i: number; share: number } {
  let left = Math.max(0, t);
  for (let i = 0; i < w.cells.length; i++) {
    const span = weight(w.cells[i]) * w.spc;
    if (left <= span) return { i, share: span > 0 ? left / span : 1 };
    left -= span;
  }
  return { i: w.cells.length - 1, share: 1 };
}

/** A border's crossing point in world tiles: the middle of the tile the line crosses at. */
function borderPoint(sh: number, c: FarCell, side: number): { x: number; z: number } {
  const at = Math.max(0, railAt(sh, c.cx, c.cz, side));
  const ox = c.cx * N, oz = c.cz * N;
  if (side === 0) return { x: ox + N, z: oz + at + 0.5 };
  if (side === 2) return { x: ox, z: oz + at + 0.5 };
  if (side === 1) return { x: ox + at + 0.5, z: oz + N };
  return { x: ox + at + 0.5, z: oz };
}

/** About where a far train is, in world tiles, from the plan alone (the region map's dot, the follow-cam's aim). */
export function farPoint(sh: number, w: Pick<FarWire, 'cells' | 'spc'>, t: number): { x: number; z: number; cx: number; cz: number } {
  const { i, share } = farAt(w, t);
  const c = w.cells[i];
  const mid = { x: (c.cx + 0.5) * N, z: (c.cz + 0.5) * N };
  const a = c.enter >= 0 ? borderPoint(sh, c, c.enter) : mid, b = c.exit >= 0 ? borderPoint(sh, c, c.exit) : mid;
  return { x: a.x + (b.x - a.x) * share, z: a.z + (b.z - a.z) * share, cx: c.cx, cz: c.cz };
}

/** The far station a route ends at, from the plan. */
export const farStation = (sh: number, cells: FarCell[]): StationRef | null => {
  const last = cells[cells.length - 1];
  return last && last.exit < 0 ? railStation(sh, last.cx, last.cz) : null;
};

/**
 * Stations a long haul from a beat's end may be bound for (docs/crewtrains.html): 5 to 14 counties on along the line
 * past that end, by every side of its county the line leaves by that doesn't lead back into the beat.
 */
export function farDests(sh: number, cx: number, cz: number, beatCells: [number, number][], min: number, max: number): { st: StationRef; side: number }[] {
  const out: { st: StationRef; side: number }[] = [];
  for (const line of railLines(sh, cx, cz)) {
    for (const d of line.sides) {
      if (beatCells.some(([x, z]) => x === cx + DX[d] && z === cz + DZ[d])) continue;
      for (const st of stationsAlong(sh, cx, cz, d, max)) {
        if (Math.max(Math.abs(st.cx - cx), Math.abs(st.cz - cz)) < min) continue;
        if (!out.some((q) => q.st.cx === st.cx && q.st.cz === st.cz)) out.push({ st, side: d });
      }
    }
  }
  return out;
}

/**
 * The stretch of real track a route's county runs over, if the county is in memory: from the border it is entered by
 * (or the far station's platform) to the border it leaves by (or that platform), straight on, each track its own way.
 */
function stretch(trains: Trains, sh: number, c: FarCell): { t: Track; s0: number; s1: number }[] | null {
  const w = trains.worlds.find((q) => q.cx === c.cx && q.cz === c.cz);
  if (!w) return null;
  const tracks = trains.net.tracksOf(w).filter((t) => t.p.kind !== 'loop');
  const st = c.enter < 0 || c.exit < 0 ? railStation(sh, c.cx, c.cz) : null;
  const platform = (t: Track): number | null => {
    if (!st) return null;
    for (const e of t.stations) if (!e.loop && (e.st.of ?? e.st).name === st.name) return (e.st.s0 + e.st.s1) / 2;
    return null;
  };
  // where it starts: on a track at the border it comes in by, heading in its way; or at the platform, either way
  const starts: Loc[] = [];
  for (const t of tracks) {
    if (c.enter >= 0) {
      if (t.p.start.kind === 'border' && t.p.start.side === c.enter && allowed(t, 0, 1)) starts.push({ t, s: 0, dir: 1 });
      if (t.p.end.kind === 'border' && t.p.end.side === c.enter && allowed(t, t.p.length, -1)) starts.push({ t, s: t.p.length, dir: -1 });
    } else {
      const m = platform(t);
      if (m !== null) for (const dir of [1, -1] as const) if (allowed(t, m, dir)) starts.push({ t, s: m, dir });
    }
  }
  for (const from of starts) {
    const segs: { t: Track; s0: number; s1: number }[] = [];
    let t = from.t, s = from.s, dir = from.dir;
    for (let guard = 0; guard < 24; guard++) {
      const end = dir > 0 ? t.p.length : 0;
      const m = c.exit < 0 ? platform(t) : null;
      if (m !== null && (m - s) * dir >= 0) { segs.push({ t, s0: s, s1: m }); return segs; }
      segs.push({ t, s0: s, s1: end });
      const e = dir > 0 ? t.p.end : t.p.start;
      if (e.kind === 'border') { if (c.exit >= 0 && e.side === c.exit) return segs; break; }
      const nx = trains.net.next(t, dir > 0);
      if (!nx || nx.t.w !== w) break;
      t = nx.t; s = nx.s; dir = nx.dir;
    }
  }
  return null;
}

/** Where on the real track a far train is at `t` into its leg, if that county is in memory: its front, facing its way. */
export function farLoc(trains: Trains, sh: number, w: Pick<FarWire, 'cells' | 'spc'>, t: number): (Loc & { cell: FarCell }) | null {
  const { i, share } = farAt(w, t);
  const c = w.cells[i];
  const segs = stretch(trains, sh, c);
  if (!segs) return null;
  const len = segs.reduce((n, g) => n + Math.abs(g.s1 - g.s0), 0);
  let left = share * len;
  for (const g of segs) {
    const l = Math.abs(g.s1 - g.s0), dir = (g.s1 >= g.s0 ? 1 : -1) as 1 | -1;
    if (left <= l) return { t: g.t, s: g.s0 + dir * left, dir, cell: c };
    left -= l;
  }
  const g = segs[segs.length - 1];
  return { t: g.t, s: g.s1, dir: (g.s1 >= g.s0 ? 1 : -1) as 1 | -1, cell: c };
}

/**
 * Draw (or take away) the stand-in for a far run `t` seconds into its leg, under `key`: on the real track where the
 * clock puts it when that county is in memory, stood at the far station through its dwell. True while it is drawn.
 */
export function drawFar(trains: Trains, sh: number, key: string, w: FarWire, t: number, look: { paint?: [number, number]; what: string }): boolean {
  const set = SETS.find((s) => s.id === w.m);
  const total = legTime(w);
  const loc = set && w.cells.length ? farLoc(trains, sh, w, Math.min(t, total)) : null;
  if (!set || !loc) { trains.phantom(key, null as never, null, 0); return false; }
  const to = farStation(sh, w.cells)?.name ?? '';
  trains.phantom(key, { ids: w.ids.length ? w.ids : set.cars, era: set.era, freight: set.freight, paint: look.paint, name: w.n, to, what: look.what, seed: hashString(key) }, loc, t < total ? Math.min(set.topSpeed, N / Math.max(1, w.spc)) : 0);
  return true;
}
