import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { N, STEP, Biome, World, heightAt, idx, inB } from '../world/tiles';
import { hash2 } from '../world/rng';

/**
 * Wild animals (docs/phonelist.html item 3, the user, 10 Nov 2026): the country's own life beside the biomes' herds
 * (game/herds.ts). In the sky, hawks circling a thermal over open ground, eagles wheeling higher over the mountains,
 * and in spring and autumn a skein of geese crossing the county in a V. On the ground, deer at the edge of the woods
 * that bolt for the trees when a car comes, a fox trotting the field edges at dusk that darts off in the headlamps,
 * now and then a bear by the river that rears up and lumbers away, and very rarely a mountain lion sitting on a high
 * ledge that is gone before you get close.
 *
 * Client-side and scripted, like the herds: nothing is saved, and two players do not see the same bear. Which animals
 * a county has, and where, is hashed from the county, so it is the same each visit.
 */

type Kind = 'deer' | 'fox' | 'bear' | 'lion';
type Bird = 'hawk' | 'eagle' | 'goose';

interface Animal {
  kind: Kind;
  x: number; z: number; yaw: number;
  /** Where it drifts round, how far it wanders, and where it runs to when scared. */
  hx: number; hz: number; r: number; tx: number; tz: number;
  /** 0 calm, >0 seconds left of running away. */
  flee: number;
  /** A bear standing up on its hind legs (0..1), a lion slipping away (fades). */
  rear: number; gone: number;
  phase: number;
}

interface Flier {
  kind: Bird;
  x: number; y: number; z: number; yaw: number;
  /** A circler's middle, radius, height over the ground, and how fast round. */
  cx: number; cz: number; r: number; h: number; w: number; a: number;
  /** A skein's straight line, and this bird's place in the V. */
  line?: { x0: number; z0: number; dx: number; dz: number; t: number; len: number; rank: number; side: number };
  flap: number;
}

const CAP: Record<Kind, number> = { deer: 18, fox: 4, bear: 2, lion: 1 };
const BIRD_CAP: Record<Bird, number> = { hawk: 4, eagle: 2, goose: 13 };
/** Tiles a car may come within before an animal runs (a lion's are wider: it's off long before). */
const SCARE: Record<Kind, number> = { deer: 4.5, fox: 3.5, bear: 3.0, lion: 9 };
const RUN: Record<Kind, number> = { deer: 2.6, fox: 2.4, bear: 1.5, lion: 2.0 };
const AMBLE: Record<Kind, number> = { deer: 0.12, fox: 0.3, bear: 0.1, lion: 0 };

function paint(g: THREE.BufferGeometry, hex: number): THREE.BufferGeometry {
  const out = g.index ? g.toNonIndexed() : g;
  out.deleteAttribute('uv');
  const n = out.attributes.position.count, c = new THREE.Color(hex), a = new Float32Array(n * 3);
  for (let k = 0; k < n; k++) { a[k * 3] = c.r; a[k * 3 + 1] = c.g; a[k * 3 + 2] = c.b; }
  out.setAttribute('color', new THREE.BufferAttribute(a, 3));
  return out;
}
const box = (w: number, h: number, d: number, x: number, y: number, z: number, hex: number) => paint(new THREE.BoxGeometry(w, h, d).translate(x, y, z), hex);

/** The animals' bodies, facing +z, feet at y 0. */
function animalGeo(kind: Kind): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const legs = (w: number, h: number, sx: number, z0: number, z1: number, hex: number) => {
    for (const x of [-sx, sx]) for (const z of [z0, z1]) parts.push(box(w, h, w, x, h / 2, z, hex));
  };
  switch (kind) {
    case 'deer':
      legs(0.018, 0.1, 0.03, -0.06, 0.06, 0x7a5638);
      parts.push(box(0.07, 0.06, 0.17, 0, 0.13, 0, 0x9a6a44), box(0.03, 0.08, 0.03, 0, 0.19, 0.08, 0x9a6a44));
      parts.push(box(0.04, 0.035, 0.06, 0, 0.23, 0.1, 0x8a5c3a), box(0.03, 0.02, 0.02, 0, 0.12, -0.09, 0xf2ece0));
      // antlers
      for (const s of [-1, 1]) parts.push(box(0.008, 0.06, 0.008, s * 0.018, 0.27, 0.09, 0x6a5038), box(0.03, 0.008, 0.008, s * 0.03, 0.29, 0.09, 0x6a5038));
      break;
    case 'fox':
      legs(0.012, 0.05, 0.02, -0.04, 0.04, 0x3a2a20);
      parts.push(box(0.045, 0.04, 0.12, 0, 0.07, 0, 0xd8692a), box(0.04, 0.035, 0.05, 0, 0.09, 0.075, 0xd8692a));
      parts.push(box(0.015, 0.02, 0.03, 0, 0.085, 0.11, 0x2a1e18), box(0.012, 0.025, 0.008, -0.013, 0.12, 0.07, 0x2a1e18), box(0.012, 0.025, 0.008, 0.013, 0.12, 0.07, 0x2a1e18));
      parts.push(box(0.03, 0.03, 0.09, 0, 0.065, -0.1, 0xd8692a), box(0.03, 0.03, 0.025, 0, 0.065, -0.155, 0xf4f0e8));
      break;
    case 'bear':
      legs(0.04, 0.08, 0.05, -0.08, 0.08, 0x3e2a1e);
      parts.push(box(0.14, 0.11, 0.26, 0, 0.14, 0, 0x4a3224), box(0.09, 0.08, 0.08, 0, 0.17, 0.16, 0x4a3224));
      parts.push(box(0.04, 0.035, 0.04, 0, 0.15, 0.21, 0x6a4a34), box(0.025, 0.025, 0.015, -0.03, 0.22, 0.15, 0x3e2a1e), box(0.025, 0.025, 0.015, 0.03, 0.22, 0.15, 0x3e2a1e));
      break;
    case 'lion':
      // sitting up on its haunches, looking out
      parts.push(box(0.07, 0.07, 0.12, 0, 0.04, -0.02, 0xc29a62), box(0.06, 0.09, 0.05, 0, 0.1, 0.05, 0xc29a62));
      parts.push(box(0.05, 0.05, 0.06, 0, 0.17, 0.07, 0xb88c56), box(0.012, 0.012, 0.15, 0.03, 0.01, -0.12, 0xa07a48));
      break;
  }
  return mergeGeometries(parts)!;
}

/** A bird's body (along +z), and one wing (out along +x from the body's side, its root at the origin). */
function birdGeo(kind: Bird): { body: THREE.BufferGeometry; wing: THREE.BufferGeometry } {
  const s = kind === 'eagle' ? 1.6 : kind === 'goose' ? 0.8 : 1;
  const body = kind === 'goose' ? 0x5a5650 : kind === 'eagle' ? 0x4a3424 : 0x8a6a4a;
  const head = kind === 'goose' ? 0x1f1f1f : kind === 'eagle' ? 0xf4f2ec : 0x7a5a3a;
  const b = mergeGeometries([
    box(0.04 * s, 0.035 * s, 0.14 * s, 0, 0, 0, body),
    box(0.03 * s, 0.03 * s, 0.04 * s, 0, 0.01 * s, 0.085 * s, head),
    box(0.05 * s, 0.01 * s, 0.05 * s, 0, 0, -0.085 * s, body),
  ])!;
  const wing = new THREE.BufferGeometry();
  const span = 0.16 * s, chord = 0.07 * s;
  wing.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, chord / 2, span, 0, 0, 0, 0, -chord / 2, 0, 0, chord / 2, 0, 0, -chord / 2, span, 0, 0], 3));
  wing.computeVertexNormals();
  return { body: b, wing: paint(wing, kind === 'goose' ? 0x6a665e : body) };
}

export class Wildlife {
  private parent: THREE.Object3D;
  private w: World | null = null;
  private animals: Animal[] = [];
  private birds: Flier[] = [];
  private meshes = new Map<Kind, THREE.InstancedMesh>();
  private birdMeshes = new Map<Bird, { body: THREE.InstancedMesh; left: THREE.InstancedMesh; right: THREE.InstancedMesh }>();
  private player = { x: -999, z: -999, v: 0 };
  private season = { warm: 0.5, cold: 0 };
  /** Autumn or spring: the geese are on the move (game/season.ts writes it). */
  private migrating = 0;
  private skeinT = 30;
  private time = 0;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private e = new THREE.Euler();
  private v = new THREE.Vector3();
  private s = new THREE.Vector3(1, 1, 1);
  private hidden = new THREE.Matrix4().makeScale(0, 0, 0);
  /** Kinds the player has had a good look at this visit (for the Passport, should it ask). */
  readonly seen = new Set<string>();

  constructor(parent: THREE.Object3D) {
    this.parent = parent;
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85, metalness: 0 });
    const wingMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85, metalness: 0, side: THREE.DoubleSide });
    for (const k of Object.keys(CAP) as Kind[]) {
      const im = new THREE.InstancedMesh(animalGeo(k), mat, CAP[k]);
      im.count = 0; im.frustumCulled = false; im.castShadow = true;
      parent.add(im);
      this.meshes.set(k, im);
    }
    for (const k of Object.keys(BIRD_CAP) as Bird[]) {
      const g = birdGeo(k);
      const mk = (geo: THREE.BufferGeometry, mt: THREE.Material) => {
        const im = new THREE.InstancedMesh(geo, mt, BIRD_CAP[k]);
        im.count = 0; im.frustumCulled = false; im.castShadow = true;
        parent.add(im);
        return im;
      };
      const right = g.wing, left = g.wing.clone().scale(-1, 1, 1);
      this.birdMeshes.set(k, { body: mk(g.body, mat), left: mk(left, wingMat), right: mk(right, wingMat) });
    }
  }

  dispose(): void {
    for (const im of this.meshes.values()) im.removeFromParent();
    for (const b of this.birdMeshes.values()) { b.body.removeFromParent(); b.left.removeFromParent(); b.right.removeFromParent(); }
  }

  setPlayer(x: number, z: number, speed: number): void { this.player.x = x; this.player.z = z; this.player.v = speed; }
  setSeason(warm: number, cold: number, migrating = 0): void { this.season.warm = warm; this.season.cold = cold; this.migrating = migrating; }

  /** What lives in this county: hashed from it, so the same animals are in the same places every visit. */
  setWorld(w: World | null): void {
    if (w === this.w) return;
    this.w = w;
    this.animals = [];
    this.birds = [];
    this.skeinT = 20 + Math.random() * 40;
    if (!w) { for (const im of this.meshes.values()) im.count = 0; for (const b of this.birdMeshes.values()) b.body.count = b.left.count = b.right.count = 0; return; }
    const h = (s: number) => hash2(w.cx * 977 + w.cz * 131, s, 5501);
    // what kind of country it is, from a sample of its tiles
    let forest = 0, open = 0, high = 0, land = 0, red = 0;
    const edges: { x: number; z: number }[] = [], fields: { x: number; z: number }[] = [], ledges: { x: number; z: number }[] = [], rivers: { x: number; z: number }[] = [];
    for (let z = 8; z < N - 8; z += 4) for (let x = 8; x < N - 8; x += 4) {
      const i = idx(x, z), b = w.biome[i];
      if (w.water[i] >= 0 || w.townId[i] >= 0 || w.road[i] || w.blocked[i]) continue;
      land++;
      if (b === Biome.Forest) forest++;
      if (b === Biome.Plains || b === Biome.Farm || b === Biome.Hills) open++;
      if (b === Biome.Mountain || b === Biome.Canyon) high++;
      if (b === Biome.Canyon || b === Biome.Desert) red++;
      // a wood's edge: forest beside open ground
      if (b === Biome.Forest && inB(x + 3, z) && (w.biome[idx(x + 3, z)] === Biome.Plains || w.biome[idx(x + 3, z)] === Biome.Hills)) edges.push({ x: x + 1.5, z });
      if (b === Biome.Farm || (b === Biome.Plains && hash2(x, z, 5502) < 0.1)) fields.push({ x, z });
      if ((b === Biome.Mountain || b === Biome.Canyon || b === Biome.Hills) && w.corners[i * 4] * STEP > 4) ledges.push({ x, z });
      if (b === Biome.Forest && inB(x + 2, z) && w.water[idx(x + 2, z)] >= 0) rivers.push({ x, z });
    }
    if (!land) return;
    const pick = <T,>(list: T[], s: number) => list[Math.floor(h(s) * list.length) % list.length];
    // deer: a group or two at wood edges
    const groups = edges.length ? (forest / land > 0.15 ? 3 : 1) : 0;
    for (let g = 0; g < groups; g++) {
      const at = pick(edges, 10 + g);
      const n = 3 + Math.floor(h(20 + g) * 3);
      for (let k = 0; k < n && this.count('deer') < CAP.deer; k++) this.add('deer', at.x + (h(30 + g * 9 + k) - 0.5) * 3, at.z + (h(40 + g * 9 + k) - 0.5) * 3, at.x, at.z, 4);
    }
    // a fox or two in farm country
    if (fields.length && h(50) < 0.7) for (let k = 0; k < 1 + Math.floor(h(51) * 2); k++) { const at = pick(fields, 52 + k); this.add('fox', at.x, at.z, at.x, at.z, 9); }
    // a bear in big wooded country by water, one county in six
    if (rivers.length && forest / land > 0.2 && h(60) < 0.18) { const at = pick(rivers, 61); this.add('bear', at.x, at.z, at.x, at.z, 6); }
    // a mountain lion on a high ledge, very rarely
    if (ledges.length && (high + red) / land > 0.12 && h(70) < 0.08) { const at = pick(ledges, 71); this.add('lion', at.x + 0.5, at.z + 0.5, at.x, at.z, 0); }
    // hawks over open ground, eagles over the high country
    const hawks = open / land > 0.3 ? 1 + Math.floor(h(80) * 2) : h(80) < 0.4 ? 1 : 0;
    for (let k = 0; k < hawks; k++) {
      const at = fields.length ? pick(fields, 81 + k) : { x: N / 2, z: N / 2 };
      this.addCircler('hawk', at.x, at.z, 2.5 + h(85 + k) * 2.5, 3.5 + h(86 + k) * 1.5, 0.35 + h(87 + k) * 0.15, h(88 + k) * Math.PI * 2);
    }
    if (high / land > 0.1) for (let k = 0; k < (high / land > 0.3 ? 2 : 1); k++) {
      const at = ledges.length ? pick(ledges, 90 + k) : { x: N / 2, z: N / 2 };
      this.addCircler('eagle', at.x, at.z, 5 + h(91 + k) * 3, 6 + h(92 + k) * 2, 0.22, h(93 + k) * Math.PI * 2);
    }
  }

  private count(k: Kind): number { return this.animals.filter((a) => a.kind === k).length; }

  private add(kind: Kind, x: number, z: number, hx: number, hz: number, r: number): void {
    if (!this.w || this.count(kind) >= CAP[kind]) return;
    const cx = Math.min(N - 1, Math.max(0, x)), cz = Math.min(N - 1, Math.max(0, z));
    this.animals.push({ kind, x: cx, z: cz, yaw: Math.random() * Math.PI * 2, hx, hz, r, tx: cx, tz: cz, flee: 0, rear: 0, gone: 0, phase: Math.random() * 6 });
  }

  private addCircler(kind: Bird, cx: number, cz: number, r: number, h: number, w: number, a: number): void {
    if (this.birds.filter((b) => b.kind === kind).length >= BIRD_CAP[kind]) return;
    this.birds.push({ kind, x: cx, y: 0, z: cz, yaw: 0, cx, cz, r, h, w, a, flap: Math.random() * 6 });
  }

  /** A skein of geese across the county, south in autumn and north in spring, in a V. */
  private addSkein(): void {
    const w = this.w;
    if (!w) return;
    this.birds = this.birds.filter((b) => b.kind !== 'goose');
    const south = this.season.warm < 0.5;
    const dz = south ? 1 : -1, dx = (Math.random() - 0.5) * 0.6;
    const l = Math.hypot(dx, dz);
    const x0 = 40 + Math.random() * (N - 80), z0 = south ? -10 : N + 10;
    const n = 7 + Math.floor(Math.random() * 6);
    for (let k = 0; k < n; k++) {
      const rank = Math.ceil(k / 2), side = k === 0 ? 0 : k % 2 ? -1 : 1;
      this.birds.push({ kind: 'goose', x: x0, y: 0, z: z0, yaw: 0, cx: 0, cz: 0, r: 0, h: 9, w: 0, a: 0, flap: Math.random() * 6,
        line: { x0, z0, dx: dx / l, dz: dz / l, t: 0, len: N + 20, rank, side } });
    }
  }

  update(dt: number, hour: number): void {
    const w = this.w;
    if (!w || dt <= 0) return;
    this.time += dt;
    const dusk = (hour > 5 && hour < 8.5) || (hour > 17 && hour < 21);
    const night = hour >= 21 || hour < 5;
    // the geese pass over now and then while they are on the move
    if (this.migrating > 0.3) {
      this.skeinT -= dt;
      if (this.skeinT <= 0 && !this.birds.some((b) => b.kind === 'goose')) { this.addSkein(); this.skeinT = 60 + Math.random() * 90; }
    }
    // the ground animals
    const used = new Map<Kind, number>();
    for (const a of this.animals) {
      const im = this.meshes.get(a.kind)!;
      const i = used.get(a.kind) ?? 0;
      used.set(a.kind, i + 1);
      // the fox is out at dusk and by night; the deer graze at dawn and dusk and in the woods' shade by day
      const out = a.kind === 'fox' ? dusk || night : a.kind === 'deer' ? !night : true;
      const d = Math.hypot(this.player.x - a.x, this.player.z - a.z);
      if (d < SCARE[a.kind] && this.player.v > 0.3 && a.flee <= 0) {
        a.flee = a.kind === 'lion' ? 99 : 4 + Math.random() * 2;
        // away from the car, toward the woods where there are some
        const ax = (a.x - this.player.x) / (d || 1), az = (a.z - this.player.z) / (d || 1);
        a.tx = a.x + ax * 10; a.tz = a.z + az * 10;
        this.seen.add(a.kind);
      } else if (d < 10 && d >= SCARE[a.kind]) this.seen.add(a.kind);
      if (a.kind === 'lion') {
        // never runs where you can see it: it's simply gone off its ledge once you come near
        if (a.flee > 0) a.gone = Math.min(1, a.gone + dt * 2);
      } else if (a.flee > 0) {
        a.flee -= dt;
        // a bear rears up first, then lumbers off
        if (a.kind === 'bear' && a.rear < 1 && a.flee > 3) a.rear = Math.min(1, a.rear + dt * 2);
        else { a.rear = Math.max(0, a.rear - dt * 2); this.step(w, a, a.tx, a.tz, RUN[a.kind] * dt); }
      } else {
        // grazing and pottering about their home ground
        if (Math.hypot(a.tx - a.x, a.tz - a.z) < 0.1 || Math.random() < dt * 0.05) {
          const ang = Math.random() * Math.PI * 2, r = Math.random() * a.r;
          a.tx = a.hx + Math.cos(ang) * r; a.tz = a.hz + Math.sin(ang) * r;
        }
        this.step(w, a, a.tx, a.tz, AMBLE[a.kind] * dt);
        // and drift home again after a fright
        if (Math.hypot(a.hx - a.x, a.hz - a.z) > a.r + 6) { a.tx = a.hx; a.tz = a.hz; }
      }
      if (!out || a.gone >= 1) { im.setMatrixAt(i, this.hidden); continue; }
      const y = heightAt(w, Math.min(N - 0.01, Math.max(0, a.x)), Math.min(N - 0.01, Math.max(0, a.z)));
      const gait = a.flee > 0 ? Math.abs(Math.sin(this.time * 14 + a.phase)) * 0.025 : 0;
      this.e.set(-a.rear * 1.1, a.yaw, 0, 'YXZ');
      this.q.setFromEuler(this.e);
      this.v.set(a.x, y + gait, a.z);
      this.s.setScalar(1 - a.gone * 0.6);
      this.m.compose(this.v, this.q, this.s);
      im.setMatrixAt(i, this.m);
    }
    for (const [k, im] of this.meshes) { im.count = used.get(k) ?? 0; if (im.count) im.instanceMatrix.needsUpdate = true; }
    this.s.setScalar(1);
    // the birds
    const counts = new Map<Bird, number>();
    for (const b of this.birds) {
      b.flap += dt * (b.kind === 'goose' ? 7 : 4);
      if (b.line) {
        const L = b.line;
        L.t += dt * 2.2;
        // the V: each rank a little back and out from the one in front
        const back = L.rank * 0.45, out = L.side * L.rank * 0.4;
        b.x = L.x0 + L.dx * (L.t - back) - L.dz * out;
        b.z = L.z0 + L.dz * (L.t - back) + L.dx * out;
        b.yaw = Math.atan2(L.dx, L.dz);
      } else {
        b.a += dt * b.w;
        b.x = b.cx + Math.cos(b.a) * b.r;
        b.z = b.cz + Math.sin(b.a) * b.r;
        b.yaw = Math.atan2(-Math.sin(b.a), Math.cos(b.a));
      }
      const gx = Math.min(N - 0.01, Math.max(0, b.x)), gz = Math.min(N - 0.01, Math.max(0, b.z));
      b.y = heightAt(w, gx, gz) + b.h;
      const set = this.birdMeshes.get(b.kind)!;
      const i = counts.get(b.kind) ?? 0;
      counts.set(b.kind, i + 1);
      if (i >= BIRD_CAP[b.kind]) continue;
      if (b.kind !== 'goose' && night) { set.body.setMatrixAt(i, this.hidden); set.left.setMatrixAt(i, this.hidden); set.right.setMatrixAt(i, this.hidden); continue; }
      // a circler banks into its turn; a goose flies level
      const bank = b.line ? 0 : -0.35;
      this.e.set(0, b.yaw, bank, 'YXZ');
      this.q.setFromEuler(this.e);
      this.v.set(b.x, b.y, b.z);
      this.m.compose(this.v, this.q, this.s);
      set.body.setMatrixAt(i, this.m);
      // the wings beat (a hawk and an eagle mostly glide, a stroke now and then)
      const beat = b.kind === 'goose' ? Math.sin(b.flap) * 0.6 : Math.sin(b.flap) * (Math.sin(b.flap * 0.13) > 0.6 ? 0.5 : 0.08);
      for (const [mesh, sgn] of [[set.right, 1], [set.left, -1]] as [THREE.InstancedMesh, number][]) {
        this.e.set(0, b.yaw, bank + sgn * beat, 'YXZ');
        this.q.setFromEuler(this.e);
        this.m.compose(this.v, this.q, this.s);
        mesh.setMatrixAt(i, this.m);
      }
    }
    for (const [k, set] of this.birdMeshes) {
      const n = Math.min(BIRD_CAP[k], counts.get(k) ?? 0);
      set.body.count = set.left.count = set.right.count = n;
      if (n) { set.body.instanceMatrix.needsUpdate = true; set.left.instanceMatrix.needsUpdate = true; set.right.instanceMatrix.needsUpdate = true; }
    }
    // a skein that has flown on past the county is gone
    this.birds = this.birds.filter((b) => !b.line || b.line.t < b.line.len + 10);
  }

  /** Move an animal toward (tx, tz), keeping off water, roads it would stand in and buildings; turn it the way it goes. */
  private step(w: World, a: Animal, tx: number, tz: number, dist: number): void {
    const dx = tx - a.x, dz = tz - a.z, d = Math.hypot(dx, dz);
    if (d < 1e-3 || dist <= 0) return;
    const s = Math.min(d, dist), nx = a.x + (dx / d) * s, nz = a.z + (dz / d) * s;
    const fx = Math.floor(nx), fz = Math.floor(nz);
    if (!inB(fx, fz)) { a.flee = 0; a.tx = a.x; a.tz = a.z; return; }
    const i = idx(fx, fz);
    if (w.water[i] >= 0 || w.blocked[i] || w.townId[i] >= 0) { a.tx = a.x; a.tz = a.z; return; }
    a.x = nx; a.z = nz;
    const want = Math.atan2(dx, dz);
    let dy = want - a.yaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    a.yaw += Math.max(-0.2, Math.min(0.2, dy));
  }
}
