import { hex, scale, type RGB } from '../../world/biomes';
import { mulberry32, type Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, TAU, WHITE, type Kit, type P3 } from './kit';

/**
 * An aquarium's big tank, seen through its front glass: blue-lit water, sand, rocks, kelp and coral, and
 * the life in it. Every creature is a part of one rig per aquarium, hidden until its turn: every few seconds
 * the tank sends something across behind the glass from one end to the other (a school of fish, a shark, a
 * ray gliding up the glass belly-first, a turtle, jellyfish, a pod of dolphins, an octopus on the sand) and
 * now and then a whale, its species picked per aquarium. The tank runs further than its windows, so each
 * comes in and leaves behind solid wall. At night the water glows and they swim across it in silhouette;
 * the jellyfish glow on their own.
 */

/** The tank lights: on from late afternoon right through the night. */
export const TANK: Sched = [15.5, 31, 1.4];

/** Where the tank is, in the building's frame: its inside from x0 to x1, the window between -wx and wx. */
export interface Tank {
  x0: number; x1: number; wx: number;
  /** Sand, window bottom, window top, ceiling. */
  fl: number; wy0: number; wy1: number; ce: number;
  /** The back wall and the inside of the glass. */
  zb: number; zg: number;
}

// ---- shapes ------------------------------------------------------------------------------------

/**
 * A body round the x axis, nose at +x: `prof` is the girth at even stations from nose to tail (0 closes
 * to a point, anything else is capped flat), the back in `top` and the belly in `under`.
 */
function spindle(k: Kit, x: number, y: number, z: number, len: number, rh: number, rw: number, top: RGB, under: RGB, prof: number[], seg = 6): void {
  const n = prof.length, sx = (i: number) => x + len / 2 - (i / (n - 1)) * len;
  const at = (i: number, s: number): P3 => {
    const a = (s / seg) * TAU, f = prof[i];
    return [sx(i), y + Math.sin(a) * rh * f, z + Math.cos(a) * rw * f];
  };
  const tone = (s: number) => (Math.sin(((s + 0.5) / seg) * TAU) > 0 ? top : under);
  for (let i = 0; i < n - 1; i++) {
    const I: P3 = [(sx(i) + sx(i + 1)) / 2, y, z];
    for (let s = 0; s < seg; s++) {
      const a = at(i, s), b = at(i, s + 1), c = at(i + 1, s + 1), d = at(i + 1, s);
      if (prof[i] === 0) k.tri(a, c, d, tone(s), I);
      else if (prof[i + 1] === 0) k.tri(a, b, c, tone(s), I);
      else k.quad(a, b, c, d, tone(s), I);
    }
  }
  // flat caps on a blunt head or tail
  for (const [i, back] of [[0, -1], [n - 1, 1]] as const) {
    if (prof[i] === 0) continue;
    const C: P3 = [sx(i), y, z], I: P3 = [sx(i) + back * 0.01, y, z];
    for (let s = 0; s < seg; s++) k.tri(C, at(i, s), at(i, s + 1), tone(s), I);
  }
}

/** A flat fin, seen from both sides. */
function fin(k: Kit, a: P3, b: P3, c: P3, col: RGB): void {
  const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
  let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
  const L = Math.hypot(nx, ny, nz) || 1;
  nx = (nx / L) * 0.01; ny = (ny / L) * 0.01; nz = (nz / L) * 0.01;
  const m: P3 = [(a[0] + b[0] + c[0]) / 3, (a[1] + b[1] + c[1]) / 3, (a[2] + b[2] + c[2]) / 3];
  k.tri(a, b, c, col, [m[0] + nx, m[1] + ny, m[2] + nz]);
  k.tri(a, b, c, col, [m[0] - nx, m[1] - ny, m[2] - nz]);
}

/** Flukes spread flat across the tail at x. */
function flukes(k: Kit, x: number, y: number, span: number, col: RGB): void {
  fin(k, [x + 0.02, y, 0], [x - span * 0.45, y + 0.005, span], [x - span * 0.3, y, 0], col);
  fin(k, [x + 0.02, y, 0], [x - span * 0.3, y, 0], [x - span * 0.45, y + 0.005, -span], col);
}

/** A pair of flippers hanging down and back from a root at (x, y), either side of a body rw wide. */
function flippers(k: Kit, x: number, y: number, rw: number, len: number, drop: number, col: RGB): void {
  for (const s of [-1, 1]) fin(k, [x, y, s * rw * 0.9], [x - len * 0.35, y - 0.005, s * rw], [x - len, y - drop, s * (rw + len * 0.3)], col);
}

function eyes(k: Kit, x: number, y: number, rw: number, size = 0.01, col = DARK): void {
  for (const s of [-1, 1]) k.box(x, y - size / 2, s * rw, size, size, 0.006, col);
}

/** A small fish lying along x: a diamond with a tail, its back darker. */
function fishlet(k: Kit, x: number, y: number, z: number, l: number, body: RGB, tail: RGB): void {
  const N: P3 = [x + l / 2, y, z], T: P3 = [x - l * 0.3, y, z], U: P3 = [x, y + l * 0.24, z], D: P3 = [x, y - l * 0.22, z];
  const back = scale(body, 0.72), I: P3 = [x, y, z];
  for (const s of [-1, 1]) {
    const S: P3 = [x + l * 0.05, y, z + s * l * 0.11];
    k.tri(N, U, S, back, I); k.tri(T, U, S, back, I);
    k.tri(N, D, S, body, I); k.tri(T, D, S, body, I);
  }
  fin(k, [x - l * 0.25, y, z], [x - l * 0.6, y + l * 0.22, z], [x - l * 0.6, y - l * 0.22, z], tail);
}

/** A lit bell of a jellyfish with its trailing tentacles. */
function jelly(k: Kit, x: number, y: number, z: number, r: number, day: RGB, glow: RGB): void {
  const seg = 8, rings = 3, I: P3 = [x, y + r * 0.2, z];
  const at = (j: number, s: number): P3 => {
    const p = (j / rings) * (Math.PI / 2), a = (s / seg) * TAU;
    return [x + Math.cos(a) * Math.cos(p) * r, y + Math.sin(p) * r * 0.8, z + Math.sin(a) * Math.cos(p) * r];
  };
  for (let j = 0; j < rings; j++) for (let s = 0; s < seg; s++) {
    if (j === rings - 1) k.glowTri(at(j, s), at(j, s + 1), [x, y + r * 0.8, z], I, day, TANK, glow);
    else k.glowQuad(at(j, s), at(j, s + 1), at(j + 1, s + 1), at(j + 1, s), I, day, TANK, glow);
  }
  const t = scale(day, 0.9);
  for (let s = 0; s < 5; s++) {
    const a = (s / 5) * TAU + 0.3, px = x + Math.cos(a) * r * 0.75, pz = z + Math.sin(a) * r * 0.75;
    k.bar([px, y, pz], [px + Math.cos(a) * r * 0.2, y - r * 1.4, pz], 0.0025, t);
    k.bar([px + Math.cos(a) * r * 0.2, y - r * 1.4, pz], [px - 0.006, y - r * 2.4, pz], 0.002, t);
  }
  k.bar([x, y, z], [x + 0.004, y - r * 1.6, z], 0.006, scale(glow, 0.85));
}

// ---- the creatures, each drawn round its own middle, nose to +x --------------------------------

type Move = 'glide' | 'arc' | 'wiggle' | 'flap' | 'pulse' | 'crawl' | 'school';

interface Kind {
  draw: (k: Kit) => void;
  /** Length along x, height, half its thickness across the tank. */
  len: number; h: number; zr: number;
  speed: number; weight: number; move: Move;
  whale?: boolean;
}

const humpback = (k: Kit) => {
  const top = hex(0x3d4c5f), under = hex(0xd3d9de);
  spindle(k, 0, 0, 0, 0.56, 0.068, 0.06, top, under, [0.35, 0.85, 1, 0.95, 0.8, 0.55, 0.3, 0.14, 0.06], 8);
  flukes(k, -0.26, 0, 0.1, top);
  flippers(k, 0.13, -0.03, 0.05, 0.19, 0.1, hex(0xc4ccd3));
  fin(k, [-0.11, 0.055, 0], [-0.16, 0.08, 0], [-0.19, 0.045, 0], top);
  eyes(k, 0.2, -0.01, 0.056);
  // the grooves under the throat
  for (let i = 0; i < 3; i++) k.bar([0.25, -0.045 - i * 0.008, 0.02], [0.08, -0.06 - i * 0.008, 0.035], 0.002, hex(0xa7b0b8));
};

const orca = (k: Kit) => {
  const black = hex(0x1c2025);
  spindle(k, 0, 0, 0, 0.44, 0.06, 0.054, black, WHITE, [0.3, 0.85, 1, 0.95, 0.75, 0.45, 0.2, 0.08], 8);
  fin(k, [0.03, 0.05, 0], [-0.04, 0.18, 0], [-0.08, 0.045, 0], black);
  flukes(k, -0.2, 0, 0.085, black);
  flippers(k, 0.1, -0.03, 0.045, 0.08, 0.05, black);
  for (const s of [-1, 1]) k.box(0.125, 0.004, s * 0.05, 0.036, 0.012, 0.004, WHITE);
};

const beluga = (k: Kit) => {
  const white = hex(0xe8eef1), under = hex(0xd5dee3);
  spindle(k, 0, 0, 0, 0.4, 0.06, 0.056, white, under, [0.55, 0.95, 1, 0.9, 0.7, 0.45, 0.2, 0.08], 8);
  // the melon on its brow
  spindle(k, 0.15, 0.025, 0, 0.1, 0.04, 0.045, white, white, [0.5, 1, 0.8, 0]);
  flukes(k, -0.18, 0, 0.08, under);
  flippers(k, 0.1, -0.03, 0.045, 0.07, 0.04, under);
  eyes(k, 0.15, 0.0, 0.05, 0.008);
};

const dolphins = (k: Kit) => {
  const top = hex(0x6b7a8a), under = hex(0xdfe4e8);
  for (const [x, y, z] of [[0.06, 0, 0.02], [-0.1, 0.06, -0.025]] as P3[]) {
    spindle(k, x, y, z, 0.2, 0.03, 0.026, top, under, [0.08, 0.35, 0.8, 1, 0.85, 0.5, 0.2, 0.08]);
    fin(k, [x, y + 0.026, z], [x - 0.04, y + 0.065, z], [x - 0.05, y + 0.024, z], top);
    fin(k, [x - 0.08, y, z], [x - 0.12, y + 0.004, z + 0.04], [x - 0.11, y, z], top);
    fin(k, [x - 0.08, y, z], [x - 0.11, y, z], [x - 0.12, y + 0.004, z - 0.04], top);
    for (const s of [-1, 1]) fin(k, [x + 0.04, y - 0.015, z + s * 0.02], [x + 0.02, y - 0.015, z + s * 0.022], [x - 0.01, y - 0.04, z + s * 0.04], top);
    for (const s of [-1, 1]) k.box(x + 0.06, y + 0.002, z + s * 0.022, 0.008, 0.008, 0.005, DARK);
  }
};

const shark = (hammer: boolean) => (k: Kit) => {
  const top = hex(hammer ? 0x7c7a6e : 0x6c7682), under = hex(0xe8e7e1);
  spindle(k, 0, 0, 0, 0.32, 0.044, 0.036, top, under, [0.2, 0.7, 1, 0.9, 0.6, 0.3, 0.12, 0.05]);
  fin(k, [0.03, 0.04, 0], [-0.03, 0.115, 0], [-0.05, 0.035, 0], top);
  fin(k, [-0.15, 0, 0], [-0.215, 0.09, 0], [-0.19, 0, 0], top);
  fin(k, [-0.15, 0, 0], [-0.2, -0.05, 0], [-0.18, 0, 0], top);
  for (const s of [-1, 1]) fin(k, [0.06, -0.02, s * 0.03], [0.0, -0.02, s * 0.034], [-0.03, -0.065, s * 0.075], top);
  // gill slits
  for (let i = 0; i < 3; i++) for (const s of [-1, 1]) k.box(0.08 - i * 0.012, -0.012, s * 0.034, 0.003, 0.022, 0.004, scale(top, 0.6));
  if (hammer) {
    k.box(0.16, -0.008, 0, 0.035, 0.016, 0.15, top);
    for (const s of [-1, 1]) k.box(0.16, -0.004, s * 0.077, 0.012, 0.01, 0.006, DARK);
  } else eyes(k, 0.12, 0.005, 0.03, 0.008);
};

/** A manta stood on its wingtip edge with its white belly to the glass, the way they glide up a tank's window. */
const manta = (k: Kit) => {
  const back = hex(0x2a313b), belly = hex(0xeef0ee);
  const N: P3 = [0.07, 0, 0], U: P3 = [-0.035, 0.14, 0], Dn: P3 = [-0.035, -0.14, 0], T: P3 = [-0.075, 0, 0];
  const F: P3 = [0, 0, 0.018], B: P3 = [0, 0, -0.02];
  for (const [a, b] of [[N, U], [U, T], [T, Dn], [Dn, N]] as [P3, P3][]) {
    k.tri(F, a, b, belly, B);
    k.tri(B, a, b, back, F);
  }
  // dark edges to the wings, the horns either side of the mouth, gill slits and the whip of a tail
  for (const s of [-1, 1]) {
    fin(k, [-0.01, s * 0.1, 0.006], [-0.035, s * 0.14, 0], [-0.045, s * 0.1, 0.004], back);
    fin(k, [0.06, s * 0.012, 0.004], [0.095, s * 0.03, 0.006], [0.07, s * 0.03, 0.002], back);
    for (let i = 0; i < 3; i++) k.box(0.025 - i * 0.012, s * 0.03 - 0.002, 0.012, 0.004, 0.004 * (i + 2), 0.004, hex(0x9aa0a8));
  }
  k.box(0.072, -0.006, 0.004, 0.006, 0.012, 0.006, DARK);
  k.bar(T, [-0.2, 0.005, 0], 0.004, back);
};

const turtle = (k: Kit) => {
  const shell = hex(0x5b7838), under = hex(0xd8c88a), skin = hex(0x8b9c5c);
  spindle(k, 0, 0, 0, 0.16, 0.035, 0.06, shell, under, [0.3, 0.85, 1, 0.9, 0.5], 8);
  // plates on the shell
  for (const [x, z] of [[0.03, 0], [-0.025, 0], [0, 0.03], [0, -0.03]]) k.box(x, 0.028, z, 0.026, 0.008, 0.022, hex(0x7a8f45));
  spindle(k, 0.1, 0.004, 0, 0.055, 0.016, 0.015, skin, skin, [0.6, 1, 0.8, 0.6]);
  eyes(k, 0.115, 0.01, 0.014, 0.006);
  for (const s of [-1, 1]) {
    fin(k, [0.05, -0.008, s * 0.045], [0.02, -0.01, s * 0.055], [-0.05, -0.06, s * 0.085], skin);
    fin(k, [-0.06, -0.008, s * 0.035], [-0.075, -0.008, s * 0.04], [-0.1, -0.025, s * 0.06], skin);
  }
};

const sunfish = (k: Kit) => {
  const body = hex(0xa6b0b5), side = hex(0x8c979d), n = 12, rx = 0.07, ry = 0.075, t = 0.016;
  const at = (i: number, z: number): P3 => [Math.cos((i / n) * TAU) * rx, Math.sin((i / n) * TAU) * ry, z];
  for (let i = 0; i < n; i++) {
    k.tri([0, 0, t], at(i, t * 0.6), at(i + 1, t * 0.6), body, [0, 0, -t]);
    k.tri([0, 0, -t], at(i, -t * 0.6), at(i + 1, -t * 0.6), body, [0, 0, t]);
    k.quad(at(i, t * 0.6), at(i + 1, t * 0.6), at(i + 1, -t * 0.6), at(i, -t * 0.6), side, [0, 0, 0]);
  }
  fin(k, [0.0, 0.06, 0], [-0.035, 0.17, 0], [-0.06, 0.05, 0], side);
  fin(k, [0.0, -0.06, 0], [-0.035, -0.17, 0], [-0.06, -0.05, 0], side);
  k.box(-0.075, -0.05, 0, 0.018, 0.1, 0.012, side);
  eyes(k, 0.04, 0.02, t * 0.65, 0.01);
  k.box(0.065, -0.01, 0, 0.008, 0.012, 0.012, DARK);
};

const octopus = (k: Kit) => {
  const col = hex(0xc9532f), pale = hex(0xe6936c);
  // the arms spread over the sand, each curling at its tip; then the head and the mantle draped back
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.2, c = i % 2 ? 0.6 : -0.6;
    const p = (rr: number, da: number, y: number): P3 => [Math.cos(a + da) * rr, y, Math.sin(a + da) * rr * 0.65];
    k.bar(p(0.015, 0, 0.022), p(0.055, 0.15 * c, 0.008), 0.008, col);
    k.bar(p(0.055, 0.15 * c, 0.008), p(0.09, 0.45 * c, 0.01), 0.006, col);
    k.bar(p(0.09, 0.45 * c, 0.01), p(0.095, 0.9 * c, 0.03), 0.004, pale);
  }
  k.cyl(0, 0.01, 0, 0.026, 0.03, col, 8);
  spindle(k, -0.03, 0.065, 0, 0.09, 0.034, 0.03, col, pale, [0.7, 1, 0.95, 0.6, 0], 8);
  for (const s of [-1, 1]) {
    k.box(0.012, 0.045, s * 0.022, 0.014, 0.014, 0.008, hex(0xf2e6c8));
    k.box(0.016, 0.047, s * 0.025, 0.006, 0.008, 0.006, DARK);
  }
};

const jellies = (day: number, glow: number) => (k: Kit) => {
  for (const [x, y, z, r] of [[0, 0.03, 0, 0.034], [0.09, 0.09, -0.02, 0.026], [-0.085, -0.03, 0.02, 0.024]]) jelly(k, x, y, z, r, hex(day), hex(glow));
};

/** A school of n fish of length l in a lens rx by ry, coloured from `cols` ([body, tail] pairs). */
const school = (n: number, l: number, rx: number, ry: number, cols: [number, number][], seed: number) => (k: Kit) => {
  const r = mulberry32(seed);
  for (let i = 0; i < n; i++) {
    const a = r() * TAU, d = Math.sqrt(r());
    const [b, t] = cols[i % cols.length];
    fishlet(k, Math.cos(a) * d * rx, Math.sin(a) * d * ry, (r() - 0.5) * 0.08, l * (0.85 + r() * 0.3), hex(b), hex(t));
  }
};

/** Bubbles rising in two columns from the sand; the tick slides them up a spacing at a time. */
const BUBBLE_GAP = 0.055;
const bubbles = (t: Tank, xs: number[]) => (k: Kit) => {
  const col = hex(0xdff4ff), n = Math.floor((t.ce - t.fl - 0.02) / BUBBLE_GAP) - 1;
  for (const x of xs) for (let j = 0; j < n; j++) {
    const s = 0.008 + (j % 3) * 0.003;
    k.box(x + Math.sin(j * 2.1) * 0.01, t.fl + j * BUBBLE_GAP, t.zb + 0.035, s, s, s, col);
  }
};

// ---- the tank itself ---------------------------------------------------------------------------

const SAND = hex(0xc9c49c), ROCK = [0x5d656c, 0x515a62, 0x6a6a62], KELP = hex(0x3f8a3a), KELP2 = hex(0x5c9c3c);
const CORAL = [0xf07a9a, 0xf29a3b, 0x9a6ad8, 0xf2d04a];

/** The scenery on the tank floor and against its back wall. */
function scenery(k: Kit, t: Tank, r: Rng, murky: boolean): void {
  const depth = t.zg - t.zb;
  // the sand floor
  k.box((t.x0 + t.x1) / 2, 0, (t.zb + t.zg) / 2, t.x1 - t.x0, t.fl, depth, murky ? hex(0x8a8466) : hex(0xb8b0a0), murky ? hex(0x7d7a5a) : SAND);
  // rocks heaped along the back
  for (let x = t.x0 + 0.08; x < t.x1 - 0.05; x += 0.16 + r() * 0.22) {
    const w = 0.05 + r() * 0.07, h = 0.03 + r() * 0.04, col = hex(ROCK[Math.floor(r() * ROCK.length)]);
    const z = t.zb + 0.015 + w * 0.3;
    k.hip(x, t.fl, z, w, h, w * 0.7, col);
    k.hip(x + w * 0.35, t.fl, z + 0.012, w * 0.6, h * 0.65, w * 0.5, scale(col, 0.85));
  }
  if (murky) return;
  // kelp swaying up the back wall
  for (let x = t.x0 + 0.1; x < t.x1 - 0.05; x += 0.22 + r() * 0.25) {
    const h = 0.18 + r() * (t.wy1 - t.fl - 0.18), z = t.zb + 0.02 + r() * 0.03, col = r() < 0.5 ? KELP : KELP2;
    let p: P3 = [x, t.fl, z];
    for (let j = 1; j <= 4; j++) {
      const q: P3 = [x + (j % 2 ? 0.018 : -0.012), t.fl + (h * j) / 4, z];
      k.bar(p, q, 0.006, col);
      fin(k, q, [q[0] + 0.03, q[1] - 0.02, z + 0.004], [q[0] + 0.004, q[1] - 0.035, z], col);
      p = q;
    }
  }
  // coral heads and fans on the sand, a starfish or two near the glass
  for (let x = t.x0 + 0.15; x < t.x1 - 0.1; x += 0.25 + r() * 0.3) {
    const col = hex(CORAL[Math.floor(r() * CORAL.length)]), z = t.zb + 0.05 + r() * depth * 0.4;
    if (r() < 0.5) {
      for (let j = 0; j < 4; j++) {
        const a = j * 1.7;
        k.bar([x, t.fl, z], [x + Math.cos(a) * 0.025, t.fl + 0.035 + j * 0.008, z + Math.sin(a) * 0.015], 0.006, col);
      }
    } else fin(k, [x - 0.01, t.fl, z], [x - 0.05, t.fl + 0.07, z], [x + 0.04, t.fl + 0.075, z], col);
  }
  for (let i = 0; i < 2; i++) {
    const x = -t.wx + 0.15 + r() * (t.wx * 2 - 0.3), z = t.zg - 0.03, y = t.fl + 0.003, col = hex(i ? 0xe2662f : 0xf2a03b);
    for (let a = 0; a < 5; a++) {
      const g = (a / 5) * TAU;
      k.tri([x, y + 0.004, z], [x + Math.cos(g) * 0.025, y, z + Math.sin(g) * 0.025], [x + Math.cos(g + 0.6) * 0.008, y, z + Math.sin(g + 0.6) * 0.008], col, [x, y - 0.01, z]);
      k.tri([x, y + 0.004, z], [x + Math.cos(g - 0.6) * 0.008, y, z + Math.sin(g - 0.6) * 0.008], [x + Math.cos(g) * 0.025, y, z + Math.sin(g) * 0.025], col, [x, y - 0.01, z]);
    }
  }
}

/** The water lit behind and above, in bands paler toward the light. */
function water(k: Kit, t: Tank, murky: boolean): void {
  const z = t.zb + 0.006, cut = [t.fl, t.fl + (t.ce - t.fl) * 0.35, t.fl + (t.ce - t.fl) * 0.7, t.ce];
  const day = murky ? [0x46604a, 0x4f6a50, 0x587458] : [0x2479a2, 0x3192bb, 0x52b2d2];
  const glow = murky ? [0x000000, 0x000000, 0x000000] : [0x1fa4c4, 0x2fc2da, 0x6fdeec];
  for (let i = 0; i < 3; i++) {
    k.glowQuad([t.x0, cut[i], z], [t.x1, cut[i], z], [t.x1, cut[i + 1], z], [t.x0, cut[i + 1], z], [0, cut[i], z - 0.05], hex(day[i]), TANK, hex(glow[i]));
  }
  if (!murky) {
    // the lights in the tank's lid, seen from below
    const y = t.ce, zc = (t.zb + t.zg) / 2;
    k.glowQuad([t.x0, y, t.zb], [t.x1, y, t.zb], [t.x1, y, t.zg], [t.x0, y, t.zg], [0, y + 0.05, zc], hex(0x9cd8ea), TANK, hex(0xa8f2ff));
  }
}

interface Swim { on: boolean; x: number; y: number; z: number; dir: number; speed: number; t: number }

/** Draw the tank's water, scenery and life: `murky` (a derelict aquarium) is green, dark and empty. */
export function seaTank(k: Kit, t: Tank, r: Rng, murky = false): void {
  water(k, t, murky);
  scenery(k, t, r, murky);
  if (murky) return;
  const seed = Math.floor(r() * 2 ** 31), rnd = mulberry32(seed);
  const pickW = rnd();
  const whale: Kind = pickW < 0.45
    ? { draw: humpback, len: 0.56, h: 0.24, zr: 0.07, speed: 0.11, weight: 0, move: 'glide', whale: true }
    : pickW < 0.75
      ? { draw: orca, len: 0.44, h: 0.26, zr: 0.065, speed: 0.17, weight: 0, move: 'glide', whale: true }
      : { draw: beluga, len: 0.42, h: 0.16, zr: 0.065, speed: 0.12, weight: 0, move: 'glide', whale: true };
  const kinds: Kind[] = [
    whale,
    { draw: dolphins, len: 0.38, h: 0.15, zr: 0.06, speed: 0.42, weight: 1.2, move: 'arc' },
    { draw: shark(rnd() < 0.3), len: 0.36, h: 0.17, zr: 0.08, speed: 0.26, weight: 1.3, move: 'wiggle' },
    { draw: manta, len: 0.3, h: 0.28, zr: 0.03, speed: 0.15, weight: 1, move: 'flap' },
    { draw: turtle, len: 0.2, h: 0.1, zr: 0.08, speed: 0.1, weight: 0.9, move: 'glide' },
    { draw: sunfish, len: 0.16, h: 0.34, zr: 0.02, speed: 0.06, weight: 0.5, move: 'glide' },
    { draw: octopus, len: 0.22, h: 0.12, zr: 0.07, speed: 0.045, weight: 0.6, move: 'crawl' },
    { draw: jellies(0xf2b8d8, 0xff86c8), len: 0.24, h: 0.24, zr: 0.06, speed: 0.05, weight: 0.7, move: 'pulse' },
    { draw: jellies(0xcfe6f6, 0x8fe4ff), len: 0.24, h: 0.24, zr: 0.06, speed: 0.045, weight: 0.6, move: 'pulse' },
    { draw: school(24, 0.034, 0.17, 0.07, [[0xc9d6de, 0x8fa3b0]], seed + 1), len: 0.38, h: 0.16, zr: 0.06, speed: 0.34, weight: 2, move: 'school' },
    { draw: school(10, 0.05, 0.14, 0.06, [[0xf5d23a, 0xf5d23a]], seed + 2), len: 0.32, h: 0.14, zr: 0.06, speed: 0.24, weight: 1.6, move: 'school' },
    { draw: school(12, 0.045, 0.15, 0.07, [[0x2f66d6, 0xf2d03b], [0xf2792a, 0xf4f2ec], [0xd04a9a, 0xd04a9a], [0xe8e04a, 0x2f66d6]], seed + 3), len: 0.34, h: 0.16, zr: 0.06, speed: 0.2, weight: 1.6, move: 'school' },
  ];
  const sw: Swim[] = kinds.map(() => ({ on: false, x: 0, y: 0, z: 0, dir: 1, speed: 0, t: 0 }));
  let next = 1, sinceWhale = 30 + rnd() * 40, clock = rnd() * 100;

  const launch = (i: number) => {
    const kd = kinds[i], s = sw[i];
    s.dir = rnd() < 0.5 ? 1 : -1;
    s.x = s.dir > 0 ? t.x0 + kd.len / 2 : t.x1 - kd.len / 2;
    s.speed = kd.speed * (0.85 + rnd() * 0.3);
    s.t = rnd() * 10;
    // kept well under the lintel: looked at from above, the top of the tank hides behind it
    const lo = Math.max(t.fl + kd.h / 2 + 0.01, t.wy0 + kd.h * 0.2), hi = Math.max(lo, Math.min(t.ce - kd.h / 2 - 0.01, t.wy1 - kd.h * 0.5 - 0.05));
    s.y = kd.move === 'crawl' ? t.fl : lo + rnd() * Math.max(0, hi - lo);
    // a lane across the tank as far as can be from whatever else is swimming
    const zlo = t.zb + kd.zr + 0.01, zhi = Math.max(zlo, t.zg - kd.zr - 0.01);
    let best = (zlo + zhi) / 2, far = -1;
    for (let c = 0; c < 4; c++) {
      const z = zlo + rnd() * (zhi - zlo);
      let d = 1;
      sw.forEach((o, j) => { if (o.on && j !== i && Math.abs(o.x - s.x) < 0.6) d = Math.min(d, Math.abs(o.z - z)); });
      if (d > far) { far = d; best = z; }
    }
    s.z = kd.move === 'crawl' ? t.zb + (t.zg - t.zb) * 0.6 : best;
    s.on = true;
  };

  /** The tank's life, run on: swimmers move on and leave, and every few seconds another sets off. */
  const step = (dt: number) => {
    clock += dt; sinceWhale += dt; next -= dt;
    sw.forEach((s, i) => {
      if (!s.on) return;
      s.x += s.dir * s.speed * dt; s.t += dt;
      if (s.dir > 0 ? s.x > t.x1 - kinds[i].len / 2 : s.x < t.x0 + kinds[i].len / 2) s.on = false;
    });
    if (next > 0) return;
    next = 1.5 + rnd() * 4.5;
    if (sw.filter((s) => s.on).length >= 4) { next = 1; return; }
    if (!sw[0].on && (sinceWhale > 80 || (sinceWhale > 35 && rnd() < 0.2))) { sinceWhale = 0; launch(0); return; }
    let total = 0;
    kinds.forEach((kd, i) => { if (!sw[i].on) total += kd.weight; });
    let pick = rnd() * total;
    for (let i = 1; i < kinds.length; i++) {
      if (sw[i].on) continue;
      pick -= kinds[i].weight;
      if (pick <= 0) { launch(i); return; }
    }
  };
  // a tank already going when it comes into view
  for (let i = 0; i < 160; i++) step(0.25);

  const parts = [...kinds.map((kd) => kd.draw), bubbles(t, [t.x0 + (t.x1 - t.x0) * 0.33, t.x0 + (t.x1 - t.x0) * 0.71])];
  k.rig(0, 0, 0, parts, (objs, dt) => {
    step(dt);
    const bub = objs[objs.length - 1];
    bub.position.y = ((clock * 0.09) % BUBBLE_GAP);
    sw.forEach((s, i) => {
      const o = objs[i];
      o.visible = s.on;
      if (!s.on) return;
      const m = kinds[i].move, w = s.t;
      let y = s.y + Math.sin(w * 0.7) * 0.01, pitch = 0, yaw = 0, sy = 1;
      if (m === 'arc') { y = s.y + Math.sin(w * 2.2) * 0.05; pitch = Math.cos(w * 2.2) * 0.45; }
      else if (m === 'wiggle') yaw = Math.sin(w * 3.1) * 0.12;
      else if (m === 'flap') { sy = 1 + Math.sin(w * 1.8) * 0.12; y = s.y + Math.sin(w * 0.9) * 0.03; pitch = Math.sin(w * 0.9) * 0.15; }
      else if (m === 'pulse') { sy = 1 + Math.sin(w * 2.4) * 0.1; y = s.y + Math.sin(w * 0.6) * 0.04; }
      else if (m === 'crawl') { y = s.y; sy = 1 + Math.sin(w * 1.3) * 0.07; }
      else if (m === 'school') { yaw = Math.sin(w * 1.3) * 0.18; sy = 1 + Math.sin(w * 0.8) * 0.12; y = s.y + Math.sin(w * 0.5) * 0.025; }
      else pitch = Math.sin(w * 0.5) * 0.05;
      o.position.set(s.x, y, s.z);
      o.rotation.set(0, yaw, pitch * s.dir);
      o.scale.set(s.dir, sy, 1);
    });
  });
}
