import { DEPOT_OF, FACTIONS, FACTION_IDS, depotModels, fcss, type FactionId } from './factions/factions';
import { FACTION_LABEL, type FactionKind } from '../world/factionKinds';
import { idx, inB, type Building, type RailStation, type Town, type TownKind, type World } from '../world/tiles';
import { hashString, mulberry32 } from '../world/rng';
import { runwaysOf } from '../world/runways';
import { berthOf, storefronts } from '../world/storefronts';
import { surfaceY } from './cargo';
import { standNear } from './stash';
import { ALL_VEHICLES, type MenuGroup, type VehicleDef } from './vehicles';
import { SLOTS, type SlotId } from './parts';
import { TECH_BY_ID, isStarter } from './tech';
import type { DoorMotif, DoorTheme } from '../render/doorMarker';

/**
 * Vehicle Shops and Vehicle Dealers: the places the fleet buys from. Each is a door on the map, an
 * entrance ring like the first drive's auto shop, stopped in and gone into with Space.
 *
 * - A **shop** sells parts for the workshop: 3–5 kinds of upgrade at a time.
 * - A **dealer** sells vehicles of one trade (land, air or sea): 2–6 models at a time for cars, 1–3 for boats and aircraft.
 *
 * Every cell with a town has exactly one shop; a cell with a small city may have a dealer too, and a cell
 * with a big city or a metropolis always has one. Never two of either in one cell.
 *
 * Trains are sold only by **train dealers** (trade `rail`, 6 Oct 2026): rare, one at most to a cell, at the
 * door of its grandest staffed station: most termini have one, some city stations, a few town stations,
 * never a halt or a goods yard. Car, aircraft and boat dealers never sell trains. Where they stand the
 * world decides as it is made (world/storefronts.ts), in real garages and dealerships; what they stock and how their prices run is
 * a hash of the seed, the place and the game year, so it changes each year and is the same for everyone
 * who asks. The prices are the list price times the place's roll for the year, less the town's regard
 * for the fleet (mission standing) and the place's own regard (what the fleet has spent there).
 */

type OutletKind = 'shop' | 'dealer';
export type Trade = 'land' | 'air' | 'sea' | 'rail';

export interface Outlet {
  /** "cx,cz#shop", "cx,cz#dealer" (the first), "cx,cz#dealer-sea" / "cx,cz#dealer-air" (a second), or "cx,cz#rail" (a train dealer). */
  key: string;
  kind: OutletKind;
  /** A dealer's trade; a shop has none. */
  trade?: Trade;
  name: string;
  icon: string;
  cx: number; cz: number;
  /** The door, in the cell's own tiles, and in world tiles. */
  lx: number; lz: number; x: number; z: number; y: number;
  /** The town it trades in, keyed like the ledger ("cx,cz#id"), with its name and size. */
  town: string; townName: string; townKind: TownKind;
  /** The longest runway in the cell, for which jets an air dealer can deliver; 0 without one. */
  runway: number;
  /** The building it is in, when it has one (a boat dealer's berth on the quay has none). */
  b?: Building;
  /** A faction's depot (docs/factions.html): it sells only that faction's models, and only once earned. */
  faction?: FactionId;
}

export const TRADE_GROUP: Record<Trade, MenuGroup> = { land: 'road', air: 'sky', sea: 'water', rail: 'rail' };
export const TRADE_LABEL: Record<Trade, string> = { land: 'cars & trucks', air: 'aircraft', sea: 'boats', rail: 'trains' };
const TRADE_ICON: Record<Trade, string> = { land: '🚗', air: '✈️', sea: '⛵', rail: '🚂' };
/** A cell's chance of a train dealer at its grandest station, by the station's kind: rare, and only where trains are staffed. */
const RAIL_DEALER_CHANCE: Partial<Record<RailStation['kind'], number>> = { terminus: 0.2, cityStation: 0.1, townStation: 0.04 };
const STATION_RANK: RailStation['kind'][] = ['terminus', 'cityStation', 'townStation'];
const SHOP_ICON = '🔧';
export const KIND_LABEL: Record<OutletKind, string> = { shop: 'Vehicle Shop', dealer: 'Vehicle Dealer' };
/** How many models a dealer's floor holds in a year, fewest and most, by trade: a car dealer up to six. */
const DEALER_FLOOR: Partial<Record<Trade, [number, number]>> = { land: [2, 6], sea: [1, 3], air: [1, 3], rail: [1, 3] };

const townKey = (w: World, t: Town) => `${w.cx},${w.cz}#${t.id}`;

/**
 * Where the cell's shop and dealer stand, if it has towns. The world made them (world/storefronts.ts): the
 * shop is a garage and a land dealer a car dealership, each with its ring on the kerb out front; a boat
 * dealer keeps a berth on the quay and an aircraft dealer a stand on the apron. Pure: the same world
 * always gives the same answer.
 */
export function placeOutlets(w: World): Outlet[] {
  const towns = w.towns.filter((t) => t.buildings.length);
  if (!towns.length) return [];
  const runway = runwaysOf(w).reduce((m, r) => Math.max(m, r.len), 0);
  const out: Outlet[] = [];
  // a cell's first dealer keeps the old key ("#dealer"), so a save's loyalty and sold stock still find it; a
  // boat or aircraft dealer beside a car dealer is "#dealer-sea" / "#dealer-air"
  let dealers = 0;
  const keyOf = (kind: OutletKind, trade?: Trade) => (trade === 'rail' ? 'rail' : kind === 'dealer' && dealers++ > 0 ? `dealer-${trade}` : kind);
  const make = (kind: OutletKind, t: Town, at: { x: number; z: number }, name: string, icon: string, b?: Building, trade?: Trade): Outlet => ({
    key: `${w.cx},${w.cz}#${keyOf(kind, trade)}`, kind, trade, name, icon, cx: w.cx, cz: w.cz,
    lx: at.x, lz: at.z, x: at.x + w.ox, z: at.z + w.oz, y: surfaceY(w, at.x, at.z),
    town: townKey(w, t), townName: t.name, townKind: t.kind, runway, b,
  });
  const nearestTown = (p: { x: number; z: number }) => [...towns].sort((a, b) =>
    Math.hypot(a.x0 + a.size / 2 - p.x, a.z0 + a.size / 2 - p.z) - Math.hypot(b.x0 + b.size / 2 - p.x, b.z0 + b.size / 2 - p.z))[0];

  for (const trade of [w.dealerTrade, ...(w.dealerExtra ?? [])]) {
  if (trade === 'land') {
    const got = storefronts(w, 'dealer')[0];
    if (got) out.push(make('dealer', got.t, got.at, `${got.t.name} Motors`, TRADE_ICON.land, got.b, 'land'));
  } else if (trade === 'sea') {
    const berth = berthOf(w, null);
    const port = berth ? w.ports.find((p) => p.id === berth.port) : undefined;
    if (berth && port) {
      const t = port.town >= 0 ? w.towns.find((q) => q.id === port.town) ?? nearestTown(berth) : nearestTown(berth);
      const base = port.name.replace(/(\s+(Harbour|Harbor|Port|Docks|Quay|Pier|Wharf|Landing))+$/i, '') || port.name;
      out.push(make('dealer', t, berth, `${base} Marine`, TRADE_ICON.sea, undefined, 'sea'));
    }
  } else if (trade === 'air') {
    const runways = runwaysOf(w);
    const rw = [...runways].sort((a, b) => Number(b.major) - Number(a.major) || b.len - a.len)[0];
    if (rw) {
      // the far stand from the one the airport's own work waits at, stepped back off the apron's edge
      const st = rw.stands[rw.stands.length - 1];
      const at = { x: st.x - w.ox - Math.sin(st.heading) * 2.5, z: st.z - w.oz - Math.cos(st.heading) * 2.5 };
      const ok = inB(Math.floor(at.x), Math.floor(at.z)) && w.edges[idx(Math.floor(at.x), Math.floor(at.z))] && w.water[idx(Math.floor(at.x), Math.floor(at.z))] < 0;
      // no dry apron there (a stand over a channel): the nearest ground a car can stop on
      const spot = ok ? at : standNear(w, st.x - w.ox, st.z - w.oz, 8, false) ?? { x: st.x - w.ox, z: st.z - w.oz };
      const base = rw.name.replace(/(\s+(Municipal|Regional|International|Intl\.?|Airport|Airfield|Aerodrome|Field|Airstrip))+$/i, '') || rw.name;
      out.push(make('dealer', nearestTown(spot), spot, `${base} Aviation`, TRADE_ICON.air, undefined, 'air'));
    }
  }
  }
  const shop = storefronts(w, 'shop')[0];
  if (shop) out.push(make('shop', shop.t, shop.at, `${shop.t.name} Auto Shop`, SHOP_ICON, shop.b));
  const rail = trainDealer(w);
  if (rail) out.push(make('dealer', w.towns.find((t) => t.id === rail.st.town) ?? nearestTown(rail.at), rail.at, `${rail.st.name} Rolling Stock`, TRADE_ICON.rail, undefined, 'rail'));
  // each faction's depot in the cell, the first of its kind: a counter for that faction's own vehicles (docs/factions.html)
  for (const f of FACTION_IDS) {
    const b = w.allBuildings.find((q) => q.kind === DEPOT_OF[f] && !q.gone);
    if (!b) continue;
    const at = standNear(w, b.x + b.w / 2, b.z + b.d / 2, Math.max(b.w, b.d) + 3, false);
    if (!at) continue;
    // "Army depot", not "Army Army depot"
    const label = FACTION_LABEL[b.kind as FactionKind] ?? 'depot';
    const o = make('dealer', nearestTown(at), at, label.startsWith(FACTIONS[f].short) ? label : `${FACTIONS[f].short} ${label}`, FACTIONS[f].icon, b, 'land');
    o.key = `${w.cx},${w.cz}#fac-${f}`;
    o.faction = f;
    out.push(o);
  }
  return out;
}

/** Each faction depot's ring: the pattern round its mat, after what the faction is. */
const DEPOT_MOTIF: Record<FactionId, DoorMotif> = {
  police: 'checker', family: 'pinstripe', ministry: 'seal', visitors: 'crop', unions: 'hazard',
  post: 'airmail', army: 'camo', studios: 'film', guild: 'rope', press: 'newsprint',
};

/** A faction depot's door in the faction's own colours and motif, not the auto shop's red-and-cream stripes. */
export function doorTheme(f: FactionId): DoorTheme {
  const F = FACTIONS[f];
  return { body: fcss(F.colour), accent: fcss(F.accent), glyph: F.glyph, motif: DEPOT_MOTIF[f] };
}

/**
 * The cell's train dealer, if it has one: at the door of its grandest staffed station (a terminus before a
 * city station before a town station), on a roll of the seed and the cell against RAIL_DEALER_CHANCE.
 * Pure, so every load and every player finds the same one.
 */
function trainDealer(w: World): { st: RailStation; at: { x: number; z: number } } | null {
  const st = [...w.stations].filter((s) => s.building && !s.building.gone && STATION_RANK.includes(s.kind))
    .sort((a, b) => STATION_RANK.indexOf(a.kind) - STATION_RANK.indexOf(b.kind))[0];
  if (!st || !st.building) return null;
  if (mulberry32(hashString(`${w.seed}|${w.cx},${w.cz}|traindealer`))() >= (RAIL_DEALER_CHANCE[st.kind] ?? 0)) return null;
  const b = st.building;
  // on the forecourt: the nearest ground a car can stop on beside the station's front
  const at = standNear(w, b.x + b.w / 2, b.z + b.d / 2, Math.max(b.w, b.d) / 2 + 4, false);
  return at ? { st, at } : null;
}

// ---- terms -----------------------------------------------------------------------------------------

/** What the fleet has spent at a place, and what that makes it there. */
const LOYALTY: { at: number; name: string; off: number }[] = [
  { at: 0, name: 'New customer', off: 0 },
  { at: 1500, name: 'Known face', off: 0.03 },
  { at: 6000, name: 'Regular', off: 0.06 },
  { at: 20000, name: 'Valued customer', off: 0.09 },
  { at: 60000, name: 'Friend of the house', off: 0.12 },
];
/** Off the price for each step of the town's standing with the fleet (0–4). */
const STANDING_OFF = 0.03;
/** Off everything at a shop or a dealership whose building the fleet owns (docs/property.html). */
const OWNED_OFF = 0.1;
/** The yearly roll's range: a place's prices this year run from 20% under list to 30% over. */
const ROLL_LO = 0.8, ROLL_HI = 1.3;

type Deal = 'good' | 'fair' | 'bad';
export const DEAL_LABEL: Record<Deal, string> = { good: 'Good prices', fair: 'Fair prices', bad: 'Steep prices' };

interface Terms {
  year: number;
  /** This year's roll for the place, and what it amounts to. */
  roll: number; deal: Deal;
  /** The town's standing (0–4) and what it takes off. */
  standing: number; standingOff: number;
  /** The place's own regard: what has been spent there, its step, and what that takes off. */
  spent: number; loyal: number; loyalName: string; loyalOff: number;
  /** The fleet owns the building: 10% off. */
  ownedOff: number;
  /** Everything together: list × mul is the price. */
  mul: number;
}

interface OutletsHost {
  seed(): string;
  /** The game year: game days over days-per-year. */
  year(): number;
  /** Game days until the next year's stock comes in (at midnight), counting today as one. */
  restockIn?(): number;
  /** A town's standing with the fleet, 0–4, keyed "cx,cz#id". */
  standing(town: string): number;
  /** May this model be sold yet (the tech trees, docs/territory.html)? Absent: everything may. */
  unlocked?(id: string): boolean;
  /** Does the fleet own this place's building? */
  owns?(o: Outlet): boolean;
}

/** How long a depot's open-or-shut answer is kept, in ms: an earned model shows its ring within this. */
const OPEN_FOR = 500;

/** Rounded to the nearest $10, as every price in the game is. */
export const r10 = (v: number): number => Math.round(v / 10) * 10;

/** The dealer models a trade can carry: its menu group (trains only at a train dealer). */
export function tradeModels(trade: Trade): VehicleDef[] {
  return ALL_VEHICLES.filter((d) => d.group === TRADE_GROUP[trade]);
}

export class Outlets {
  /** Every cell's places seen this session, by cell key. */
  private cells = new Map<string, Outlet[]>();
  /** Dollars the fleet has spent at each place, by outlet key. Saved. */
  readonly spent = new Map<string, number>();
  /**
   * What each dealer has sold this year (docs/hqwindow.html): a dealer holds one of each model it stocks,
   * so a model bought there is gone from its floor until the new year's stock comes in. "key|year" → models.
   */
  private sold = new Map<string, Set<string>>();

  constructor(private host: OutletsHost) {}

  /** The cell's places: found once per cell and kept. */
  of(w: World): Outlet[] {
    const k = `${w.cx},${w.cz}`;
    let list = this.cells.get(k);
    if (!list) { list = placeOutlets(w); this.cells.set(k, list); }
    return list;
  }

  /** The cell's places still standing: a shop or dealership that was knocked down is gone. */
  live(w: World): Outlet[] { return this.of(w).filter((o) => !o.b?.gone); }

  /** Everything seen so far. */
  known(): Outlet[] { return [...this.cells.values()].flat(); }

  /**
   * Is it open to this player? Every shop is; a dealer only while it has something on its floor this year (the
   * user, 5 Nov 2026: a Rolling Stock dealer with no train unlocked stood open with nothing to sell), and a
   * faction's depot only once something it sells has been earned. Until then its ring isn't drawn and it is never
   * named as the nearest dealer. Asked every frame for each dealer's ring, so the answer is kept for a moment.
   */
  open(o: Outlet): boolean {
    if (o.kind !== 'dealer') return true;
    const now = performance.now(), had = this.opened.get(o.key);
    if (had && now - had.at < OPEN_FOR) return had.v;
    const v = this.models(o).length > 0;
    this.opened.set(o.key, { at: now, v });
    return v;
  }
  private opened = new Map<string, { at: number; v: boolean }>();

  byKey(key: string): Outlet | undefined {
    return this.cells.get(key.split('#')[0])?.find((o) => o.key === key);
  }

  /** Game days until every place restocks: 1 means tonight at midnight. */
  restockIn(): number { return this.host.restockIn?.() ?? 0; }

  /** A new world: forget every place and every account. */
  reset(): void { this.cells.clear(); this.spent.clear(); this.sold.clear(); }

  private rng(o: Outlet, what: string, year = this.host.year()): () => number {
    return mulberry32(hashString(`${what}|${this.host.seed()}|${o.key}|${year}`));
  }

  terms(o: Outlet): Terms {
    const year = this.host.year();
    const roll = ROLL_LO + (ROLL_HI - ROLL_LO) * this.rng(o, 'roll', year)();
    const deal: Deal = roll < 0.93 ? 'good' : roll > 1.12 ? 'bad' : 'fair';
    const standing = Math.max(0, Math.min(4, this.host.standing(o.town)));
    const spent = this.spent.get(o.key) ?? 0;
    let loyal = 0;
    for (let i = 0; i < LOYALTY.length; i++) if (spent >= LOYALTY[i].at) loyal = i;
    const standingOff = standing * STANDING_OFF, loyalOff = LOYALTY[loyal].off;
    const ownedOff = o.b && this.host.owns?.(o) ? OWNED_OFF : 0;
    return {
      year, roll, deal, standing, standingOff, spent, loyal, loyalName: LOYALTY[loyal].name, loyalOff, ownedOff,
      mul: roll * (1 - standingOff) * (1 - loyalOff) * (1 - ownedOff),
    };
  }

  /** What something on the list at `list` costs here now. */
  price(o: Outlet, list: number): number {
    if (list <= 0) return 0;
    return Math.max(10, r10(list * this.terms(o).mul));
  }

  /**
   * A dealer's stock this year: 1–3 unlocked models of its trade (jets only where the cell's runway takes
   * them). Each model has its own roll for the place and year and the lowest rolls are stocked, so
   * unlocking a model puts it on some dealers' floors without reshuffling the rest. A car dealer always has
   * at least one basic (tier 0) model on its floor: when the year's roll leaves them all off, the best-rolled
   * of them takes the place of the last model picked.
   */
  models(o: Outlet): string[] {
    if (o.kind !== 'dealer' || !o.trade) return [];
    const ok = this.host.unlocked ?? (() => true);
    // a faction's depot keeps one of each of its own models the player has earned, every year
    if (o.faction) return depotModels(o.faction).filter((id) => ok(id) && ALL_VEHICLES.some((d) => d.id === id));
    const pool = tradeModels(o.trade).filter((d) => ok(d.id) && !(d.kind === 'air' && d.jet && d.jet.runway > o.runway));
    // a car dealer's floor holds up to DEALER_FLOOR.land models (Oct 2026), a boat or aircraft dealer's up to 3
    const [lo, hi] = DEALER_FLOOR[o.trade] ?? [1, 3];
    const n = Math.min(pool.length, lo + Math.floor(this.rng(o, 'stock')() * (hi - lo + 1)));
    const ranked = pool.map((d) => ({ id: d.id, key: this.rng(o, `stock|${d.id}`)() })).sort((a, b) => a.key - b.key);
    const floor = ranked.slice(0, n).map((m) => m.id);
    if (o.trade === 'land' && floor.length) {
      const basic = (id: string) => isStarter(TECH_BY_ID.get(id));
      const starter = ranked.find((m) => basic(m.id));
      if (starter && !floor.some(basic)) floor[floor.length - 1] = starter.id;
    }
    return floor;
  }

  /** Has this dealer sold its one of this model this year? */
  soldOut(o: Outlet, id: string): boolean { return !!this.sold.get(`${o.key}|${this.host.year()}`)?.has(id); }

  /** A dealer has sold its one of this model: gone from its floor until the new year. */
  sell(o: Outlet, id: string): void {
    const k = `${o.key}|${this.host.year()}`;
    let s = this.sold.get(k);
    if (!s) this.sold.set(k, (s = new Set()));
    s.add(id);
  }

  /** A sale that didn't go through: back on the floor. */
  unsell(o: Outlet, id: string): void { this.sold.get(`${o.key}|${this.host.year()}`)?.delete(id); }

  /** What is still on a dealer's floor this year: its stock, less what has been sold. */
  inStock(o: Outlet): string[] { return this.models(o).filter((id) => !this.soldOut(o, id)); }

  /** This year's sales, for the save ("key|year|model"); last year's are past caring about. */
  soldSave(): string[] {
    const year = this.host.year();
    return [...this.sold].filter(([k]) => k.endsWith(`|${year}`)).flatMap(([k, s]) => [...s].map((id) => `${k}|${id}`));
  }

  soldLoad(list: string[] | undefined): void {
    this.sold.clear();
    for (const e of list ?? []) {
      const i = e.lastIndexOf('|');
      if (i < 0) continue;
      const k = e.slice(0, i);
      let s = this.sold.get(k);
      if (!s) this.sold.set(k, (s = new Set()));
      s.add(e.slice(i + 1));
    }
  }

  /** A shop's stock this year: 3–5 kinds of part. Boat hulls and wings are rarer on a shop's shelves. */
  slots(o: Outlet): SlotId[] {
    if (o.kind !== 'shop') return [];
    const rnd = this.rng(o, 'stock');
    const n = 3 + Math.floor(rnd() * 3);
    const bag = SLOTS.map((s) => ({ id: s.id, key: rnd() ** (1 / (s.id === 'hull' || s.id === 'wings' ? 0.4 : 1)) }));
    return bag.sort((a, b) => b.key - a.key).slice(0, n).map((s) => s.id);
  }

  /** Money went over this counter. */
  record(o: Outlet, amount: number): void {
    // a refund (a sale that didn't go through) takes it back off
    if (amount !== 0) this.spent.set(o.key, Math.max(0, (this.spent.get(o.key) ?? 0) + amount));
  }

  /** The nearest known place of a kind that passes `ok`, from world tiles (gx, gz). */
  nearest(kind: OutletKind, gx: number, gz: number, ok: (o: Outlet) => boolean = () => true): { o: Outlet; d: number } | null {
    let best: { o: Outlet; d: number } | null = null;
    for (const o of this.known()) {
      if (o.kind !== kind || !this.open(o) || !ok(o)) continue;
      const d = Math.hypot(o.x - gx, o.z - gz);
      if (!best || d < best.d) best = { o, d };
    }
    return best;
  }

  save(): Record<string, number> {
    return Object.fromEntries([...this.spent].filter(([, v]) => v > 0));
  }

  load(s: Record<string, number> | undefined): void {
    this.spent.clear();
    for (const [k, v] of Object.entries(s ?? {})) if (v > 0) this.spent.set(k, v);
  }
}

/** "120 tiles north-east", for pointing the way. */
export function wayTo(fromX: number, fromZ: number, o: { x: number; z: number }): string {
  const dx = o.x - fromX, dz = o.z - fromZ, d = Math.hypot(dx, dz);
  if (d < 12) return 'right here';
  // screen north is −z
  const ang = Math.atan2(dx, -dz);
  const names = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
  return `${Math.round(d)} tiles ${names[((Math.round(ang / (Math.PI / 4)) % 8) + 8) % 8]}`;
}
