import * as THREE from 'three';
import { N, STEP, heightAt, idx, type World } from '../world/tiles';
import { CONE } from '../game/policeBeat';

/**
 * Each patrol car's line of sight drawn on the ground (docs/smuggling.html): a faint red fan, brighter
 * at the car and toward its rim, with a thin outline. The fan is built from the same ray lengths the
 * sight test uses, so the glow is the rule. Nothing is drawn at all until there is contraband aboard —
 * with a clean hold the cones cannot catch anyone, so they would only be noise — and then there is an
 * edge that flares when the player is just outside one, and solid red on the car that has seen them.
 */

/** Rings along each ray: the fan follows the ground this finely. */
const RINGS = 4;
/** How strong the fill is at the car and at the far edge, and how much brighter the rim is. */
const NEAR_A = 0.22, FAR_A = 0.06, RIM_A = 0.12;
/** Height over the ground. */
const LIFT = 0.06;

interface ConeView {
  w: World;
  lens: Float32Array;
  /** Where the fan starts and which way it points, in w's frame; the eye height it was cast at. */
  ox: number; oz: number; dir: number;
  warn: boolean;
  solid: boolean;
}

/** Ground, water or deck under a point of a cell's frame, whichever is on top. */
function surfaceAt(w: World, x: number, z: number, near: number): number {
  let y = heightAt(w, x, z);
  const tx = Math.floor(x), tz = Math.floor(z);
  if (tx >= 0 && tz >= 0 && tx < N && tz < N) {
    const i = idx(tx, tz);
    if (w.water[i] >= 0) y = Math.max(y, w.water[i] * STEP);
    // a deck the car is on (not one far overhead) carries the fan along it
    if (w.deckAxis[i]) { const d = Math.max(w.deckLo[i], w.deckHi[i]); if (Math.abs(d - near) < 1.2) y = Math.max(y, d); }
  }
  return y;
}

class Fan {
  readonly fill: THREE.Mesh;
  readonly line: THREE.LineLoop;
  private pos: Float32Array;
  private linePos: Float32Array;
  readonly uni = { uColor: { value: new THREE.Color(0xff3524) }, uStrength: { value: 1 }, uWarn: { value: 0 }, uSolid: { value: 0 } };

  constructor(parent: THREE.Object3D, fillMat: THREE.ShaderMaterial, lineMat: THREE.LineBasicMaterial) {
    const n = CONE.rays;
    const verts = 1 + n * RINGS;
    this.pos = new Float32Array(verts * 3);
    const alpha = new Float32Array(verts), rim = new Float32Array(verts);
    alpha[0] = NEAR_A;
    for (let r = 0; r < n; r++) for (let k = 1; k <= RINGS; k++) {
      const v = 1 + r * RINGS + (k - 1);
      alpha[v] = NEAR_A + (FAR_A - NEAR_A) * (k / RINGS);
      rim[v] = k === RINGS || r === 0 || r === n - 1 ? 1 : 0;
    }
    const index: number[] = [];
    for (let r = 0; r < n - 1; r++) {
      const a = 1 + r * RINGS, b = 1 + (r + 1) * RINGS;
      index.push(0, b, a);
      for (let k = 0; k < RINGS - 1; k++) index.push(a + k, b + k, b + k + 1, a + k, b + k + 1, a + k + 1);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    g.setAttribute('alpha', new THREE.BufferAttribute(alpha, 1));
    g.setAttribute('rim', new THREE.BufferAttribute(rim, 1));
    g.setIndex(index);
    const mat = fillMat.clone();
    mat.uniforms = this.uni;
    this.fill = new THREE.Mesh(g, mat);
    this.fill.frustumCulled = false;
    this.fill.renderOrder = 21;
    this.linePos = new Float32Array((n + 1) * 3);
    const lg = new THREE.BufferGeometry();
    lg.setAttribute('position', new THREE.BufferAttribute(this.linePos, 3));
    this.line = new THREE.LineLoop(lg, lineMat.clone());
    this.line.frustumCulled = false;
    this.line.renderOrder = 22;
    parent.add(this.fill, this.line);
  }

  set(c: ConeView, strength: number): void {
    const n = CONE.rays, w = c.w;
    const oy = surfaceAt(w, c.ox, c.oz, Infinity);
    const put = (arr: Float32Array, v: number, x: number, z: number) => {
      arr[v * 3] = w.ox + x;
      arr[v * 3 + 1] = surfaceAt(w, x, z, oy) + LIFT;
      arr[v * 3 + 2] = w.oz + z;
    };
    put(this.pos, 0, c.ox, c.oz);
    put(this.linePos, 0, c.ox, c.oz);
    for (let r = 0; r < n; r++) {
      const a = c.dir - CONE.half + (2 * CONE.half * r) / (n - 1);
      const sx = Math.sin(a), sz = Math.cos(a), len = c.lens[r];
      for (let k = 1; k <= RINGS; k++) {
        const d = (len * k) / RINGS;
        put(this.pos, 1 + r * RINGS + (k - 1), c.ox + sx * d, c.oz + sz * d);
      }
      put(this.linePos, 1 + r, c.ox + sx * len, c.oz + sz * len);
    }
    (this.fill.geometry.attributes.position as THREE.BufferAttribute).needsUpdate = true;
    (this.line.geometry.attributes.position as THREE.BufferAttribute).needsUpdate = true;
    this.uni.uStrength.value = strength;
    this.uni.uWarn.value = c.warn ? 1 : 0;
    this.uni.uSolid.value = c.solid ? 1 : 0;
    (this.line.material as THREE.LineBasicMaterial).opacity = Math.min(1, (c.solid ? 0.9 : c.warn ? 0.75 : 0.4) * strength);
    this.fill.visible = this.line.visible = true;
  }

  hide(): void { this.fill.visible = this.line.visible = false; }

  dispose(): void {
    this.fill.removeFromParent();
    this.line.removeFromParent();
    this.fill.geometry.dispose();
    this.line.geometry.dispose();
    (this.fill.material as THREE.Material).dispose();
    (this.line.material as THREE.Material).dispose();
  }
}

export class PoliceCones {
  private group = new THREE.Group();
  private fans: Fan[] = [];
  private fillMat: THREE.ShaderMaterial;
  private lineMat = new THREE.LineBasicMaterial({ color: 0xff5040, transparent: true, opacity: 0.4, depthWrite: false, blending: THREE.AdditiveBlending, fog: false });

  constructor(scene: THREE.Scene) {
    this.fillMat = new THREE.ShaderMaterial({
      uniforms: {},
      vertexShader: /* glsl */ `
        attribute float alpha;
        attribute float rim;
        varying float vA;
        varying float vRim;
        void main() {
          vA = alpha;
          vRim = rim;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }`,
      fragmentShader: /* glsl */ `
        uniform vec3 uColor;
        uniform float uStrength;
        uniform float uWarn;
        uniform float uSolid;
        varying float vA;
        varying float vRim;
        void main() {
          float a = vA + vRim * ${RIM_A.toFixed(3)} * (1.0 + 2.0 * uWarn);
          a = mix(a, 0.5, uSolid);
          gl_FragColor = vec4(uColor, a * uStrength);
        }`,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      polygonOffset: true,
      polygonOffsetFactor: -4,
      polygonOffsetUnits: -4,
      side: THREE.DoubleSide,
    });
    this.group.renderOrder = 21;
    scene.add(this.group);
  }

  /** Draw these cones at this strength (0 draws none). */
  sync(cones: ConeView[], strength: number): void {
    const show = strength > 0.01 ? cones : [];
    while (this.fans.length < show.length) this.fans.push(new Fan(this.group, this.fillMat, this.lineMat));
    this.fans.forEach((f, k) => (k < show.length ? f.set(show[k], strength) : f.hide()));
  }

  clear(): void {
    for (const f of this.fans) f.dispose();
    this.fans = [];
  }
}
