/**
 * Milliseconds of trying to save with no 'saved' back from the server before the game reconnects: three autosaves
 * (main.ts AUTOSAVE × 2 online, 40 s) and some, and well past a slow world's load.
 */
const ACK_LOST = 150_000;

/**
 * Characters of JSON past which the career is sent gzipped: one that roams wide passed the server's old 2 MB and
 * stopped being kept (mickle, 28 Oct 2026). A career's JSON zips to a tenth or so.
 */
const ZIP_FROM = 200_000;
/** The most a zipped career may be to send (the server takes 3 MB in one message and closes the socket past it). */
const ZIP_MAX = 2_800_000;

/** Text gzipped, in base64. */
async function gzip64(text: string): Promise<string> {
  const zipped = new Blob([text]).stream().pipeThrough(new CompressionStream('gzip'));
  const bytes = new Uint8Array(await new Response(zipped).arrayBuffer());
  let s = '';
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s);
}

/** How long a lost game keeps trying to reconnect before it gives up and says so. */
const RETRY_FOR = 5 * 60_000;
/** How long a cell may stay missing before the cells are sent for again (syncCells), in milliseconds. */
const SUB_RETRY_MS = 4000;
/**
 * Seconds before the next try: 2, then half again longer each time up to 20, each a quarter either way at random.
 * A server restarting has every game trying at once, and fixed 3 s tries all landed on it together.
 */
const retryDelay = (n: number): number => Math.min(20, 2 * 1.5 ** n) * (0.75 + Math.random() * 0.5);

const STORE = 'tinyfleet-online';
interface Stored { server: string; name: string; token: string }

function stored(): Stored {
  try {
    const s = JSON.parse(localStorage.getItem(STORE) ?? '{}') as Partial<Stored>;
    return { server: String(s.server ?? ''), name: String(s.name ?? ''), token: String(s.token ?? '') };
  } catch { return { server: '', name: '', token: '' }; }
}
function store(s: Stored): void {
  try { localStorage.setItem(STORE, JSON.stringify(s)); } catch { /* not remembered */ }
}

/**
 * The online world as this device last knew it: which server, its seed, and the cell the player was last
 * in there. The title screen plays it, from that cell, so Play online starts on cells already built.
 */
interface KnownWorld { server: string; seed: string; cell: [number, number] | null; start?: [number, number] | null }
const WORLD_STORE = 'tinyfleet-online-world';
export function knownWorld(): KnownWorld | null {
  try {
    const s = JSON.parse(localStorage.getItem(WORLD_STORE) ?? 'null') as Partial<KnownWorld> | null;
    if (!s || typeof s.seed !== 'string' || !s.seed) return null;
    const c = Array.isArray(s.cell) && s.cell.length === 2 ? [Number(s.cell[0]) || 0, Number(s.cell[1]) || 0] as [number, number] : null;
    const st = Array.isArray(s.start) && s.start.length === 2 ? [Number(s.start[0]) || 0, Number(s.start[1]) || 0] as [number, number] : null;
    return { server: String(s.server ?? ''), seed: s.seed, cell: c, start: st };
  } catch { return null; }
}
function rememberWorld(patch: Partial<KnownWorld>): void {
  const was = knownWorld();
  const next = { server: '', seed: '', cell: null, ...was, ...patch };
  // another world on that server (it began again): the cell was the old world's
  if (was && patch.seed && patch.seed !== was.seed && !('cell' in patch)) next.cell = null;
  try { localStorage.setItem(WORLD_STORE, JSON.stringify(next)); } catch { /* not remembered */ }
}

/**
 * The fleet last played on this device and the county it was last in, by server (the user, 5 Nov 2026): the title's
 * Tribune asks that server for that fleet's own news, its circle's and its county's (server /wire.json). A fleet id
 * and a county are all it sends, and every story it gets back is on the public wire already.
 */
interface TribuneMe { server: string; pid: string; cell: [number, number] }
const TRIBUNE_STORE = 'tinyfleet-tribune-me';
function tribuneMe(server: string): TribuneMe | null {
  try {
    const s = JSON.parse(localStorage.getItem(TRIBUNE_STORE) ?? 'null') as Partial<TribuneMe> | null;
    if (!s || s.server !== server || typeof s.pid !== 'string' || !Array.isArray(s.cell) || s.cell.length !== 2 || !s.cell.every(Number.isFinite)) return null;
    return { server, pid: s.pid, cell: [s.cell[0], s.cell[1]] };
  } catch { return null; }
}
function rememberTribuneMe(me: TribuneMe): void {
  try { localStorage.setItem(TRIBUNE_STORE, JSON.stringify(me)); } catch { /* not remembered */ }
}

/**
 * Where each name signed in on this device was last in the online world, newest first: typed on the sign-in card,
 * its county is built ahead while the PIN is typed (main.ts, world/islands.ts prewarm). Kept on this device only;
 * nothing is asked of the server before the PIN is in.
 */
interface NameCell { server: string; seed: string; name: string; cell: [number, number] }
const CELLS_STORE = 'tinyfleet-online-cells';
const CELLS_MAX = 8;
function nameCells(): NameCell[] {
  try {
    const a = JSON.parse(localStorage.getItem(CELLS_STORE) ?? '[]') as Partial<NameCell>[];
    return Array.isArray(a) ? a.filter((e): e is NameCell => typeof e?.server === 'string' && typeof e.seed === 'string' && typeof e.name === 'string'
      && Array.isArray(e.cell) && e.cell.length === 2 && e.cell.every(Number.isFinite)) : [];
  } catch { return []; }
}
function rememberNameCell(e: NameCell): void {
  const same = (x: NameCell) => x.server === e.server && x.name === e.name;
  const next = [e, ...nameCells().filter((x) => !same(x))].slice(0, CELLS_MAX);
  try { localStorage.setItem(CELLS_STORE, JSON.stringify(next)); } catch { /* not remembered */ }
}

/** The server a build was made for (VITE_ONLINE_URL), or the one a developer runs beside the dev game. */
const BUILT_FOR = String(import.meta.env.VITE_ONLINE_URL ?? '');
const DEV = !!import.meta.env.DEV;

/** "play.example.com", "https://…", "ws://…": the address as typed, as a web address. */
export function httpUrl(server: string): string {
  let s = server.trim().replace(/\/+$/, '');
  if (!s) return '';
  if (/^wss?:\/\//i.test(s)) s = s.replace(/^ws/i, 'http');
  else if (!/^https?:\/\//i.test(s)) s = `${/^(localhost|127\.|192\.168\.|10\.|\[::1\])/i.test(s) ? 'http' : 'https'}://${s}`;
  return s;
}
const wsUrl = (server: string): string => httpUrl(server).replace(/^http/i, 'ws');

const around = (cx: number, cz: number): string[] => {
  const out: string[] = [];
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) out.push(cellKey(cx + dx, cz + dz));
  return out;
};
const r2 = (v: number): number => Math.round(v * 100) / 100;
const r3 = (v: number): number => Math.round(v * 1000) / 1000;

export class Online {
  /** An online game is loading or in play. */
  active = false;
  me: Who | null = null;
  readonly remotes: Remotes;
  readonly ui: OnlineUi;
  /** Doors players hold, by lot key: everyone's, this player's included. */
  readonly deeds = new Map<string, DeedRow>();
  readonly people = new Map<Pid, Who>();
  /** My friends as the server last told them (asked for on signing in and while the Friends tab is up). */
  friends: FriendRow[] = [];
  /** The friends list has come in again. */
  onFriends: () => void = () => {};
  /** The cell last told the server the camera watches, so it is only said when it changes. */
  private watched: string | null = null;
  /** What else rides on the session: community (net/community.ts) and marks (net/marks.ts), set by the game. */
  readonly extras: OnlineExtra[] = [];
  /** Rent taken at one of my doors (`from`: whose trade), and my trade paying rent at someone else's. */
  onRent: (key: string, amt: number, from: Pid | undefined) => void = () => {};
  onPaid: (key: string, gross: number, owner: Pid) => void = () => {};
  /** The week's picks as online.json last had them (docs/marks.html). */
  picks: Picks | null = null;

  private ws: WebSocket | null = null;
  private status: 'off' | 'signing' | 'on' | 'lost' = 'off';
  private server = '';
  private name = '';
  private welcome: Welcome | null = null;
  /** Cells' shared state as it arrived, until the world is ready to take it. */
  private docs = new Map<string, { doc: CellDoc; host: Pid }>();
  /** Cells whose shared state is laid into the game. */
  private known = new Set<string>();
  /** The cells the server has been asked for. */
  private wanted = new Set<string>();
  private hosts = new Map<string, Pid>();
  private where = new Map<Pid, string>();
  /** How many of a cell's edits the server has, by cell: anything past it in the delta is this player's, unsent. */
  private synced = new Map<string, number>();
  private landSent = new Map<string, Record<string, string>>();
  private sent = new Map<string, string>();
  private sentAt = new Map<string, number>();
  private sentDeeds = new Map<string, string>();
  private rent = new Map<string, number>();
  private lookSent = '';
  private isles: Islands | null = null;
  /** The world has loaded through to its firms: shared state is laid in as it arrives from here on. */
  private attached = false;
  private waiters: { want: (m: ServerMsg) => boolean; done: (m: ServerMsg | null) => void }[] = [];
  private srvHours = 8;
  private srvAt = 0;
  private moveT = 0;
  private beat = 0;
  private slowT = 0;
  private bookT = 0;
  private rentT = 0;
  private owed = 0;
  private retries = 0;
  private retryT = 0;
  /** When the line was lost (Date.now() ms): reconnecting gives up RETRY_FOR ms after it. */
  private lostAt = 0;
  /** A fleet that has never played: it may ask for another home if this one has no town. */
  fresh = false;
  /** Shared fleets (net/crew.ts, docs/sharedfleets.html): the purse, the roster and the buildings kept in step with the fleet's other players. */
  readonly crew: CrewSync;
  /**
   * Asked before the world loads when the sign-in carried an invite (docs/sharedfleets.html): yes to join that
   * fleet, no to play one's own. Set by the game (the title's confirmation screen).
   */
  confirmJoin: (offer: NonNullable<Welcome['offer']>) => Promise<boolean> = async () => false;
  /**
   * Watching from a postcard's link with no fleet (docs/postcards.html, phase 3): the server sends cells and
   * who moves round the camera; nothing goes back but the cells wanted and where the camera is.
   */
  guest = false;
  /** The fleet in play was made in one click and has no name or PIN of its own yet: it lives in this browser by its token. */
  auto = false;
  /** The fleet's renames so far, as the server keeps them (shared/names.ts): the fleet editor's wait. */
  renames: Renames | null = null;
  private heartT = 0;
  private rerolls = 0;

  constructor(private host: OnlineHost) {
    this.remotes = new Remotes(host.scene);
    this.crew = new CrewSync({
      fleet: host.fleet, wallet: host.wallet, estate: host.estate,
      cash: () => host.cash(),
      brand: (b) => { if (this.me) { this.me = { ...this.me, brand: b }; this.people.set(this.me.id, this.me); } host.rebrand(b); },
      announce: (t, b, ms) => host.announce(t, b, ms),
      nameOf: (pid) => this.people.get(pid)?.name ?? this.crew.members.find((x) => x.id === pid)?.name ?? 'a fleet-mate',
    }, (m) => this.send(m));
    this.ui = new OnlineUi({
      say: (text) => this.send({ t: 'chat', text }),
      askBoard: () => this.send({ t: 'board' }),
      people: () => this.roster(),
      here: () => { const w = host.home(); return w ? cellKey(w.cx, w.cz) : '0,0'; },
      free: () => this.active && this.status === 'on' && host.playing() && !host.busy(),
      enterFree: () => this.active && this.status === 'on' && host.playing() && !host.busy() && !host.holdsEnter(),
      // somebody new online: their name on the screen, and where to find them (the user, 10 Nov 2026)
      arrived: (who) => { if (host.playing()) host.announce(`${who.name} is online`, `${who.brand?.name ?? 'A fleet'} · click "online" up in the corner to follow them`, 5000); },
    });
    // the other players' fleets, where the game names a carrier or paints a town in its colours
    OTHERS.name = (who) => (isPid(who) ? this.fleetName(who) : null);
    OTHERS.colour = (who) => (isPid(who) ? this.people.get(who)?.brand?.primary ?? 0x7d8a92 : null);
    host.estate.remote = {
      heldBy: (key) => {
        const row = this.active ? this.deeds.get(key) : undefined;
        return row && !this.crew.ours(row.by) ? `Owned by ${this.fleetName(row.by)}` : null;
      },
      trade: (key, gross, player) => this.trade(key, gross, player),
    };
    host.economy.onBooked = (b) => {
      if (!this.active || this.status !== 'on') return;
      const h = this.hosts.get(b.town.split('#')[0]);
      if (h && h !== this.me?.id) this.send({ t: 'credit', town: b.town, amt: r2(b.amount), lot: b.lot ?? undefined, lotAmt: r2(b.lotAmount), dir: b.dir });
    };
    // the player's rent counts on a town's carriage (Economy.rentShare): the game running the town keeps that
    host.economy.onRentBooked = (town, amount) => {
      if (!this.active || this.status !== 'on') return;
      const h = this.hosts.get(town.split('#')[0]);
      if (h && h !== this.me?.id) this.send({ t: 'credit', town, amt: r2(amount), rent: true });
    };
    window.addEventListener('beforeunload', () => { if (this.active && this.status === 'on' && host.playing()) this.save(true); });
  }

  // ---- who and where --------------------------------------------------------------------------------

  /** The connection has dropped and is being mended: the game waits under a card. */
  get down(): boolean { return this.active && this.status === 'lost'; }

  fleetName(id: Pid): string {
    const w = this.people.get(id);
    return w?.brand?.name ?? w?.name ?? 'another fleet';
  }

  /** The door's owner when it is another player's, as a carrier id; '' otherwise. */
  ownerOf(key: string): string {
    const row = this.active ? this.deeds.get(key) : undefined;
    return row && !this.crew.ours(row.by) ? row.by : '';
  }

  /** Is this game the one running a cell's towns? Alone, always. */
  hosting(w: World): boolean {
    if (!this.active) return true;
    const h = this.hosts.get(cellKey(w.cx, w.cz));
    return !h || h === this.me?.id;
  }

  private roster(): Person[] {
    const out: Person[] = [];
    const w = this.host.home();
    if (this.me) out.push({ who: this.me, cell: w ? cellKey(w.cx, w.cz) : '0,0', you: true });
    for (const id of this.remotes.ids()) {
      const who = this.remotes.whoOf(id);
      if (who) out.push({ who, cell: this.where.get(id) ?? this.remotes.cellOf(id) ?? '0,0', you: false });
    }
    return out;
  }

  /**
   * The server to offer on the sign-in card: the one serving this very page if it is one, else the last
   * one used, the one this build was made for, or a developer's own.
   */
  /** The server signed in to, as typed ("tinyfleet.up.railway.app", "localhost:8787"). */
  get serverAddress(): string { return this.server; }
  defaultServer(): string { return this.origin || stored().server || BUILT_FOR || (DEV ? 'localhost:8787' : ''); }
  lastName(): string { return stored().name; }
  /** The cell a name played on this device was last in, in this world: null for a name never signed in here. */
  lastCellOf(server: string, name: string, seed: string): [number, number] | null {
    const n = name.trim().toLowerCase();
    return nameCells().find((e) => e.server === server.trim() && e.name === n && e.seed === seed)?.cell ?? null;
  }
  hasToken(server: string, name: string): boolean {
    const s = stored();
    return !!s.token && s.server === server.trim() && s.name.toLowerCase() === name.trim().toLowerCase();
  }

  /** Is the game being served by an online server? Then that server is where Play online goes. */
  private origin = '';
  async probeOrigin(signal?: AbortSignal): Promise<void> {
    if (!/^https?:$/.test(location.protocol)) return;
    try {
      const r = await fetch(new URL('online.json', location.href).toString(), { cache: 'no-store', signal });
      const j = r.ok && /json/.test(r.headers.get('content-type') ?? '') ? await r.json() as { tinyfleet?: boolean } : null;
      if (j?.tinyfleet) this.origin = location.origin;
    } catch { /* an ordinary web server: nothing to say */ }
  }

  /**
   * The address to sign in at (the user, 8 Nov 2026): a page an online server serves signs in there, not at
   * the address the build or an old visit named. The server only takes sockets from its own pages, and the
   * same server on a domain of its own (tinyfleet.online beside tinyfleet.up.railway.app) refused them as
   * foreign. A different server the player typed is left alone.
   */
  private async thisPage(server: string): Promise<string> {
    if (!this.origin && /^https?:$/.test(location.protocol)) {
      const ctl = new AbortController();
      const timer = setTimeout(() => ctl.abort(), 3000);
      await this.probeOrigin(ctl.signal);
      clearTimeout(timer);
    }
    if (!this.origin) return server;
    const want = httpUrl(server).toLowerCase();
    const named = [BUILT_FOR, stored().server].map((s) => httpUrl(s).toLowerCase()).filter(Boolean);
    return want && want !== this.origin.toLowerCase() && named.includes(want) ? this.origin : server;
  }

  /**
   * The online world's seed, asked of the server Play online would use (and remembered), within `ms`;
   * null when there is no server or it doesn't answer in time.
   */
  async worldSeed(ms: number): Promise<string | null> {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), ms);
    try {
      if (!this.origin && /^https?:$/.test(location.protocol)) await this.probeOrigin(ctl.signal);
      const base = httpUrl(this.defaultServer());
      if (!base) return null;
      const [r] = await Promise.all([fetch(`${base}/online.json`, { cache: 'no-store', signal: ctl.signal }), this.fetchLocal(base, this.defaultServer(), ctl.signal)]);
      const j = r.ok ? await r.json() as { tinyfleet?: boolean; seed?: string; gen?: number; start?: [number, number]; picks?: Picks } : null;
      if (j?.picks && Array.isArray(j.picks.items)) this.picks = j.picks;
      if (!j?.tinyfleet || typeof j.seed !== 'string' || j.gen !== GEN_VERSION) return null;
      // where a new fleet would start now: the title plays there for a device that has never been online
      rememberWorld({ server: this.defaultServer(), seed: j.seed, start: Array.isArray(j.start) ? j.start : null });
      return j.seed;
    } catch { return null; } finally { clearTimeout(timer); }
  }

  /** The player is in this cell of the online world: the title starts there next time. */
  rememberCell(cx: number, cz: number): void {
    if (!this.active || (this.lastCell && this.lastCell[0] === cx && this.lastCell[1] === cz)) return;
    this.lastCell = [cx, cz];
    rememberWorld({ cell: [cx, cz] });
    this.rememberMine([cx, cz]);
  }
  private rememberMine(cell: [number, number]): void {
    const seed = this.welcome?.world.seed;
    if (!this.guest && this.me && seed) rememberNameCell({ server: this.server, seed, name: this.me.name.toLowerCase(), cell });
    if (!this.guest && this.me) rememberTribuneMe({ server: this.server, pid: this.me.id, cell });
  }

  /**
   * In play: the world's news and this fleet's own again (online.json's wire, /wire.json), for the annual paper
   * (game/press/wire.ts). Resolves when both have answered, or not.
   */
  async refreshNews(): Promise<void> {
    const base = this.active ? httpUrl(this.server) : null;
    if (!base) return;
    await Promise.all([
      fetch(`${base}/online.json`, { cache: 'no-store' }).then((r) => (r.ok ? r.json() : null)).then((j: { picks?: Picks } | null) => {
        if (j?.picks && Array.isArray(j.picks.items)) this.picks = j.picks;
      }).catch(() => { /* kept as it was */ }),
      this.fetchLocal(base, this.server),
    ]);
  }

  /** This device's fleet's local news (server /wire.json), as that server last told it; null before it is asked or with no fleet played here. */
  local: LocalWire | null = null;
  private async fetchLocal(base: string, server: string, signal?: AbortSignal): Promise<void> {
    const me = tribuneMe(server.trim());
    if (!me) return;
    try {
      const r = await fetch(`${base}/wire.json?p=${encodeURIComponent(me.pid)}&c=${me.cell[0]},${me.cell[1]}`, { cache: 'no-store', signal });
      const j = r.ok ? await r.json() as LocalWire : null;
      if (j && Array.isArray(j.stories)) this.local = j;
    } catch { /* an older server, or none: the world's edition only */ }
  }
  private lastCell: [number, number] | null = null;

  async probe(server: string): Promise<{ players: number; max: number; day: number } | null> {
    const base = httpUrl(server);
    if (!base) return null;
    try {
      const [r] = await Promise.all([fetch(`${base}/online.json`, { cache: 'no-store' }), this.fetchLocal(base, server)]);
      const j = r.ok ? await r.json() as { tinyfleet?: boolean; players: number; max: number; day: number; picks?: Picks } : null;
      if (j?.picks && Array.isArray(j.picks.items)) this.picks = j.picks;
      return j?.tinyfleet ? { players: j.players, max: j.max, day: j.day } : null;
    } catch { return null; }
  }

  /** Whether a name is taken on a server (server/index.ts /name.json): null when it can't say (an older server, no answer). */
  async nameTaken(server: string, name: string): Promise<boolean | null> {
    const base = httpUrl(server);
    if (!base) return null;
    try {
      const r = await fetch(`${base}/name.json?n=${encodeURIComponent(name)}`, { cache: 'no-store' });
      const j = r.ok ? await r.json() as { taken?: boolean | null } : null;
      return typeof j?.taken === 'boolean' ? j.taken : null;
    } catch { return null; }
  }

  // ---- the wire -------------------------------------------------------------------------------------

  // ---- friends -------------------------------------------------------------------------------------

  isFriend(id: Pid): boolean { return this.friends.some((f) => f.id === id); }
  /** Add or drop a friend; the list comes back from the server. */
  friend(id: Pid, on: boolean): void { if (id !== this.me?.id) this.send({ t: 'friend', id, on }); }
  askFriends(): void { this.send({ t: 'friends' }); }
  /** The cell the camera is watching away from the player, so the server sends who moves round it (null: none). */
  watch(c: string | null): void {
    if (c === this.watched) return;
    this.watched = c;
    this.send({ t: 'watch', c });
  }
  /** Where a player is signed in, as the last tick had it ("cx,cz"), or null. */
  cellOf(id: Pid): string | null { return this.where.get(id) ?? null; }

  /** Said to the server if the line is open; false when it wasn't (nothing went). */
  private send(m: ClientMsg): boolean {
    if (this.ws?.readyState !== WebSocket.OPEN) return false;
    this.ws.send(JSON.stringify(m));
    return true;
  }

  /** A message from outside this file (community): sent only while signed in and in play. */
  post(m: ClientMsg): void { if (this.active && this.status === 'on') this.send(m); }

  private next<T extends ServerMsg['t']>(types: T[], ms: number): Promise<Extract<ServerMsg, { t: T }> | null> {
    return new Promise((done) => {
      const w = { want: (m: ServerMsg) => (types as string[]).includes(m.t), done: (m: ServerMsg | null) => { clearTimeout(timer); done(m as Extract<ServerMsg, { t: T }> | null); } };
      const timer = setTimeout(() => { this.waiters = this.waiters.filter((x) => x !== w); done(null); }, ms);
      this.waiters.push(w);
    });
  }

  private open(server: string): Promise<boolean> {
    return new Promise((done) => {
      let ws: WebSocket;
      try { ws = new WebSocket(wsUrl(server)); } catch { done(false); return; }
      const timer = setTimeout(() => { try { ws.close(); } catch { /* never opened */ } done(false); }, 9000);
      ws.onopen = () => { clearTimeout(timer); this.ws = ws; done(true); };
      ws.onerror = () => { clearTimeout(timer); done(false); };
      ws.onmessage = (e) => {
        if (ws !== this.ws) return;
        let m: ServerMsg;
        try { m = JSON.parse(String(e.data)) as ServerMsg; } catch { return; }
        const k = this.waiters.findIndex((x) => x.want(m));
        if (k >= 0) { const w = this.waiters.splice(k, 1)[0]; w.done(m); if (m.t === 'welcome' || m.t === 'refuse' || m.t === 'home') return; }
        try { this.got(m); } catch (err) { console.error('online:', m.t, err); }
      };
      ws.onclose = () => { if (ws === this.ws) this.closed(); };
    });
  }

  private closed(): void {
    this.ws = null;
    for (const w of this.waiters.splice(0)) w.done(null);
    // a guest has nothing to wait for: the watching is over
    if (this.status === 'on' && this.active && this.guest) { this.end('The connection to the server was lost.'); return; }
    if (this.status === 'on' && this.active) this.lose();
  }

  /**
   * Sign in, or with a brand make a new fleet. Resolves once the world is loading; or says why not
   * ('new': nobody of that name yet, ask whether to make them; 'pin': the PIN is wanted or wrong).
   */
  async signIn(server: string, name: string, pin: string, brand?: FleetBrand): Promise<SignIn> {
    this.shut();
    this.status = 'signing';
    server = await this.thisPage(server.trim());
    name = name.trim();
    if (!(await this.open(server))) { this.status = 'off'; return { ok: false, code: 'net', why: 'Couldn’t reach that server.' }; }
    const s = stored();
    const token = !pin && s.server === server && s.name.toLowerCase() === name.toLowerCase() ? s.token : undefined;
    const invite = pendingInvite() ?? undefined;
    this.send({ t: 'hello', v: PROTOCOL, gen: GEN_VERSION, name, pin: pin || undefined, token, create: brand ? { brand } : undefined, invite });
    let m = await this.next(['welcome', 'refuse'], 12000);
    if (!m || m.t === 'refuse') {
      this.status = 'off';
      const ws = this.ws;
      this.ws = null;
      try { ws?.close(); } catch { /* gone */ }
      return m ? { ok: false, code: m.code, why: m.why } : { ok: false, code: 'net', why: 'The server didn’t answer.' };
    }
    this.server = server;
    this.name = m.you.name;
    // an invite this game was opened with (docs/sharedfleets.html): asked now, before the world loads
    const offer = m.offer;
    let note: string | null = null;
    if (offer) {
      setPendingInvite(null);
      if (offer.why) note = offer.why;
      else if (await this.confirmJoin(offer)) {
        this.send({ t: 'join', code: offer.code });
        const j = await this.next(['joined'], 12000);
        if (j?.welcome) m = j.welcome;
        else note = j?.why ?? 'The server didn’t answer: playing your own fleet.';
      }
      if (this.status !== 'signing' || !this.ws) return { ok: false, code: 'net', why: 'The connection was lost.' };
    }
    await this.start(m, null);
    if (note) { const n = note; setTimeout(() => this.host.announce('Not joined', n, 7000), 4000); }
    return { ok: true };
  }

  /** A welcome in hand: fetch the cells round where the player will stand, then load the world. */
  private async start(w: Welcome, resume: SaveGame | null): Promise<void> {
    this.reset();
    this.guest = false;
    this.auto = !!w.auto;
    this.renames = w.renames ?? null;
    this.welcome = w;
    this.me = w.you;
    this.crew.welcome(w);
    for (const x of this.extras) x.welcome(w);
    this.people.set(w.you.id, w.you);
    store({ server: this.server, name: w.you.name, token: w.token });
    this.srvHours = w.world.hours;
    this.srvAt = performance.now();
    this.owed += Math.max(0, w.owed || 0);
    for (const o of w.online) {
      this.people.set(o.who.id, o.who);
      this.where.set(o.who.id, o.c);
      this.remotes.join(o.who, o.c, o.look);
    }
    const rec = resume ?? (w.record as SaveGame | null);
    const hour = ((w.world.hours % 24) + 24) % 24, days = Math.floor(w.world.hours / 24);
    let save: SaveGame | null = null, carry: OnlineStart['carry'] = null;
    if (rec && rec.gen === GEN_VERSION && Array.isArray(rec.cell)) {
      save = { ...rec, seed: w.world.seed, hour, days, cells: {}, lots: {} };
    } else if (rec) {
      // a career from before the world began again: the money, the models and their upgrades come with it
      const models = [...new Set([...(rec.owned ?? []), ...(rec.fleet?.units ?? []).map((u) => u.model)])].filter((x) => typeof x === 'string');
      const units = (rec.fleet?.units ?? []).filter((u) => u && typeof u.model === 'string').map((u) => ({ model: u.model, name: String(u.name ?? ''), parts: u.parts }));
      // and its buildings, refunded at what was paid for them, the HQ among them (estateRefund, the user, 10 Nov 2026):
      // the HQ then looks for its like in the new world (game/hqCarry.ts), bought out of that refund (main.ts carryHq)
      const oldHq = (rec.fleet as { hq?: Hq | null } | undefined)?.hq ?? null;
      const hqDeed = oldHq && rec.estate ? rec.estate[oldHq.key] : undefined;
      const refund = estateRefund(rec.estate);
      const hqCarry = oldHq && oldHq.grade && hqDeed ? {
        want: { kind: oldHq.kind ?? hqDeed[0], town: oldHq.townKind ?? null, grade: oldHq.grade, cx: oldHq.cx, cz: oldHq.cz },
        name: oldHq.name, worth: 0,
      } : null;
      // and what it spent building into the old world: roads, bridges, track, boost pads, earthworks (game/books.ts)
      const works = worksSpent((rec as SaveGame).books);
      carry = { cash: Math.max(0, Number(rec.cash) || 0) + refund.total + works, ...(works ? { works } : {}), owned: models, units, earned: Number(rec.earned) || 0, played: Number(rec.played) || 0, brand: (rec.brand as FleetBrand | undefined) ?? null, ...(refund.n ? { refund } : {}), ...(hqCarry ? { hq: hqCarry } : {}), ...(rec.missions?.passport ? { passport: carryPassport(rec.missions.passport) } : {}), ...(Array.isArray(rec.unlocks) ? { unlocks: rec.unlocks as string[] } : {}), ...(Array.isArray(rec.tech) ? { tech: rec.tech.filter((x) => typeof x === 'string') } : {}), ...(rec.factions ? { factions: rec.factions } : {}), ...(Array.isArray(rec.missions?.arcs) ? { arcs: rec.missions.arcs } : {}) };
    }
    // in a shared fleet, the career's money, vehicles and buildings are the fleet's; just joined, it starts where it was put
    const spawn = w.spawn;
    this.crew.patchSave(save);
    this.fresh = !rec && !spawn;
    this.rerolls = 0;
    const at: [number, number] = save ? [save.cell[0], save.cell[1]] : spawn ? [spawn[0], spawn[1]] : w.home;
    this.status = 'on';
    this.active = true;
    this.friends = [];
    this.watched = null;
    this.askFriends();
    rememberWorld({ server: this.server, seed: w.world.seed, cell: at });
    this.rememberMine(at);
    this.lastCell = at;
    this.host.signedIn();
    // saves count from here: the watch gives the world its time to load before it expects a word back
    this.savesFrom = Date.now();
    this.lastAck = 0;
    await this.prefetch(at);
    if (this.status !== 'on') return;
    this.host.begin({ seed: w.world.seed, save, carry, book: (rec as SaveGame | null)?.book ?? null, at, brand: this.crew.brand ?? (w.you.brand as FleetBrand | null) ?? carry?.brand ?? null });
  }

  // ---- guests, one-click fleets (docs/postcards.html, phase 3) ---------------------------------------

  /**
   * Watch the world from a postcard's link, with no fleet: connected as a guest, the cells round `at` asked
   * for and waited on. Resolves with the world's seed (the game then loads it as the title would, and lays
   * the cells in as they come), or why not.
   */
  async watchAs(server: string, at: [number, number]): Promise<{ ok: true; seed: string; players: number } | { ok: false; why: string }> {
    this.shut();
    this.status = 'signing';
    server = await this.thisPage(server.trim());
    if (!(await this.open(server))) { this.status = 'off'; return { ok: false, why: 'Couldn’t reach the server.' }; }
    this.send({ t: 'hello', v: PROTOCOL, gen: GEN_VERSION, guest: true });
    const m = await this.next(['guest', 'refuse'], 10000);
    if (!m || m.t !== 'guest') {
      this.status = 'off';
      const ws = this.ws;
      this.ws = null;
      try { ws?.close(); } catch { /* gone */ }
      return { ok: false, why: m && m.t === 'refuse' ? m.why : 'The server didn’t answer.' };
    }
    this.reset();
    this.server = server;
    this.guest = true;
    this.auto = false;
    this.me = null;
    this.srvHours = m.world.hours;
    this.srvAt = performance.now();
    for (const o of m.online) {
      this.people.set(o.who.id, o.who);
      this.where.set(o.who.id, o.c);
      this.remotes.join(o.who, o.c, o.look);
    }
    this.status = 'on';
    this.active = true;
    this.watched = null;
    this.heartT = 60;
    // the title plays this world from here next time, on the cells this has built
    rememberWorld({ server, seed: m.world.seed, cell: at });
    await this.prefetch(at);
    return { ok: true, seed: m.world.seed, players: m.players };
  }

  /** Stop watching: back to a world of this game's own. */
  leaveGuest(): void {
    if (!this.guest) return;
    this.send({ t: 'bye' });
    this.guest = false;
    this.leave();
  }

  /**
   * Take a car (docs/postcards.html): a fleet made in one click, named by the server, with a home near the
   * postcard that brought them. Resolves once the world is loading, or with why not.
   */
  async takeCar(brand: FleetBrand, from: string | null, guest = false): Promise<SignIn> {
    const server = await this.thisPage(this.server || this.defaultServer());
    if (this.guest) this.leaveGuest();
    this.shut();
    this.status = 'signing';
    if (!(await this.open(server))) { this.status = 'off'; return { ok: false, code: 'net', why: 'Couldn’t reach the server.' }; }
    this.send({ t: 'hello', v: PROTOCOL, gen: GEN_VERSION, create: { brand, auto: true, ...(from ? { from } : {}), ...(guest ? { guest: true as const } : {}) } });
    const m = await this.next(['welcome', 'refuse'], 12000);
    if (!m || m.t === 'refuse') {
      this.status = 'off';
      const ws = this.ws;
      this.ws = null;
      try { ws?.close(); } catch { /* gone */ }
      return m ? { ok: false, code: m.code, why: m.why } : { ok: false, code: 'net', why: 'The server didn’t answer.' };
    }
    this.server = server;
    this.name = m.you.name;
    await this.start(m, null);
    return { ok: true };
  }

  /** A one-click fleet takes a name and a PIN of its own. */
  async keep(name: string, pin: string): Promise<{ ok: true } | { ok: false; why: string }> {
    if (!this.active || this.status !== 'on' || !this.auto) return { ok: false, why: 'Not signed in.' };
    this.send({ t: 'keep', name, pin });
    const m = await this.next(['kept'], 8000);
    if (!m) return { ok: false, why: 'The server didn’t answer.' };
    if (!m.you) return { ok: false, why: m.why ?? 'That didn’t work.' };
    this.me = m.you;
    this.name = m.you.name;
    this.auto = false;
    this.people.set(m.you.id, m.you);
    // this browser still signs it in without the PIN, now under its new name
    store({ server: this.server, name: m.you.name, token: stored().token });
    return { ok: true };
  }

  /** The server's clock as it stands this instant. */
  serverHours(): number { return this.srvHours + ((performance.now() - this.srvAt) / 1000) * HOURS_PER_SECOND; }

  /** Ask for the 3 × 3 round a cell and wait until its shared state is here (or five seconds have gone). */
  private async prefetch(at: [number, number]): Promise<void> {
    const need = around(at[0], at[1]);
    for (const k of need) this.wanted.add(k);
    this.sendSubs();
    const until = performance.now() + 5000;
    while (performance.now() < until && this.status === 'on' && !need.every((k) => this.docs.has(k) || this.known.has(k))) {
      await new Promise((r) => setTimeout(r, 30));
    }
  }

  /** A new fleet's home has no town to start in: ask for another. Null when there are no more to be had. */
  async reroll(): Promise<[number, number] | null> {
    if (!this.fresh || this.rerolls >= 12 || this.status !== 'on') return null;
    this.rerolls++;
    this.send({ t: 'reroll' });
    const m = await this.next(['home'], 6000);
    if (!m) return null;
    this.detach();
    await this.prefetch(m.home);
    return m.home;
  }

  private sendSubs(): void { this.subsAt = performance.now(); this.send({ t: 'sub', cells: [...this.wanted] }); }
  /**
   * When the cells were last sent for. The server can turn a far cell away (a few far reads a player each ten
   * seconds, server/reach.ts), and a cell that never comes waits at the gate for good: its county is never built,
   * and a camera following something there looks at nothing. So while any is missing they are sent for again.
   */
  private subsAt = 0;

  private reset(): void {
    this.docs.clear();
    this.known.clear();
    this.wanted.clear();
    this.hosts.clear();
    this.where.clear();
    this.synced.clear();
    this.landSent.clear();
    this.sent.clear();
    this.sentAt.clear();
    this.sentDeeds.clear();
    this.rent.clear();
    this.deeds.clear();
    this.people.clear();
    this.remotes.clear();
    this.lookSent = '';
    this.attached = false;
    this.isles = null;
    for (const x of this.extras) x.reset();
    this.crew.reset();
  }

  /** Close the socket and forget the session, without touching the game. */
  private shut(): void {
    const ws = this.ws;
    this.ws = null;
    this.status = 'off';
    if (ws) { try { ws.close(); } catch { /* gone */ } }
    for (const w of this.waiters.splice(0)) w.done(null);
  }

  /** Sign out: the career is sent one last time and the world goes back to being this game's alone. */
  signOut(): void {
    if (!this.active) return;
    if (this.guest) { this.leaveGuest(); return; }
    if (this.status === 'on') { this.crew.flush(); this.flushAll(); this.save(true); this.send({ t: 'bye' }); }
    this.leave();
  }

  private leave(): void {
    this.active = false;
    this.shut();
    const isles = this.isles;
    if (isles) { isles.gate = null; isles.admitAll(); }
    this.reset();
    // money a lost session never sent is not carried into whoever signs in next
    this.crew.dropCarry();
    this.me = null;
    this.ui.show(false);
  }

  // ---- losing the server and finding it again -------------------------------------------------------

  private lose(): void {
    this.status = 'lost';
    this.retries = 0;
    this.lostAt = Date.now();
    this.retryT = retryDelay(0);
    this.ui.setLost(true, 'The game is waiting where you were.');
  }

  private async retry(): Promise<void> {
    this.retries++;
    if (Date.now() - this.lostAt > RETRY_FOR) { this.end('The connection to the server was lost.'); return; }
    this.ui.setLost(true, `Attempt ${this.retries}…`);
    if (!(await this.open(this.server))) { this.retryT = retryDelay(this.retries); return; }
    // the career as it stands, built only once there is a line to send it down
    const snap = this.host.snapshot();
    this.send({ t: 'hello', v: PROTOCOL, gen: GEN_VERSION, name: this.name, token: stored().token });
    const m = await this.next(['welcome', 'refuse'], 10000);
    if (!this.active) return;
    if (!m) { this.retryT = retryDelay(this.retries); return; }
    if (m.t === 'refuse') { this.end(m.why); return; }
    this.ui.setLost(false);
    // picked up from where this game stood, which is later than anything the server was sent
    await this.start(m, { ...snap, cells: {}, lots: {} });
  }

  private end(why: string): void {
    this.leave();
    this.host.ended(why);
  }

  // ---- cells: the gate, and laying shared state into the game ---------------------------------------

  /** The world is being loaded: cells wait at the gate for their shared state, and what has arrived is laid in. */
  attach(isles: Islands): void {
    this.isles = isles;
    this.attached = false;
    this.known.clear();
    this.synced.clear();
    this.landSent.clear();
    isles.gate = (cx, cz) => this.gate(cellKey(cx, cz));
    for (const [k, d] of this.docs) this.layWorld(k, d.doc, d.host);
  }

  /** The load has reached the end of its saves (the firms and the carriage are in): the rest of what arrived goes in. */
  loaded(): void {
    if (this.guest) {
      // a guest's world takes the cells as they are, and shows no chat: nothing it does goes anywhere
      for (const [k, d] of this.docs) this.layBooks(k, d.doc);
      this.docs.clear();
      this.attached = true;
      this.slowT = 0.2;
      for (const x of this.extras) x.ready();
      return;
    }
    for (const [k, d] of this.docs) this.layBooks(k, d.doc);
    this.docs.clear();
    this.attached = true;
    // a shared fleet's vehicles, drivers, buildings and purse, over the career's (net/crew.ts)
    this.crew.ready();
    this.ui.show(true);
    this.slowT = 0.2;
    for (const x of this.extras) x.ready();
    if (this.owed > 0) {
      const owed = Math.round(this.owed);
      this.owed = 0;
      this.host.wallet.earn(owed, 'rent', 'other');
      this.host.cash();
      setTimeout(() => { if (this.active) { this.host.announce('While you were away', `Your buildings took in $${owed.toLocaleString('en-US')} from the trade at their doors`, 7000); this.save(); } }, 3500);
    }
  }

  /** The world is being thrown away (a reroll, a reconnect): forget what was laid into it. */
  private detach(): void {
    if (this.isles) this.isles.gate = null;
    this.isles = null;
    this.attached = false;
    this.known.clear();
    this.synced.clear();
    this.landSent.clear();
    this.docs.clear();
    this.wanted.clear();
  }

  /** The server's clock as it stands this instant, put on the game's. */
  setClock(): void {
    this.host.setHours(this.srvHours + ((performance.now() - this.srvAt) / 1000) * HOURS_PER_SECOND);
  }

  private gate(k: string): boolean {
    if (this.known.has(k)) return true;
    if (!this.wanted.has(k)) { this.wanted.add(k); this.sendSubs(); }
    return false;
  }

  /** The edits, the earthworks, the towns' books and the doors of a cell. */
  private layWorld(k: string, doc: CellDoc, host: Pid): void {
    const isles = this.isles;
    if (!isles) return;
    const [cx, cz] = cellOfKey(k);
    this.hosts.set(k, host);
    for (const key of [...this.deeds.keys()]) if (key.startsWith(`${k}#`)) this.deeds.delete(key);
    for (const [key, row] of Object.entries(doc.deeds ?? {})) this.deeds.set(key, row);
    const w = isles.at(cx, cz);
    if (!w) {
      const d: CellDelta = { edits: (doc.edits as Edit[]).slice() };
      if (doc.land && Object.keys(doc.land).length) d.land = { ...doc.land } as unknown as LandBlock;
      isles.deltas.set(k, d);
      this.synced.set(k, d.edits.length);
      this.landSent.set(k, { ...(doc.land ?? {}) });
    } else this.lateLay(w, k, doc);
    const eco = this.host.economy;
    for (const [key, r] of Object.entries(doc.towns ?? {})) eco.importTown(key, r as TownLedger);
    for (const [key, v] of Object.entries(doc.lots ?? {})) this.importLot(key, v);
    for (const x of this.extras) x.cell(k, doc, w, isles);
    this.known.add(k);
  }

  /** The towns' carriage, and the rival firms whose home the cell is. */
  private layBooks(k: string, doc: CellDoc): void {
    const [cx, cz] = cellOfKey(k);
    for (const [key, row] of Object.entries(doc.carriage ?? {})) this.host.economy.carriage.importTown(key, this.rowIn(row));
    // a firm is taken as its host last had it, unless this game already has it out on the road
    if (!this.attached || !this.isles?.at(cx, cz)) for (const sf of Object.values(doc.firms ?? {})) this.host.firms.adopt(sf as SavedFirm);
    for (const [key, row] of Object.entries(doc.deeds ?? {})) if (!this.crew.ours(row.by)) this.host.firms.evict(key);
  }

  private importLot(key: string, v: number[]): void {
    if (!Array.isArray(v) || v.length < 7) return;
    const lots = this.host.economy.lots;
    lots.set(key, { rate: v[0], at: v[1], ins: v[2], outs: v[3], value: v[4], mine: lots.get(key)?.mine ?? 0, lost: v[6] });
  }

  /** A cell that was built before its shared state arrived (asked for on the spot): the state is laid over it as it stands. */
  private lateLay(w: World, k: string, doc: CellDoc): void {
    const isles = this.isles!;
    const d = isles.delta(w.cx, w.cz);
    const mine = d.edits.slice(this.synced.get(k) ?? 0);
    const tiles: number[] = [];
    for (const e of doc.edits as Edit[]) { try { tiles.push(...applyEdit(w, e)); } catch (err) { console.warn('online: an edit would not lay', e, err); } }
    d.edits = [...(doc.edits as Edit[]), ...mine];
    this.synced.set(k, doc.edits.length);
    const change: Record<string, string | null> = {};
    for (const key of new Set([...Object.keys(d.land ?? {}), ...Object.keys(doc.land ?? {})])) change[key] = doc.land?.[key] ?? null;
    const moved = applyLandChange(w, d.land, change);
    if (doc.land && Object.keys(doc.land).length) d.land = { ...doc.land } as unknown as LandBlock; else delete d.land;
    this.landSent.set(k, { ...(doc.land ?? {}) });
    if (tiles.length) this.host.worldChanged(w, tiles);
    if (moved.length) this.host.landChanged(w, moved);
  }

  /** A cell has left memory: if this game was running it, its books go to the server as they stand. */
  left(w: World): void {
    if (!this.active || this.status !== 'on') return;
    const k = cellKey(w.cx, w.cz);
    this.flushEdits();
    if (this.hosts.get(k) === this.me?.id) this.uploadBooks(k, true);
  }

  /** Keep the server's idea of which cells this game has in step with the world in memory. */
  private syncCells(): void {
    const isles = this.isles;
    if (!isles || !this.attached) return;
    const now = new Set(isles.wantedKeys());
    let changed = false;
    for (const k of [...this.wanted]) {
      if (now.has(k)) continue;
      this.wanted.delete(k);
      this.known.delete(k);
      this.synced.delete(k);
      this.landSent.delete(k);
      this.hosts.delete(k);
      for (const key of [...this.deeds.keys()]) if (key.startsWith(`${k}#`) && !this.crew.ours(this.deeds.get(key)!.by)) this.deeds.delete(key);
      for (const x of this.extras) x.forget(k);
      changed = true;
    }
    for (const k of now) if (!this.wanted.has(k)) { this.wanted.add(k); changed = true; }
    if (changed) this.sendSubs();
    // (the server skips the cells it is already sending, so asking again costs it nothing for those)
    else if (performance.now() - this.subsAt > SUB_RETRY_MS && [...this.wanted].some((k) => !this.known.has(k))) this.sendSubs();
  }

  // ---- edits and earthworks -------------------------------------------------------------------------

  /** Anything in a cell's delta the server has not had is this player's: a road, a bulldozed tile, a town grown. */
  private flushEdits(): void {
    const isles = this.isles;
    if (!isles || this.status !== 'on') return;
    for (const k of this.known) {
      const d = isles.deltas.get(k);
      if (!d) continue;
      let n = this.synced.get(k) ?? 0;
      if (n >= d.edits.length) { if (n > d.edits.length) this.synced.set(k, d.edits.length); continue; }
      while (n < d.edits.length) {
        const e = d.edits[n++] as Edit & { lot?: string };
        this.send({ t: 'edit', c: k, e, lot: e.lot });
      }
      this.synced.set(k, n);
    }
  }

  private onEdit(c: string, e: Edit): void {
    if (!this.attached) { this.docs.get(c)?.doc.edits.push(e); return; }
    const isles = this.isles;
    if (!isles || !this.known.has(c)) return;
    this.flushEdits();
    const [cx, cz] = cellOfKey(c);
    const d = isles.delta(cx, cz);
    d.edits.push(e);
    this.synced.set(c, d.edits.length);
    const w = isles.at(cx, cz);
    if (!w) return;
    let tiles: number[] = [];
    try { tiles = applyEdit(w, e); } catch (err) { console.warn('online: an edit would not lay', e, err); }
    if (tiles.length) this.host.worldChanged(w, tiles);
  }

  /**
   * A construction (world/erect.ts, docs/blueprints.html): sent, not applied. The server echoes it back to this
   * game too, and it lands then, in the server's order, so every player's building uids agree. False when the
   * game is not online with the cell: the caller applies it itself.
   */
  sendErect(w: World, e: Edit): boolean {
    if (!this.active || this.status !== 'on' || !this.attached) return false;
    const k = cellKey(w.cx, w.cz);
    if (!this.known.has(k)) return false;
    this.flushEdits();
    this.send({ t: 'edit', c: k, e });
    return true;
  }

  /** The earthworks tool has finished a stroke: the chunks it changed go to the server. */
  landEdited(w: World, land: LandBlock | undefined): void {
    if (!this.active) return;
    const k = cellKey(w.cx, w.cz);
    const was = this.landSent.get(k) ?? {};
    const now = (land ?? {}) as unknown as Record<string, string>;
    const chunks: Record<string, string | null> = {};
    for (const key of new Set([...Object.keys(was), ...Object.keys(now)])) if (was[key] !== now[key]) chunks[key] = now[key] ?? null;
    if (!Object.keys(chunks).length) return;
    this.landSent.set(k, { ...now });
    this.send({ t: 'land', c: k, chunks });
  }

  private onLand(c: string, chunks: Record<string, string | null>): void {
    if (!this.attached) {
      const doc = this.docs.get(c)?.doc;
      if (doc) for (const [key, v] of Object.entries(chunks)) { if (v === null) delete doc.land?.[key]; else (doc.land ??= {})[key] = v; }
      return;
    }
    const isles = this.isles;
    if (!isles || !this.known.has(c)) return;
    const [cx, cz] = cellOfKey(c);
    const d = isles.delta(cx, cz);
    const w = isles.at(cx, cz);
    const moved = w ? applyLandChange(w, d.land, chunks) : [];
    const land = { ...((d.land ?? {}) as unknown as Record<string, string>) };
    for (const [key, v] of Object.entries(chunks)) { if (v === null) delete land[key]; else land[key] = v; }
    if (Object.keys(land).length) d.land = land as unknown as LandBlock; else delete d.land;
    this.landSent.set(c, { ...land });
    if (w && moved.length) this.host.landChanged(w, moved);
  }

  // ---- the towns' books: the host's go up, a guest's come down --------------------------------------

  private rowOut(row: CarriageRow): CarriageRow {
    const me = this.me!.id;
    const v: Record<string, number> = {};
    for (const [c, x] of Object.entries(row[3])) v[c === YOU ? me : c] = x;
    return [row[0], row[1] === YOU ? me : row[1], row[2], v];
  }

  private rowIn(row: CarriageRow): CarriageRow {
    const me = this.me?.id;
    const v: Record<string, number> = {};
    for (const [c, x] of Object.entries(row[3] ?? {})) v[c === me ? YOU : c] = x;
    return [row[0], row[1] === me ? YOU : row[1], row[2], v];
  }

  /** Is a town's carriage far enough from what was last sent to be worth sending again? */
  private carriageMoved(id: string, row: CarriageRow, now: number): boolean {
    const was = this.sent.get(id);
    if (!was) return true;
    const old = JSON.parse(was) as CarriageRow;
    if (old[1] !== row[1]) return true;
    const keys = new Set([...Object.keys(old[3]), ...Object.keys(row[3])]);
    for (const k of keys) {
      const a = old[3][k] ?? 0, b = row[3][k] ?? 0;
      if (Math.abs(a - b) > Math.max(5, 0.04 * Math.max(a, b))) return true;
    }
    return now - (this.sentAt.get(id) ?? 0) > 45000 && was !== JSON.stringify(row);
  }

  /** Send the books of the cells this game is running: only what has changed since they were last sent. */
  private uploadBooks(only?: string, force = false): void {
    if (this.status !== 'on' || !this.me || !this.attached) return;
    const eco = this.host.economy, me = this.me.id, now = performance.now();
    const mine = (k: string) => this.hosts.get(k) === me && (!only || k === only);
    const out = new Map<string, Extract<ClientMsg, { t: 'state' }>>();
    const msg = (k: string) => { let m = out.get(k); if (!m) out.set(k, (m = { t: 'state', c: k })); return m; };
    for (const key of eco.towns.keys()) {
      const k = key.split('#')[0];
      if (!mine(k)) continue;
      const row = eco.exportTown(key);
      if (!row) continue;
      const json = JSON.stringify(row), id = `t|${key}`;
      if (this.sent.get(id) !== json) { this.sent.set(id, json); (msg(k).towns ??= {})[key] = row; }
    }
    for (const key of eco.carriage.keys()) {
      const k = key.split('#')[0];
      if (!mine(k)) continue;
      const raw = eco.carriage.exportTown(key);
      if (!raw) continue;
      const row = this.rowOut(raw), id = `c|${key}`;
      if (force || this.carriageMoved(id, row, now)) { this.sent.set(id, JSON.stringify(row)); this.sentAt.set(id, now); (msg(k).carriage ??= {})[key] = row; }
    }
    for (const [key, l] of eco.lots) {
      const k = key.split('#')[0];
      if (!mine(k) || (!l.ins && !l.outs && !l.lost)) continue;
      const sig = `${l.ins},${l.outs},${l.lost}`, id = `l|${key}`;
      if (this.sent.get(id) !== sig) { this.sent.set(id, sig); (msg(k).lots ??= {})[key] = [r2(l.rate), Math.round(l.at * 10) / 10, l.ins, l.outs, Math.round(l.value), 0, l.lost]; }
    }
    for (const f of this.host.firms.firms.values()) {
      const k = cellKey(f.home[0], f.home[1]);
      if (!mine(k) || !f.id.startsWith(`${k}/`)) continue;
      const id = `f|${f.id}`;
      if (!force && now - (this.sentAt.get(id) ?? -1e9) < 30000) continue;
      const json = JSON.stringify(this.host.firms.saveFirm(f));
      if (this.sent.get(id) !== json) { this.sent.set(id, json); this.sentAt.set(id, now); (msg(k).firms ??= {})[f.id] = JSON.parse(json); }
    }
    for (const m of out.values()) this.send(m);
  }

  private onState(m: Extract<ServerMsg, { t: 'state' }>): void {
    if (!this.attached) {
      const doc = this.docs.get(m.c)?.doc;
      if (doc) { Object.assign((doc.towns ??= {}), m.towns ?? {}); Object.assign((doc.lots ??= {}), m.lots ?? {}); Object.assign((doc.carriage ??= {}), m.carriage ?? {}); }
      return;
    }
    // a late word from whoever ran the cell before this game took it over
    if (this.hosts.get(m.c) === this.me?.id) return;
    for (const [key, r] of Object.entries(m.towns ?? {})) this.host.economy.importTown(key, r as TownLedger);
    for (const [key, v] of Object.entries(m.lots ?? {})) this.importLot(key, v);
    for (const [key, row] of Object.entries(m.carriage ?? {})) this.host.economy.carriage.importTown(key, this.rowIn(row));
  }

  // ---- doors ----------------------------------------------------------------------------------------

  /**
   * Trade at a door (game/estate.ts `remote`): true when it is not for this game to pay. Another player's
   * door: the rent is sent to them. The CPU's trade in a county another game runs: that game's CPU counts.
   */
  private trade(key: string, gross: number, player: boolean): boolean {
    if (!this.active) return false;
    const me = this.me?.id;
    const h = this.hosts.get(key.split('#')[0]);
    if (!player && h && h !== me) return true;
    const row = this.deeds.get(key);
    // a door of mine, or of my shared fleet's: this game pays it into the purse
    if (!row || this.crew.ours(row.by)) return false;
    if (gross > 0) { this.rent.set(key, (this.rent.get(key) ?? 0) + gross); if (player) this.onPaid(key, gross, row.by); }
    return true;
  }

  /** The doors this player holds, kept in step with the server: bought, sold, bulldozed, or made the HQ. */
  private syncDeeds(): void {
    if (!this.attached || !this.me || !this.host.playing()) return;
    const mine = this.host.estate.deeds, me = this.me.id, hq = this.host.fleet.hq;
    const set: Record<string, { name: string; ceil: number; hq?: number; rects?: [number, number, number, number][] }> = {};
    const del: string[] = [];
    for (const [key, d] of mine) {
      const theirs = this.deeds.get(key);
      // the server has it as somebody else's (they bought it first, or while this player was away): it is theirs
      if (theirs && !this.crew.ours(theirs.by)) { this.sentDeeds.delete(key); this.host.estate.revoke(key, this.fleetName(theirs.by)); continue; }
      // a shared fleet's door in a fleet-mate's name: their game keeps it in step with the server
      if (theirs && theirs.by !== me) continue;
      // with the ground its buildings stand on, while its island is in memory to read it from
      const lot = this.host.estate.resolve(key);
      const rects = lot?.all.map((b) => [Math.floor(b.x), Math.floor(b.z), Math.ceil(b.w), Math.ceil(b.d)] as [number, number, number, number]);
      const row = { name: d.name, ceil: Math.round(d.ceil), ...(hq?.key === key ? { hq: hq.grade } : {}), ...(rects?.length ? { rects } : {}) };
      const json = JSON.stringify(row);
      if (this.sentDeeds.get(key) === json) continue;
      this.sentDeeds.set(key, json);
      this.deeds.set(key, { by: me, ...row });
      set[key] = row;
    }
    for (const key of [...this.sentDeeds.keys()]) if (!mine.has(key)) { this.sentDeeds.delete(key); del.push(key); if (this.deeds.get(key)?.by === me) this.deeds.delete(key); }
    // a door the server has as this player's that the career does not: let go of
    for (const [key, row] of this.deeds) if (row.by === me && !mine.has(key)) { del.push(key); this.deeds.delete(key); }
    if (Object.keys(set).length || del.length) this.send({ t: 'deeds', set, del: [...new Set(del)] });
  }

  // ---- far runs (docs/crewtrains.html, Long haul) ---------------------------------------------------

  /** Other players' crewed trains on far runs, as last heard: the route and clock, and when it was heard (seconds). */
  private farRuns = new Map<string, { id: Pid; w: FarWire; at: number }>();
  /** Far runs heard to be over (back, or their player gone), whose stand-ins are still to come off. */
  private farGone: string[] = [];

  /** One of my crewed trains has begun a leg of a far run (or is back: null): its route and clock, once a leg and now and then. */
  sendFar(uid: number, w: FarWire | null): void {
    if (!this.active || this.status !== 'on' || this.guest || !this.attached) return;
    this.send({ t: 'far', uid, w });
  }

  /**
   * Other players' far-run trains drawn here, each frame: a stand-in on this game's own track wherever its clock puts it
   * in a county this game has in memory (game/farRun.ts drawFar), in its fleet's colours; its CPU trains give way to it.
   */
  drawFar(trains: Trains, sh: number): void {
    for (const key of this.farGone.splice(0)) trains.phantom(`p:${key}`, null as never, null, 0);
    if (!this.farRuns.size) return;
    const now = performance.now() / 1000;
    for (const [key, r] of this.farRuns) {
      const t = r.w.t + (now - r.at);
      // (well past the end of the leg with no word: the next leg's word was lost, or the game went; it comes off)
      if (t > legTime(r.w) + r.w.dwell + 30) { this.farRuns.delete(key); trains.phantom(`p:${key}`, null as never, null, 0); continue; }
      const who = this.people.get(r.id);
      const b = who?.brand;
      drawFar(trains, sh, `p:${key}`, r.w, t, { paint: b ? [b.primary, b.accent] : undefined, what: `${b?.name ?? who?.name ?? 'Another fleet'} · long haul` });
    }
  }

  // ---- positions ------------------------------------------------------------------------------------

  private sendPose(): void {
    const w = this.host.home(), v = this.host.veh();
    if (!w || !v || !this.host.playing()) return;
    // stamped with this game's own clock: the others draw it on our timeline, whatever the network did to it
    const now = Math.round(performance.now());
    const p: Pose = [w.cx, w.cz, r2(v.x), r2(v.z), r2(v.y), r3(v.heading), r2(v.v), r3(v.pitch), r3(v.roll), now];
    const m: Extract<ClientMsg, { t: 'm' }> = { t: 'm', p };
    // the working vehicles every other beat
    if (this.beat++ % 2 === 0) {
      m.f = [];
      for (const u of this.host.fleet.units) {
        const a = u.agent;
        if (!a || u.where === 'ridden' || u.where === 'garaged') continue;
        const s = a.state;
        m.f.push([u.uid, a.w.cx, a.w.cz, r2(s.x), r2(s.z), r2(s.y), r3(s.heading), r2(s.v), r3(s.pitch), r3(s.roll), now]);
      }
      // crewed trains (docs/crewtrains.html): the engine on the line, as a train you ride is sent
      for (const u of this.host.fleet.units) {
        const tr = u.where === 'working' ? this.host.fleet.rail?.train(u) : null;
        const p = tr ? enginePose(tr) : null;
        if (p) m.f.push([u.uid, ...p, now]);
      }
    }
    this.send(m);
  }

  /** What this player is driving and which of their vehicles are out, sent when it changes. */
  private syncLook(): void {
    if (!this.host.playing()) return;
    const fleet = this.host.fleet, ridden = fleet.ridden;
    // with the Passport's treats it shows (game/treats.ts): none set, none sent
    const look: Look = { m: ridden?.model ?? this.host.def().id, p: packParts(ridden?.parts), units: [], ...lookTreats(fleet) };
    const d = this.host.drops().slice(0, LOOK_DROPS * 4);
    if (d.length) look.d = d;
    for (const u of fleet.units) {
      // a fleet-mate's vehicle is drawn from their game's positions, as theirs
      if (u.where === 'ridden' || u.where === 'garaged' || u.where === 'towing' || u.away) continue;
      // (a crewed train on the line is drawn from its positions, not stood where it was put to work)
      const standing = !u.agent && !(u.where === 'working' && this.host.fleet.rail?.train(u));
      look.units.push({ uid: u.uid, m: u.model, p: packParts(u.parts), at: standing ? [u.cx, u.cz, Math.round(u.x * 10) / 10, Math.round(u.z * 10) / 10, r2(u.y), r2(u.heading)] : undefined });
    }
    const json = JSON.stringify(look);
    if (json === this.lookSent) return;
    this.lookSent = json;
    this.send({ t: 'look', look });
  }

  /** The fleet has a new name or new colours. */
  setBrand(b: FleetBrand): void {
    // a shared fleet's livery is its founder's to change (docs/sharedfleets.html)
    if (!this.active || !this.me || !this.crew.founder) return;
    this.me = { ...this.me, brand: b };
    this.people.set(this.me.id, this.me);
    this.send({ t: 'brand', brand: b });
  }

  // ---- the career -----------------------------------------------------------------------------------

  /** Send the career to be kept, and this game's lines for the leaderboard. Returns false when it could not be sent. */
  /** When the career last went to the server (Date.now() ms), 0 before the first save this session: the pause card's "last saved". */
  lastSaved = 0;
  /**
   * The server's word that a career was kept ('saved'), and the last time the game tried to save (Date.now() ms).
   * A save sent into a socket that wasn't open used to count as saved, and nothing checked the server had it:
   * a player's saves stopped landing for days with nobody the wiser (the user, 23 Oct 2026).
   */
  lastAck = 0;
  lastTry = 0;
  /** Why the latest save didn't go (or didn't land), for the play report; '' while saves are landing. */
  saveWhy = '';
  /** When this session's saves started counting (signed in, or back from a reconnect). */
  private savesFrom = 0;

  /** How saves stand, for the developer's play reports (net/report.ts). */
  saveState(): { why: string; tried: number; sent: number; ack: number } | null {
    if (!this.active || this.guest) return null;
    return { why: this.saveWhy, tried: this.lastTry, sent: this.lastSaved, ack: this.lastAck };
  }

  /**
   * The autosave: the career built and sent in the next idle moment rather than in the middle of a frame (a whole
   * career, stringified, grows with the session). Within 2 s whatever happens.
   */
  saveSoon(): void {
    if (this.saveQueued) return;
    this.saveQueued = true;
    const run = () => { this.saveQueued = false; this.save(); };
    if (typeof requestIdleCallback === 'function') requestIdleCallback(run, { timeout: 2000 });
    else setTimeout(run, 0);
  }
  private saveQueued = false;

  /**
   * Send the career. A big one (ZIP_FROM) goes gzipped once it is zipped, a moment later; `now` (the page closing,
   * signing out) can't wait for that, and sends the last one zipped instead.
   */
  save(now = false): boolean {
    const p = this.career();
    if (!p) return false;
    let sent: boolean;
    if (p.json.length < ZIP_FROM || typeof CompressionStream === 'undefined') sent = this.send({ t: 'record', record: p.record, board: p.board });
    // (and never one too big for a single message: the server would only close the socket on it)
    else if (now) sent = this.lastZip ? this.send({ t: 'record', z: this.lastZip, board: p.board }) : p.json.length <= ZIP_MAX && this.send({ t: 'record', record: p.record, board: p.board });
    else { void this.sendZipped(p.json, p.board); sent = this.status === 'on'; }
    if (!sent) { this.saveWhy = 'the connection wasn’t open'; return false; }
    this.lastSaved = Date.now();
    return true;
  }

  /** Send the career and wait until it has gone (zipped, if it is big): before something the server reads it for. */
  async saveAndWait(): Promise<boolean> {
    const p = this.career();
    if (!p) return false;
    const sent = p.json.length < ZIP_FROM || typeof CompressionStream === 'undefined'
      ? this.send({ t: 'record', record: p.record, board: p.board })
      : await this.sendZipped(p.json, p.board);
    if (!sent) { this.saveWhy = 'the connection wasn’t open'; return false; }
    this.lastSaved = Date.now();
    return true;
  }

  /** The last career sent zipped, for a save that can't wait to zip one (the page closing). */
  private lastZip = '';

  private async sendZipped(json: string, board: NonNullable<Extract<ClientMsg, { t: 'record' }>['board']>): Promise<boolean> {
    try {
      const z = await gzip64(json);
      // too big to send even zipped: sending it would only cut the connection, so the player is told instead
      if (z.length > ZIP_MAX) { this.recordRefused(`Your career has grown too big for the server to keep (${(json.length / 1048576).toFixed(1)} MB), so nothing since your last save is being kept.`); return false; }
      this.lastZip = z;
      return this.send({ t: 'record', z, board });
    } catch {
      return this.send({ t: 'record', record: JSON.parse(json) as unknown, board });
    }
  }

  /** The career and the board line, as the server keeps them; null (and why) when it can't be sent now. */
  private career(): { record: unknown; json: string; board: NonNullable<Extract<ClientMsg, { t: 'record' }>['board']> } | null {
    this.lastTry = Date.now();
    if (!this.active || this.status !== 'on' || !this.attached || !this.me) {
      this.saveWhy = !this.active ? 'not signed in' : this.status !== 'on' ? `connection ${this.status}` : !this.attached ? 'the world isn’t attached to the server' : 'no player';
      return null;
    }
    const s = this.host.snapshot();
    const you = this.host.metrics.you();
    const cpu: BoardRow[] = [];
    for (const b of this.host.metrics.list()) {
      if (b.you || b.gone !== null) continue;
      const id = b.id.split('@')[0], home = id.split('/')[0];
      if (this.hosts.get(home) !== this.me.id) continue;
      cpu.push({ id, name: b.name, cpu: true, worth: b.v.worth, units: b.v.units, towns: b.v.held, primary: b.livery[0], accent: b.livery[1], logo: b.logo, v: { ...b.v } });
    }
    const record = { ...s, cells: {}, lots: {} };
    // for the fleet card (docs/social.html): the goods the fleet moves most, and its vehicles by model and name
    const goods = this.host.metrics.topGoods(GOODS_MAX);
    const fleetList = this.host.fleet.units.slice(0, FLEET_LIST_MAX).map((u) => ({ m: u.model, n: u.name }));
    const board = { me: { name: you.name, worth: you.v.worth, units: you.v.units, towns: you.v.held, primary: you.livery[0], accent: you.livery[1], logo: you.logo, v: { ...you.v, ...(myNameGilded(this.host.fleet) ? { gilded: 1 } : {}) },
      ...(goods.length ? { goods } : {}), ...(fleetList.length ? { fleet: fleetList } : {}),
      // every kind's loads and every culture's units, for the cargo and culture boards (the server keeps them off the line)
      gA: this.host.metrics.allGoods(), cA: this.host.metrics.allCulture(),
      // loads and dollars by vehicle model, for the vehicle boards (5 Nov 2026)
      vA: this.host.metrics.allInModel(), eA: this.host.metrics.allEarnedIn(),
      // the career's bests, for the world's records (server/records.ts, the Range Trophies)
      rec: { high: deeds.count('altitude'), deep: deeds.count('deepestDive'), jump: deeds.count('longestJump'), haul: deeds.count('farthest') } }, cpu };
    return { record, json: JSON.stringify(record), board };
  }

  /**
   * The watch on saves: a server that says 'saved' back (Welcome.acks) and has said nothing to the last saves for
   * ACK_LOST: the line is dead or the career isn't reaching it. The player is told, and the game reconnects,
   * picking up from where it stands (retry), which is then saved.
   */
  private watchSaves(): void {
    if (!this.welcome?.acks || this.guest || this.status !== 'on' || !this.savesFrom) return;
    // the server has said it won't keep this career: reconnecting won't change that, and the player has been told
    if (this.refused) return;
    const heard = Math.max(this.lastAck, this.savesFrom);
    // only while the game is trying to save (paused or on a menu it may not be)
    if (this.lastTry - heard < ACK_LOST) return;
    if (!this.saveWhy) this.saveWhy = 'no word back from the server';
    this.host.announce('Reconnecting', 'Your last few saves didn’t reach the server, so the game is reconnecting. Nothing is lost: it carries on from here.', 8000);
    const ws = this.ws;
    this.ws = null;
    try { ws?.close(); } catch { /* gone */ }
    for (const w of this.waiters.splice(0)) w.done(null);
    this.lose();
  }

  /** The server won't keep this career (too big): the player is told plainly, in the corner and in red in the chat. */
  private refused = false;
  private refusedTold = 0;
  private recordRefused(why: string): void {
    this.refused = true;
    this.saveWhy = why;
    if (Date.now() - this.refusedTold < 10 * 60_000) return;
    this.refusedTold = Date.now();
    this.host.announce('Your progress isn’t being saved', `${why} Please tell the developer (Esc → Feedback).`, 20000);
    this.ui.line('alert', '', `Your progress isn’t being saved: ${why}`);
  }

  /** Everything unsent goes now: before signing out, or when the page is closing. */
  private flushAll(): void {
    this.flushEdits();
    this.syncDeeds();
    this.uploadBooks(undefined, true);
    if (this.rent.size) { this.send({ t: 'rent', k: Object.fromEntries(this.rent) }); this.rent.clear(); }
  }

  // ---- what the server says -------------------------------------------------------------------------

  private got(m: ServerMsg): void {
    if (this.crew.got(m)) return;
    if (this.extras.some((x) => x.got(m))) return;
    switch (m.t) {
      case 'saved': {
        this.lastAck = Date.now();
        this.saveWhy = '';
        this.refused = false;
        return;
      }
      case 'cell': {
        for (const w of m.people) this.people.set(w.id, w);
        if (!this.attached) { this.docs.set(m.c, { doc: m.doc, host: m.host }); return; }
        if (!this.wanted.has(m.c)) return;
        const [kx, kz] = cellOfKey(m.c);
        // already laid into a cell that is in the world: only who runs it is news
        if (this.known.has(m.c) && this.isles?.at(kx, kz)) { this.hosts.set(m.c, m.host); return; }
        this.layWorld(m.c, m.doc, m.host);
        this.layBooks(m.c, m.doc);
        const [cx, cz] = cellOfKey(m.c);
        this.isles?.admit(cx, cz);
        return;
      }
      case 'host': {
        const d = this.docs.get(m.c);
        if (d) d.host = m.host;
        this.hosts.set(m.c, m.host);
        return;
      }
      case 'edit': this.onEdit(m.c, m.e as Edit); return;
      case 'land': this.onLand(m.c, m.chunks); return;
      case 'state': this.onState(m); return;
      case 'credit': this.host.economy.creditRemote(m.town, m.by, m.amt, m.lot ?? null, m.lotAmt ?? 0, m.dir ?? 'in', !!m.rent); return;
      case 'deed': {
        if (m.who) this.people.set(m.who.id, m.who);
        if (m.row) { this.deeds.set(m.key, m.row); if (!this.crew.ours(m.row.by)) this.host.firms.evict(m.key); }
        else if (this.deeds.get(m.key)?.by !== this.me?.id) this.deeds.delete(m.key);
        return;
      }
      case 'deedDeny': {
        this.people.set(m.who.id, m.who);
        this.sentDeeds.delete(m.key);
        this.deeds.set(m.key, { by: m.who.id, name: '', ceil: 0 });
        this.host.estate.revoke(m.key, this.fleetName(m.who.id));
        return;
      }
      case 'renames': this.renames = m.renames; return;
      case 'deny':
        if (m.what === 'record') { this.recordRefused(m.why); return; }
        // the fleet's look as the server kept it (a rename refused: the old name, the new colours): put it back on
        if (m.what === 'brand' && m.brand) {
          const b = m.brand as FleetBrand;
          if (this.me) { this.me = { ...this.me, brand: b }; this.people.set(this.me.id, this.me); }
          this.host.rebrand(b);
          this.host.announce('Fleet name not changed', m.why, 7000);
          return;
        }
        this.host.announce(m.what === 'raze' ? 'Not yours to clear' : 'The server said no', `${m.why} Your view of this county is out of step until you come back to it.`, 6000); return;
      case 'rent': {
        if (this.host.estate.deeds.has(m.key)) this.host.estate.credit(m.key, m.amt);
        else { this.host.wallet.earn(m.amt, 'rent', 'other'); this.host.cash(); }
        this.onRent(m.key, m.amt, m.from);
        return;
      }
      case 'mv': this.remotes.moves(m.a, m.f); return;
      case 'far': {
        // another player's crewed train on a far run (docs/crewtrains.html): drawn where it is, if near (drawFar)
        const key = `${m.id}:${m.uid}`;
        if (m.w) this.farRuns.set(key, { id: m.id, w: m.w, at: performance.now() / 1000 });
        else if (this.farRuns.delete(key)) this.farGone.push(key);
        return;
      }
      case 'look': this.remotes.setLook(m.id, m.look); return;
      case 'on': {
        const isNew = !this.people.has(m.who.id) || !this.remotes.whoOf(m.who.id);
        this.people.set(m.who.id, m.who);
        this.where.set(m.who.id, m.c);
        this.remotes.join(m.who, m.c, m.look);
        if (isNew && this.attached) this.ui.line('sys', '', `${m.who.name} signed in`);
        return;
      }
      case 'off': {
        const who = this.remotes.whoOf(m.id);
        this.remotes.leave(m.id);
        for (const [key, r] of this.farRuns) if (r.id === m.id) { this.farRuns.delete(key); this.farGone.push(key); }
        this.where.delete(m.id);
        if (who && this.attached) this.ui.line('sys', '', `${who.name} signed out`);
        return;
      }
      case 'tick': {
        this.srvHours = m.hours;
        this.srvAt = performance.now();
        for (const [id, c] of Object.entries(m.at)) { this.where.set(id, c); this.remotes.setCell(id, c); }
        return;
      }
      case 'chat': this.ui.line(m.kind, m.name ?? '', m.text, m.from ? this.people.get(m.from)?.brand?.primary : undefined, m.to, m.from); return;
      case 'board': this.ui.setBoard(m.rows); return;
      case 'friends': this.friends = m.rows; this.onFriends(); return;
      case 'refuse': if (this.active) this.end(m.why); return;
      default: return;
    }
  }

  // ---- every frame ----------------------------------------------------------------------------------

  frame(dt: number, camera: THREE.Camera, focus: { x: number; z: number }, showTags: boolean): void {
    if (!this.active) return;
    if (this.status === 'lost') {
      this.retryT -= dt;
      if (this.retryT <= 0) { this.retryT = 1e9; void this.retry(); }
      return;
    }
    this.watchSaves();
    if (this.status !== 'on' || !this.attached) return;
    if (this.guest) {
      // watching: the cells follow the camera, a word every minute so the server keeps us, and the players drawn
      for (const x of this.extras) x.frame(dt);
      this.slowT -= dt;
      if (this.slowT <= 0) { this.slowT = 1; this.syncCells(); }
      this.heartT -= dt;
      if (this.heartT <= 0) { this.heartT = 60; this.send({ t: 'watch', c: this.watched }); }
      const isles = this.isles;
      this.remotes.update(dt, camera, focus, (cx, cz) => isles?.at(cx, cz) ?? null, showTags);
      return;
    }
    // the one clock is the server's
    const h = this.srvHours + ((performance.now() - this.srvAt) / 1000) * HOURS_PER_SECOND;
    if (Math.abs(h - this.host.hours()) > 0.03) this.host.setHours(h);
    this.flushEdits();
    for (const x of this.extras) x.frame(dt);
    this.crew.frame(dt);
    this.moveT -= dt;
    if (this.moveT <= 0) { this.moveT = Math.max(this.moveT + 1 / MOVE_HZ, 0); this.sendPose(); }
    this.slowT -= dt;
    if (this.slowT <= 0) { this.slowT = 1; this.syncCells(); this.syncDeeds(); this.syncLook(); }
    this.bookT -= dt;
    if (this.bookT <= 0) { this.bookT = 4; this.uploadBooks(); }
    this.rentT -= dt;
    if (this.rentT <= 0 && this.rent.size) { this.rentT = 2; this.send({ t: 'rent', k: Object.fromEntries(this.rent) }); this.rent.clear(); }
    const isles = this.isles;
    this.remotes.update(dt, camera, focus, (cx, cz) => isles?.at(cx, cz) ?? null, showTags);
    this.ui.tick(dt);
  }
}

const ePt = { x: 0, y: 0, z: 0, ang: 0 }, ePt2 = { x: 0, y: 0, z: 0, ang: 0 };
/**
 * A crewed train as another game draws it (net/remote.ts poseTrain): the engine's front, facing the way the engine
 * faces, its speed negative while it runs last car first (turned round at the end of a beat), so the cars behind it
 * are laid along the line the right way round. [cx, cz, x, z, y, heading, v, pitch, roll].
 */
function enginePose(tr: Train): [number, number, number, number, number, number, number, number, number] | null {
  const d = tr.flipped ? tr.length : 0;
  const a = pointBehind(tr, d), b = pointBehind(tr, tr.flipped ? d - 1 : d + 1);
  if (!a || !b) return null;
  sampleAt(a.t, a.s, ePt); sampleAt(b.t, b.s, ePt2);
  // the engine faces away from the rest of its train
  const h = Math.atan2(ePt.x - ePt2.x, ePt.z - ePt2.z);
  const cx = Math.floor(ePt.x / N), cz = Math.floor(ePt.z / N);
  const r2 = (v: number) => Math.round(v * 100) / 100, r3 = (v: number) => Math.round(v * 1000) / 1000;
  return [cx, cz, r2(ePt.x - cx * N), r2(ePt.z - cz * N), r2(ePt.y), r3(h), r2(tr.flipped ? -tr.v : tr.v), 0, 0];
}
