/**
 * The CPU firms in the social window's Fleets tab (net/fleetsTab.ts, docs/social.html; once the Rivals tab
 * of Standings, and before that a window of its own on L; docs/rivals.html). Every firm the player has
 * met as a row — its livery, its trade, how many vehicles it has out, its doors and its takings lately —
 * and, picked, its card: its fleet, its doors, the towns it is winning and what its board has done. And
 * who carries the town the player is in, and what it would take to make it your territory. The Fleets tab
 * draws them and hands this the clicks inside them.
 */
import { esc, money } from './cargoHud';
import { youHtml } from './brand';
import { YOU } from './carriage';
import { BENT_LABEL, STAGE_LABEL, TRADE_LABEL, chip, css, unitWord, type Firm, type Firms } from './firms';
import { townKey, plainName, type Economy } from './ledger';
import { VEHICLES } from './vehicles';
import { rankOf } from './drivers';
import type { Town, World } from '../world/tiles';
import { gradeName, gradePips } from './hqGrade';
import { firmOfferLine, type Buyout } from './buyout';

const BARS = '▁▂▃▄▅▆▇█';

/** A row of block characters for a run of numbers, newest last. */
function spark(days: number[]): string {
  const xs = [...days].reverse();
  const top = Math.max(1, ...xs);
  return xs.map((v) => BARS[Math.min(7, Math.floor((v / top) * 7.99))]).join('');
}

export class FirmsWindow {
  /** Follow one of a firm's vehicles with the camera. */
  onFollow: (f: Firm) => void = () => {};
  /** Asks the Fleets tab to pick a firm (from show()). */
  onShow: (id: string) => void = () => {};
  /** Buying a whole firm (game/buyout.ts), set by main; the firm whose Buy has been pressed once (the second press buys). */
  buyout: Buyout | null = null;
  private arming = '';

  constructor(private firms: Firms, private economy: Economy, private here: () => { w: World; t: Town } | null) {}

  /** A press inside a firm's card: one of its vehicles followed, or the firm bought. True if it was this one's. */
  press(target: HTMLElement): boolean {
    const b = target.closest('.rivals button[data-act][data-id]') as HTMLElement | null;
    if (!b) return false;
    const id = b.dataset.id!;
    if (b.dataset.act === 'follow') {
      const f = this.firms.firm(id);
      if (f) this.onFollow(f);
    } else if (b.dataset.act === 'buyout') {
      const f = this.firms.firm(id);
      if (!f || !this.buyout || b.classList.contains('off')) return true;
      if (this.arming !== id) { this.arming = id; return true; }
      this.arming = '';
      const why = this.buyout.buyFirm(f);
      if (why) this.buyout.say('Can’t buy them', why);
    }
    return true;
  }

  /** Pick one firm in the Fleets tab (the firm's vehicle card, say). */
  show(id: string): void { this.onShow(id); }

  private townName(tk: string): string {
    const [cell, id] = tk.split('#');
    const [cx, cz] = cell.split(',').map(Number);
    for (const d of this.firms.list()) if (d.townKey === tk) return d.town;
    const w = this.worldAt(cx, cz);
    const t = w?.towns[Number(id)];
    return t ? plainName(t) : 'a town far off';
  }

  private worldAt: (cx: number, cz: number) => World | null = () => null;
  setWorlds(at: (cx: number, cz: number) => World | null): void { this.worldAt = at; }

  private detail(f: Firm): string {
    const c = this.economy.carriage;
    const held = c.heldBy(f.id).map((k) => this.townName(k));
    const courting = c.among(f.id, 0.15).filter((x) => c.preferred(x.key) !== f.id).slice(0, 3)
      .map((x) => `${this.townName(x.key)} ${Math.round(x.share * 100)}%`);
    const byModel = new Map<string, number>();
    for (const u of f.units) byModel.set(u.model, (byModel.get(u.model) ?? 0) + 1);
    const fleet = [...byModel].map(([m, n]) => `${n} ${VEHICLES.find((v) => v.id === m)?.name ?? m}`).join(' · ');
    const drivers = f.units.slice(0, 6).map((u) => `${esc(u.driver.name)} <i>${rankOf(u.driver)}</i>`).join(', ');
    const doors = [...f.deeds.values()].map((d) => esc(d.name + (d.key === f.depot ? ' (depot)' : d.key === f.hq.key ? ' (HQ)' : ''))).join(' · ');
    const log = f.log.slice(0, 6).map(([d, what]) => `<li><span>Day ${d + 1}</span> ${esc(what)}</li>`).join('');
    const out = this.firms.out(f);
    const o = this.buyout?.firmOffer(f);
    const armed = this.arming === f.id;
    const buy = o ? `<p><b>Buy them</b> <button type="button" class="link${o.why ? ' off' : ''}" data-act="buyout" data-id="${esc(f.id)}"${o.why ? ` title="${esc(o.why)}"` : ''}>${armed ? `Sure? Pay ${money(o.price)}` : `Buy the whole fleet · ${money(o.price)}`}</button>`
      + ` <small>${esc(o.why ?? firmOfferLine(f, o))}</small></p>` : '';
    return `<div class="more">
      <p><b>Fleet</b> ${esc(fleet) || 'nothing left'} · ${out} out now${out ? ` <button type="button" class="link" data-act="follow" data-id="${esc(f.id)}">follow one</button>` : ''}</p>
      <p><b>Drivers</b> ${drivers}${f.units.length > 6 ? ' …' : ''}</p>
      <p><b>HQ</b> ${f.hq.name ? `${esc(f.hq.name)} <span class="stars">${gradePips(f.hq.grade)}</span> ${esc(gradeName({ grade: f.hq.grade, plus: false }))} · runs ${this.firms.roomOf(f)} vehicles` : 'graded when its town is next in reach'}</p>
      <p><b>Doors</b> ${doors || 'none'}</p>
      <p><b>Territory</b> ${held.length ? esc(held.join(', ')) : 'nowhere yet'}${courting.length ? ` · courting ${esc(courting.join(', '))}` : ''}</p>
      <p><b>Fourteen days</b> <span class="spark">${spark(f.days) || '—'}</span></p>
      <p class="q">Loads you took from under them: ${f.snatched} · tows: ${f.tows} (${money(f.towed)})</p>
      ${buy}
      ${log ? `<ul class="log">${log}</ul>` : ''}
    </div>`;
  }

  /** Every firm met, as the Fleets tab lists them: the ones in memory first, then the rest by distance. */
  list(): Firm[] {
    const town = this.here();
    const tk = town ? townKey(town.w, town.t) : '';
    return this.firms.list().sort((a, b) => Number(this.firms.here(b)) - Number(this.firms.here(a))
      || Number(b.townKey === tk) - Number(a.townKey === tk) || this.firms.away(a) - this.firms.away(b) || b.units.length - a.units.length);
  }

  /** The firms' rows for the Fleets tab: each a pick button and its rate, no detail. */
  rows(): { id: string; name: string; quiet: boolean; html: string }[] {
    return this.list().map((f) => {
      const n = f.units.length;
      const what = `${TRADE_LABEL[f.trade]} · ${STAGE_LABEL[f.stage]} · ${BENT_LABEL[f.bent]}`;
      const line = `${n} ${unitWord(f, n)} · ${f.deeds.size} door${f.deeds.size === 1 ? '' : 's'} · ${esc(f.town)}`;
      const quiet = !this.firms.out(f);
      const html = `<button type="button" class="pick" data-fpick="f:${esc(f.id)}">${chip(f.livery, f.logo)}<span class="what"><b>${esc(f.name)}</b><small>CPU · ${what}</small><small>${line}${quiet ? ' · quiet: not in memory' : ''}</small></span></button>
        <span class="pay"><em>${money(Math.round(this.firms.rateOf(f)))}</em><small>an hour</small></span>`;
      return { id: f.id, name: f.name, quiet, html };
    });
  }

  /** A firm's card: its head and the detail, in the Fleets tab's right column. Empty when the firm is gone. */
  firmCard(id: string): string {
    const f = this.firms.firm(id);
    if (!f) return '';
    const n = f.units.length;
    const out = this.firms.out(f);
    return `<div class="rivals fcard firm"><header class="fc-head">${chip(f.livery, f.logo)}<div><h3>${esc(f.name)}</h3>
      <div class="fc-who">CPU firm · ${TRADE_LABEL[f.trade]} · ${STAGE_LABEL[f.stage]} · ${BENT_LABEL[f.bent]} · from ${esc(f.town)}</div>
      <div class="fc-who">${n} ${unitWord(f, n)} · ${out} out now · ${f.deeds.size} door${f.deeds.size === 1 ? '' : 's'} · ${money(Math.round(this.firms.rateOf(f)))} an hour</div></div></header>
      ${this.detail(f)}</div>`;
  }

  /** Who carries the town the player is in, and what it would take to make it yours. */
  carriers(): string {
    const at = this.here();
    if (!at) return '';
    const tk = townKey(at.w, at.t), c = this.economy.carriage;
    const shares = c.shares(tk);
    const pref = c.preferred(tk);
    const bar = shares.map((s) => `<i style="width:${(s.share * 100).toFixed(1)}%;background:${s.who ? css(this.firms.carrierColour(s.who)) : '#c9ced4'}"></i>`).join('');
    const names = shares.filter((s) => s.share >= 0.03).map((s) => {
      const f = this.firms.firm(s.who);
      const lab = s.who === YOU ? youHtml() : f ? `${chip(f.livery, f.logo)}${esc(f.name)}` : s.who ? 'a firm long gone' : 'others';
      return `${lab} ${Math.round(s.share * 100)}%`;
    }).join(' · ');
    const gap = c.gap(tk, YOU);
    const lead = pref ? `<b>${pref === YOU ? 'Your' : `${esc(this.firms.carrierName(pref))}’s`}</b> territory since day ${c.since(tk) + 1}` : 'Nobody’s territory';
    return `<div class="town">
      <b>Who carries ${esc(plainName(at.t))}</b>
      ${shares.length ? `<div class="bar">${bar}</div><small>${names}</small>` : '<small>Nobody has carried anything here lately.</small>'}
      <small class="pref">${lead}${pref === YOU ? ' · half the levy, first refusal on its loads' : gap ? ` · to take it: about ${money(gap)} more trade` : ''}</small>
    </div>`;
  }
}
