import type { Building, BuildingKind } from '../../../world/tiles';
import { curArch, type Draw } from '../kit';
import { HOUSE_VARIANTS } from './houses';
import { BLOCK_VARIANTS } from './blocks';
import { HOME_VARIANTS } from './homes';
import { FARM_VARIANTS } from './farm';
import { TOWN_VARIANTS } from './town';
import { HARBOUR_VARIANTS } from './harbour';
import { GOLF_VARIANTS } from './golf';
import { LIDO_VARIANTS } from './lido';
import { TERMINAL_VARIANTS } from './terminals';
import { GLASS_VARIANTS } from './glass';
import { deckSlab } from './blocks';
import { conservatoryCafe, jettiedInn } from './town';
import { NEXT_WORLD } from '../../../world/nextWorld';
import { NEON_VARIANTS, SHOWBIZ_VARIANTS, neonless } from '../showbiz';

/**
 * Alternative models for the kinds a world is mostly made of (the census of 22 Sep 2026: the top 25
 * kinds per tile in any world mode get one, the top 10 two, the top 3 three), so a street of houses is
 * not one house over and over.
 *
 * Each alternative is drawn in the same local frame, on the same lot, as the kind's own model, and
 * keeps its walls inside the kind's solid shape (world/footprint.ts SHAPES; a kind with no shape is
 * solid over its lot), since that is what the car meets. It follows the town's style through the same
 * helpers the original does (cur, styleWall, roofOver, ...), so a Dutch street's alternatives are Dutch.
 *
 * Render only: which model a building draws is picked from its seed here, never stored, so worlds and
 * saves are untouched. The original is one of the choices, all equally likely.
 */
export const VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  ...HOUSE_VARIANTS, ...BLOCK_VARIANTS, ...HOME_VARIANTS, ...FARM_VARIANTS, ...TOWN_VARIANTS, ...HARBOUR_VARIANTS,
  // not common kinds, but ones that read as one course over and over without layouts of their own (./golf.ts)
  ...GOLF_VARIANTS,
  // the pools (lido.ts): kept in lidoPlan.ts's order, which the bathers and swim meets read the model number by
  ...LIDO_VARIANTS,
  // airport terminals after famous ones (terminals.ts): TWA, Dulles, Denver, Kansai, Barajas T4; 0.7.0's, like every model
  // change since 0.6.7, so a 0.6.x build draws terminals as it always has
  ...(NEXT_WORLD ? TERMINAL_VARIANTS : {}),
  // the glass spire's twelve other towers (glass.ts), since 0.7.1
  ...GLASS_VARIANTS,
};
// the old-school places to go out (../showbiz.ts): appended after a kind's own alternatives, never in front
// of them, so a building already drawing one keeps it (marquees.ts counts on the order)
for (const [kind, list] of Object.entries(SHOWBIZ_VARIANTS) as [BuildingKind, Draw[]][]) VARIANTS[kind] = [...(VARIANTS[kind] ?? []), ...list];

/** How many models a kind has, its own included. */
export const variantCount = (kind: BuildingKind): number => 1 + (VARIANTS[kind]?.length ?? 0);

/** Dev and audits: draw this building as model n (0 = the kind's own) whatever its seed says. */
export const VARIANT_PIN = new WeakMap<Building, number>();

/** Which model this building draws: 0 is the kind's own, n its n-th alternative. */
export function variantOf(b: Building): number {
  const n = variantCount(b.kind);
  if (n === 1) return 0;
  const pin = VARIANT_PIN.get(b);
  if (pin !== undefined) return Math.min(pin, n - 1);
  // a hash of the seed apart from the model's own random stream (mulberry32(seed)), so the original
  // still draws exactly as it did wherever it is picked
  let h = Math.imul((b.seed ^ 0x5bd1e995) >>> 0, 0x9e3779b1);
  h ^= h >>> 15; h = Math.imul(h, 0x85ebca6b); h ^= h >>> 13;
  return (h >>> 0) % n;
}

/** The alternative this building draws, or null for the kind's own model. */
export function variantDraw(b: Building): Draw | null {
  // an Adriatic old town's houses are its own narrow pairs, never another street's (townMesh townhouse)
  if (b.kind === 'townhouse' && curArch === 'adriatic') return null;
  const v = variantOf(b);
  const d = v ? VARIANTS[b.kind]![v - 1] : null;
  // 0.7.0 (docs/models070-audit.md): no deck-access slab, Tudor coaching inn or glasshouse café in a Rovinj
  if (NEXT_WORLD && curArch === 'adriatic' && (d === deckSlab || d === jettiedInn || d === conservatoryCafe)) return null;
  // a neon bar or diner in a town of an older world than neon draws the kind's own model (the style is
  // set before the model is asked for: townMesh drawBuilding, modelFootprint)
  return d && NEON_VARIANTS.has(d) && neonless() ? null : d;
}
