import * as THREE from 'three';

/**
 * A launch (docs/supplychains.html, chain 23): when a launch pad of the fleet's sends a satellite up, a rocket rises off
 * it on a column of smoke and is gone into the sky in about ten seconds. Plain meshes in world space, made when needed.
 */

interface Flight { rocket: THREE.Group; t: number; x: number; y: number; z: number; puffs: { m: THREE.Mesh; t: number }[]; next: number }

const RISE = 10;
const PUFF = new THREE.SphereGeometry(0.22, 8, 6);

export class LaunchFx {
  readonly group = new THREE.Group();
  private flights: Flight[] = [];
  private body = new THREE.CylinderGeometry(0.1, 0.12, 1.1, 10).translate(0, 0.55, 0);
  private nose = new THREE.ConeGeometry(0.1, 0.32, 10).translate(0, 1.26, 0);
  private fin = new THREE.BoxGeometry(0.34, 0.2, 0.03).translate(0, 0.1, 0);
  private white = new THREE.MeshLambertMaterial({ color: 0xf4f2ec });
  private red = new THREE.MeshLambertMaterial({ color: 0xe2412f });
  private flame = new THREE.MeshBasicMaterial({ color: 0xffb040 });

  constructor(scene: THREE.Scene) { scene.add(this.group); }

  /** Lift-off from (x, y, z), world tiles. */
  launch(x: number, y: number, z: number): void {
    const rocket = new THREE.Group();
    rocket.add(new THREE.Mesh(this.body, this.white), new THREE.Mesh(this.nose, this.red));
    for (const a of [0, Math.PI / 2]) { const f = new THREE.Mesh(this.fin, this.red); f.rotation.y = a; rocket.add(f); }
    const fl = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.4, 8).rotateX(Math.PI).translate(0, -0.2, 0), this.flame);
    rocket.add(fl);
    rocket.position.set(x, y, z);
    this.group.add(rocket);
    this.flights.push({ rocket, t: 0, x, y, z, puffs: [], next: 0 });
  }

  update(dt: number): void {
    for (let k = this.flights.length - 1; k >= 0; k--) {
      const f = this.flights[k];
      f.t += dt;
      // slow off the pad, then away
      const h = 0.4 * f.t * f.t;
      f.rocket.position.set(f.x + f.t * f.t * 0.02, f.y + h, f.z);
      f.next -= dt;
      if (f.t < RISE - 2 && f.next <= 0) {
        f.next = 0.08;
        const m = new THREE.Mesh(PUFF, new THREE.MeshLambertMaterial({ color: 0xe8e8e8, transparent: true, opacity: 0.8 }));
        m.position.set(f.rocket.position.x + (Math.random() - 0.5) * 0.2, f.rocket.position.y - 0.1, f.rocket.position.z + (Math.random() - 0.5) * 0.2);
        this.group.add(m);
        f.puffs.push({ m, t: 0 });
      }
      for (const p of f.puffs) {
        p.t += dt;
        p.m.scale.setScalar(1 + p.t * 1.6);
        (p.m.material as THREE.MeshLambertMaterial).opacity = Math.max(0, 0.8 - p.t * 0.16);
      }
      if (f.t >= RISE) {
        this.group.remove(f.rocket);
        for (const p of f.puffs) { this.group.remove(p.m); (p.m.material as THREE.Material).dispose(); }
        this.flights.splice(k, 1);
      }
    }
  }
}
