import * as THREE from 'three';
import type { VehicleState } from '../game/vehicles';

const MAX = 120;

/** Little foam puffs left behind anything moving through water. */
export class Wake {
  readonly mesh: THREE.InstancedMesh;
  private px = new Float32Array(MAX);
  private py = new Float32Array(MAX);
  private pz = new Float32Array(MAX);
  private age = new Float32Array(MAX).fill(1);
  private life = new Float32Array(MAX).fill(1);
  private size = new Float32Array(MAX);
  private next = 0;
  private acc = 0;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private pos = new THREE.Vector3();
  private scl = new THREE.Vector3();

  constructor() {
    const g = new THREE.CircleGeometry(0.5, 10);
    g.rotateX(-Math.PI / 2);
    const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.6, depthWrite: false });
    this.mesh = new THREE.InstancedMesh(g, mat, MAX);
    this.mesh.frustumCulled = false;
    this.m.makeScale(0, 0, 0);
    for (let i = 0; i < MAX; i++) this.mesh.setMatrixAt(i, this.m);
  }

  private spawn(x: number, y: number, z: number, size: number): void {
    const i = this.next;
    this.next = (this.next + 1) % MAX;
    this.px[i] = x; this.py[i] = y; this.pz[i] = z;
    this.age[i] = 0;
    this.life[i] = 1.1 + Math.random() * 0.5;
    this.size[i] = size;
  }

  update(dt: number, s: VehicleState, halfLen: number, halfWid: number): void {
    const speed = Math.abs(s.v);
    if (!Number.isNaN(s.surfaceY) && speed > 0.4 && dt > 0) {
      this.acc += dt * Math.min(14, 3 + speed * 2.2);
      const fx = Math.sin(s.heading), fz = Math.cos(s.heading);
      const rx = fz, rz = -fx;
      const back = s.v >= 0 ? -halfLen : halfLen;
      while (this.acc >= 1) {
        this.acc -= 1;
        for (const side of [-1, 1]) {
          const off = side * halfWid * 0.7;
          this.spawn(s.x + fx * back + rx * off, s.surfaceY + 0.02, s.z + fz * back + rz * off, halfWid * (0.7 + speed * 0.06));
        }
      }
    } else {
      this.acc = 0;
    }
    for (let i = 0; i < MAX; i++) {
      this.age[i] += dt;
      const t = this.age[i] / this.life[i];
      const k = t >= 1 ? 0 : this.size[i] * (0.35 + 1.6 * t) * (1 - t * t);
      this.pos.set(this.px[i], this.py[i], this.pz[i]);
      this.scl.set(k, 1, k);
      this.m.compose(this.pos, this.q, this.scl);
      this.mesh.setMatrixAt(i, this.m);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }
}
