/**
 * The one "ready: press Enter to start" prompt (the user, 26 Oct 2026: the key that starts a night shoot, a
 * race or a tow should be plain on screen). A big key cap, pulsing, with the mission's name and what the key
 * does, low in the middle of the screen. It shows only while that key really would start something: each owner
 * calls `show` every frame it could start and `hide` the moment it starts or the player leaves. The main loop
 * calls `frame` once at the top of every frame, which drops any claim the last frame didn't renew (a menu up,
 * the title, the mission gone), so nothing can leave it standing.
 */

export type StartKey = 'Enter' | 'Space';

export interface StartSpec {
  key: StartKey;
  /** The mission or activity, small over the line: "Night shoot · Take 1 of 3". */
  title: string;
  /** What the key does, after "to": "call Action". */
  action: string;
  /** A short rider under it, if any. */
  sub?: string;
  /** A card it sits inside instead of over the middle of the screen, where that card is centred too (a PvP line's). */
  dock?: HTMLElement;
}

const KEY_TEXT: Record<StartKey, string> = { Enter: 'Enter ⏎', Space: 'Space' };
const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);

class StartPrompt {
  /** Each owner's claim, and whether it was renewed since the last `frame`. */
  private claims = new Map<string, { spec: StartSpec; live: boolean }>();
  private el: HTMLDivElement | null = null;
  private sig = '';

  /** `owner` can start now with `spec`'s key. Call every frame it can. */
  show(owner: string, spec: StartSpec): void {
    if (typeof document === 'undefined') return;
    this.claims.delete(owner); // the newest claim is the one shown
    this.claims.set(owner, { spec, live: true });
    this.paint();
  }

  /** `owner` can't start any more (it started, the player left, it ended). */
  hide(owner: string): void {
    if (this.claims.delete(owner)) this.paint();
  }

  /** The top of a frame: claims the last frame didn't renew are dropped. */
  frame(): void {
    let gone = false;
    for (const [k, c] of this.claims) {
      if (!c.live) { this.claims.delete(k); gone = true; } else c.live = false;
    }
    if (gone) this.paint();
  }

  /** Who the prompt is up for, or null (the bots and the console). */
  get showing(): string | null { return [...this.claims.keys()].pop() ?? null; }

  private paint(): void {
    const last = [...this.claims.values()].pop();
    if (!last) {
      if (this.el) this.el.hidden = true;
      this.sig = '';
      return;
    }
    const s = last.spec;
    const sig = `${s.key}|${s.title}|${s.action}|${s.sub ?? ''}`;
    if (!this.el) {
      this.el = document.createElement('div');
      this.el.id = 'start-prompt';
      this.el.className = 'hud';
      this.el.setAttribute('role', 'status');
    }
    // in its dock (put back after the card redraws itself), else over the middle of the screen
    const parent = s.dock ?? document.body;
    if (this.el.parentElement !== parent) parent.append(this.el);
    this.el.classList.toggle('docked', !!s.dock);
    if (sig === this.sig) return;
    // a prompt coming up pops in; one changing its words while up (the next take) doesn't
    const fresh = !this.sig;
    this.sig = sig;
    this.el.innerHTML = `<kbd class="sp-key${s.key === 'Space' ? ' wide' : ''}">${KEY_TEXT[s.key]}</kbd>`
      + `<div class="sp-text"><div class="sp-title">${esc(s.title)}</div><div class="sp-act">Press <b>${s.key}</b> to ${esc(s.action)}</div>`
      + `${s.sub ? `<div class="sp-sub">${esc(s.sub)}</div>` : ''}</div>`;
    this.el.hidden = false;
    if (fresh) { this.el.classList.remove('pop'); void this.el.offsetWidth; this.el.classList.add('pop'); }
  }
}

/** The game's one start prompt. */
export const startPrompt = new StartPrompt();
