import { N, STEP, Biome, DIRS, Flag, World, idx, inB, waterDepth, type Building, type PlantKind } from './tiles';
import type { Rng } from './rng';
import { buildingHeight } from './towns';
import { solidMask } from './footprint';
import { KIND_SPEC } from './townKinds';

/**
 * The supply chains' plants (docs/supplychains.html, "World generation"; held for 0.8.0, world/nextWorld.ts
 * NEXT_080): seventeen kinds of works that turn one good into a dearer one where no building of the island already
 * does. Each stands on a lot just outside a town's lines with its front on a road, chosen by what is near (a creamery
 * by the dairies, a joinery by a sawmill, a smokehouse by a harbour), at most one of a kind a county. Placed after
 * every other building on a random stream of its own (generate.ts), so nothing else in a county moves.
 */

interface Row {
  kind: PlantKind;
  w: number; d: number;
  /** The share of counties that get one, before a lot is looked for. */
  chance: number;
  /** What the lot wants round it: a score, or null where it won't do. */
  want: (c: Ctx, x: number, z: number) => number | null;
}

interface Ctx {
  w: World;
  near: (x: number, z: number, r: number, test: (i: number) => boolean) => number;
  /** Tiles to the nearest town's edge (of the big ones only, with `big`), and that town's kind. */
  town: (x: number, z: number, big?: boolean) => number;
  has: (x: number, z: number, r: number, kinds: Set<string>) => boolean;
}

const S = (...k: string[]) => new Set(k);
const DAIRY = S('dairy', 'farmhouse', 'barn', 'ranchHouse');
const BOOKISH = S('library', 'university', 'school', 'museum');
const TIMBER = S('sawmill', 'lumberYard', 'lumberSiding', 'loggingCamp');
const QUARRY = S('crusher', 'mineHeadframe', 'gravelPlant', 'cementPlant', 'oreMill', 'quarry');
const VINES = S('vineyard', 'wineryBarn', 'orchard');
const SEABED = S('noduleField', 'ventField', 'seaHabitat');
const FASHION = S('departmentStore', 'operaHouse', 'premiereTheatre', 'theatre', 'mall');
const PLANTATION = S('plantation', 'plantationManor', 'teaHouse', 'tradingPost');
const SPIRITS = S('distillery', 'wineryBarn', 'vineyard', 'brewery', 'pub');
const FINE = S('museum', 'exchange', 'bank', 'mansion', 'casino');
const MUSIC = S('concertHall', 'operaHouse', 'theatre', 'nightclub');

const cold = (w: World) => (i: number) => w.biome[i] === Biome.Snow || w.biome[i] === Biome.Ice || w.biome[i] === Biome.Mountain;
const coast = (c: Ctx, x: number, z: number) => c.w.coastDist[idx(x, z)];

const ROWS: Row[] = [
  { kind: 'iceHouse', w: 2, d: 2, chance: 0.55, want: (c, x, z) => { const k = c.near(x, z, 8, cold(c.w)); return k >= 10 ? 20 + k : coast(c, x, z) <= 10 ? 12 - coast(c, x, z) * 0.5 : null; } },
  { kind: 'creamery', w: 3, d: 2, chance: 0.5, want: (c, x, z) => (c.has(x, z, 40, DAIRY) ? 30 - c.town(x, z) : null) },
  { kind: 'bindery', w: 2, d: 2, chance: 0.45, want: (c, x, z) => (c.town(x, z, true) <= 6 && c.has(x, z, 40, BOOKISH) ? 30 - c.town(x, z) : null) },
  { kind: 'joinery', w: 3, d: 2, chance: 0.5, want: (c, x, z) => (c.has(x, z, 60, TIMBER) ? 25 - c.town(x, z) : null) },
  { kind: 'printShop', w: 2, d: 2, chance: 0.6, want: (c, x, z) => { const d = c.town(x, z); return d <= 4 ? 20 - d : null; } },
  { kind: 'parcelHub', w: 3, d: 3, chance: 0.4, want: (c, x, z) => { const d = c.town(x, z, true); return d <= 8 ? 25 - d : null; } },
  { kind: 'readyMix', w: 3, d: 3, chance: 0.45, want: (c, x, z) => (c.has(x, z, 50, QUARRY) && c.town(x, z) <= 12 ? 25 - c.town(x, z) : null) },
  { kind: 'smokehouse', w: 2, d: 2, chance: 0.55, want: (c, x, z) => { const k = coast(c, x, z); return k <= 6 ? 20 - k * 2 : null; } },
  { kind: 'winery', w: 3, d: 2, chance: 0.5, want: (c, x, z) => (c.has(x, z, 40, VINES) ? 25 - c.town(x, z) * 0.5 : null) },
  { kind: 'alloyWorks', w: 3, d: 3, chance: 0.5, want: (c, x, z) => (coast(c, x, z) <= 8 && c.has(x, z, 120, SEABED) ? 30 - coast(c, x, z) : null) },
  { kind: 'atelier', w: 2, d: 2, chance: 0.4, want: (c, x, z) => (c.town(x, z, true) <= 4 && c.has(x, z, 40, FASHION) ? 25 - c.town(x, z) : null) },
  { kind: 'roastery', w: 2, d: 2, chance: 0.5, want: (c, x, z) => (c.has(x, z, 70, PLANTATION) ? 25 - c.town(x, z) * 0.5 : null) },
  { kind: 'cooperage', w: 2, d: 2, chance: 0.45, want: (c, x, z) => (c.has(x, z, 50, SPIRITS) && c.has(x, z, 80, TIMBER) ? 20 - c.town(x, z) * 0.5 : null) },
  { kind: 'glassworks', w: 3, d: 2, chance: 0.45, want: (c, x, z) => (c.has(x, z, 60, QUARRY) && c.town(x, z) <= 14 ? 25 - c.town(x, z) : null) },
  { kind: 'auctionHouse', w: 2, d: 2, chance: 0.4, want: (c, x, z) => (c.town(x, z, true) <= 4 && c.has(x, z, 40, FINE) ? 25 - c.town(x, z) : null) },
  { kind: 'luthier', w: 2, d: 1, chance: 0.45, want: (c, x, z) => (c.has(x, z, 40, MUSIC) && c.town(x, z) <= 4 ? 20 - c.town(x, z) : null) },
  { kind: 'outfitter', w: 2, d: 2, chance: 0.55, want: (c, x, z) => { const k = c.near(x, z, 10, cold(c.w)); return k >= 14 && c.town(x, z) <= 6 ? 15 + k * 0.3 : null; } },
];

/** Tiles out from a town's edge a plant may stand. */
const OUT_MAX = 6;
/** Two plants of any kind stand at least this far apart, in tiles. */
const APART = 6;

/** The plants of one county, each where it finds a lot beside a road. */
export function placePlants(w: World, rng: Rng, band: number): Building[] {
  const out: Building[] = [];
  if (!w.towns.length) return out;
  const lo = band + 3, hi = N - band - 3;
  const free = (x: number, z: number) => {
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    const i = idx(x, z);
    return w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.feature[i] === 0 && waterDepth(w, i) === 0 && w.water[i] < 0
      && !(w.flags[i] & (Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor | Flag.Field));
  };
  const townEdge = (x: number, z: number, big = false) => {
    let best = 999;
    for (const t of w.towns) {
      if (big && t.kind !== 'city' && t.kind !== 'metro' && t.kind !== 'mega') continue;
      best = Math.min(best, Math.max(0, Math.abs(x - (t.x0 + t.size / 2)) - t.size / 2, Math.abs(z - (t.z0 + t.size / 2)) - t.size / 2));
    }
    return best;
  };
  const ctx: Ctx = {
    w,
    near: (x, z, r, test) => {
      let n = 0;
      for (let zz = z - r; zz <= z + r; zz += 2) for (let xx = x - r; xx <= x + r; xx += 2) if (inB(xx, zz) && test(idx(xx, zz))) n++;
      return n;
    },
    town: townEdge,
    has: (x, z, r, kinds) => w.allBuildings.some((b) => !b.gone && kinds.has(b.kind) && Math.abs(b.x + b.w / 2 - x) <= r && Math.abs(b.z + b.d / 2 - z) <= r),
  };
  /** Every tile of the lot free and flat enough, and a road right in front of one side. Returns the side it faces, or -1. */
  const lotFace = (x: number, z: number, wx: number, wz: number): number => {
    let lo2 = 127, hi2 = -128;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
      if (!inB(xx, zz) || !free(xx, zz)) return -1;
      const i = idx(xx, zz);
      for (let k = 0; k < 4; k++) { const c = w.corners[i * 4 + k]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
    }
    if (hi2 - lo2 > 1) return -1;
    // the side with the most road along it is the front
    let best = -1, most = 0;
    for (let d = 0; d < 4; d++) {
      const [dx, dz] = DIRS[d];
      let n = 0;
      for (let k = 0; k < (dx ? wz : wx); k++) {
        const tx = dx > 0 ? x + wx : dx < 0 ? x - 1 : x + k, tz = dz > 0 ? z + wz : dz < 0 ? z - 1 : z + k;
        if (inB(tx, tz) && w.road[idx(tx, tz)]) n++;
      }
      if (n > most) { most = n; best = d; }
    }
    return best;
  };
  // the tiles worth trying as a lot's corner: off the road, outside the towns, near one
  const spots: number[] = [];
  for (let i = 0; i < N * N; i++) {
    if (!w.road[i]) continue;
    const x = i % N, z = (i - x) / N;
    if (townEdge(x, z) > OUT_MAX) continue;
    for (const [dx, dz] of DIRS) { const tx = x + dx, tz = z + dz; if (inB(tx, tz) && free(tx, tz)) spots.push(idx(tx, tz)); }
  }
  if (!spots.length) return out;
  for (const row of ROWS) {
    // the roll is made whether or not the row finds a lot, so one row's luck never moves another's
    if (rng() >= row.chance) continue;
    let best: { x: number; z: number; f: number; score: number } | null = null;
    for (let tries = 0; tries < 200; tries++) {
      const s = spots[Math.floor(rng() * spots.length)];
      const x = (s % N) - Math.floor(rng() * row.w), z = Math.floor(s / N) - Math.floor(rng() * row.d);
      const f = lotFace(x, z, row.w, row.d);
      if (f < 0) continue;
      if (out.some((b) => Math.abs(b.x - x) < APART && Math.abs(b.z - z) < APART)) continue;
      const score = row.want(ctx, x + Math.floor(row.w / 2), z + Math.floor(row.d / 2));
      if (score === null) continue;
      const sc = score + rng() * 3;
      if (!best || sc > best.score) best = { x, z, f, score: sc };
    }
    if (!best) continue;
    out.push(put(w, rng, row.kind, best.x, best.z, row.w, row.d, best.f));
  }
  return out;
}

/** A plant on its lot, levelled, its solid part blocking the ground, as the rail-side works are (world/railside.ts). */
function put(w: World, rng: Rng, kind: PlantKind, x: number, z: number, wx: number, wz: number, facing: number): Building {
  const solid = KIND_SPEC[kind]?.solid !== false;
  let sum = 0;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
  const level = Math.round(sum / (wx * wz * 4));
  const b: Building = { kind, x, z, w: wx, d: wz, facing: facing as Building['facing'], floors: 1, seed: Math.floor(rng() * 2 ** 31), solid, level, uid: w.allBuildings.length };
  w.allBuildings.push(b);
  w.countryside.push(b);
  const top = level * STEP + buildingHeight(b);
  const mask = solid ? solidMask(b) : null;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    for (let q = 0; q < 4; q++) w.corners[i * 4 + q] = level;
    if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  return b;
}
