/** What an offer's diamond shows on its mat, by the kind of work. */
const OFFER_ICON: Partial<Record<Mission['kind'], string>> = { job: '📋', race: '🏁', tow: '🪝', trip: '🧭', tail: '🕵️' };
import { speedText } from '../units';

/** Where a unit counts as out on the road with its driver. */
const ON_ROAD = new Set(['working', 'enroute', 'shadowed', 'waiting', 'towing']);
/** A mission's standing reward (docs/standing.html): trade on the town's books, this share of its whole figure a step… */
const TALK_UP = 0.12;
/** …and never less than this many dollars, so a town that has seen little trade still hears of it. */
const TALK_UP_MIN = 60;

/**
 * How many missions may be under way at once, and what opens the next: one for the first five minutes of
 * a game, two until ten, three once there is an HQ as well, and five once two drivers are out on the road
 * with you (a fleet of three). The getting-started missions don't count, and while they last (the first
 * drive, then an HQ, a second vehicle and a driver out: game/fleetTrack.ts) they keep one of the two
 * slots for themselves, so only one other mission is taken on beside them.
 */
export function activeCap(played: number, hq: boolean, driversOut: number, learning = false): { n: number; next: string } {
  if (learning) return { n: 1, next: 'One more once the getting-started missions are done' };
  if (played < 300) return { n: 1, next: `A second mission opens ${Math.ceil((300 - played) / 60)} min into the game` };
  if (played < 600) return { n: 2, next: `A third opens ${Math.ceil((600 - played) / 60)} min from now, once you own an HQ` };
  if (driversOut >= 2 && hq) return { n: 5, next: '' };
  if (hq) return { n: 3, next: 'Up to five with two drivers of yours out on the road' };
  return { n: 2, next: 'Buy your first HQ to take on a third' };
}

interface MissionDeps {
  scene: THREE.Scene;
  camera(): THREE.Camera;
  worldAt(cx: number, cz: number): World | null;
  resident(): World[];
  seed(): string;
  hours(): number;
  /** Seconds played in this game, for how many missions may be under way at once. */
  played(): number;
  /** The player: island, state in its frame, what they drive. Null with nobody out. */
  player(): { w: World; state: VehicleState; def: VehicleDef } | null;
  place(): Place | null;
  progress(): Progress;
  cargo: CargoSystem;
  fleet: Fleet;
  formation: Formation;
  estate: Estate;
  economy: Economy;
  wallet: Wallet;
  /** Car ferries sailing from a harbour of the player's island. */
  ferries(): { from: Port; to: { w: World; port: Port } }[];
  announce(title: string, body: string): void;
  float(text: string, kind: 'cash' | 'info'): void;
  cash(): void;
  /** The rush on offer's diamond (game/rushes), or null: it takes one of the map's two (Missions.onMap). */
  rushDoor?(): Door | null;
  /** Pay diamonds in as a bonus (a convoy's reward), `what` paid them. */
  gems?(n: number, what: string): void;
  /** Put a new unit down beside the player (parked), returning it. */
  giveUnit(model: string): Unit | null;
  /**
   * The first drive's helping hand has been taken on (docs/helpinghand.html): she joins the fleet now, in a car of
   * her own painted `colour`, in Follow mode behind the player; she only says she is staying at the end.
   */
  joinHand?(name: string, colour: number): void;
  /** Point the camera at a place in world tiles; with no place, back on the player's vehicle. */
  look(x?: number, z?: number): void;
  bump(strength: number): void;
  beep(final: boolean): void;
  crack(): void;
  /** Traffic on an island, in its own tiles, for a rival to brake behind. */
  traffic(w: World): { x: number; z: number }[];
  /** The helicopter searchlight's pool on the ground, world tiles; null while it is off. */
  spot(): { x: number; z: number; r: number } | null;
  /** Dark enough for the searchlight. */
  dark(): boolean;
  /** A tip a mission paid in (a tavern's): write it in the notebook. */
  heard?(line: string, from: string): void;
  /** The road traffic of a cell in memory: a tail's target is put on the road in it (game/tail). */
  trafficOf?(w: World): Traffic | null;
  /** The railway, for a tail that follows a train. */
  trains?(): Trains | null;
  /** How dark it is for driving, 0..1: a tail's mirror sees less of a car running dark at night. */
  gloom?(): number;
  /** What a tail turned up, made real: a rival's depot lit, a contact told to call. A string when it couldn't be. */
  reveal?(r: Extract<Reward, { r: 'reveal' }>): string | null;
  /** Rival firms' depots in memory (game/firms.ts), for the tails that follow one of their vans home. */
  depots?(): { id: string; name: string; colour: number; x: number; z: number; cell: [number, number]; town: string }[];
  /** Hidden vehicles nobody has claimed in the cells in memory (game/stash.ts), for a courier's tail to lead to. */
  stashes?(): { key: string; model: string; cx: number; cz: number; x: number; z: number; place: string }[];
  /** The world's effect on a town, as the old requests did it. */
  effect(w: World, t: Town, effect: Extract<Reward, { r: 'effect' }>['effect']): boolean;
  /** Why a building is somebody else's (a CPU fleet's or another player's, or already gone), or null: a knock-down leaves those be. */
  held?(w: World, b: Building): string | null;
  /**
   * Range (game/range.ts), for the Surveyor's Commission: home, this drive's honest distance from it, the best of
   * anything, each model's best, and the cells set foot in. Null before there is a home.
   */
  range?(): { home: [number, number]; credit: number; all: number; model: Record<string, number>; found: string[] } | null;
}

const kmh = (v: number) => Math.round(v * 12);
/** Seconds a knock-down's done card waits, so the building is seen coming down. */
const DUST_SECS = 2.2;
/** A train tail needs a car this quick (tiles a second, on open ground: tarmac adds a quarter): a modern freight runs at 2.7. */
const TRAIN_TAIL_TOP = 2.4;

export class MissionSystem {
  readonly ms: Missions;
  readonly card: MissionCard;
  readonly journal: Journal;
  readonly tracker: Tracker;
  /** The way back from Show Me: to the journal, or to the vehicle. */
  readonly showBar: ShowMeBar;
  race: Race | null = null;
  tow: TowJob | null = null;
  /** A night op under way (or waiting for the player to arrive after dark), and its mission. */
  op: Op | null = null;
  /** A tail under way (or waiting for the player at its start), and its mission. */
  tail: TailRun | null = null;
  private tailFor: Mission | null = null;
  private tailEnded: { m: Mission; ok: boolean; made: boolean; score: number; line: string } | null = null;
  /** A race, a night op or a tow is under way: Enter is theirs (to start it), not the chat's. */
  get holdsEnter(): boolean { return !!(this.race || this.op || this.tow); }
  private opFor: Mission | null = null;
  /** The mission the race or tow belongs to. */
  private runFor: Mission | null = null;
  /** Controls held still for a race's countdown. */
  held = false;
  /** Enter this frame, read once and shared by the race and the tow. */
  private enter = false;
  private ended: { m: Mission; won?: boolean; margin?: number; ok?: boolean } | null = null;
  private opEnded: { m: Mission; ok: boolean; score: number; line: string } | null = null;

  constructor(private d: MissionDeps) {
    const self = this;
    const host: MissionHost = {
      hours: () => d.hours(),
      ctx: () => self.ctx(),
      // `sounded`: a submarine down on the bottom (game/boat.ts onBottom), for a dived arrival (docs/underwater.html)
      // `agl`: a plane's height over the ground under it, for a crop duster's low pass (game/air.ts aboveGround)
      player: () => { const p = d.player(); return p ? { x: p.w.ox + p.state.x, z: p.w.oz + p.state.z, v: p.state.v, sounded: (p.state as { onBottom?: boolean }).onBottom === true, agl: (p.state as { aboveGround?: number }).aboveGround } : null; },
      spawn: (m, o, also) => self.spawn(m, o, also),
      release: (it) => d.cargo.unchain(it),
      grant: (m, r) => self.grant(m, r),
      arm: (m, o) => self.arm(m, o),
      disarm: (m) => self.disarm(m),
      crewReady: () => !!self.tow && self.tow.ready(),
      whyNot: (m) => self.whyNot(m),
      couldDo: (m) => self.couldDo(m),
      rushUp: () => !!d.rushDoor?.(),
      activeCap: () => activeCap(d.played(), !!d.fleet.hq, d.fleet.units.filter((u) => u.driver && ON_ROAD.has(u.where)).length,
        !!self.ms && self.ms.learning()),
      hqSlots: () => d.fleet.slots,
      // out working: a follower (the helping hand, until she is put to Work) is not out earning
      driversOut: () => d.fleet.units.filter((u) => u.driver && ON_ROAD.has(u.where) && u.mode !== 'follow').length,
      riding: () => d.player()?.def.id ?? null,
      units: () => d.fleet.units.length,
      fitted: (slot) => fitted(d.fleet.ridden?.parts, slot),
      followers: () => d.formation.followers().filter((u) => d.formation.state(u) === 'formed' || d.formation.state(u) === 'closing').length,
      range: () => {
        const r = d.range?.(), p = d.player();
        return r && p ? { home: r.home, credit: r.credit, found: r.found.length, kind: p.def.kind, model: p.def.id } : null;
      },
      announce: (t, b) => d.announce(t, b),
      offer: (m) => self.card.offer(m),
      completed: (m, gave) => self.completed(m, gave),
      changed: () => self.journal.refresh(),
      // nothing pops over a race or a tow: the start line is often a town square with a mayor on it
      busy: () => self.card.isOpen || self.journal.isOpen || !!self.race || !!self.tow || !!self.op?.running || !!self.tail?.running,
    };
    this.ms = new Missions(host);
    // a convoy's load is set down only with its vehicles in line behind the player
    this.d.cargo.heldBack = (it) => self.ms.heldBack(it);
    // the helping hand joins the fleet the moment her card is accepted, in the car the card showed
    this.ms.onAccept = (m) => {
      if (m.tpl !== 'first:hand') return;
      const colour = m.hero.kind === 'vehicle' ? m.hero.parts?.c : undefined;
      this.d.joinHand?.(m.giver.name, colour ?? 0x3f78c0);
    };
    this.d.cargo.loadWhy = (it, def) => self.ms.loadWhy(it, def.id);
    this.card = new MissionCard({
      far: (m, o) => self.far(m, o),
      whyNot: (m) => self.ms.whyNot(m),
      accept: (m) => self.accept(m),
      reject: (m) => self.ms.reject(m),
      journal: (m) => self.journal.open(m),
      closed: () => {},
      skip: () => self.ms.skipTutorial(),
    });
    this.journal = new Journal(this.ms, {
      meters: () => self.meters(),
      far: (m, o) => self.far(m, o),
      whyNot: (m) => self.ms.whyNot(m),
      accept: (m) => self.accept(m),
      reject: (m) => self.ms.reject(m),
      abandon: (m) => { self.ms.abandon(m); },
      showMe: (m) => {
        const t = self.ms.target(m) ?? m.giver.at;
        d.look(t.x, t.z);
        d.announce(m.title, m.objs[m.step]?.label ?? m.giver.name);
        self.showBar.show(m.title, () => self.journal.open(m), () => d.look());
      },
      wonders: () => self.wonders(),
      townName: (k) => self.townName(k),
      hours: () => d.hours(),
    });
    this.tracker = new Tracker(d.scene, this.ms);
    this.tracker.onMore = () => { if (!this.journal.isOpen) this.journal.toggle(); };
    this.showBar = new ShowMeBar(() => self.open);
    // standing is the carriage ladder (docs/standing.html): read, listed and talked up through the ledger's carriage
    const carriage = d.economy.carriage;
    this.ms.rungOf = (k) => carriage.rungOf(k, YOU);
    this.ms.rungsAll = () => carriage.rungs(YOU);
    this.ms.talkUp = (k, n) => {
      const total = carriage.shares(k).reduce((s, x) => s + x.v, 0);
      carriage.credit(k, YOU, Math.max(TALK_UP_MIN, total * TALK_UP * n));
      return carriage.rungOf(k, YOU);
    };
    // the Passport's stamps are the travel objectives' events
    this.ms.passport.onStamp = (kind, key) => {
      if (kind === 'ferry') return;
      this.ms.bus.emit('stamped', { what: kind === 'town' ? 'town' : kind, key, name: key });
    };
    // a long story's step with nowhere in reach: counted a day at a time, passed over after five
    const misses = new Map<string, Set<number>>();
    this.ms.storyMissed = (arc, tpl, i, day) => {
      if (lastMiss !== 'none') return false;
      const days = misses.get(tpl) ?? new Set<number>();
      days.add(day);
      misses.set(tpl, days);
      if (days.size < 5) return false;
      misses.delete(tpl);
      story.skipped(arc as Chain, i, d.hours());
      return true;
    };
    this.ms.raceTarget = () => (this.race && this.race.phase !== 'waiting' ? { x: this.race.to.x, z: this.race.to.z, name: this.race.to.name } : null);
    this.ms.opTarget = (m) => (this.op && this.opFor === m ? this.op.target() : null);
    this.ms.opLine = (m) => (this.op && this.opFor === m ? this.op.line() : null);
    this.ms.tailTarget = (m) => (this.tail && this.tailFor === m ? this.tail.target() : null);
    this.ms.tailLine = (m) => (this.tail && this.tailFor === m ? this.tail.line() : null);
    this.ms.towTarget = () => (this.tow ? (this.tow.hitched ? { x: this.tow.to.x, z: this.tow.to.z, name: this.tow.to.name } : { ...this.tow.where(), name: 'the load' }) : null);
    this.ms.ferryTarget = (m) => {
      const p = d.player(), at = d.place();
      if (!p || !at) return null;
      // the slip whose crossing lands nearest the step after it, or the nearest slip when there is none
      const next = m.objs.find((o) => o.t === 'reach');
      const goal = next && next.t === 'reach' ? next.at : at;
      let best: { x: number; z: number; name: string } | null = null, bestD = Infinity;
      for (const f of d.ferries()) {
        const far = Math.hypot(f.to.w.ox + f.to.port.x - goal.x, f.to.w.oz + f.to.port.z - goal.z);
        if (far < bestD) { bestD = far; best = { x: p.w.ox + f.from.x + 0.5, z: p.w.oz + f.from.z + 0.5, name: f.from.name }; }
      }
      return best;
    };
    d.fleet.onFit = (u, slot, tier) => { if (u === d.fleet.ridden) this.ms.bus.emit('fitted', { slot, tier }); };
  }

  /**
   * An entrance ring at every door a running mission waits on; Space in one goes in (`Missions.enter`). And a
   * diamond at every offer's giver (`isPosted`): Space there opens its card.
   */
  private syncDoors(): void {
    const doors: Door[] = [];
    if (!this.ms.slotsFull() && !this.ms.learning()) {
      for (const m of this.ms.onMap()) {
        if (!isPosted(m) || !this.couldDo(m)) continue;
        const at = m.giver.at;
        const w = this.d.worldAt(at.cell[0], at.cell[1]);
        if (!w) continue;
        doors.push({ key: `o${m.id}`, x: at.x, z: at.z, y: heightAt(w, at.x - w.ox, at.z - w.oz), name: m.title, icon: OFFER_ICON[m.kind] ?? '◆', look: 'mission' });
      }
    }
    const rush = this.ms.learning() ? null : this.d.rushDoor?.();
    if (rush) doors.push(rush);
    for (const m of this.ms.active) {
      const o = m.objs[m.step];
      if (!o || o.t !== 'reach' || !o.door) continue;
      const w = this.d.worldAt(o.at.cell[0], o.at.cell[1]);
      if (!w) continue;
      doors.push({ key: `m${m.id}`, x: o.at.x, z: o.at.z, y: heightAt(w, o.at.x - w.ox, o.at.z - w.oz), name: o.at.name, icon: o.icon });
    }
    this.d.cargo.setDoors(doors);
    this.d.cargo.onDoor ??= (key) => {
      if (key.startsWith('m')) this.ms.enter(Number(key.slice(1)));
      else if (key.startsWith('o')) {
        // an offer's diamond: its card, as if it had come up
        const m = this.ms.byId(Number(key.slice(1)));
        if (m && m.state === 'offered' && !(this.ms.learning() && !isIntro(m.tpl))) { m.shown = true; this.card.offer(m); }
      }
    };
  }

  /** Stranded craft drawn at rescues' pickups, by mission id: gone once the rider is aboard or the mission ends. */
  private props = new Map<number, { mesh: VehicleMesh; it: CargoItem }>();
  private syncProps(t: number): void {
    for (const [id, pr] of this.props) {
      const m = this.ms.byId(id);
      const aboard = this.d.cargo.hold.includes(pr.it);
      if (!m || m.state !== 'active' || aboard) {
        pr.mesh.holder.removeFromParent();
        disposeVehicleMesh(pr.mesh);
        this.props.delete(id);
        continue;
      }
      // it rocks on the swell
      pr.mesh.holder.rotation.z = Math.sin(t * 1.3 + id) * 0.08;
      pr.mesh.holder.rotation.x = Math.sin(t * 0.9 + id * 2) * 0.05;
    }
  }

  /** Whether a card or the journal is up: the game waits. */
  get open(): boolean { return this.card.isOpen || this.journal.isOpen; }

  // ---- the context a template reads ------------------------------------------------------------

  private ctx(): MissionCtx | null {
    const d = this.d;
    const p = d.player(), at = d.place();
    if (!p || !at) return null;
    const home = p.w;
    const worlds = [home, ...d.resident().filter((w) => w !== home)];
    const ridden = d.fleet.ridden;
    const units = d.fleet.units.map((u) => {
      const def = d.fleet.defFor(u);
      // crewed: a driver in it, out in the world to follow the player or work (not in the garage)
      return { uid: u.uid, model: u.model, name: u.name, crew: !!u.driver && u.where !== 'ridden' && u.where !== 'garaged', land: def.kind === 'land', pull: def.kind === 'land' ? pullOf(def as never) : 0 };
    });
    const parts = ridden?.parts ? slotsFor(defOf(ridden.model)).filter((s) => s.id !== 'paint' && fitted(ridden.parts, s.id) > 0).length : 0;
    return {
      seed: d.seed(),
      hours: d.hours(),
      stage: stageOf(d.progress()),
      worlds, home, at, def: p.def,
      units,
      pull: p.def.kind === 'land' ? pullOf(p.def as never) : 0,
      parts,
      drivers: d.fleet.drivers.length,
      buildings: d.estate.deeds.size,
      standing: (k) => this.ms.standingOf(k),
      owns: (w, uid) => { const b = w.allBuildings[uid]; return !!b && !!d.estate.owns(w, b); },
      held: (w, b) => d.held?.(w, b) ?? null,
      passport: this.ms.passport,
      sites: (kinds) => d.cargo.sitesOfKinds(kinds as never),
      ferries: d.ferries(),
      beaten: this.ms.beaten,
      done: this.ms.done,
      top: p.def.topSpeed,
      free: d.cargo.capacityFor(p.def) - d.cargo.used(),
      cash: d.wallet.cash,
      depots: d.depots?.(),
      stashes: d.stashes?.(),
      hqSlots: d.fleet.slots,
      livery: d.fleet.brand ? [d.fleet.brand.primary, d.fleet.brand.accent] : [],
      range: d.range?.() ?? undefined,
      airports: d.cargo.farAirports?.() ?? undefined,
    };
  }

  // ---- the frame -------------------------------------------------------------------------------

  /**
   * One frame. `enter` is whether Enter went down (read once in main.ts); `playing` is false while a
   * menu, the builder or the title is up.
   */
  update(dt: number, menuOpen: boolean, playing: boolean, enter: boolean): void {
    this.enter = enter && playing;
    if (!menuOpen) this.ms.update(dt);
    const paused = menuOpen || !playing;
    if (this.race) {
      this.race.update(dt, paused);
      this.race.label(this.d.camera());
      const r = this.race.over;
      if (r && this.runFor) { this.ended = { m: this.runFor, won: r.won, margin: r.margin }; }
    }
    if (this.tow) {
      this.tow.update(dt, paused);
      if (this.runFor && this.runFor.objs[this.runFor.step]?.t === 'crew' && this.tow.ready()) this.tow.armTow();
      const r = this.tow.over;
      if (r && this.runFor) this.ended = { m: this.runFor, ok: r.ok };
    }
    if (this.op) {
      this.op.update(dt, paused);
      this.op.label(this.d.camera());
      const r = this.op.result;
      if (r && this.opFor) this.opEnded = { m: this.opFor, ...r };
    }
    if (this.tail) {
      this.tail.update(dt, paused);
      this.tail.label(this.d.camera());
      const r = this.tail.result;
      if (r && this.tailFor && !this.tailEnded) this.tailEnded = { m: this.tailFor, ...r };
    }
    if (this.tailEnded) {
      const e = this.tailEnded;
      this.tailEnded = null;
      this.ms.bus.emit('tailEnd', { id: e.m.id, ok: e.ok, made: e.made, score: e.score, line: e.line });
    }
    if (this.opEnded) {
      const e = this.opEnded;
      this.opEnded = null;
      this.ms.bus.emit('opEnd', { id: e.m.id, ok: e.ok, score: e.score, line: e.line });
    }
    // a race or a tow that has ended tells its mission, outside its own update
    if (this.ended) {
      const e = this.ended;
      this.ended = null;
      if (e.won !== undefined) this.ms.bus.emit('raceEnd', { id: e.m.id, won: e.won, margin: e.margin ?? 0 });
      if (e.ok !== undefined) this.ms.bus.emit('towEnd', { id: e.m.id, ok: e.ok, snaps: this.tow?.sim.snaps ?? 0, scrapes: this.tow?.sim.scrapes ?? 0 });
    }
    if (this.doneLater && !paused && (this.doneLater.t -= dt) <= 0) {
      const l = this.doneLater;
      this.doneLater = null;
      this.card.done(l.m, l.gave);
    }
    this.checkRams();
    this.settleStandIns(dt);
    this.syncDash(paused);
    this.syncDoors();
    this.syncProps(performance.now() / 1000);
    const p = this.d.player();
    const me = p ? { x: p.w.ox + p.state.x, y: p.state.y, z: p.w.oz + p.state.z } : null;
    this.tracker.update(dt, this.d.camera(), me, (cx, cz) => this.d.worldAt(cx, cz), this.open || menuOpen);
    this.showBar.update(this.open || !playing);
    this.journal.refresh();
  }

  /** How fast the game clock runs: slowed while a night op runs, so the night lasts the job. */
  clockScale(): number { return this.op?.running ? OP_CLOCK : 1; }

  // ---- the knack jobs (missions/workTemplates.ts) ----------------------------------------------

  /** A dash's clock: a strip low on the left, and the last ten seconds big in the middle. */
  private dashStrip: HTMLDivElement | null = null;
  private dashBig: HTMLDivElement | null = null;
  private dashHtml = '';
  private dashLast = -1;
  private syncDash(hide: boolean): void {
    if (typeof document === 'undefined') return;
    const dash = this.ms.active.find((q) => this.ms.clockOf(q) !== null);
    // failing a dash, a delivery's medal clock with its load aboard (missions/medals.ts): the next medal's time counts down
    const medal = dash ? null : this.ms.active.find((q) => q.objs[q.step]?.t === 'deliver' && this.ms.medalOf(q)?.next && this.ms.aboard(q));
    const m = dash ?? medal;
    const next = medal ? this.ms.medalOf(medal)!.next! : null;
    const left = dash ? this.ms.clockOf(dash) : next ? next.left : null;
    const o = m?.objs[m.step];
    if (!this.dashStrip || !this.dashBig) {
      this.dashStrip = document.createElement('div');
      this.dashStrip.className = 'race-strip hud chip';
      this.dashBig = document.createElement('div');
      this.dashBig.className = 'race-count';
      this.dashStrip.hidden = this.dashBig.hidden = true;
      document.body.append(this.dashStrip, this.dashBig);
    }
    const strip = this.dashStrip, big = this.dashBig;
    if (!m || left === null || hide || o?.t !== 'deliver') { strip.hidden = big.hidden = true; this.dashLast = -1; return; }
    const p = this.d.player();
    const far = p ? Math.round(Math.hypot(o.to.x - (p.w.ox + p.state.x), o.to.z - (p.w.oz + p.state.z))) : 0;
    const where = `${far} t to the ${esc(o.to.name.replace(/^the /, '').toLowerCase())}`;
    const html = next
      ? `${MEDAL_ICON[next.medal]} ${where} · ${MEDAL_NAME[next.medal].toLowerCase()} in<span class="clock${left < 10 ? ' hot' : ''}">${clockText(left)}</span>`
      : `🚑 ${where}${m.notes?.siren ? ' · <b class="ahead">siren on</b>' : ' · K for the siren'}<span class="clock${left < 10 ? ' hot' : ''}">${clockText(left)}</span>`;
    if (html !== this.dashHtml) { this.dashHtml = html; strip.innerHTML = html; }
    strip.hidden = false;
    // a medal clock is only the quiet strip in the corner (the user, 29 Oct 2026); a dash's last ten seconds
    // count down big in the middle, a beep each
    strip.classList.toggle('quiet', !!next);
    if (next) { big.hidden = true; this.dashLast = -1; return; }
    const n = Math.ceil(left);
    if (left <= 10 && n !== this.dashLast) {
      this.dashLast = n;
      big.textContent = String(n);
      big.classList.remove('pop'); void big.offsetWidth; big.classList.add('pop');
      this.d.beep(false);
    }
    big.hidden = left > 10 || left - Math.floor(left) < 0.35;
  }

  /** A dash's clock is running (the patient is aboard): K is the siren's. */
  get dashing(): boolean { return this.ms.active.some((m) => this.ms.clockOf(m) !== null); }
  /** The siren was sounded: the dash pays the more for it. */
  siren(): void { if (this.ms.siren()) this.journal.refresh(); }

  /**
   * The player drove into something on island `w` at (px, pz), its tiles, at `kmh` into its face: a knock-down
   * aimed at a building there is done, and the building is handed back for the host to bring down. Too gentle,
   * or in the wrong vehicle, they are told so.
   */
  rammed(w: World, px: number, pz: number, kmh: number): Building | null {
    const model = this.d.player()?.def.id ?? '';
    for (const m of this.ms.active) {
      const o = m.objs[m.step];
      if (!o || o.t !== 'ram' || o.b.cell[0] !== w.cx || o.b.cell[1] !== w.cz) continue;
      const b = w.allBuildings[o.b.uid];
      if (!b || b.gone) continue;
      // touching it: the vehicle's middle stops on the wall, inside or right beside the footprint
      const dx = Math.max(b.x - px, 0, px - (b.x + b.w)), dz = Math.max(b.z - pz, 0, pz - (b.z + b.d));
      if (Math.hypot(dx, dz) > 0.9) continue;
      const r = this.ms.rammed(o.b.cell, o.b.uid, kmh, model, this.d.held?.(w, b) ?? null);
      if (r === 'down') return b;
      if (r === 'slow') this.d.float(`${speedText(kmh)} · hit it at ${speedText(o.kmh)}+`, 'info');
      else if (r === 'ride') this.d.float(`It takes ${o.ride.label}`, 'info');
      return null;
    }
    return null;
  }

  /**
   * An act's ride aboard bound for a stand-in (missions/wire.ts spawn: its county was not traded in when the load was
   * picked up): pointed at the real stand, station or gates as soon as the cargo system has it.
   */
  private settleT = 0;
  private settleStandIns(dt: number): void {
    if ((this.settleT -= dt) > 0) return;
    this.settleT = 1;
    for (const m of this.ms.active) {
      const o = m.objs[m.step];
      if (!m.tpl.startsWith('act:') || !o || o.t !== 'deliver') continue;
      const it = this.d.cargo.hold.find((q) => q.chain === m.id);
      if (!it || it.to.id >= 0) continue;
      let best: Site | null = null, bestD = 2.5;
      for (const s of this.d.cargo.sitesOfKinds([o.to.kind as never])) {
        const q = Math.hypot(s.x - o.to.x, s.z - o.to.z);
        if (q < bestD) { bestD = q; best = s; }
      }
      // a far airport stood in at its runway's middle: its stand is some way along the apron
      if (!best && o.to.kind === 'intl') {
        for (const s of this.d.cargo.sitesOfKinds(['intl' as never])) {
          const q = Math.hypot(s.x - o.to.x, s.z - o.to.z);
          if (q < 60 && q < (best ? Math.hypot(best.x - o.to.x, best.z - o.to.z) : Infinity)) best = s;
        }
      }
      if (best) it.to = best;
    }
  }

  /** A knock-down whose building has gone some other way, or been bought, while it was under way: it is called off. */
  private checkRams(): void {
    for (const m of this.ms.active) {
      const o = m.objs[m.step];
      if (!o || o.t !== 'ram') continue;
      const w = this.d.worldAt(o.b.cell[0], o.b.cell[1]);
      const b = w?.allBuildings[o.b.uid];
      if (!w || !b) continue;
      const why = b.gone ? 'Somebody has cleared it already' : this.d.held?.(w, b) ?? null;
      if (why) this.ms.rammed(o.b.cell, o.b.uid, 0, '', why);
    }
  }

  /** The J key. */
  toggleJournal(): void { this.journal.toggle(); }

  /** The Enter key, for the race and the tow. */
  go(): boolean { const e = this.enter; this.enter = false; return e; }

  // ---- what the game tells the missions --------------------------------------------------------

  delivered(it: CargoItem): void { this.ms.bus.emit('delivered', { it }); }
  /** Road tiles laid, a vehicle unlocked, a building asked of a town: for a 'make' step (game/coach.ts). */
  made(what: MakeKind, n: number, at?: { x: number; z: number; cell: [number, number] }): void { this.ms.bus.emit('made', { what, n, at }); }

  /** The player was airlifted to their HQ: a medal clock running now can win nothing. */
  airlifted(): void { this.ms.airlifted(); }

  ferried(from: string, to: string): void {
    this.ms.passport.stamp('ferry', [from, to].sort().join('|'));
    this.ms.bus.emit('ferried', { from, to });
  }

  /** Into a town: its stamp, its style's, and its standing on the arrival card. */
  arrivedTown(w: World, t: Town): string {
    this.ms.passport.stamp('town', `${w.cx},${w.cz}#${t.id}`);
    this.ms.passport.stamp('arch', t.style);
    const s = this.ms.standingOf(`${w.cx},${w.cz}#${t.id}`);
    return s > 0 ? STANDING[s] : '';
  }

  wonder(kind: string): void { this.ms.passport.stamp('wonder', kind); }
  /** The circuits (game/circuits.ts): whether a Race Day waits on this one, a clean lap there, where the player finished a race. */
  circuitEntered(key: string): boolean { return this.ms.circuitEntry(key); }
  circuitLap(key: string, secs: number): void { this.ms.bus.emit('circuitLap', { key, secs }); }
  circuitResult(key: string, place: number, of: number): void { this.ms.bus.emit('circuitRace', { key, place, of }); }
  biome(region: string): void { this.ms.passport.stamp('biome', region); }
  bought(model: string): void { this.ms.bus.emit('bought', { what: 'vehicle', id: model }); }

  /** A ferry from a town where the player is a Regular or better costs less. */
  fareMul(w: World, p: Port): number {
    return p.town >= 0 && this.ms.standingOf(`${w.cx},${w.cz}#${p.town}`) >= RUNG.regular ? 0.9 : 1;
  }

  // ---- accepting, arming, ending ---------------------------------------------------------------

  private accept(m: Mission): void {
    const why = this.ms.accept(m);
    if (why) { this.d.announce(m.title, why); return; }
    const o = m.objs[0];
    this.d.announce(m.title, o ? `${o.label}${this.ms.nextLine(m) ? ` · ${this.ms.nextLine(m)}` : ''}` : 'Under way');
  }

  /**
   * Can the vehicle being driven (as fitted) do this: carry its loads, race or tow on the road, keep up with
   * the rival? Judged on the one being driven, not the fleet: an offer the player can't do in what they're in
   * isn't posted, and its diamond comes back when they drive something that can (syncDoors runs every
   * frame). Only a step that asks to arrive in a given model looks at the whole fleet, as they can go and get
   * it. With nothing driven, the fleet as a whole.
   */
  private couldDo(m: Mission): boolean {
    const fleet = this.d.fleet;
    const now = this.d.player()?.def;
    const defs = now ? [now] : fleet.units.map((u) => fleet.defFor(u));
    if (!defs.length) return true;
    const land = defs.filter((d) => d.kind === 'land');
    for (const o of m.objs) {
      if (o.t === 'deliver') {
        const type = cargoById(o.cargo);
        // a pickup at sea (a rescue) needs something that floats
        const can = (d: VehicleDef) => d.holds.includes(type!.cls) && d.capacity >= type!.units && (o.from.kind !== 'adrift' || d.kind === 'water');
        // a convoy's load is carried by the whole line, its holds pooled (missions/convoyTemplates.ts)
        if (type && o.with && now) { if (!this.lineHolds(now, o.with, type)) return false; }
        else if (type && !defs.some(can)) return false;
        if (o.ride && !(now ? o.ride.ids.includes(now.id) : fleet.units.some((u) => o.ride!.ids.includes(u.model)))) return false;
      } else if (o.t === 'ram') {
        // like an arrival in a model: the Dozer can be gone and got
        if (!fleet.units.some((u) => o.ride.ids.includes(u.model)) && !(now && o.ride.ids.includes(now.id))) return false;
      } else if (o.t === 'reach' && o.ride) {
        const ids = o.ride.ids;
        if (!fleet.units.some((u) => ids.includes(u.model)) && !(now && ids.includes(now.id))) return false;
      } else if ((o.t === 'lap' || o.t === 'grid' || o.t === 'tow') && !land.length) return false;
      else if (o.t === 'range' && (o.kind || o.model)) {
        // like an arrival in a model: some vehicle of the fleet's must be of that kind, the one driven or not
        const fits = (q: VehicleDef) => (!o.kind || q.kind === o.kind) && (!o.model || q.id === o.model);
        if (!fleet.units.some((u) => fits(fleet.defFor(u))) && !(now && fits(now))) return false;
      }
      else if (o.t === 'race') {
        const r = rivalById(o.rival);
        const theirs = applyParts(defOf(rivalModel(r, o.tier)), rivalParts(r, o.tier));
        if (!land.some((d) => theirs.topSpeed <= d.topSpeed * 1.22)) return false;
      }
    }
    if (m.kind === 'op' && !defs.some((d) => isHelicopter(d))) return false;
    // a story step bound in its helicopter or boat form waits for one (0.7.0)
    if (m.form === 'heli' && !defs.some((d) => isHelicopter(d))) return false;
    if (m.form === 'boat' && !defs.some((d) => d.kind === 'water')) return false;
    if (m.form === 'sub' && !defs.some((d) => d.kind === 'water' && !!d.dive)) return false;
    // a story step out on the roads waits for a road vehicle (a meeting can be come to in anything)
    if (!m.form && m.arc && STEP_INFO.has(m.tpl) && now && now.kind !== 'land' && m.objs.some((o) => o.t === 'deliver' || o.t === 'race' || o.t === 'tow' || o.t === 'tail')) return false;
    // a tail is driven: a road car, and one quick enough to keep up with a freight on the line beside it
    for (const o of m.objs) if (o.t === 'tail' && !land.some((d) => !o.train || d.topSpeed >= TRAIN_TAIL_TOP)) return false;
    return true;
  }

  /** A convoy's line: the vehicle driven and the `n` biggest crewed road vehicles out, whose holds it pools. */
  private lineOf(now: VehicleDef, n: number): VehicleDef[] {
    const fleet = this.d.fleet;
    const out = fleet.units.filter((u) => u.driver && u.where !== 'ridden' && u.where !== 'garaged').map((u) => fleet.defFor(u)).filter((d) => d.kind === 'land');
    return [now, ...out.sort((a, b) => b.capacity - a.capacity).slice(0, n)];
  }
  /** Could that line carry a load of this type between them? */
  private lineHolds(now: VehicleDef, n: number, type: { units: number; cls: VehicleDef['holds'][number] }): boolean {
    const line = this.lineOf(now, n);
    return line.reduce((s, d) => s + d.capacity, 0) >= type.units && line.some((d) => d.holds.includes(type.cls));
  }

  private whyNot(m: Mission): string | null {
    const c = this.ctx();
    if (!c) return null;
    const race = m.objs.find((o) => o.t === 'race');
    if (race && race.t === 'race') {
      const r = rivalById(race.rival);
      const theirs = applyParts(defOf(rivalModel(r, race.tier)), rivalParts(r, race.tier));
      if (theirs.topSpeed > c.def.topSpeed * 1.22) return `Needs ${speedText(kmh(theirs.topSpeed / 1.22))} top speed · yours is ${speedText(kmh(c.def.topSpeed))}`;
    }
    const o = m.objs.find((q) => q.t === 'deliver');
    if (o && o.t === 'deliver') {
      const type = cargoById(o.cargo);
      if (type && o.with) {
        const line = this.lineOf(c.def, o.with), room = line.reduce((s, d) => s + d.capacity, 0);
        if (!line.some((d) => d.holds.includes(type.cls))) return `Nobody in the line can carry ${type.name.toLowerCase()}`;
        if (type.units > room) return `Needs ${type.units} units of hold in the line · yours has ${room}`;
      } else {
        if (type && !c.def.holds.includes(type.cls)) return `Your ${c.def.name} can’t carry ${type.name.toLowerCase()}`;
        if (type && type.units > c.def.capacity) return `Needs a hold of ${type.units} · yours is ${c.def.capacity}`;
      }
    }
    if (m.kind === 'race' || m.kind === 'tow') {
      if (this.race || this.tow) return 'Finish the race or tow under way first';
    }
    if (m.kind === 'op' && this.op) return 'Finish the night op under way first';
    if (m.kind === 'tail' && this.tail) return 'Finish the tail under way first';
    const tl = m.objs.find((q) => q.t === 'tail');
    if (tl && tl.t === 'tail' && tl.train && c.def.topSpeed < TRAIN_TAIL_TOP) return `Needs ${speedText(kmh(TRAIN_TAIL_TOP))} top speed to keep up with a train`;
    return null;
  }

  private arm(m: Mission, o: Obj): void {
    const d = this.d;
    if (o.t === 'tail') {
      if (this.tail) return;
      this.tailFor = m;
      this.tail = new TailRun(m.id, {
        worldAt: (cx, cz) => d.worldAt(cx, cz),
        player: () => d.player(),
        trafficOf: (w) => d.trafficOf?.(w) ?? null,
        trains: () => d.trains?.() ?? null,
        dark: () => d.gloom?.() ?? (d.dark() ? 1 : 0),
        say: (t, b) => d.announce(t, b),
        beep: (f) => d.beep(f),
      }, d.scene, o);
      return;
    }
    if (o.t === 'op') {
      if (this.op) return;
      this.opFor = m;
      this.op = makeOp(m.id, {
        worldAt: (cx, cz) => d.worldAt(cx, cz),
        player: () => d.player(),
        spot: () => d.spot(),
        dark: () => d.dark(),
        go: () => this.go(),
        say: (t, b) => d.announce(t, b),
        beep: (f) => d.beep(f),
        traffic: (w) => d.traffic(w),
      }, d.scene, o);
      return;
    }
    if (o.t === 'race') {
      if (this.race) return;
      const r = rivalById(o.rival);
      const def = applyParts(defOf(rivalModel(r, o.tier)), rivalParts(r, o.tier)) as LandDef;
      this.runFor = m;
      this.race = new Race(m.id, {
        worldAt: (cx, cz) => d.worldAt(cx, cz),
        player: () => d.player(),
        hold: (on) => { this.held = on; },
        go: () => this.go(),
        say: (t, b) => d.announce(t, b),
        bump: (s) => d.bump(s),
        traffic: (w) => d.traffic(w),
        beep: (f) => d.beep(f),
        ended: () => {},
      }, d.scene, o.from, o.to, { id: r.id, name: r.name, def });
    } else if (o.t === 'crew' || o.t === 'tow') {
      if (this.tow) { if (o.t === 'tow') this.tow.armTow(); return; }
      const t = m.objs.find((q) => q.t === 'tow');
      if (!t || t.t !== 'tow') return;
      this.runFor = m;
      this.tow = new TowJob(m.id, {
        worldAt: (cx, cz) => d.worldAt(cx, cz),
        player: () => d.player(),
        go: () => this.go(),
        say: (a, b) => d.announce(a, b),
        crew: (n, x, z) => d.fleet.units
          .filter((u) => u.driver && u.where !== 'ridden' && d.fleet.defFor(u).kind === 'land')
          .sort((a, b) => dist(a, x, z) - dist(b, x, z)).slice(0, n),
        defFor: (u) => d.fleet.defFor(u),
        follow: (u, on) => d.formation.setMode(on ? 'follow' : 'work', u),
        harness: (fn) => { d.formation.harness = fn; },
        crack: () => d.crack(),
        // kept on the mission, so a helper left on Follow over a reload still goes back to Work after
        wasFollow: (uid) => { const v = m.notes?.[`towWas${uid}`]; return v === undefined ? undefined : v === 1; },
        called: (uid, was) => { (m.notes ??= {})[`towWas${uid}`] = was ? 1 : 0; },
      }, d.scene, t.load, t.from, t.to, t.min);
      if (o.t === 'tow') this.tow.armTow();
    }
  }

  private disarm(m: Mission): void {
    if (this.tailFor === m) {
      this.tail?.dispose();
      this.tail = null;
      this.tailFor = null;
    }
    if (this.opFor === m) {
      this.op?.dispose();
      this.op = null;
      this.opFor = null;
    }
    if (this.runFor !== m) return;
    // a race given up part way counts as a loss; the mission has already been told
    this.race?.dispose();
    this.tow?.dispose();
    this.race = null;
    this.tow = null;
    this.runFor = null;
    this.held = false;
  }

  /** Told of every mission done, before its card: a line it returns is added to what the mission gave (the factions). */
  onFinished: ((m: Mission) => string | null) | null = null;

  private completed(m: Mission, gave: string[]): void {
    const fac = this.onFinished?.(m);
    if (fac) gave.push(fac);
    // a story chain's step (docs/storychains.html): its line, its morning news and its mark on the world
    const info = STEP_INFO.get(m.tpl);
    if (info) story.finished(info.chain, info.i, this.d.hours(), info.so, info.beat, info.i === CHAIN_LEN - 1);
    // a story chain's last chapter, and a night op done, for their toppers (game/toppers.ts phase 4)
    if (info && info.i === CHAIN_LEN - 1) deeds.mark('tales', info.chain);
    if (m.objs.some((o) => o.t === 'op')) deeds.mark('nightOps', m.tpl);
    // a tail followed to the end, and one never made (game/tail)
    if (m.kind === 'tail') { deeds.add('tails'); if (!m.notes?.made) deeds.add('ghostTails'); }
    // the convoys led home (missions/convoyTemplates.ts)
    if (m.tpl.startsWith('convoy:')) deeds.mark('convoys', m.tpl);
    // a knack job done, for its topper (game/toppers.ts)
    { const k = knackOf(m.tpl); if (k) deeds.add(knackStat(k)); }
    // a delivery inside a medal time (missions/medals.ts)
    if (m.notes?.medal) { deeds.add('medals'); if (m.notes.medal === 3) deeds.add('golds'); }
    // the old requests' deeds still count a town's errand
    if (m.thread === 'town' && m.giver.town) {
      deeds.add('chains');
      deeds.mark('helped', `${m.giver.town.cell[0]},${m.giver.town.cell[1]}#${m.giver.town.id}`);
    }
    // the first drive's missions end how its guide says: the ones that fit a part end in the workshop, on that part
    if (isIntro(m.tpl) && this.firstDone && this.firstDone(m, gave)) return;
    // a knock-down's card waits for the dust: the building coming down is the ending
    if (m.objs.some((o) => o.t === 'ram')) { this.doneLater = { m, gave, t: DUST_SECS }; return; }
    this.card.done(m, gave);
  }

  /** A done card held back a moment (a knock-down's, while the dust flies), and the seconds left. */
  private doneLater: { m: Mission; gave: string[]; t: number } | null = null;

  /** The first-drive tutorial's say in how one of its missions ends: true when it has shown the ending itself. */
  firstDone: ((m: Mission, gave: string[]) => boolean) | null = null;

  /**
   * How loudly the world's other work should show: 'only' hides everything but mission goods (the first
   * drive), 'dim' fades it (a mission under way), 'all' shows it as it is.
   */
  focus(): 'all' | 'dim' | 'only' {
    if (this.ms.hold) return 'only';
    return this.ms.active.length ? 'dim' : 'all';
  }

  // ---- goods and rewards -----------------------------------------------------------------------

  /** A delivery objective's goods, found again at the sites the mission was bound to, held for it. */
  private spawn(m: Mission, o: Extract<Obj, { t: 'deliver' }>, also?: { cargo: string; value: number }): CargoItem | null {
    const type = cargoById(also ? also.cargo : o.cargo);
    const value = also ? also.value : o.value;
    if (!type) return null;
    // already aboard (a saved game picked up part way): that load is this step's, not a new one
    const door = o.door ? { name: o.to.name, icon: o.icon } : undefined;
    const aboard = this.d.cargo.hold.find((it) => it.chain === m.id && it.type === type);
    if (aboard) { aboard.door = door; return aboard; }
    const find = (ref: { x: number; z: number; kind: string }): Site | null => {
      let best: Site | null = null, bestD = 2.5;
      for (const s of this.d.cargo.sitesOfKinds([ref.kind as never])) {
        const q = Math.hypot(s.x - ref.x, s.z - ref.z);
        if (q < bestD) { bestD = q; best = s; }
      }
      return best;
    };
    // goods left on the roadside (the first job's): a spot on the road rather than a site
    const roadside = (ref: { x: number; z: number; cell: [number, number] }): Site | null => {
      const w = this.d.worldAt(ref.cell[0], ref.cell[1]);
      if (!w) return null;
      const lx = ref.x - w.ox, lz = ref.z - w.oz;
      return { id: -1, kind: 'roadside' as never, name: 'the roadside', w, lx, lz, x: ref.x, z: ref.z, y: heightAt(w, lx, lz), port: -1, major: false };
    };
    // someone adrift (a rescue): a spot on the water, at its surface
    const adrift = (ref: { x: number; z: number; cell: [number, number] }): Site | null => {
      const s = roadside(ref);
      if (!s) return null;
      const i = Math.min(N * N - 1, Math.max(0, Math.floor(s.lz) * N + Math.floor(s.lx)));
      const wl = s.w.water[i];
      return { ...s, kind: 'adrift' as never, name: 'offshore', y: wl >= 0 ? wl : s.y };
    };
    // an act's ride (missions/actTemplates.ts) often ends a county or two off, where goods aren't traded yet, or (a
    // Jumbo's) out of memory: a stand-in at the place, in the frame of the county it starts in when its own is not in,
    // swapped for the real site once that county trades (settleStandIns)
    const standIn = (ref: SiteRef, base: Site | null): Site | null => {
      if (!m.tpl.startsWith('act:')) return null;
      const w = this.d.worldAt(ref.cell[0], ref.cell[1]) ?? base?.w;
      if (!w) return null;
      const lx = ref.x - w.ox, lz = ref.z - w.oz;
      const y = lx >= 0 && lz >= 0 && lx < N && lz < N ? heightAt(w, lx, lz) : base?.y ?? 0;
      return { id: -1, kind: ref.kind as never, name: ref.name, w, lx, lz, x: ref.x, z: ref.z, y, port: -1, major: ref.kind === 'intl' };
    };
    const from = o.from.kind === 'roadside' ? roadside(o.from) : o.from.kind === 'adrift' ? adrift(o.from) : find(o.from) ?? standIn(o.from, null);
    const to = find(o.to) ?? standIn(o.to, from);
    if (!from || !to) return null;
    const it = this.d.cargo.spawnFor(type, from, to, value, m.id, THREAD_COLOUR[m.thread]);
    if (it) it.door = door;
    // the stranded craft, bobbing where its rider waits
    if (it && o.prop && !this.props.has(m.id)) {
      const mesh = buildVehicleMesh(defOf(o.prop));
      mesh.holder.position.set(from.x + 0.6, from.y, from.z + 0.3);
      mesh.holder.rotation.y = (m.seed % 628) / 100;
      this.d.scene.add(mesh.holder);
      this.props.set(m.id, { mesh, it });
    }
    return it;
  }

  /** One reward, through the door the shop uses, less the price. A string when it had to be paid in cash instead. */
  private grant(m: Mission, r: Reward): string | null {
    const d = this.d;
    switch (r.r) {
      case 'cash': {
        // an event's prize: a tenth more with every event stamped (game/passportRewards.ts, the Front-row pass)
        const n = m.tpl.startsWith('event:') ? Math.round(r.n * rewards.eventMul()) : r.n;
        d.wallet.earn(n, 'missions');
        d.cash();
        d.float(`+${money(n)} ${m.title}`, 'cash');
        return null;
      }
      case 'gems':
        if (d.gems) { d.gems(r.n, m.title); return null; }
        d.wallet.earn(r.n * 250, 'missions');
        d.cash();
        return `${money(r.n * 250)} instead of diamonds`;
      case 'part': {
        const units = r.all ? d.fleet.units.filter((u) => defOf(u.model).kind === 'land') : d.fleet.ridden ? [d.fleet.ridden] : [];
        let fitted = 0;
        for (const u of units) if (!d.fleet.grant(u, r.slot, r.tier)) fitted++;
        if (fitted) return null;
        const cash = tierPrice(defOf(d.fleet.ridden?.model ?? 'tomato'), r.slot, r.tier);
        d.wallet.earn(cash, 'missions');
        d.cash();
        return `${money(cash)} instead of a part your vehicle can’t take`;
      }
      case 'livery': {
        const u = d.fleet.ridden;
        if (!u || d.fleet.grant(u, 'paint', Math.max(1, fitted(u.parts, 'paint')), r.colour)) return `${r.name} paint waits for a road car`;
        return null;
      }
      case 'vehicle': {
        const u = d.giveUnit(r.model);
        if (!u) {
          const cash = Math.round(priceOf(r.model) * 0.6);
          d.wallet.earn(cash, 'missions');
          d.cash();
          return `${money(cash)} instead: nowhere to park it`;
        }
        if (r.parts) for (const [slot, t] of Object.entries(r.parts.t)) if (t) d.fleet.grant(u, slot as SlotId, t[1], slot === 'paint' ? r.parts.c : undefined);
        if (r.name) u.name = r.name;
        deeds.mark('models', r.model);
        return `${r.name ?? defOf(r.model).name} is parked beside you`;
      }
      case 'building': {
        const w = d.worldAt(r.at.cell[0], r.at.cell[1]);
        const b = w?.allBuildings[r.at.uid];
        if (!w || !b || b.gone) { d.wallet.earn(1500, 'missions'); d.cash(); return `${money(1500)} instead: the ${r.at.name.toLowerCase()} is gone`; }
        const why = d.estate.grant(w, b);
        return why ? `${r.at.name}: ${why}` : `The ${r.at.name.toLowerCase()} is yours`;
      }
      case 'effect': {
        const w = d.worldAt(r.town.cell[0], r.town.cell[1]);
        const t = w?.towns[r.town.id];
        if (!w || !t) return `${r.town.name} is out of reach`;
        if (r.effect === 'credit') { d.economy.creditChain(w, t, ECONOMY.norm[t.kind] * 24); return null; }
        return d.effect(w, t, r.effect) ? null : `${r.town.name} thanks you`;
      }
      case 'driver': return `${d.fleet.gift(Math.floor(d.hours() / 24))} joins as a driver`;
      // she joined when the card was taken (joinHand): the done card is where she says she is staying
      case 'crew': return `${r.name} stays on as your driver, in her own ${r.model}`;
      case 'clue':
        d.heard?.(r.line, m.giver.name);
        return null;
      case 'reveal': {
        d.heard?.(r.line, m.giver.name);
        return d.reveal?.(r) ?? null;
      }
      case 'standing': return null;
    }
  }

  // ---- what the card and the journal show ------------------------------------------------------

  /** Tiles from the player to where an objective happens. */
  private far(m: Mission, o: Obj): number | null {
    const p = this.d.player();
    if (!p) return null;
    const x = p.w.ox + p.state.x, z = p.w.oz + p.state.z;
    const at = (q: { x: number; z: number } | null) => (q ? Math.hypot(q.x - x, q.z - z) : null);
    switch (o.t) {
      case 'deliver': return at(o.from);
      case 'reach': return o.hidden ? null : at(o.at);
      case 'visit': return at(o.at);
      case 'ram': return at(o.at);
      case 'race': return Math.hypot(o.to.x - o.from.x, o.to.z - o.from.z);
      case 'tow': return Math.hypot(o.to.x - o.from.x, o.to.z - o.from.z);
      case 'crew': { const t = m.objs.find((q) => q.t === 'tow'); return t && t.t === 'tow' ? at(t.from) : null; }
      case 'op': return at(o.at);
      case 'lap': case 'grid': return at(o.at);
      case 'tail': return at(o.at);
      default: return null;
    }
  }

  private meters(): { car: string; fleet: string; hold: string; town: string } {
    const d = this.d;
    const p = d.player();
    const u = d.fleet.ridden;
    const parts = u?.parts ? slotsFor(defOf(u.model)).filter((s) => s.id !== 'paint' && fitted(u.parts, s.id) > 0).length : 0;
    const rate = d.fleet.units.filter((q) => q.driver).reduce((s, q) => s + d.fleet.dayRate(q), 0);
    const known = this.ms.rungsAll().map((r) => r.rung);
    const best = known.length ? Math.max(...known) : 0;
    return {
      car: p ? `${speedText(kmh(p.def.topSpeed))} · ${parts} part${parts === 1 ? '' : 's'}` : '—',
      fleet: `${d.fleet.units.length} · $${Math.round(rate)}/day`,
      hold: `${d.estate.deeds.size} building${d.estate.deeds.size === 1 ? '' : 's'}`,
      town: known.filter((s) => s > 0).length ? `${known.filter((s) => s > 0).length} know you · best ${STANDING[best]}` : 'Stranger everywhere',
    };
  }

  private wonders(): Map<string, string> {
    const out = new Map<string, string>();
    for (const r of Object.values(REGIONS)) out.set(r.wonder.kind, r.wonder.name[0].replace(/^the /, '').replace(/ $/, ''));
    out.set('moatedCastle', 'Moated castle');
    return out;
  }

  private townName(key: string): string {
    const [cell, id] = key.split('#');
    const [cx, cz] = cell.split(',').map(Number);
    const t = this.d.worldAt(cx, cz)?.towns[Number(id)];
    return t ? plainTown(t.name) : key;
  }

  // ---- saving ----------------------------------------------------------------------------------

  toSave(): SavedMissions { return this.ms.toSave(); }

  fromSave(s: SavedMissions | undefined, sameGen: boolean): void {
    this.race?.dispose();
    this.tow?.dispose();
    this.race = null;
    this.tow = null;
    this.runFor = null;
    this.held = false;
    this.op?.dispose();
    this.op = null;
    this.opFor = null;
    this.tail?.dispose();
    this.tail = null;
    this.tailFor = null;
    this.card.close();
    this.journal.close();
    this.ms.fromSave(s, sameGen);
    this.migrateStanding();
  }

  /**
   * A save from before standing was the carriage's (docs/standing.html): each town's mission standing becomes
   * trade on its books, once, enough to put the player at the matching rung (Trusted for Trusted, 35% for a
   * Friend or Freedom town); never less than they already carry. From then on it fades like any other trade.
   */
  private migrateStanding(): void {
    const carriage = this.d.economy.carriage;
    for (const [key, level] of this.ms.legacy) {
      const share = level >= 3 ? RUNGS[RUNG.territory].at : level >= 2 ? RUNGS[RUNG.trusted].at : 0;
      const need = carriage.need(key, YOU, share);
      if (need > 0) carriage.credit(key, YOU, need + 1);
    }
    this.ms.legacy.clear();
  }

  /** Back to the title: nothing running, nothing on screen. */
  stand(): void {
    this.race?.dispose();
    this.tow?.dispose();
    this.race = null;
    this.tow = null;
    this.runFor = null;
    this.held = false;
    this.op?.dispose();
    this.op = null;
    this.opFor = null;
    this.tail?.dispose();
    this.tail = null;
    this.tailFor = null;
    this.card.close();
    this.journal.close();
    this.tracker.hide();
    if (this.showBar.active) { this.showBar.hide(); this.d.look(); }
  }

  // ---- the console -----------------------------------------------------------------------------

  console() {
    const ms = this.ms;
    return {
      system: ms,
      wire: this,
      list: () => { const l = ms.lines(); console.table(l); return l; },
      templates: () => ms.templates(),
      offer: (id: string) => ms.force(id),
      /** The acts' rides wanted now (missions/actTemplates.ts), and what a bus, a train and the Jumbo make of each from here. */
      acts: () => { const c = this.ctx(); return c ? actsReport(c) : []; },
      finish: () => ms.finishNow(),
      step: () => ms.stepNow(),
      fill: () => { ms.fill(); return ms.lines(); },
      /** What the director would offer now, best first, with its score. */
      rank: () => { const c = this.ctx(); return c ? ms.rank(c).map(({ m, s }) => `${s.toFixed(1)} ${m.tpl} · ${m.title}${ms.whyNot(m) ? ` (${ms.whyNot(m)})` : ''}`) : []; },
      /** Real seconds until the next offer may be made; set it to hurry one along. */
      gap: (n?: number) => { if (n !== undefined) ms.gap = n; return Math.round(ms.gap); },
      standing: (key?: string, n?: number) => { if (key && n) ms.talkUp(key, n); return ms.rungsAll().map((r) => `${r.key} ${STANDING[r.rung]}`); },
      journal: () => { this.journal.open(); return 'open'; },
      card: (id: number) => { const m = ms.byId(id); if (m) this.card.offer(m); return m?.title ?? 'no such mission'; },
      take: (id: number) => { const m = ms.byId(id); if (m) this.accept(m); return ms.lines(); },
      passport: () => ms.passport.toSave(),
      race: () => this.race?.snapshot() ?? null,
      tow: () => this.tow?.sim.snapshot() ?? null,
      /** The night op under way: which, whether it has started, its clock and its result. */
      op: () => (this.op ? { op: this.op.o.op, started: this.op.started, t: Math.round(this.op.t), result: this.op.result, target: this.op.target() } : null),
      /** The tail under way: its phase, the meter, where the player stands to its mirror, and how it ended. */
      tail: () => this.tail?.snapshot() ?? null,
    };
  }
}

const dist = (u: Unit, x: number, z: number) => {
  const a = u.agent;
  return a ? Math.hypot(a.w.ox + a.state.x - x, a.w.oz + a.state.z - z) : Math.hypot(u.x - x, u.z - z) + 1e4;
};
void N;
void hashString;
