/**
 * A plant's state as it rides on its deed (docs/supplychains.html): pure data and its saved form, so the deed
 * book (game/estate.ts) can keep it without knowing what a recipe is.
 */

/** One made load waiting at the kerb (or still to be put out there). */
export interface Stock {
  /** Its cargo id, and the steps of the fleet's own making behind it (pedigree). */
  id: string;
  steps: number;
  /** The game hour it was made. */
  at: number;
  /** The load's id once it stands at the kerb; 0 while its island is away. Not saved. */
  load: number;
  /** The game hour it was put out, for opening it to the island. Not saved. */
  out: number;
  /** Opened to the island's haulers: anyone may take it now. */
  open?: boolean;
}

export interface Plant {
  /** Units of each input in the bins: one entry a load, each the pedigree steps that load carries in (0 for none). */
  bins: Record<string, number[]>;
  /** The run in hand: which of the kind's recipes, what it will make, its steps, and the game hours left. */
  run: { r: number; out: string; steps: number; left: number } | null;
  /** A base plant's clock: game hours run toward the next load. */
  clock: number;
  stock: Stock[];
  /** The cargo id its owner has fixed it to make, or '' for any. */
  set: string;
  /** The game hour it last ran to. */
  at: number;
  /** Loads made, loads fed in, maker's fees taken, loads that went stale at the kerb, loads opened to the island. */
  made: number; fed: number; fees: number; missed: number; opened: number;
  /** Maker's fees taken on the game day `feeDay` (not saved: a day's allowance starts again on load). */
  feeDay?: number; feeToday?: number;
}

export const freshPlant = (hours: number): Plant => ({ bins: {}, run: null, clock: 0, stock: [], set: '', at: hours, made: 0, fed: 0, fees: 0, missed: 0, opened: 0 });

/** The saved form: [bins, run | 0, clock, stock [id, steps, at, open?][], set, at, made, fed, fees, missed, opened]. */
export type SavedPlant = [Record<string, number[]>, [number, string, number, number] | 0, number, [string, number, number, 1?][], string, number, number, number, number, number, number];

export function packPlant(p: Plant): SavedPlant {
  const bins: Record<string, number[]> = {};
  for (const [id, l] of Object.entries(p.bins)) if (l.length) bins[id] = l.slice(0, 32);
  return [
    bins, p.run ? [p.run.r, p.run.out, p.run.steps, +p.run.left.toFixed(3)] : 0, +p.clock.toFixed(3),
    p.stock.map((s) => (s.open ? [s.id, s.steps, +s.at.toFixed(2), 1] : [s.id, s.steps, +s.at.toFixed(2)])),
    p.set, +p.at.toFixed(3), p.made, p.fed, Math.round(p.fees), p.missed, p.opened,
  ];
}

const num = (v: unknown, d = 0): number => (typeof v === 'number' && Number.isFinite(v) ? v : d);
const str = (v: unknown): string => (typeof v === 'string' ? v : '');

/** A saved plant back, or null when it makes no sense (an old or broken slot). */
export function unpackPlant(t: unknown): Plant | null {
  if (!Array.isArray(t) || t.length < 6) return null;
  const [b, run, clock, stock, set, at, made, fed, fees, missed, opened] = t as unknown[];
  const bins: Record<string, number[]> = {};
  if (b && typeof b === 'object') for (const [id, l] of Object.entries(b as Record<string, unknown>)) {
    if (Array.isArray(l)) bins[id] = l.filter((n): n is number => typeof n === 'number' && Number.isFinite(n)).slice(0, 32);
  }
  const r = Array.isArray(run) && run.length === 4 ? { r: num(run[0]), out: str(run[1]), steps: num(run[2]), left: num(run[3]) } : null;
  return {
    bins, run: r && r.out ? r : null, clock: num(clock),
    stock: (Array.isArray(stock) ? stock : []).filter(Array.isArray).slice(0, 6).map((s) => ({ id: str(s[0]), steps: num(s[1]), at: num(s[2]), load: 0, out: 0, ...(s[3] === 1 ? { open: true } : {}) })).filter((s) => s.id),
    set: str(set), at: num(at), made: num(made), fed: num(fed), fees: num(fees), missed: num(missed), opened: num(opened),
  };
}
