import { idx, inB, type World, type RailPath } from './tiles';
import { targetAt } from '../game/demolish';

/**
 * Where to bulldoze a built track (or a station's platform) the player has just undone, so that the same raze
 * replayed on the next load takes up exactly that track: a tile along it where the bulldozer's target is it.
 * Call while it is still laid. Null when no tile of it is clear of roads and of other built track.
 */
export function undoRaze(w: World, path: RailPath): { x: number; z: number } | null {
  const n = path.xz.length / 2;
  // from the middle out: the ends are where it meets other lines
  const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => Math.abs(a - n / 2) - Math.abs(b - n / 2));
  const seen = new Set<number>();
  for (const i of order) {
    const x = Math.floor(path.xz[i * 2]), z = Math.floor(path.xz[i * 2 + 1]);
    if (!inB(x, z) || seen.has(idx(x, z))) continue;
    seen.add(idx(x, z));
    const t = targetAt(w, x, z);
    if ((t.kind === 'rail' || t.kind === 'station') && t.path === path) return { x, z };
  }
  return null;
}
