import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import { Vis, type Sched } from '../../nightLights';
import { DARK, LEAF, PINE, TAU, TRUNK, WARM_GLOW, type Draw, type Kit, type P3 } from '../kit';

/**
 * The Terraces: pagoda, shrine, tea house, bathhouse, rice terraces and the hilltop castle. Dark
 * timber, white plaster, vermilion posts and wide grey-blue roofs whose eaves turn up at the corners;
 * paper screens that glow warm after dark.
 */

const TIMBER = hex(0x4a3428), PLASTER = hex(0xf2eee4), VERMILION = hex(0xd2452e), TILE = hex(0x4a5560);
const TILE_BLUE = hex(0x3a4a60), STONE = hex(0xb8b4a8), STONE_DARK = hex(0x8e8a80), GRAVEL = hex(0xd8d2c0);
const PAPER = hex(0xf4ecd8), PAPER_GLOW = hex(0xffe2b0), GOLD = hex(0xd9a441), POND = hex(0x5f9fb8);
const BUND = hex(0x6b5238), SEEDLING = hex(0x7fbf4a), STRAW = hex(0xd8b870), BLOSSOM = hex(0xf2b8cc);
const LANTERN: Sched = [17.3, 30, 1.3];
const SCREENS: Sched = [17.5, 23.5, 1.4];

// ---- shared pieces -------------------------------------------------------------------------------

/**
 * A tiled roof with the eastern curve: hipped, steep toward the ridge and flattening to eaves whose
 * corners turn up by `lift`. (x, z) is its middle, y the eave line, w × d the eave outline; the
 * ridge runs along the longer side. Returns the ridge height.
 */
export function eastRoof(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, col: RGB, lift = 0.06, ridge: RGB = scale(col, 0.7)): number {
  const n = 4, hx = w / 2, hz = d / 2;
  const tx = w >= d ? (w - d) / 2 : 0, tz = d > w ? (d - w) / 2 : 0;
  const ring = (ax: number, az: number, yy: number, up: number): P3[] => {
    const pts: P3[] = [];
    for (let s = 0; s < 4; s++) for (let i = 0; i < n; i++) {
      const u = -1 + (2 * i) / n;
      const [px, pz] = s === 0 ? [u, 1] : s === 1 ? [1, -u] : s === 2 ? [-u, -1] : [-1, u];
      pts.push([x + px * ax, yy + up * (px * pz) ** 2, z + pz * az]);
    }
    return pts;
  };
  const lerp = (a: number, b: number, f: number) => a + (b - a) * f;
  const outer = ring(hx, hz, y, lift);
  const mid = ring(lerp(hx, tx, 0.4), lerp(hz, tz, 0.4), y + h * 0.3, lift * 0.35);
  const top = ring(tx, tz, y + h, 0);
  const under = ring(hx * 0.8, hz * 0.8, y + lift * 0.2, lift * 0.3);
  const below: P3 = [x, y - h, z], above: P3 = [x, y + h * 2, z];
  const m = outer.length, soffit = scale(TIMBER, 0.8);
  for (let i = 0; i < m; i++) {
    const j = (i + 1) % m;
    k.quad(outer[i], outer[j], mid[j], mid[i], col, below);
    k.quad(mid[i], mid[j], top[j], top[i], col, below);
    k.quad(outer[i], outer[j], under[j], under[i], soffit, above);
  }
  k.box(x, y + h - 0.012, z, 2 * tx + 0.05, 0.03, 2 * tz + 0.05, ridge);
  return y + h;
}

/** A truncated pyramid: a stone plinth with battered sides. */
export function frustum(k: Kit, x: number, y: number, z: number, w0: number, d0: number, w1: number, d1: number, h: number, col: RGB, top: RGB = col): void {
  const I: P3 = [x, y + h / 2, z];
  const b = [[-w0 / 2, -d0 / 2], [w0 / 2, -d0 / 2], [w0 / 2, d0 / 2], [-w0 / 2, d0 / 2]];
  const t = [[-w1 / 2, -d1 / 2], [w1 / 2, -d1 / 2], [w1 / 2, d1 / 2], [-w1 / 2, d1 / 2]];
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    k.quad([x + b[i][0], y, z + b[i][1]], [x + b[j][0], y, z + b[j][1]], [x + t[j][0], y + h, z + t[j][1]], [x + t[i][0], y + h, z + t[i][1]], col, I);
  }
  k.quad([x + t[0][0], y + h, z + t[0][1]], [x + t[1][0], y + h, z + t[1][1]], [x + t[2][0], y + h, z + t[2][1]], [x + t[3][0], y + h, z + t[3][1]], top, I);
}

/** A stone lantern standing on y, lit all night. */
export function stoneLantern(k: Kit, x: number, y: number, z: number, s = 1): void {
  k.box(x, y, z, 0.08 * s, 0.03 * s, 0.08 * s, STONE_DARK);
  k.cyl(x, y + 0.03 * s, z, 0.018 * s, 0.08 * s, STONE, 5);
  k.glowBox(x, y + 0.11 * s, z, 0.06 * s, 0.05 * s, 0.06 * s, STONE, LANTERN, WARM_GLOW);
  k.hip(x, y + 0.16 * s, z, 0.11 * s, 0.05 * s, 0.11 * s, STONE_DARK);
}

/** A torii across (x, z) facing +z: two vermilion posts, a black-capped lintel with upturned ends. */
export function torii(k: Kit, x: number, z: number, w: number, h: number): void {
  const r = h * 0.055;
  for (const sx of [-1, 1]) k.cyl(x + sx * w / 2, 0, z, r, h, VERMILION, 6);
  k.box(x, h * 0.72, z, w + r * 5, h * 0.06, r * 1.6, VERMILION);
  k.box(x, h * 0.72 + h * 0.06, z, r * 1.6, h * 0.16, r * 1.4, VERMILION);
  k.box(x, h, z, w + r * 7, h * 0.07, r * 2.4, VERMILION, DARK);
  k.box(x, h + h * 0.07, z, w + r * 8, h * 0.035, r * 2.6, DARK);
  for (const sx of [-1, 1]) k.bar([x + sx * (w / 2 + r * 3), h + h * 0.08, z], [x + sx * (w / 2 + r * 5), h + h * 0.16, z], h * 0.025, DARK);
}

/** A little figure in a conical straw hat. */
function strawHat(k: Kit, x: number, y: number, z: number, shirt: RGB): void {
  k.box(x, y, z, 0.035, 0.06, 0.03, hex(0x3a3f55));
  k.box(x, y + 0.06, z, 0.045, 0.06, 0.035, shirt);
  k.box(x, y + 0.12, z, 0.028, 0.028, 0.028, hex(0xe0b890));
  k.cone(x, y + 0.14, z, 0.055, 0.035, STRAW, 7);
}

/** A cherry: a crooked trunk and a pink crown (green through summer). */
function cherry(k: Kit, x: number, y: number, z: number, s: number): void {
  k.bar([x, y, z], [x + 0.04 * s, y + 0.22 * s, z], 0.025 * s, TRUNK);
  k.tagged(Vis.NotSummer, () => k.dome(x + 0.04 * s, y + 0.18 * s, z, 0.2 * s, BLOSSOM, 7, 2));
  k.tagged(Vis.Summer, () => k.dome(x + 0.04 * s, y + 0.18 * s, z, 0.2 * s, LEAF, 7, 2));
}

/** A flat-crowned garden pine. */
function gardenPine(k: Kit, x: number, y: number, z: number, s: number): void {
  k.bar([x, y, z], [x + 0.08 * s, y + 0.3 * s, z + 0.03 * s], 0.02 * s, TRUNK);
  k.cyl(x + 0.08 * s, y + 0.28 * s, z + 0.03 * s, 0.2 * s, 0.06 * s, PINE, 7);
  k.cyl(x - 0.06 * s, y + 0.18 * s, z, 0.13 * s, 0.05 * s, PINE, 6);
}

// ---- 1. pagoda -----------------------------------------------------------------------------------

const pagoda: Draw = (k) => {
  k.box(0, 0, 0, 1.45, 0.08, 1.45, STONE, GRAVEL);
  k.box(0, 0, 0.8, 0.5, 0.04, 0.2, STONE);
  let y = 0.08;
  for (let i = 0; i < 5; i++) {
    const s = 1 - i * 0.13, h = i ? 0.26 : 0.34, hw = s * 0.4;
    k.box(0, y, 0, s * 0.8, h, s * 0.8, PLASTER);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * hw, y, sz * hw, 0.05, h, 0.05, VERMILION);
    for (const sx of [-1, 1]) k.box(0, y, sx * hw, s * 0.8, 0.035, 0.03, VERMILION);
    for (let f = 0; f < 4; f++) {
      const [px, pz] = f === 0 ? [hw, 0] : f === 1 ? [0, hw] : f === 2 ? [-hw, 0] : [0, -hw];
      k.pane(px, y + 0.05, pz, s * 0.3, h * 0.6, f, i ? PAPER : scale(TIMBER, 1.2), i ? SCREENS : LANTERN, PAPER_GLOW);
    }
    y += h;
    k.box(0, y, 0, s * 0.92, 0.04, s * 0.92, TIMBER);
    eastRoof(k, 0, y + 0.03, 0, s * 1.45, s * 1.45, i === 4 ? 0.26 : 0.15, i % 2 ? TILE_BLUE : TILE, 0.07);
    y += i === 4 ? 0.26 : 0.1;
  }
  // the spire: a bronze mast of nine rings with a ball on top
  k.cyl(0, y, 0, 0.025, 0.6, hex(0x6b5a3a), 5);
  for (let i = 0; i < 6; i++) k.cyl(0, y + 0.12 + i * 0.06, 0, 0.055 - i * 0.004, 0.015, GOLD, 6);
  k.dome(0, y + 0.58, 0, 0.04, GOLD, 6, 2);
  stoneLantern(k, -0.55, 0.08, 0.55);
  stoneLantern(k, 0.55, 0.08, 0.55);
};

// ---- 2. shrine -----------------------------------------------------------------------------------

const shrine: Draw = (k) => {
  torii(k, 0, 0.38, 0.3, 0.36);
  // the approach and the hall
  k.box(0, 0, 0.1, 0.14, 0.012, 0.5, GRAVEL);
  k.box(0, 0, -0.14, 0.48, 0.06, 0.4, STONE);
  k.box(0, 0.06, -0.15, 0.34, 0.2, 0.28, TIMBER);
  for (const sx of [-1, 1]) k.box(sx * 0.17, 0.06, -0.01, 0.03, 0.2, 0.03, VERMILION);
  k.pane(0, 0.08, -0.01, 0.2, 0.14, 1, PAPER, SCREENS, PAPER_GLOW);
  k.box(0, 0.06, 0.06, 0.2, 0.02, 0.1, TIMBER);
  eastRoof(k, 0, 0.26, -0.13, 0.56, 0.48, 0.2, TILE, 0.05);
  k.gable(0, 0.3, 0.07, 0.2, 0.1, 0.1, TILE, TIMBER, true);
  k.box(0, 0.2, 0.02, 0.05, 0.05, 0.02, GOLD);
  stoneLantern(k, -0.3, 0, 0.14, 0.9);
  stoneLantern(k, 0.3, 0, 0.14, 0.9);
};

// ---- 3. tea house --------------------------------------------------------------------------------

const teaHouse: Draw = (k, _W, _D, _b, r) => {
  const hx = -0.2, hz = -0.3;
  // the engawa: a raised deck all round the house on short posts
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(hx + sx * 0.66, 0, hz + sz * 0.5, 0.04, 0.08, 0.04, TIMBER);
  k.box(hx, 0.08, hz, 1.4, 0.03, 1.08, hex(0x8a6a4a));
  k.box(hx, 0, hz + 0.6, 0.3, 0.05, 0.12, STONE);
  // dark frame, paper screens
  k.box(hx, 0.11, hz, 1.08, 0.3, 0.76, TIMBER);
  for (let i = 0; i < 4; i++) {
    const px = hx - 0.405 + i * 0.27;
    k.pane(px, 0.13, hz + 0.38, 0.22, 0.24, 1, PAPER, SCREENS, PAPER_GLOW);
    k.pane(px, 0.13, hz - 0.38, 0.22, 0.24, 3, PAPER, SCREENS, PAPER_GLOW);
  }
  for (let i = 0; i < 3; i++) {
    const pz = hz - 0.25 + i * 0.25;
    k.pane(hx + 0.54, 0.13, pz, 0.19, 0.24, 0, PAPER, SCREENS, PAPER_GLOW);
    k.pane(hx - 0.54, 0.13, pz, 0.19, 0.24, 2, PAPER, SCREENS, PAPER_GLOW);
  }
  eastRoof(k, hx, 0.41, hz, 1.62, 1.26, 0.34, TILE, 0.07);
  // the pond with its stepping stones, a little arched bridge and a lantern
  const px = 0.45, pz = 0.5;
  k.disc(px, 0.004, pz, 0.4, POND, 12, 0.34);
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    k.box(px + Math.cos(a) * 0.42, 0, pz + Math.sin(a) * 0.36, 0.08, 0.035, 0.07, i % 2 ? STONE : STONE_DARK);
  }
  const arc: P3[] = [];
  for (let i = 0; i <= 4; i++) arc.push([px - 0.46 + i * 0.23, 0.02 + Math.sin((i / 4) * Math.PI) * 0.1, pz]);
  for (let i = 0; i < 4; i++) {
    k.bar(arc[i], arc[i + 1], 0.045, VERMILION);
    for (const sz of [-1, 1]) k.box(arc[i][0], arc[i][1], pz + sz * 0.05, 0.015, 0.07, 0.015, VERMILION);
  }
  k.bar([arc[0][0], 0.09, pz + 0.05], [arc[4][0], 0.09, pz + 0.05], 0.008, VERMILION);
  stoneLantern(k, 0.85, 0, 0.1);
  cherry(k, -0.75, 0, 0.6, 1.2 + r() * 0.2);
  gardenPine(k, 0.8, 0, -0.7, 1.1);
};

// ---- 4. bathhouse --------------------------------------------------------------------------------

const bathhouse: Draw = (k) => {
  const bz = -0.42;
  k.box(0, 0, bz, 1.5, 0.05, 0.86, STONE);
  k.box(0, 0.05, bz, 1.36, 0.32, 0.72, TIMBER);
  k.box(0, 0.25, bz, 1.38, 0.12, 0.74, PLASTER);
  for (let i = 0; i < 4; i++) k.pane(-0.5 + i * 0.33, 0.27, bz + 0.37, 0.2, 0.07, 1, PAPER, SCREENS, PAPER_GLOW);
  eastRoof(k, 0, 0.37, bz, 1.7, 1.04, 0.36, TILE_BLUE, 0.07);
  // the doorway with its indigo noren curtain in three strips
  k.box(0.35, 0.05, bz + 0.37, 0.3, 0.22, 0.02, DARK);
  k.glowBox(0.35, 0.06, bz + 0.381, 0.26, 0.14, 0.01, hex(0x5a4a3a), SCREENS, WARM_GLOW);
  for (let i = 0; i < 3; i++) k.box(0.26 + i * 0.09, 0.16, bz + 0.395, 0.08, 0.11, 0.008, i === 1 ? hex(0xe8e0d0) : hex(0x2a3a70));
  k.gable(0.35, 0.3, bz + 0.46, 0.44, 0.1, 0.2, TILE_BLUE, TIMBER, true);
  // the tall bath chimney
  k.box(-0.55, 0.37, bz - 0.2, 0.12, 0.9, 0.12, hex(0x9c5040));
  k.box(-0.55, 1.27, bz - 0.2, 0.15, 0.04, 0.15, DARK);
  // the outdoor pool behind a bamboo fence, its steam turning slowly above it
  const px = -0.35, pz = 0.45;
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    k.box(px + Math.cos(a) * 0.36, 0, pz + Math.sin(a) * 0.3, 0.1, 0.05 + (i % 3) * 0.02, 0.09, i % 2 ? STONE_DARK : STONE);
  }
  k.disc(px, 0.02, pz, 0.32, hex(0x8fc8cc), 12, 0.26);
  k.spin(px, 0.03, pz, 'y', 0.25, (s) => {
    const steam = hex(0xf2f4f6);
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU;
      s.dome(Math.cos(a) * 0.14, 0.04 + i * 0.07, Math.sin(a) * 0.12, 0.08 - i * 0.008, steam, 6, 2);
    }
  });
  for (let i = 0; i < 9; i++) k.box(0.2, 0, 0.1 + i * 0.1, 0.03, 0.24 + (i % 2) * 0.02, 0.03, hex(0xb8a060));
  k.bar([0.2, 0.18, 0.1], [0.2, 0.18, 0.9], 0.01, hex(0x8a7040));
  stoneLantern(k, 0.6, 0, 0.55);
  cherry(k, 0.65, 0, 0.1, 1.1);
};

// ---- 5. rice terraces ----------------------------------------------------------------------------

const riceTerraces: Draw = (k, W, D, b, r) => {
  // the paddy water is the lot's finish; these are the bunds between the plots and the planting in them
  const nx = Math.max(2, Math.round(W / 1.6)), nz = Math.max(2, Math.round(D / 1.3));
  const cw = W / nx, cd = D / nz, bund = scale(BUND, 1.05), top = hex(0x7a8a4a);
  for (let i = 0; i <= nz; i++) k.box(0, 0, -D / 2 + i * cd, W, 0.05, 0.08, bund, top);
  for (let i = 0; i <= nx; i++) k.box(-W / 2 + i * cw, 0, 0, 0.08, 0.05, D, bund, top);
  k.tagged(Vis.NotWinter, () => {
    for (let pz = 0; pz < nz; pz++) for (let px = 0; px < nx; px++) {
      if ((px + pz * 3 + b.seed) % 7 === 3) continue;     // one plot left fallow, a bare mirror
      const x0 = -W / 2 + px * cw, z0 = -D / 2 + pz * cd;
      for (let rz = z0 + 0.16; rz < z0 + cd - 0.1; rz += 0.14) {
        for (let rx = x0 + 0.14; rx < x0 + cw - 0.1; rx += 0.34) {
          // a row of seedlings as just its top and its sunny face: they are only ever seen from above
          const a = rx, e = rx + 0.24, h = 0.04, I: P3 = [rx + 0.12, 0, rz];
          k.quad([a, h, rz - 0.012], [e, h, rz - 0.012], [e, h, rz + 0.012], [a, h, rz + 0.012], SEEDLING, I);
          k.quad([a, 0, rz + 0.012], [e, 0, rz + 0.012], [e, h, rz + 0.012], [a, h, rz + 0.012], scale(SEEDLING, 0.85), I);
        }
      }
    }
  });
  // planters in straw hats, and a hut on the corner bund
  strawHat(k, -W / 2 + cw * 0.5, 0, -D / 2 + cd * 0.55, hex(0x5a7aa8));
  strawHat(k, -W / 2 + cw * 0.72, 0, -D / 2 + cd * 0.4, hex(0xe8e0d0));
  if (r() < 0.7) strawHat(k, W / 2 - cw * 0.4, 0, D / 2 - cd * 0.5, hex(0xa84a3a));
  const hx = W / 2 - 0.35, hz = -D / 2 + 0.35;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(hx + sx * 0.14, 0, hz + sz * 0.12, 0.03, 0.2, 0.03, TIMBER);
  k.box(hx, 0.08, hz, 0.34, 0.03, 0.3, hex(0x8a6a4a));
  k.box(hx, 0.11, hz - 0.1, 0.3, 0.12, 0.06, hex(0x9a8a6a));
  k.gable(hx, 0.24, hz, 0.42, 0.18, 0.4, STRAW, hex(0x9a8a6a));
};

// ---- 6. hilltop castle (wonder) ------------------------------------------------------------------

const hilltopCastle: Draw = (k, _W, _D, b) => {
  const wall = hex(0xf6f4ee), roof = hex(0x5a636e), moat = hex(0x4f8fb0), base = 0.6;
  const lit = (i: number): Sched => (i * 7 + b.seed) % 5 === 0 ? [99, 0, 0] : [17.4 + ((i * 13) % 10) * 0.1, 23 + ((i * 7) % 20) * 0.1, 1.5];
  // the moat: a square ring of water with a stone kerb, the causeway crossing it at the front
  const mo = 5.65, mi = 4.75, mw = mo - mi, mc = (mo + mi) / 2;
  k.box(0, 0, -mc, 2 * mo, 0.012, mw, moat);
  k.box(-mc, 0, 0, mw, 0.012, 2 * mi, moat);
  k.box(mc, 0, 0, mw, 0.012, 2 * mi, moat);
  for (const sx of [-1, 1]) k.box(sx * (mo + 0.65) / 2, 0, mc, mo - 0.65, 0.012, mw, moat);
  for (const [x, z, w, d] of [[0, -mo, 2 * mo, 0.08], [-mo, 0, 0.08, 2 * mo], [mo, 0, 0.08, 2 * mo], [-3.15, mo, 5, 0.08], [3.15, mo, 5, 0.08]]) k.box(x, 0, z, w, 0.06, d, STONE_DARK);
  k.box(0, 0, 5.3, 1.3, 0.05, 1.4, GRAVEL);
  for (const sx of [-1, 1]) k.box(sx * 0.68, 0, 5.2, 0.08, 0.12, 1.1, STONE_DARK);
  // the battered stone base and the ramp up to the gate
  frustum(k, 0, 0, 0, 9.4, 9.4, 8.5, 8.5, base, STONE_DARK, GRAVEL);
  k.turned(Math.PI, () => k.wedge(0, 0, -4.6, 1.2, base, 1.2, STONE));
  // curtain walls in white plaster with tiled caps, a gap at the gate
  const e = 4.05, wh = 0.3;
  const run = (x: number, z: number, len: number, alongZ: boolean) => {
    const [w, d] = alongZ ? [0.12, len] : [len, 0.12];
    k.box(x, base, z, w, wh, d, wall);
    k.box(x, base, z, w + 0.01, 0.06, d + 0.01, STONE);
    k.gable(x, base + wh, z, alongZ ? 0.24 : len + 0.04, 0.09, alongZ ? len + 0.04 : 0.24, roof, wall, alongZ);
  };
  run(0, -e, 2 * e, false);
  run(-e, 0, 2 * e, true);
  run(e, 0, 2 * e, true);
  for (const sx of [-1, 1]) run(sx * (e + 0.62) / 2, e, e - 0.62, false);
  // the gatehouse over the entrance, its doors swung open
  for (const sx of [-1, 1]) k.box(sx * 0.82, base, e, 0.42, 0.5, 0.6, STONE_DARK);
  k.box(0, base + 0.5, e, 2.1, 0.36, 0.7, wall);
  for (let i = 0; i < 3; i++) k.pane(-0.6 + i * 0.6, base + 0.64, e + 0.35, 0.22, 0.1, 1, DARK, lit(i), WARM_GLOW);
  eastRoof(k, 0, base + 0.86, e, 2.5, 1.05, 0.34, roof, 0.1);
  for (const sx of [-1, 1]) k.box(sx * 0.5, base, e - 0.22, 0.24, 0.46, 0.04, TIMBER);
  // corner turrets, two storeys each
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const tx = sx * 3.7, tz = sz * 3.7;
    k.box(tx, base, tz, 1.0, 0.42, 1.0, wall);
    eastRoof(k, tx, base + 0.42, tz, 1.34, 1.34, 0.2, roof, 0.08);
    k.box(tx, base + 0.5, tz, 0.72, 0.3, 0.72, wall);
    eastRoof(k, tx, base + 0.8, tz, 1.02, 1.02, 0.3, roof, 0.08);
    for (let f = 0; f < 4; f++) {
      const [px, pz] = f === 0 ? [0.5, 0] : f === 1 ? [0, 0.5] : f === 2 ? [-0.5, 0] : [0, -0.5];
      k.pane(tx + px, base + 0.16, tz + pz, 0.2, 0.1, f, DARK, lit(f * 4 + (sx + 1) * 3 + sz + 1), WARM_GLOW);
    }
  }
  // a low palace hall, pines and cherries in the bailey
  k.box(2.1, base, 2.0, 1.6, 0.34, 1.0, TIMBER);
  k.box(2.1, base + 0.2, 2.0, 1.62, 0.14, 1.02, wall);
  for (let i = 0; i < 4; i++) k.pane(1.5 + i * 0.4, base + 0.05, 2.51, 0.3, 0.14, 1, PAPER, SCREENS, PAPER_GLOW);
  eastRoof(k, 2.1, base + 0.34, 2.0, 1.95, 1.3, 0.34, roof, 0.07);
  for (const [x, z, s] of [[-2.6, 2.6, 1.8], [-3.0, 0.8, 1.5], [-2.2, -2.9, 1.6], [2.9, -2.4, 1.7]]) cherry(k, x, base, z, s);
  for (const [x, z, s] of [[-1.5, 3.2, 1.8], [0.9, 2.9, 1.5], [3.2, 0.4, 1.6]]) gardenPine(k, x, base, z, s);
  for (const sx of [-1, 1]) stoneLantern(k, sx * 0.9, base, 3.2, 1.6);
  // the keep: a stone plinth and five stepped white storeys under curved roofs, gold on the ridge
  const kz = -0.9, ph = 0.8;
  frustum(k, 0, base, kz, 3.7, 3.4, 3.1, 2.8, ph, STONE_DARK, STONE);
  let y = base + ph;
  const ws = [2.8, 2.4, 2.0, 1.6, 1.2];
  for (let i = 0; i < 5; i++) {
    const w = ws[i], d = w * 0.86, h = i === 4 ? 0.4 : 0.44;
    k.box(0, y, kz, w, h, d, wall);
    k.box(0, y, kz, w + 0.02, 0.07, d + 0.02, hex(0x3a3a3e));
    const nw = Math.max(2, Math.round(w / 0.42)), nd = Math.max(2, Math.round(d / 0.42));
    for (let j = 0; j < nw; j++) {
      const px = -w / 2 + (w / nw) * (j + 0.5);
      k.pane(px, y + 0.18, kz + d / 2 + 0.006, 0.14, 0.12, 1, DARK, lit(i * 11 + j), WARM_GLOW);
      k.pane(px, y + 0.18, kz - d / 2, 0.14, 0.12, 3, DARK, lit(i * 5 + j + 3), WARM_GLOW);
    }
    for (let j = 0; j < nd; j++) {
      const pz = kz - d / 2 + (d / nd) * (j + 0.5);
      k.pane(w / 2, y + 0.18, pz, 0.14, 0.12, 0, DARK, lit(i * 3 + j + 1), WARM_GLOW);
      k.pane(-w / 2, y + 0.18, pz, 0.14, 0.12, 2, DARK, lit(i * 9 + j + 2), WARM_GLOW);
    }
    // floodlight wash on the front, invisible by day
    k.glowBox(0, y + 0.08, kz + d / 2 + 0.004, w - 0.1, h - 0.12, 0.004, wall, [18, 23.5, 0.35], hex(0xfff6e8));
    y += h;
    const rh = i === 4 ? 0.62 : 0.28;
    const ridge = eastRoof(k, 0, y, kz, w + 0.55, d + 0.55, rh, roof, 0.12);
    if (i === 1 || i === 3) {
      // a triangular gable on the roof's front and back
      for (const sz of [-1, 1]) k.gable(0, y + 0.04, kz + sz * (d / 2 + 0.05), w * 0.42, 0.3, 0.4, roof, wall, true);
    }
    if (i === 4) {
      k.box(0, ridge - 0.02, kz, 0.2, 0.04, 0.08, GOLD);
      for (const sx of [-1, 1]) {
        k.bar([sx * 0.12, ridge, kz], [sx * 0.2, ridge + 0.16, kz], 0.03, GOLD);
        k.box(sx * 0.2, ridge + 0.12, kz, 0.05, 0.08, 0.05, GOLD);
      }
    }
    y += 0.08;
  }
};

