// ---- shipwreck (3 × 2) -------------------------------------------------------------------------------

/** A wrecked steamer on the shore: heeled over, broken in two, its ribs showing, sand drifted against it. */
const shipwreck: Draw = (k) => {
  const DECK = hex(0x6e5c4a), B = 0.5, HL = 0.15, HU = 0.17;
  // the sand it lies in, and the drifts against the weather side
  mound(k, 0, 0, 0.95, 0.06, SAND, 10);
  mound(k, -0.8, 0.05, 0.62, 0.05, SAND, 8);
  mound(k, 0.75, 0.05, 0.62, 0.05, SAND, 8);
  mound(k, -0.85, -0.42, 0.5, 0.24, SAND, 7, scale(SAND, 1.04));
  mound(k, 0.85, -0.38, 0.4, 0.16, SAND, 7, scale(SAND, 1.04));
  // the stern half: deckhouse and a leaning funnel
  const fs = frame([-0.72, 0.07, -0.02], 0.08, -0.03, 0.4);
  fbox(k, fs, 0, 0, 0, 1.0, HL, B, HULL_RED);
  fbox(k, fs, 0, HL, 0, 1.0, HU, B + 0.02, HULL_BLACK, DECK);
  fbox(k, fs, -0.56, 0.04, 0, 0.14, HL + HU - 0.04, B * 0.7, HULL_BLACK, DECK);
  fbox(k, fs, 0.5, 0.02, 0, 0.02, HL + HU - 0.04, B - 0.06, GAP);
  fbox(k, fs, -0.12, HL + HU, 0, 0.42, 0.16, 0.3, hex(0xcfc8b8), hex(0x8f8a80));
  for (const dx of [-0.24, -0.1, 0.04]) fbox(k, fs, dx, HL + HU + 0.07, 0.15, 0.06, 0.05, 0.02, GAP);
  tube(k, fs([0.0, HL + HU + 0.16, 0]), fs([0.1, HL + HU + 0.52, 0.04]), 0.085, 0.075, HULL_BLACK, 8, GAP);
  tube(k, fs([0.06, HL + HU + 0.37, 0.024]), fs([0.08, HL + HU + 0.45, 0.032]), 0.09, 0.088, HULL_RED, 8);
  fbox(k, fs, -0.42, HL + HU, 0, 0.1, 0.04, 0.4, RUST_DARK);
  // the bow half, swung round and canted the other way
  const fb = frame([0.62, 0.06, 0.08], -0.16, 0.07, 0.3);
  fbox(k, fb, -0.05, 0, 0, 0.6, HL, B, HULL_RED);
  fbox(k, fb, -0.05, HL, 0, 0.6, HU, B + 0.02, HULL_BLACK, DECK);
  fbox(k, fb, -0.35, 0.02, 0, 0.02, HL + HU - 0.04, B - 0.06, GAP);
  {
    // the stem: the sides drawn in to a point
    const x0 = 0.25, x1 = 0.72, h = B / 2, yt = HL + HU, I = fb([0.35, yt / 2, 0]);
    k.tri(fb([x0, yt, -h]), fb([x0, yt, h]), fb([x1, yt + 0.04, 0]), DECK, I);
    for (const s of [-1, 1]) {
      k.quad(fb([x0, HL, s * h]), fb([x1 - 0.12, HL, 0]), fb([x1, yt + 0.04, 0]), fb([x0, yt, s * h]), HULL_BLACK, I);
      k.quad(fb([x0, 0, s * h]), fb([x1 - 0.2, 0, 0]), fb([x1 - 0.12, HL, 0]), fb([x0, HL, s * h]), HULL_RED, I);
    }
  }
  fbox(k, fb, -0.05, HL + HU, 0, 0.2, 0.05, 0.2, RUST_DARK);
  // the mast, down across the deck and into the sand, its yard still on it
  k.bar(fb([0.1, HL + HU, 0]), [0.35, 0.08, 0.88], 0.018, hex(0x8a7a66));
  k.bar([0.18, 0.12, 0.7], [0.62, 0.1, 0.62], 0.012, hex(0x8a7a66));
  // the ribs in the gap, on what is left of the keel
  const fg = frame([0.02, 0.06, 0.03], -0.04, 0, 0.36);
  k.bar(fg([-0.3, 0.01, 0]), fg([0.32, 0.01, 0]), 0.022, RUST_DARK);
  for (const x of [-0.14, 0.0, 0.14]) {
    for (const s of [-1, 1]) {
      k.bar(fg([x, 0.01, 0]), fg([x, 0.1, s * 0.2]), 0.014, RUST);
      k.bar(fg([x, 0.1, s * 0.2]), fg([x, 0.27 - Math.abs(x) * 0.4, s * 0.25]), 0.014, RUST);
    }
  }
  // crates off the deck cargo, grown over with barnacles
  const BARN = hex(0xcfd2c4), CRATE = hex(0x7a6248);
  k.box(-0.95, 0.04, 0.68, 0.17, 0.14, 0.17, CRATE, BARN);
  fbox(k, frame([-0.68, 0.03, 0.78], 0.5, 0.2), 0, 0, 0, 0.15, 0.13, 0.15, CRATE, BARN);
  k.box(-0.35, 0.04, 0.62, 0.13, 0.1, 0.13, scale(CRATE, 0.9), BARN);
  fbox(k, frame([1.05, 0.03, 0.66], -0.3, 0, 0.25), 0, 0, 0, 0.16, 0.12, 0.14, CRATE, BARN);
};

// ---- plane wreck (3 × 3) -----------------------------------------------------------------------------

/** A nacelle on a wing with its propeller bent back by the ground. */
function engine(k: Kit, f: Xf, x: number, y: number, z: number): void {
  tube(k, f([x - 0.12, y, z]), f([x + 0.2, y, z]), 0.07, 0.085, SILVER_DARK, 8, GAP, DARK);
  tube(k, f([x + 0.2, y, z]), f([x + 0.26, y, z]), 0.03, 0.02, DARK, 6);
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * TAU + 0.5, c = Math.cos(a), s = Math.sin(a);
    k.bar(f([x + 0.24, y, z]), f([x + 0.24, y + c * 0.12, z + s * 0.12]), 0.014, DARK);
    k.bar(f([x + 0.24, y + c * 0.12, z + s * 0.12]), f([x + 0.15, y + c * 0.2, z + s * 0.2]), 0.013, DARK);
  }
}

/** A crashed twin-engined transport: broken behind the wing, one wing torn off, a scar across the ground, saplings through it. */
const planeWreck: Draw = (k, _W, _D, _b, r) => {
  const yaw = -0.6, f0 = frame([0.1, 0, 0.05], yaw);
  // the scar it cut coming down, and the earth thrown up along it
  fbox(k, f0, -0.78, 0, 0, 1.55, 0.02, 0.36, EARTH_DARK);
  fbox(k, f0, -0.1, 0, 0.02, 0.5, 0.025, 0.5, EARTH_DARK);
  for (let i = 0; i < 6; i++) {
    const p = f0([-1.4 + i * 0.26, 0, (i % 2 ? 1 : -1) * (0.2 + r() * 0.06)]);
    mound(k, p[0], p[2], 0.1 + r() * 0.06, 0.06 + r() * 0.04, EARTH, 5);
  }
  // the forward fuselage on its belly, cockpit glass gone dark
  const fy = 0.16, R = 0.15;
  tube(k, f0([-0.05, fy, 0]), f0([0.8, fy, 0]), R, R, SILVER, 8, GAP);
  tube(k, f0([0.8, fy, 0]), f0([1.12, fy - 0.02, 0]), R, 0.05, SILVER, 8, SILVER_DARK);
  fbox(k, f0, 0.84, fy + 0.085, 0, 0.13, 0.055, 0.2, GAP);
  for (const s of [-1, 1]) for (const dx of [0.1, 0.28, 0.46]) fbox(k, f0, dx, fy + 0.02, s * (R - 0.012), 0.07, 0.05, 0.02, GAP);
  // the wing still on, its tip lifted; the engine and its bent blades
  const fw = frame(f0([0.42, 0.07, -0.1]), yaw, 0, 0.1);
  fbox(k, fw, 0, 0, -0.52, 0.36, 0.035, 1.0, SILVER, SILVER_DARK);
  fbox(k, fw, -0.02, 0, -0.98, 0.26, 0.03, 0.12, SILVER, SILVER_DARK);
  engine(k, fw, 0.06, 0.04, -0.38);
  // the stub of the other, and the wing itself lying where it was thrown
  fbox(k, f0, 0.42, 0.07, 0.24, 0.36, 0.035, 0.22, SILVER, SILVER_DARK);
  const ft = frame(f0([-0.25, 0.03, 0.98]), yaw + 0.9, 0.05, -0.04);
  fbox(k, ft, 0, 0, 0, 0.36, 0.035, 0.95, SILVER, SILVER_DARK);
  fbox(k, ft, 0, 0, -0.475, 0.34, 0.03, 0.02, GAP);
  engine(k, ft, 0.06, 0.05, -0.12);
  // the rear fuselage, slewed round, the tail standing up
  const fr = frame(f0([-0.2, 0.0, 0.1]), yaw + 0.5, -0.2);
  tube(k, fr([0, fy, 0]), fr([-0.95, fy + 0.06, 0]), R, 0.05, SILVER, 8, GAP, SILVER_DARK);
  {
    const I = fr([-0.8, fy + 0.3, 0]), t = 0.015;
    for (const s of [-1, 1]) {
      k.quad(fr([-0.62, fy + 0.12, s * t]), fr([-0.98, fy + 0.1, s * t]), fr([-1.0, fy + 0.5, s * t]), fr([-0.84, fy + 0.5, s * t]), s > 0 ? SILVER : SILVER_DARK, [I[0], I[1], I[2]]);
    }
    k.quad(fr([-0.62, fy + 0.12, -t]), fr([-0.62, fy + 0.12, t]), fr([-0.84, fy + 0.5, t]), fr([-0.84, fy + 0.5, -t]), SILVER, I);
    k.quad(fr([-0.84, fy + 0.5, -t]), fr([-0.84, fy + 0.5, t]), fr([-1.0, fy + 0.5, t]), fr([-1.0, fy + 0.5, -t]), SILVER, I);
    fbox(k, fr, -0.9, fy + 0.36, 0, 0.1, 0.12, 0.034, hex(0x9a4a3a));
  }
  fbox(k, fr, -0.84, fy + 0.07, 0, 0.2, 0.025, 0.62, SILVER, SILVER_DARK);
  // what has grown up through it since
  const a = f0([-0.12, 0, -0.02]), b2 = f0([0.3, 0, 0.5]), c = f0([-0.75, 0, -0.35]);
  tree(k, a[0], 0, a[2], 0.85, false);
  tree(k, b2[0], 0, b2[2], 0.6, false);
  tree(k, c[0], 0, c[2], 0.55, true);
  for (const [bx, bz, br] of [[0.75, -0.55, 0.1], [-0.5, 0.35, 0.09], [1.0, 0.95, 0.08], [0.2, -0.9, 0.07], [-0.95, 0.75, 0.09]] as const) ball(k, bx, 0, bz, br, BUSH);
};

// ---- ruined abbey (4 × 5) ----------------------------------------------------------------------------

/** A roofless Gothic abbey: empty pointed windows down the nave, a west front with its rose window open to the sky. */
const ruinedAbbey: Draw = (k, _W, _D, _b, r) => {
  k.box(0, 0, -0.05, 3.1, 0.02, 4.7, GRASS);
  const nx = 1.1, z0 = -2.15, z1 = 1.85, n = 6, step = (z1 - z0) / n, T = 0.17;
  const PH = 1.1, RISE = 0.4, TOP = 1.62;
  // which bays of each side still carry their arch (the east side nearly whole, the west mostly down)
  const whole: Record<number, boolean[]> = { 1: [true, true, true, true, false, true], [-1]: [true, false, false, true, true, false] };
  for (const sx of [-1, 1]) {
    const x = sx * nx, w = whole[sx];
    for (let i = 0; i <= n; i++) {
      const z = z0 + i * step, full = (i > 0 && w[i - 1]) || (i < n && w[i]);
      const ph = full ? PH : 0.3 + r() * 0.55;
      k.box(x, 0.02, z, T, full ? TOP : ph, T, STONE, STONE_DARK);
      k.box(x + sx * 0.15, 0.02, z, 0.12, Math.min(ph, 0.75), 0.14, STONE_DARK);
    }
    for (let i = 0; i < n; i++) {
      const za = z0 + i * step, zm = za + step / 2;
      // the sill wall under the window
      k.box(x, 0.02, zm, 0.13, w[i] ? 0.38 : 0.12 + r() * 0.2, step - T, STONE_DARK);
      if (!w[i]) continue;
      for (const s of [-1, 1]) k.bar([x, PH - 0.02, zm + s * (step / 2 - 0.06)], [x, PH + RISE, zm], 0.045, STONE_DARK);
      // the course of wall the arch still carries, its top broken
      k.box(x, PH + RISE, zm, 0.13, TOP - PH - RISE + 0.02 + r() * 0.12, step - T + 0.02, STONE, STONE_DARK);
    }
  }
  // two bays at the east end walled up solid, and the ivy that has taken them
  for (const i of [0, 1]) {
    const zm = z0 + (i + 0.5) * step;
    k.box(nx, 0.4, zm, 0.12, 0.95, step - T, STONE);
    k.box(nx, 0.3 + i * 0.25, zm - 0.04, 0.18, 0.95 - i * 0.2, step * 0.62, IVY);
    k.box(nx, 0.02, zm + 0.2, 0.24, 0.62, 0.3, scale(IVY, 1.15));
  }
  k.box(nx + 0.02, 0.5, z0, T + 0.06, 0.75, T + 0.06, IVY);
  // the east end: a tall lancet between two stubs of wall
  lancet(k, 0, z0, false, 0.62, 1.35, 0.5, T, STONE);
  for (const s of [-1, 1]) k.box(s * 0.7, 0.02, z0, 0.6, 0.35 + r() * 0.35, 0.14, STONE_DARK);
  // the west front: two towers, the door, and the ring of the rose window with a few spokes left in it
  const zf = 2.1;
  k.box(-1.0, 0.02, zf, 0.44, 2.38, 0.44, STONE, STONE_DARK);
  k.box(-1.1, 2.4, zf + 0.1, 0.16, 0.14, 0.16, STONE, STONE_DARK);
  k.box(1.0, 0.02, zf, 0.44, 1.85, 0.44, STONE, STONE_DARK);
  k.box(1.1, 1.87, zf - 0.1, 0.2, 0.22, 0.2, STONE, STONE_DARK);
  for (const s of [-1, 1]) {
    k.box(s * 1.0, 0.9, zf + 0.225, 0.1, 0.34, 0.02, GAP);
    k.box(s * 0.6, 0.02, zf, 0.4, 1.05, 0.26, STONE);
    k.box(s * 0.65, 1.07, zf, 0.28, s < 0 ? 0.95 : 0.7, 0.22, STONE, STONE_DARK);
  }
  lancet(k, 0, zf, false, 0.62, 0.62, 0.36, 0.18, STONE_DARK);
  k.box(0, 0.98, zf, 0.84, 0.1, 0.26, STONE);
  k.hoop(0, 1.56, zf, 0.43, 0.045, STONE, 12, 'xy');
  k.hoop(0, 1.56, zf, 0.12, 0.02, STONE_DARK, 8, 'xy');
  for (const a of [0.4, 1.45, 2.6, 3.5, 5.3]) {
    k.bar([Math.cos(a) * 0.12, 1.56 + Math.sin(a) * 0.12, zf], [Math.cos(a) * 0.4, 1.56 + Math.sin(a) * 0.4, zf], 0.014, STONE_DARK);
  }
  k.bar([-0.78, 2.02, zf], [0.02, 2.38, zf], 0.05, STONE);
  k.bar([0.78, 1.77, zf], [0.3, 2.06, zf], 0.05, STONE);
  // stumps of the nave's columns, and a drum rolled off one
  for (const sx of [-1, 1]) {
    for (let j = 0; j < 5; j++) {
      const z = -1.5 + j * 0.72;
      k.box(sx * 0.5, 0.02, z, 0.26, 0.05, 0.26, STONE_DARK);
      k.cyl(sx * 0.5, 0.07, z, 0.09, 0.12 + r() * 0.6, STONE, 7, STONE_DARK);
    }
  }
  tube(k, [0.1, 0.11, 0.35], [0.3, 0.11, 0.5], 0.09, 0.09, STONE, 7, STONE_DARK);
  // fallen blocks in the grass
  for (let i = 0; i < 12; i++) {
    const bx = (r() - 0.5) * 2.6, bz = -2.0 + r() * 3.8, s = 0.1 + r() * 0.12;
    if (Math.abs(Math.abs(bx) - 0.5) < 0.2) continue;
    fbox(k, frame([bx, 0.01, bz], r() * 3, (r() - 0.5) * 0.4), 0, 0, 0, s * 1.4, s * 0.8, s, i % 3 ? STONE : STONE_DARK);
  }
};

