/** A Cold War bunker: a mossy casemate in a grassed mound, a rusted blast door, a sagging fence, one red lamp. */
const bunker: Draw = (k) => {
  mound(k, 0, -0.1, 0.86, 0.5, GRASS, 10, scale(GRASS, 1.06));
  mound(k, 0, -0.42, 0.62, 0.66, GRASS, 9, scale(GRASS, 1.06));
  // the casemate, its roof slab gone green
  k.box(0, 0.02, 0.14, 0.96, 0.44, 0.8, CONCRETE);
  k.box(0, 0.46, 0.14, 1.04, 0.07, 0.88, CONCRETE_DARK, MOSS);
  k.box(0.481, 0.28, 0.3, 0.02, 0.05, 0.3, GAP);
  k.box(-0.481, 0.28, 0.3, 0.02, 0.05, 0.3, GAP);
  // the entrance: wing walls, a lintel, and the door set back between them
  for (const s of [-1, 1]) k.box(s * 0.29, 0.02, 0.66, 0.12, 0.42, 0.28, CONCRETE);
  k.box(0, 0.4, 0.66, 0.7, 0.1, 0.3, CONCRETE_DARK, MOSS);
  k.box(0, 0.0, 0.7, 0.46, 0.03, 0.3, CONCRETE_DARK);
  k.box(0, 0.03, 0.545, 0.42, 0.37, 0.03, RUST);
  k.box(0, 0.03, 0.565, 0.02, 0.37, 0.012, RUST_DARK);
  for (const y of [0.1, 0.3]) k.box(0, y, 0.566, 0.42, 0.025, 0.014, RUST_DARK);
  k.hoop(0.09, 0.21, 0.585, 0.045, 0.009, DARK, 8, 'xy');
  k.glowBox(0, 0.415, 0.82, 0.07, 0.05, 0.03, hex(0x7a2622), ALL_NIGHT, RED_LIGHT);
  // on the roof: a ventilation cowl and what is left of the mast
  k.cyl(-0.3, 0.53, 0.2, 0.05, 0.15, CONCRETE_DARK, 6);
  k.dome(-0.3, 0.68, 0.2, 0.085, RUST, 6, 2);
  k.bar([0.32, 0.53, 0.0], [0.36, 1.05, -0.13], 0.014, DARK);
  k.bar([0.26, 0.85, -0.12], [0.44, 0.88, -0.12], 0.009, DARK);
  k.bar([0.36, 1.05, -0.13], [0.46, 1.12, -0.05], 0.009, DARK);
  for (const [gx, gz] of [[0.16, 0.1], [0.44, 0.2]] as const) k.bar([0.34, 0.75, -0.115], [gx, 0.53, gz], 0.005, METAL);
  // the fence: leaning posts, sagging wire, a gap where the gate was, the sign still on it
  const E = 0.88, FH = 0.3, WIRE = hex(0x8e9498);
  const posts: P3[] = [];
  const run: [number, number][] = [[-0.34, E], [-E, E], [-E, 0], [-E, -E], [0, -E], [E, -E], [E, 0], [E, E], [0.34, E]];
  run.forEach(([px, pz], i) => {
    const lx = ((i * 37) % 5 - 2) * 0.025, lz = ((i * 53) % 5 - 2) * 0.025;
    k.bar([px, 0, pz], [px + lx, FH, pz + lz], 0.012, WIRE);
    posts.push([px + lx, FH, pz + lz]);
  });
  for (let i = 0; i + 1 < posts.length; i++) {
    const a = posts[i], b = posts[i + 1];
    for (const [dy, sag] of [[-0.02, 0.07], [-0.13, 0.05], [-0.24, 0.02]] as const) {
      const m: P3 = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2 + dy - sag, (a[2] + b[2]) / 2];
      k.bar([a[0], a[1] + dy, a[2]], m, 0.005, WIRE);
      k.bar(m, [b[0], b[1] + dy, b[2]], 0.005, WIRE);
    }
  }
  fbox(k, frame([0.6, 0.1, E + 0.01], 0, -0.12), 0, 0, 0, 0.2, 0.15, 0.015, hex(0xe0b83a));
  fbox(k, frame([0.6, 0.1, E + 0.022], 0, -0.12), 0, 0.04, 0, 0.12, 0.07, 0.01, GAP);
};

// ---- crashed satellite (2 × 2) -----------------------------------------------------------------------

/** A fallen satellite in its crater: gold foil half buried, one solar wing up and one down, marker flags round it. */
const crashedSatellite: Draw = (k) => {
  // the crater: a ring of thrown-up earth round a scorched floor
  k.band(0, 0, 0, 0.74, 0.13, 0.58, 10, EARTH);
  k.band(0, 0, 0.13, 0.58, 0.135, 0.5, 10, scale(EARTH, 1.1), scale(EARTH, 1.1));
  k.band(0, 0, 0.13, 0.5, 0.02, 0.34, 10, EARTH_DARK, EARTH_DARK);
  k.cyl(0, 0, 0, 0.35, 0.02, SCORCH, 10);
  for (let i = 0; i < 5; i++) {
    const a = 0.5 + i * 1.3, c = Math.cos(a), s = Math.sin(a);
    fbox(k, frame([c * 0.8, 0, s * 0.8], -a), 0, 0, 0, 0.16 + (i % 2) * 0.08, 0.012, 0.06, SCORCH);
  }
  k.glowBox(0.02, 0.022, 0.02, 0.4, 0.008, 0.4, SCORCH, ALL_NIGHT, scale(COOL_GLOW, 0.45));
  // the body, nose down at an angle
  const f = frame([0.03, -0.06, 0.02], 0.5, 0.45, 0.3);
  fbox(k, f, 0, 0, 0, 0.36, 0.44, 0.34, FOIL, FOIL_DARK);
  fbox(k, f, 0.1, 0.12, 0.171, 0.12, 0.2, 0.012, SCORCH);
  fbox(k, f, -0.181, 0.2, 0.02, 0.012, 0.18, 0.18, FOIL_DARK);
  fbox(k, f, 0, 0.44, 0, 0.22, 0.04, 0.2, DARK);
  {
    const a = f([0.11, 0.3, 0.177]), g: P3 = [a[0], a[1], a[2]];
    k.glowBox(g[0], g[1], g[2], 0.035, 0.035, 0.035, hex(0x9fb4c8), ALL_NIGHT, COOL_GLOW);
  }
  // the dish, still on its boom
  const d0 = f([-0.05, 0.48, 0.0]), d1 = f([-0.12, 0.66, -0.04]), d2 = f([-0.145, 0.725, -0.055]);
  k.bar(d0, d1, 0.012, METAL);
  tube(k, d1, d2, 0.02, 0.17, hex(0xd9dcdc), 8, DARK, WHITE);
  k.bar(d2, f([-0.17, 0.79, -0.07]), 0.008, DARK);
  // one solar wing sticking up, bent at the hinge; the other lying flat on the rim
  const s0 = f([0.18, 0.26, 0]), s1 = f([0.3, 0.3, 0]);
  k.bar(s0, s1, 0.012, METAL);
  const fp = frame(s1, 0.5, 1.15, 0.12);
  fbox(k, fp, 0.2, 0, 0, 0.38, 0.015, 0.22, SOLAR, scale(SOLAR, 1.25));
  const fp2 = frame(fp([0.39, 0, 0]), 0.75, 0.7, 0.3);
  fbox(k, fp2, 0.17, 0, 0, 0.34, 0.015, 0.22, SOLAR, scale(SOLAR, 1.25));
  const fl = frame([-0.5, 0.16, 0.3], 2.2, 0.06, -0.1);
  fbox(k, fl, 0, 0, 0, 0.62, 0.015, 0.22, scale(SOLAR, 0.8), scale(SOLAR, 1.25));
  for (const dx of [-0.155, 0, 0.155]) fbox(k, fl, dx, 0.012, 0, 0.012, 0.006, 0.22, METAL);
  // the survey's marker flags
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.2, x = Math.cos(a) * 0.9, z = Math.sin(a) * 0.9;
    k.box(x, 0, z, 0.014, 0.24, 0.014, WHITE);
    k.box(x + 0.04, 0.17, z, 0.08, 0.06, 0.012, i % 2 ? hex(0xf07a28) : hex(0xf2c230));
  }
};

// ---- cape light (2 × 2) ------------------------------------------------------------------------------

/** A remote lighthouse station: a banded white tower, its lantern turning, the keeper's cottage against its foot. */
const capeLight: Draw = (k) => {
  const tx = -0.38, tz = -0.3, H = 2.35, R0 = 0.33, R1 = 0.19;
  const rad = (y: number) => R0 + ((R1 - R0) * y) / H;
  k.cyl(tx, 0, tz, R0 + 0.05, 0.06, STONE, 10);
  const cuts = [0.06, 0.6, 0.98, 1.5, 1.88, H];
  for (let i = 0; i + 1 < cuts.length; i++) k.band(tx, tz, cuts[i], rad(cuts[i]), cuts[i + 1], rad(cuts[i + 1]), 10, i % 2 ? RED : WHITE);
  k.box(tx, 0.06, tz + R0 - 0.02, 0.13, 0.26, 0.04, DARK);
  for (const [y, fz] of [[0.75, 1], [1.3, 1], [1.62, -1]] as const) k.box(tx, y, tz + fz * (rad(y) - 0.012), 0.07, 0.12, 0.03, DARK);
  // the gallery and its rail
  k.cyl(tx, H, tz, 0.3, 0.04, DARK, 10);
  k.hoop(tx, H + 0.15, tz, 0.285, 0.008, DARK, 10, 'xz');
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    k.box(tx + Math.cos(a) * 0.285, H + 0.04, tz + Math.sin(a) * 0.285, 0.014, 0.11, 0.014, DARK);
  }
  // the lantern room: glass all round, lit from dusk to dawn, under a dark cap
  const ly = H + 0.04;
  k.cyl(tx, ly, tz, 0.16, 0.06, WHITE, 8);
  k.glowBox(tx, ly + 0.06, tz, 0.24, 0.24, 0.24, GLASS_LIGHT, ALL_NIGHT, hex(0xfff2c0));
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) k.box(tx + sx * 0.12, ly + 0.06, tz + sz * 0.12, 0.025, 0.24, 0.025, DARK);
  k.cyl(tx, ly + 0.3, tz, 0.19, 0.03, DARK, 8);
  k.cone(tx, ly + 0.33, tz, 0.18, 0.16, hex(0x4a3a36), 8);
  k.box(tx, ly + 0.49, tz, 0.03, 0.08, 0.03, DARK);
  // (its beams sweep round over the sea after dark: render/lighthouseBeams.ts)
  // the keeper's cottage, against the foot of the tower
  const cx = 0.3, cz = -0.32;
  k.box(cx, 0, cz, 0.9, 0.36, 0.56, WHITE);
  k.gable(cx, 0.36, cz, 0.96, 0.24, 0.64, RED, WHITE);
  k.box(cx + 0.28, 0.4, cz - 0.1, 0.1, 0.3, 0.1, STONE, DARK);
  k.box(cx - 0.05, 0, cz + 0.285, 0.11, 0.24, 0.02, hex(0x3d5a78));
  k.pane(cx - 0.3, 0.13, cz + 0.28, 0.11, 0.12, 1, DARK, EVENING, WARM_GLOW);
  k.pane(cx + 0.24, 0.13, cz + 0.28, 0.11, 0.12, 1, DARK, EVENING, WARM_GLOW);
  k.pane(cx + 0.45, 0.13, cz, 0.11, 0.12, 0, DARK, EVENING, WARM_GLOW);
  // the yard wall, open at the front, and the flagpole
  const E = 0.88, WH = 0.13;
  k.box(0, 0, -E, E * 2 + 0.08, WH, 0.08, STONE, STONE_DARK);
  for (const s of [-1, 1]) {
    k.box(s * E, 0, 0, 0.08, WH, E * 2 - 0.08, STONE, STONE_DARK);
    k.box(s * 0.58, 0, E, 0.68, WH, 0.08, STONE, STONE_DARK);
    k.box(s * 0.24, 0, E, 0.1, WH + 0.06, 0.1, STONE, STONE_DARK);
  }
  k.box(0.6, 0, 0.48, 0.025, 0.95, 0.025, WHITE);
  k.box(0.7, 0.78, 0.48, 0.18, 0.12, 0.012, RED);
  k.box(-0.05, 0, 0.4, 0.16, 0.012, 0.9, hex(0xcfc4a6));
};

// ---- hermit's cabin (1 × 1) --------------------------------------------------------------------------

/** A hermit's shack: mismatched planks, a patched tin roof, a smoking stovepipe, a rocking chair on a scrap of porch. */
const hermitCabin: Draw = (k, _W, _D, _b, r) => {
  const x = -0.1, z = -0.14, w = 0.5, d = 0.4, h = 0.3, zf = z + d / 2;
  const planks = [hex(0x8a6a4a), hex(0x6f5a44), hex(0xa08a6a), hex(0x7d7468), hex(0x94764e)];
  k.box(x, 0, z, w, h, d, planks[0]);
  // the front and the side boarded in whatever came to hand
  for (let i = 0; i < 6; i++) {
    if (i === 2) continue;
    k.box(x - w / 2 + 0.042 + i * 0.0832, 0, zf + 0.004, 0.075, h - 0.01 - r() * 0.03, 0.014, planks[(i * 3 + 1) % 5]);
  }
  for (let i = 0; i < 4; i++) k.box(x + w / 2 + 0.004, 0, z - d / 2 + 0.055 + i * 0.097, 0.014, h - 0.01 - 0.03 * (i % 2), 0.088, planks[(i * 2 + 2) % 5]);
  k.box(x - 0.042, 0, zf + 0.006, 0.085, 0.22, 0.02, GAP);
  k.pane(x + 0.15, 0.12, zf + 0.012, 0.09, 0.09, 1, hex(0x4a4238), ALL_NIGHT, WARM_GLOW);
  // the roof: tin, crooked, patched
  const fr = frame([x, h + 0.07, z + 0.02], 0.05, -0.05, 0.16);
  fbox(k, fr, 0, 0, 0, w + 0.12, 0.02, d + 0.2, TIN);
  fbox(k, fr, -0.14, 0.02, 0.1, 0.2, 0.012, 0.2, RUST);
  fbox(k, fr, 0.16, 0.02, -0.12, 0.16, 0.012, 0.22, hex(0x6f7a80));
  fbox(k, fr, 0.2, 0.02, 0.16, 0.12, 0.012, 0.12, hex(0xa9a08a));
  k.box(x, h - 0.05, z - d / 4, w - 0.02, 0.11, d / 2 - 0.02, planks[1]);
  // the stovepipe and its smoke
  const px = x - 0.13, pz = z - 0.08;
  tube(k, [px, h, pz], [px + 0.02, h + 0.3, pz], 0.025, 0.025, DARK, 6);
  k.cone(px + 0.02, h + 0.3, pz, 0.045, 0.035, DARK, 6);
  ball(k, px + 0.05, h + 0.4, pz, 0.045, SMOKE);
  ball(k, px + 0.12, h + 0.53, pz + 0.02, 0.06, SMOKE);
  ball(k, px + 0.22, h + 0.7, pz + 0.03, 0.075, scale(SMOKE, 1.04));
  // a scrap of porch and the rocking chair
  k.box(x, 0, zf + 0.12, w + 0.04, 0.025, 0.22, planks[3], planks[2]);
  k.box(x - w / 2 + 0.02, 0.025, zf + 0.2, 0.025, 0.24, 0.025, planks[1]);
  const fc = frame([x + 0.13, 0.025, zf + 0.13], -0.4, 0, 0.18);
  for (const s of [-1, 1]) fbox(k, fc, s * 0.04, 0, 0, 0.012, 0.015, 0.14, DARK_WOOD);
  fbox(k, fc, 0, 0.05, 0, 0.09, 0.015, 0.09, planks[4]);
  fbox(k, fc, 0, 0.05, -0.04, 0.09, 0.13, 0.015, planks[4]);
  for (const s of [-1, 1]) fbox(k, fc, s * 0.04, 0.015, 0.03, 0.012, 0.04, 0.012, DARK_WOOD);
  // the woodpile against the wall
  const wx = x + w / 2 + 0.11;
  for (const [i, j] of [[0, 0], [1, 0], [2, 0], [0.5, 1], [1.5, 1], [1, 2]] as const) {
    tube(k, [wx - 0.07 + i * 0.07, 0.035 + j * 0.06, z - 0.14], [wx - 0.07 + i * 0.07, 0.035 + j * 0.06, z + 0.1], 0.034, 0.034, TRUNK, 6, hex(0xc9a877));
  }
  k.box(wx + 0.02, 0, z + 0.26, 0.09, 0.07, 0.09, TRUNK, hex(0xc9a877));
  k.bar([wx + 0.02, 0.07, z + 0.26], [wx + 0.08, 0.2, z + 0.24], 0.008, DARK_WOOD);
  // an oil drum and a kettle
  k.cyl(-0.37, 0, 0.3, 0.06, 0.15, RUST, 8, RUST_DARK);
  k.cyl(x - 0.17, 0.025, zf + 0.14, 0.03, 0.04, DARK, 6);
};

