/**
 * Race days at the circuits (docs/circuits.html). Every so often — and whenever the player comes up to
 * one after a while away — a circuit near the camera holds a meeting: the stands fill, spectators' cars
 * fill the infield, the field rolls out of the pits onto the grid, five lights, three laps, a trophy
 * over the winner, the cars park, and the crowd drifts home. The race is game/circuitRace.ts; this
 * keeps the schedule and draws what the meeting adds to the model: crowd, parked cars, race cars,
 * lights, trophy, and the strip at the foot of the screen.
 *
 * It also times the player round any circuit they drive onto (a Hot Lap), and gives them a grid slot
 * when a Race Day mission asks for one.
 */
import * as THREE from 'three';
import { MARKS } from '../../shared/marks';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { N, heightAt, type World, type Building } from '../world/tiles';
import {
  circuitsOf, frameOf, planOf, toIsland, toModel, lapAt, zoneAt, seatsOf, raceName, liftAt, bankLift,
  type CircuitPlan,
} from '../world/circuits';
import { hashString, mulberry32 } from '../world/rng';
import { press } from './press/desk';
import { buildingAt } from './press/hooks';
import { CarState } from './car';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { LIVERY_NAMES, LIVERIES, MeetSim, pickModel, Racer, LAPS, type PlayerEntrant } from './circuitRace';
import type { LandDef, VehicleDef, VehicleState } from './vehicles';
import { ALL_VEHICLES, LAND_SCALE, VEHICLE_SCALE } from './vehicles';
import { Floodlights } from '../render/floodlights';
import { FLOOD_HEAD, floodMastsOf } from '../render/buildings/circuits';

interface CircuitHost {
  scene: THREE.Scene;
  worlds(): World[];
  focus(): { x: number; z: number };
  player(): { w: World; state: VehicleState; def: VehicleDef } | null;
  hours(): number;
  /** `group`: the circuit, so its notifications stack together in the log. */
  say(title: string, body: string, group?: string): void;
  beep(final: boolean): void;
  cheer(): void;
  /** A Race Day mission is waiting on this circuit: the player takes a grid slot at its next meeting. */
  entered(key: string): boolean;
  /** A clean lap of this circuit, in seconds. */
  lap(key: string, secs: number): void;
  /** The player's race here is over: where they finished (0: never started), of how many. */
  result(key: string, place: number, of: number): void;
  /** A flypast over (x, z) in `secs` seconds (game/skyTraffic.ts): jets or helicopters in formation as the race begins. */
  flyover?(x: number, z: number, secs: number, seed: number, venue: string): string;
}

/** The share of meetings that open with a flypast (the user, 2 Nov 2026). */
const FLYPAST_SHARE = 0.33;

/** One meeting a game day at each circuit, at an hour of its own; and none start in the small hours. */
const PERIOD = 24;
/** Game hours from the end of one meeting at a circuit to the start of the next, however it comes about (a Race Day aside). */
const GAP = 24;
/** Real seconds the crowd takes to arrive, and to leave. */
const ARRIVE = 24, LEAVE = 30;
/** Meetings run only while the camera is this near, in tiles; a venue is kept this near. */
const ACTIVE_R = 190, KEEP_R = 300;
/** Coming this near after a while away starts a meeting soon, so a visit usually sees a race. */
const VISIT_R = 110;
/** How long the trophy stands over the winner, seconds. */
const TROPHY_SECS = 7;

type Stage = 'arrive' | 'sim' | 'leave';

interface Meet {
  sim: MeetSim;
  stage: Stage;
  t: number;
  name: string;
  meshes: { r: Racer; m: VehicleMesh }[];
  winner: Racer | null;
  trophyT: number;
  entered: boolean;
  announced: boolean;
  /** The lap the player was last told they were on, racing: a card each new lap. */
  toldLap?: number;
}

interface Venue {
  key: string;
  w: World;
  b: Building;
  p: CircuitPlan;
  f: ReturnType<typeof frameOf>;
  name: string;
  root: THREE.Group;
  crowd: THREE.InstancedMesh;
  parked: THREE.InstancedMesh;
  roofs: THREE.InstancedMesh;
  lights: THREE.Mesh[];
  slotRing: THREE.Mesh;
  /** The track lit from the corner masts while a meeting runs after dark. */
  floods: Floodlights;
  fill: number;
  meet: Meet | null;
  lastSlot: number;
  /** Game hour the last meeting ended; the visit that starts one soon. */
  lastEnd: number;
  soonAt: number | null;
  wasFar: boolean;
  best: number | null;
}

/** The key a circuit is known by: its cell and its building's uid. */
const circuitKey = (w: World, b: Building): string => `${w.cx},${w.cz}#${b.uid}`;

const PERSON = new THREE.BoxGeometry(0.075, 0.13, 0.07);
/**
 * A spectator's car, drawn after the Tomato that every fleet starts with: the painted body and roof (tinted
 * per car), and the parts that keep their own colour (tyres, glass all round the cabin, bumpers, lamps).
 * Both stand on the ground at y = 0, the nose toward +z.
 */
function carPart(g: THREE.BufferGeometry, x: number, y: number, z: number, hex: number): THREE.BufferGeometry {
  const out = (g.index ? g.toNonIndexed() : g).translate(x, y, z);
  out.deleteAttribute('uv');
  const n = out.attributes.position.count, col = new THREE.Color(hex), a = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { a[i * 3] = col.r; a[i * 3 + 1] = col.g; a[i * 3 + 2] = col.b; }
  out.setAttribute('color', new THREE.BufferAttribute(a, 3));
  return out;
}
const CAR_BODY = mergeGeometries([
  carPart(new THREE.BoxGeometry(0.46, 0.17, 0.78), 0, 0.155, 0, 0xffffff),
  carPart(new THREE.BoxGeometry(0.4, 0.14, 0.4), 0, 0.31, -0.06, 0xffffff),
])!;
const CAR_ROOF = mergeGeometries([
  ...[-1, 1].flatMap((sx) => [-1, 1].map((sz) => carPart(new THREE.BoxGeometry(0.06, 0.16, 0.16), sx * 0.235, 0.08, sz * 0.25, 0x26282c))),
  carPart(new THREE.BoxGeometry(0.36, 0.1, 0.02), 0, 0.31, 0.145, 0x9cc6d9),
  carPart(new THREE.BoxGeometry(0.36, 0.09, 0.02), 0, 0.31, -0.265, 0x9cc6d9),
  ...[-1, 1].map((sx) => carPart(new THREE.BoxGeometry(0.02, 0.09, 0.32), sx * 0.205, 0.31, -0.06, 0x9cc6d9)),
  carPart(new THREE.BoxGeometry(0.48, 0.05, 0.03), 0, 0.09, 0.4, 0x3a3f45),
  carPart(new THREE.BoxGeometry(0.48, 0.05, 0.03), 0, 0.09, -0.4, 0x3a3f45),
  ...[-1, 1].map((sx) => carPart(new THREE.BoxGeometry(0.1, 0.05, 0.02), sx * 0.15, 0.18, 0.395, 0xfff2b0)),
  ...[-1, 1].map((sx) => carPart(new THREE.BoxGeometry(0.1, 0.04, 0.02), sx * 0.15, 0.18, -0.395, 0xb02020)),
])!;
const SHIRTS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0x3a3f45, 0xd98fb0];
const PAINT = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0xf4f2ec, 0x3a3f45, 0x3f9b4a, 0xb9bdc2, 0x7fb7e6];

export class Circuits {
  private venues = new Map<string, Venue>();
  /** When each circuit's last meeting ended, kept while its venue comes and goes with its cell, so the GAP holds. */
  private ended = new Map<string, number>();
  private count = document.createElement('div');
  private lastCount = '';
  private lap: { key: string; lastS: number; prog: number; t: number; valid: boolean; running: boolean } | null = null;
  private trophy: THREE.Group;
  /** Controls held still while the lights are on for a player on the grid. */
  held = false;

  constructor(private host: CircuitHost) {
    this.count.className = 'race-count';
    this.count.hidden = true;
    document.body.append(this.count);
    this.trophy = makeTrophy();
    this.trophy.visible = false;
    host.scene.add(this.trophy);
  }

  /** One frame; dt is 0 while a menu is open. */
  update(dt: number): void {
    const focus = this.host.focus();
    this.sync(focus);
    const pl = this.host.player();
    this.held = false;
    // nothing is written along the bottom of the screen: what a meeting has to say comes as cards
    for (const v of this.venues.values()) {
      const d = Math.hypot(v.w.ox + v.f.ox - focus.x, v.w.oz + v.f.oz - focus.z);
      this.schedule(v, d, dt);
      v.floods.update(dt, !!v.meet);
      if (v.meet) this.runMeet(v, v.meet, dt, pl, d);
      this.dress(v, dt);
    }
    this.lapTimer(dt, pl);
    this.poseTrophy(dt);
  }

  // ---- venues ---------------------------------------------------------------------------------

  /** Keep a venue for every circuit near the camera, and let go of the rest. */
  private sync(focus: { x: number; z: number }): void {
    const seen = new Set<string>();
    for (const w of this.host.worlds()) {
      for (const b of circuitsOf(w)) {
        const key = circuitKey(w, b);
        const f = frameOf(b);
        if (Math.hypot(w.ox + f.ox - focus.x, w.oz + f.oz - focus.z) > KEEP_R) continue;
        seen.add(key);
        if (!this.venues.has(key)) this.venues.set(key, this.makeVenue(key, w, b));
      }
    }
    for (const [key, v] of this.venues) if (!seen.has(key)) { this.endMeet(v); this.disposeVenue(v); this.venues.delete(key); }
  }

  private makeVenue(key: string, w: World, b: Building): Venue {
    const p = planOf(b), f = frameOf(b);
    const g = w.works.find((q) => q.buildings.includes(b));
    const root = new THREE.Group();
    root.position.set(w.ox, 0, w.oz);
    this.host.scene.add(root);
    // the crowd: one little figure a seat, shown as many as have come
    const seats = seatsOf(p);
    const total = seats.length / 3;
    const crowd = new THREE.InstancedMesh(PERSON, new THREE.MeshStandardMaterial({ roughness: 0.9 }), total);
    const m = new THREE.Matrix4(), c = new THREE.Color();
    const r = mulberry32(hashString(key));
    for (let i = 0; i < total; i++) {
      const q = toIsland(f, seats[i * 3], seats[i * 3 + 2]);
      m.makeTranslation(q.x, f.oy + seats[i * 3 + 1] + 0.065, q.z);
      crowd.setMatrixAt(i, m);
      crowd.setColorAt(i, c.setHex(SHIRTS[Math.floor(r() * SHIRTS.length)]));
    }
    crowd.count = 0;
    crowd.frustumCulled = false;
    root.add(crowd);
    // the spectators' cars on the infield grass, at the size of the cars on the road: each of the plan's
    // spaces (sized for the model before it was scaled) has room for two rows of three, nose to nose, but
    // only about a third of those bays are ever used: a gappy lot reads fine and keeps the triangles down
    const SC = LAND_SCALE * VEHICLE_SCALE;
    const subs: { x: number; z: number; front: boolean }[] = [];
    for (const s of p.parking) for (const dz of [-0.13, 0.13]) for (const dx of [-0.205, 0, 0.205]) if (r() < 0.35) subs.push({ x: s.x + dx, z: s.z + dz, front: dz > 0 });
    const spots = subs.length;
    const parked = new THREE.InstancedMesh(CAR_BODY, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.55, flatShading: true }), spots);
    const roofs = new THREE.InstancedMesh(CAR_ROOF, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.45, flatShading: true }), spots);
    const order = subs.map((_, i) => i).sort(() => r() - 0.5);
    const scl = new THREE.Vector3(SC, SC, SC);
    order.forEach((k, i) => {
      const s = subs[k], q = toIsland(f, s.x, s.z);
      // nosed in toward the other row, and the odd one backed in
      const yaw = f.yaw + ((s.front ? Math.PI : 0) + (r() < 0.15 ? Math.PI : 0));
      m.makeRotationY(yaw).scale(scl).setPosition(q.x, f.oy, q.z);
      parked.setMatrixAt(i, m);
      roofs.setMatrixAt(i, m);
      parked.setColorAt(i, c.setHex(PAINT[Math.floor(r() * PAINT.length)]));
    });
    parked.count = roofs.count = 0;
    parked.frustumCulled = roofs.frustumCulled = false;
    root.add(parked, roofs);
    // the five red lights on the gantry, facing the grid
    const [ga, gb] = p.gantry;
    const lights: THREE.Mesh[] = [];
    const lightMat = new THREE.MeshBasicMaterial({ color: 0xff2a1a });
    const mid = { x: (ga.x + gb.x) / 2, z: (ga.z + gb.z) / 2 };
    const ax = gb.x - ga.x, az = gb.z - ga.z, al = Math.hypot(ax, az) || 1;
    const back = { x: -p.tx[0] * 0.08, z: -p.tz[0] * 0.08 };
    for (let i = 0; i < 5; i++) {
      const o = (i - 2) * 0.26;
      const q = toIsland(f, mid.x + (ax / al) * o + back.x, mid.z + (az / al) * o + back.z);
      const l = new THREE.Mesh(new THREE.SphereGeometry(0.075, 10, 8), lightMat);
      l.position.set(q.x, f.oy + 1.14, q.z);
      l.visible = false;
      root.add(l);
      lights.push(l);
    }
    // the ring on the player's grid slot, when a Race Day has given them one
    const slotRing = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.06, 6, 36), new THREE.MeshBasicMaterial({ color: 0xf5cf3a, transparent: true, opacity: 0.9 }));
    slotRing.rotation.x = Math.PI / 2;
    slotRing.visible = false;
    root.add(slotRing);
    // the floodlights: a pool over the lot and a beam from each corner mast, on for a meeting after dark
    // a band along the racing surface itself (brightest on it, gone a little past its edges, up the banking),
    // and only a faint wash over the rest of the lot
    // (falling off toward the edges, so the surface keeps some shape rather than one flat white sheet)
    const across: [number, number][] = [[-1.6, 0], [-1, 0.5], [0, 1], [1, 0.5], [1.6, 0]];
    const ribbon = [];
    for (let i = 0; i < p.n; i += 2) {
      ribbon.push(across.map(([f, a]) => {
        const u = f * p.half;
        return { x: p.px[i] + p.tz[i] * u, y: bankLift(p, p.bank[i], Math.max(-p.half, Math.min(p.half, u))) + 0.06, z: p.pz[i] - p.tx[i] * u, a };
      }));
    }
    const floods = new Floodlights({
      // each mast aimed at the stretch of track nearest it, not across the lot
      masts: floodMastsOf(p).map((m) => {
        let best = 0, bd = Infinity;
        for (let i = 0; i < p.n; i++) { const d = Math.hypot(p.px[i] - m.x, p.pz[i] - m.z); if (d < bd) { bd = d; best = i; } }
        return { x: m.x, y: FLOOD_HEAD, z: m.z, at: { x: p.px[best], y: bankLift(p, p.bank[best], 0), z: p.pz[best] } };
      }),
      pool: { x: 0, z: 0, w: p.W - 1, d: p.D - 1, y: 0, dim: 0.15 },
      ribbon,
    });
    floods.group.position.set(f.ox, f.oy, f.oz);
    floods.group.rotation.y = f.yaw;
    root.add(floods.group);
    const off = hashString(key) % PERIOD;
    return {
      key, w, b, p, f, name: g?.name ?? 'The circuit', root, crowd, parked, roofs, lights, slotRing, floods,
      fill: 0, meet: null, lastSlot: Math.floor((this.host.hours() + off) / PERIOD), lastEnd: this.ended.get(key) ?? -99, soonAt: null, wasFar: true, best: null,
    };
  }

  private disposeVenue(v: Venue): void {
    this.host.scene.remove(v.root);
    v.crowd.dispose();
    v.parked.dispose();
    v.roofs.dispose();
    for (const l of v.lights) l.geometry.dispose();
    v.slotRing.geometry.dispose();
    v.floods.dispose();
  }

  // ---- the schedule ---------------------------------------------------------------------------

  private schedule(v: Venue, d: number, dt: number): void {
    const hours = this.host.hours();
    const off = hashString(v.key) % PERIOD;
    const slot = Math.floor((hours + off) / PERIOD);
    const hour = ((hours % 24) + 24) % 24;
    const wants = this.host.entered(v.key);
    // too far to watch: nothing runs, and a meeting under way is called off
    if (d > ACTIVE_R + 30 && v.meet) this.endMeet(v);
    if (d > ACTIVE_R) { v.wasFar = true; v.lastSlot = slot; return; }
    if (v.meet) return;
    // back after a while away: a meeting soon
    if (v.wasFar && d < VISIT_R) {
      v.wasFar = false;
      if (hours - v.lastEnd >= GAP) v.soonAt = hours + 0.4;
    }
    const rested = hours - v.lastEnd >= GAP;
    const due = (rested && ((slot !== v.lastSlot && hour >= 9 && hour < 23) || (v.soonAt !== null && hours >= v.soonAt))) || wants;
    if (dt > 0 && due) {
      v.lastSlot = slot;
      v.soonAt = null;
      this.startMeet(v, wants);
    }
  }

  /** Open the gates: the crowd starts coming, the cars are in the pits. */
  startMeet(v: Venue, entered = false): void {
    if (v.meet) return;
    const seed = hashString(`${v.key}|${Math.floor(this.host.hours())}`);
    const r = mulberry32(seed);
    const pl = this.host.player();
    // a Race Day is a one-make race in the player's own model
    const model = entered && pl && pl.def.kind === 'land' && ALL_VEHICLES.some((q) => q.id === pl.def.id) ? pl.def.id : pickModel(v.p, r);
    const cars = entered ? 5 : 4 + Math.floor(r() * 3);
    const sim = new MeetSim(v.w, v.b, model, cars, seed, entered, {
      light: (n) => { if (this.near(v, 90)) this.host.beep(false); void n; },
      go: () => {
        if (this.near(v, 90)) { this.host.beep(true); this.host.say(v.meet?.name ?? 'The race', 'Lights out: three laps', v.name); }
      },
      finish: (who, place, secs) => this.finished(v, who, place, secs),
    });
    const meshes = sim.racers.map((q) => {
      const m = buildVehicleMesh(q.def);
      v.root.add(m.holder);
      return { r: q, m };
    });
    v.meet = { sim, stage: 'arrive', t: entered ? ARRIVE * 0.6 : 0, name: raceName(v.b, v.w, seed), meshes, winner: null, trophyT: 0, entered, announced: false };
    // now and then a flypast, timed to come over as the grid forms and the lights come on: the crowd's arrival, then
    // the slowest car's out lap (its release, its path at the out lap's pace, a little lost in the bends), then the lights
    if (this.host.flyover && mulberry32(seed ^ 0x5a17)() < FLYPAST_SHARE) {
      const out = Math.max(...sim.racers.map((q) => q.release + q.path.length / Math.max(0.5, q.def.topSpeed * 0.62 * 0.8)));
      const secs = ARRIVE - v.meet.t + Math.min(110, out) + 3;
      this.host.flyover(v.w.ox + v.b.x + v.b.w / 2, v.w.oz + v.b.z + v.b.d / 2, secs, seed, v.name);
    }
  }

  private endMeet(v: Venue): void {
    const m = v.meet;
    if (!m) return;
    for (const q of m.meshes) { v.root.remove(q.m.holder); disposeVehicleMesh(q.m); }
    if (m.entered && m.sim.player && m.sim.player.finished === null) this.host.result(v.key, 0, m.sim.racers.length + 1);
    v.meet = null;
    v.lastEnd = this.host.hours();
    this.ended.set(v.key, v.lastEnd);
    for (const l of v.lights) l.visible = false;
    v.slotRing.visible = false;
    if (this.trophyFor === v) { this.trophy.visible = false; this.trophyFor = null; }
  }

  private near(v: Venue, r: number): boolean {
    const pl = this.host.player();
    if (!pl) return false;
    return Math.hypot(pl.w.ox + pl.state.x - (v.w.ox + v.f.ox), pl.w.oz + pl.state.z - (v.w.oz + v.f.oz)) < r;
  }

  // ---- the meeting ----------------------------------------------------------------------------

  private runMeet(v: Venue, m: Meet, dt: number, pl: ReturnType<CircuitHost['player']>, d: number): void {
    m.t += dt;
    const me = pl && pl.w === v.w && pl.def.kind === 'land' && pl.state instanceof CarState ? { st: pl.state, def: pl.def as LandDef } : null;
    if (m.stage === 'arrive') {
      if (!m.announced && this.near(v, 150)) {
        m.announced = true;
        this.host.say(v.name, m.entered ? `${m.name}: your grid slot is waiting · the ring on the grid` : `Race day: ${m.name} · the stands are filling`, v.name);
      }
      for (const q of m.sim.racers) q.hold(dt);
      if (m.t >= ARRIVE) { m.stage = 'sim'; m.t = 0; }
    } else if (m.stage === 'sim') {
      m.sim.step(dt, me);
      if (m.sim.noShow && m.entered) { m.entered = false; this.host.result(v.key, 0, m.sim.racers.length + 1); this.host.say(m.name, 'Missed the start: the race went without you', v.name); }
      if (m.sim.phase === 'done') { m.stage = 'leave'; m.t = 0; }
    } else if (m.t >= LEAVE) {
      this.endMeet(v);
      return;
    }
    // the cars
    for (const q of m.meshes) { q.m.holder.visible = m.stage !== 'leave' || m.t < LEAVE * 0.7; poseVehicleMesh(q.m, q.r.st, q.r.def, v.w); }
    // the lights: on one by one on the grid, out together at the go
    const lit = m.stage === 'sim' && m.sim.phase === 'grid' ? m.sim.lit : 0;
    v.lights.forEach((l, i) => { l.visible = i < lit; });
    // the player's slot
    const entrant = m.sim.player;
    const onGrid = !!entrant && m.entered && (m.stage === 'arrive' || m.sim.phase === 'out' || (m.sim.phase === 'grid' && m.sim.lightsAt === null));
    v.slotRing.visible = onGrid;
    if (onGrid && entrant) {
      const g = v.p.grid[entrant.slot], q = toIsland(v.f, g.x, g.z);
      v.slotRing.position.set(q.x, heightAt(v.w, q.x, q.z) + liftAt(v.p, g.x, g.z) + 0.05, q.z);
      const k = 1 + Math.sin(performance.now() / 180) * 0.08;
      v.slotRing.scale.set(k, k, k);
    }
    this.held = this.held || (!!entrant && m.entered && m.stage === 'sim' && m.sim.phase === 'grid' && m.sim.lightsAt !== null);
    this.countdown(m, entrant, onGrid);
    // racing: a card as each new lap starts, with where the player is in the field
    if (entrant && m.entered && m.stage === 'sim' && m.sim.phase === 'race') {
      const st = m.sim.standings();
      if (st.lap > 1 && st.lap !== m.toldLap) {
        m.toldLap = st.lap;
        this.host.say(`🏁 ${st.lap === LAPS ? 'Last lap' : `Lap ${st.lap}/${LAPS}`}`, `${m.name} · P${st.order.indexOf(entrant) + 1} of ${st.order.length}`, v.name);
      }
    }
    void d;
  }

  /** The big lights over the screen for a player on the grid; GO as they go out. */
  private countdown(m: Meet, entrant: PlayerEntrant | null, onGrid: boolean): void {
    let txt = '';
    if (entrant && m.entered && m.stage === 'sim') {
      if (m.sim.phase === 'grid' && m.sim.lightsAt !== null) txt = '●'.repeat(m.sim.lit) + '○'.repeat(5 - m.sim.lit);
      else if (m.sim.phase === 'race' && m.sim.raceT < 1) txt = 'GO';
    }
    void onGrid;
    this.count.hidden = !txt;
    if (txt && txt !== this.lastCount) {
      this.count.textContent = txt;
      this.count.style.fontSize = txt === 'GO' ? '' : '64px';
      this.count.style.color = txt === 'GO' ? '' : '#ff3b30';
      this.count.classList.remove('pop'); void this.count.offsetWidth; this.count.classList.add('pop');
    }
    this.lastCount = txt;
  }

  private trophyFor: Venue | null = null;

  private finished(v: Venue, who: Racer | PlayerEntrant, place: number, secs: number): void {
    const m = v.meet;
    if (!m) return;
    if (place === 1) {
      m.winner = who instanceof Racer ? who : null;
      m.trophyT = TROPHY_SECS;
      this.trophyFor = v;
      if (this.near(v, 110)) this.host.cheer();
      if (this.near(v, 110) && !(m.entered && !(who instanceof Racer))) {
        const name = who instanceof Racer ? `${LIVERY_NAMES[LIVERIES.indexOf(who.def.color)] ?? 'A'} ${modelName(who.def)}` : 'You';
        this.host.say(`🏆 ${m.name}`, `${name} wins${secs > 0 ? ` in ${secs.toFixed(1)} s` : ''}`, v.name);
        // the paper (docs/newspaper.html): a race the player watched, won by somebody else
        if (who instanceof Racer) press.write({ k: 'raceResult', v: 'world', at: buildingAt(v.w, v.b), w: 2, f: { circuit: m.name, winner: name, ...(secs > 0 ? { secs: Math.round(secs * 10) / 10 } : {}) }, pic: { kind: 'trophy' } });
      }
    }
    if (!(who instanceof Racer) && m.entered) {
      const of = m.sim.racers.length + 1;
      this.host.result(v.key, secs < 0 ? of : place, of);
      m.entered = false;
      if (place === 1) { m.winner = null; this.host.cheer(); }
      this.host.say(m.name, secs < 0 ? 'Out of time: did not finish' : place === 1 ? `You win! ${secs.toFixed(1)} s` : `You finished P${place} of ${of}`, v.name);
      if (secs >= 0) press.write({
        k: 'raceResult', who: 'you', v: place === 1 ? 'won' : 'placed', at: buildingAt(v.w, v.b), w: place === 1 ? 5 : 3,
        f: { circuit: m.name, place, of, ...(place === 1 && secs > 0 ? { secs: Math.round(secs * 10) / 10 } : {}) }, ...(place === 1 ? { pic: { kind: 'trophy' } } : {}),
      });
    }
  }

  /** The trophy over the winner: a pop up, a slow spin and a bob, then gone. */
  private poseTrophy(dt: number): void {
    const v = this.trophyFor, m = v?.meet;
    if (!v || !m || m.trophyT <= 0) { this.trophy.visible = false; return; }
    m.trophyT -= dt;
    let x: number, y: number, z: number;
    if (m.winner) {
      const s = m.winner.st;
      x = v.w.ox + s.x; z = v.w.oz + s.z; y = s.y + 1.3;
    } else {
      const pl = this.host.player();
      if (!pl) { this.trophy.visible = false; return; }
      x = pl.w.ox + pl.state.x; z = pl.w.oz + pl.state.z; y = pl.state.y + 1.1;
    }
    const age = TROPHY_SECS - m.trophyT;
    const pop = Math.min(1, age / 0.35) * Math.min(1, m.trophyT / 0.5);
    this.trophy.visible = pop > 0.01;
    this.trophy.position.set(x, y + Math.sin(age * 3) * 0.08, z);
    this.trophy.rotation.y += dt * 1.8;
    this.trophy.scale.setScalar(pop * 1.6);
  }

  // ---- the crowd, the car park ---------------------------------------------------------------

  private dress(v: Venue, dt: number): void {
    const m = v.meet;
    const want = !m ? 0 : m.stage === 'arrive' ? Math.min(1, m.t / ARRIVE) : m.stage === 'leave' ? Math.max(0, 1 - m.t / (LEAVE * 0.85)) : 1;
    v.fill += Math.max(-dt * 0.5, Math.min(dt * 0.5, want - v.fill));
    if (dt === 0) v.fill = v.fill || 0;
    const people = Math.floor(v.fill * v.crowd.instanceMatrix.count * 0.94);
    if (v.crowd.count !== people) v.crowd.count = people;
    // the car park fills a little ahead of the stands and empties a little behind
    const cars = Math.floor(Math.min(1, v.fill * 1.25) * v.parked.instanceMatrix.count * 0.85);
    if (v.parked.count !== cars) v.parked.count = v.roofs.count = cars;
  }

  // ---- the hot lap ----------------------------------------------------------------------------

  /** Times the player round a circuit whose track they're on; a lap counts only driven the right way, all the way round. */
  private lapTimer(dt: number, pl: ReturnType<CircuitHost['player']>): string {
    if (!pl || pl.def.kind !== 'land') { this.lap = null; return ''; }
    const gx = pl.w.ox + pl.state.x, gz = pl.w.oz + pl.state.z;
    let venue: Venue | null = null;
    for (const v of this.venues.values()) {
      const lx = gx - v.w.ox, lz = gz - v.w.oz;
      if (lx >= v.b.x && lz >= v.b.z && lx < v.b.x + v.b.w && lz < v.b.z + v.b.d) { venue = v; break; }
    }
    // racing on the grid is its own clock
    if (!venue || (venue.meet?.entered && venue.meet.stage === 'sim' && venue.meet.sim.phase !== 'out')) { this.lap = null; return ''; }
    const v = venue;
    const m = toModel(v.f, gx - v.w.ox, gz - v.w.oz);
    const at = lapAt(v.p, m.x, m.z), zone = zoneAt(v.p, m.x, m.z);
    const len = v.p.len;
    if (!this.lap || this.lap.key !== v.key) this.lap = { key: v.key, lastS: at?.s ?? 0, prog: 0, t: 0, valid: false, running: false };
    const L = this.lap;
    if (!at || zone === 0 && Math.abs(at.u) > v.p.half + 2.5) {
      // off the track altogether: the lap in hand doesn't count
      L.valid = false;
      L.running = false;
      return v.best !== null ? `<span>⏱ ${esc(v.name)}</span><span>Best ${fmt(v.best)}</span>` : '';
    }
    let ds = at.s - L.lastS;
    if (ds > len / 2) ds -= len;
    if (ds < -len / 2) ds += len;
    // over the line, going the right way
    const crossed = L.lastS > len - 4 && at.s < 4 && ds > 0;
    L.lastS = at.s;
    if (L.running) L.t += dt;
    if (Math.abs(ds) > 3 || ds < -0.4) L.valid = false;
    else L.prog += Math.max(0, ds);
    // driven on the track: more than a wheel past the kerb, either side, the infield and the pit lane included, and the
    // lap doesn't count (shared/marks.ts lapBand; the server checks a record's ghost to the same band)
    if (Math.abs(at.u) > v.p.half + MARKS.lapBand) L.valid = false;
    if (crossed) {
      if (L.running && L.valid && L.prog > len * 0.92) {
        const secs = L.t;
        const was = v.best;
        if (v.best === null || secs < v.best) v.best = secs;
        this.host.lap(v.key, secs);
        this.host.say(`⏱ ${fmt(secs)}`, was === null || secs < was ? `A new best at ${v.name}` : `Best here ${fmt(v.best!)}`);
      }
      L.running = true; L.valid = true; L.prog = 0; L.t = 0;
      this.lapsBegun++;
    }
    if (!L.running) return `<span>⏱ ${esc(v.name)}</span><span>Cross the line to start a lap</span>${v.best !== null ? `<span>Best ${fmt(v.best)}</span>` : ''}`;
    return `<span>⏱ ${esc(v.name)}</span><span class="clock">${fmt(L.t)}</span>${L.valid ? '' : '<span><b class="behind">cut · doesn’t count</b></span>'}${v.best !== null ? `<span>Best ${fmt(v.best)}</span>` : ''}`;
  }

  /** A circuit's lot, [x, z, w, d, facing] in island tiles: what the server checks a lap's ghost against (server/marks.ts). */
  lot(key: string): number[] | null {
    const v = this.venues.get(key);
    return v ? [v.b.x, v.b.z, v.b.w, v.b.d, v.b.facing] : null;
  }

  // ---- for the missions and the console ---------------------------------------------------------

  /** The circuits near the camera: key, name, design, where, and what's on. */
  list(): { key: string; name: string; design: string; x: number; z: number; on: string; best: number | null }[] {
    return [...this.venues.values()].map((v) => ({
      key: v.key, name: v.name, design: v.p.design, x: Math.round(v.w.ox + v.f.ox), z: Math.round(v.w.oz + v.f.oz),
      on: v.meet ? `${v.meet.name}: ${v.meet.stage === 'sim' ? v.meet.sim.phase : v.meet.stage}` : 'quiet', best: v.best,
    }));
  }

  /** Start a meeting now at the circuit nearest the camera. */
  go(): string {
    const f = this.host.focus();
    const v = [...this.venues.values()].sort((a, b) => Math.hypot(a.w.ox + a.f.ox - f.x, a.w.oz + a.f.oz - f.z) - Math.hypot(b.w.ox + b.f.ox - f.x, b.w.oz + b.f.oz - f.z))[0];
    if (!v) return 'no circuit near';
    if (v.meet) this.endMeet(v);
    this.startMeet(v);
    v.meet!.t = ARRIVE - 3;
    return `${v.name}: ${v.meet!.name}`;
  }

  /** Where a Race Day's player should head: their grid slot while there is one to take, else the gate. */
  target(key: string): { x: number; z: number; name: string } | null {
    const v = this.venues.get(key);
    if (!v) return null;
    const m = v.meet;
    if (m?.entered && m.sim.player) {
      const g = v.p.grid[m.sim.player.slot], q = toIsland(v.f, g.x, g.z);
      if (m.stage === 'arrive' || m.sim.phase === 'out' || m.sim.phase === 'grid') return { x: v.w.ox + q.x, z: v.w.oz + q.z, name: 'your grid slot' };
    }
    const q = toIsland(v.f, v.p.gateX, v.p.D / 2);
    return { x: v.w.ox + q.x, z: v.w.oz + q.z, name: v.name };
  }

  /** The line under a Race Day mission. */
  line(key: string): string | null {
    const v = this.venues.get(key), m = v?.meet;
    if (!v) return null;
    if (!m || !m.entered) return `Drive to ${v.name}`;
    if (m.stage === 'arrive' || m.sim.phase === 'out') return 'Stop on the yellow ring on the grid';
    if (m.sim.phase === 'grid') return m.sim.lightsAt === null ? 'Stop on the ring to start the lights' : 'Wait for the lights to go out';
    return `Race: ${LAPS} laps · finish in the top three`;
  }

  /**
   * The hot lap in hand (docs/marks.html: ghosts and lap records): the circuit, its name and island, the clock,
   * whether a lap is running and still clean, and how many laps have been started there, so a new one shows.
   */
  lapNow(): { key: string; name: string; w: World; t: number; running: boolean; valid: boolean; n: number } | null {
    const L = this.lap;
    const v = L ? this.venues.get(L.key) : null;
    return L && v ? { key: L.key, name: v.name, w: v.w, t: L.t, running: L.running, valid: L.valid, n: this.lapsBegun } : null;
  }
  private lapsBegun = 0;

  /** The best lap the player has set at a circuit this session. */
  bestAt(key: string): number | null { return this.venues.get(key)?.best ?? null; }

  clear(): void {
    for (const v of this.venues.values()) { this.endMeet(v); this.disposeVenue(v); }
    this.venues.clear();
    this.lap = null;
    this.count.hidden = true;
    this.trophy.visible = false;
    this.held = false;
  }
}

const esc = (s: string) => s.replace(/[<&]/g, (c) => (c === '<' ? '&lt;' : '&amp;'));
const fmt = (t: number) => `${Math.floor(t / 60)}:${(t % 60).toFixed(1).padStart(4, '0')}`;
const modelName = (d: VehicleDef) => d.name;

/** A little gold cup on a black plinth. */
function makeTrophy(): THREE.Group {
  const g = new THREE.Group();
  const gold = new THREE.MeshStandardMaterial({ color: 0xf2c14e, metalness: 0.7, roughness: 0.28, emissive: 0x5a3a00, emissiveIntensity: 0.6 });
  const pts = [[0, 0], [0.16, 0], [0.16, 0.05], [0.05, 0.08], [0.04, 0.22], [0.1, 0.27], [0.19, 0.36], [0.22, 0.56], [0.2, 0.58],
    // over the lip and down the inside to a floor, so the bowl is solid seen from above, not an open shell
    [0.185, 0.555], [0.165, 0.38], [0.08, 0.31], [0, 0.3]].map(([x, y]) => new THREE.Vector2(x, y));
  const cup = new THREE.Mesh(new THREE.LatheGeometry(pts, 18), gold);
  cup.position.y = 0.16;
  g.add(cup);
  for (const s of [-1, 1]) {
    const h = new THREE.Mesh(new THREE.TorusGeometry(0.09, 0.022, 6, 14, Math.PI * 1.2), gold);
    h.position.set(s * 0.22, 0.6, 0);
    h.rotation.z = s > 0 ? -Math.PI * 0.6 : Math.PI * 1.6;
    g.add(h);
  }
  const base = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.16, 0.34), new THREE.MeshStandardMaterial({ color: 0x2a2a2e, roughness: 0.5 }));
  base.position.y = 0.08;
  g.add(base);
  return g;
}

void N;
