/**
 * Railway rolling stock as pure data: every car (engines, tenders, passenger cars, tails and the 64
 * wagons of docs/trains.html), the six buyable sets (seven from 0.7.0, with the cog railway's), the CPU
 * speeds, and consist composition. No three.js here; src/render/trainMeshes.ts draws what this names.
 */
import { NEXT_WORLD } from '../world/nextWorld';

type Era = 'steam' | 'streamline' | 'modern';
export type CarRole = 'engine' | 'tender' | 'coach' | 'observation' | 'caboose' | 'powerCar' | 'wagon' | 'eot';
type WagonBody =
  | 'coveredHopper' | 'openHopper' | 'gondola' | 'bunkFlat' | 'centerbeam' | 'rackFlat' | 'tank' | 'reefer'
  | 'boxcar' | 'van' | 'stockCar' | 'openWagon' | 'flat' | 'wellCar' | 'autoRack' | 'crane' | 'coilCar';
export type Hold = 'people' | 'parcel' | 'freight' | 'bulk' | 'container';

export interface CarSpec {
  id: string; name: string; role: CarRole;
  era: Era | null;          // null = runs on any period's trains
  length: number;           // tiles, coupler face to coupler face (excluding the 0.08 coupling gap)
  body?: WagonBody;         // wagons only
  cargo?: string[];         // ids from cargoTypes.ts CARGO
  from?: string[];          // producer / consumer building kinds (the doc's "From / for" column)
  color: number; accent?: number;
  freight: boolean;         // engines: a freight engine
  /** Mesh sub-style within a body (e.g. 'ribbed', 'twin', 'circus'). */
  style?: string;
  /** Colour of the visible load (heaps, logs, lumber), where there is one. */
  load?: number;
  /** Drawn as `base` turned end for end (a rear power car, the second unit of a back-to-back pair). */
  base?: string;
  /** Not drawn into ordinary freights: maintenance and circus stock. */
  special?: boolean;
}

/** The gap between two cars' coupler faces, in tiles. */
export const COUPLING_GAP = 0.08;

const car = (s: Omit<CarSpec, 'freight'> & { freight?: boolean }): CarSpec => ({ freight: false, ...s });

