/**
 * How rare they are: the chance a CPU train put on the line is one of them, and how the three share that.
 * The Christmas train runs only in winter; the rave train mostly after dark; the stealth train any time.
 */
export const SPECIAL_RATE = { chance: 0.025, christmas: 1, rave: 0.25, raveNight: 1, stealth: 0.6 };

/** Which special, if any, this roll puts on the line, by the season and how dark it is. Pure: the gate runs it. */
export function specialFor(r: number, pick: number, season: string, night: number): SpecialKind | null {
  if (r >= SPECIAL_RATE.chance) return null;
  const w: [SpecialKind, number][] = [
    ['christmas', season === 'winter' ? SPECIAL_RATE.christmas : 0],
    ['rave', night > 0.4 ? SPECIAL_RATE.raveNight : SPECIAL_RATE.rave],
    ['stealth', SPECIAL_RATE.stealth],
  ];
  const total = w.reduce((s, [, v]) => s + v, 0);
  let x = pick * total;
  for (const [k, v] of w) if ((x -= v) < 0) return k;
  return null;
}

export const CARS: Record<string, CarSpec> = Object.fromEntries([...LOCO, ...WAGONS, ...SPECIAL_CARS].map((c) => [c.id, c]));

