// ---- consists ------------------------------------------------------------------------------

const irand = (rng: () => number, lo: number, hi: number): number => lo + Math.floor(rng() * (hi - lo + 1));

/** A CPU passenger consist for this era: engine(+tender), 2–5 coaches, observation, tail; modern is a fixed symmetrical set. */
export function passengerConsist(era: Era, rng: () => number): string[] {
  const n = irand(rng, 2, 5);
  if (era === 'modern') {
    // power car, first class, coaches with the bistro in the middle, power car at the back
    const coaches = Array.from({ length: Math.max(2, n) }, () => 'modernCoach');
    coaches.splice(Math.floor(coaches.length / 2), 0, 'bistroCar');
    return ['wedge', 'modernFirst', ...coaches, 'wedgeRear'];
  }
  const steam = era === 'steam';
  const out = steam ? ['american', 'americanTender'] : ['bulldog'];
  if (rng() < 0.4) out.push(steam ? 'steamBaggage' : 'streamBaggage');
  if (rng() < 0.25) out.push('mailCar');
  for (let i = 0; i < n; i++) out.push(steam ? 'steamCoach' : 'streamCoach');
  out.push(steam ? 'steamObservation' : 'domeCar', steam ? 'woodCaboose' : 'bayCaboose');
  return out;
}

/** Wooden, period-look stock that a steam freight favours on top of its own period bodies. */
const WOODEN = new Set(['peatWagon', 'pulpwoodRack', 'horseBox', 'powderVan', 'wineTank', 'stockCar', 'cattleCar', 'logCar', 'kegWagon', 'woolBaleWagon']);
const MODERN_FAVOURED = new Set<WagonBody>(['flat', 'wellCar', 'coveredHopper', 'boxcar', 'reefer', 'autoRack', 'centerbeam']);

function matches(w: CarSpec, producers: Set<string>): boolean {
  for (const f of w.from ?? []) if (producers.has(f)) return true;
  for (const c of w.cargo ?? []) if (producers.has(c)) return true;
  return false;
}

function weightOf(w: CarSpec, era: Era, producers: Set<string> | null): number {
  if (w.special) return 0;
  let wt = 1;
  if (w.era === era) wt *= 3;
  else if (w.era) wt *= 0.25;
  if (era === 'steam' && WOODEN.has(w.id)) wt *= 2;
  if (era === 'modern' && w.body && MODERN_FAVOURED.has(w.body)) wt *= 1.5;
  if (w.id === 'containerFlat' && era === 'modern') wt *= 2;
  if (producers && producers.size) wt *= matches(w, producers) ? 12 : 0.08;
  return wt;
}

function pickWeighted(rng: () => number, era: Era, producers: Set<string> | null): string {
  let total = 0;
  const ws = WAGONS.map((w) => { const x = weightOf(w, era, producers); total += x; return x; });
  let r = rng() * total;
  for (let i = 0; i < WAGONS.length; i++) { r -= ws[i]; if (r <= 0 && ws[i] > 0) return WAGONS[i].id; }
  return 'goodsBoxcar';
}

/** n wagons: weighted draws in short blocks of the same kind, with two wildcards from the whole table. */
function drawWagons(era: Era, n: number, rng: () => number, producers?: string[]): string[] {
  const set = producers && producers.length ? new Set(producers) : null;
  const out: string[] = [];
  while (out.length < n) {
    let id = pickWeighted(rng, era, set);
    if (id === out[out.length - 1]) id = pickWeighted(rng, era, set);   // blocks of one kind, but not two blocks running
    const block = rng() < 0.45 ? irand(rng, 2, 3) : 1;
    for (let i = 0; i < block && out.length < n; i++) out.push(id);
  }
  // two wildcards from the whole (non-special) table
  const pool = WAGONS.filter((w) => !w.special);
  for (let k = 0; k < Math.min(2, n); k++) out[Math.floor(rng() * n)] = pool[Math.floor(rng() * pool.length)].id;
  return out;
}

const FREIGHT_WAGONS: Record<Era, [number, number]> = { steam: [6, 12], streamline: [8, 14], modern: [10, 16] };

/** A CPU freight consist: engine(s)(+tender), n wagons, tail. */
export function freightConsist(era: Era, rng: () => number, producers?: string[]): string[] {
  const head = era === 'steam' ? ['consolidation', 'consolidationTender']
    : era === 'streamline' ? (rng() < 0.5 ? ['hoodUnit'] : ['hoodUnit', 'hoodUnitB'])
    : ['wideCab', 'wideCabB'];
  const tail = era === 'steam' ? 'woodCaboose' : era === 'streamline' ? 'bayCaboose' : 'eot';
  const [lo, hi] = FREIGHT_WAGONS[era];
  const n = irand(rng, lo, hi);
  let wagons: string[];
  if (rng() < 1 / 40) {
    wagons = Array.from({ length: n }, () => 'circusCar');
  } else {
    wagons = drawWagons(era, n, rng, producers);
    if (rng() < 1 / 20 && n >= 3) {
      const at = irand(rng, 0, n - 3);
      wagons.splice(at, 3, 'ballastHopper', 'ballastHopper', 'railCrane');
    }
  }
  return [...head, ...wagons, tail];
}

/** Fill the '*' slots of a buyable freight set the same way. */
export function fillSet(set: TrainSet, rng: () => number, producers?: string[]): string[] {
  const n = set.cars.filter((c) => c === '*').length;
  const wagons = drawWagons(set.era, n, rng, producers);
  let i = 0;
  return set.cars.map((c) => (c === '*' ? wagons[i++] : c));
}
